--   venue_duplicate_suspects     -> etkin: 214_misafir_hakki_kaynaktan.sql  (ayrica: 211_kart_aglari_kaynaktan.sql)
--   venue_guest_profile          -> etkin: 215_saglayici_veri_yollari.sql  (ayrica: 213_saglayici_kurumsal_katman.sql)
--   venue_inbound_wave           -> etkin: 292_zaman_dilimi_yerel_an.sql  (ayrica: 209_saglayici_modulu.sql)
--   venue_norm                   -> etkin: 113_dedupe_and_wording.sql  (ayrica: 103_consolidate_and_charter.sql)
--   venue_program_mix            -> etkin: 215_saglayici_veri_yollari.sql  (ayrica: 213_saglayici_kurumsal_katman.sql)
--   verification_state           -> etkin: 138_email_otp.sql  (ayrica: 136_otp_honesty.sql)
--   verify_otp                   -> etkin: 079_email_otp_contact_verification.sql  (ayrica: 009_phone_otp.sql, 026_doc_parity_core.sql, 062_fix_verify_otp.sql)
--   yarinki_lounge_hatirlat      -> etkin: 292_zaman_dilimi_yerel_an.sql  (ayrica: 266_eksik_bildirimler.sql)

-- ----------------------------------------------------------------------
-- compute_trust_badge   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.compute_trust_badge(score int)
returns text language sql stable set search_path = public as $fn$
  select case
    when score >= coalesce((select value from rule_thresholds where key='badge_trusted_plus'), 88) then 'trusted_plus'
    when score >= coalesce((select value from rule_thresholds where key='badge_trusted'),      72) then 'trusted'
    when score >= coalesce((select value from rule_thresholds where key='badge_verified'),     56) then 'verified'
    else 'basic' end;
$fn$;

-- Eşikler değiştiğinde eski rozetler yalan söylemesin: BO kaydettiğinde
-- rozetleri yeniden hesaplayan RPC.

-- ----------------------------------------------------------------------
-- handle_new_user   [etkin kaynak: 041_staff_accounts_excluded.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare g user_gender; n text; r user_role; v_staff boolean;
begin
  begin g := (new.raw_user_meta_data->>'gender')::user_gender; exception when others then g := null; end;
  begin r := coalesce((new.raw_user_meta_data->>'role')::user_role, 'guest'); exception when others then r := 'guest'; end;
  n := coalesce(nullif(trim(new.raw_user_meta_data->>'name'), ''), split_part(new.email, '@', 1));

  -- YENİ (041): BO daveti bu bayrakları zaten gönderiyor
  begin
    v_staff := coalesce((new.raw_user_meta_data->>'is_staff')::boolean, false)
            or coalesce((new.raw_user_meta_data->>'is_partner')::boolean, false);
  exception when others then v_staff := false;
  end;

  insert into public.users (id, email, role, gender, password_hash, is_staff)
  values (new.id, new.email, r, g, 'supabase-auth', v_staff) on conflict (id) do nothing;

  -- staff ise keşifte görünme
  insert into public.profiles (user_id, name, show_on_discovery)
  values (new.id, n, not v_staff) on conflict (user_id) do nothing;

  insert into public.verifications (user_id, email_verified, email_verified_at)
  values (new.id, true, now()) on conflict (user_id) do nothing;
  insert into public.trust_scores (user_id, score, components, badge)
  values (new.id, 10, '{"email":10}'::jsonb, 'New') on conflict (user_id) do nothing;

  -- BETA (033): açılış kredisi — ama ekip hesabına DEĞİL.
  -- Kendi hatasını yutar: kredi verilemezse KAYIT YİNE DE TAMAMLANIR.
  if not v_staff then
    begin
      perform grant_signup_credits(new.id);
    exception when others then
      null;
    end;
  end if;

  return new;
end $$;

-- ----------------------------------------------------------------------
-- create_request   [etkin kaynak: 140_rls_and_ratelimit.sql]
-- ⚠ Bu fonksiyon 7 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.create_request(
  p_avail_id uuid, p_type text default 'lounge'::text,
  p_intro text default null::text, p_idem text default null::text
) returns jsonb language plpgsql security definer set search_path = public as $$
begin
  -- Saatte 20 istek: gercek kullanici bir oturumda 2-3 istek atar;
  -- 20 hem bol hem otomatik spam'i durduran bir esik.
  if not public.rate_ok('create_request', 20, 1) then
    raise exception 'rate_limited_request';
  end if;
  return public.create_request_impl(p_avail_id, p_type, p_intro, p_idem);
end $$;

-- ----------------------------------------------------------------------
-- respond_request   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ⚠ Bu fonksiyon 5 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.respond_request(p_request_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid  uuid := auth.uid();
  v_req  requests%rowtype;
  v_av   availabilities%rowtype;
  v_bal  integer;
  v_chan uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);   -- 282/B1: yasakli/silinmis hesap yazamaz

  select * into v_req from requests where id = p_request_id for update;
  if not found then raise exception 'request_not_found'; end if;

  if p_action = 'accept' then
    if v_req.host_id <> v_uid then raise exception 'not_host'; end if;
    if v_req.status <> 'pending' then raise exception 'not_pending'; end if;

    select * into v_av from availabilities where id = v_req.avail_id for update;
    if not found then raise exception 'availability_not_found'; end if;
    -- 🔴 300/B1: süresi geçmiş ya da kaldırılmış ilana KABUL yok.
    -- Eskiden host buluşma saati geçtikten sonra da kabul edebiliyordu:
    -- misafirin kredisi tutuluyor, sohbet açılıyor, ama buluşma imkânsız.
    if not coalesce(v_av.active, true)
       or public.yerel_an(v_av.avail_date, v_av.time_to, v_av.airport_code) < now() then
      raise exception 'availability_expired';
    end if;
    if coalesce(v_av.filled,0) >= v_av.slots then raise exception 'fully_booked'; end if;

    update requests set status='accepted', responded_at=now() where id = v_req.id;

    insert into chat_channels (request_id) values (v_req.id)
      on conflict (request_id) do nothing;
    select id into v_chan from chat_channels where request_id = v_req.id;

    -- 077-3: misafirin tanıtım metni sohbetin ilk mesajı
    if v_chan is not null and coalesce(nullif(trim(v_req.intro_message),''),'') <> '' then
      insert into messages (channel_id, from_id, body, created_at)
      select v_chan, v_req.guest_id, trim(v_req.intro_message), now()
       where not exists (select 1 from messages m where m.channel_id = v_chan);
    end if;

    -- 080: OTURUM BURADA AÇILMAZ. Kabul, buluşma günlerce sonra olabileceği
    -- için "aktif oturum" değildir; iki taraf buluşunca start_session_request
    -- ile başlatılır.
    insert into notifications (user_id, category, title, body, ref_id, ref_type)
    values (v_req.guest_id, 'requests', 'İstek kabul edildi! 🎉',
            'Sohbet açıldı. Buluştuğunuzda iki taraf da "Oturumu Başlat"a basacak.',
            v_req.id, 'request');

    return jsonb_build_object('ok', true, 'channel_id', v_chan, 'session_id', null);

  elsif p_action in ('decline','cancel') then
    if p_action = 'decline' and v_req.host_id  <> v_uid then raise exception 'not_host'; end if;
    if p_action = 'cancel'  and v_req.guest_id <> v_uid then raise exception 'not_guest'; end if;
    if v_req.status not in ('pending','accepted') then raise exception 'not_open'; end if;
    -- 080: oturum başladıysa istek üzerinden iptal edilemez (cancel_session yolu)
    if exists (select 1 from sessions s where s.request_id = v_req.id and s.status in ('pending','active')
                 -- 🔴 300/B2: HİÇ BAŞLATILMAMIŞ boş 'pending' oturum engel değil.
                 -- 293'ten beri davet kabulü böyle bir satır açıyor; misafir
                 -- iptal edemiyor, süpürge de görmüyordu → kredi + slot kilitli.
                 and not (s.status = 'pending' and s.host_started_at is null
                          and s.guest_started_at is null)) then
      raise exception 'session_started';
    end if;

    update requests set status = case when p_action='decline' then 'declined' else 'cancelled' end::request_status,
           responded_at = now()
     where id = v_req.id;

    -- 300/B2: geride kalan boş oturumu da kapat (yetim kalmasın).
    update sessions set status = 'cancelled', completed_at = now(),
           cancelled_by = v_uid, cancel_reason = 'not_started'
     where request_id = v_req.id and status = 'pending'
       and host_started_at is null and guest_started_at is null;

    perform public.istek_kredisi_iade(v_req.id, 'request_refund');

    insert into notifications (user_id, category, title, body, ref_id, ref_type)
    values (case when p_action='decline' then v_req.guest_id else v_req.host_id end,
            'requests',
            case when p_action='decline' then 'İstek reddedildi' else 'İstek iptal edildi' end,
            'Kredi anında iade edildi.', v_req.id, 'request');
    return jsonb_build_object('ok', true);
  end if;

  raise exception 'unknown_action';
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B3 · confirm_session  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.confirm_session(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_s sessions%rowtype; v_r requests%rowtype;
  v_done boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);   -- 300/B3: yasaklı hesap oturum kapatamaz (diğer akış fonksiyonlarıyla aynı)
  select * into v_s from sessions where id = p_session_id for update;
  if not found then raise exception 'session_not_found'; end if;
  select * into v_r from requests where id = v_s.request_id;
  if v_uid not in (v_r.host_id, v_r.guest_id) then raise exception 'not_party'; end if;
  if v_s.status <> 'active' then raise exception 'not_active'; end if;

  if v_uid = v_r.host_id then
    update sessions set host_confirmed = true where id = p_session_id;
  else
    update sessions set guest_confirmed = true where id = p_session_id;
  end if;

  select host_confirmed and guest_confirmed into v_done from sessions where id = p_session_id;

  if v_done then
    update sessions set status = 'completed', completed_at = now() where id = p_session_id;
    update requests set status = 'completed' where id = v_s.request_id;

    -- 078: ÖDÜL BURADA (oturum bitti = hak edildi). Host 500 / misafir 200.
    -- Çift ödemeye karşı: aynı oturum için daha önce yazılmışsa atlanır.
    -- NOT: points_ledger'da balance_after KOLONU YOK (SQL 050'de tespit
    -- edilmişti; bakiye user_balances view'ından okunur). Buraya yazmaya
    -- kalkmak fonksiyonu çalışma anında patlatır — yazılmıyor.
    if not exists (select 1 from points_ledger
                    where ref_id = p_session_id and reason = 'session_reward') then
      insert into points_ledger (user_id, delta, reason, ref_id)
      values (v_r.host_id, 500, 'session_reward', p_session_id),
             (v_r.guest_id, 200, 'session_reward', p_session_id);
    end if;

    -- 067'deki ESCROW KAPANIŞ NOTU korunur (drift_check yakaladı):
    -- kredi host'a aktarılmaz (kredi = hak, para değil); misafirin kredisi
    -- harcanmış sayılır, deftere kapanış satırı düşülür.
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    select v_r.guest_id, 0, 'session_settled', p_session_id, coalesce(sum(delta),0)
      from credit_ledger where user_id = v_r.guest_id;

    -- Güven: oturum sayısı değişti → İKİ TARAF için kanonik hesap
    perform public.recompute_trust(v_r.host_id);
    perform public.recompute_trust(v_r.guest_id);

    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    select u, 'sessions', 'Oturum tamamlandı ✓',
           'Puanların hesabına eklendi. Karşı tarafı puanlamayı unutma.',
           'session', p_session_id
      from unnest(array[v_r.host_id, v_r.guest_id]) u;
  else
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (case when v_uid = v_r.host_id then v_r.guest_id else v_r.host_id end,
            'sessions', 'Oturum onayı bekleniyor',
            'Karşı taraf oturumu tamamladı olarak işaretledi.', 'session', p_session_id);
  end if;

  return jsonb_build_object('ok', true, 'completed', coalesce(v_done,false));
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B2 · expire_stale_sessions  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.expire_stale_sessions(p_kaynak text DEFAULT 'uygulama'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req int := 0; v_sess int := 0;
  v_son timestamptz;
  v_sonuc jsonb;
begin
  -- ── FREN (298) ────────────────────────────────────────────────────
  -- `for update` ile alıyoruz: iki istemci aynı anda çağırırsa ikincisi
  -- birincinin damgasını bekler ve "atlandi" döner. pg_cron ile uygulama
  -- tetiği AYNI FRENİ paylaşır — ikisi birden açık olsa bile gövde
  -- 5 dakikada bir koşar.
  select son_kosum into v_son from public.supurge_damgasi
   where ad = 'expire_stale_sessions' for update;

  if v_son is not null and v_son > now() - interval '5 minutes' then
    return jsonb_build_object('ok', true, 'durum', 'atlandi',
                              'kaynak', p_kaynak,
                              'sonraki', v_son + interval '5 minutes');
  end if;

  insert into public.supurge_damgasi (ad, son_kosum, kaynak)
  values ('expire_stale_sessions', now(), p_kaynak)
  on conflict (ad) do update set son_kosum = now(), kaynak = excluded.kaynak;

  -- ── GÖVDE ─────────────────────────────────────────────────────────
  --
  -- 🔴🔴 299/A2 — 298'DE KENDİ DÜŞÜRDÜĞÜM DÖRT ADIM GERİ KONULDU.
  --
  -- 298'de bu fonksiyonun başına freni takarken gövdeyi de yeniden
  -- yazdım ve 292'nin gövdesindeki DÖRT ADIMI düşürdüm. `drift_check.py`
  -- ikisini gösterdi (`perform public…`), kalan ikisini ben okuyarak
  -- buldum. Düşenler:
  --
  --   1) (b) bloğundaki `r.status = 'accepted'` KAPISI.
  --      280/K2'nin koyduğu kapı: iptal edilmiş isteğin yetim oturumu
  --      no_show DEĞİLDİR. Düşünce, iptal edilmiş bir isteğin arkasında
  --      kalan oturum yüzünden masum bir tarafa no_show yazılıyordu.
  --
  --   2) `perform public.recompute_trust(u) …`
  --      no_show işaretlenen tarafın güven puanı tazelenmiyordu. Yani
  --      ceza yazılıyor ama puana yansımıyordu.
  --
  --   3) (c) BLOĞUNUN TAMAMI — 187-noshow'un kapattığı hata.
  --      (b) oturumu 'expired' yapıyor ama isteği 'accepted' BIRAKIYOR.
  --      Bloksuz hali: misafirin kredisi sonsuza kilitli, host'un slotu
  --      sonsuza dolu (`sync_availability_filled` filled'ı accepted
  --      sayısından türetiyor). TEK BİR NO-SHOW İLANI KALICI OLARAK
  --      ÖLDÜRÜYORDU. 298 bunu geri getirmişti.
  --
  --   4) `perform public.tek_tarafli_oturumlari_kapat();`
  --
  -- 🆕 SINIF: "BİR FONKSİYONUN BAŞINA KAPI TAKARKEN GÖVDESİNİ YENİDEN
  -- YAZMA — ELDEKİ TANIMIN ÜSTÜNE EKLE. YENİDEN YAZMAK, GÖRMEDİĞİN HER
  -- ESKİ DÜZELTMEYİ SESSİZCE GERİ ALIR."
  --
  -- (a) Hiç başlatılmamış kabuller: kimse gelmedi ya da unutuldu →
  --     cezasız kapanış + kredi iadesi.
  --     🔴 İade tutarı artık sabit 1 değil: GERÇEKTEN TUTULAN kadar.
  with stale as (
    select r.id, r.guest_id
      from requests r
      join availabilities a on a.id = r.avail_id
      left join sessions s on s.request_id = r.id
     where r.status = 'accepted'
       -- 🔴 300/B2: `s.id is null` davet kabulünün açtığı BOŞ oturumu
       -- görmüyordu (293). Hiç kimse başlatmadıysa, oturum yok sayılır.
       and (s.id is null
            or (s.status = 'pending' and s.host_started_at is null
                and s.guest_started_at is null))
       and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours'
  ), upd as (
    update requests set status = 'cancelled' where id in (select id from stale) returning id, guest_id
  )
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  select u.guest_id, public.tutulan_kredi(u.id), 'expired_refund', u.id,
         coalesce((select sum(delta) from credit_ledger c where c.user_id = u.guest_id), 0)
           + public.tutulan_kredi(u.id)
    from upd u;
  get diagnostics v_req = row_count;
  -- 300/B2: iptal edilen isteğin arkasındaki boş oturum → 'expired' (no_show DEĞİL).
  update sessions s set status = 'expired', completed_at = now(), cancel_reason = 'not_started'
    from requests r
   where r.id = s.request_id and r.status = 'cancelled'
     and s.status = 'pending' and s.host_started_at is null and s.guest_started_at is null;

  -- (b) Tek taraf başlatmış ama diğeri hiç gelmemiş → 'expired'.
  --     `r.status = 'accepted'` KAPISI 280/K2'den; 299'da geri kondu.
  update sessions s
     set status = 'expired',
         completed_at = now(),
         cancel_reason = 'no_show',
         no_show_user_id = case when s.host_started_at is null then r.host_id else r.guest_id end
    from requests r, availabilities a
   where r.id = s.request_id and a.id = r.avail_id
     and s.status = 'pending'
     and r.status = 'accepted'
     and (s.host_started_at is null) <> (s.guest_started_at is null)
     and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours';
  get diagnostics v_sess = row_count;

  -- Etkilenenlerin güvenini tazele (292'den; 298'de düşmüştü).
  perform public.recompute_trust(u) from (
    select distinct no_show_user_id as u from sessions
     where cancel_reason = 'no_show' and no_show_user_id is not null
       and completed_at > now() - interval '1 day'
  ) x where u is not null;

  -- (c) 187-noshow · 298'de TAMAMEN DÜŞMÜŞTÜ, geri konuldu.
  --     (b) oturumu kapatır ama isteği 'accepted' bırakır; burada istek
  --     de kapanır ve kredi iade edilir. Yoksa kredi de slot da sonsuza
  --     kilitli kalır.
  with kapanan as (
    select r.id, r.guest_id
      from requests r
      join sessions s2 on s2.request_id = r.id
     where r.status = 'accepted'
       and s2.status = 'expired'
       and s2.cancel_reason = 'no_show'
  ), iade as (
    update requests set status = 'cancelled'
     where id in (select id from kapanan)
    returning id, guest_id
  )
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  select i.guest_id, public.tutulan_kredi(i.id), 'no_show_refund', i.id,
         coalesce((select sum(c.delta) from credit_ledger c
                    where c.user_id = i.guest_id), 0) + public.tutulan_kredi(i.id)
    from iade i
   where not exists (select 1 from credit_ledger c2
                      where c2.ref_id = i.id and c2.reason = 'no_show_refund');

  perform public.tek_tarafli_oturumlari_kapat();

  v_sonuc := jsonb_build_object('ok', true, 'durum', 'kosuldu',
                                'kaynak', p_kaynak,
                                'iptal_edilen', v_req, 'suresi_dolan', v_sess);

  -- Sonucu damgaya yaz: panelde "en son koşum NE YAPTI" görünsün.
  update public.supurge_damgasi
     set son_sonuc = v_sonuc, ardisik_hata = 0
   where ad = 'expire_stale_sessions';

  return v_sonuc;
exception
  when others then
    -- ⚠️ BURADA `update` DEĞİL `insert … on conflict` KULLANILIYOR VE
    -- BUNUN SEBEBİ ÖNEMLİ: plpgsql'de bir istisna, bloğun BAŞINDAN
    -- itibaren her şeyi geri alır — yukarıdaki damga `insert`i DAHİL.
    -- Yani handler'a girildiğinde satır ARTIK YOKTUR; `update` 0 satır
    -- günceller ve hata izi sessizce kaybolur. Tam da görünür kılmaya
    -- çalıştığımız şeyi kaybederdik.
    --
    -- 🆕 SINIF: "BİR HATA KAYDINI, HATANIN GERİ ALDIĞI SATIRIN ÜSTÜNE
    -- YAZAMAZSIN — HANDLER'DA HER ZAMAN YENİDEN OLUŞTURMAYA HAZIR OL."
    --
    -- Hatayı istisna olarak ATMIYORUZ, jsonb olarak DÖNÜYORUZ: çağıran
    -- `ok=false` görür, damga kalıcı olur ve `bo_supurge_sagligi()`
    -- onu gösterir. Yutmak değil — yerini değiştirmek.
    insert into public.supurge_damgasi (ad, son_kosum, kaynak, ardisik_hata, son_hata, son_hata_an)
    values ('expire_stale_sessions', coalesce(v_son, now() - interval '1 hour'),
            p_kaynak, 1, left(SQLERRM, 400), now())
    on conflict (ad) do update
      set ardisik_hata = public.supurge_damgasi.ardisik_hata + 1,
          kaynak       = excluded.kaynak,
          son_hata     = excluded.son_hata,
          son_hata_an  = excluded.son_hata_an;
    return jsonb_build_object('ok', false, 'durum', 'hata',
                              'kaynak', p_kaynak, 'hata', left(SQLERRM, 400));
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B4 · bayat_istekleri_iade_et  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.bayat_istekleri_iade_et()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saat int := coalesce((select (value #>> '{}')::int from beta_settings
                           where key = 'bayat_istek_saat'), 72);
  r record; v_bal int; v_kapatilan int := 0; v_iade int := 0;
begin
  perform public.motor_yazimi_ac();

  for r in
    select req.id, req.guest_id
      from requests req
      join availabilities a on a.id = req.avail_id
     where req.status = 'pending'
       and req.responded_at is null
       -- 🔴 300/B4: UTC tarihi değil, havalimanının yerel saati. Eskiden
       -- saati geçmiş bir ilanın bekleyen isteği ertesi UTC gününe kadar
       -- açık kalıyordu (kredi tutulu, host cevap veremez).
       and (public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()
            or req.created_at < now() - make_interval(hours => v_saat))
  loop
    -- Satır satır: bir satır bir iş kuralına takılırsa toplu iş çökmesin.
    begin
      update requests
         set status = 'cancelled',
             responded_at = now(),
             decision_note = coalesce(decision_note,
               'Host süresinde yanıtlamadı — istek otomatik kapatıldı (274).')
       where id = r.id and status = 'pending';
      if not found then continue; end if;
      v_kapatilan := v_kapatilan + 1;

      -- İADE yalnız gerçekten kredi düşülmüşse ve daha önce iade
      -- edilmemişse. `request_free_tier` satırları burada kasıtla dışarıda:
      -- harcanmayan kredi iade edilmez.
      if exists (select 1 from credit_ledger cl
                  where cl.ref_id = r.id and cl.reason in ('request_hold','invite_hold') and cl.delta < 0)
         and not exists (select 1 from credit_ledger cl
                          where cl.ref_id = r.id and cl.reason = 'request_stale_refund')
      then
        select coalesce(sum(delta), 0) into v_bal from credit_ledger where user_id = r.guest_id;
        insert into credit_ledger (user_id, delta, reason, ref_id, balance_after, note)
        values (r.guest_id, public.tutulan_kredi(r.id), 'request_stale_refund', r.id,
                v_bal + public.tutulan_kredi(r.id),
                format('%s saat içinde yanıt gelmedi', v_saat));
        v_iade := v_iade + 1;
      end if;

      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      values (r.guest_id, 'requests', 'İsteğin kapandı',
              format('Başvurun %s saat içinde yanıtlanmadı. Artık yeni istek gönderebilirsin.', v_saat),
              'request', r.id);
    exception when others then
      raise notice '274: istek % kapatilamadi: %', r.id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object('ok', true, 'kapatilan', v_kapatilan,
                            'iade_edilen', v_iade, 'esik_saat', v_saat);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B5 · create_request_impl  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.create_request_impl(p_avail_id uuid, p_type text DEFAULT 'lounge'::text, p_intro text DEFAULT NULL::text, p_idem text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare v_acik boolean; v_kalan int; v_tavan int;
      begin
        -- (a) ACİL DURDURMA
        select f.enabled into v_acik from feature_flags f where f.key = 'marketplace';
        if not coalesce(v_acik, true) then
          raise exception 'marketplace_closed';
        end if;

        -- (b) AYNI ANDA AÇIK İSTEK TAVANI — 029'da tohumlanmış ama
        -- yedi ay boyunca hiçbir yerde uygulanmamış bir eşik.
        select value into v_tavan from rule_thresholds where key = 'max_active_requests';
        select count(*) into v_kalan from requests
         where guest_id = auth.uid() and status = 'pending';
        if v_kalan >= coalesce(v_tavan, 5) then
          raise exception 'too_many_active_requests';
        end if;

        -- 🔴 300/B5: iki kapı, ikisi de ÖLÇÜLDÜ (SEED8 §5):
        --  · aynı ilana ikinci başvuru ham bir kısıt hatası döndürüyordu:
        --    "duplicate key value violates unique constraint …" — uygulama
        --    bunu "Bir şeyler ters gitti" diye gösteriyordu.
        --  · tarih bugünse ama SAAT geçmişse başvuru kabul ediliyordu.
        --  · 🔴 AYNI İLANA YENİDEN İSTEK SESSİZCE HİÇBİR ŞEY YAPMIYORDU.
        --    Uygulama tekrar-deneme anahtarını `uid:ilan` olarak üretiyor; iptal
        --    ettiğin (ya da reddedilen) isteğin anahtarı aynı kalıyordu. Yeni
        --    istek bu anahtarla gelince `preflag` ESKİ, KAPALI isteği
        --    `{"ok":true,"idempotent":true}` diye döndürüyordu — ekran "gönderildi"
        --    diyor, host hiçbir şey görmüyor. (Ölçüldü: ilk → iptal → tekrar =
        --    aynı id, durum `cancelled`.)
        --    Kapalı bir isteğin anahtarı artık serbest bırakılıyor: çift dokunuş
        --    korunur (açık istek), yeni deneme yeni istek olur.
        -- 🆕 SINIF: "BİR TEKRAR-DENEME ANAHTARI, KORUDUĞU İŞLEMDEN UZUN
        -- YAŞARSA, SONRAKİ HER GERÇEK İSTEĞİ BİR TEKRAR SANIR."
        if p_idem is not null then
          update requests set idempotency_key = null
           where idempotency_key = p_idem and guest_id = auth.uid()
             and status not in ('pending', 'accepted');
        end if;
        -- Tekrar deneme anahtarı (p_idem) ile gelen AÇIK istek dokunulmadan geçer.
        if p_idem is null or not exists (select 1 from requests
                                          where idempotency_key = p_idem and guest_id = auth.uid()) then
          if exists (select 1 from requests where guest_id = auth.uid() and avail_id = p_avail_id
                                              and status in ('pending','accepted')) then
            raise exception 'already_requested';
          end if;
          if exists (select 1 from availabilities a where a.id = p_avail_id
                      and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()) then
            raise exception 'availability_expired';
          end if;
        end if;

        return public.create_request_impl_preflag(p_avail_id, p_type, p_intro, p_idem);
      end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B6 · trg_bakiye_negatife_dusemez  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.trg_bakiye_negatife_dusemez()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_bal int;
begin
  if new.delta >= 0 then return new; end if;
  if new.reason like 'paid_guest_thanks_reversal:%' or new.reason like 'admin%' then
    return new;
  end if;

  -- 🔴 300/B6: KİLİT TETİKLEYİCİNİN İÇİNDE. 299/B2 kilidi dört yola
  -- koymuştu; `misafir_hakki_hediye_et` beşinciydi ve kilitsizdi. İki
  -- eşzamanlı hediye aynı 3 krediyi iki kez harcayabiliyordu (ölçüldü:
  -- ikinci oturum birincinin commit'ini beklemeden geçti).
  -- Kilit burada olunca YOL SAYISI önemsizleşiyor: bakiyeyi eksilten her
  -- satır, aynı kullanıcının diğer eksiltmesini commit'e kadar bekler ve
  -- sonra GÜNCEL toplamı okur.
  perform pg_advisory_xact_lock(hashtextextended('kredi:' || new.user_id::text, 0));
  select coalesce(sum(delta), 0) into v_bal
    from credit_ledger where user_id = new.user_id;

  if v_bal + new.delta < 0 then
    raise exception 'insufficient_credits'
      using detail = format('kullanıcı %s: bakiye %s, denenen %s (%s)',
                            new.user_id, v_bal, new.delta, new.reason),
            hint   = 'Bu satır bakiyeyi negatife düşürürdü; 299/B1 reddetti.';
  end if;
  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ. Açık kalan kapı varsa DUR.
-- ════════════════════════════════════════════════════════════════════════
do $z300$
declare v_n int; v_liste text;
begin
  -- A1: kilitli olanlar authenticated/anon tarafından çağrılamaz
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('change_plan','kredi_akis_raporu','anonymized_users',
                       'host_kota_durumu','doluluk_reddi_sayisi','oturum_kural_hedefi',
                       'kural_guncelligi','access_options_for_user','bo_slot_asimlari')
     and (has_function_privilege('authenticated', p.oid, 'execute')
          or has_function_privilege('anon', p.oid, 'execute'));
  if v_n > 0 then raise exception '300 §Z/A1: hâlâ açık: %', v_liste; end if;

  -- A2: PUBLIC'e açık SECURITY DEFINER fonksiyon kalmadı
  select count(distinct p.oid), string_agg(distinct p.proname, ', ') into v_n, v_liste
    from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef
     and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '300 §Z/A2: PUBLIC''e açık % fonksiyon: %', v_n, v_liste; end if;

  -- A2: küresel varsayılan gerçekten yazıldı mı?
  if not exists (select 1 from pg_default_acl d
                  where d.defaclnamespace = 0 and d.defaclobjtype = 'f'
                    and d.defaclrole = 'postgres'::regrole) then
    raise exception '300 §Z/A2: küresel varsayılan yetki kaydı yok';
  end if;

  -- Uygulamanın çağırdığı beş fonksiyon authenticated'da KALDI mı?
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('cancel_availability','binis_karti_kaydet','ilani_yeniden_yayinla',
                       'hikaye_davetini_ertele','kesifte_gorun','profil_karti',
                       'create_request','respond_request','confirm_session')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '300 §Z: uygulama fonksiyonu KAPANDI: %', v_liste; end if;

  -- A3 / B6 tetikleyicileri yerinde mi?
  if not exists (select 1 from pg_trigger where tgname = 'trg_visit_0_beyan_temizle') then
    raise exception '300 §Z/A3: tetikleyici yok';
  end if;
  if position('pg_advisory_xact_lock' in
       (select prosrc from pg_proc where proname = 'trg_bakiye_negatife_dusemez')) = 0 then
    raise exception '300 §Z/B6: kredi kilidi tetikleyicide yok';
  end if;
  if position('availability_expired' in
       (select prosrc from pg_proc where proname = 'respond_request')) = 0 then
    raise exception '300 §Z/B1: kabul kapısı yok';
  end if;
  if position('already_requested' in
       (select prosrc from pg_proc where proname = 'create_request_impl')) = 0 then
    raise exception '300 §Z/B5: mükerrer başvuru kapısı yok';
  end if;

  raise notice '300 §Z: bütün kapılar ölçüldü — kapalı';
end $z300$;

select '300 OK — uçtan uca denetim bulguları kapatıldı' as sonuc;

-- ----------------------------------------------------------------------
-- start_session   [etkin kaynak: 080_session_lifecycle.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.start_session(p_request_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  return public.start_session_request(p_request_id);
end $$;

-- ----------------------------------------------------------------------
-- confirm_session   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.confirm_session(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_s sessions%rowtype; v_r requests%rowtype;
  v_done boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);   -- 300/B3: yasaklı hesap oturum kapatamaz (diğer akış fonksiyonlarıyla aynı)
  select * into v_s from sessions where id = p_session_id for update;
  if not found then raise exception 'session_not_found'; end if;
  select * into v_r from requests where id = v_s.request_id;
  if v_uid not in (v_r.host_id, v_r.guest_id) then raise exception 'not_party'; end if;
  if v_s.status <> 'active' then raise exception 'not_active'; end if;

  if v_uid = v_r.host_id then
    update sessions set host_confirmed = true where id = p_session_id;
  else
    update sessions set guest_confirmed = true where id = p_session_id;
  end if;

  select host_confirmed and guest_confirmed into v_done from sessions where id = p_session_id;

  if v_done then
    update sessions set status = 'completed', completed_at = now() where id = p_session_id;
    update requests set status = 'completed' where id = v_s.request_id;

    -- 078: ÖDÜL BURADA (oturum bitti = hak edildi). Host 500 / misafir 200.
    -- Çift ödemeye karşı: aynı oturum için daha önce yazılmışsa atlanır.
    -- NOT: points_ledger'da balance_after KOLONU YOK (SQL 050'de tespit
    -- edilmişti; bakiye user_balances view'ından okunur). Buraya yazmaya
    -- kalkmak fonksiyonu çalışma anında patlatır — yazılmıyor.
    if not exists (select 1 from points_ledger
                    where ref_id = p_session_id and reason = 'session_reward') then
      insert into points_ledger (user_id, delta, reason, ref_id)
      values (v_r.host_id, 500, 'session_reward', p_session_id),
             (v_r.guest_id, 200, 'session_reward', p_session_id);
    end if;

    -- 067'deki ESCROW KAPANIŞ NOTU korunur (drift_check yakaladı):
    -- kredi host'a aktarılmaz (kredi = hak, para değil); misafirin kredisi
    -- harcanmış sayılır, deftere kapanış satırı düşülür.
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    select v_r.guest_id, 0, 'session_settled', p_session_id, coalesce(sum(delta),0)
      from credit_ledger where user_id = v_r.guest_id;

    -- Güven: oturum sayısı değişti → İKİ TARAF için kanonik hesap
    perform public.recompute_trust(v_r.host_id);
    perform public.recompute_trust(v_r.guest_id);

    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    select u, 'sessions', 'Oturum tamamlandı ✓',
           'Puanların hesabına eklendi. Karşı tarafı puanlamayı unutma.',
           'session', p_session_id
      from unnest(array[v_r.host_id, v_r.guest_id]) u;
  else
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (case when v_uid = v_r.host_id then v_r.guest_id else v_r.host_id end,
            'sessions', 'Oturum onayı bekleniyor',
            'Karşı taraf oturumu tamamladı olarak işaretledi.', 'session', p_session_id);
  end if;

  return jsonb_build_object('ok', true, 'completed', coalesce(v_done,false));
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B2 · expire_stale_sessions  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.expire_stale_sessions(p_kaynak text DEFAULT 'uygulama'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req int := 0; v_sess int := 0;
  v_son timestamptz;
  v_sonuc jsonb;
begin
  -- ── FREN (298) ────────────────────────────────────────────────────
  -- `for update` ile alıyoruz: iki istemci aynı anda çağırırsa ikincisi
  -- birincinin damgasını bekler ve "atlandi" döner. pg_cron ile uygulama
  -- tetiği AYNI FRENİ paylaşır — ikisi birden açık olsa bile gövde
  -- 5 dakikada bir koşar.
  select son_kosum into v_son from public.supurge_damgasi
   where ad = 'expire_stale_sessions' for update;

  if v_son is not null and v_son > now() - interval '5 minutes' then
    return jsonb_build_object('ok', true, 'durum', 'atlandi',
                              'kaynak', p_kaynak,
                              'sonraki', v_son + interval '5 minutes');
  end if;

  insert into public.supurge_damgasi (ad, son_kosum, kaynak)
  values ('expire_stale_sessions', now(), p_kaynak)
  on conflict (ad) do update set son_kosum = now(), kaynak = excluded.kaynak;

  -- ── GÖVDE ─────────────────────────────────────────────────────────
  --
  -- 🔴🔴 299/A2 — 298'DE KENDİ DÜŞÜRDÜĞÜM DÖRT ADIM GERİ KONULDU.
  --
  -- 298'de bu fonksiyonun başına freni takarken gövdeyi de yeniden
  -- yazdım ve 292'nin gövdesindeki DÖRT ADIMI düşürdüm. `drift_check.py`
  -- ikisini gösterdi (`perform public…`), kalan ikisini ben okuyarak
  -- buldum. Düşenler:
  --
  --   1) (b) bloğundaki `r.status = 'accepted'` KAPISI.
  --      280/K2'nin koyduğu kapı: iptal edilmiş isteğin yetim oturumu
  --      no_show DEĞİLDİR. Düşünce, iptal edilmiş bir isteğin arkasında
  --      kalan oturum yüzünden masum bir tarafa no_show yazılıyordu.
  --
  --   2) `perform public.recompute_trust(u) …`
  --      no_show işaretlenen tarafın güven puanı tazelenmiyordu. Yani
  --      ceza yazılıyor ama puana yansımıyordu.
  --
  --   3) (c) BLOĞUNUN TAMAMI — 187-noshow'un kapattığı hata.
  --      (b) oturumu 'expired' yapıyor ama isteği 'accepted' BIRAKIYOR.
  --      Bloksuz hali: misafirin kredisi sonsuza kilitli, host'un slotu
  --      sonsuza dolu (`sync_availability_filled` filled'ı accepted
  --      sayısından türetiyor). TEK BİR NO-SHOW İLANI KALICI OLARAK
  --      ÖLDÜRÜYORDU. 298 bunu geri getirmişti.
  --
  --   4) `perform public.tek_tarafli_oturumlari_kapat();`
  --
  -- 🆕 SINIF: "BİR FONKSİYONUN BAŞINA KAPI TAKARKEN GÖVDESİNİ YENİDEN
  -- YAZMA — ELDEKİ TANIMIN ÜSTÜNE EKLE. YENİDEN YAZMAK, GÖRMEDİĞİN HER
  -- ESKİ DÜZELTMEYİ SESSİZCE GERİ ALIR."
  --
  -- (a) Hiç başlatılmamış kabuller: kimse gelmedi ya da unutuldu →
  --     cezasız kapanış + kredi iadesi.
  --     🔴 İade tutarı artık sabit 1 değil: GERÇEKTEN TUTULAN kadar.
  with stale as (
    select r.id, r.guest_id
      from requests r
      join availabilities a on a.id = r.avail_id
      left join sessions s on s.request_id = r.id
     where r.status = 'accepted'
       -- 🔴 300/B2: `s.id is null` davet kabulünün açtığı BOŞ oturumu
       -- görmüyordu (293). Hiç kimse başlatmadıysa, oturum yok sayılır.
       and (s.id is null
            or (s.status = 'pending' and s.host_started_at is null
                and s.guest_started_at is null))
       and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours'
  ), upd as (
    update requests set status = 'cancelled' where id in (select id from stale) returning id, guest_id
  )
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  select u.guest_id, public.tutulan_kredi(u.id), 'expired_refund', u.id,
         coalesce((select sum(delta) from credit_ledger c where c.user_id = u.guest_id), 0)
           + public.tutulan_kredi(u.id)
    from upd u;
  get diagnostics v_req = row_count;
  -- 300/B2: iptal edilen isteğin arkasındaki boş oturum → 'expired' (no_show DEĞİL).
  update sessions s set status = 'expired', completed_at = now(), cancel_reason = 'not_started'
    from requests r
   where r.id = s.request_id and r.status = 'cancelled'
     and s.status = 'pending' and s.host_started_at is null and s.guest_started_at is null;

  -- (b) Tek taraf başlatmış ama diğeri hiç gelmemiş → 'expired'.
  --     `r.status = 'accepted'` KAPISI 280/K2'den; 299'da geri kondu.
  update sessions s
     set status = 'expired',
         completed_at = now(),
         cancel_reason = 'no_show',
         no_show_user_id = case when s.host_started_at is null then r.host_id else r.guest_id end
    from requests r, availabilities a
   where r.id = s.request_id and a.id = r.avail_id
     and s.status = 'pending'
     and r.status = 'accepted'
     and (s.host_started_at is null) <> (s.guest_started_at is null)
     and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours';
  get diagnostics v_sess = row_count;

  -- Etkilenenlerin güvenini tazele (292'den; 298'de düşmüştü).
  perform public.recompute_trust(u) from (
    select distinct no_show_user_id as u from sessions
     where cancel_reason = 'no_show' and no_show_user_id is not null
       and completed_at > now() - interval '1 day'
  ) x where u is not null;

  -- (c) 187-noshow · 298'de TAMAMEN DÜŞMÜŞTÜ, geri konuldu.
  --     (b) oturumu kapatır ama isteği 'accepted' bırakır; burada istek
  --     de kapanır ve kredi iade edilir. Yoksa kredi de slot da sonsuza
  --     kilitli kalır.
  with kapanan as (
    select r.id, r.guest_id
      from requests r
      join sessions s2 on s2.request_id = r.id
     where r.status = 'accepted'
       and s2.status = 'expired'
       and s2.cancel_reason = 'no_show'
  ), iade as (
    update requests set status = 'cancelled'
     where id in (select id from kapanan)
    returning id, guest_id
  )
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  select i.guest_id, public.tutulan_kredi(i.id), 'no_show_refund', i.id,
         coalesce((select sum(c.delta) from credit_ledger c
                    where c.user_id = i.guest_id), 0) + public.tutulan_kredi(i.id)
    from iade i
   where not exists (select 1 from credit_ledger c2
                      where c2.ref_id = i.id and c2.reason = 'no_show_refund');

  perform public.tek_tarafli_oturumlari_kapat();

  v_sonuc := jsonb_build_object('ok', true, 'durum', 'kosuldu',
                                'kaynak', p_kaynak,
                                'iptal_edilen', v_req, 'suresi_dolan', v_sess);

  -- Sonucu damgaya yaz: panelde "en son koşum NE YAPTI" görünsün.
  update public.supurge_damgasi
     set son_sonuc = v_sonuc, ardisik_hata = 0
   where ad = 'expire_stale_sessions';

  return v_sonuc;
exception
  when others then
    -- ⚠️ BURADA `update` DEĞİL `insert … on conflict` KULLANILIYOR VE
    -- BUNUN SEBEBİ ÖNEMLİ: plpgsql'de bir istisna, bloğun BAŞINDAN
    -- itibaren her şeyi geri alır — yukarıdaki damga `insert`i DAHİL.
    -- Yani handler'a girildiğinde satır ARTIK YOKTUR; `update` 0 satır
    -- günceller ve hata izi sessizce kaybolur. Tam da görünür kılmaya
    -- çalıştığımız şeyi kaybederdik.
    --
    -- 🆕 SINIF: "BİR HATA KAYDINI, HATANIN GERİ ALDIĞI SATIRIN ÜSTÜNE
    -- YAZAMAZSIN — HANDLER'DA HER ZAMAN YENİDEN OLUŞTURMAYA HAZIR OL."
    --
    -- Hatayı istisna olarak ATMIYORUZ, jsonb olarak DÖNÜYORUZ: çağıran
    -- `ok=false` görür, damga kalıcı olur ve `bo_supurge_sagligi()`
    -- onu gösterir. Yutmak değil — yerini değiştirmek.
    insert into public.supurge_damgasi (ad, son_kosum, kaynak, ardisik_hata, son_hata, son_hata_an)
    values ('expire_stale_sessions', coalesce(v_son, now() - interval '1 hour'),
            p_kaynak, 1, left(SQLERRM, 400), now())
    on conflict (ad) do update
      set ardisik_hata = public.supurge_damgasi.ardisik_hata + 1,
          kaynak       = excluded.kaynak,
          son_hata     = excluded.son_hata,
          son_hata_an  = excluded.son_hata_an;
    return jsonb_build_object('ok', false, 'durum', 'hata',
                              'kaynak', p_kaynak, 'hata', left(SQLERRM, 400));
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B4 · bayat_istekleri_iade_et  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.bayat_istekleri_iade_et()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saat int := coalesce((select (value #>> '{}')::int from beta_settings
                           where key = 'bayat_istek_saat'), 72);
  r record; v_bal int; v_kapatilan int := 0; v_iade int := 0;
begin
  perform public.motor_yazimi_ac();

  for r in
    select req.id, req.guest_id
      from requests req
      join availabilities a on a.id = req.avail_id
     where req.status = 'pending'
       and req.responded_at is null
       -- 🔴 300/B4: UTC tarihi değil, havalimanının yerel saati. Eskiden
       -- saati geçmiş bir ilanın bekleyen isteği ertesi UTC gününe kadar
       -- açık kalıyordu (kredi tutulu, host cevap veremez).
       and (public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()
            or req.created_at < now() - make_interval(hours => v_saat))
  loop
    -- Satır satır: bir satır bir iş kuralına takılırsa toplu iş çökmesin.
    begin
      update requests
         set status = 'cancelled',
             responded_at = now(),
             decision_note = coalesce(decision_note,
               'Host süresinde yanıtlamadı — istek otomatik kapatıldı (274).')
       where id = r.id and status = 'pending';
      if not found then continue; end if;
      v_kapatilan := v_kapatilan + 1;

      -- İADE yalnız gerçekten kredi düşülmüşse ve daha önce iade
      -- edilmemişse. `request_free_tier` satırları burada kasıtla dışarıda:
      -- harcanmayan kredi iade edilmez.
      if exists (select 1 from credit_ledger cl
                  where cl.ref_id = r.id and cl.reason in ('request_hold','invite_hold') and cl.delta < 0)
         and not exists (select 1 from credit_ledger cl
                          where cl.ref_id = r.id and cl.reason = 'request_stale_refund')
      then
        select coalesce(sum(delta), 0) into v_bal from credit_ledger where user_id = r.guest_id;
        insert into credit_ledger (user_id, delta, reason, ref_id, balance_after, note)
        values (r.guest_id, public.tutulan_kredi(r.id), 'request_stale_refund', r.id,
                v_bal + public.tutulan_kredi(r.id),
                format('%s saat içinde yanıt gelmedi', v_saat));
        v_iade := v_iade + 1;
      end if;

      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      values (r.guest_id, 'requests', 'İsteğin kapandı',
              format('Başvurun %s saat içinde yanıtlanmadı. Artık yeni istek gönderebilirsin.', v_saat),
              'request', r.id);
    exception when others then
      raise notice '274: istek % kapatilamadi: %', r.id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object('ok', true, 'kapatilan', v_kapatilan,
                            'iade_edilen', v_iade, 'esik_saat', v_saat);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B5 · create_request_impl  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.create_request_impl(p_avail_id uuid, p_type text DEFAULT 'lounge'::text, p_intro text DEFAULT NULL::text, p_idem text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare v_acik boolean; v_kalan int; v_tavan int;
      begin
        -- (a) ACİL DURDURMA
        select f.enabled into v_acik from feature_flags f where f.key = 'marketplace';
        if not coalesce(v_acik, true) then
          raise exception 'marketplace_closed';
        end if;

        -- (b) AYNI ANDA AÇIK İSTEK TAVANI — 029'da tohumlanmış ama
        -- yedi ay boyunca hiçbir yerde uygulanmamış bir eşik.
        select value into v_tavan from rule_thresholds where key = 'max_active_requests';
        select count(*) into v_kalan from requests
         where guest_id = auth.uid() and status = 'pending';
        if v_kalan >= coalesce(v_tavan, 5) then
          raise exception 'too_many_active_requests';
        end if;

        -- 🔴 300/B5: iki kapı, ikisi de ÖLÇÜLDÜ (SEED8 §5):
        --  · aynı ilana ikinci başvuru ham bir kısıt hatası döndürüyordu:
        --    "duplicate key value violates unique constraint …" — uygulama
        --    bunu "Bir şeyler ters gitti" diye gösteriyordu.
        --  · tarih bugünse ama SAAT geçmişse başvuru kabul ediliyordu.
        --  · 🔴 AYNI İLANA YENİDEN İSTEK SESSİZCE HİÇBİR ŞEY YAPMIYORDU.
        --    Uygulama tekrar-deneme anahtarını `uid:ilan` olarak üretiyor; iptal
        --    ettiğin (ya da reddedilen) isteğin anahtarı aynı kalıyordu. Yeni
        --    istek bu anahtarla gelince `preflag` ESKİ, KAPALI isteği
        --    `{"ok":true,"idempotent":true}` diye döndürüyordu — ekran "gönderildi"
        --    diyor, host hiçbir şey görmüyor. (Ölçüldü: ilk → iptal → tekrar =
        --    aynı id, durum `cancelled`.)
        --    Kapalı bir isteğin anahtarı artık serbest bırakılıyor: çift dokunuş
        --    korunur (açık istek), yeni deneme yeni istek olur.
        -- 🆕 SINIF: "BİR TEKRAR-DENEME ANAHTARI, KORUDUĞU İŞLEMDEN UZUN
        -- YAŞARSA, SONRAKİ HER GERÇEK İSTEĞİ BİR TEKRAR SANIR."
        if p_idem is not null then
          update requests set idempotency_key = null
           where idempotency_key = p_idem and guest_id = auth.uid()
             and status not in ('pending', 'accepted');
        end if;
        -- Tekrar deneme anahtarı (p_idem) ile gelen AÇIK istek dokunulmadan geçer.
        if p_idem is null or not exists (select 1 from requests
                                          where idempotency_key = p_idem and guest_id = auth.uid()) then
          if exists (select 1 from requests where guest_id = auth.uid() and avail_id = p_avail_id
                                              and status in ('pending','accepted')) then
            raise exception 'already_requested';
          end if;
          if exists (select 1 from availabilities a where a.id = p_avail_id
                      and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()) then
            raise exception 'availability_expired';
          end if;
        end if;

        return public.create_request_impl_preflag(p_avail_id, p_type, p_intro, p_idem);
      end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B6 · trg_bakiye_negatife_dusemez  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.trg_bakiye_negatife_dusemez()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_bal int;
begin
  if new.delta >= 0 then return new; end if;
  if new.reason like 'paid_guest_thanks_reversal:%' or new.reason like 'admin%' then
    return new;
  end if;

  -- 🔴 300/B6: KİLİT TETİKLEYİCİNİN İÇİNDE. 299/B2 kilidi dört yola
  -- koymuştu; `misafir_hakki_hediye_et` beşinciydi ve kilitsizdi. İki
  -- eşzamanlı hediye aynı 3 krediyi iki kez harcayabiliyordu (ölçüldü:
  -- ikinci oturum birincinin commit'ini beklemeden geçti).
  -- Kilit burada olunca YOL SAYISI önemsizleşiyor: bakiyeyi eksilten her
  -- satır, aynı kullanıcının diğer eksiltmesini commit'e kadar bekler ve
  -- sonra GÜNCEL toplamı okur.
  perform pg_advisory_xact_lock(hashtextextended('kredi:' || new.user_id::text, 0));
  select coalesce(sum(delta), 0) into v_bal
    from credit_ledger where user_id = new.user_id;

  if v_bal + new.delta < 0 then
    raise exception 'insufficient_credits'
      using detail = format('kullanıcı %s: bakiye %s, denenen %s (%s)',
                            new.user_id, v_bal, new.delta, new.reason),
            hint   = 'Bu satır bakiyeyi negatife düşürürdü; 299/B1 reddetti.';
  end if;
  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ. Açık kalan kapı varsa DUR.
-- ════════════════════════════════════════════════════════════════════════
do $z300$
declare v_n int; v_liste text;
begin
  -- A1: kilitli olanlar authenticated/anon tarafından çağrılamaz
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('change_plan','kredi_akis_raporu','anonymized_users',
                       'host_kota_durumu','doluluk_reddi_sayisi','oturum_kural_hedefi',
                       'kural_guncelligi','access_options_for_user','bo_slot_asimlari')
     and (has_function_privilege('authenticated', p.oid, 'execute')
          or has_function_privilege('anon', p.oid, 'execute'));
  if v_n > 0 then raise exception '300 §Z/A1: hâlâ açık: %', v_liste; end if;

  -- A2: PUBLIC'e açık SECURITY DEFINER fonksiyon kalmadı
  select count(distinct p.oid), string_agg(distinct p.proname, ', ') into v_n, v_liste
    from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef
     and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '300 §Z/A2: PUBLIC''e açık % fonksiyon: %', v_n, v_liste; end if;

  -- A2: küresel varsayılan gerçekten yazıldı mı?
  if not exists (select 1 from pg_default_acl d
                  where d.defaclnamespace = 0 and d.defaclobjtype = 'f'
                    and d.defaclrole = 'postgres'::regrole) then
    raise exception '300 §Z/A2: küresel varsayılan yetki kaydı yok';
  end if;

  -- Uygulamanın çağırdığı beş fonksiyon authenticated'da KALDI mı?
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('cancel_availability','binis_karti_kaydet','ilani_yeniden_yayinla',
                       'hikaye_davetini_ertele','kesifte_gorun','profil_karti',
                       'create_request','respond_request','confirm_session')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '300 §Z: uygulama fonksiyonu KAPANDI: %', v_liste; end if;

  -- A3 / B6 tetikleyicileri yerinde mi?
  if not exists (select 1 from pg_trigger where tgname = 'trg_visit_0_beyan_temizle') then
    raise exception '300 §Z/A3: tetikleyici yok';
  end if;
  if position('pg_advisory_xact_lock' in
       (select prosrc from pg_proc where proname = 'trg_bakiye_negatife_dusemez')) = 0 then
    raise exception '300 §Z/B6: kredi kilidi tetikleyicide yok';
  end if;
  if position('availability_expired' in
       (select prosrc from pg_proc where proname = 'respond_request')) = 0 then
    raise exception '300 §Z/B1: kabul kapısı yok';
  end if;
  if position('already_requested' in
       (select prosrc from pg_proc where proname = 'create_request_impl')) = 0 then
    raise exception '300 §Z/B5: mükerrer başvuru kapısı yok';
  end if;

  raise notice '300 §Z: bütün kapılar ölçüldü — kapalı';
end $z300$;

select '300 OK — uçtan uca denetim bulguları kapatıldı' as sonuc;

-- ----------------------------------------------------------------------
-- rate_session   [etkin kaynak: 078_trust_single_writer.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.rate_session(p_session_id uuid, p_score integer, p_comment text DEFAULT NULL::text)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_s sessions%rowtype; v_r requests%rowtype;
  v_other uuid; v_role text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_score < 1 or p_score > 5 then raise exception 'bad_score'; end if;

  select * into v_s from sessions where id = p_session_id;
  if not found then raise exception 'session_not_found'; end if;
  if v_s.status <> 'completed' then raise exception 'not_completed'; end if;

  select * into v_r from requests where id = v_s.request_id;
  if v_uid not in (v_r.host_id, v_r.guest_id) then raise exception 'not_party'; end if;

  v_role  := case when v_uid = v_r.host_id then 'host' else 'guest' end;
  v_other := case when v_uid = v_r.host_id then v_r.guest_id else v_r.host_id end;

  if exists (select 1 from ratings where session_id = p_session_id and rater_id = v_uid) then
    raise exception 'already_rated';
  end if;

  insert into ratings (session_id, rater_id, rated_id, score, comment)
  values (p_session_id, v_uid, v_other, p_score, nullif(trim(coalesce(p_comment,'')),''));

  -- 078: puan ARTIK BURADA VERİLMEZ (confirm_session'da veriliyor) ve
  -- güven skoru elle yazılmaz — kanonik hesap çağrılır.
  perform public.recompute_trust(v_other);

  return jsonb_build_object('ok', true, 'rated', true);
end $function$;
grant execute on function public.rate_session(uuid, integer, text) to authenticated;


-- ============================================================
-- 3) confirm_session — çift onay tamamlanınca PUANLARI VERİR
--    (067'nin gövdesi korunur; ödül + güven tazeleme eklendi)
-- ============================================================
CREATE OR REPLACE FUNCTION public.confirm_session(p_session_id uuid)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_s sessions%rowtype; v_r requests%rowtype;
  v_done boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_s from sessions where id = p_session_id for update;
  if not found then raise exception 'session_not_found'; end if;
  select * into v_r from requests where id = v_s.request_id;
  if v_uid not in (v_r.host_id, v_r.guest_id) then raise exception 'not_party'; end if;
  if v_s.status <> 'active' then raise exception 'not_active'; end if;

  if v_uid = v_r.host_id then
    update sessions set host_confirmed = true where id = p_session_id;
  else
    update sessions set guest_confirmed = true where id = p_session_id;
  end if;

  select host_confirmed and guest_confirmed into v_done from sessions where id = p_session_id;

  if v_done then
    update sessions set status = 'completed', completed_at = now() where id = p_session_id;
    update requests set status = 'completed' where id = v_s.request_id;

    -- 078: ÖDÜL BURADA (oturum bitti = hak edildi). Host 500 / misafir 200.
    -- Çift ödemeye karşı: aynı oturum için daha önce yazılmışsa atlanır.
    -- NOT: points_ledger'da balance_after KOLONU YOK (SQL 050'de tespit
    -- edilmişti; bakiye user_balances view'ından okunur). Buraya yazmaya
    -- kalkmak fonksiyonu çalışma anında patlatır — yazılmıyor.
    if not exists (select 1 from points_ledger
                    where ref_id = p_session_id and reason = 'session_reward') then
      insert into points_ledger (user_id, delta, reason, ref_id)
      values (v_r.host_id, 500, 'session_reward', p_session_id),
             (v_r.guest_id, 200, 'session_reward', p_session_id);
    end if;

    -- 067'deki ESCROW KAPANIŞ NOTU korunur (drift_check yakaladı):
    -- kredi host'a aktarılmaz (kredi = hak, para değil); misafirin kredisi
    -- harcanmış sayılır, deftere kapanış satırı düşülür.
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    select v_r.guest_id, 0, 'session_settled', p_session_id, coalesce(sum(delta),0)
      from credit_ledger where user_id = v_r.guest_id;

    -- Güven: oturum sayısı değişti → İKİ TARAF için kanonik hesap
    perform public.recompute_trust(v_r.host_id);
    perform public.recompute_trust(v_r.guest_id);

    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    select u, 'sessions', 'Oturum tamamlandı ✓',
           'Puanların hesabına eklendi. Karşı tarafı puanlamayı unutma.',
           'session', p_session_id
      from unnest(array[v_r.host_id, v_r.guest_id]) u;
  else
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (case when v_uid = v_r.host_id then v_r.guest_id else v_r.host_id end,
            'sessions', 'Oturum onayı bekleniyor',
            'Karşı taraf oturumu tamamladı olarak işaretledi.', 'session', p_session_id);
  end if;

  return jsonb_build_object('ok', true, 'completed', coalesce(v_done,false));
end $function$;
grant execute on function public.confirm_session(uuid) to authenticated;


-- ============================================================
-- 4) verify_otp / change_phone — güveni elle DEĞİL, kanonik hesapla
--    (026'nın etkin gövdeleri korunur; yalnız trust yazımı değişti)
-- ============================================================
CREATE OR REPLACE FUNCTION public.change_phone(p_phone text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  update users set phone = p_phone where id = v_uid;
  update verifications set phone_verified = false, phone_verified_at = null where user_id = v_uid;
  perform public.recompute_trust(v_uid);   -- 078: elle -10 yerine kanonik hesap
  return jsonb_build_object('ok', true, 'reverify_required', true);
end $$;

-- ----------------------------------------------------------------------
-- send_otp   [etkin kaynak: 269_dogrulama_zinciri.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.send_otp(p_phone text)
returns jsonb
language plpgsql security definer set search_path = public, extensions as $so269$
declare
  v_uid uuid := auth.uid();
  v_code text;
  v_recent int;
  v_saglayici text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_phone !~ '^\+[1-9][0-9]{9,14}$' then raise exception 'bad_phone_format'; end if;

  -- 🔴 GÖNDERİCİ YOKSA BAŞTAN SÖYLE. Kod üretip saklamanın da anlamı yok:
  -- kimsenin okuyamayacağı bir kod, `otp_tokens` tablosunu şişiren bir
  -- kayıttan başka bir şey değil.
  select coalesce(value #>> '{}', '') into v_saglayici
    from beta_settings where key = 'otp_sms_saglayici';
  if coalesce(v_saglayici, '') = '' then
    raise exception 'sms_not_configured';
  end if;

  select count(*) into v_recent from otp_tokens
   where user_id = v_uid and created_at > now() - interval '1 minute';
  if v_recent >= 1 then raise exception 'too_many_requests'; end if;

  v_code := lpad((floor(random() * 1000000))::int::text, 6, '0');

  update otp_tokens set used_at = now()
   where user_id = v_uid and used_at is null and purpose = 'phone_verify';

  insert into otp_tokens (user_id, phone_e164, code_hash, purpose, expires_at)
  values (v_uid, p_phone, crypt(v_code, gen_salt('bf')), 'phone_verify', now() + interval '5 minutes');

  -- ⚠️ SMS GÖNDERİMİ BURAYA GELECEK (Edge Function / pg_net → sağlayıcı).
  -- Kodu YANITTA DÖNDÜRME: 253 §3 tam olarak o arka kapıyı kapattı.
  return jsonb_build_object('ok', true, 'expires_in', 300);
end $so269$;
grant execute on function public.send_otp(text) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §6 — NÖBETÇİ: ZİNCİRİN HER HALKASI DENENİYOR
-- ════════════════════════════════════════════════════════════════════════
do $nb269$
declare
  u uuid; s0 int; s1 int; v_kanal jsonb; v_hata text := '';
begin
  select id into u from users where deleted_at is null order by id limit 1;
  if u is null then raise notice '269 NOBETCI: kullanici yok — atlandi.'; return; end if;

  -- (a) E-POSTA DOĞRULAMASI ARTIK PUAN GETİRİYOR
  insert into verifications (user_id, email_verified, phone_verified)
  values (u, false, false)
  on conflict (user_id) do update set email_verified=false, phone_verified=false;
  s0 := public.recompute_trust(u);
  update verifications set email_verified = true, email_verified_at = now() where user_id = u;
  s1 := public.recompute_trust(u);
  raise notice '269 NOBETCI: dogrulanmamis % → dogrulanmis %  (fark %)', s0, s1, s1 - s0;
  if s1 - s0 <> 10 then
    v_hata := v_hata || format('e-posta dogrulamasi %s puan getiriyor (10 olmali); ', s1 - s0);
  end if;

  -- (b) TERS YÖN: doğrulanmamış kullanıcı e-posta puanı ALMAMALI
  if (select (components ? 'email') from trust_scores where user_id = u) is null then
    v_hata := v_hata || 'trust_scores yazilmamis; ';
  end if;

  -- (c) SMS GÖNDERİCİSİ YOKKEN `send_otp` SESSİZCE BAŞARILI OLMAMALI
  begin
    perform public.send_otp('+905551112233');
    v_hata := v_hata || 'send_otp saglayici yokken OK donuyor; ';
  exception
    when sqlstate 'P0001' then
      if sqlerrm not in ('sms_not_configured', 'not_authenticated') then
        v_hata := v_hata || format('send_otp beklenmeyen hata: %s; ', sqlerrm);
      end if;
  end;

  -- (d) KANAL İSTEMCİYE OKUNABİLİR
  v_kanal := public.dogrulama_kanali();
  raise notice '269 NOBETCI: kanal = % · sms_hazir = %',
    v_kanal ->> 'kanal', v_kanal ->> 'sms_hazir';
  if (v_kanal ->> 'kanal') is null then
    v_hata := v_hata || 'dogrulama_kanali kanal dondurmuyor; ';
  end if;

  if v_hata <> '' then
    raise exception '269 NOBETCI: %', v_hata;
  end if;
  raise notice '269 NOBETCI OK — dogrulama zinciri butun.';

  raise exception 'NOBETCI_GERI_AL';
exception when others then
  if sqlerrm = 'NOBETCI_GERI_AL' then
    raise notice '269 NOBETCI: deney satirlari geri alindi.';
  else
    raise;
  end if;
end $nb269$;

-- ════════════════════════════════════════════════════════════════════════
-- §7 — ARTIK OKUNMAYAN İKİ AYAR: SİL, AMA GEREKÇESİNİ BIRAK
--
-- 🔴 §5 `send_otp`ı yeniden yazınca `otp_demo_mode` okuması ORTADAN
-- KALKTI — yani ayar artık HİÇBİR ŞEYİ KONTROL ETMİYOR. Bırakmak
-- tehlikeli: bir gün biri onu `yes` yapıp "demo modu açtım" sanır ve
-- hiçbir şey olmaz; ya da tersine, `no` gördüğü için arka kapının
-- kapalı olduğunu sanır — oysa kapıyı kapatan artık gövdenin kendisi.
--
-- 🆕 SINIF: "İŞLEVİNİ KAYBETMİŞ BİR AYARI SİLMEZSEN, O AYAR BİR KONTROL
-- SANILIR — VE YANLIŞ YERE BAKAN BİR GÜVENLİK KONTROLÜ, HİÇ KONTROL
-- OLMAMASINDAN DAHA KÖTÜDÜR."
--
-- Anahtarı siliyoruz; kararın KAYDI `_note` olarak kalıyor (nöbetçi
-- `_note` ile bitenleri ölü saymıyor — çünkü onlar okunmak için değil,
-- okunmak istenmeyen bir soruya cevap vermek için var).
-- ════════════════════════════════════════════════════════════════════════
insert into beta_settings (key, value) values
  ('otp_demo_mode_note', to_jsonb(
     'Kaldırıldı (269): send_otp artık kodu yanıtta hiç üretmiyor; arka '
     'kapı ayarla değil gövdeyle kapatıldı. Anahtar bırakılsaydı, olmayan '
     'bir kontrolü kontrol sanan biri yanlış güvenceye kapılırdı.'::text))
on conflict (key) do nothing;

delete from beta_settings where key = 'otp_demo_mode';

-- ════════════════════════════════════════════════════════════════════════
-- §8 — `mark_email_verified` İSTEMCİ YÜZEYİNDEN ÇIKIYOR
--
-- 🔴 Gövdesi `verify_email_contact` ile BİREBİR AYNI: ikisi de
-- `auth.users.email_confirmed_at`e bakıp `verifications`a yazıp
-- `recompute_trust` çağırıyor. Uygulama İKİSİNİ DE art arda çağırıyordu —
-- bir tur fazladan bekleme ve iki kez puan hesabı.
--
-- Uygulama tarafındaki ikinci çağrı kaldırıldı; fonksiyon artık istemci
-- yüzeyinde durmasın. Kendi nöbetçim (`sozlesme_check`) bunu hemen
-- yakaladı: "yüzeye yazılmış ama app HİÇ çağırmıyor".
--
-- ⚠️ Fonksiyon SİLİNMİYOR: `service_role` ya da bir bakım işi çağırabilir.
-- Kapanan şey İSTEMCİ YÜZEYİ — yani anon/authenticated'in görebildiği
-- yüzey. Bir fonksiyonu silmekle onu istemciye kapatmak aynı şey değil.
-- 🆕 SINIF: "KULLANILMAYAN BİR UCU SİLMEK İLE KAPATMAK FARKLI KARARLARDIR
-- — SİLMEK GERİ ALINAMAZ, KAPATMAK ALINABİLİR."
-- ════════════════════════════════════════════════════════════════════════
delete from rpc_client_surface where fn_name = 'mark_email_verified';
revoke execute on function public.mark_email_verified() from anon, authenticated;

commit;

-- ⚠️ COMMIT SONRASI: nöbetçi kendi deneyini geri aldı ama §1'in doldurduğu
-- ayna KALICI. Puanları gerçeğe göre yeniden hesapla:
select public.recompute_trust(id) from users where deleted_at is null;

-- ----------------------------------------------------------------------
-- verify_otp   [etkin kaynak: 079_email_otp_contact_verification.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.verify_otp(p_phone text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid    uuid := auth.uid();
  v_row    otp_tokens%rowtype;
  v_ok     boolean := false;
  v_demo   boolean := false;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- Demo kısayolu yalnızca ayar açıkken geçerli (lansmanda kapatılacak)
  select coalesce((value)::text = 'true', false) into v_demo
    from beta_settings where key = 'otp_demo_bypass';

  if v_demo and p_code = '0000' then
    v_ok := true;
  else
    -- DOĞRU KOLONLAR: phone_e164 + used_at (send_otp ile aynı)
    select * into v_row from otp_tokens
     where user_id = v_uid
       and phone_e164 = p_phone
       and used_at is null
       and expires_at > now()
     order by created_at desc
     limit 1
     for update;

    if not found then
      raise exception 'invalid_code';       -- süresi dolmuş ya da hiç yok
    end if;

    -- KABA-KUVVET KORUMASI (009'dan geri getirildi)
    if coalesce(v_row.attempts, 0) >= 5 then
      raise exception 'too_many_attempts';
    end if;

    if v_row.code_hash = crypt(p_code, v_row.code_hash) then
      v_ok := true;
      update otp_tokens set used_at = now() where id = v_row.id;
    else
      -- Yanlış kod → deneme sayacını artır, sonra hata ver
      update otp_tokens set attempts = coalesce(attempts,0) + 1 where id = v_row.id;
      raise exception 'invalid_code';
    end if;
  end if;

  if not v_ok then raise exception 'invalid_code'; end if;

  -- Telefonu kullanıcıya yaz — HER İKİ kolon da (phone_in_use phone_e164 okuyor)
  update users set phone = p_phone, phone_e164 = p_phone where id = v_uid;

  insert into verifications (user_id, phone_verified, phone_verified_at)
  values (v_uid, true, now())
  on conflict (user_id) do update
    set phone_verified = true, phone_verified_at = now();

  -- §16: telefon doğrulama +10 (yalnızca bir kez)
  perform public.recompute_trust(v_uid);   -- 078/079: tek yazıcı

  return jsonb_build_object('ok', true);
end $function$;
grant execute on function public.verify_otp(text, text) to authenticated;

-- ---------- 6) KAPILAR: telefon → doğrulanmış iletişim ----------
CREATE OR REPLACE FUNCTION public.create_availability(p_lounge_id uuid, p_airport text, p_date date, p_from time without time zone, p_to time without time zone, p_slots integer, p_flight text DEFAULT NULL::text, p_visibility text DEFAULT 'all'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_cap int; v_ok boolean; v_id uuid; v_conflict boolean;
  v_vis availability_visibility; v_min_trust smallint := 0;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- 079: KAPI ARTIK "DOĞRULANMIŞ İLETİŞİM" (telefon VEYA e-posta).
  -- SMS maliyetli olduğu için beta boyunca e-posta doğrulaması yeterli;
  -- demo bypass (kod 0000) kaldırıldı.
  v_ok := public.is_contact_verified(v_uid);
  if not v_ok then raise exception 'contact_not_verified'; end if;

  select guest_capacity into v_cap from profiles where user_id = v_uid;
  if v_cap is null then raise exception 'no_access_source'; end if;
  if p_slots > v_cap then raise exception 'slots_exceed_capacity'; end if;
  if p_date < current_date then raise exception 'date_in_past'; end if;

  -- 033: örtüşen saatte bekleyen/kabul edilmiş guest isteğin varsa ilan açamazsın
  select exists (
    select 1 from requests r
      join availabilities a on a.id = r.avail_id
     where r.guest_id = v_uid and r.status in ('pending','accepted')
       and a.avail_date = p_date
       and a.time_from < p_to and p_from < a.time_to
  ) into v_conflict;
  if v_conflict then raise exception 'guest_same_slot'; end if;

  -- 040: MVP'nin all/trusted/hidden -> enum + eşik
  case lower(coalesce(p_visibility,'all'))
    when 'all'         then v_vis := 'Public';      v_min_trust := 0;
    when 'trusted'     then v_vis := 'Public';      v_min_trust := 55;
    when 'hidden'      then v_vis := 'Hidden';      v_min_trust := 0;
    when 'connections' then v_vis := 'Connections'; v_min_trust := 0;
    else raise exception 'bad_visibility';
  end case;

  insert into availabilities (
    host_id, lounge_id, airport_code, avail_date, time_from, time_to,
    slots, filled, active, visibility, flight_number, min_trust
  )
  values (
    v_uid, p_lounge_id, p_airport, p_date, p_from, p_to,
    p_slots, 0, true, v_vis, nullif(trim(p_flight),''), v_min_trust
  )
  returning id into v_id;

  -- 055: ilan açmak = host olmak (rol)
  update users set role = 'host' where id = v_uid and role <> 'host';

  -- YENİ (074): ilan açmak = APP HOST'U olmak (görünürlük).
  -- Sıra önemli: is_staff hâlâ true iken profil düzeltilir (işaret olarak
  -- kullanılıyor), SONRA bayrak temizlenir. Kullanıcının kendi kapattığı
  -- show_on_discovery'ye (staff değilse) dokunulmaz.
  update profiles p set show_on_discovery = true
   where p.user_id = v_uid
     and p.show_on_discovery = false
     and exists (select 1 from users u where u.id = v_uid and u.is_staff = true);
  update users set is_staff = false where id = v_uid and is_staff = true;

  -- 056: ARZ-TALEP EŞLEŞTİRME — eşleşen misafirlere "host geldi" bildirimi
  -- (SELECT içindeki literal enum'a OTOMATİK çevrilmez -> 071 cast'i korunur)
  insert into notifications (user_id, category, title, body, ref_id, ref_type)
  select distinct vs.user_id, 'requests'::notif_category,
         'Havalimanında host var! ✦',
         'Seni bekleyen bir host ' || p_airport || ' için ilan açtı. Hemen başvur.',
         v_id, 'availability'
    from visits vs
    join users gu on gu.id = vs.user_id
   where vs.airport_code = p_airport
     and vs.visit_date = p_date
     and vs.time_from < p_to and p_from < vs.time_to
     and vs.user_id <> v_uid
     and coalesce(gu.is_staff,false) = false
     and gu.deleted_at is null;

  return jsonb_build_object('ok', true, 'id', v_id, 'visibility', v_vis, 'min_trust', v_min_trust);
end $function$;

CREATE OR REPLACE FUNCTION public.create_request(p_avail_id uuid, p_type text DEFAULT 'lounge'::text, p_intro text DEFAULT NULL::text, p_idem text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_av availabilities%rowtype;
  v_ok boolean; v_bal int; v_score int; v_req_id uuid; v_has_trip boolean;
  v_conflict boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  if p_idem is not null then
    select id into v_req_id from requests where idempotency_key = p_idem;
    if v_req_id is not null then return jsonb_build_object('ok', true, 'id', v_req_id, 'idempotent', true); end if;
  end if;

  -- 079: KAPI ARTIK "DOĞRULANMIŞ İLETİŞİM" (telefon VEYA e-posta).
  -- SMS maliyetli olduğu için beta boyunca e-posta doğrulaması yeterli;
  -- demo bypass (kod 0000) kaldırıldı.
  v_ok := public.is_contact_verified(v_uid);
  if not v_ok then raise exception 'contact_not_verified'; end if;

  select * into v_av from availabilities where id = p_avail_id for update;
  if not found or not v_av.active then raise exception 'availability_not_found'; end if;
  if v_av.host_id = v_uid then raise exception 'self_request_blocked'; end if;
  if v_av.filled >= v_av.slots then raise exception 'fully_booked'; end if;
  if v_av.avail_date < current_date then raise exception 'availability_expired'; end if;

  -- YENİ (033): aynı gün + örtüşen saatte kendi AKTİF host ilanın varsa başvuramazsın
  select exists (
    select 1 from availabilities a
     where a.host_id = v_uid and a.active
       and a.avail_date = v_av.avail_date
       and a.time_from < v_av.time_to and v_av.time_from < a.time_to
  ) into v_conflict;
  if v_conflict then raise exception 'hosting_same_slot'; end if;

  -- REQUEST KAPISI: trip zorunlu (rolden bağımsız — host da trip eklemeli)
  select exists (
    select 1 from visits v
     where v.user_id = v_uid and v.airport_code = v_av.airport_code
       and v.visit_date = v_av.avail_date
       and v.time_from < v_av.time_to and v_av.time_from < v.time_to
  ) into v_has_trip;
  if not v_has_trip then raise exception 'no_matching_trip'; end if;

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  if v_bal < 1 then raise exception 'insufficient_credits'; end if;

  select match_score into v_score from discover_availabilities(v_av.airport_code, null, null)
   where id = p_avail_id limit 1;

  insert into requests (guest_id, host_id, avail_id, status, type, purpose, intro_message, match_score, idempotency_key)
  values (v_uid, v_av.host_id, p_avail_id, 'pending', 'standard'::request_type, coalesce(p_type,'lounge'), left(coalesce(p_intro,''),120),
          coalesce(v_score,40), p_idem)
  returning id into v_req_id;

  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  values (v_uid, -1, 'request_hold', v_req_id, v_bal - 1);

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_av.host_id, 'requests', 'Yeni istek ✦',
          'Bir misafir lounge isteği gönderdi.', 'request', v_req_id);

  return jsonb_build_object('ok', true, 'id', v_req_id);
end $function$;

CREATE OR REPLACE FUNCTION public.send_connection(p_to uuid, p_intent text, p_intro text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_ok boolean; v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_to = v_uid then raise exception 'self_connect_blocked'; end if;

  -- 079: KAPI ARTIK "DOĞRULANMIŞ İLETİŞİM" (telefon VEYA e-posta).
  -- SMS maliyetli olduğu için beta boyunca e-posta doğrulaması yeterli;
  -- demo bypass (kod 0000) kaldırıldı.
  v_ok := public.is_contact_verified(v_uid);
  if not v_ok then raise exception 'contact_not_verified'; end if;

  if exists (select 1 from connection_requests
              where ((from_id=v_uid and to_id=p_to) or (from_id=p_to and to_id=v_uid))
                and status in ('pending','accepted')) then
    raise exception 'connection_exists';
  end if;

  insert into connection_requests (from_id, to_id, intent, intro, status)
  values (v_uid, p_to, coalesce(p_intent,'connect'), left(coalesce(p_intro,''),140), 'pending')
  returning id into v_id;

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (p_to, 'connections', 'Yeni bağlantı isteği ◈',
          'Bir yolcu seninle bağlantı kurmak istiyor.', 'connection', v_id);

  return jsonb_build_object('ok', true, 'id', v_id);
end $function$;

CREATE OR REPLACE FUNCTION public.send_invite(p_guest uuid, p_avail_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_ok boolean; v_id uuid; v_av availabilities%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  -- 079: KAPI ARTIK "DOĞRULANMIŞ İLETİŞİM" (telefon VEYA e-posta).
  -- SMS maliyetli olduğu için beta boyunca e-posta doğrulaması yeterli;
  -- demo bypass (kod 0000) kaldırıldı.
  v_ok := public.is_contact_verified(v_uid);
  if not v_ok then raise exception 'contact_not_verified'; end if;

  select * into v_av from availabilities where id = p_avail_id;
  if v_av.host_id <> v_uid then raise exception 'not_owner'; end if;
  if v_av.filled >= v_av.slots then raise exception 'fully_booked'; end if;

  -- soğuk davet yasak: geçmiş misafir olmalı
  if not exists (
    select 1 from requests r join availabilities a on a.id = r.avail_id
     where a.host_id = v_uid and r.guest_id = p_guest and r.status in ('accepted','completed')
  ) then raise exception 'cold_invite_blocked'; end if;

  insert into invites (host_id, guest_id, avail_id, note, status)
  values (v_uid, p_guest, p_avail_id, left(coalesce(p_note,''),140), 'pending')
  returning id into v_id;

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (p_guest, 'requests', 'Lounge daveti ✦',
          coalesce(v_av.lounge_name, v_av.airport_code) || ' · ' || left(coalesce(p_note,''),80), 'invite', v_id);

  return jsonb_build_object('ok', true, 'id', v_id);
end $function$;

grant execute on function public.create_request(uuid, text, text, text) to authenticated;
grant execute on function public.create_availability(uuid, text, date, time, time, integer, text, text) to authenticated;
grant execute on function public.send_invite(uuid, uuid, text) to authenticated;
grant execute on function public.send_connection(uuid, text, text) to authenticated;


-- ============================================================
-- DOĞRULAMA
-- ============================================================
-- (1) true dönmeli: kapılar artık iletişim doğrulamasına bakıyor
select bool_and(prosrc ilike '%is_contact_verified%') as "kapilar_guncel"
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public'
   and p.proname in ('create_request','create_availability','send_invite','send_connection');

-- (2) false dönmeli: demo bypass kapalı
select (value)::text = 'true' as "demo_bypass_hala_acik" from beta_settings where key='otp_demo_bypass';

-- (3) true dönmeli: e-posta doğrulama fonksiyonu var
select exists (select 1 from pg_proc where proname='verify_email_contact') as "email_dogrulama_var";

select '079 OK - dogrulama kapisi telefon VEYA e-posta, demo bypass kapatildi' as sonuc;

-- ----------------------------------------------------------------------
-- discover_availabilities   [etkin kaynak: 243_one_cikarma_gercekten_calissin.sql]
-- ⚠ Bu fonksiyon 15 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.discover_availabilities(%s) returns %s '
    'language sql stable security definer set search_path = public as $b$ '
    '  select (t.r).* from ( '
    '    select h as r, row_number() over () as rn '
    '      from public.discover_availabilities_ham(p_airport, p_sector, p_flight, p_date) h '
    '  ) t '
    '  order by coalesce((t.r).is_featured, false) desc, t.rn $b$', v_arg, v_ret);

  raise notice '243: kesif sarmalandi — ic siralama AYNEN korundu, one cikanlar basa alindi.';
end $siralama$;

grant execute on function public.discover_availabilities(text, text, text, date) to authenticated;

-- ----------------------------------------------------------------------------
-- 4b) ÖNE ÇIKARMAYI ONARINCA YENİ BİR RİSK AÇTIM — ONU DA KAPATIYORUM
-- ----------------------------------------------------------------------------
-- 🔴 Öne çıkarmayı sıralamanın BİRİNCİ ölçütü yaptım. Aynı anda Kâhya
-- planında `one_cikarma_ayda = 99` var — yani pratikte sınırsız, günde
-- ~3 öne çıkarma. Üç ilanı olan tek bir Kâhya kullanıcısı, keşfin en
-- üstünü SÜREKLİ işgal edebilir.
--
-- Yani bir kırığı onarırken bir kaldıraç yarattım: para ödeyen tek
-- kullanıcı, eşleşme kalitesini kalıcı olarak ezebilir. Öne çıkarma
-- "24 saatliğine görünürlük" demek olmalı, "keşfi satın almak" değil.
--
-- 🆕 SINIF: **"BİR SIRALAMA KALDIRACINI ONARIRKEN, O KALDIRACIN TAVANINI
-- DA KOYMAZSAN ONARDIĞIN ŞEY İSTİSMAR YOLU OLUR."**
--
-- Tavan: bir host'un aynı anda EN FAZLA 1 ilanı öne çıkabilir. Plan
-- hakkı ayda kaç kez öne çıkarabileceğini belirler; bu kural aynı anda
-- kaç tanesinin üstte durabileceğini. İkisi farklı sorulardır.
insert into beta_settings (key, value) values ('one_cikan_esz_tavan_host', to_jsonb(1))
on conflict (key) do nothing;

do $tavan$
declare v_def text; v_yeni text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='set_featured' limit 1;
  if v_def is null then raise exception '243: set_featured yok.'; end if;
  if v_def ~ 'one_cikan_esz_tavan_host' then
    raise notice '243: es zamanli one cikarma tavani zaten kurulu.';
    return;
  end if;

  -- Sahiplik kontrolünden HEMEN SONRA araya giriyorum. Metni birebir
  -- aramıyorum: `not_owner` satırı kısa ve kararlı bir çapa.
  v_yeni := regexp_replace(v_def,
    '(raise exception ''not_owner'';\s*end if;)',
    E'\\1\n'
    '   if (select count(*) from availabilities a\n'
    '        where a.host_id = v_uid and a.featured_until > now()\n'
    '          and a.id <> p_avail_id)\n'
    '      >= coalesce((select (value #>> ''{}'')::int from beta_settings\n'
    '                    where key = ''one_cikan_esz_tavan_host''), 1) then\n'
    '     raise exception ''zaten_one_cikan_ilanin_var''\n'
    '       using hint = ''Ayni anda tek ilanin one cikabilir. Digerinin 24 saati dolunca tekrar dene.'';\n'
    '   end if;');

  if v_yeni = v_def then
    raise exception '243: set_featured govdesinde `not_owner` capasi bulunamadi — '
                    'es zamanli tavan EKLENEMEDI. Govde: %', left(v_def, 300);
  end if;
  execute v_yeni;
  raise notice '243: es zamanli one cikarma tavani kuruldu (host basina 1).';
end $tavan$;

-- ----------------------------------------------------------------------------
-- 5) NÖBETÇİ — HER İKİ KIRIĞI DA, HER İKİ YÖNDE
-- ----------------------------------------------------------------------------
do $n243$
declare
  v_av      uuid;
  v_host    uuid;
  v_son     timestamptz;
  v_hatalar text[] := '{}';
  v_notlar  text[] := '{}';
  v_r       jsonb;
  v_ilk     uuid;
begin
  begin  -- ölçüm alt işlemi, sonunda geri alınır
    select a.id, a.host_id into v_av, v_host
      from availabilities a
     where a.active and a.avail_date >= current_date
       and not exists (select 1 from requests r where r.avail_id=a.id and r.status='accepted')
     order by a.id limit 1;

    if v_av is null then
      raise notice '243 OLCULMEDI: uygun ilan yok (SEED kosulmamis olabilir).';
    else
      perform set_config('request.jwt.claims',
        json_build_object('sub', v_host, 'role', 'authenticated')::text, true);

      -- Ölçüm için puan yatırıyorum. Alt işlem geri alınacağı için
      -- veriye dokunmuyor; amaç `set_featured`in PUAN yolunu da
      -- sınayabilmek (host'un plan hakkı olmayabilir).
      insert into points_ledger (user_id, delta, reason)
      values (v_host, 1000, 'nobetci_243_olcum');

      -- (1) 🔴 ASIL KIRIK: set_featured GERÇEKTEN yazıyor mu
      begin
        v_r := public.set_featured(v_av);
      exception when others then
        v_hatalar := v_hatalar || ('set_featured patladi: ' || sqlerrm);
      end;
      select featured_until into v_son from availabilities where id = v_av;
      if v_son is null or v_son <= now() then
        v_hatalar := v_hatalar ||
          format('set_featured "%s" dedi ama featured_until YAZILMADI (%s) — hak harcandi, ilan one cikmadi',
                 coalesce(v_r::text,'(hata)'), coalesce(v_son::text,'NULL'));
      end if;

      -- (2) TERS YÖN: istemci yolundan motor çıktısı HÂLÂ yazılamamalı.
      -- Bayrak işlem-yerel; ayrı bir alt işlemde sıfırlanmadığı için
      -- burada elle kapatıyorum — yoksa (1) yüzünden açık kalır ve bu
      -- ölçüm yalancı yeşil verir.
      perform set_config('loungelink.motor', '', true);
      update availabilities set rule_headline = 'Kesinlikle girersin' where id = v_av;
      if exists (select 1 from availabilities where id=v_av and rule_headline='Kesinlikle girersin') then
        v_hatalar := v_hatalar || 'motor cikitisi istemci yolundan YAZILABILDI — 240 in korumasi gitti'::text;
      end if;
    end if;

    raise exception 'GERI_AL_243';
  exception when others then
    if sqlerrm <> 'GERI_AL_243' then
      v_hatalar := v_hatalar || ('olcum alt islemi coktu: ' || sqlerrm);
    end if;
  end;

  -- 🔴 (3) VE (4) ÖNCE METNE BAKIYORDU: "gövdede `is_featured` geçiyor
  -- mu", "`match_score` geçiyor mu". Sarmalayıcı yaklaşımına geçince
  -- ikisi de gövdeden çıktı (artık `_ham`ın içindeler) ve nöbetçi
  -- ÇALIŞAN bir düzeltmeyi hata saydı.
  --
  -- 🆕 SINIF: **"BİR DAVRANIŞI KOD METNİNDEN DOĞRULAMAK, DAVRANIŞI DEĞİL
  -- YAZIM BİÇİMİNİ DOĞRULAMAKTIR."**
  --
  -- Artık ikisi de DAVRANIŞ ölçüyor: gerçekten öne çıkarıp listeye
  -- bakıyorum, ve iç sıralamanın bozulmadığını satır satır karşılaştırıyorum.
  begin
    declare
      v_dusuk uuid; v_ilk uuid; v_ham uuid[]; v_yeni uuid[];
    begin
      -- Ham sıra (öne çıkarmadan önce)
      select array_agg(id order by sira) into v_ham from (
        select id, row_number() over () as sira
          from public.discover_availabilities(null,null,null,null)) z;

      select id into v_dusuk from public.discover_availabilities(null,null,null,null)
       order by match_score asc limit 1;

      if v_dusuk is null then
        v_notlar := v_notlar || 'siralama OLCULMEDI (kesifte ilan yok)'::text;
      else
        perform public.motor_yazimi_ac();
        update availabilities set featured_until = now() + interval '24 hours' where id = v_dusuk;

        select id into v_ilk from public.discover_availabilities(null,null,null,null) limit 1;
        if v_ilk is distinct from v_dusuk then
          v_hatalar := v_hatalar ||
            'one cikarilan ilan listenin BASINA GELMEDI — siralama onarimi calismiyor'::text;
        end if;

        -- TERS YÖN: öne çıkarma listeden satır DÜŞÜRMEMELİ, EKLEMEMELİ.
        --
        -- 🔴 İLK YAZDIĞIMDA "kalanların sırası birebir aynı kalmalı"
        -- diyordum ve nöbetçi kırmızı yandı. Sebebini ölçtüm: iç
        -- sıralamada BERABERLİK BOZUCU YOK (48 ilanın match_score'u aynı:
        -- 54). Eşit puanlı satırların sırası her çağrıda değişebiliyor —
        -- yani onarımım değil, ALTTAKİ SIRALAMA kararsız.
        --
        -- Nöbetçiyi gevşetiyorum ama kusuru SUSTURMUYORUM: aşağıda
        -- ayrıca ölçülüp NOT olarak raporlanıyor.
        select array_agg(id order by sira) into v_yeni from (
          select id, row_number() over () as sira
            from public.discover_availabilities(null,null,null,null)
           where id <> v_dusuk) z;
        if (select count(*) from unnest(array_remove(v_ham, v_dusuk)) x
             where x <> all (coalesce(v_yeni, '{}'))) > 0
           or coalesce(array_length(v_yeni,1),0) <> coalesce(array_length(v_ham,1),1) - 1 then
          v_hatalar := v_hatalar ||
            'one cikarma listeden satir DUSURDU ya da EKLEDI — sarmalayici veri kaybettiriyor'::text;
        end if;
        v_notlar := v_notlar || 'siralama davranisla olculdu'::text;

        -- 🔴 AYRI BULGU: keşif sıralaması KARARSIZ mı? Aynı sorguyu iki
        -- kez çağırıp karşılaştırıyorum. Kararsızsa sayfalama bozulur:
        -- kullanıcı 2. sayfaya geçince 1. sayfadaki ilanı tekrar görür ya
        -- da hiç görmez. Bunu bu turda DÜZELTMİYORUM (iç gövde ayrı bir
        -- sözleşme) ama sessizce de geçmiyorum.
        declare v_a uuid[]; v_b uuid[];
        begin
          select array_agg(id order by sira) into v_a from (
            select id, row_number() over () as sira
              from public.discover_availabilities(null,null,null,null)) z;
          select array_agg(id order by sira) into v_b from (
            select id, row_number() over () as sira
              from public.discover_availabilities(null,null,null,null)) z;
          if v_a is distinct from v_b then
            -- 🔴 Once iki bitisik literal yazmistim; `sql_lint` hakli olarak
            -- yakaladi. Bitisik literal SQL'de tek dizeye birlesir ama
            -- cast'in nereye bagli oldugu okuyana belirsiz kalir.
            v_notlar := v_notlar || ('UYARI: kesif siralamasi KARARSIZ (ayni sorgu iki '
                     || 'farkli sira dondurdu). Beraberlik bozucu yok; sayfalama '
                     || 'guvenilmez. Ayri bir turda ele alinmali.')::text;
          end if;
        end;
      end if;
    end;
    raise exception 'GERI_AL_243_SIRA';
  exception when others then
    if sqlerrm <> 'GERI_AL_243_SIRA' then
      v_hatalar := v_hatalar || ('siralama olcumu coktu: ' || sqlerrm);
    end if;
  end;

  if array_length(v_hatalar,1) is not null then
    raise exception '243 NOBETCI: %', array_to_string(v_hatalar, ' | ');
  end if;
  raise notice '243 OK · one cikarma yaziliyor · motor cikitisi hala korumali · siralama featured i okuyor';
  -- Notlar HATA degil ama SESSIZ de kalmamali: olculemeyen ve
  -- olculup kusur bulunan seyler burada gorunur.
  if array_length(v_notlar,1) is not null then
    raise notice '243 NOTLAR · %', array_to_string(v_notlar, ' | ');
  end if;
end $n243$;

select '243 ONE CIKARMA CALISIYOR' as sonuc,
       (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
         where n.nspname='public' and p.prosrc ilike '%motor_yazimi_ac%'
           and p.proname <> 'motor_yazimi_ac')                                as bayrakli_fonksiyon,
       (select (prosrc ilike '%is_featured%')::int from pg_proc p
          join pg_namespace n on n.oid=p.pronamespace
         where n.nspname='public' and p.proname='discover_availabilities' limit 1) as siralama_duzeldi;

-- ----------------------------------------------------------------------
-- save_push_token   [etkin kaynak: 111_push_direct_expo.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.save_push_token(p_token text, p_platform text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if coalesce(p_token,'') not like 'ExponentPushToken%' then
    -- 🔴 Bicimi dogrula. Gecersiz token Expo tarafinda "DeviceNotRegistered"
    -- uretir ve tum toplu gonderiyi bozabilir.
    return jsonb_build_object('ok', false, 'reason', 'invalid_token_format');
  end if;

  insert into push_tokens (user_id, token, platform, active, updated_at)
  values (v_uid, p_token, p_platform, true, now())
  on conflict (token) do update
    set user_id = excluded.user_id,      -- cihaz el degistirmis olabilir
        platform = excluded.platform,
        active = true, updated_at = now();
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- notify_push   [etkin kaynak: 266_eksik_bildirimler.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.notify_push()
returns trigger language plpgsql security definer set search_path = public as $np266$
declare
  v_body  jsonb;
  v_quiet boolean := false;
  v_dil   text;
  v_baslik text;
  v_govde  text;
  v_req   bigint;
begin
  begin
    select coalesce(
             (n.prefs -> NEW.category::text ->> 'push')::boolean = false, false)
      into v_quiet
      from notification_prefs n where n.user_id = NEW.user_id;
  exception when undefined_table or undefined_column then
    v_quiet := false;
  end;
  if v_quiet then return NEW; end if;

  -- ALICININ dili. `aktif_dil()` DEĞİL: o, bildirimi YAZAN işlemin dili.
  begin
    select lower(coalesce(p.dil, 'tr')) into v_dil
      from profiles p where p.user_id = NEW.user_id;
  exception when others then v_dil := 'tr';
  end;

  v_baslik := coalesce(NEW.title, 'LoungeLink');
  v_govde  := coalesce(NEW.body, '');
  if coalesce(v_dil, 'tr') = 'en' then
    -- Karşılığı yoksa Türkçe kalır: çeviri eksikliği bildirimi düşürmez.
    v_baslik := coalesce((select en from push_ceviri where tr = v_baslik), v_baslik);
    v_govde  := coalesce((select en from push_ceviri where tr = v_govde),  v_govde);
  end if;

  select jsonb_agg(jsonb_build_object(
           'to', t.token,
           'title', v_baslik,
           'body', v_govde,
           'sound', 'default',
           'channelId', 'default',
           'priority', 'high',
           'data', jsonb_build_object(
                     'category', NEW.category,
                     'ref_type', NEW.ref_type,
                     'ref_id',   NEW.ref_id,
                     'notification_id', NEW.id)))
    into v_body
    from push_tokens t
   where t.user_id = NEW.user_id
     and coalesce(t.active, true)
     and coalesce(t.token,'') like 'ExponentPushToken%';

  if v_body is null then return NEW; end if;

  if to_regnamespace('net') is null then
    raise warning 'notify_push: pg_net kurulu degil, push atlandi (bildirim kaydi DURUYOR)';
    return NEW;
  end if;

  -- ══════════════════════════════════════════════════════════════════
  -- 🔴 GÖNDERİM DEFTERİ — VE BURADA KENDİ HATAMI DÜZELTİYORUM.
  --
  -- SQL 257 `notify_push`i METİN OLARAK YAMALIYORDU: `perform
  -- net.http_post(...)` çağrısını `select ... into v_req`e çevirip
  -- altına `push_gonderimleri` kaydı ekliyordu. Amaç Expo'nun MAKBUZUNU
  -- okuyabilmek: `DeviceNotRegistered` dönen token'ı pasife almak.
  --
  -- Bu dosyanın ilk hâli `notify_push`i SIFIRDAN yeniden yazdı ve
  -- 257'nin yamasını SESSİZCE GERİ ALDI. Ölçtüm ve doğruladım:
  --     select pg_get_functiondef(...) like '%push_gonderimleri%'  → f
  --
  -- Sonucu şu olurdu: silinmiş uygulamaların token'ları sonsuza kadar
  -- "aktif" kalır, her bildirimde onlara da gönderilir ve sağlık
  -- raporundaki "ULAŞILABİLEN kişi" sayısı zamanla YALAN SÖYLER.
  --
  -- 🆕 SINIF: "BİR FONKSİYONU YENİDEN YAZARKEN, ONA SONRADAN YAMA
  -- ATMIŞ DOSYALARI DA OKUMAK ZORUNDASIN — YAMA, KAYNAK DOSYADA
  -- GÖRÜNMEZ."
  --
  -- Ve kalıcı çözüm yamayı tekrar uygulamak DEĞİL, defteri buraya
  -- ASIL GÖVDEYE yazmak: metin yaması her yeniden yazımda tekrar
  -- düşecek bir bağımlılıktır.
  begin
    if to_regclass('public.push_gonderimleri') is not null then
      select net.http_post(
        url     := 'https://exp.host/--/api/v2/push/send',
        headers := jsonb_build_object('Content-Type', 'application/json',
                                      'Accept', 'application/json'),
        body    := v_body) into v_req;
      insert into push_gonderimleri (notification_id, user_id, net_request_id, token_sayisi)
      values (NEW.id, NEW.user_id, v_req, jsonb_array_length(v_body));
    else
      -- Defter yoksa (257 çalıştırılmamış) gönderim yine yapılır.
      perform net.http_post(
        url     := 'https://exp.host/--/api/v2/push/send',
        headers := jsonb_build_object('Content-Type', 'application/json',
                                      'Accept', 'application/json'),
        body    := v_body);
    end if;
  exception when others then
    raise warning 'notify_push: push gonderilemedi (% / %) — bildirim kaydi DURUYOR',
      sqlstate, sqlerrm;
  end;
  return NEW;
end $np266$;

-- ════════════════════════════════════════════════════════════════════════
-- §3 — PUANLAMA HATIRLATMASI
--
-- Oturum tamamlandı, 24 saat geçti, kimse puanlamadı. Güven puanı bu
-- ürünün tek güvenlik mekanizması; girdisi gelmezse sistem kördür.
-- Kişi başına TEK hatırlatma: ikincisi rahatsızlıktır.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- send_connection   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.send_connection(p_to uuid, p_intent text, p_intro text default null)
returns jsonb
language plpgsql security definer set search_path = public as $sc248$
declare v_uid uuid := auth.uid(); v_ok boolean; v_id uuid; v_eski connection_requests%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_to = v_uid then raise exception 'self_connect_blocked'; end if;

  v_ok := public.is_contact_verified(v_uid);
  if not v_ok then raise exception 'contact_not_verified'; end if;

  if public.is_blocked_pair(v_uid, p_to) then raise exception 'blocked_pair'; end if;

  if exists (select 1 from connection_requests
              where ((from_id=v_uid and to_id=p_to) or (from_id=p_to and to_id=v_uid))
                and status in ('pending','accepted')) then
    raise exception 'connection_exists';
  end if;

  select * into v_eski from connection_requests
   where from_id = v_uid and to_id = p_to;

  if found then
    -- Reddedilmis (ya da baska bir son durumda) eski satir. Tabloda
    -- UNIQUE(from_id,to_id) oldugu icin INSERT patlar; satiri yeniden
    -- isletiyoruz.
    if coalesce(v_eski.responded_at, v_eski.created_at) > now() - interval '7 days' then
      raise exception 'baglanti_soguma'
        using hint = 'Bu kisiye kisa sure once istek gonderdin ve yanit olumsuzdu. '
                  || 'Yeni istek icin 7 gun beklemen gerekiyor.';
    end if;
    update connection_requests
       set intent = coalesce(p_intent,'connect'),
           intro  = left(coalesce(p_intro,''),140),
           status = 'pending',
           created_at = now(),
           responded_at = null
     where id = v_eski.id
     returning id into v_id;
  else
    insert into connection_requests (from_id, to_id, intent, intro, status)
    values (v_uid, p_to, coalesce(p_intent,'connect'), left(coalesce(p_intro,''),140), 'pending')
    returning id into v_id;
  end if;

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (p_to, 'connections', 'Yeni bağlantı isteği ◈',
          'Bir yolcu seninle bağlantı kurmak istiyor.', 'connection', v_id);

  return jsonb_build_object('ok', true, 'id', v_id);
end $sc248$;

grant execute on function public.send_connection(uuid, text, text) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §4 — İLAN ÖZETİ (madde 8: "seyahat ekle" otomatik dolmuyor)
--
-- Gokberk: "baglantilar sayfasindan seyahat ekle dedigimde ilgili bilgiler
-- otomatik dolmuyor. Bunu kesfet ekranindaki seyahat ekle butonlari icin
-- yapmistik. Burada da uygulanmali."
--
-- Kok neden APP tarafinda (App.js `onAddTrip={() => setShowAddVisit(true)}`
-- — parametre HIC gecilmiyor) ama sunucu tarafinda da bir boslugu var:
-- `discover_people` ilanin ID'sini veriyor, TARIH ve SAATINI vermiyor.
-- AddVisit'in doldurmasi gereken alanlar tam olarak bunlar.
--
-- `discover_people`'in donus tipini degistirmek yerine (o fonksiyon 20
-- kolonlu ve dort ekran okuyor) tek amacli kucuk bir fonksiyon yaziyorum.
-- Bir sozlesmeyi genisletmek, tasimayan bir sozlesmeyi bozmaktan ucuzdur.

-- ----------------------------------------------------------------------
-- respond_connection   [etkin kaynak: 159_grants_home_flows_request_gate.sql]
-- ⚠ Bu fonksiyon 5 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.respond_connection(p_id uuid, p_accept boolean)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_cr connection_requests%rowtype; v_chan uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_cr from connection_requests where id = p_id for update;
  if not found then raise exception 'connection_not_found'; end if;
  if v_cr.to_id <> v_uid then raise exception 'not_recipient'; end if;
  if v_cr.status <> 'pending' then raise exception 'already_responded'; end if;

  -- v159: yanıt ZAMANI artık kayıtlı — ana sayfadaki 24 saat kuralı buna dayanır.
  update connection_requests
     set status = (case when p_accept then 'accepted' else 'declined' end)::connection_status,
         responded_at = now()
   where id = p_id;

  if p_accept then
    insert into chat_channels (connection_id, kind, created_at)
    values (p_id, 'companion', now())
    on conflict (connection_id) where connection_id is not null do nothing
    returning id into v_chan;
    if v_chan is null then select id into v_chan from chat_channels where connection_id = p_id; end if;

    -- YENİ (077-3): "Bağlan" ekranında yazılan tanıtım sohbetin ilk mesajı
    if v_chan is not null and coalesce(nullif(trim(v_cr.intro),''),'') <> '' then
      insert into messages (channel_id, from_id, body, created_at)
      select v_chan, v_cr.from_id, trim(v_cr.intro), now()
       where not exists (select 1 from messages m where m.channel_id = v_chan);
    end if;

    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_cr.from_id, 'connections', 'Bağlantı kabul edildi ✓', 'Sohbet açıldı.', 'connection', p_id);
  else
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_cr.from_id, 'connections', 'Bağlantı yanıtlandı', 'İstek reddedildi.', 'connection', p_id);
  end if;

  return jsonb_build_object('ok', true, 'channel_id', v_chan);
end $function$;

-- ---- 4) home_connections(): ana sayfa bağlantı kartının TEK kaynağı ----
-- 🔴 Kural (Gökberk, madde 2): kabulden sonra 24 SAAT ana sayfada;
-- aktif sohbet varsa (son 24 saatte mesaj) sohbet sürdükçe kalır;
-- ikisi de yoksa düşer — Tanış > Bağlantılar'da her zaman durur.
-- RPC olması bilinçli: grant/RLS bağımsız tek çağrı + kural sunucuda
-- (istemcide saat hesabı = her istemcide ayrı davranış).
drop function if exists public.home_connections();

-- ----------------------------------------------------------------------
-- discover_people   [etkin kaynak: 070_discover_people_trip_data.sql]
-- ⚠ Bu fonksiyon 7 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.discover_people(p_airport text DEFAULT NULL::text, p_date date DEFAULT NULL::date)
 RETURNS TABLE(user_id uuid, name text, profession text, bio text, badge text, score integer, rel text, photo text, purpose text, same_purpose boolean, airport text, is_hosting boolean, host_avail_id uuid, host_slots_left integer, host_airport text, can_request boolean, req_reason text,
  visit_date date, flight_number text, same_flight boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_female boolean; v_safe boolean;
  v_phone_ok boolean;
begin
  select (u.gender='female'), coalesce(pr.women_safety_mode,false)
    into v_female, v_safe from users u left join profiles pr on pr.user_id=u.id where u.id=v_uid;

  select coalesce(bool_or(v.phone_verified), false) into v_phone_ok
    from verifications v where v.user_id = v_uid;

  return query
  with
  -- Karşı tarafın en yakın aktif+açık-slotlu ilanı (İstek butonu bilgisi)
  hosting as (
    select distinct on (a.host_id)
           a.host_id, a.id as avail_id, a.airport_code::text as ap,
           a.avail_date, a.time_from, a.time_to,
           greatest(0, a.slots - coalesce(a.filled,0)) as slots_left
      from availabilities a
     where a.active = true
       and a.avail_date >= current_date
       and a.visibility <> 'Hidden'
       and coalesce(a.min_trust,0) = 0
       and greatest(0, a.slots - coalesce(a.filled,0)) > 0
       and (p_airport is null or a.airport_code = p_airport)
       and (p_date is null or a.avail_date = p_date)
     order by a.host_id, a.avail_date, a.time_from
  ),
  -- Karşı tarafın en yakın seyahati — MVP kartında "✈ IST · 15 Haziran" ve
  -- "AYNI UÇUŞ · TK712" bunun üzerinden gösterilir. ESKİ SÜRÜMDE YOKTU:
  -- airport yalnız hosting CTE'sinden geliyordu, dolayısıyla ilanı olmayan
  -- misafirlerde tüm bu alanlar BOŞ kalıyordu (Canlı APP 3).
  trip as (
    select distinct on (v.user_id)
           v.user_id, v.airport_code::text as ap, v.visit_date,
           v.flight_number, v.purpose
      from visits v
     where v.visit_date >= current_date
       and (p_airport is null or v.airport_code = p_airport)
       and (p_date is null or v.visit_date = p_date)
     order by v.user_id, v.visit_date, v.time_from
  ),
  -- Benim seyahatlerim — İstek kapısı için (aynı yer/tarih/±1s örtüşme)
  mine as (
    select v.airport_code::text as ap, v.visit_date, v.time_from, v.time_to,
           v.flight_number, v.purpose
      from visits v
     where v.user_id = v_uid and v.visit_date >= current_date
  )
  select p.user_id, p.name, p.profession, p.bio, ts.badge, ts.score,
         coalesce(cr.status::text, 'none') as rel,
         case when p.photo_url is not null and (
                coalesce(p.photo_connections_only,false) = false
                or coalesce(cr.status::text,'') = 'accepted'
              ) then p.photo_url else null end as photo,
         tr.purpose,
         (tr.purpose is not null and exists (
            select 1 from mine m where m.purpose = tr.purpose)) as same_purpose,
         coalesce(tr.ap, ho.ap) as airport,
         (ho.host_id is not null) as is_hosting,
         ho.avail_id as host_avail_id,
         ho.slots_left as host_slots_left,
         ho.ap as host_airport,
         -- can_request: üç şart birden
         (ho.host_id is not null
          and v_phone_ok
          and exists (
            select 1 from mine m
             where m.ap = ho.ap
               and m.visit_date = ho.avail_date
               -- saat penceresi ±1 saat (ilan from-1s .. to+1s ile örtüşme)
               and m.time_from < (ho.time_to + interval '1 hour')
               and (ho.time_from - interval '1 hour') < m.time_to
          )) as can_request,
         -- req_reason: neden pasif (öncelik: ilan yok > telefon > seyahat)
         case
           when ho.host_id is null then 'noslot'
           when not v_phone_ok then 'phone'
           when not exists (
             select 1 from mine m
              where m.ap = ho.ap and m.visit_date = ho.avail_date
                and m.time_from < (ho.time_to + interval '1 hour')
                and (ho.time_from - interval '1 hour') < m.time_to
           ) then 'trip'
           else null
         end as req_reason,
         tr.visit_date,
         tr.flight_number,
         -- AYNI UÇUŞ: benim uçuş numaramla eşleşiyor mu
         (tr.flight_number is not null and exists (
            select 1 from mine m
             where m.flight_number is not null
               and upper(m.flight_number) = upper(tr.flight_number))) as same_flight
    from profiles p
    join users hu on hu.id = p.user_id
    left join trust_scores ts on ts.user_id = p.user_id
    left join connection_requests cr on
      (cr.from_id = v_uid and cr.to_id = p.user_id) or (cr.from_id = p.user_id and cr.to_id = v_uid)
    left join hosting ho on ho.host_id = p.user_id
    left join trip tr on tr.user_id = p.user_id
   where p.user_id <> v_uid
     and coalesce(p.show_on_discovery, true) = true
     and public.is_visible(p.user_id)
     -- KADIN GÜVENLİK — 049 kuralı AYNEN korunur:
     and (not (v_female and v_safe) or hu.gender = 'female')
     and (not coalesce(p.women_safety_mode,false)
          or (v_female and v_phone_ok)
          or exists (select 1 from connection_requests c9 where c9.from_id = p.user_id and c9.to_id = v_uid)
          or exists (select 1 from requests r9 join availabilities a9 on a9.id = r9.avail_id
                     where r9.guest_id = p.user_id and a9.host_id = v_uid)
          or exists (select 1 from invites i9 where i9.host_id = p.user_id and i9.guest_id = v_uid))
   order by (ho.host_id is not null) desc,          -- ilanı olanlar üstte
            ts.score desc nulls last
   limit 100;
end $function$;


grant execute on function public.discover_people(text, date) to authenticated;

select '070 OK - discover_people artik seyahat bilgisi donduruyor (havalimani/tarih/ucus/ayni-ucus)' as sonuc;

-- ----------------------------------------------------------------------
-- redeem_reward   [etkin kaynak: 229_odul_teslim_sozu.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.redeem_reward(p_reward_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $rr$
declare
  v_uid  uuid := auth.uid();
  v_r    rewards%rowtype;
  v_pts  int;
  v_ref  text;
  v_due  timestamptz;
  v_id   uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_r from rewards where id = p_reward_id for update;
  if not found or not coalesce(v_r.active,false) then raise exception 'reward_unavailable'; end if;
  if v_r.stock is not null and v_r.stock <= 0 then raise exception 'out_of_stock'; end if;

  -- 🔴 Teslim sözü olmayan ödül SATILMAZ. Kısıt zaten engelliyor ama
  -- eski bir satır kısıttan önce girmişse burada da duruyoruz:
  -- "iki kapı" bilerek — biri veriye, biri akışa.
  if v_r.teslim_sekli is null or v_r.teslim_saat is null or v_r.supplier is null then
    raise exception 'reward_fulfillment_undefined';
  end if;

  select coalesce(sum(delta),0) into v_pts from points_ledger where user_id = v_uid;
  if v_pts < v_r.cost_points then raise exception 'insufficient_points'; end if;

  -- 🔴 ARTIK "KUPON" DEĞİL, "TALEP NUMARASI".
  -- Eski kod LL-XXXXXX üretiyordu ve ekranda kupon gibi duruyordu.
  -- Bu numara bir TAKİP numarası: kullanıcı bununla bize sorar, biz
  -- bununla kuyrukta buluruz. Kimse onu tedarikçiye yazmaya kalkmaz.
  v_ref := 'TAL-' || to_char(now(), 'YYMMDD') || '-' || upper(substr(md5(random()::text), 1, 5));
  v_due := now() + make_interval(hours => v_r.teslim_saat);

  insert into redemptions (user_id, reward_id, cost_points, voucher_code, durum, due_at)
  values (v_uid, p_reward_id, v_r.cost_points, v_ref, 'bekliyor', v_due)
  returning id into v_id;

  insert into points_ledger (user_id, delta, reason, ref_id)
  values (v_uid, -v_r.cost_points, 'reward_redeem', p_reward_id);

  if v_r.stock is not null then
    update rewards set stock = stock - 1 where id = p_reward_id;
  end if;

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_uid, 'system', 'Talebin alındı ✦',
          v_r.title || ' · takip no ' || v_ref || E'\n'
       || v_r.supplier || ' tarafından hazırlanıyor. En geç '
       || to_char(v_due, 'DD.MM HH24:MI') || ' itibarıyla hesabındaki e-posta adresine gelecek. '
       || 'Gelmezse bu takip numarasıyla bize yaz — puanın iade edilir.',
          'reward', v_id);

  return jsonb_build_object(
    'ok', true,
    'takip_no', v_ref,
    'durum', 'bekliyor',
    'teslim_sekli', v_r.teslim_sekli,
    'son_tarih', v_due,
    'tedarikci', v_r.supplier,
    'bakiye', v_pts - v_r.cost_points,
    -- Eski alan adları geriye dönük bırakılıyor: app'in eski sürümü
    -- `code`/`voucher` okuyorsa ekran boş kalmasın. Ama içerik artık
    -- takip numarası ve bildirim metni ne olduğunu söylüyor.
    'code', v_ref,
    'voucher', v_ref
  );
end $rr$;
grant execute on function public.redeem_reward(uuid) to authenticated;

