-- ----------------------------------------------------------------------
-- change_plan   [etkin kaynak: 018_subscriptions.sql]
-- ----------------------------------------------------------------------
create or replace function public.change_plan(p_plan plan_type)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_current plan_type;
  v_new_credits int; v_old_credits int; v_diff int; v_bal int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select plan into v_current from users where id = v_uid;
  if v_current = p_plan then raise exception 'already_on_plan'; end if;

  select monthly_credits into v_new_credits from plan_catalog where plan = p_plan;
  select monthly_credits into v_old_credits from plan_catalog where plan = v_current;

  -- users.plan güncelle
  update users set plan = p_plan where id = v_uid;

  -- subscriptions kaydı (demo — stripe alanları boş)
  insert into subscriptions (user_id, plan, status, renews_at)
  values (v_uid, p_plan, 'active', now() + interval '30 days')
  on conflict (user_id) do update set plan = p_plan, status = 'active',
    renews_at = now() + interval '30 days', cancelled_at = null;

  -- Yükseltmede kredi farkını hemen ver (demo davranışı)
  v_diff := v_new_credits - v_old_credits;
  if v_diff > 0 then
    select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
    insert into credit_ledger (user_id, delta, reason, balance_after)
    values (v_uid, v_diff, 'plan_upgrade', v_bal + v_diff);
  end if;

  insert into notifications (user_id, category, title, body, ref_type)
  values (v_uid, 'system', 'Plan güncellendi 🎉',
    'Yeni planın: ' || p_plan || (case when v_diff>0 then ' · +'||v_diff||' kredi' else '' end), 'plan');

  return jsonb_build_object('ok', true, 'plan', p_plan, 'credits_added', greatest(v_diff,0));
end $$;

-- ----------------------------------------------------------------------
-- admin_adjust_credit   [etkin kaynak: 019_admin_management.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_adjust_credit(p_user uuid, p_delta int, p_reason text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_bal int;
begin
  -- Bu RPC yalnız service role veya admin tarafından çağrılır (backoffice).
  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = p_user;
  insert into credit_ledger (user_id, delta, reason, balance_after)
  values (p_user, p_delta, coalesce(p_reason,'admin_adjust'), v_bal + p_delta);
  return jsonb_build_object('ok', true, 'new_balance', v_bal + p_delta);
end $$;

-- ----------------------------------------------------------------------
-- admin_adjust_points   [etkin kaynak: 019_admin_management.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_adjust_points(p_user uuid, p_delta int, p_reason text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  insert into points_ledger (user_id, delta, reason)
  values (p_user, p_delta, coalesce(p_reason,'admin_adjust'));
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- admin_has_permission   [etkin kaynak: 020_rbac.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_has_permission(p_user uuid, p_module text)
returns boolean language sql security definer set search_path = public as $$
  select exists (
    select 1 from admin_roles
     where user_id = p_user
       and (role = 'super_admin' or permissions ? p_module)
  );
$$;

-- ----------------------------------------------------------------------
-- upsert_admin   [etkin kaynak: 035_password_flow.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.upsert_admin(
  p_email text, p_role text, p_permissions jsonb, p_display_name text default null,
  p_must_change boolean default false
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid;
begin
  select id into v_uid from auth.users where email = lower(p_email);
  if v_uid is null then raise exception 'user_not_found'; end if;

  insert into admin_roles (user_id, role, permissions, display_name, must_change_password)
  values (v_uid, p_role::text, coalesce(p_permissions,'[]'::jsonb), p_display_name, p_must_change)
  on conflict (user_id) do update set
    role = excluded.role, permissions = excluded.permissions,
    display_name = coalesce(excluded.display_name, admin_roles.display_name),
    must_change_password = excluded.must_change_password;
  return jsonb_build_object('ok', true, 'user_id', v_uid);
end $$;

-- ----------------------------------------------------------------------
-- remove_admin   [etkin kaynak: 020_rbac.sql]
-- ----------------------------------------------------------------------
create or replace function public.remove_admin(p_user uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  delete from admin_roles where user_id = p_user;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- resolve_report   [etkin kaynak: 021_moderation_tools.sql]
-- ----------------------------------------------------------------------
create or replace function public.resolve_report(p_report_id uuid, p_status text, p_resolution text, p_resolver uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  update reports set status = p_status::report_status, resolution = p_resolution,
    resolved_by = p_resolver, updated_at = now()
  where id = p_report_id;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- remove_rating   [etkin kaynak: 297_yetki_kapilari.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.remove_rating(p_rating_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_uid uuid := auth.uid();
  v_r   ratings%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_r from ratings where id = p_rating_id;
  if not found then
    -- Var olmayan kimlikle var olanı ayırt ETTİRMİYORUZ: aksi hâlde bu
    -- fonksiyon "şu puan var mı?" sorusuna cevap veren bir tarayıcıya
    -- dönüşür.
    return jsonb_build_object('ok', true, 'silinen', 0);
  end if;

  -- Yalnız PUANI VEREN silebilir. Yönetici yolu backoffice'te ayrı
  -- (`admin_*` yüzeyi, service_role) — buraya karıştırmıyorum.
  if v_r.rater_id <> v_uid then
    raise exception 'baskasinin_verisi'
      using hint = 'Yalniz kendi yazdigin degerlendirmeyi kaldirabilirsin.';
  end if;

  delete from ratings where id = p_rating_id;

  insert into audit_log (actor_id, action, entity_type, entity_id, before_data)
  values (v_uid, 'rating.remove', 'ratings', p_rating_id,
          jsonb_build_object('rated_id', v_r.rated_id, 'score', v_r.score));

  return jsonb_build_object('ok', true, 'silinen', 1);
end $function$;

grant execute on function public.remove_rating(uuid) to authenticated;

-- ══ D · flow_test_cleanup — İSTEMCİYE KAPALI ════════════════════════════
-- 🔴 ÖLÇÜLDÜ: `security definer`, yetki kontrolü yok, `exception when
-- others then null` ile hatayı yutuyor ve sırayla messages → chat_channels
-- → ratings → sessions → requests siliyor. Herhangi bir kullanıcı,
-- BAŞKASININ aktif oturumunu ve değerlendirmesini kalıcı olarak
-- silebiliyordu (yerelde yeniden ürettim: requests 6→4, sessions 5→3).
-- Adı "test" diyor; grant'ı "üretim" diyordu.
-- 🆕 SINIF: "ADINDA 'TEST' GEÇEN BİR FONKSİYON ÜRETİM VERİTABANINDA
-- DURUYORSA, ADI DEĞİL GRANT'I BAĞLAYICIDIR."
do $$
declare r record;
begin
  for r in select p.oid::regprocedure::text as imza
             from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
            where ns.nspname='public' and p.proname='flow_test_cleanup'
  loop
    execute format('revoke execute on function %s from authenticated, anon', r.imza);
    raise notice '297/D: % istemciye kapatildi', r.imza;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- admin_set_trust   [etkin kaynak: 021_moderation_tools.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_set_trust(p_user uuid, p_score int, p_badge text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  update trust_scores set score = greatest(0, least(100, p_score)),
    badge = coalesce(p_badge, badge), updated_at = now()
  where user_id = p_user;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- partner_demand   [etkin kaynak: 209_saglayici_modulu.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function partner_demand(p_lounge_id uuid,
-- p_user uuid default null)` yazmak, VAR OLAN tek argümanlı
-- `partner_demand(uuid)` fonksiyonunu DEĞİŞTİRMEZ — farklı arite,
-- yeni bir fonksiyon demektir. İkisi yan yana durunca tek argümanla
-- yapılan her çağrı belirsizleşir ve 42725 döner.
--
-- Bu hatayı 207'de `partner_demand` için yaptım, burada `partner_payout`
-- için tekrarlayacaktım. Üstelik `partner_payout`'un dönüş TİPİ de
-- değişiyor (TABLE → jsonb), yani `create or replace` zaten
-- çalışmazdı; eskisi öylece kalıp yanlış şekil döndürmeye devam
-- ederdi.
--
-- YENİ HATA SINIFI (20.): VARSAYILAN PARAMETRE EKLEMEK, İMZAYI
-- DEĞİŞTİRMEZ — YENİ BİR FONKSİYON YARATIR. Eskisi açıkça
-- düşürülmeli.
drop function if exists public.partner_demand(uuid);
drop function if exists public.partner_payout(uuid, date, date);


-- ============================================================
-- 1) AYARLAR — sayılar koda gömülü kalmasın
-- ============================================================
-- 🔴 k-ANONİMİTE EŞİĞİ NEDEN AYAR OLMALI: bugün 5 kodda sabit ve
-- YALNIZ host sayısına uygulanıyor. Ekran ise "en az 5 farklı
-- kullanıcı" diyor. Beyan ile kod ayrışmış durumda — bir KVKK
-- tartışmasında savunması en zor hâl budur. Tek yerden okunacak.
insert into beta_settings (key, value) values
  ('partner_k_threshold', to_jsonb(5)),
  ('partner_commission_pct', to_jsonb(15))
on conflict (key) do nothing;

-- ----------------------------------------------------------------------
-- assign_partner   [etkin kaynak: 023_partner_portal.sql]
-- ----------------------------------------------------------------------
create or replace function public.assign_partner(p_email text, p_lounge_id uuid, p_role text default 'viewer')
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid;
begin
  select id into v_uid from auth.users where email = lower(p_email);
  if v_uid is null then raise exception 'user_not_found'; end if;
  insert into lounge_partners (user_id, lounge_id, role)
  values (v_uid, p_lounge_id, p_role)
  on conflict (user_id, lounge_id) do update set role = excluded.role;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- grant_consents   [etkin kaynak: 026_doc_parity_core.sql]
-- ----------------------------------------------------------------------
create or replace function public.grant_consents(p_types text[], p_version text default 'v15')
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); t text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  foreach t in array p_types loop
    insert into consents (user_id, type, version, granted_at)
    values (v_uid, t, p_version, now())
    on conflict do nothing;
  end loop;
  return jsonb_build_object('ok', true, 'count', array_length(p_types,1));
end $$;

-- ----------------------------------------------------------------------
-- publish_availability   [etkin kaynak: 026_doc_parity_core.sql]
-- ----------------------------------------------------------------------
create or replace function public.publish_availability(
  p_airport text, p_lounge_id uuid, p_lounge_name text, p_date date,
  p_from time, p_to time, p_slots int, p_flight text default null,
  p_visibility text default 'Public'
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_ok boolean; v_cap int; v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- §6: telefon doğrulaması zorunlu
  select phone_verified into v_ok from verifications where user_id = v_uid;
  if not coalesce(v_ok,false) then raise exception 'phone_not_verified'; end if;

  -- §4: slot limiti beyan edilen kapasiteyi aşamaz
  select guest_capacity into v_cap from profiles where user_id = v_uid;
  if v_cap is null then raise exception 'no_access_declared'; end if;
  if p_slots > v_cap then raise exception 'slots_exceed_capacity'; end if;
  if p_to <= p_from then raise exception 'invalid_time_range'; end if;

  insert into availabilities (host_id, airport_code, lounge_id, lounge_name, avail_date,
                              time_from, time_to, slots, filled, flight_number, visibility, active)
  values (v_uid, p_airport, p_lounge_id, p_lounge_name, p_date, p_from, p_to, p_slots, 0,
          nullif(p_flight,''), p_visibility, true)
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id);
end $$;

-- ----------------------------------------------------------------------
-- change_phone   [etkin kaynak: 078_trust_single_writer.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.change_phone(p_phone text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  update users set phone = p_phone where id = v_uid;
  update verifications set phone_verified = false, phone_verified_at = null where user_id = v_uid;
  perform public.recompute_trust(v_uid);   -- 078: elle -10 yerine kanonik hesap
  return jsonb_build_object('ok', true, 'reverify_required', true);
end $$;

-- ----------------------------------------------------------------------
-- my_connections   [etkin kaynak: 027_companion_chat.sql]
-- ----------------------------------------------------------------------
create or replace function public.my_connections()
returns table (conn_id uuid, other_id uuid, other_name text, other_photo text,
               status text, channel_id uuid, intent text)
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  return query
  select cr.id,
         case when cr.from_id = v_uid then cr.to_id else cr.from_id end,
         p.name,
         case when p.photo_url is not null and (
                coalesce(p.photo_connections_only,false)=false or cr.status='accepted'
              ) then p.photo_url else null end,
         cr.status::text, c.id, cr.intent
    from connection_requests cr
    join profiles p on p.user_id = (case when cr.from_id = v_uid then cr.to_id else cr.from_id end)
    left join chat_channels c on c.connection_id = cr.id
   where cr.from_id = v_uid or cr.to_id = v_uid
   order by cr.created_at desc;
end $$;

-- ----------------------------------------------------------------------
-- my_referral   [etkin kaynak: 028_referral.sql]
-- ----------------------------------------------------------------------
create or replace function public.my_referral()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_code text; v_invited jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select referral_code into v_code from profiles where user_id = v_uid;
  if v_code is null then
    loop
      v_code := 'LL' || upper(substr(md5(random()::text), 1, 6));
      begin
        update profiles set referral_code = v_code where user_id = v_uid;
        exit;
      exception when unique_violation then null;
      end;
    end loop;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('name', p.name)), '[]'::jsonb)
    into v_invited from profiles p where p.referred_by = v_uid;

  return jsonb_build_object('code', v_code, 'invited', v_invited);
end $$;

-- ----------------------------------------------------------------------
-- apply_referral   [etkin kaynak: 028_referral.sql]
-- ----------------------------------------------------------------------
create or replace function public.apply_referral(p_code text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_ref uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if exists (select 1 from profiles where user_id = v_uid and referred_by is not null) then
    raise exception 'referral_already_used';
  end if;
  select user_id into v_ref from profiles where upper(referral_code) = upper(p_code);
  if v_ref is null then raise exception 'invalid_referral_code'; end if;
  if v_ref = v_uid then raise exception 'self_referral_blocked'; end if;

  update profiles set referred_by = v_ref where user_id = v_uid;
  insert into invites (host_id, guest_id, status, created_at)
  values (v_ref, v_uid, 'accepted', now()) on conflict do nothing;

  insert into points_ledger (user_id, delta, reason) values (v_ref, 500, 'referral_invite');
  insert into points_ledger (user_id, delta, reason) values (v_uid, 500, 'referral_joined');

  insert into notifications (user_id, category, title, body, ref_type)
  values (v_ref, 'system', 'Davetin kabul edildi 🎉', 'Arkadaşın katıldı · +500 puan', 'referral');

  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- open_dispute   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.open_dispute(p_session uuid, p_reason text, p_detail text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_s sessions%rowtype; v_r requests%rowtype; v_saat int; v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);
  if coalesce(p_reason,'') not in ('gelmedi','kapida_ret','ucret','davranis','kredi','diger') then
    raise exception 'dispute_reason_invalid';
  end if;
  select * into v_s from sessions where id = p_session;
  if not found then raise exception 'session_not_found'; end if;
  select * into v_r from requests where id = v_s.request_id;
  if v_r.guest_id <> v_uid and v_r.host_id <> v_uid then raise exception 'not_participant'; end if;
  v_saat := coalesce((select (value #>> '{}')::int from beta_settings where key = 'kapida_ret_saat'), 24) * 3;
  if coalesce(v_s.completed_at, v_s.started_at) < now() - make_interval(hours => v_saat) then
    raise exception 'dispute_window_closed';
  end if;
  if exists (select 1 from disputes where session_id = p_session and status = 'open') then
    raise exception 'dispute_already_open';
  end if;
  insert into disputes (session_id, request_id, opener_id, reason, detail)
  values (p_session, v_s.request_id, v_uid, p_reason, left(nullif(btrim(coalesce(p_detail,'')),''), 600))
  returning id into v_id;
  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_uid, 'system', 'Bildirimin alındı', 'Ekibimiz 48 saat içinde inceleyip sana yazacak.', 'session', p_session);
  return jsonb_build_object('ok', true, 'id', v_id, 'sla_saat', 48);
end $$;

-- ----------------------------------------------------------------------
-- resolve_dispute   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resolve_dispute(p_dispute uuid, p_decision text, p_admin uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_d disputes%rowtype; v_r requests%rowtype; v_bal int;
begin
  select * into v_d from disputes where id = p_dispute for update;
  if not found then raise exception 'dispute_not_found'; end if;
  if v_d.status <> 'open' then raise exception 'already_decided'; end if;
  select * into v_r from requests where id = v_d.request_id;

  if p_decision = 'refund' then
    perform public.istek_kredisi_iade(v_r.id, 'dispute_refund', p_dispute);   -- 284/9: idempotent, tutulan kadar
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_r.guest_id, 'system', 'İtirazın sonuçlandı', 'Kredin iade edildi.', 'dispute', p_dispute);
  elsif p_decision = 'partial' then
    -- kısmi: puan telafisi (kredi iade yok)
    insert into points_ledger (user_id, delta, reason) values (v_r.guest_id, 250, 'dispute_partial');
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_r.guest_id, 'system', 'İtirazın sonuçlandı', 'Kısmi telafi uygulandı.', 'dispute', p_dispute);
  else -- capture: kredi host lehine kapanır, iade yok
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_d.opener_id, 'system', 'İtirazın sonuçlandı', 'İtiraz reddedildi.', 'dispute', p_dispute);
  end if;

  update disputes set status = case when p_decision='capture' then 'rejected' else 'resolved' end,
    decision = p_decision, decided_by = p_admin, decided_at = now() where id = p_dispute;
  return jsonb_build_object('ok', true, 'decision', p_decision);
end $function$;

do $$
begin
  if pg_get_functiondef('public.resolve_dispute'::regproc) not like '%istek_kredisi_iade%' then raise exception '284: resolve_dispute yamali degil'; end if;
  raise notice '284/9 NOBETCI OK: dispute iadesi tek kapidan';
end $$;

-- ----------------------------------------------------------------------
-- flag_enabled   [etkin kaynak: 029_bo_requirements.sql]
-- ----------------------------------------------------------------------
create or replace function public.flag_enabled(p_key text)
returns boolean language sql security definer set search_path = public as $$
  select coalesce((
    select f.enabled and (
      f.rollout_pct >= 100 or
      (abs(hashtext(coalesce(auth.uid()::text,'anon'))) % 100) < f.rollout_pct
    ) from feature_flags f where f.key = p_key
  ), false);
$$;

-- ----------------------------------------------------------------------
-- send_campaign   [etkin kaynak: 047_campaign_targets.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.send_campaign(
  p_title text, p_body text, p_segment jsonb, p_admin uuid,
  p_user_ids uuid[] default null
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_cid uuid; v_n int := 0;
begin
  insert into notification_campaigns (title, body, segment, created_by)
  values (p_title, p_body, coalesce(p_segment,'{}'::jsonb), p_admin) returning id into v_cid;

  if p_user_ids is not null and array_length(p_user_ids, 1) > 0 then
    -- KİŞİ BAZLI: seçilen kullanıcılar (silinmiş ve staff hariç)
    with target as (
      select u.id from users u
      where u.id = any(p_user_ids)
        and u.deleted_at is null
        and coalesce(u.is_staff, false) = false
    ), ins as (
      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      select id, 'system'::notif_category, p_title, p_body, 'campaign', v_cid from target
      returning 1
    )
    select count(*) into v_n from ins;
  else
    -- SEGMENT BAZLI: 029 gövdesi + staff filtresi
    with target as (
      select u.id from users u
      left join profiles p on p.user_id = u.id
      left join trust_scores ts on ts.user_id = u.id
      where u.deleted_at is null
        and coalesce(u.is_staff, false) = false
        and (p_segment->>'role' is null or u.role::text = p_segment->>'role')
        and (p_segment->>'plan' is null or u.plan::text = p_segment->>'plan')
        and (p_segment->>'min_trust' is null or coalesce(ts.score,0) >= (p_segment->>'min_trust')::int)
        and (p_segment->>'airport' is null or exists (
              select 1 from visits v where v.user_id = u.id and v.airport_code = p_segment->>'airport'
            ))
    ), ins as (
      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      select id, 'system'::notif_category, p_title, p_body, 'campaign', v_cid from target
      returning 1
    )
    select count(*) into v_n from ins;
  end if;

  update notification_campaigns set sent_count = v_n where id = v_cid;
  return jsonb_build_object('ok', true, 'sent', v_n, 'campaign_id', v_cid);
end $$;

-- ----------------------------------------------------------------------
-- partner_payout   [etkin kaynak: 209_saglayici_modulu.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.partner_payout(
  p_lounge_id uuid, p_from date, p_to date, p_user uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid uuid;
  v_k   int := public.partner_k();
  v_satis int; v_ciro numeric; v_kisi int; v_akis boolean;
  v_kom int := coalesce((select (value #>> '{}')::int from beta_settings where key='partner_commission_pct'), 15);
begin
  v_uid := public.partner_gate(p_user, p_lounge_id);

  select coalesce(sum(o.sold),0),
         coalesce(sum(o.sold * o.price_try),0),
         count(distinct o.id)
    into v_satis, v_ciro, v_kisi
    from lounge_offers o
   where o.lounge_id = p_lounge_id
     and o.offer_date between p_from and p_to
     and o.status = 'approved';

  -- Satış akışı hiç yazılmadıysa bunu SÖYLE.
  v_akis := exists (select 1 from lounge_offers where coalesce(sold,0) > 0);

  return jsonb_build_object(
    'from', p_from, 'to', p_to,
    'satis', v_satis,
    'ciro_try', v_ciro,
    'komisyon_yuzde', v_kom,
    'komisyon_try', round(v_ciro * v_kom / 100.0),
    'net_try', round(v_ciro * (100 - v_kom) / 100.0),
    'satis_akisi_var', v_akis,
    -- k-eşiği: az sayıda satış tek bir kişiyi saat aralığıyla ifşa
    -- edebilir. Eşik altındaysa TUTAR gösterilmez.
    'k_esigi', v_k,
    'k_altinda', v_satis > 0 and v_satis < v_k,
    'not', case
      when not v_akis then 'Satın alma akışı henüz açılmadı; bu sayı yapısal olarak 0. Ekranda "veri yok" olarak gösterilmeli.'
      when v_satis > 0 and v_satis < v_k then format('Bu dönemde %s satış var; %s eşiğinin altında olduğu için tutar gizlendi.', v_satis, v_k)
      end);
end $fn$;


-- ============================================================
-- 4) Ö1 · KAPI RAPORU — işletmecinin başka yerden alamayacağı veri
-- ============================================================
-- 🔴 EN DEĞERLİ EKRAN VE SEBEBİ ŞU: bir işletmeci, kapıdan GERİ
-- ÇEVİRDİĞİ kişinin hangi programla geldiğini bilmiyor — kendi kapı
-- kaydında o kişi hiç yok. Bizde `outcome = 'refused'` diye bir
-- satır var. Bu, banka/program sözleşmesi pazarlığının verisi.
--
-- ⚠️ k-eşiği HER SATIRA uygulanıyor, yalnız toplama değil. Beş
-- kişiden az veri taşıyan bir program satırı, o beş kişiyi
-- tanımlanabilir kılar.

-- ----------------------------------------------------------------------
-- apply_rule_engine   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.apply_rule_engine(p_user uuid)
returns jsonb
language plpgsql security definer set search_path = public as $are250$
declare
  v_reports int; v_agir int; v_ns int;
  v_thr int; v_ns_thr int; v_days int; v_agir_thr int;
  v_acted text := 'none'; v_sebep text;
begin
  select value into v_thr      from rule_thresholds where key = 'report_threshold';
  select value into v_ns_thr   from rule_thresholds where key = 'no_show_limit';
  select value into v_days     from rule_thresholds where key = 'restrict_days';
  select value into v_agir_thr from rule_thresholds where key = 'agir_sikayet_esigi';

  select count(*) into v_reports from reports where target_id = p_user and status = 'open';

  -- AĞIR TÜRLER — burada sayı değil, VARLIK önemli.
  select count(*) into v_agir from reports
   where target_id = p_user and status = 'open'
     and type in ('harassment','fraud','off_platform_payment');

  select count(*) into v_ns from sessions
   where no_show_user_id = p_user and cancel_reason = 'no_show'
     and completed_at > now() - interval '90 days';

  if v_agir >= coalesce(v_agir_thr, 1) then
    -- SÜRESİZ: tarih koymak "şu gün serbest" sözü vermek olurdu. İnsan
    -- bakacak. `restricted_until`i null bırakmıyoruz çünkü kodun başka
    -- yerlerinde null "kısıt yok" demek — uzak bir tarih, açık bir bayrak.
    update users set shadow_limited = true,
           restricted_until = now() + interval '100 years',
           kisit_inceleme_bekliyor = true,
           kisit_sebebi = format('%s acik agir sikayet — insan incelemesi bekleniyor', v_agir)
     where id = p_user;
    update reports set is_urgent = true
     where target_id = p_user and status = 'open'
       and type in ('harassment','fraud','off_platform_payment');
    v_acted := 'agir_sikayet';
    v_sebep := 'insan_incelemesi';

  elsif v_reports >= coalesce(v_thr, 3) or v_ns >= coalesce(v_ns_thr, 2) then
    update users set shadow_limited = true,
      restricted_until = greatest(coalesce(restricted_until, now()), now())
                         + make_interval(days => coalesce(v_days, 7)),
      kisit_sebebi = case when v_reports >= coalesce(v_thr,3)
                          then format('%s acik sikayet', v_reports)
                          else format('%s no-show (90 gun)', v_ns) end
    where id = p_user;
    v_acted := case when v_reports >= coalesce(v_thr,3) then 'sikayet' else 'no_show' end;
    v_sebep := 'otomatik_sure';
  end if;

  return jsonb_build_object('ok', true, 'action', v_acted, 'sebep', v_sebep,
                            'acik_sikayet', v_reports, 'agir_sikayet', v_agir,
                            'no_show_90g', v_ns);
end $are250$;

-- ---- İFTİRA KORUMASI: şikâyet reddedilirse süresiz kısıt KALKAR ----
-- 🔴 Bu olmadan yeni kural bir silaha dönüşürdü: tek bir asılsız
-- "taciz" şikâyeti bir kullanıcıyı kalıcı olarak susturabilirdi.

-- ----------------------------------------------------------------------
-- is_visible   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.is_visible(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- 301/§3: test hesapları gerçek kullanıcıya görünmez (BO flag: test_hesaplarini_gizle)
  select not public.test_hesabi_gizli_mi(p_user) and not coalesce((select shadow_limited and (restricted_until is null or restricted_until > now())
                       from users where id = p_user), false)
     and (not coalesce((select is_staff from users where id = p_user), false) or coalesce((select x.is_staff from users x where x.id = auth.uid()), false));   -- YENİ (041)
$function$;

-- ──────────────────────────────────────────────────────────────────────
-- §3c · havalimani_nabzi (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.havalimani_nabzi(p_gun integer DEFAULT 14)
 RETURNS TABLE(airport_code text, sehir text, canli_ilan integer, acik_slot integer, host_sayisi integer, bekleyen_istek integer, talep_kaydi integer, aktif_seyahat integer, tamamlanan_oturum integer, doluluk numeric, karsilanma numeric, durum text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_son date := current_date + greatest(1, coalesce(p_gun,14));
begin
  return query
  with arz as (
    select a.airport_code::text as ap,
           count(*)::int                                   as ilan,
           coalesce(sum(greatest(0, a.slots - coalesce(a.filled,0))),0)::int as slot,
           coalesce(sum(a.slots),0)::int                    as toplam_slot,
           coalesce(sum(coalesce(a.filled,0)),0)::int       as dolu,
           count(distinct a.host_id)::int                   as hostlar
      from availabilities a
     where a.active and a.avail_date between current_date and v_son
       and a.visibility <> 'Hidden'
       and not public.test_hesabi_gizli_mi(a.host_id)   -- 301/§3
     group by a.airport_code
  ), talep as (
    select a.airport_code::text as ap, count(*)::int as bekleyen
      from requests r join availabilities a on a.id = r.avail_id
     where r.status = 'pending' and a.avail_date between current_date and v_son
     group by a.airport_code
  ), haber as (
    select t.airport_code::text as ap, count(*)::int as kayit
      from talep_kayitlari t
     where t.aktif and t.tarih_bit >= current_date and t.tarih_bas <= v_son
     group by t.airport_code
  ), seyahat as (
    select v.airport_code::text as ap, count(*)::int as gezi
      from visits v
     where v.visit_date between current_date and v_son
       and not public.test_hesabi_gizli_mi(v.user_id)   -- 301/§3
     group by v.airport_code
  ), oturum as (
    select a.airport_code::text as ap, count(*)::int as bitmis
      from sessions s join requests r on r.id = s.request_id
      join availabilities a on a.id = r.avail_id
     where s.status = 'completed'
     group by a.airport_code
  )
  select ap.code::text,
         coalesce(ap.city, ap.name),
         coalesce(arz.ilan,0), coalesce(arz.slot,0), coalesce(arz.hostlar,0),
         coalesce(talep.bekleyen,0), coalesce(haber.kayit,0), coalesce(seyahat.gezi,0),
         coalesce(oturum.bitmis,0),
         case when coalesce(arz.toplam_slot,0) = 0 then null
              else round(arz.dolu::numeric / arz.toplam_slot, 2) end,
         -- 🔴 SIFIRA BÖLME DEĞİL, ANLAMSIZ ORAN KORUMASI:
         -- talep yoksa "karşılanma" diye bir şey yoktur; 0 yazmak
         -- "hiç karşılamıyoruz" gibi okunurdu. null = ölçülemedi.
         case when (coalesce(talep.bekleyen,0) + coalesce(haber.kayit,0)) = 0 then null
              else round(coalesce(arz.slot,0)::numeric
                         / (coalesce(talep.bekleyen,0) + coalesce(haber.kayit,0)), 2) end,
         case when coalesce(arz.hostlar,0) = 0 then 'soguk'
              when coalesce(arz.hostlar,0) < 3 then 'isiniyor'
              else 'canli' end
    from airports ap
    left join arz     on arz.ap     = ap.code::text
    left join talep   on talep.ap   = ap.code::text
    left join haber   on haber.ap   = ap.code::text
    left join seyahat on seyahat.ap = ap.code::text
    left join oturum  on oturum.ap  = ap.code::text
   where coalesce(arz.ilan,0) > 0 or coalesce(talep.bekleyen,0) > 0
      or coalesce(haber.kayit,0) > 0 or coalesce(seyahat.gezi,0) > 0
   order by coalesce(arz.hostlar,0) desc, coalesce(haber.kayit,0) desc, ap.code;
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §5 · create_availability (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.create_availability(p_lounge_id uuid, p_airport text, p_date date, p_from time without time zone, p_to time without time zone, p_slots integer, p_flight text DEFAULT NULL::text, p_visibility text DEFAULT 'all'::text, p_carrier text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb; v_id uuid;
  v_pg uuid; v_kaynak text; v_kod text; v_ad text;
begin
  -- ══════════════════════════════════════════════════════════════════
  -- 🔴 261 — ROL KAPISI. ILAN ACMAK ARTIK KIMSEYI SESSIZCE HOST YAPMAZ.
  --
  -- Kapi EN USTTE: `_base` cagrilmadan once. Boylece `_base` icindeki
  -- 055 terfisi (`update users set role='host'`) ULASILAMAZ hale
  -- geliyor — buraya gelen zaten host.
  --
  -- Host olmanin TEK yolu artik acik niyet: `rolumu_sec('host')`
  -- (uygulamadaki "Host ol" dugmesi) ya da onaylanmis host basvurusu.
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from users u where u.id = auth.uid() and u.role = 'host')
     and not exists (select 1 from host_applications ha
                      where ha.user_id = auth.uid() and ha.status = 'approved')
  then
    raise exception 'not_a_host';
  end if;
  -- 🔴 301/§5: KENDİ İLANIYLA ÇAKIŞAN İLAN açılabiliyordu (tam akış testi,
  -- 10–13 varken 12–15 GEÇTİ). `update_availability` bunu 'kendi_ilanlarin_
  -- cakisiyor' ile zaten reddediyordu — açma yolu reddetmiyordu. Aynı kişi
  -- aynı saatte iki salonda olamaz; ikinci ilana kabul edilen misafir kapıda kalır.
  if exists (select 1 from availabilities a
              where a.host_id = auth.uid() and a.active
                and a.avail_date = p_date
                and a.time_from < p_to and p_from < a.time_to) then
    raise exception 'kendi_ilanlarin_cakisiyor'
      using hint = 'Bu saatte başka bir ilanın var. Önce onu kaldır ya da saatleri ayır.';
  end if;
  -- ══════════════════════════════════════════════════════════════════

  -- Butun kapilar, kotalar, bildirimler _base zincirinde.
  -- Buraya tek bir is kaldi: SONUCU ANLATMAK.
  v := public.create_availability_base(
         p_lounge_id, p_airport, p_date, p_from, p_to, p_slots,
         p_flight, p_visibility, p_carrier);

  v_id := nullif(v ->> 'id', '')::uuid;
  if v_id is null then
    return v;   -- _base bir sey dondurmediyse uydurmuyoruz
  end if;

  select a.program_id, a.program_source, p.code, p.name
    into v_pg, v_kaynak, v_kod, v_ad
    from availabilities a
    left join lounge_programs p on p.id = a.program_id
   where a.id = v_id;

  return v || jsonb_build_object(
    'program_id',     v_pg,
    'program_kodu',   v_kod,
    'program_adi',    v_ad,
    'program_kaynagi', coalesce(v_kaynak, 'bilinmiyor'),
    'program_notu', case
      when v_pg is null then
        'Bu ilan bir kart programına bağlanamadı: hak beyanınız bu salonun kabul listesiyle eşleşmiyor. İlan yayında; yalnız sağlayıcı raporunda "program bilinmeyen" sayılacak.'
      when coalesce(v_kaynak, '') = 'turetildi' then
        format('Bu ilan "%s" programı altında sayılacak. Bu bir ÇIKARIM: doğrulanmış hak beyanınızdan türetildi, sizin beyanınız değil.', coalesce(v_ad, v_kod))
      else
        format('Bu ilan "%s" programı altında sayılacak (beyan).', coalesce(v_ad, v_kod))
      end);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §8 · seyahat_sil (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.seyahat_sil(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_sahip uuid;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select user_id into v_sahip from visits where id = p_id;
  if v_sahip is null then raise exception 'visit_not_found'; end if;
  if v_sahip <> v_uid then raise exception 'not_your_visit'; end if;
  -- 240'ın sözleşme kilidi: bu seyahate dayanan aktif başvuru varsa silinmez.
  -- 🔴 301/§8: fonksiyon SAYI döndürüyor; `if <sayı> then` 0/1 için
  -- tesadüfen çalışıyor ('0'/'1' geçerli boolean metni), 2+ açık başvuruda
  -- "invalid input syntax for type boolean: "2"" ile patlıyordu (tam akış testi).
  if public.seyahate_bagli_basvuru(p_id) > 0 then
    raise exception 'seyahat_silinemez_basvuru_var';
  end if;
  delete from visits where id = p_id;
  return jsonb_build_object('ok', true);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §9 · blok_gecmisi_kapat (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.blok_gecmisi_kapat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- 🔴 301/§9: 204'ten beri bekleyen istek KAPANIYOR ama tutulan kredi
  -- İADE EDİLMİYORDU (tam akış testi: defterde yalnız `request_hold:-1`).
  -- Engelleme uygulamadan yapılamadığı için bu hiç görünmemişti; 301 §1
  -- engellemeyi açınca canlı hataya dönüşecekti. Artık her kapanan istek
  -- iade yolundan geçiyor (tekrar iadeyi `istek_kredisi_iade` kendisi önler).
  declare v_r record;
  begin
    for v_r in
      update requests set status = 'cancelled', responded_at = now()
       where status = 'pending'
         and ((guest_id = new.blocker and host_id = new.blocked)
           or (guest_id = new.blocked and host_id = new.blocker))
      returning id
    loop
      perform public.istek_kredisi_iade(v_r.id, 'request_refund');
    end loop;
  end;

  -- ⚠️ `connection_status` = pending | accepted | declined | blocked.
  -- İlk yazışımda 'rejected' yazdım — enum'da YOK, 22P02 aldım. Enum'un
  -- kendisinde zaten 'blocked' var ve burada 'declined'dan DAHA DOĞRU:
  -- kullanıcı reddetmedi, engelledi. Sebep kayıtta kalsın.
  update connection_requests set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((from_id = new.blocker and to_id = new.blocked)
       or (from_id = new.blocked and to_id = new.blocker));

  update invites set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((host_id = new.blocker and guest_id = new.blocked)
       or (host_id = new.blocked and guest_id = new.blocker));

  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ
-- ════════════════════════════════════════════════════════════════════════
do $z301$
declare v_n int; v_l text;
begin
  select count(*), string_agg(p.proname, ', ') into v_n, v_l
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('engelle','engeli_kaldir','engellediklerim','gelmedi_bildir','gelmedi_esigi')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '301 §Z: authenticated çağıramıyor: %', v_l; end if;
  select count(*) into v_n from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '301 §Z: PUBLIC''e açık % fonksiyon (300 §A2 geriledi)', v_n; end if;
  if position('test_hesabi_gizli_mi' in (select prosrc from pg_proc where proname = 'is_visible')) = 0 then
    raise exception '301 §Z: is_visible yamasız';
  end if;
  if not exists (select 1 from pg_trigger where tgname = 'trg_mesaj_engel') then
    raise exception '301 §Z: mesaj engel tetikleyicisi yok';
  end if;
  raise notice '301 §Z: kapılar ölçüldü';
end $z301$;

select '301 OK — engelleme · gelmedi · test hesabı gizleme · rehber sayacı' as sonuc;

-- ----------------------------------------------------------------------
-- set_featured   [etkin kaynak: 225_planin_sozu_tutulsun.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.set_featured(p_avail_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); v_pts int; v_host uuid;
  v_plan_hak int; v_kul_ay int; v_ay_bas timestamptz;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select host_id into v_host from availabilities where id = p_avail_id;
  if v_host is null then raise exception 'availability_not_found'; end if;
  if v_host <> v_uid then raise exception 'not_owner'; end if;

  v_ay_bas := (date_trunc('month', timezone('Europe/Istanbul', now()))
                 at time zone 'Europe/Istanbul');

  select coalesce(p.one_cikarma_ayda, 0) into v_plan_hak
    from users u left join plan_catalog p on p.plan = u.plan and p.aktif
   where u.id = v_uid;
  v_plan_hak := coalesce(v_plan_hak, 0);

  select count(*) into v_kul_ay from points_ledger
   where user_id = v_uid and reason = 'plan_feature' and created_at >= v_ay_bas;

  if coalesce(v_kul_ay,0) < v_plan_hak then
    -- 225: planın aylık ücretsiz öne çıkarma hakkı. Puan HARCANMAZ;
    -- deftere 0 delta ile iz düşülür ki sayılabilsin.
    insert into points_ledger (user_id, delta, reason, ref_id)
    values (v_uid, 0, 'plan_feature', p_avail_id);
  else
    select coalesce(sum(delta),0) into v_pts from points_ledger where user_id = v_uid;
    if v_pts < 200 then
      raise exception 'insufficient_points'
        using detail = format('%s/200 puan', v_pts),
              hint   = 'eksik=' || (200 - v_pts)::text;
    end if;
    insert into points_ledger (user_id, delta, reason, ref_id)
    values (v_uid, -200, 'feature_listing', p_avail_id);
  end if;

  update availabilities
     set featured_until = now() + interval '24 hours'
   where id = p_avail_id;

  return jsonb_build_object('ok', true,
    'kaynak', case when coalesce(v_kul_ay,0) < v_plan_hak then 'plan' else 'puan' end,
    'plan_hakki_kalan', greatest(0, v_plan_hak - coalesce(v_kul_ay,0) - 1));
end $$;

-- ----------------------------------------------------------------------
-- invitable_guests   [etkin kaynak: 075_invitable_guests_detail.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.invitable_guests(p_avail_id uuid)
RETURNS TABLE (guest_id uuid, name text, photo text, last_seen date, invite_status text,
               profession text, sessions_count integer)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  return query
  select distinct r.guest_id, p.name,
         case when p.photo_url is not null and coalesce(p.photo_connections_only,false)=false
              then p.photo_url else null end,
         max(a.avail_date) over (partition by r.guest_id),
         coalesce((select i.status::text from invites i
                    where i.guest_id = r.guest_id and i.avail_id = p_avail_id limit 1), 'none'),
         p.profession,
         -- misafirin tamamlanmış oturum sayısı (MVP: "· 6 oturum")
         (select count(*)::int from sessions s
           join requests r2 on r2.id = s.request_id
          where s.status = 'completed' and r2.guest_id = r.guest_id)
    from requests r
    join availabilities a on a.id = r.avail_id
    join profiles p on p.user_id = r.guest_id
   where a.host_id = v_uid and r.status in ('accepted','completed');
end $$;

-- ----------------------------------------------------------------------
-- send_invite   [etkin kaynak: 079_email_otp_contact_verification.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.send_invite(p_guest uuid, p_avail_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_ok boolean; v_id uuid; v_av availabilities%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  -- 079: KAPI ARTIK "DOĞRULANMIŞ İLETİŞİM" (telefon VEYA e-posta).
  -- SMS maliyetli olduğu için beta boyunca e-posta doğrulaması yeterli;
  -- demo bypass (kod 0000) kaldırıldı.
  v_ok := public.is_contact_verified(v_uid);
  if not v_ok then raise exception 'contact_not_verified'; end if;

  select * into v_av from availabilities where id = p_avail_id;
  if v_av.host_id <> v_uid then raise exception 'not_owner'; end if;
  if v_av.filled >= v_av.slots then raise exception 'fully_booked'; end if;

  -- soğuk davet yasak: geçmiş misafir olmalı
  if not exists (
    select 1 from requests r join availabilities a on a.id = r.avail_id
     where a.host_id = v_uid and r.guest_id = p_guest and r.status in ('accepted','completed')
  ) then raise exception 'cold_invite_blocked'; end if;

  insert into invites (host_id, guest_id, avail_id, note, status)
  values (v_uid, p_guest, p_avail_id, left(coalesce(p_note,''),140), 'pending')
  returning id into v_id;

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (p_guest, 'requests', 'Lounge daveti ✦',
          coalesce(v_av.lounge_name, v_av.airport_code) || ' · ' || left(coalesce(p_note,''),80), 'invite', v_id);

  return jsonb_build_object('ok', true, 'id', v_id);
end $function$;

grant execute on function public.create_request(uuid, text, text, text) to authenticated;
grant execute on function public.create_availability(uuid, text, date, time, time, integer, text, text) to authenticated;
grant execute on function public.send_invite(uuid, uuid, text) to authenticated;
grant execute on function public.send_connection(uuid, text, text) to authenticated;


-- ============================================================
-- DOĞRULAMA
-- ============================================================
-- (1) true dönmeli: kapılar artık iletişim doğrulamasına bakıyor
select bool_and(prosrc ilike '%is_contact_verified%') as "kapilar_guncel"
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public'
   and p.proname in ('create_request','create_availability','send_invite','send_connection');

-- (2) false dönmeli: demo bypass kapalı
select (value)::text = 'true' as "demo_bypass_hala_acik" from beta_settings where key='otp_demo_bypass';

-- (3) true dönmeli: e-posta doğrulama fonksiyonu var
select exists (select 1 from pg_proc where proname='verify_email_contact') as "email_dogrulama_var";

select '079 OK - dogrulama kapisi telefon VEYA e-posta, demo bypass kapatildi' as sonuc;

-- ----------------------------------------------------------------------
-- respond_invite   [etkin kaynak: 293_davet_cift_onay_ve_ilan_geri_cekme.sql]
-- ⚠ Bu fonksiyon 5 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.respond_invite(p_id uuid, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_i invites%rowtype; v_req uuid; v_chan uuid;
  v_bal int; v_sess uuid; v_av availabilities%rowtype;
  v_mevcut requests%rowtype;
  v_yeni boolean := false;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);   -- 282/B1: yasaklı/silinmiş hesap yazamaz

  select * into v_i from invites where id = p_id for update;
  if not found then raise exception 'invite_not_found'; end if;
  if v_i.guest_id <> v_uid then raise exception 'not_recipient'; end if;
  if v_i.status <> 'pending' then raise exception 'already_responded'; end if;

  update invites set status = (case when p_accept then 'accepted' else 'declined' end)::connection_status,
         responded_at = now()
   where id = p_id;

  if p_accept then
    -- ── 289: AYNI İLANA ZATEN AKTİF BİR İSTEK VAR MI? ─────────────────
    select * into v_mevcut from requests
     where guest_id = v_uid and avail_id = v_i.avail_id
       and status in ('pending','accepted')
     order by created_at desc limit 1
     for update;

    if found and v_mevcut.status = 'accepted' then
      -- Zaten kabul edilmiş: davet fazlalık. Yeni satır da yeni kredi de yok.
      v_req := v_mevcut.id;
    else
      -- Kapasite kontrolü her iki yolda da geçerli (030'dan beri).
      select * into v_av from availabilities where id = v_i.avail_id for update;
      if not found then raise exception 'availability_not_found'; end if;
      if coalesce(v_av.filled,0) >= v_av.slots then raise exception 'fully_booked'; end if;

      if v_mevcut.id is not null then
        -- PENDING istek var → davet onu kabule yükseltir. Kredi zaten emanette.
        update requests set status = 'accepted', responded_at = now(),
               type = 'direct_invite'
         where id = v_mevcut.id;
        v_req := v_mevcut.id;
      else
        -- Hiç istek yok → eskisi gibi: kredi al, satırı aç.
        select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
        if v_bal < 1 then raise exception 'insufficient_credits'; end if;

        insert into requests (guest_id, host_id, avail_id, status, type, intro_message, match_score)
        values (v_uid, v_i.host_id, v_i.avail_id, 'accepted', 'direct_invite', v_i.note, 60)
        returning id into v_req;
        v_yeni := true;

        insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
        values (v_uid, -1, 'invite_hold', v_req, v_bal - 1);
      end if;
    end if;

    insert into chat_channels (request_id, kind) values (v_req, 'lounge')
      on conflict (request_id) do nothing;
    select id into v_chan from chat_channels where request_id = v_req;

    -- Davet notu ilk mesaj (gönderen: HOST — daveti o yazdı)
    if v_chan is not null and coalesce(nullif(trim(v_i.note),''),'') <> '' then
      insert into messages (channel_id, from_id, body, created_at)
      select v_chan, v_i.host_id, trim(v_i.note), now()
       where not exists (select 1 from messages m where m.channel_id = v_chan);
    end if;

    -- Oturum: zaten varsa YENİSİ AÇILMAZ (davet iki kez oturum başlatamaz).
    select id into v_sess from sessions where request_id = v_req and status in ('pending','active') limit 1;
    if v_sess is null then
      -- 🔴 13 EYLÜL — BURASI 'active', now() YAZIYORDU.
      -- Yani davet kabul edilir edilmez oturum BAŞLAMIŞ sayılıyordu:
      -- buluşmadan günler önce, iki taraf da "Oturumu Başlat"a
      -- basmadan. İstek yolu (SQL 080 · v1.75) ÇİFT ONAY istiyor;
      -- davet yolu o kuralı tamamen atlıyordu. Aynı üründe aynı
      -- buluşmanın iki farklı başlama kuralı vardı.
      insert into sessions (request_id, status)
      values (v_req, 'pending') returning id into v_sess;
    end if;

    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_i.host_id, 'requests', 'Davetin kabul edildi ✓', 'Sohbet açıldı, oturum başladı.', 'request', v_req);
  else
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_i.host_id, 'requests', 'Davetin yanıtlandı', 'Davet reddedildi.', 'invite', p_id);
  end if;

  return jsonb_build_object('ok', true, 'request_id', v_req, 'channel_id', v_chan,
                            'session_id', v_sess, 'yeni_istek', v_yeni);
end $function$;

-- ── cancel_availability(uuid, boolean) ───────────────────
CREATE OR REPLACE FUNCTION public.cancel_availability(p_id uuid, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_accepted int; v_pending int; v_iptal int := 0;
  r record;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);
  if not exists (select 1 from availabilities where id = p_id and host_id = v_uid) then
    raise exception 'not_your_availability';
  end if;

  -- Oturum başladıysa hiçbir yoldan geri çekilemez.
  -- 🔴 13 EYLÜL — BU KAPI ÇOK GENİŞTİ VE 291'İN KENDİ AMACINI
  -- ÇÜRÜTÜYORDU. `pending` bir oturum "başlamış" demek DEĞİL: SQL 080'de
  -- oturum satırı kabulde oluşur, gerçekten `active` olması için İKİ
  -- TARAFIN DA "Oturumu Başlat"a basması gerekir.
  -- ÖLÇÜM: `respond_invite` her kabulde bir oturum satırı yaratıyor
  -- (293 öncesi doğrudan 'active'). Sonuç: daveti kabul edilmiş bir
  -- ilanı host ZORLA BİLE geri çekemiyordu — yani Gökberk'in 13 Eylül
  -- madde 2'de istediği şeyin tam tersi oluyordu.
  -- Doğru kapı: buluşma GERÇEKTEN başlamışsa geri çekilemez.
  --   · status = 'active'                        → başladı
  --   · 'pending' ama bir taraf "geldim" dediyse  → biri kapıda bekliyor
  -- İkisi de yoksa zorlu kaldırma çalışır ve o boş oturum satırı da
  -- kapatılır (yetim satır bırakmak, temizlik değil sızıntıdır — 291'in
  -- kendi sınıfı).
  if exists (
    select 1 from sessions s join requests q on q.id = s.request_id
     where q.avail_id = p_id
       and (s.status = 'active'
            or (s.status = 'pending'
                and (s.host_started_at is not null or s.guest_started_at is not null)))
  ) then raise exception 'session_started'; end if;

  select count(*) filter (where status = 'accepted'),
         count(*) filter (where status = 'pending')
    into v_accepted, v_pending
    from requests where avail_id = p_id;

  if v_accepted > 0 and not p_force then
    raise exception 'has_accepted_requests';
  end if;

  if p_force then
    -- Açık her isteği REDDET: kredi iadesi + bildirim, `respond_request`
    -- ile AYNI yoldan (iade mantığı tek yerde kalsın).
    for r in select id, guest_id from requests
              where avail_id = p_id and status in ('pending','accepted')
              for update
    loop
      update requests set status = 'declined', responded_at = now() where id = r.id;
      perform public.istek_kredisi_iade(r.id, 'request_refund');
      insert into notifications (user_id, category, title, body, ref_id, ref_type)
      values (r.guest_id, 'requests', 'İlan geri çekildi',
              'Host bu ilanı kaldırdı. Kredin anında iade edildi; başka bir ilana başvurabilirsin.',
              r.id, 'request');
      v_iptal := v_iptal + 1;
    end loop;
  else
    -- Zorlamasız yolda BİLE bekleyen istekler serbest bırakılır:
    -- ilan kapanınca o istek zaten cevaplanamaz hâle geliyordu.
    for r in select id, guest_id from requests
              where avail_id = p_id and status = 'pending' for update
    loop
      update requests set status = 'declined', responded_at = now() where id = r.id;
      perform public.istek_kredisi_iade(r.id, 'request_refund');
      insert into notifications (user_id, category, title, body, ref_id, ref_type)
      values (r.guest_id, 'requests', 'İlan geri çekildi',
              'Host bu ilanı kaldırdı. Kredin anında iade edildi; başka bir ilana başvurabilirsin.',
              r.id, 'request');
      v_iptal := v_iptal + 1;
    end loop;
  end if;

  -- Bekleyen davetler de kapanır.
  -- 'cancelled' bu enum'da YOK (pending|accepted|declined|blocked) — davet geri
  -- çekilince 'declined' doğru karşılık: davet edilen kişi bir şey yapmadı.
  update invites set status = 'declined'::connection_status, responded_at = now()
   where avail_id = p_id and status = 'pending';

  -- Hiç başlamamış ('pending' ve iki taraf da basmamış) oturum satırları
  -- ilanla birlikte kapanır; yoksa `expire_stale_sessions` onları
  -- no-show sanıp kullanıcının güvenini düşürürdü.
  update sessions s set status = 'cancelled', completed_at = now(),
         cancel_reason = coalesce(s.cancel_reason, 'ilan_geri_cekildi')
    from requests q
   where q.id = s.request_id and q.avail_id = p_id
     and s.status = 'pending'
     and s.host_started_at is null and s.guest_started_at is null;

  -- Hiç başlamamış ('pending' ve iki taraf da basmamış) oturum satırları
  -- ilanla birlikte kapanır; yoksa `expire_stale_sessions` onları
  -- no-show sanıp kullanıcının güvenini düşürürdü.
  update sessions s set status = 'cancelled', completed_at = now(),
         cancel_reason = coalesce(s.cancel_reason, 'ilan_geri_cekildi')
    from requests q
   where q.id = s.request_id and q.avail_id = p_id
     and s.status = 'pending'
     and s.host_started_at is null and s.guest_started_at is null;

  update availabilities set active = false, updated_at = now() where id = p_id;
  return jsonb_build_object('ok', true, 'iptal_edilen', v_iptal,
                            'bekleyen', v_pending, 'kabul_edilen', v_accepted);
end $function$;

-- ── 3 · AŞIRI YÜKLEME BELİRSİZLİĞİ — 291'İN SESSİZ REGRESYONU ─────────
-- 🔴 ÖLÇÜM: 291, `cancel_availability(p_id uuid, p_force boolean default
-- false)` ekledi ama ESKİ `cancel_availability(p_id uuid)` yerinde kaldı.
-- İkisi bir arada, tek argümanlı her çağrıyı BELİRSİZ yapıyor:
--     ERROR: function public.cancel_availability(uuid) is not unique
-- Yani "geriye dönük uyumluluk için eskisini bıraktım" diye yazdığım
-- satır, tam da korumak istediğim eski çağrıyı KIRIYORDU. (Uygulama bu
-- turda `p_force: true` gönderdiği için fark edilmiyordu; NOT3 kanıtı
-- zorlamasız yolu sınayınca çıktı.)
--
-- 🆕 SINIF: "VARSAYILAN DEĞERLİ BİR AŞIRI YÜKLEME, ESKİ İMZAYI KORUMAZ —
-- ONU BELİRSİZ YAPAR. GERİYE DÖNÜK UYUM AŞIRI YÜKLEMEYLE DEĞİL
-- VARSAYILANLA SAĞLANIR."
--
-- Tek fonksiyon kalıyor: `(p_id uuid, p_force boolean default false)`.
-- `cancel_availability(p_id => ...)` ve `cancel_availability(av)` yine
-- çalışır, davranış eskisiyle aynıdır (zorlamasız).
drop function if exists public.cancel_availability(uuid);
grant execute on function public.cancel_availability(uuid, boolean) to authenticated;

-- ── KENDİ SINAMASI ─────────────────────────────────────────────────────
do $$
declare
  hd uuid; g uuid; lng uuid; av uuid; inv_id uuid; rq uuid;
  v_st text; sonuc jsonb; v_ses uuid; v_n int;
begin
  select id into hd from users where role = 'host' and deleted_at is null limit 1;
  select id into lng from lounges where airport_code = 'IST' limit 1;
  if hd is null or lng is null then raise notice '293 sinama: veri yok, atlandi'; return; end if;
  select id into g from users where id <> hd and deleted_at is null limit 1;
  if g is null then raise notice '293 sinama: misafir yok, atlandi'; return; end if;

  insert into availabilities (host_id, airport_code, lounge_id, avail_date, time_from, time_to, slots, active)
    values (hd, 'IST', lng, public.yerel_gun('IST') + 5, time '10:00', time '13:00', 2, true)
    returning id into av;
  insert into credit_ledger (user_id, delta, reason, balance_after)
    values (g, 3, 'sinama_293', coalesce((select sum(delta) from credit_ledger where user_id = g), 0) + 3);

  -- 1) Davet kabulü oturumu 'pending' doğurmalı, 'active' DEĞİL
  insert into invites (host_id, guest_id, avail_id, status, note)
    values (hd, g, av, 'pending', '293 sinama') returning id into inv_id;
  perform set_config('request.jwt.claims',
    json_build_object('sub', g::text, 'role', 'authenticated')::text, true);
  perform public.respond_invite(inv_id, true);
  select s.id, s.status::text into v_ses, v_st
    from sessions s join requests q on q.id = s.request_id
   where q.avail_id = av limit 1;
  if v_ses is null then raise exception '293: davet kabulunde oturum satiri olusmadi'; end if;
  if v_st <> 'pending' then
    raise exception '293: davet kabulu oturumu % yapti (pending bekleniyordu)', v_st;
  end if;
  raise notice '293 sinama 1 ✓ davet kabulu → oturum ''pending'' (cift onay korunuyor)';

  -- 2) Host, daveti kabul edilmiş ilanı ZORLA geri çekebilmeli
  perform set_config('request.jwt.claims',
    json_build_object('sub', hd::text, 'role', 'authenticated')::text, true);
  sonuc := public.cancel_availability(av, true);
  if (sonuc ->> 'ok') is distinct from 'true' then
    raise exception '293: zorlu kaldirma hala dusuyor';
  end if;
  if (select active from availabilities where id = av) then
    raise exception '293: ilan pasife dusmedi';
  end if;
  select status::text into v_st from sessions where id = v_ses;
  if v_st <> 'cancelled' then
    raise exception '293: baslamamis oturum satiri yetim kaldi (%)', v_st;
  end if;
  raise notice '293 sinama 2 ✓ davet kabul edilmis ilan ZORLA geri cekildi · oturum %', v_st;

  -- 3) GERÇEKTEN başlamış buluşma hâlâ korunmalı
  insert into availabilities (host_id, airport_code, lounge_id, avail_date, time_from, time_to, slots, active)
    values (hd, 'IST', lng, public.yerel_gun('IST') + 6, time '10:00', time '13:00', 2, true)
    returning id into av;
  insert into requests (guest_id, host_id, avail_id, status) values (g, hd, av, 'accepted') returning id into rq;
  insert into sessions (request_id, status, started_at) values (rq, 'active', now());
  begin
    perform public.cancel_availability(av, true);
    raise exception '293: BASLAMIS oturumda kaldirma engellenmedi';
  exception when others then
    if SQLERRM <> 'session_started' then raise; end if;
    raise notice '293 sinama 3 ✓ gercekten baslamis bulusma korunuyor (session_started)';
  end;

  raise exception 'GERI_AL_SINAMA';
exception
  when others then
    if SQLERRM <> 'GERI_AL_SINAMA' then raise; end if;
    raise notice '293 sinama: tum veri geri alindi';
end $$;

-- ----------------------------------------------------------------------
-- pending_actions   [etkin kaynak: 030_match_and_broadcast.sql]
-- ----------------------------------------------------------------------
create or replace function public.pending_actions()
returns table (kind text, id uuid, title text, subtitle text, note text, from_name text, from_photo text)
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  return query
  -- gelen lounge davetleri
  select 'invite'::text, i.id,
         coalesce(a.lounge_name, a.airport_code),
         a.airport_code || ' · ' || a.avail_date::text,
         i.note, p.name,
         case when p.photo_url is not null and coalesce(p.photo_connections_only,false)=false then p.photo_url else null end
    from invites i
    join availabilities a on a.id = i.avail_id
    join profiles p on p.user_id = i.host_id
   where i.guest_id = v_uid and i.status = 'pending'
  union all
  -- gelen bağlantı istekleri
  select 'connection'::text, cr.id, p.name, coalesce(cr.intent,'connect'), cr.intro, p.name,
         case when p.photo_url is not null and coalesce(p.photo_connections_only,false)=false then p.photo_url else null end
    from connection_requests cr
    join profiles p on p.user_id = cr.from_id
   where cr.to_id = v_uid and cr.status = 'pending';
end $$;

-- ----------------------------------------------------------------------
-- cancel_request   [etkin kaynak: 280_kredi_ve_durum_kilidi.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.cancel_request(p_request_id uuid, p_reason text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare v_uid uuid := auth.uid(); v_r requests%rowtype; v_other uuid; v_iade int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_r from requests where id = p_request_id for update;
  if not found then raise exception 'request_not_found'; end if;
  if v_r.guest_id <> v_uid and v_r.host_id <> v_uid then raise exception 'not_participant'; end if;
  if v_r.status not in ('pending','accepted') then raise exception 'cannot_cancel'; end if;

  -- K2: pending VEYA active oturum varsa istek üzerinden iptal YOK —
  -- `cancel_session` yolu kullanılır (orada geç-iptal kuralı işler).
  if public.istegin_acik_oturumu_var_mi(p_request_id) then
    raise exception 'session_active';
  end if;

  update requests set status = 'cancelled', responded_at = now() where id = p_request_id;

  v_iade := public.istek_kredisi_iade(p_request_id, 'request_cancel_refund');

  v_other := case when v_uid = v_r.guest_id then v_r.host_id else v_r.guest_id end;
  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_other, 'requests', 'İstek iptal edildi',
          coalesce(left(p_reason,80), 'Karşı taraf isteği iptal etti.'), 'request', p_request_id);
  if v_iade > 0 then
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_r.guest_id, 'system', 'Kredin iade edildi',
            format('İptal nedeniyle %s kredi iade edildi.', v_iade), 'request', p_request_id);
  end if;
  return jsonb_build_object('ok', true, 'refunded', v_iade > 0, 'amount', v_iade);
end $$;

-- ----------------------------------------------------------------------
-- recompute_badge   [etkin kaynak: 046_trust_and_host_visibility.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.recompute_badge(p_user uuid)
returns text language plpgsql security definer set search_path = public as $$
declare v_role user_role; v_host_sessions int; v_guest_sessions int; v_score int; v_badge text;
begin
  select role into v_role from users where id = p_user;
  select coalesce(score,0) into v_score from trust_scores where user_id = p_user;

  select count(*) into v_host_sessions
    from sessions s join requests r on r.id = s.request_id
   where s.status = 'completed' and r.host_id = p_user;
  select count(*) into v_guest_sessions
    from sessions s join requests r on r.id = s.request_id
   where s.status = 'completed' and r.guest_id = p_user;

  if v_role = 'host' then
    v_badge := case
      when v_host_sessions >= 20 then 'Elite Host'
      when v_host_sessions >= 5  then 'Trusted Host'
      when v_host_sessions >= 1  then 'Verified Host'
      else 'Basic Verified' end;
  else
    v_badge := case
      when v_score >= 70 then 'High Trust Guest'      -- artik ULASILABILIR (tavan 82)
      when v_guest_sessions >= 1 then 'Verified Guest'
      else 'Basic Verified' end;
  end if;

  update trust_scores set badge = v_badge, updated_at = now() where user_id = p_user;
  return v_badge;
end $$;

-- ----------------------------------------------------------------------
-- trg_session_completed   [etkin kaynak: 032_p2_flows.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_session_completed()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_r requests%rowtype;
begin
  if new.status = 'completed' and (old.status is distinct from 'completed') then
    select * into v_r from requests where id = new.request_id;
    perform public.recompute_badge(v_r.host_id);
    perform public.recompute_badge(v_r.guest_id);
  end if;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- defer_rating   [etkin kaynak: 032_p2_flows.sql]
-- ----------------------------------------------------------------------
create or replace function public.defer_rating(p_session uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  update sessions
     set rate_deferred_by = array_append(coalesce(rate_deferred_by, '{}'), v_uid)
   where id = p_session and not (coalesce(rate_deferred_by,'{}') @> array[v_uid]);
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- pending_ratings   [etkin kaynak: 187_kanitlanmis_kusurlar.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.pending_ratings()
returns table (
  session_id uuid, request_id uuid, other_id uuid, other_name text,
  lounge text, completed_at timestamptz, i_am_host boolean,
  airport_code text, avail_date date, time_from time, time_to time,
  flight_number text, carrier text
)
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  return query
  select s.id, r.id,
         case when r.host_id = v_uid then r.guest_id else r.host_id end,
         coalesce(p.name, 'Yolcu'),
         coalesce(a.lounge_name, a.airport_code::text),
         s.completed_at,
         (r.host_id = v_uid),
         a.airport_code::text,          -- 🔴 char(3) -> text
         a.avail_date, a.time_from, a.time_to,
         a.flight_number, a.carrier
    from sessions s
    join requests r on r.id = s.request_id
    left join availabilities a on a.id = r.avail_id
    left join profiles p
      on p.user_id = case when r.host_id = v_uid then r.guest_id else r.host_id end
   where s.status = 'completed'
     and (r.host_id = v_uid or r.guest_id = v_uid)
     and not exists (select 1 from ratings rt
                      where rt.session_id = s.id and rt.rater_id = v_uid)
   order by s.completed_at desc nulls last
   limit 20;
end $$;

-- ----------------------------------------------------------------------
-- has_active_session   [etkin kaynak: 080_session_lifecycle.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.has_active_session()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from sessions s join requests r on r.id = s.request_id
     where s.status = 'active' and (r.host_id = auth.uid() or r.guest_id = auth.uid())
  )
$$;

-- ----------------------------------------------------------------------
-- grant_signup_credits   [etkin kaynak: 033_beta_credits_dualrole_radar.sql]
-- ----------------------------------------------------------------------
create or replace function public.grant_signup_credits(p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_cfg jsonb; v_amt int; v_bal int;
begin
  select value into v_cfg from beta_settings where key = 'signup_credits';
  if not coalesce((v_cfg->>'enabled')::boolean, false) then return; end if;
  v_amt := coalesce((v_cfg->>'amount')::int, 0);
  if v_amt <= 0 then return; end if;

  -- zaten verilmişse tekrar verme
  if exists (select 1 from credit_ledger where user_id = p_user and reason = 'beta_signup') then
    return;
  end if;

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = p_user;
  insert into credit_ledger (user_id, delta, reason, balance_after)
  values (p_user, v_amt, 'beta_signup', v_bal + v_amt);

  insert into notifications (user_id, category, title, body)
  values (p_user, 'system', 'Hoş geldin ✦',
          v_amt || ' beta kredin hesabına tanımlandı. Her lounge isteği 1 kredi.');
end $$;

-- ----------------------------------------------------------------------
-- admin_credit_adjust   [etkin kaynak: 033_beta_credits_dualrole_radar.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_credit_adjust(
  p_user uuid, p_delta int, p_note text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_bal int;
begin
  if p_delta = 0 then raise exception 'delta_zero'; end if;
  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = p_user;
  if v_bal + p_delta < 0 then raise exception 'would_go_negative'; end if;

  insert into credit_ledger (user_id, delta, reason, balance_after, note)
  values (p_user, p_delta, 'admin_adjust', v_bal + p_delta, p_note);

  insert into notifications (user_id, category, title, body)
  values (p_user, 'system',
          case when p_delta > 0 then 'Kredi tanımlandı ✦' else 'Kredi düzeltmesi' end,
          case when p_delta > 0 then '+' || p_delta || ' kredi hesabına eklendi.'
               else p_delta || ' kredi düzeltmesi yapıldı.' end ||
          coalesce(' · ' || p_note, ''));

  return jsonb_build_object('ok', true, 'balance', v_bal + p_delta);
end $$;

-- ----------------------------------------------------------------------
-- admin_bulk_credit   [etkin kaynak: 033_beta_credits_dualrole_radar.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_bulk_credit(
  p_delta int, p_note text default null, p_role text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_count int := 0; v_u record; v_bal int;
begin
  if p_delta <= 0 then raise exception 'delta_must_be_positive'; end if;
  for v_u in
    select id from users
     where deleted_at is null
       and (p_role is null or role = p_role)
  loop
    select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_u.id;
    insert into credit_ledger (user_id, delta, reason, balance_after, note)
    values (v_u.id, p_delta, 'admin_adjust', v_bal + p_delta, coalesce(p_note,'Toplu beta kredisi'));
    insert into notifications (user_id, category, title, body)
    values (v_u.id, 'system', 'Kredi tanımlandı ✦', '+' || p_delta || ' kredi hesabına eklendi.');
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('ok', true, 'affected', v_count);
end $$;

-- ----------------------------------------------------------------------
-- create_availability   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ⚠ Bu fonksiyon 11 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_availability(p_lounge_id uuid, p_airport text, p_date date, p_from time without time zone, p_to time without time zone, p_slots integer, p_flight text DEFAULT NULL::text, p_visibility text DEFAULT 'all'::text, p_carrier text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb; v_id uuid;
  v_pg uuid; v_kaynak text; v_kod text; v_ad text;
begin
  -- ══════════════════════════════════════════════════════════════════
  -- 🔴 261 — ROL KAPISI. ILAN ACMAK ARTIK KIMSEYI SESSIZCE HOST YAPMAZ.
  --
  -- Kapi EN USTTE: `_base` cagrilmadan once. Boylece `_base` icindeki
  -- 055 terfisi (`update users set role='host'`) ULASILAMAZ hale
  -- geliyor — buraya gelen zaten host.
  --
  -- Host olmanin TEK yolu artik acik niyet: `rolumu_sec('host')`
  -- (uygulamadaki "Host ol" dugmesi) ya da onaylanmis host basvurusu.
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from users u where u.id = auth.uid() and u.role = 'host')
     and not exists (select 1 from host_applications ha
                      where ha.user_id = auth.uid() and ha.status = 'approved')
  then
    raise exception 'not_a_host';
  end if;
  -- 🔴 301/§5: KENDİ İLANIYLA ÇAKIŞAN İLAN açılabiliyordu (tam akış testi,
  -- 10–13 varken 12–15 GEÇTİ). `update_availability` bunu 'kendi_ilanlarin_
  -- cakisiyor' ile zaten reddediyordu — açma yolu reddetmiyordu. Aynı kişi
  -- aynı saatte iki salonda olamaz; ikinci ilana kabul edilen misafir kapıda kalır.
  if exists (select 1 from availabilities a
              where a.host_id = auth.uid() and a.active
                and a.avail_date = p_date
                and a.time_from < p_to and p_from < a.time_to) then
    raise exception 'kendi_ilanlarin_cakisiyor'
      using hint = 'Bu saatte başka bir ilanın var. Önce onu kaldır ya da saatleri ayır.';
  end if;
  -- ══════════════════════════════════════════════════════════════════

  -- Butun kapilar, kotalar, bildirimler _base zincirinde.
  -- Buraya tek bir is kaldi: SONUCU ANLATMAK.
  v := public.create_availability_base(
         p_lounge_id, p_airport, p_date, p_from, p_to, p_slots,
         p_flight, p_visibility, p_carrier);

  v_id := nullif(v ->> 'id', '')::uuid;
  if v_id is null then
    return v;   -- _base bir sey dondurmediyse uydurmuyoruz
  end if;

  select a.program_id, a.program_source, p.code, p.name
    into v_pg, v_kaynak, v_kod, v_ad
    from availabilities a
    left join lounge_programs p on p.id = a.program_id
   where a.id = v_id;

  return v || jsonb_build_object(
    'program_id',     v_pg,
    'program_kodu',   v_kod,
    'program_adi',    v_ad,
    'program_kaynagi', coalesce(v_kaynak, 'bilinmiyor'),
    'program_notu', case
      when v_pg is null then
        'Bu ilan bir kart programına bağlanamadı: hak beyanınız bu salonun kabul listesiyle eşleşmiyor. İlan yayında; yalnız sağlayıcı raporunda "program bilinmeyen" sayılacak.'
      when coalesce(v_kaynak, '') = 'turetildi' then
        format('Bu ilan "%s" programı altında sayılacak. Bu bir ÇIKARIM: doğrulanmış hak beyanınızdan türetildi, sizin beyanınız değil.', coalesce(v_ad, v_kod))
      else
        format('Bu ilan "%s" programı altında sayılacak (beyan).', coalesce(v_ad, v_kod))
      end);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §8 · seyahat_sil (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.seyahat_sil(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_sahip uuid;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select user_id into v_sahip from visits where id = p_id;
  if v_sahip is null then raise exception 'visit_not_found'; end if;
  if v_sahip <> v_uid then raise exception 'not_your_visit'; end if;
  -- 240'ın sözleşme kilidi: bu seyahate dayanan aktif başvuru varsa silinmez.
  -- 🔴 301/§8: fonksiyon SAYI döndürüyor; `if <sayı> then` 0/1 için
  -- tesadüfen çalışıyor ('0'/'1' geçerli boolean metni), 2+ açık başvuruda
  -- "invalid input syntax for type boolean: "2"" ile patlıyordu (tam akış testi).
  if public.seyahate_bagli_basvuru(p_id) > 0 then
    raise exception 'seyahat_silinemez_basvuru_var';
  end if;
  delete from visits where id = p_id;
  return jsonb_build_object('ok', true);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §9 · blok_gecmisi_kapat (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.blok_gecmisi_kapat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- 🔴 301/§9: 204'ten beri bekleyen istek KAPANIYOR ama tutulan kredi
  -- İADE EDİLMİYORDU (tam akış testi: defterde yalnız `request_hold:-1`).
  -- Engelleme uygulamadan yapılamadığı için bu hiç görünmemişti; 301 §1
  -- engellemeyi açınca canlı hataya dönüşecekti. Artık her kapanan istek
  -- iade yolundan geçiyor (tekrar iadeyi `istek_kredisi_iade` kendisi önler).
  declare v_r record;
  begin
    for v_r in
      update requests set status = 'cancelled', responded_at = now()
       where status = 'pending'
         and ((guest_id = new.blocker and host_id = new.blocked)
           or (guest_id = new.blocked and host_id = new.blocker))
      returning id
    loop
      perform public.istek_kredisi_iade(v_r.id, 'request_refund');
    end loop;
  end;

  -- ⚠️ `connection_status` = pending | accepted | declined | blocked.
  -- İlk yazışımda 'rejected' yazdım — enum'da YOK, 22P02 aldım. Enum'un
  -- kendisinde zaten 'blocked' var ve burada 'declined'dan DAHA DOĞRU:
  -- kullanıcı reddetmedi, engelledi. Sebep kayıtta kalsın.
  update connection_requests set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((from_id = new.blocker and to_id = new.blocked)
       or (from_id = new.blocked and to_id = new.blocker));

  update invites set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((host_id = new.blocker and guest_id = new.blocked)
       or (host_id = new.blocked and guest_id = new.blocker));

  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ
-- ════════════════════════════════════════════════════════════════════════
do $z301$
declare v_n int; v_l text;
begin
  select count(*), string_agg(p.proname, ', ') into v_n, v_l
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('engelle','engeli_kaldir','engellediklerim','gelmedi_bildir','gelmedi_esigi')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '301 §Z: authenticated çağıramıyor: %', v_l; end if;
  select count(*) into v_n from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '301 §Z: PUBLIC''e açık % fonksiyon (300 §A2 geriledi)', v_n; end if;
  if position('test_hesabi_gizli_mi' in (select prosrc from pg_proc where proname = 'is_visible')) = 0 then
    raise exception '301 §Z: is_visible yamasız';
  end if;
  if not exists (select 1 from pg_trigger where tgname = 'trg_mesaj_engel') then
    raise exception '301 §Z: mesaj engel tetikleyicisi yok';
  end if;
  raise notice '301 §Z: kapılar ölçüldü';
end $z301$;

select '301 OK — engelleme · gelmedi · test hesabı gizleme · rehber sayacı' as sonuc;

-- ----------------------------------------------------------------------
-- recompute_trust   [etkin kaynak: 080_session_lifecycle.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.recompute_trust(p_user uuid)
returns int language plpgsql security definer set search_path = public as $$
declare
  v_c jsonb := '{}'::jsonb; v_score int := 0;
  v_p profiles%rowtype; v_v verifications%rowtype;
  v_sessions int; v_rating numeric; v_rating_n int; v_badge text;
  v_bad int; v_penalty int := 0;
begin
  select * into v_p from profiles where user_id = p_user;
  select * into v_v from verifications where user_id = p_user;

  select count(*) into v_sessions
    from sessions s join requests r on r.id = s.request_id
   where s.status = 'completed' and (r.guest_id = p_user or r.host_id = p_user);

  v_c := v_c || '{"email":10}'::jsonb;
  if coalesce(v_v.phone_verified,false) then v_c := v_c || '{"phone":10}'::jsonb; end if;
  if coalesce(v_v.id_verified,false)    then v_c := v_c || '{"id":18}'::jsonb; end if;

  if coalesce(v_p.linkedin_verified, false) then
    v_c := v_c || '{"linkedin":8}'::jsonb;
  elsif coalesce(nullif(trim(v_p.linkedin_url),''), '') <> '' then
    v_c := v_c || '{"linkedin":4}'::jsonb;
  end if;

  if coalesce(nullif(trim(v_p.profession),''), '') <> '' then
    v_c := v_c || '{"profession":6}'::jsonb;
  end if;
  if length(coalesce(trim(v_p.bio),'')) >= 40 then
    v_c := v_c || '{"bio":6}'::jsonb;
  end if;

  if v_p.guest_capacity is not null and v_sessions >= 1 then
    v_c := v_c || '{"host_access":8}'::jsonb;
  end if;

  if v_sessions >= 10 then v_c := v_c || '{"sessions":14}'::jsonb;
  elsif v_sessions >= 3 then v_c := v_c || '{"sessions":10}'::jsonb;
  elsif v_sessions >= 1 then v_c := v_c || '{"sessions":6}'::jsonb;
  end if;

  select avg(score)::numeric, count(*) into v_rating, v_rating_n
    from ratings where rated_id = p_user;

  if coalesce(v_rating_n,0) >= 3 then
    if v_rating >= 4.5 then v_c := v_c || '{"rating":10}'::jsonb;
    elsif v_rating >= 4.0 then v_c := v_c || '{"rating":6}'::jsonb;
    elsif v_rating >= 3.0 then v_c := v_c || '{"rating":2}'::jsonb;
    end if;
  end if;

  -- 🔴 080: SON 90 GÜNDEKİ GEÇ İPTAL + NO-SHOW CEZASI (her biri -12).
  -- Neden 90 gün: ceza kalıcı olursa kullanıcı asla toparlanamaz; unutulan
  -- ceza da caydırıcı olmaz. 90 gün ikisinin dengesi.
  select count(*) into v_bad from sessions s
   where s.completed_at > now() - interval '90 days'
     and ((s.cancel_reason = 'late_cancel' and s.cancelled_by = p_user)
       or (s.cancel_reason = 'no_show' and s.no_show_user_id = p_user));
  v_penalty := least(36, coalesce(v_bad,0) * 12);
  if v_penalty > 0 then
    v_c := v_c || jsonb_build_object('reliability', -v_penalty);
  end if;

  select coalesce(sum(value::int),0) into v_score from jsonb_each_text(v_c);
  v_score := least(100, greatest(0, v_score));

  v_badge := public.compute_trust_badge(v_score);

  insert into trust_scores (user_id, score, badge, components, updated_at)
  values (p_user, v_score, v_badge, v_c, now())
  on conflict (user_id) do update
    set score = excluded.score, badge = excluded.badge,
        components = excluded.components, updated_at = now();

  return v_score;
end $$;

-- ----------------------------------------------------------------------
-- trg_profile_trust   [etkin kaynak: 033_beta_credits_dualrole_radar.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_profile_trust()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform recompute_trust(new.user_id);
  return new;
end $$;

-- ----------------------------------------------------------------------
-- trg_profile_trust_v   [etkin kaynak: 033_beta_credits_dualrole_radar.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_profile_trust_v()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform recompute_trust(new.user_id);
  return new;
end $$;

-- ----------------------------------------------------------------------
-- lounge_radar_people   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_radar_people()
returns table (
  user_id uuid, name text, profession text, bio text,
  badge text, score int, photo_url text,
  same_flight boolean, rel text, lounge_name text
)
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_air text; v_from time; v_to time; v_flight text;
  v_me_women boolean; v_me_gender text; v_me_share boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select coalesce(p.location_sharing, false) into v_me_share from profiles p where p.user_id = v_uid;
  if not v_me_share then return; end if;

  -- bağlam: bugün, şu anı kapsayan ilan veya trip
  select a.airport_code, a.time_from, a.time_to into v_air, v_from, v_to
    from availabilities a
   where a.host_id = v_uid and a.active
     and a.avail_date = public.yerel_gun(a.airport_code)
     and a.time_from <= public.yerel_saat(a.airport_code)
     and public.yerel_saat(a.airport_code) <= a.time_to
   limit 1;

  if v_air is null then
    select v.airport_code, v.time_from, v.time_to, v.flight_number into v_air, v_from, v_to, v_flight
      from visits v
     where v.user_id = v_uid
       and v.visit_date = public.yerel_gun(v.airport_code)
       and v.time_from <= public.yerel_saat(v.airport_code)
       and public.yerel_saat(v.airport_code) <= v.time_to
     limit 1;
  end if;

  if v_air is null then return; end if;

  select coalesce(pr.women_safety_mode, false), u.gender into v_me_women, v_me_gender
    from profiles pr join users u on u.id = pr.user_id where pr.user_id = v_uid;

  return query
  with present as (
    -- aynı havalimanında, bugün, örtüşen saatte olan HERKES (host + guest)
    select v.user_id as uid, v.flight_number as flight, null::uuid as lid
      from visits v
     where v.visit_date = public.yerel_gun(v_air)
       and v.airport_code = v_air
       and v.time_from < v_to and v_from < v.time_to
       and v.user_id <> v_uid
    union
    select a.host_id as uid, null::text as flight, a.lounge_id as lid
      from availabilities a
     where a.active and a.avail_date = public.yerel_gun(v_air)
       and a.airport_code = v_air
       and a.time_from < v_to and v_from < a.time_to
       and a.host_id <> v_uid
  )
  select distinct on (pe.uid)
    pe.uid,
    pr.name,
    pr.profession,
    case when pr.profile_visibility = 'Connections'
              and not exists (select 1 from connection_requests c
                               where c.status='accepted'
                                 and ((c.from_id=v_uid and c.to_id=pe.uid)
                                   or (c.to_id=v_uid and c.from_id=pe.uid)))
         then null else pr.bio end as bio,
    ts.badge,
    ts.score,
    -- foto yalnızca bağlantılıysa (mevcut gizlilik kuralı)
    case when pr.photo_connections_only
              and not exists (select 1 from connection_requests c
                               where c.status='accepted'
                                 and ((c.from_id=v_uid and c.to_id=pe.uid)
                                   or (c.to_id=v_uid and c.from_id=pe.uid)))
         then null else pr.photo_url end as photo_url,
    (v_flight is not null and pe.flight = v_flight) as same_flight,
    coalesce((select c.status::text from connection_requests c
               where (c.from_id=v_uid and c.to_id=pe.uid)
                  or (c.to_id=v_uid and c.from_id=pe.uid)
               order by c.created_at desc limit 1), 'none') as rel,
    l.name as lounge_name
  from present pe
  join profiles pr on pr.user_id = pe.uid
  join users u on u.id = pe.uid
  left join trust_scores ts on ts.user_id = pe.uid
  left join lounges l on l.id = pe.lid
  where u.deleted_at is null
    -- opt-in: konum paylaşımı kapalı olan radara girmez
    and coalesce(pr.location_sharing, false)
    -- gölge kısıt: 029'daki FONKSIYON (profiles kolonu değil)
    and is_visible(pe.uid)
    -- profil görünürlüğü 'nobody' ise hiç gösterme
    -- 'Connections' gizli degil; bio kilitlenir ama kisi listede gorunur (mevcut kural)
    -- kadın güvenlik modu: çift yönlü
    and (not v_me_women or u.gender = 'female')
    and (not coalesce(pr.women_safety_mode,false) or v_me_gender = 'female')
    -- engelleme
    and not exists (
      select 1 from blocks b
       where (b.blocker = v_uid and b.blocked = pe.uid)
          or (b.blocker = pe.uid and b.blocked = v_uid))
  order by pe.uid, ts.score desc nulls last;
end $$;

-- ----------------------------------------------------------------------
-- lounge_radar_count   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_radar_count()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_ctx record;
  v_count int := 0;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- Kullanıcının ŞU ANKİ bağlamı: bugün, şu saati kapsayan trip veya ilan
  select coalesce(a.airport_code, v.airport_code) as airport,
         a.lounge_id as lounge_id,
         coalesce(a.time_from, v.time_from) as t_from,
         coalesce(a.time_to,   v.time_to)   as t_to
    into v_ctx
    from (select 1) x
    left join availabilities a
      on a.host_id = v_uid and a.active
     and a.avail_date = public.yerel_gun(a.airport_code)
     and a.time_from <= public.yerel_saat(a.airport_code)
     and public.yerel_saat(a.airport_code) <= a.time_to
    left join visits v
      on v.user_id = v_uid
     and v.visit_date = public.yerel_gun(v.airport_code)
     and v.time_from <= public.yerel_saat(v.airport_code)
     and public.yerel_saat(v.airport_code) <= v.time_to
   limit 1;

  if v_ctx.airport is null then
    return jsonb_build_object('active', false);
  end if;

  -- Konum paylaşımı KAPALIYSA: radar çalışmaz ama app'e "açabilirsin" sinyali dön.
  -- Varsayılan false (001) — gizlilik açısından doğru, opt-in olmalı.
  -- App bu durumda "Radarı aç" kartı gösterir; kullanıcı bilinçli açar.
  if not coalesce((select location_sharing from profiles where user_id = v_uid), false) then
    return jsonb_build_object(
      'active', false,
      'reason', 'location_off',
      'can_enable', true,          -- app: "Radarı aç" kartı göster
      'airport', v_ctx.airport
    );
  end if;

  select count(*) into v_count from lounge_radar_people();

  return jsonb_build_object(
    'active', true,
    'airport', v_ctx.airport,
    'lounge_id', v_ctx.lounge_id,
    'count', v_count,
    'time_from', v_ctx.t_from,
    'time_to', v_ctx.t_to
  );
end $$;

-- ----------------------------------------------------------------------
-- needs_password_change   [etkin kaynak: 035_password_flow.sql]
-- ----------------------------------------------------------------------
create or replace function public.needs_password_change(p_user uuid default null)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    (select must_change_password from admin_roles where user_id = coalesce(p_user, auth.uid())),
    (select bool_or(must_change_password) from lounge_partners where user_id = coalesce(p_user, auth.uid())),
    false
  );
$$;

-- ----------------------------------------------------------------------
-- mark_password_changed   [etkin kaynak: 035_password_flow.sql]
-- ----------------------------------------------------------------------
create or replace function public.mark_password_changed()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  update admin_roles      set must_change_password = false where user_id = v_uid;
  update lounge_partners  set must_change_password = false where user_id = v_uid;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- apply_for_host   [etkin kaynak: 036_host_applications.sql]
-- ----------------------------------------------------------------------
create or replace function public.apply_for_host(
  p_access_source text, p_guest_capacity int, p_note text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_role user_role; v_ok boolean; v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select role into v_role from users where id = v_uid;
  if v_role = 'host' then raise exception 'already_host'; end if;

  -- Telefon doğrulaması şart (§16 — beyan sahibi ulaşılabilir olmalı)
  select phone_verified into v_ok from verifications where user_id = v_uid;
  if not coalesce(v_ok, false) then raise exception 'phone_not_verified'; end if;

  if coalesce(trim(p_access_source),'') = '' then raise exception 'access_source_required'; end if;
  if p_guest_capacity is null or p_guest_capacity < 1 then raise exception 'capacity_required'; end if;

  if exists (select 1 from host_applications where user_id = v_uid and status = 'pending') then
    raise exception 'application_pending';
  end if;

  insert into host_applications (user_id, access_source, guest_capacity, note)
  values (v_uid, p_access_source, p_guest_capacity, left(coalesce(p_note,''), 140))
  returning id into v_id;

  insert into notifications (user_id, category, title, body)
  values (v_uid, 'system', 'Başvurun alındı ✦',
          'Host başvurun incelemeye alındı. Sonucu bildirimle ileteceğiz.');

  return jsonb_build_object('ok', true, 'id', v_id);
end $$;

-- ----------------------------------------------------------------------
-- my_host_application   [etkin kaynak: 036_host_applications.sql]
-- ----------------------------------------------------------------------
create or replace function public.my_host_application()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_a host_applications%rowtype; v_role user_role;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select role into v_role from users where id = v_uid;
  if v_role = 'host' then return jsonb_build_object('is_host', true); end if;

  select * into v_a from host_applications
   where user_id = v_uid order by created_at desc limit 1;

  if not found then return jsonb_build_object('is_host', false, 'status', 'none'); end if;

  return jsonb_build_object(
    'is_host', false,
    'status', v_a.status,
    'access_source', v_a.access_source,
    'guest_capacity', v_a.guest_capacity,
    'review_note', v_a.review_note,
    'created_at', v_a.created_at
  );
end $$;

-- ----------------------------------------------------------------------
-- review_host_application   [etkin kaynak: 036_host_applications.sql]
-- ----------------------------------------------------------------------
create or replace function public.review_host_application(
  p_id uuid, p_approve boolean, p_note text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_a host_applications%rowtype;
begin
  select * into v_a from host_applications where id = p_id for update;
  if not found then raise exception 'application_not_found'; end if;
  if v_a.status <> 'pending' then raise exception 'already_reviewed'; end if;

  update host_applications
     set status = case when p_approve then 'approved' else 'rejected' end,
         reviewed_at = now(), review_note = p_note
   where id = p_id;

  if p_approve then
    -- Rolü host yap + beyanı profile işle
    update users set role = 'host' where id = v_a.user_id;
    update profiles
       set access_source = v_a.access_source,
           guest_capacity = v_a.guest_capacity
     where user_id = v_a.user_id;

    -- Trust: host erişim kaynağı beyanı (§16) — 033'teki recompute_trust yeniden hesaplar
    perform recompute_trust(v_a.user_id);
    perform recompute_badge(v_a.user_id);

    insert into notifications (user_id, category, title, body)
    values (v_a.user_id, 'system', 'Host başvurun onaylandı ✦',
            'Artık lounge ilanı açabilirsin. Hosting sekmesinden ilk ilanını oluştur.');
  else
    insert into notifications (user_id, category, title, body)
    values (v_a.user_id, 'system', 'Host başvurun sonuçlandı',
            coalesce(nullif(p_note,''), 'Başvurun bu sefer onaylanmadı. Detay için destek ile iletişime geçebilirsin.'));
  end if;

  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- admin_update_profile   [etkin kaynak: 036_host_applications.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_update_profile(p_user uuid, p_patch jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  update profiles set
    name               = coalesce(p_patch->>'name', name),
    profession         = coalesce(p_patch->>'profession', profession),
    bio                = coalesce(p_patch->>'bio', bio),
    linkedin_url       = coalesce(p_patch->>'linkedin_url', linkedin_url),
    access_source      = coalesce(p_patch->>'access_source', access_source),
    guest_capacity     = coalesce((p_patch->>'guest_capacity')::int, guest_capacity),
    profile_visibility = coalesce((p_patch->>'profile_visibility')::profile_visibility, profile_visibility),
    women_safety_mode  = coalesce((p_patch->>'women_safety_mode')::boolean, women_safety_mode),
    location_sharing   = coalesce((p_patch->>'location_sharing')::boolean, location_sharing),
    show_on_discovery  = coalesce((p_patch->>'show_on_discovery')::boolean, show_on_discovery),
    updated_at         = now()
  where user_id = p_user;

  if p_patch ? 'linkedin_verified' then
    update profiles set linkedin_verified = (p_patch->>'linkedin_verified')::boolean where user_id = p_user;
  end if;

  perform recompute_trust(p_user);
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- admin_set_verification   [etkin kaynak: 037_admin_verifications.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_set_verification(
  p_user uuid, p_field text, p_value boolean
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_score int;
begin
  if p_field not in ('phone_verified','id_verified','linkedin_verified','email_verified') then
    raise exception 'invalid_field';
  end if;

  -- satır yoksa aç
  insert into verifications (user_id) values (p_user) on conflict (user_id) do nothing;

  if p_field = 'phone_verified' then
    update verifications set phone_verified = p_value,
      phone_verified_at = case when p_value then now() else null end,
      updated_at = now() where user_id = p_user;

  elsif p_field = 'id_verified' then
    update verifications set id_verified = p_value,
      id_verified_at = case when p_value then now() else null end,
      id_provider = case when p_value then coalesce(id_provider, 'manual') else id_provider end,
      updated_at = now() where user_id = p_user;

  elsif p_field = 'linkedin_verified' then
    update verifications set linkedin_verified = p_value, updated_at = now() where user_id = p_user;
    -- profiles'ta da ayrı bir linkedin_verified var (trust bunu okuyor) — ikisini eşle
    update profiles set linkedin_verified = p_value, updated_at = now() where user_id = p_user;

  elsif p_field = 'email_verified' then
    update verifications set email_verified = p_value,
      email_verified_at = case when p_value then now() else null end,
      updated_at = now() where user_id = p_user;
  end if;

  -- Güven puanı ANINDA yeniden hesaplanır (033'teki recompute_trust)
  select recompute_trust(p_user) into v_score;
  perform recompute_badge(p_user);

  return jsonb_build_object('ok', true, 'score', v_score);
end $$;

-- ----------------------------------------------------------------------
-- my_availabilities   [etkin kaynak: 040_visibility_and_discovery_fix.sql]
-- ----------------------------------------------------------------------
create or replace function public.my_availabilities()
returns table (
  id uuid, airport_code text, lounge_id uuid, lounge_name text,
  avail_date date, time_from time, time_to time,
  slots int, filled int, flight_number text, visibility text, min_trust int,
  active boolean, is_featured boolean, pending_count int
)
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  return query
  select a.id, a.airport_code::text,
         a.lounge_id,
         coalesce(l.name, a.lounge_name) as lounge_name,
         a.avail_date, a.time_from, a.time_to,
         a.slots::int, a.filled::int, a.flight_number,
         coalesce(a.visibility,'Public')::text, coalesce(a.min_trust,0)::int,
         a.active,
         (a.featured_until is not null and a.featured_until > now()) as is_featured,
         (select count(*) from requests r where r.avail_id = a.id and r.status='pending')::int as pending_count
  from availabilities a
  left join lounges l on l.id = a.lounge_id
  where a.host_id = v_uid
  order by a.avail_date desc, a.time_from desc;
end $$;

-- ----------------------------------------------------------------------
-- cancel_availability   [etkin kaynak: 293_davet_cift_onay_ve_ilan_geri_cekme.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.cancel_availability(p_id uuid, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_accepted int; v_pending int; v_iptal int := 0;
  r record;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);
  if not exists (select 1 from availabilities where id = p_id and host_id = v_uid) then
    raise exception 'not_your_availability';
  end if;

  -- Oturum başladıysa hiçbir yoldan geri çekilemez.
  -- 🔴 13 EYLÜL — BU KAPI ÇOK GENİŞTİ VE 291'İN KENDİ AMACINI
  -- ÇÜRÜTÜYORDU. `pending` bir oturum "başlamış" demek DEĞİL: SQL 080'de
  -- oturum satırı kabulde oluşur, gerçekten `active` olması için İKİ
  -- TARAFIN DA "Oturumu Başlat"a basması gerekir.
  -- ÖLÇÜM: `respond_invite` her kabulde bir oturum satırı yaratıyor
  -- (293 öncesi doğrudan 'active'). Sonuç: daveti kabul edilmiş bir
  -- ilanı host ZORLA BİLE geri çekemiyordu — yani Gökberk'in 13 Eylül
  -- madde 2'de istediği şeyin tam tersi oluyordu.
  -- Doğru kapı: buluşma GERÇEKTEN başlamışsa geri çekilemez.
  --   · status = 'active'                        → başladı
  --   · 'pending' ama bir taraf "geldim" dediyse  → biri kapıda bekliyor
  -- İkisi de yoksa zorlu kaldırma çalışır ve o boş oturum satırı da
  -- kapatılır (yetim satır bırakmak, temizlik değil sızıntıdır — 291'in
  -- kendi sınıfı).
  if exists (
    select 1 from sessions s join requests q on q.id = s.request_id
     where q.avail_id = p_id
       and (s.status = 'active'
            or (s.status = 'pending'
                and (s.host_started_at is not null or s.guest_started_at is not null)))
  ) then raise exception 'session_started'; end if;

  select count(*) filter (where status = 'accepted'),
         count(*) filter (where status = 'pending')
    into v_accepted, v_pending
    from requests where avail_id = p_id;

  if v_accepted > 0 and not p_force then
    raise exception 'has_accepted_requests';
  end if;

  if p_force then
    -- Açık her isteği REDDET: kredi iadesi + bildirim, `respond_request`
    -- ile AYNI yoldan (iade mantığı tek yerde kalsın).
    for r in select id, guest_id from requests
              where avail_id = p_id and status in ('pending','accepted')
              for update
    loop
      update requests set status = 'declined', responded_at = now() where id = r.id;
      perform public.istek_kredisi_iade(r.id, 'request_refund');
      insert into notifications (user_id, category, title, body, ref_id, ref_type)
      values (r.guest_id, 'requests', 'İlan geri çekildi',
              'Host bu ilanı kaldırdı. Kredin anında iade edildi; başka bir ilana başvurabilirsin.',
              r.id, 'request');
      v_iptal := v_iptal + 1;
    end loop;
  else
    -- Zorlamasız yolda BİLE bekleyen istekler serbest bırakılır:
    -- ilan kapanınca o istek zaten cevaplanamaz hâle geliyordu.
    for r in select id, guest_id from requests
              where avail_id = p_id and status = 'pending' for update
    loop
      update requests set status = 'declined', responded_at = now() where id = r.id;
      perform public.istek_kredisi_iade(r.id, 'request_refund');
      insert into notifications (user_id, category, title, body, ref_id, ref_type)
      values (r.guest_id, 'requests', 'İlan geri çekildi',
              'Host bu ilanı kaldırdı. Kredin anında iade edildi; başka bir ilana başvurabilirsin.',
              r.id, 'request');
      v_iptal := v_iptal + 1;
    end loop;
  end if;

  -- Bekleyen davetler de kapanır.
  -- 'cancelled' bu enum'da YOK (pending|accepted|declined|blocked) — davet geri
  -- çekilince 'declined' doğru karşılık: davet edilen kişi bir şey yapmadı.
  update invites set status = 'declined'::connection_status, responded_at = now()
   where avail_id = p_id and status = 'pending';

  -- Hiç başlamamış ('pending' ve iki taraf da basmamış) oturum satırları
  -- ilanla birlikte kapanır; yoksa `expire_stale_sessions` onları
  -- no-show sanıp kullanıcının güvenini düşürürdü.
  update sessions s set status = 'cancelled', completed_at = now(),
         cancel_reason = coalesce(s.cancel_reason, 'ilan_geri_cekildi')
    from requests q
   where q.id = s.request_id and q.avail_id = p_id
     and s.status = 'pending'
     and s.host_started_at is null and s.guest_started_at is null;

  -- Hiç başlamamış ('pending' ve iki taraf da basmamış) oturum satırları
  -- ilanla birlikte kapanır; yoksa `expire_stale_sessions` onları
  -- no-show sanıp kullanıcının güvenini düşürürdü.
  update sessions s set status = 'cancelled', completed_at = now(),
         cancel_reason = coalesce(s.cancel_reason, 'ilan_geri_cekildi')
    from requests q
   where q.id = s.request_id and q.avail_id = p_id
     and s.status = 'pending'
     and s.host_started_at is null and s.guest_started_at is null;

  update availabilities set active = false, updated_at = now() where id = p_id;
  return jsonb_build_object('ok', true, 'iptal_edilen', v_iptal,
                            'bekleyen', v_pending, 'kabul_edilen', v_accepted);
end $function$;

-- ── 3 · AŞIRI YÜKLEME BELİRSİZLİĞİ — 291'İN SESSİZ REGRESYONU ─────────
-- 🔴 ÖLÇÜM: 291, `cancel_availability(p_id uuid, p_force boolean default
-- false)` ekledi ama ESKİ `cancel_availability(p_id uuid)` yerinde kaldı.
-- İkisi bir arada, tek argümanlı her çağrıyı BELİRSİZ yapıyor:
--     ERROR: function public.cancel_availability(uuid) is not unique
-- Yani "geriye dönük uyumluluk için eskisini bıraktım" diye yazdığım
-- satır, tam da korumak istediğim eski çağrıyı KIRIYORDU. (Uygulama bu
-- turda `p_force: true` gönderdiği için fark edilmiyordu; NOT3 kanıtı
-- zorlamasız yolu sınayınca çıktı.)
--
-- 🆕 SINIF: "VARSAYILAN DEĞERLİ BİR AŞIRI YÜKLEME, ESKİ İMZAYI KORUMAZ —
-- ONU BELİRSİZ YAPAR. GERİYE DÖNÜK UYUM AŞIRI YÜKLEMEYLE DEĞİL
-- VARSAYILANLA SAĞLANIR."
--
-- Tek fonksiyon kalıyor: `(p_id uuid, p_force boolean default false)`.
-- `cancel_availability(p_id => ...)` ve `cancel_availability(av)` yine
-- çalışır, davranış eskisiyle aynıdır (zorlamasız).
drop function if exists public.cancel_availability(uuid);
grant execute on function public.cancel_availability(uuid, boolean) to authenticated;

-- ── KENDİ SINAMASI ─────────────────────────────────────────────────────
do $$
declare
  hd uuid; g uuid; lng uuid; av uuid; inv_id uuid; rq uuid;
  v_st text; sonuc jsonb; v_ses uuid; v_n int;
begin
  select id into hd from users where role = 'host' and deleted_at is null limit 1;
  select id into lng from lounges where airport_code = 'IST' limit 1;
  if hd is null or lng is null then raise notice '293 sinama: veri yok, atlandi'; return; end if;
  select id into g from users where id <> hd and deleted_at is null limit 1;
  if g is null then raise notice '293 sinama: misafir yok, atlandi'; return; end if;

  insert into availabilities (host_id, airport_code, lounge_id, avail_date, time_from, time_to, slots, active)
    values (hd, 'IST', lng, public.yerel_gun('IST') + 5, time '10:00', time '13:00', 2, true)
    returning id into av;
  insert into credit_ledger (user_id, delta, reason, balance_after)
    values (g, 3, 'sinama_293', coalesce((select sum(delta) from credit_ledger where user_id = g), 0) + 3);

  -- 1) Davet kabulü oturumu 'pending' doğurmalı, 'active' DEĞİL
  insert into invites (host_id, guest_id, avail_id, status, note)
    values (hd, g, av, 'pending', '293 sinama') returning id into inv_id;
  perform set_config('request.jwt.claims',
    json_build_object('sub', g::text, 'role', 'authenticated')::text, true);
  perform public.respond_invite(inv_id, true);
  select s.id, s.status::text into v_ses, v_st
    from sessions s join requests q on q.id = s.request_id
   where q.avail_id = av limit 1;
  if v_ses is null then raise exception '293: davet kabulunde oturum satiri olusmadi'; end if;
  if v_st <> 'pending' then
    raise exception '293: davet kabulu oturumu % yapti (pending bekleniyordu)', v_st;
  end if;
  raise notice '293 sinama 1 ✓ davet kabulu → oturum ''pending'' (cift onay korunuyor)';

  -- 2) Host, daveti kabul edilmiş ilanı ZORLA geri çekebilmeli
  perform set_config('request.jwt.claims',
    json_build_object('sub', hd::text, 'role', 'authenticated')::text, true);
  sonuc := public.cancel_availability(av, true);
  if (sonuc ->> 'ok') is distinct from 'true' then
    raise exception '293: zorlu kaldirma hala dusuyor';
  end if;
  if (select active from availabilities where id = av) then
    raise exception '293: ilan pasife dusmedi';
  end if;
  select status::text into v_st from sessions where id = v_ses;
  if v_st <> 'cancelled' then
    raise exception '293: baslamamis oturum satiri yetim kaldi (%)', v_st;
  end if;
  raise notice '293 sinama 2 ✓ davet kabul edilmis ilan ZORLA geri cekildi · oturum %', v_st;

  -- 3) GERÇEKTEN başlamış buluşma hâlâ korunmalı
  insert into availabilities (host_id, airport_code, lounge_id, avail_date, time_from, time_to, slots, active)
    values (hd, 'IST', lng, public.yerel_gun('IST') + 6, time '10:00', time '13:00', 2, true)
    returning id into av;
  insert into requests (guest_id, host_id, avail_id, status) values (g, hd, av, 'accepted') returning id into rq;
  insert into sessions (request_id, status, started_at) values (rq, 'active', now());
  begin
    perform public.cancel_availability(av, true);
    raise exception '293: BASLAMIS oturumda kaldirma engellenmedi';
  exception when others then
    if SQLERRM <> 'session_started' then raise; end if;
    raise notice '293 sinama 3 ✓ gercekten baslamis bulusma korunuyor (session_started)';
  end;

  raise exception 'GERI_AL_SINAMA';
exception
  when others then
    if SQLERRM <> 'GERI_AL_SINAMA' then raise; end if;
    raise notice '293 sinama: tum veri geri alindi';
end $$;

-- ----------------------------------------------------------------------
-- create_report   [etkin kaynak: 042_reports_and_sos.sql]
-- ----------------------------------------------------------------------
create or replace function public.create_report(
  p_target uuid, p_type text, p_description text, p_session uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); v_id uuid; v_existing uuid; v_ok boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_target = v_uid then raise exception 'cannot_report_self'; end if;
  if not exists (select 1 from users where id = p_target) then
    raise exception 'target_not_found';
  end if;
  if coalesce(trim(p_description),'') = '' then raise exception 'description_required'; end if;

  -- oturum verildiyse: gerçekten tarafı mısın?
  if p_session is not null then
    select exists (
      select 1 from sessions s join requests r on r.id = s.request_id
       where s.id = p_session and (r.guest_id = v_uid or r.host_id = v_uid)
    ) into v_ok;
    if not v_ok then raise exception 'not_your_session'; end if;
  end if;

  -- 24 saat içinde aynı kişi için açık raporun var mı?
  select id into v_existing from reports
   where reporter_id = v_uid and target_id = p_target
     and status in ('open','reviewing')
     and created_at > now() - interval '24 hours'
   limit 1;

  if v_existing is not null then
    update reports
       set description = description || E'\n---\n' || trim(p_description),
           updated_at = now()
     where id = v_existing;
    return jsonb_build_object('ok', true, 'id', v_existing, 'merged', true);
  end if;

  insert into reports (reporter_id, target_id, session_id, type, description, status)
  values (v_uid, p_target, p_session, p_type::report_type, trim(p_description), 'open')
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id, 'merged', false);
end $$;

-- ----------------------------------------------------------------------
-- sos_alert   [etkin kaynak: 042_reports_and_sos.sql]
-- ----------------------------------------------------------------------
create or replace function public.sos_alert(p_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); v_sess uuid; v_other uuid; v_id uuid; v_name text;
  v_desc text; a record;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- aktif oturum ve karşı taraf
  select s.id,
         case when r.guest_id = v_uid then r.host_id else r.guest_id end
    into v_sess, v_other
    from sessions s join requests r on r.id = s.request_id
   where s.status = 'active' and (r.guest_id = v_uid or r.host_id = v_uid)
   order by s.started_at desc limit 1;

  select name into v_name from profiles where user_id = v_uid;

  v_desc := '[SOS] ' || coalesce(v_name, 'Kullanıcı') || ' acil yardım çağrısı gönderdi.'
         || case when v_sess is not null then ' Aktif oturum var.' else ' Aktif oturum yok.' end
         || case when coalesce(trim(p_note),'') <> '' then E'\nNot: ' || trim(p_note) else '' end;

  -- Hedef: aktif oturumdaki karşı taraf; yoksa kendisi (yalnız kayıt için —
  -- moderatör kimin çağırdığını reporter_id'den görür)
  insert into reports (reporter_id, target_id, session_id, type, description, status, is_urgent)
  values (v_uid, coalesce(v_other, v_uid), v_sess, 'other', v_desc, 'open', true)
  returning id into v_id;

  -- tüm adminlere bildirim
  for a in select user_id from admin_roles loop
    begin
      insert into notifications (user_id, category, icon, title, body)
      values (a.user_id, 'safety', '🆘', 'SOS çağrısı',
              coalesce(v_name,'Bir kullanıcı') || ' acil yardım istedi. Moderasyon kuyruğuna bak.');
    exception when others then null;   -- bildirim patlarsa SOS kaydı yine dursun
    end;
  end loop;

  return jsonb_build_object('ok', true, 'id', v_id, 'has_session', v_sess is not null);
end $$;

-- ----------------------------------------------------------------------
-- my_reports   [etkin kaynak: 042_reports_and_sos.sql]
-- ----------------------------------------------------------------------
create or replace function public.my_reports()
returns table (id uuid, type text, description text, status text,
               resolution text, is_urgent boolean, created_at timestamptz)
language sql stable security definer set search_path = public as $$
  select r.id, r.type::text, r.description, r.status::text,
         r.resolution, r.is_urgent, r.created_at
  from reports r
  where r.reporter_id = auth.uid()
  order by r.created_at desc
  limit 50;
$$;

-- ----------------------------------------------------------------------
-- admin_delete_availability   [etkin kaynak: 043_admin_data_cleanup.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_delete_availability(
  p_id uuid, p_hard boolean default false, p_reason text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_a availabilities%rowtype; v_r record; v_bal int; v_refunded int := 0; v_done int;
begin
  select * into v_a from availabilities where id = p_id;
  if not found then raise exception 'availability_not_found'; end if;

  -- Tamamlanmış oturumu olan ilan asla silinmez — geçmiş korunur
  select count(*) into v_done
    from requests r join sessions s on s.request_id = r.id
   where r.avail_id = p_id and s.status in ('active','completed');
  if v_done > 0 and p_hard then
    raise exception 'has_sessions_cannot_hard_delete';
  end if;
  if exists (select 1 from sessions s join requests r on r.id = s.request_id
             where r.avail_id = p_id and s.status = 'active') then
    raise exception 'session_active';
  end if;

  -- Bekleyen/kabul edilmiş isteklere GERÇEK iade
  -- (Info kutusu bunu vaat ediyordu, kod yapmıyordu — artık yapıyor.)
  for v_r in select * from requests where avail_id = p_id and status in ('pending','accepted') loop
    update requests set status = 'cancelled' where id = v_r.id;
    select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_r.guest_id;
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    values (v_r.guest_id, 1, 'request_cancel_refund', v_r.id, v_bal + 1);
    v_refunded := v_refunded + 1;
    begin
      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      values (v_r.guest_id, 'requests', 'İlan kaldırıldı',
              coalesce(left(p_reason,80), 'Host''un ilanı kaldırıldı. Kredin iade edildi.'),
              'request', v_r.id);
    exception when others then null;
    end;
  end loop;

  if p_hard then
    delete from requests where avail_id = p_id;   -- iptal edilmişler
    delete from availabilities where id = p_id;
  else
    update availabilities set active = false, updated_at = now() where id = p_id;
  end if;

  return jsonb_build_object('ok', true, 'hard', p_hard, 'refunded', v_refunded);
end $$;

-- ----------------------------------------------------------------------
-- admin_delete_visit   [etkin kaynak: 043_admin_data_cleanup.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_delete_visit(p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_v visits%rowtype;
begin
  select * into v_v from visits where id = p_id;
  if not found then raise exception 'visit_not_found'; end if;
  delete from visits where id = p_id;
  return jsonb_build_object('ok', true, 'user_id', v_v.user_id, 'airport', v_v.airport_code);
end $$;

-- ----------------------------------------------------------------------
-- admin_list_visits   [etkin kaynak: 043_admin_data_cleanup.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_list_visits(
  p_airport text default null, p_from date default null, p_limit int default 100
)
returns table (
  id uuid, user_id uuid, user_name text, user_email text,
  airport_code text, destination text, visit_date date,
  time_from time, time_to time, flight_number text, created_at timestamptz
)
language sql stable security definer set search_path = public as $$
  select v.id, v.user_id, p.name, u.email,
         v.airport_code::text, v.destination::text, v.visit_date,
         v.time_from, v.time_to, v.flight_number, v.created_at
  from visits v
  join users u on u.id = v.user_id
  left join profiles p on p.user_id = v.user_id
  where (p_airport is null or v.airport_code = p_airport)
    and (p_from is null or v.visit_date >= p_from)
  order by v.created_at desc
  limit coalesce(p_limit, 100);
$$;

-- ----------------------------------------------------------------------
-- admin_purge_test_data   [etkin kaynak: 043_admin_data_cleanup.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_purge_test_data(
  p_before date, p_dry_run boolean default true
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_avail int; v_visits int; v_reqs int;
begin
  if p_before is null then raise exception 'date_required'; end if;
  if p_before > current_date then raise exception 'date_in_future'; end if;

  -- Sayım: tamamlanmış/aktif oturumu OLMAYAN ilanlar
  select count(*) into v_avail from availabilities a
   where a.avail_date < p_before
     and not exists (select 1 from requests r join sessions s on s.request_id = r.id
                      where r.avail_id = a.id and s.status in ('active','completed'));
  select count(*) into v_visits from visits where visit_date < p_before;
  select count(*) into v_reqs from requests r
   where exists (select 1 from availabilities a where a.id = r.avail_id and a.avail_date < p_before)
     and not exists (select 1 from sessions s where s.request_id = r.id and s.status in ('active','completed'));

  if p_dry_run then
    return jsonb_build_object('dry_run', true, 'would_delete',
      jsonb_build_object('availabilities', v_avail, 'visits', v_visits, 'requests', v_reqs));
  end if;

  delete from requests r
   where exists (select 1 from availabilities a where a.id = r.avail_id and a.avail_date < p_before)
     and not exists (select 1 from sessions s where s.request_id = r.id and s.status in ('active','completed'));
  delete from availabilities a
   where a.avail_date < p_before
     and not exists (select 1 from requests r join sessions s on s.request_id = r.id
                      where r.avail_id = a.id and s.status in ('active','completed'));
  delete from visits where visit_date < p_before;

  return jsonb_build_object('dry_run', false, 'deleted',
    jsonb_build_object('availabilities', v_avail, 'visits', v_visits, 'requests', v_reqs));
end $$;

-- ----------------------------------------------------------------------
-- my_visits   [etkin kaynak: 044_trip_purpose_and_people_fix.sql]
-- ----------------------------------------------------------------------
create or replace function public.my_visits()
returns table (
  id uuid, airport_code text, destination text, visit_date date,
  time_from time, time_to time, flight_number text, purpose text,
  open_hosts int, people_here int
)
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  return query
  select v.id, v.airport_code::text, v.destination::text, v.visit_date,
         v.time_from, v.time_to, v.flight_number, v.purpose,
         -- bu seyahate uyan acik ilan sayisi
         (select count(*)::int from availabilities a
           where a.active and a.airport_code = v.airport_code
             and a.avail_date = v.visit_date
             and a.time_from < v.time_to and v.time_from < a.time_to
             and a.filled < a.slots
             and a.host_id <> v_uid
             and coalesce(a.visibility,'Public') <> 'Hidden') as open_hosts,
         -- ayni yerde/zamanda kac kisi var (kendim haric)
         (select count(distinct v2.user_id)::int from visits v2
            join users u2 on u2.id = v2.user_id
           where v2.airport_code = v.airport_code
             and v2.visit_date = v.visit_date
             and v2.time_from < v.time_to and v.time_from < v2.time_to
             and v2.user_id <> v_uid
             and coalesce(u2.is_staff,false) = false) as people_here
  from visits v
  where v.user_id = v_uid
  order by v.visit_date desc, v.time_from desc;
end $$;

-- ----------------------------------------------------------------------
-- admin_set_email   [etkin kaynak: 045_admin_edit_email_phone.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_set_email(p_user uuid, p_email text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_old text; v_new text := lower(trim(p_email));
begin
  if v_new is null or v_new = '' then raise exception 'email_required'; end if;
  if v_new !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'email_invalid'; end if;

  select email into v_old from users where id = p_user;
  if not found then raise exception 'user_not_found'; end if;
  if v_old = v_new then return jsonb_build_object('ok', true, 'unchanged', true); end if;

  if exists (select 1 from users where lower(email) = v_new and id <> p_user) then
    raise exception 'email_taken';
  end if;

  -- 1) bizim tablo
  update users set email = v_new, updated_at = now() where id = p_user;

  -- 2) 🔴 Auth tablosu — bu satır olmazsa kullanıcı yeni e-postayla GİREMEZ
  update auth.users
     set email = v_new,
         raw_user_meta_data = coalesce(raw_user_meta_data,'{}'::jsonb) || jsonb_build_object('email', v_new),
         updated_at = now()
   where id = p_user;

  -- E-posta değişti: eski adresin doğrulaması artık yeni adresi kanıtlamaz.
  -- (026'daki telefon mantığının e-posta karşılığı.)
  update verifications
     set email_verified = false, email_verified_at = null
   where user_id = p_user;
  update trust_scores
     set score = greatest(0, score - 10),
         components = coalesce(components,'{}'::jsonb) - 'email',
         updated_at = now()
   where user_id = p_user and (coalesce(components,'{}'::jsonb) ? 'email');

  begin
    insert into notifications (user_id, category, icon, title, body)
    values (p_user, 'system', '✉', 'E-posta adresin güncellendi',
            'Hesabının e-postası ' || v_new || ' olarak değiştirildi. Bundan sonra bu adresle giriş yapacaksın.');
  exception when others then null;
  end;

  return jsonb_build_object('ok', true, 'old', v_old, 'new', v_new, 'reverify_required', true);
end $$;

-- ----------------------------------------------------------------------
-- admin_set_phone   [etkin kaynak: 045_admin_edit_email_phone.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_set_phone(p_user uuid, p_phone text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_old text; v_new text := nullif(trim(p_phone), ''); v_e164 text;
begin
  if not exists (select 1 from users where id = p_user) then raise exception 'user_not_found'; end if;
  select phone into v_old from users where id = p_user;

  -- E.164'e kaba normalize: yalnız rakam + baştaki +
  if v_new is not null then
    v_e164 := regexp_replace(v_new, '[^0-9+]', '', 'g');
    if v_e164 !~ '^\+?[0-9]{7,15}$' then raise exception 'phone_invalid'; end if;
    if left(v_e164,1) <> '+' then v_e164 := '+' || v_e164; end if;
    if exists (select 1 from users where phone_e164 = v_e164 and id <> p_user) then
      raise exception 'phone_taken';
    end if;
  end if;

  update users set phone = v_new, phone_e164 = v_e164, updated_at = now() where id = p_user;

  -- 026 change_phone ile AYNI kural: numara değişti -> doğrulama düşer, -10 güven
  update verifications
     set phone_verified = false, phone_verified_at = null
   where user_id = p_user;
  update trust_scores
     set score = greatest(0, score - 10),
         components = coalesce(components,'{}'::jsonb) - 'phone',
         updated_at = now()
   where user_id = p_user and (coalesce(components,'{}'::jsonb) ? 'phone');

  begin
    insert into notifications (user_id, category, icon, title, body)
    values (p_user, 'system', '📱', 'Telefon numaran güncellendi',
            'Numaran değiştiği için tekrar doğrulaman gerekiyor.');
  exception when others then null;
  end;

  return jsonb_build_object('ok', true, 'old', v_old, 'new', v_new,
                            'e164', v_e164, 'reverify_required', true);
end $$;

-- ----------------------------------------------------------------------
-- host_requests   [etkin kaynak: 050_host_requests_flight.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.host_requests()
returns table (
  id uuid, guest_id uuid, avail_id uuid, status text, intro_message text,
  created_at timestamptz,
  guest_name text, guest_photo text, guest_profession text,
  guest_score int, guest_badge text, guest_id_verified boolean,
  guest_phone_verified boolean, guest_linkedin boolean,
  guest_sessions int, guest_rating numeric, guest_rating_count int,
  same_flight boolean, same_purpose boolean, guest_fit int,
  lounge_name text, avail_date date, time_from time, time_to time, flight_number text
)
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  return query
  with base as (
    select r.id, r.guest_id, r.avail_id, r.status::text as st, r.intro_message, r.created_at,
           a.lounge_name, a.avail_date, a.time_from, a.time_to,
           a.flight_number as host_flight, a.airport_code,
           p.name as gname, p.profession as gprof, p.bio as gbio,
           p.photo_url, coalesce(p.photo_connections_only,false) as photo_priv,
           p.linkedin_url, p.linkedin_verified,
           coalesce(ts.score,0) as gscore, ts.badge as gbadge,
           coalesce(v.id_verified,false) as gid,
           coalesce(v.phone_verified,false) as gphone,
           (select count(*)::int from sessions s2 join requests r2 on r2.id = s2.request_id
             where s2.status='completed' and (r2.guest_id = r.guest_id or r2.host_id = r.guest_id)) as gsessions,
           (select avg(score)::numeric from ratings where rated_id = r.guest_id) as grating,
           (select count(*)::int from ratings where rated_id = r.guest_id) as grating_n,
           -- misafirin ayni havalimani/zamandaki seyahati
           (select vs.flight_number from visits vs
             where vs.user_id = r.guest_id and vs.airport_code = a.airport_code
               and vs.visit_date = a.avail_date
               and vs.time_from < a.time_to and a.time_from < vs.time_to
             limit 1) as gflight,
           (select vs.purpose from visits vs
             where vs.user_id = r.guest_id and vs.airport_code = a.airport_code
               and vs.visit_date = a.avail_date
               and vs.time_from < a.time_to and a.time_from < vs.time_to
             limit 1) as gpurpose,
           -- host'un kendi seyahat amaci (ayni amac karsilastirmasi icin)
           (select vs.purpose from visits vs
             where vs.user_id = v_uid and vs.airport_code = a.airport_code
               and vs.visit_date = a.avail_date limit 1) as hpurpose,
           (select p2.profession from profiles p2 where p2.user_id = v_uid) as hprof
      from requests r
      join availabilities a on a.id = r.avail_id
      join profiles p on p.user_id = r.guest_id
      left join trust_scores ts on ts.user_id = r.guest_id
      left join verifications v on v.user_id = r.guest_id
     where r.host_id = v_uid
       and r.status in ('pending','accepted')
  )
  select b.id, b.guest_id, b.avail_id, b.st, b.intro_message, b.created_at,
         b.gname,
         case when b.photo_url is not null and (
                b.photo_priv = false
                or exists (select 1 from connection_requests cr where cr.status='accepted'
                           and ((cr.from_id=v_uid and cr.to_id=b.guest_id)
                             or (cr.from_id=b.guest_id and cr.to_id=v_uid)))
              ) then b.photo_url else null end,
         b.gprof, b.gscore, b.gbadge, b.gid, b.gphone,
         (b.linkedin_url is not null and b.linkedin_url <> ''),
         b.gsessions, b.grating, b.grating_n,
         (b.gflight is not null and b.host_flight is not null
          and upper(b.gflight) = upper(b.host_flight)) as same_flight,
         (b.gpurpose is not null and b.hpurpose is not null
          and b.gpurpose = b.hpurpose) as same_purpose,
         -- guest_fit: MISAFIRIN BU ILANA uyumu (30-99)
         least(99, greatest(30,
           30
           + (case when b.gscore >= 70 then 18 when b.gscore >= 50 then 10 else 0 end)
           + (case when b.gid then 14 else 0 end)
           + (case when b.gphone then 6 else 0 end)
           + (case when b.gflight is not null and b.host_flight is not null
                    and upper(b.gflight) = upper(b.host_flight) then 12 else 0 end)
           + (case when b.gpurpose is not null and b.hpurpose is not null
                    and b.gpurpose = b.hpurpose then 8 else 0 end)
           + (case when b.hprof is not null and b.gprof is not null
                    and (b.gprof ilike '%'||b.hprof||'%' or b.hprof ilike '%'||b.gprof||'%') then 8 else 0 end)
           + (case when b.gsessions >= 3 then 8 when b.gsessions >= 1 then 4 else 0 end)
           + (case when coalesce(b.grating_n,0) >= 3 and b.grating >= 4.5 then 8
                   when coalesce(b.grating_n,0) >= 3 and b.grating >= 4.0 then 4 else 0 end)
           + (case when length(coalesce(b.gbio,'')) >= 40 then 4 else 0 end)
         ))::int as guest_fit,
         b.lounge_name, b.avail_date, b.time_from, b.time_to,
         b.gflight as flight_number                                     -- 050/#26: misafirin uçuşu
  from base b
  order by coalesce(b.st = 'pending', false) desc, guest_fit desc, b.created_at desc;
end $$;

-- ----------------------------------------------------------------------
-- active_campaigns   [etkin kaynak: 049_discovery_safety_phone_delete.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.active_campaigns()
returns jsonb language sql security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id, 'title', c.title, 'description', c.description,
    'ends_at', c.ends_at, 'joinable', coalesce(c.joinable, true),
    'joined', exists (select 1 from campaign_participations cp
                      where cp.campaign_id = c.id and cp.user_id = auth.uid())
  ) order by c.created_at desc), '[]'::jsonb)
  from promo_campaigns c
  where c.active and (c.ends_at is null or c.ends_at >= current_date);
$$;

-- ----------------------------------------------------------------------
-- join_campaign   [etkin kaynak: 049_discovery_safety_phone_delete.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.join_campaign(p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_title text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select title into v_title from promo_campaigns
   where id = p_id and active and coalesce(joinable, true)          -- 049/#23
     and (ends_at is null or ends_at >= current_date);
  if v_title is null then raise exception 'campaign_not_found_or_ended'; end if;
  insert into campaign_participations (campaign_id, user_id) values (p_id, v_uid)
    on conflict (campaign_id, user_id) do nothing;
  insert into audit_log (action, entity_type, entity_id, after_data)
  values ('app.campaign_join', 'promo_campaigns', p_id,
          jsonb_build_object('user_id', v_uid, 'campaign', v_title));
  return jsonb_build_object('ok', true);
end $$;

