  values (p_title, p_description, p_ends, p_admin) returning id;
$$;

-- ----------------------------------------------------------------------
-- redeem_promo_code   [etkin kaynak: 048_promo_campaigns.sql]
-- ----------------------------------------------------------------------
create or replace function public.redeem_promo_code(p_code text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid; v_type text; v_amount int; v_max int; v_used int; v_bal int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select id, reward_type, amount, max_uses, used_count
    into v_id, v_type, v_amount, v_max, v_used
    from promo_codes
   where upper(code) = upper(trim(p_code)) and active
     and (expires_at is null or expires_at >= current_date)
   for update;
  if v_id is null then raise exception 'invalid_or_expired_code'; end if;
  if v_max is not null and v_used >= v_max then raise exception 'code_limit_reached'; end if;
  if exists (select 1 from promo_redemptions where code_id = v_id and user_id = v_uid) then
    raise exception 'code_already_used';
  end if;

  insert into promo_redemptions (code_id, user_id) values (v_id, v_uid);
  update promo_codes set used_count = used_count + 1 where id = v_id;

  if v_type = 'points' then
    insert into points_ledger (user_id, delta, reason, ref_id)
    values (v_uid, v_amount, 'promo_code', v_id);
  else
    select coalesce((select balance_after from credit_ledger
                     where user_id = v_uid order by created_at desc limit 1), 0) into v_bal;
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    values (v_uid, v_amount, 'promo_code', v_id, v_bal + v_amount);
  end if;

  insert into audit_log (action, entity_type, entity_id, after_data)
  values ('app.promo_redeem', 'promo_codes', v_id,
          jsonb_build_object('user_id', v_uid, 'reward', v_type, 'amount', v_amount));

  return jsonb_build_object('ok', true, 'reward_type', v_type, 'amount', v_amount);
end $$;

-- ----------------------------------------------------------------------
-- admin_create_promo_code   [etkin kaynak: 048_promo_campaigns.sql]
-- ----------------------------------------------------------------------
create or replace function public.admin_create_promo_code(
  p_code text, p_type text, p_amount int, p_max int, p_expires date, p_admin uuid
) returns uuid language sql security definer set search_path = public as $$
  insert into promo_codes (code, reward_type, amount, max_uses, expires_at, created_by)
  values (upper(trim(p_code)), p_type, p_amount, p_max, p_expires, p_admin) returning id;
$$;

-- ----------------------------------------------------------------------
-- phone_in_use   [etkin kaynak: 253_guvenlik_kapanisi.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.phone_in_use(p_phone text)
returns boolean
language plpgsql stable security definer set search_path = public as $piu253$
declare v_ben uuid := auth.uid(); v_say int;
begin
  if v_ben is null then raise exception 'not_authenticated'; end if;
  -- 🔴 Saatte 10 sorgu. Kayıt akışının ihtiyacı 1-2; tarama yapanın
  -- ihtiyacı binlerce. Aradaki fark kapının kendisidir.
  select count into v_say from rate_limits
   where user_id = v_ben and action = 'phone_in_use'
     and window_start = date_trunc('hour', now());
  if coalesce(v_say, 0) >= 10 then raise exception 'too_many_requests'; end if;
  insert into rate_limits (user_id, action, window_start, count)
  values (v_ben, 'phone_in_use', date_trunc('hour', now()), 1)
  on conflict (user_id, action, window_start) do update set count = rate_limits.count + 1;

  return exists (
    select 1 from users u
     where u.deleted_at is null and u.id <> v_ben
       and regexp_replace(coalesce(u.phone,''), '\D', '', 'g')
         = regexp_replace(coalesce(p_phone,''), '\D', '', 'g')
       and coalesce(p_phone,'') <> '');
end $piu253$;

grant execute on function public.phone_in_use(text) to authenticated;

-- ⚠️ `phone_in_use` STABLE değil artık (yazıyor). STABLE bırakmak
-- PostgreSQL'in çağrıyı atlamasına yol açabilirdi — yani sayaç
-- artmayabilirdi. Bu yüzden VOLATILE:
alter function public.phone_in_use(text) volatile;

-- ════════════════════════════════════════════════════════════════════════
-- §9 — `my_plan` HER ÇAĞRIDA PATLIYORDU (42883)
--
--   ERROR: operator does not exist: text = plan_type
--   CONTEXT: my_plan(uuid) line 52 → select * from plan_catalog
--            where plan::text = v_etkin
--
-- `v_etkin` `plan_type` tipinde bir değişken ama içine `::text` cast
-- edilmiş değer atanıyor. `plan_kredisi_yerlestir` hatayı yutuyor ve
-- `{"ok":false}` dönüyordu — yani AYLIK KREDİ YÜKLEMESİ sessizce
-- çalışmıyordu.
--
-- 🆕 SINIF: "BİR HATAYI YUTAN İŞ, ÇALIŞMADIĞINI DA YUTAR."
-- ════════════════════════════════════════════════════════════════════════

do $mp253$
declare r record; v_yeni text; v_say int := 0;
begin
  for r in
    select p.oid, p.proname, pg_get_functiondef(p.oid) as tanim
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.prokind = 'f'
       and pg_get_functiondef(p.oid) like '%plan::text = v_etkin%'
  loop
    v_yeni := replace(r.tanim, 'plan::text = v_etkin', 'plan = v_etkin');
    execute v_yeni;
    v_say := v_say + 1;
    raise notice '253 §9: % icindeki tip uyusmazligi duzeltildi.', r.proname;
  end loop;
  if v_say = 0 then raise notice '253 §9: kalip bulunamadi — dokunulmadi.'; end if;
end $mp253$;

-- ════════════════════════════════════════════════════════════════════════
-- §10 — `anon` ROLÜNDEN İŞE YARAMAYAN YAZMA HAKLARI
--
-- Bugün zararsız (politikalar `auth.uid()` istiyor, `anon`da o NULL).
-- Ama bir politikanın şartı gevşediği gün kapı hazır bekliyor olur.
-- ════════════════════════════════════════════════════════════════════════

do $an253$
declare r record;
begin
  for r in
    select table_name, privilege_type
      from information_schema.role_table_grants
     where grantee = 'anon' and table_schema = 'public'
       and privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')
       -- `waitlist` bilinçli: giriş yapmamış ziyaretçi bekleme listesine
       -- yazabilmeli (`with check (consent = true)` koruyor).
       and table_name <> 'waitlist'
  loop
    execute format('revoke %s on public.%I from anon', r.privilege_type, r.table_name);
  end loop;
end $an253$;

-- ════════════════════════════════════════════════════════════════════════
-- §11 — MİGRATION DEFTERİ: TAHMİN ETMEYİ BIRAKIYORUZ
--
-- Bu projede hangi SQL'in koştuğu bugüne kadar İZDEN çıkarılıyordu ve
-- 278 dosyanın 49'u iz bırakmıyordu. Bundan sonra her dosya kendini
-- yazsın; tahmin bitsin.
--
-- 🆕 SINIF: "TESPİT EDİLEMEYENİ TAHMİN ETMEK YERİNE TESPİT EDİLEBİLİR YAP."
-- ════════════════════════════════════════════════════════════════════════

-- Defter §0'da kuruldu. Bundan sonraki HER migration son satırında
-- `select public.migration_kaydet('<dosya adı>');` çağırmalı —
-- `sqlcheck.py` bunu artık zorunlu tutuyor.
revoke all on schema_migrations from anon;
revoke all on schema_migrations from authenticated;
grant select, insert, update on schema_migrations to service_role;

select public.migration_kaydet('253_guvenlik_kapanisi.sql');

-- ════════════════════════════════════════════════════════════════════════
-- §12 — NÖBETÇİ
-- ════════════════════════════════════════════════════════════════════════

do $n253$
declare
  v_h text[] := '{}';
  v_n int; v_r record; v_b boolean; v_ben uuid; v_oteki uuid;
begin
  begin
    -- (1) Hiçbir görünüm istemciye açık kalmamalı.
    select count(*) into v_n
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname='public' and c.relkind in ('v','m')
       and has_table_privilege('anon', c.oid, 'select');
    if v_n > 0 then
      v_h := v_h || format('%s gorunum hala ANON`a ACIK', v_n)::text;
    end if;

    -- `authenticated`e açık kalan TEK görünüm `user_balances` olmalı VE
    -- o da `security_invoker` ile RLS'in altında olmalı. İkisini birlikte
    -- ölçüyoruz: hak vermek yetmez, hakkın altında filtre olmalı.
    select count(*) into v_n
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname='public' and c.relkind in ('v','m')
       and has_table_privilege('authenticated', c.oid, 'select')
       and c.relname <> 'user_balances';
    if v_n > 0 then
      v_h := v_h || format('%s gorunum authenticated`e ACIK (yalniz user_balances olmali)', v_n)::text;
    end if;
    if to_regclass('public.user_balances') is not null then
      if not has_table_privilege('authenticated', 'public.user_balances', 'select') then
        v_h := v_h || 'user_balances istemciye KAPALI — app kredi/puan gosteremez'::text;
      end if;
      if not exists (select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
                      where n.nspname='public' and c.relname='user_balances'
                        and array_to_string(c.reloptions,',') like '%security_invoker=%on%') then
        v_h := v_h || 'user_balances acik AMA security_invoker KAPALI — RLS atlanir'::text;
      end if;
    end if;

    -- (2) Varsayılan haklar: yeni tablo `anon`a okunur DOĞMAMALI.
    -- ════════════════════════════════════════════════════════════
    -- 🔴 KATALOĞU OKUMAK YANLIŞ SORUYU SORMAKTI.
    --
    -- İlk iki denemem `pg_default_acl`i tarıyordu ve Gökberk'in
    -- veritabanında üç kayıt buldu — üçü de `supabase_admin`in.
    -- Ama `ALTER DEFAULT PRIVILEGES FOR ROLE r`, "r BİR TABLO
    -- OLUŞTURURSA ne olsun" demektir. Bizim migration'larımız
    -- `supabase_admin` olarak değil, kendi rolümüzle tablo oluşturuyor.
    -- Yani o kayıtlar BİZİM tablolarımıza HİÇ uygulanmıyordu.
    --
    -- Nöbetçi var olmayan bir kusuru bildiriyordu — ve daha kötüsü,
    -- gerçek kusuru (bizim rolümüzün kaydı) aynı gürültünün içinde
    -- gizleyebilirdi.
    --
    -- Doğru soru katalogda değil: "ŞİMDİ bir tablo oluşturursam,
    -- `anon` onu okuyabilir mi?" Bu soruyu SORMAK yerine ÖLÇÜYORUZ:
    -- bir deneme tablosu açılıyor, `anon`un hakkı ölçülüyor, tablo
    -- siliniyor. Hangi rolün hangi kaydı verdiği önemsiz — sonuç
    -- doğrudan görülüyor.
    --
    -- 🆕 SINIF: "BİR AYARIN DOĞRU OLUP OLMADIĞINI KATALOGDAN OKUMA —
    -- O AYARIN ETKİSİNİ ÜRET VE ÖLÇ. KATALOG NİYETİ, DENEY SONUCU
    -- SÖYLER."
    -- ════════════════════════════════════════════════════════════
    begin
      execute 'create table public.__dacl_sonda_253 (x int)';
      if has_table_privilege('anon', 'public.__dacl_sonda_253', 'select') then
        v_h := v_h || ('yeni tablolar hala anon''a OKUNUR doguyor — DENEY: '
               || 'public.__dacl_sonda_253 olusturuldu ve anon SELECT alabildi. '
               || '`alter default privileges for role ' || current_user
               || ' in schema public revoke select on tables from anon, authenticated` '
               || 'calistir.')::text;
      end if;
      if has_table_privilege('authenticated', 'public.__dacl_sonda_253', 'select') then
        v_h := v_h || ('yeni tablolar hala authenticated''a OKUNUR doguyor (ayni deney)')::text;
      end if;
      execute 'drop table public.__dacl_sonda_253';
    exception when others then
      begin execute 'drop table if exists public.__dacl_sonda_253'; exception when others then null; end;
      v_h := v_h || ('varsayilan hak DENEYI yapilamadi: ' || sqlerrm)::text;
    end;

    -- (3) change_plan istemciye kapalı olmalı.
    if has_function_privilege('authenticated', 'public.change_plan(plan_type)', 'execute') then
      v_h := v_h || 'change_plan hala istemciye ACIK — odemesiz plan'::text;
    end if;

    -- (4) send_otp kodu yanıtta VERMEMELİ.
    if (select pg_get_functiondef(to_regprocedure('public.send_otp(text)')::oid))
       like '%demo_code%' then
      v_h := v_h || 'send_otp hala demo_code donduruyor'::text;
    end if;

    -- (5) Sahiplik: `coalesce(p_user, auth.uid())` kalıntısı KALMAMALI.
    select count(*) into v_n
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname='public' and p.prokind = 'f'
       and pg_get_functiondef(p.oid) ~ 'coalesce\(\s*p_user(_id)?\s*,\s*auth\.uid\(\)\s*\)';
    if v_n > 0 then
      v_h := v_h || format('%s fonksiyonda sahipliksiz kalip DURUYOR', v_n)::text;
    end if;

    -- (6) `kimlik()` gerçekten reddediyor mu — DAVRANIŞ ölçümü.
    begin
      -- 🔴 YÖNETİCİ SEÇMEMEK ŞART: `kimlik()` yöneticiye bilerek izin veriyor.
      -- İlk denemede sıradaki ilk kullanıcıyı seçtim ve nöbetçi "kabul etti"
      -- dedi — kapı çalışıyordu, ÖLÇÜM yanlıştı.
      -- 🆕 SINIF: "BİR KAPIYI, ANAHTARI OLAN BİRİYLE DENEMEK KAPIYI DEĞİL
      -- ANAHTARI ÖLÇER."
      select u.id into v_ben from users u
       where u.deleted_at is null
         and not exists (select 1 from admin_roles a where a.user_id = u.id)
       order by u.created_at limit 1;
      select u.id into v_oteki from users u
       where u.deleted_at is null and u.id <> v_ben
       order by u.created_at desc limit 1;
      if v_ben is null or v_oteki is null then
        v_h := v_h || 'olcum icin iki yonetici-olmayan kullanici bulunamadi'::text;
      end if;
      perform set_config('request.jwt.claims',
        json_build_object('sub', v_ben::text)::text, true);
      begin
        perform public.kimlik(v_oteki);
        v_h := v_h || 'kimlik() BASKASININ uuid`ini kabul etti'::text;
      exception when others then
        if sqlerrm not like '%baskasinin_verisi%' then
          v_h := v_h || ('kimlik() beklenmeyen hata: ' || sqlerrm)::text;
        end if;
      end;
      -- Kendi kimliğim geçmeli.
      if public.kimlik(null) is null then
        v_h := v_h || 'kimlik(null) kendi kimligimi DONDURMEDI'::text;
      end if;
      perform set_config('request.jwt.claims', '', true);
    exception when others then
      perform set_config('request.jwt.claims', '', true);
      v_h := v_h || ('kimlik olcumu coktu: ' || sqlerrm)::text;
    end;

    -- (7) Kolon kapıları.
    if has_column_privilege('authenticated', 'public.profiles', 'linkedin_verified', 'update')
       or has_column_privilege('authenticated', 'public.profiles', 'founding_host_no', 'update')
       or has_column_privilege('authenticated', 'public.users'::regclass::text, 'gender', 'update') then
      v_h := v_h || 'sunucuya ait kolonlar hala istemciden YAZILABILIR'::text;
    end if;

    -- (7b) `contact_email` artık `profiles` üzerinde OLMAMALI.
    if exists (select 1 from information_schema.columns
                where table_schema='public' and table_name='profiles'
                  and column_name='contact_email') then
      v_h := v_h || 'contact_email hala profiles uzerinde — herkese acik tabloda e-posta'::text;
    end if;
    if has_table_privilege('anon', 'public.user_contact', 'select') then
      v_h := v_h || 'user_contact anon`a ACIK'::text;
    end if;

    -- (8) Görünürlük yüklemi gerçekten ayırt ediyor mu.
    if public.profil_gorunur_mu(null) then
      v_h := v_h || 'profil_gorunur_mu(null) TRUE dondu'::text;
    end if;

    -- (9) 🔴 ARZ KAYBI OLMAMALI: keşif RPC'leri SECURITY DEFINER olduğu
    -- için RLS daralmasından ETKİLENMEMELİ. Sayıyla kanıtla.
    select count(*) into v_n from public.discover_availabilities();
    if v_n = 0 then
      v_h := v_h || 'kesif ilan sayisi 0 — RLS daralmasi arzi VURMUS olabilir'::text;
    end if;

    -- (10) chat_channels: tek politika kalmalı ve `connection_id is null`
    -- deliği gitmiş olmalı.
    if exists (select 1 from pg_policies where schemaname='public' and tablename='chat_channels'
                and qual like '%connection_id IS NULL%') then
      v_h := v_h || 'chat_channels`de `connection_id IS NULL` deligi DURUYOR'::text;
    end if;

    -- (11) Defter yazıyor mu.
    if not exists (select 1 from schema_migrations
                    where dosya = '253_guvenlik_kapanisi.sql' and kaynak = 'migration') then
      v_h := v_h || 'migration defterine YAZILMADI'::text;
    end if;

    raise exception 'GERI_AL_253';
  exception when others then
    if sqlerrm <> 'GERI_AL_253' then
      v_h := v_h || ('olcum coktu: ' || sqlerrm);
    end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '253 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '253 OK · gorunumler kapali · plan odemesiz degistirilemez · otp kodu sizmiyor · sahiplik kapisi 23 fonksiyonda · gorunurluk uygulaniyor';
end $n253$;

-- 🔴 `kimlik` ve `profil_gorunur_mu` YÜZEYE YAZILMADI — bilerek.
-- Nöbetçi ilk denemede haklı olarak kırmızı yandı: ikisi de app tarafından
-- ÇAĞRILMIYOR. `kimlik` SECURITY DEFINER gövdelerin içinden, o gövdelerin
-- sahibi haklarıyla çalışıyor; `profil_gorunur_mu` ise RLS politikasından
-- çağrılıyor (o yüzden `authenticated` hakkı ŞART, ama bir "ekran ucu" değil).
-- 🆕 SINIF: "BİR FONKSİYONU İSTEMCİ YÜZEYİNE YAZMAK, ONU İSTEMCİ ÇAĞIRIYOR
-- DEMEK DEĞİL — YÜZEY BİR SÖZDÜR, TUTULMAZSA KAYIT YALAN OLUR."
revoke all on function public.kimlik(uuid) from authenticated;

insert into rpc_client_surface (fn_name, client, note) values
  ('iletisim_epostam', 'app', 'Iletisim e-postasi — profiles`tan cikarildi (253)'),
  ('iletisim_epostam_yaz', 'app', 'Iletisim e-postasini yaz (253)')
on conflict (fn_name) do update set note = excluded.note;

commit;

select '253 KURULDU' as sonuc,
       (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
         where n.nspname='public' and c.relkind in ('v','m')
           and has_table_privilege('anon', c.oid, 'select'))            as acik_gorunum,
       (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
         where n.nspname='public' and p.prokind = 'f'
           and pg_get_functiondef(p.oid) ~ 'coalesce\(\s*p_user(_id)?\s*,\s*auth\.uid\(\)\s*\)') as sahipliksiz;

-- ----------------------------------------------------------------------
-- delete_my_account   [etkin kaynak: 282_ban_ve_kvkk_silme.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.delete_my_account()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_email text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select email into v_email from users where id = v_uid;
  update users set deleted_at = now() where id = v_uid and deleted_at is null;
  update availabilities set active = false where host_id = v_uid;
  -- 282/B2: SLA kuyruğuna DÜŞ. `bo_silme_talepleri` yalnız bu tabloyu
  -- okuyor; buraya yazmayan bir silme talebi BO için yoktur.
  insert into deletion_requests (email, note, source, status, matched_user_id)
  select coalesce(v_email, v_uid::text), 'uygulama içi "Hesabı sil"', 'app', 'open', v_uid
   where not exists (select 1 from deletion_requests
                      where matched_user_id = v_uid and status in ('open','in_progress'));
  insert into audit_log (action, entity_type, entity_id, after_data)
  values ('app.account_delete', 'users', v_uid, jsonb_build_object('requested_by','user'));
  return jsonb_build_object('ok', true, 'sla_days', 30);
end $$;

-- ----------------------------------------------------------------------
-- share_session_status   [etkin kaynak: 052_session_live_status.sql]
-- ----------------------------------------------------------------------
create or replace function public.share_session_status(p_session_id uuid, p_status text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_host uuid; v_guest uuid; v_active boolean;
begin
  select r.host_id, r.guest_id, (s.status = 'active')
    into v_host, v_guest, v_active
  from sessions s join requests r on r.id = s.request_id
  where s.id = p_session_id;

  if v_host is null then raise exception 'session_not_found'; end if;
  if not v_active then raise exception 'session_not_active'; end if;
  if v_uid not in (v_host, v_guest) then raise exception 'not_a_participant'; end if;
  if coalesce(trim(p_status), '') = '' then raise exception 'empty_status'; end if;

  if v_uid = v_host then
    update sessions set host_status = p_status, host_status_ts = now() where id = p_session_id;
  else
    update sessions set guest_status = p_status, guest_status_ts = now() where id = p_session_id;
  end if;

  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- waiting_demand   [etkin kaynak: 057_waiting_demand_rpc.sql]
-- ----------------------------------------------------------------------
create or replace function public.waiting_demand(p_airport text, p_date date default null)
returns int language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_n int;
begin
  select count(distinct vs.user_id) into v_n
    from visits vs
    join users gu on gu.id = vs.user_id
   where vs.airport_code = p_airport
     and vs.visit_date >= current_date
     and (p_date is null or vs.visit_date = p_date)
     and vs.user_id <> v_uid
     and coalesce(gu.is_staff,false) = false
     and gu.deleted_at is null;
  return coalesce(v_n, 0);
end $$;

-- ----------------------------------------------------------------------
-- log_client_error   [etkin kaynak: 063_error_logging.sql]
-- ----------------------------------------------------------------------
create or replace function public.log_client_error(
  p_screen   text,
  p_message  text,
  p_code     text  default null,
  p_version  text  default null,
  p_platform text  default null,
  p_context  jsonb default null
) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_recent int;
begin
  if v_uid is null then return; end if;          -- anonim log tutmuyoruz

  -- Şişme koruması: 10 dakikada 20 kayıt üstü sessizce yok sayılır
  select count(*) into v_recent from app_errors
   where user_id = v_uid and created_at > now() - interval '10 minutes';
  if v_recent >= 20 then return; end if;

  insert into app_errors (user_id, platform, app_version, screen, code, message, context)
  values (v_uid,
          left(coalesce(p_platform,''), 20),
          left(coalesce(p_version,''), 20),
          left(coalesce(p_screen,'?'), 80),
          left(coalesce(p_code,''), 60),
          left(coalesce(p_message,'(bos)'), 500),
          p_context);
exception when others then
  -- Log yazamamak uygulamayı ASLA etkilememeli.
  return;
end $$;

-- ----------------------------------------------------------------------
-- bo_error_summary   [etkin kaynak: 063_error_logging.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_error_summary(p_days int default 7)
returns table (
  screen text, code text, message text,
  adet bigint, etkilenen_kullanici bigint,
  ilk_gorulme timestamptz, son_gorulme timestamptz
)
language sql security definer set search_path = public as $$
  select e.screen, e.code, e.message,
         count(*)                         as adet,
         count(distinct e.user_id)        as etkilenen_kullanici,
         min(e.created_at)                as ilk_gorulme,
         max(e.created_at)                as son_gorulme
    from app_errors e
   where e.created_at > now() - make_interval(days => greatest(p_days,1))
   group by e.screen, e.code, e.message
   order by count(*) desc, max(e.created_at) desc
   limit 200;
$$;

-- ----------------------------------------------------------------------
-- sync_availability_filled   [etkin kaynak: 077_session_autostart_intro_slots.sql]
-- ----------------------------------------------------------------------
create or replace function public.sync_availability_filled()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_av uuid;
begin
  v_av := coalesce(new.avail_id, old.avail_id);
  if v_av is null then return coalesce(new, old); end if;
  -- ⚠️ TAVAN ŞART: availabilities tablosunda `check (filled <= slots)`
  -- kısıtı var. Geçmişte sayaç bozulduğu için bazı ilanlarda slots=2 iken
  -- ÜÇ kabul edilmiş/tamamlanmış istek birikmiş olabiliyor (canlıda oldu:
  -- slots=2, hesaplanan 3 → kısıt ihlali, migration patladı). Hesaplanan
  -- değer slot sayısıyla SINIRLANIR; aşım BO'da anomali olarak görülebilir
  -- (aşağıdaki doğrulama sorgusu listeler).
  update availabilities a
     set filled = least(
           a.slots,
           (select count(*) from requests r
             where r.avail_id = v_av
               and r.status in ('accepted','completed'))
         ),
         updated_at = now()
   where a.id = v_av;
  return coalesce(new, old);
end $$;

-- ----------------------------------------------------------------------
-- is_contact_verified   [etkin kaynak: 079_email_otp_contact_verification.sql]
-- ----------------------------------------------------------------------
create or replace function public.is_contact_verified(p_user uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(bool_or(phone_verified) or bool_or(email_verified), false)
    from verifications where user_id = p_user
$$;

-- ----------------------------------------------------------------------
-- verify_email_contact   [etkin kaynak: 079_email_otp_contact_verification.sql]
-- ----------------------------------------------------------------------
create or replace function public.verify_email_contact()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_conf timestamptz; v_email text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select email_confirmed_at, email into v_conf, v_email from auth.users where id = v_uid;
  if v_conf is null then raise exception 'email_not_confirmed'; end if;

  insert into verifications (user_id, email_verified, email_verified_at)
  values (v_uid, true, now())
  on conflict (user_id) do update set email_verified = true, email_verified_at = now();

  perform public.recompute_trust(v_uid);
  return jsonb_build_object('ok', true, 'email', v_email);
end $$;

-- ----------------------------------------------------------------------
-- start_session_request   [etkin kaynak: 080_session_lifecycle.sql]
-- ----------------------------------------------------------------------
create or replace function public.start_session_request(p_request_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); v_req requests%rowtype; v_s sessions%rowtype;
  v_is_host boolean; v_both boolean; v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_req from requests where id = p_request_id;
  if not found then raise exception 'request_not_found'; end if;
  if v_uid not in (v_req.host_id, v_req.guest_id) then raise exception 'not_party'; end if;
  if v_req.status <> 'accepted' then raise exception 'request_not_accepted'; end if;
  v_is_host := (v_uid = v_req.host_id);

  select * into v_s from sessions where request_id = p_request_id for update;
  if not found then
    insert into sessions (request_id, status,
                          host_started_at, guest_started_at)
    values (p_request_id, 'pending',
            case when v_is_host then now() end,
            case when not v_is_host then now() end)
    returning * into v_s;
    -- karşı tarafa "seni bekliyor" bildirimi
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (case when v_is_host then v_req.guest_id else v_req.host_id end,
            'sessions', 'Oturum başlatılmayı bekliyor',
            'Karşı taraf buluştuğunuzu işaretledi. Sen de onaylayınca oturum başlar.',
            'session', v_s.id);
    return jsonb_build_object('ok', true, 'id', v_s.id, 'status', 'pending', 'both', false);
  end if;

  if v_s.status = 'active' then
    return jsonb_build_object('ok', true, 'id', v_s.id, 'status', 'active', 'both', true);
  end if;
  if v_s.status <> 'pending' then raise exception 'session_closed'; end if;

  update sessions
     set host_started_at  = case when v_is_host then coalesce(host_started_at, now()) else host_started_at end,
         guest_started_at = case when not v_is_host then coalesce(guest_started_at, now()) else guest_started_at end
   where id = v_s.id
   returning * into v_s;

  v_both := v_s.host_started_at is not null and v_s.guest_started_at is not null;
  if v_both then
    update sessions
       set status = 'active', started_at = now(),
           cancel_grace_until = now() + interval '5 minutes'
     where id = v_s.id;
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    select u, 'sessions', 'Oturum başladı ⏱',
           'İlk 5 dakika içinde iptal edersen kredin iade edilir.', 'session', v_s.id
      from unnest(array[v_req.host_id, v_req.guest_id]) u;
  end if;

  return jsonb_build_object('ok', true, 'id', v_s.id,
                            'status', case when v_both then 'active' else 'pending' end,
                            'both', v_both);
end $$;

-- ----------------------------------------------------------------------
-- cancel_session   [etkin kaynak: 080_session_lifecycle.sql]
-- ----------------------------------------------------------------------
create or replace function public.cancel_session(p_session_id uuid, p_reason text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); v_s sessions%rowtype; v_req requests%rowtype;
  v_late boolean; v_bal int; v_other uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_s from sessions where id = p_session_id for update;
  if not found then raise exception 'session_not_found'; end if;
  select * into v_req from requests where id = v_s.request_id;
  if v_uid not in (v_req.host_id, v_req.guest_id) then raise exception 'not_party'; end if;
  if v_s.status not in ('pending','active') then raise exception 'session_closed'; end if;
  v_other := case when v_uid = v_req.host_id then v_req.guest_id else v_req.host_id end;

  -- GEÇ İPTAL: oturum aktif VE 5 dakikalık pencere kapandıysa
  v_late := (v_s.status = 'active'
             and v_s.cancel_grace_until is not null
             and now() > v_s.cancel_grace_until);

  update sessions
     set status = 'cancelled', cancelled_by = v_uid,
         cancel_reason = coalesce(nullif(trim(p_reason),''), case when v_late then 'late_cancel' else 'cancelled' end),
         completed_at = now()
   where id = p_session_id;
  update requests set status = 'cancelled' where id = v_s.request_id;
  -- slot iadesi: trg_requests_sync_filled otomatik

  if v_late then
    -- Kredi YANAR (misafirin escrow'u kullanılmış sayılır) ve iptal EDENİN
    -- güveni düşer. Karşı taraf hiçbir şey kaybetmez.
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    select v_req.guest_id, 0, 'late_cancel_forfeit', p_session_id, coalesce(sum(delta),0)
      from credit_ledger where user_id = v_req.guest_id;
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_other, 'sessions', 'Oturum iptal edildi',
            'Karşı taraf oturumu geç iptal etti. Bu durum güven puanına yansıdı; sen etkilenmedin.',
            'session', p_session_id);
  else
    -- Serbest iptal: kredi iade, ceza yok.
    select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_req.guest_id;
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    values (v_req.guest_id, 1, 'session_cancel_refund', p_session_id, v_bal + 1);
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (v_other, 'sessions', 'Oturum iptal edildi',
            'Plan değişmiş. Kredi iade edildi, kimsenin puanı etkilenmedi.',
            'session', p_session_id);
  end if;

  perform public.recompute_trust(v_uid);
  perform public.recompute_trust(v_other);
  return jsonb_build_object('ok', true, 'late', v_late);
end $$;

-- ----------------------------------------------------------------------
-- expire_stale_sessions   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ⚠ Bu fonksiyon 6 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.expire_stale_sessions(p_kaynak text DEFAULT 'uygulama'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req int := 0; v_sess int := 0;
  v_son timestamptz;
  v_sonuc jsonb;
begin
  -- ── FREN (298) ────────────────────────────────────────────────────
  -- `for update` ile alıyoruz: iki istemci aynı anda çağırırsa ikincisi
  -- birincinin damgasını bekler ve "atlandi" döner. pg_cron ile uygulama
  -- tetiği AYNI FRENİ paylaşır — ikisi birden açık olsa bile gövde
  -- 5 dakikada bir koşar.
  select son_kosum into v_son from public.supurge_damgasi
   where ad = 'expire_stale_sessions' for update;

  if v_son is not null and v_son > now() - interval '5 minutes' then
    return jsonb_build_object('ok', true, 'durum', 'atlandi',
                              'kaynak', p_kaynak,
                              'sonraki', v_son + interval '5 minutes');
  end if;

  insert into public.supurge_damgasi (ad, son_kosum, kaynak)
  values ('expire_stale_sessions', now(), p_kaynak)
  on conflict (ad) do update set son_kosum = now(), kaynak = excluded.kaynak;

  -- ── GÖVDE ─────────────────────────────────────────────────────────
  --
  -- 🔴🔴 299/A2 — 298'DE KENDİ DÜŞÜRDÜĞÜM DÖRT ADIM GERİ KONULDU.
  --
  -- 298'de bu fonksiyonun başına freni takarken gövdeyi de yeniden
  -- yazdım ve 292'nin gövdesindeki DÖRT ADIMI düşürdüm. `drift_check.py`
  -- ikisini gösterdi (`perform public…`), kalan ikisini ben okuyarak
  -- buldum. Düşenler:
  --
  --   1) (b) bloğundaki `r.status = 'accepted'` KAPISI.
  --      280/K2'nin koyduğu kapı: iptal edilmiş isteğin yetim oturumu
  --      no_show DEĞİLDİR. Düşünce, iptal edilmiş bir isteğin arkasında
  --      kalan oturum yüzünden masum bir tarafa no_show yazılıyordu.
  --
  --   2) `perform public.recompute_trust(u) …`
  --      no_show işaretlenen tarafın güven puanı tazelenmiyordu. Yani
  --      ceza yazılıyor ama puana yansımıyordu.
  --
  --   3) (c) BLOĞUNUN TAMAMI — 187-noshow'un kapattığı hata.
  --      (b) oturumu 'expired' yapıyor ama isteği 'accepted' BIRAKIYOR.
  --      Bloksuz hali: misafirin kredisi sonsuza kilitli, host'un slotu
  --      sonsuza dolu (`sync_availability_filled` filled'ı accepted
  --      sayısından türetiyor). TEK BİR NO-SHOW İLANI KALICI OLARAK
  --      ÖLDÜRÜYORDU. 298 bunu geri getirmişti.
  --
  --   4) `perform public.tek_tarafli_oturumlari_kapat();`
  --
  -- 🆕 SINIF: "BİR FONKSİYONUN BAŞINA KAPI TAKARKEN GÖVDESİNİ YENİDEN
  -- YAZMA — ELDEKİ TANIMIN ÜSTÜNE EKLE. YENİDEN YAZMAK, GÖRMEDİĞİN HER
  -- ESKİ DÜZELTMEYİ SESSİZCE GERİ ALIR."
  --
  -- (a) Hiç başlatılmamış kabuller: kimse gelmedi ya da unutuldu →
  --     cezasız kapanış + kredi iadesi.
  --     🔴 İade tutarı artık sabit 1 değil: GERÇEKTEN TUTULAN kadar.
  with stale as (
    select r.id, r.guest_id
      from requests r
      join availabilities a on a.id = r.avail_id
      left join sessions s on s.request_id = r.id
     where r.status = 'accepted'
       -- 🔴 300/B2: `s.id is null` davet kabulünün açtığı BOŞ oturumu
       -- görmüyordu (293). Hiç kimse başlatmadıysa, oturum yok sayılır.
       and (s.id is null
            or (s.status = 'pending' and s.host_started_at is null
                and s.guest_started_at is null))
       and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours'
  ), upd as (
    update requests set status = 'cancelled' where id in (select id from stale) returning id, guest_id
  )
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  select u.guest_id, public.tutulan_kredi(u.id), 'expired_refund', u.id,
         coalesce((select sum(delta) from credit_ledger c where c.user_id = u.guest_id), 0)
           + public.tutulan_kredi(u.id)
    from upd u;
  get diagnostics v_req = row_count;
  -- 300/B2: iptal edilen isteğin arkasındaki boş oturum → 'expired' (no_show DEĞİL).
  update sessions s set status = 'expired', completed_at = now(), cancel_reason = 'not_started'
    from requests r
   where r.id = s.request_id and r.status = 'cancelled'
     and s.status = 'pending' and s.host_started_at is null and s.guest_started_at is null;

  -- (b) Tek taraf başlatmış ama diğeri hiç gelmemiş → 'expired'.
  --     `r.status = 'accepted'` KAPISI 280/K2'den; 299'da geri kondu.
  update sessions s
     set status = 'expired',
         completed_at = now(),
         cancel_reason = 'no_show',
         no_show_user_id = case when s.host_started_at is null then r.host_id else r.guest_id end
    from requests r, availabilities a
   where r.id = s.request_id and a.id = r.avail_id
     and s.status = 'pending'
     and r.status = 'accepted'
     and (s.host_started_at is null) <> (s.guest_started_at is null)
     and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours';
  get diagnostics v_sess = row_count;

  -- Etkilenenlerin güvenini tazele (292'den; 298'de düşmüştü).
  perform public.recompute_trust(u) from (
    select distinct no_show_user_id as u from sessions
     where cancel_reason = 'no_show' and no_show_user_id is not null
       and completed_at > now() - interval '1 day'
  ) x where u is not null;

  -- (c) 187-noshow · 298'de TAMAMEN DÜŞMÜŞTÜ, geri konuldu.
  --     (b) oturumu kapatır ama isteği 'accepted' bırakır; burada istek
  --     de kapanır ve kredi iade edilir. Yoksa kredi de slot da sonsuza
  --     kilitli kalır.
  with kapanan as (
    select r.id, r.guest_id
      from requests r
      join sessions s2 on s2.request_id = r.id
     where r.status = 'accepted'
       and s2.status = 'expired'
       and s2.cancel_reason = 'no_show'
  ), iade as (
    update requests set status = 'cancelled'
     where id in (select id from kapanan)
    returning id, guest_id
  )
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  select i.guest_id, public.tutulan_kredi(i.id), 'no_show_refund', i.id,
         coalesce((select sum(c.delta) from credit_ledger c
                    where c.user_id = i.guest_id), 0) + public.tutulan_kredi(i.id)
    from iade i
   where not exists (select 1 from credit_ledger c2
                      where c2.ref_id = i.id and c2.reason = 'no_show_refund');

  perform public.tek_tarafli_oturumlari_kapat();

  v_sonuc := jsonb_build_object('ok', true, 'durum', 'kosuldu',
                                'kaynak', p_kaynak,
                                'iptal_edilen', v_req, 'suresi_dolan', v_sess);

  -- Sonucu damgaya yaz: panelde "en son koşum NE YAPTI" görünsün.
  update public.supurge_damgasi
     set son_sonuc = v_sonuc, ardisik_hata = 0
   where ad = 'expire_stale_sessions';

  return v_sonuc;
exception
  when others then
    -- ⚠️ BURADA `update` DEĞİL `insert … on conflict` KULLANILIYOR VE
    -- BUNUN SEBEBİ ÖNEMLİ: plpgsql'de bir istisna, bloğun BAŞINDAN
    -- itibaren her şeyi geri alır — yukarıdaki damga `insert`i DAHİL.
    -- Yani handler'a girildiğinde satır ARTIK YOKTUR; `update` 0 satır
    -- günceller ve hata izi sessizce kaybolur. Tam da görünür kılmaya
    -- çalıştığımız şeyi kaybederdik.
    --
    -- 🆕 SINIF: "BİR HATA KAYDINI, HATANIN GERİ ALDIĞI SATIRIN ÜSTÜNE
    -- YAZAMAZSIN — HANDLER'DA HER ZAMAN YENİDEN OLUŞTURMAYA HAZIR OL."
    --
    -- Hatayı istisna olarak ATMIYORUZ, jsonb olarak DÖNÜYORUZ: çağıran
    -- `ok=false` görür, damga kalıcı olur ve `bo_supurge_sagligi()`
    -- onu gösterir. Yutmak değil — yerini değiştirmek.
    insert into public.supurge_damgasi (ad, son_kosum, kaynak, ardisik_hata, son_hata, son_hata_an)
    values ('expire_stale_sessions', coalesce(v_son, now() - interval '1 hour'),
            p_kaynak, 1, left(SQLERRM, 400), now())
    on conflict (ad) do update
      set ardisik_hata = public.supurge_damgasi.ardisik_hata + 1,
          kaynak       = excluded.kaynak,
          son_hata     = excluded.son_hata,
          son_hata_an  = excluded.son_hata_an;
    return jsonb_build_object('ok', false, 'durum', 'hata',
                              'kaynak', p_kaynak, 'hata', left(SQLERRM, 400));
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B4 · bayat_istekleri_iade_et  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.bayat_istekleri_iade_et()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saat int := coalesce((select (value #>> '{}')::int from beta_settings
                           where key = 'bayat_istek_saat'), 72);
  r record; v_bal int; v_kapatilan int := 0; v_iade int := 0;
begin
  perform public.motor_yazimi_ac();

  for r in
    select req.id, req.guest_id
      from requests req
      join availabilities a on a.id = req.avail_id
     where req.status = 'pending'
       and req.responded_at is null
       -- 🔴 300/B4: UTC tarihi değil, havalimanının yerel saati. Eskiden
       -- saati geçmiş bir ilanın bekleyen isteği ertesi UTC gününe kadar
       -- açık kalıyordu (kredi tutulu, host cevap veremez).
       and (public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()
            or req.created_at < now() - make_interval(hours => v_saat))
  loop
    -- Satır satır: bir satır bir iş kuralına takılırsa toplu iş çökmesin.
    begin
      update requests
         set status = 'cancelled',
             responded_at = now(),
             decision_note = coalesce(decision_note,
               'Host süresinde yanıtlamadı — istek otomatik kapatıldı (274).')
       where id = r.id and status = 'pending';
      if not found then continue; end if;
      v_kapatilan := v_kapatilan + 1;

      -- İADE yalnız gerçekten kredi düşülmüşse ve daha önce iade
      -- edilmemişse. `request_free_tier` satırları burada kasıtla dışarıda:
      -- harcanmayan kredi iade edilmez.
      if exists (select 1 from credit_ledger cl
                  where cl.ref_id = r.id and cl.reason in ('request_hold','invite_hold') and cl.delta < 0)
         and not exists (select 1 from credit_ledger cl
                          where cl.ref_id = r.id and cl.reason = 'request_stale_refund')
      then
        select coalesce(sum(delta), 0) into v_bal from credit_ledger where user_id = r.guest_id;
        insert into credit_ledger (user_id, delta, reason, ref_id, balance_after, note)
        values (r.guest_id, public.tutulan_kredi(r.id), 'request_stale_refund', r.id,
                v_bal + public.tutulan_kredi(r.id),
                format('%s saat içinde yanıt gelmedi', v_saat));
        v_iade := v_iade + 1;
      end if;

      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      values (r.guest_id, 'requests', 'İsteğin kapandı',
              format('Başvurun %s saat içinde yanıtlanmadı. Artık yeni istek gönderebilirsin.', v_saat),
              'request', r.id);
    exception when others then
      raise notice '274: istek % kapatilamadi: %', r.id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object('ok', true, 'kapatilan', v_kapatilan,
                            'iade_edilen', v_iade, 'esik_saat', v_saat);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B5 · create_request_impl  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.create_request_impl(p_avail_id uuid, p_type text DEFAULT 'lounge'::text, p_intro text DEFAULT NULL::text, p_idem text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare v_acik boolean; v_kalan int; v_tavan int;
      begin
        -- (a) ACİL DURDURMA
        select f.enabled into v_acik from feature_flags f where f.key = 'marketplace';
        if not coalesce(v_acik, true) then
          raise exception 'marketplace_closed';
        end if;

        -- (b) AYNI ANDA AÇIK İSTEK TAVANI — 029'da tohumlanmış ama
        -- yedi ay boyunca hiçbir yerde uygulanmamış bir eşik.
        select value into v_tavan from rule_thresholds where key = 'max_active_requests';
        select count(*) into v_kalan from requests
         where guest_id = auth.uid() and status = 'pending';
        if v_kalan >= coalesce(v_tavan, 5) then
          raise exception 'too_many_active_requests';
        end if;

        -- 🔴 300/B5: iki kapı, ikisi de ÖLÇÜLDÜ (SEED8 §5):
        --  · aynı ilana ikinci başvuru ham bir kısıt hatası döndürüyordu:
        --    "duplicate key value violates unique constraint …" — uygulama
        --    bunu "Bir şeyler ters gitti" diye gösteriyordu.
        --  · tarih bugünse ama SAAT geçmişse başvuru kabul ediliyordu.
        --  · 🔴 AYNI İLANA YENİDEN İSTEK SESSİZCE HİÇBİR ŞEY YAPMIYORDU.
        --    Uygulama tekrar-deneme anahtarını `uid:ilan` olarak üretiyor; iptal
        --    ettiğin (ya da reddedilen) isteğin anahtarı aynı kalıyordu. Yeni
        --    istek bu anahtarla gelince `preflag` ESKİ, KAPALI isteği
        --    `{"ok":true,"idempotent":true}` diye döndürüyordu — ekran "gönderildi"
        --    diyor, host hiçbir şey görmüyor. (Ölçüldü: ilk → iptal → tekrar =
        --    aynı id, durum `cancelled`.)
        --    Kapalı bir isteğin anahtarı artık serbest bırakılıyor: çift dokunuş
        --    korunur (açık istek), yeni deneme yeni istek olur.
        -- 🆕 SINIF: "BİR TEKRAR-DENEME ANAHTARI, KORUDUĞU İŞLEMDEN UZUN
        -- YAŞARSA, SONRAKİ HER GERÇEK İSTEĞİ BİR TEKRAR SANIR."
        if p_idem is not null then
          update requests set idempotency_key = null
           where idempotency_key = p_idem and guest_id = auth.uid()
             and status not in ('pending', 'accepted');
        end if;
        -- Tekrar deneme anahtarı (p_idem) ile gelen AÇIK istek dokunulmadan geçer.
        if p_idem is null or not exists (select 1 from requests
                                          where idempotency_key = p_idem and guest_id = auth.uid()) then
          if exists (select 1 from requests where guest_id = auth.uid() and avail_id = p_avail_id
                                              and status in ('pending','accepted')) then
            raise exception 'already_requested';
          end if;
          if exists (select 1 from availabilities a where a.id = p_avail_id
                      and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()) then
            raise exception 'availability_expired';
          end if;
        end if;

        return public.create_request_impl_preflag(p_avail_id, p_type, p_intro, p_idem);
      end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B6 · trg_bakiye_negatife_dusemez  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.trg_bakiye_negatife_dusemez()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_bal int;
begin
  if new.delta >= 0 then return new; end if;
  if new.reason like 'paid_guest_thanks_reversal:%' or new.reason like 'admin%' then
    return new;
  end if;

  -- 🔴 300/B6: KİLİT TETİKLEYİCİNİN İÇİNDE. 299/B2 kilidi dört yola
  -- koymuştu; `misafir_hakki_hediye_et` beşinciydi ve kilitsizdi. İki
  -- eşzamanlı hediye aynı 3 krediyi iki kez harcayabiliyordu (ölçüldü:
  -- ikinci oturum birincinin commit'ini beklemeden geçti).
  -- Kilit burada olunca YOL SAYISI önemsizleşiyor: bakiyeyi eksilten her
  -- satır, aynı kullanıcının diğer eksiltmesini commit'e kadar bekler ve
  -- sonra GÜNCEL toplamı okur.
  perform pg_advisory_xact_lock(hashtextextended('kredi:' || new.user_id::text, 0));
  select coalesce(sum(delta), 0) into v_bal
    from credit_ledger where user_id = new.user_id;

  if v_bal + new.delta < 0 then
    raise exception 'insufficient_credits'
      using detail = format('kullanıcı %s: bakiye %s, denenen %s (%s)',
                            new.user_id, v_bal, new.delta, new.reason),
            hint   = 'Bu satır bakiyeyi negatife düşürürdü; 299/B1 reddetti.';
  end if;
  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ. Açık kalan kapı varsa DUR.
-- ════════════════════════════════════════════════════════════════════════
do $z300$
declare v_n int; v_liste text;
begin
  -- A1: kilitli olanlar authenticated/anon tarafından çağrılamaz
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('change_plan','kredi_akis_raporu','anonymized_users',
                       'host_kota_durumu','doluluk_reddi_sayisi','oturum_kural_hedefi',
                       'kural_guncelligi','access_options_for_user','bo_slot_asimlari')
     and (has_function_privilege('authenticated', p.oid, 'execute')
          or has_function_privilege('anon', p.oid, 'execute'));
  if v_n > 0 then raise exception '300 §Z/A1: hâlâ açık: %', v_liste; end if;

  -- A2: PUBLIC'e açık SECURITY DEFINER fonksiyon kalmadı
  select count(distinct p.oid), string_agg(distinct p.proname, ', ') into v_n, v_liste
    from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef
     and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '300 §Z/A2: PUBLIC''e açık % fonksiyon: %', v_n, v_liste; end if;

  -- A2: küresel varsayılan gerçekten yazıldı mı?
  if not exists (select 1 from pg_default_acl d
                  where d.defaclnamespace = 0 and d.defaclobjtype = 'f'
                    and d.defaclrole = 'postgres'::regrole) then
    raise exception '300 §Z/A2: küresel varsayılan yetki kaydı yok';
  end if;

  -- Uygulamanın çağırdığı beş fonksiyon authenticated'da KALDI mı?
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('cancel_availability','binis_karti_kaydet','ilani_yeniden_yayinla',
                       'hikaye_davetini_ertele','kesifte_gorun','profil_karti',
                       'create_request','respond_request','confirm_session')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '300 §Z: uygulama fonksiyonu KAPANDI: %', v_liste; end if;

  -- A3 / B6 tetikleyicileri yerinde mi?
  if not exists (select 1 from pg_trigger where tgname = 'trg_visit_0_beyan_temizle') then
    raise exception '300 §Z/A3: tetikleyici yok';
  end if;
  if position('pg_advisory_xact_lock' in
       (select prosrc from pg_proc where proname = 'trg_bakiye_negatife_dusemez')) = 0 then
    raise exception '300 §Z/B6: kredi kilidi tetikleyicide yok';
  end if;
  if position('availability_expired' in
       (select prosrc from pg_proc where proname = 'respond_request')) = 0 then
    raise exception '300 §Z/B1: kabul kapısı yok';
  end if;
  if position('already_requested' in
       (select prosrc from pg_proc where proname = 'create_request_impl')) = 0 then
    raise exception '300 §Z/B5: mükerrer başvuru kapısı yok';
  end if;

  raise notice '300 §Z: bütün kapılar ölçüldü — kapalı';
end $z300$;

select '300 OK — uçtan uca denetim bulguları kapatıldı' as sonuc;

-- ----------------------------------------------------------------------
-- unrated_sessions   [etkin kaynak: 081_pending_ratings_link.sql]
-- ----------------------------------------------------------------------
create or replace function public.unrated_sessions()
returns table (session_id uuid, request_id uuid, other_id uuid, other_name text,
               lounge text, completed_at timestamptz, deferred boolean, hours_left numeric)
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  return query
  select s.id, r.id,
         (case when r.guest_id = v_uid then r.host_id else r.guest_id end),
         p.name,
         coalesce(a.lounge_name, a.airport_code),
         s.completed_at,
         (coalesce(s.rate_deferred_by,'{}') @> array[v_uid]),
         round(extract(epoch from (s.completed_at + interval '24 hours' - now())) / 3600.0, 1)
    from sessions s
    join requests r on r.id = s.request_id
    join availabilities a on a.id = r.avail_id
    join profiles p on p.user_id = (case when r.guest_id = v_uid then r.host_id else r.guest_id end)
   where s.status = 'completed'
     and (r.guest_id = v_uid or r.host_id = v_uid)
     and s.completed_at > now() - interval '24 hours'
     and not exists (select 1 from ratings rt where rt.session_id = s.id and rt.rater_id = v_uid)
   order by s.completed_at desc;
end $$;

-- ----------------------------------------------------------------------
-- rl_limit   [etkin kaynak: 082_rate_limiting.sql]
-- ----------------------------------------------------------------------
create or replace function public.rl_limit(p_key text, p_default int)
returns int language sql stable security definer set search_path = public as $$
  select coalesce((select (value ->> p_key)::int from beta_settings where key = 'rate_limits'), p_default)
$$;

-- ----------------------------------------------------------------------
-- rl_guard   [etkin kaynak: 223_sinirlar_dogruyu_soylesin.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.rl_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid; v_claims text;
  v_key text; v_def int; v_dk int; v_limit int; v_durum jsonb;
begin
  -- 176: test muafiyeti (ll.test_mode yalnız oturum ömürlü; PostgREST
  -- üzerinden yerleştirilemez, canlı kullanıcı bununla sınırı aşamaz).
  if coalesce(current_setting('ll.test_mode', true), '') = 'on' then
    return new;
  end if;

  -- 166: boş/bozuk JWT claims'te ÇÖKME. Sınır uygulanamıyorsa yazmayı
  -- engellemiyoruz — kimliksiz bir isteği zaten RLS durduruyor.
  v_claims := nullif(current_setting('request.jwt.claims', true), '');
  if v_claims is null then return new; end if;
  begin
    v_uid := nullif(v_claims::json ->> 'sub', '')::uuid;
  exception when others then
    return new;
  end;
  if v_uid is null then return new; end if;

  -- 🔴 082'DEN GERİ GELEN KISIM: her tetikleyici KENDİ anahtarını,
  -- KENDİ varsayılanını ve KENDİ pencere boyunu taşıyor.
  v_key := coalesce(TG_ARGV[0], 'genel');
  v_def := coalesce(nullif(TG_ARGV[1],'')::int, 20);
  v_dk  := coalesce(nullif(TG_ARGV[2],'')::int, 60);
  v_limit := public.rl_limit(v_key, v_def);

  v_durum := public.oran_kapisi(v_key, v_limit, v_dk);
  if not coalesce((v_durum ->> 'ok')::boolean, true) then
    raise exception 'rate_limited'
      using detail = format('%s: %s/%s', v_key, v_durum ->> 'kullanilan', v_durum ->> 'tavan'),
            hint   = 'yenilenme=' || (v_durum ->> 'yenilenme') || ';islem=' || v_key;
  end if;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- lounge_rule_check   [etkin kaynak: 083_lounge_rules_and_flight_prep.sql]
-- ----------------------------------------------------------------------
create or replace function public.lounge_rule_check(
  p_program_code text,
  p_venue_id     uuid,
  p_carrier      text,
  p_card_tier    text,
  p_cabin        text,
  p_guest_flight text default null      -- misafirin uçuş no'su ('TK712')
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_r lounge_guest_rules%rowtype; v_guest_carrier text; v_warns text[] := '{}';
begin
  select r.* into v_r
    from lounge_guest_rules r
    join lounge_programs p on p.id = r.program_id
   where p.code = p_program_code
     and (r.venue_id is null or r.venue_id = p_venue_id)
     and (r.carrier is null or r.carrier = p_carrier)
     and (r.card_tier is null or r.card_tier = p_card_tier)
     and (r.cabin_class is null or r.cabin_class = p_cabin)
     and (r.effective_from is null or r.effective_from <= current_date)
     and (r.effective_to is null or r.effective_to >= current_date)
   order by (r.venue_id is not null) desc,      -- salona özel kural genel kuralı ezer
            (r.card_tier is not null) desc,
            (r.cabin_class is not null) desc
   limit 1;

  if not found then
    return jsonb_build_object('known', false,
      'message', 'Bu program/salon için kayıtlı kural yok — kapıda teyit et.');
  end if;

  if v_r.blocked_reason is not null then
    return jsonb_build_object('known', true, 'allowed', false,
      'reason', v_r.blocked_reason, 'guest_allowance', 0);
  end if;

  -- misafirin taşıyıcısı uçuş numarasının harf önekinden çıkarılır (TK712 → TK)
  v_guest_carrier := upper(substring(coalesce(p_guest_flight,'') from '^[A-Za-z]+'));

  if v_r.guest_must_match_carrier and v_guest_carrier <> '' and v_guest_carrier <> p_carrier then
    v_warns := v_warns || format('Bu salonun kuralı: misafir de %s seferinde uçmalı (misafirin uçuşu %s).',
                                 p_carrier, p_guest_flight);
  end if;
  if v_r.guest_carrier_whitelist is not null and array_length(v_r.guest_carrier_whitelist,1) > 0
     and v_guest_carrier <> '' and not (v_guest_carrier = any(v_r.guest_carrier_whitelist)) then
    v_warns := v_warns || format('Misafirin taşıyıcısı (%s) bu salonun kabul listesinde değil.', v_guest_carrier);
  end if;
  if v_r.guest_allowance = 0 then
    v_warns := v_warns || ('Bu kart/kabin birleşiminde misafir hakkı bulunmuyor.')::text;
  end if;

  return jsonb_build_object(
    'known', true,
    'allowed', (v_r.guest_allowance > 0 and coalesce(array_length(v_warns,1),0) = 0),
    'guest_allowance', v_r.guest_allowance,
    'family_allowed', v_r.family_allowed,
    'earliest_entry_hours', v_r.earliest_entry_hours,
    'paid_entry_allowed', v_r.paid_entry_allowed,
    'warnings', to_jsonb(v_warns),
    'notes', v_r.notes
  );
end $$;

-- ----------------------------------------------------------------------
-- flight_lookup   [etkin kaynak: 083_lounge_rules_and_flight_prep.sql]
-- ----------------------------------------------------------------------
create or replace function public.flight_lookup(p_flight_no text, p_date date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v flight_cache%rowtype;
begin
  select * into v from flight_cache
   where upper(flight_no) = upper(trim(p_flight_no)) and flight_date = p_date;
  if not found then
    return jsonb_build_object('hit', false);
  end if;
  return jsonb_build_object('hit', true,
    'scheduled_departure', v.scheduled_departure, 'terminal', v.terminal,
    'status', v.status, 'source', v.source, 'fetched_at', v.fetched_at);
end $$;

-- ----------------------------------------------------------------------
-- match_deletion_requests   [etkin kaynak: 084_deletion_requests.sql]
-- ----------------------------------------------------------------------
create or replace function public.match_deletion_requests()
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  update deletion_requests d
     set matched_user_id = u.id
    from users u
   where lower(u.email) = lower(d.email)
     and d.matched_user_id is null;
  get diagnostics n = row_count;
  return n;
end $$;

-- ----------------------------------------------------------------------
-- availability_rule_snapshot   [etkin kaynak: 086_lounge_rules_v3.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.availability_rule_snapshot(p_avail_id uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select public.lounge_access_decision(p_avail_id, null);
$$;

-- ----------------------------------------------------------------------
-- apply_rule_snapshot   [etkin kaynak: 086_lounge_rules_v3.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.apply_rule_snapshot(p_avail_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare d jsonb; v_car text[];
begin
  d := public.lounge_access_decision(p_avail_id, null);

  if (d ->> 'flight_coupling') = 'same_carrier' then
    select array[upper(coalesce(a.carrier, substring(coalesce(a.flight_number,'') from '^[A-Za-z]+')))]
      into v_car from availabilities a where a.id = p_avail_id;
    if v_car[1] is null or v_car[1] = '' then v_car := null; end if;
  end if;

  update availabilities
     set rule_guest_policy    = d ->> 'guest_policy',
         rule_flight_coupling = d ->> 'flight_coupling',
         rule_severity        = d ->> 'severity',
         rule_headline        = d ->> 'headline',
         rule_note            = d ->> 'detail',
         rule_entry_hours     = nullif(d ->> 'earliest_entry_hours','')::numeric,
         guest_carrier_required = v_car,
         rule_checked_at      = now()
   where id = p_avail_id;
  return d;
end $$;

-- ----------------------------------------------------------------------
-- guest_flight_fits   [etkin kaynak: 086_lounge_rules_v3.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.guest_flight_fits(p_avail_id uuid, p_flight_no text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare d jsonb;
begin
  d := public.lounge_access_decision(p_avail_id, p_flight_no);
  return jsonb_build_object(
    'fits',     coalesce((d ->> 'fits')::boolean, true),
    'soft',     (d ->> 'fits') is null,
    'severity', d ->> 'severity',
    'reason',   d ->> 'headline',
    'detail',   d ->> 'detail');
end $$;

-- ----------------------------------------------------------------------
-- lounge_rules_health   [etkin kaynak: 137_placeholder_vs_data.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_rules_health()
returns table (alan text, sorun text, ayrinti text, agirlik int)
language sql stable security definer set search_path = public as $$
  select v.airport_code || ' · ' || v.name, 'kabul matrisi bos',
         'Bu salon icin hicbir program kabul satiri yok', 1
    from lounge_venues v
   where v.active and v.section_of is null and not exists (
         select 1 from lounge_venue_acceptance a where a.venue_id = v.id)
  union all
  -- 🔴 Yer tutucular BAYAT sayilmaz: hic dogrulanmadilar ki eskisinler.
  -- Onlar ayri bir is listesi (asagida).
  select v.airport_code || ' · ' || v.name, 'kabul dogrulanmadi',
         p.name || ' — son dogrulama ' || coalesce(a.checked_at::text, 'yok'), 2
    from lounge_venue_acceptance a
    join lounge_venues v on v.id = a.venue_id
    join lounge_programs p on p.id = a.program_id
   where a.active and not a.is_placeholder
     and (a.checked_at is null or a.checked_at < current_date - 90)
  union all
  select v.airport_code || ' · ' || v.name, 'yer tutucu — arastirilmayi bekliyor',
         p.name || ' — 096 otomatik doldurmasindan geldi', 3
    from lounge_venue_acceptance a
    join lounge_venues v on v.id = a.venue_id
    join lounge_programs p on p.id = a.program_id
   where a.active and a.is_placeholder
  union all
  select p.name, 'tarife bitiyor',
         coalesce(r.card_tier,'tum kartlar') || ' — ' || r.effective_to::text, 1
    from lounge_guest_rules r join lounge_programs p on p.id = r.program_id
   where r.effective_to is not null and r.effective_to <= current_date + 45
  union all
  select p.name, 'kaynak yok', 'Resmi kaynak URL girilmemis', 3
    from lounge_programs p where p.active and coalesce(p.source_url,'') = ''
  union all
  select p.name, 'takma ad yok', 'Host beyanindan bu program hicbir zaman eslesmez', 2
    from lounge_programs p
   where p.active and not exists (
         select 1 from lounge_program_aliases a where a.program_id = p.id)
  union all
  select p.name, 'kim oduyor belirsiz',
         'fee_payer bos — misafire ne diyecegimizi bilmiyoruz', 2
    from lounge_programs p
   where p.active and p.guest_default = 'paid' and p.fee_payer is null
  union all
  select l.airport_code || ' · ' || l.name, 'salon eslesmedi',
         'lounges kaydinin lounge_venues karsiligi yok', 1
    from lounges l where l.venue_id is null and l.active;
$$;

-- ----------------------------------------------------------------------
-- match_program_by_text   [etkin kaynak: 086_lounge_rules_v3.sql]
-- ----------------------------------------------------------------------
create or replace function public.match_program_by_text(p_text text)
returns uuid language sql stable security definer set search_path = public as $$
  select a.program_id
    from lounge_program_aliases a
    join lounge_programs p on p.id = a.program_id and p.active
   where coalesce(p_text,'') <> ''
     and position(lower(a.alias) in lower(p_text)) > 0
   order by length(a.alias) desc, a.weight desc
   limit 1;
$$;

-- ----------------------------------------------------------------------
-- resolve_venue_for_availability   [etkin kaynak: 161_venue_merge_and_catalog_truth.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.resolve_venue_for_availability(p_avail_id uuid)
returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
           a.venue_id,
           (select l.venue_id from lounges l where l.id = a.lounge_id),
           (select v.id from lounge_venues v
             where v.airport_code = a.airport_code and v.active
               and lower(regexp_replace(translate(v.name,'İıŞşĞğÜüÖöÇç','IiSsGgUuOoCc'),'\s+',' ','g'))
                 = lower(regexp_replace(translate(coalesce(a.lounge_name,''),'İıŞşĞğÜüÖöÇç','IiSsGgUuOoCc'),'\s+',' ','g'))
             limit 1)
         )
    from availabilities a where a.id = p_avail_id;
$$;

-- ----------------------------------------------------------------------
-- parse_host_entitlements   [etkin kaynak: 086_lounge_rules_v3.sql]
-- ----------------------------------------------------------------------
create or replace function public.parse_host_entitlements(p_user_id uuid default null)
returns integer language plpgsql security definer set search_path = public as $$
declare v_n integer := 0;
begin
  insert into host_entitlements (user_id, program_id, guest_capacity, origin, note)
  select pr.user_id,
         public.match_program_by_text(pr.access_source),
         nullif(pr.guest_capacity, 0),
         'parsed',
         'access_source: ' || left(pr.access_source, 180)
    from profiles pr
   where (p_user_id is null or pr.user_id = p_user_id)
     and coalesce(pr.access_source,'') <> ''
     and public.match_program_by_text(pr.access_source) is not null
  on conflict do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- ----------------------------------------------------------------------
-- lounge_access_decision   [etkin kaynak: 191_kaynak_celiskileri_ve_bosluklar.sql]
-- ⚠ Bu fonksiyon 5 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_access_decision('
       || pg_get_function_arguments(v_oid) || ') returns '
       || pg_get_function_result(v_oid)
       || ' language plpgsql stable security definer set search_path = public as $BODY$'
       || v_new || '$BODY$';
  raise notice '191: kabin sinifi karar zincirine baglandi';
end $$;

-- ----------------------------------------------------------------------
-- entitlement_remaining   [etkin kaynak: 087_entitlements_and_coverage.sql]
-- ----------------------------------------------------------------------
create or replace function public.entitlement_remaining(p_entitlement_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare e host_entitlements%rowtype; v_start date; v_left int;
begin
  select * into e from host_entitlements where id = p_entitlement_id;
  if not found or e.quota_total is null or e.quota_period = 'unlimited' then
    return jsonb_build_object('known', false, 'unlimited', e.quota_period = 'unlimited');
  end if;
  v_start := coalesce(e.quota_period_start,
                      case when e.quota_period = 'month' then date_trunc('month', current_date)::date
                           else date_trunc('year', current_date)::date end);
  -- Dönem devrettiyse sayaç mantıken sıfırlanmış sayılır (yazmıyoruz, okuyoruz)
  if (e.quota_period = 'month' and v_start < date_trunc('month', current_date)::date)
     or (e.quota_period = 'year' and v_start < date_trunc('year', current_date)::date) then
    v_left := e.quota_total;
  else
    v_left := greatest(e.quota_total - e.quota_used, 0);
  end if;
  return jsonb_build_object(
    'known', true, 'unlimited', false,
    'total', e.quota_total, 'used', e.quota_used, 'left', v_left,
    'period', e.quota_period, 'period_start', v_start,
    'stale', e.self_reported_at is null or e.self_reported_at < now() - interval '60 days');
end $$;

-- ----------------------------------------------------------------------
-- trg_field_report_rollup   [etkin kaynak: 087_entitlements_and_coverage.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_field_report_rollup()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.venue_id is null or new.program_id is null then return new; end if;
  update lounge_venue_acceptance
     set field_reports_ok  = field_reports_ok  + (case when new.outcome = 'admitted_free' then 1 else 0 end),
         field_reports_bad = field_reports_bad + (case when new.outcome in ('admitted_paid','refused') then 1 else 0 end),
         updated_at = now()
   where venue_id = new.venue_id and program_id = new.program_id;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- pending_field_report   [etkin kaynak: 087_entitlements_and_coverage.sql]
-- ----------------------------------------------------------------------
create or replace function public.pending_field_report(p_user_id uuid default null)
returns table (session_id uuid, venue_id uuid, program_id uuid, venue_name text, lounge_date date)
language sql stable security definer set search_path = public as $$
  select s.id, public.resolve_venue_for_availability(a.id), a.program_id, v.name, a.avail_date
    from sessions s
    join requests r on r.id = s.request_id
    join availabilities a on a.id = r.avail_id
    left join lounge_venues v on v.id = public.resolve_venue_for_availability(a.id)
   where s.status = 'completed'
     and s.completed_at > now() - interval '7 days'   -- sessions'ta updated_at YOK (sema teyit edildi)
     and (r.guest_id = coalesce(p_user_id, auth.uid()) or r.host_id = coalesce(p_user_id, auth.uid()))
     and not exists (select 1 from lounge_field_reports f
                      where f.session_id = s.id
                        and f.reporter_id = coalesce(p_user_id, auth.uid()));
$$;

-- ----------------------------------------------------------------------
-- lounge_access_decision_v2   [etkin kaynak: 087_entitlements_and_coverage.sql]
-- ----------------------------------------------------------------------
create or replace function public.lounge_access_decision_v2(
  p_avail_id     uuid,
  p_guest_flight text default null
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  d          jsonb;
  v_av       availabilities%rowtype;
  v_ent      host_entitlements%rowtype;
  v_card     lounge_card_products%rowtype;
  v_acc      lounge_venue_acceptance%rowtype;
  v_venue_id uuid;
  v_quota    jsonb;
  v_conf     text := 'unknown';
  v_extra    text[] := '{}';
  v_sev      text;
begin
  d := public.lounge_access_decision(p_avail_id, p_guest_flight);
  select * into v_av from availabilities where id = p_avail_id;
  if not found then return d; end if;
  v_venue_id := public.resolve_venue_for_availability(p_avail_id);
  v_sev := d ->> 'severity';

  -- ---- GÜVEN DERECESİ ----------------------------------------------
  if v_venue_id is not null then
    select * into v_acc from lounge_venue_acceptance
     where venue_id = v_venue_id and program_id = (d ->> 'program_id')::uuid;
  end if;
  if (d ->> 'known')::boolean is not true then
    v_conf := 'unknown';
  elsif (d ->> 'checked_at') is not null and (d ->> 'checked_at')::date >= current_date - 90 then
    v_conf := 'verified';
  elsif coalesce(v_acc.field_reports_ok, 0) + coalesce(v_acc.field_reports_bad, 0) >= 3 then
    v_conf := 'reported';        -- sahadan geldi, resmî kaynaktan değil
  elsif (d ->> 'guest_policy') = 'unknown' then
    v_conf := 'unknown';
  else
    v_conf := 'assumed';         -- program varsayılanından türetildi
  end if;

  -- ---- HOST'UN KOTASI ----------------------------------------------
  select he.* into v_ent
    from host_entitlements he
   where he.user_id = v_av.host_id
     and (he.program_id = (d ->> 'program_id')::uuid or (d ->> 'program_id') is null)
   order by he.verified desc, he.created_at
   limit 1;

  if v_ent.id is not null then
    v_quota := public.entitlement_remaining(v_ent.id);
    if v_ent.card_product_id is not null then
      select * into v_card from lounge_card_products where id = v_ent.card_product_id;
    end if;

    if (v_quota ->> 'known')::boolean and (v_quota ->> 'left')::int = 0 then
      -- 🔴 Kotası bitmiş host: misafir kapıda ücret öder. Engel DEĞİL,
      -- ama misafire söylenmeden istek gönderilmemeli.
      v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
      v_extra := v_extra || format(
        'Host''un bu dönemdeki ücretsiz giriş hakkı tükenmiş görünüyor (%s/%s). Misafir girişi ücretli olabilir.',
        (v_quota ->> 'used'), (v_quota ->> 'total'));
    elsif (v_quota ->> 'known')::boolean and (v_quota ->> 'left')::int <= 2 then
      v_extra := v_extra || format('Host''un kalan ücretsiz giriş hakkı: %s.', (v_quota ->> 'left'));
    end if;

    if (v_quota ->> 'stale')::boolean then
      v_extra := v_extra || ('Bu hak bilgisi host''un beyanı ve bir süredir güncellenmedi.')::text;
    end if;

    if coalesce(v_card.guest_consumes_quota, false) then
      v_extra := v_extra || ('Bu kartta misafirin girişi de host''un kendi hakkından düşüyor.')::text;
    end if;

    -- ---- ÖNCEDEN ÜRETİLEN GEÇİŞ (TEB karekod modeli) ----------------
    if coalesce(v_card.requires_preissued_pass, false) then
      v_extra := v_extra || ('Host girişi ÖNCEDEN oluşturmak zorunda.')::text;
      if coalesce(v_card.pass_needs_guest_legal_name, false) then
        v_extra := v_extra || ('Bunun için misafirin ad-soyadını kabul aşamasında host''la paylaşması gerekiyor.')::text;
      end if;
      if not coalesce(v_card.pass_change_allowed, true) then
        v_extra := v_extra || ('Oluşturulan geçiş DEĞİŞTİRİLEMİYOR: geç iptal host''un hakkını yakar.')::text;
      end if;
    end if;
  end if;

  -- ---- BİLİNMEYEN DURUM: SUSMA, SÖYLE ------------------------------
  if v_conf = 'unknown' then
    v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
    v_extra := v_extra || coalesce(
      (select value #>> '{}' from beta_settings where key = 'lounge_generic_notice'),
      'Bu salonun misafir kurallarını henüz doğrulamadık; koşulları kapıda teyit edin.');
  end if;

  return d
    || jsonb_build_object(
         'confidence', v_conf,
         'severity',   v_sev,
         'quota',      v_quota,
         'card_product', v_card.name,
         'requires_preissued_pass', coalesce(v_card.requires_preissued_pass, false),
         'needs_guest_legal_name',  coalesce(v_card.pass_needs_guest_legal_name, false),
         'detail', trim(both ' ' from coalesce(d ->> 'detail','') || ' ' || array_to_string(v_extra, ' ')));
end $$;

-- ----------------------------------------------------------------------
-- entitlement_health   [etkin kaynak: 087_entitlements_and_coverage.sql]
-- ----------------------------------------------------------------------
create or replace function public.entitlement_health()
returns table (alan text, sorun text, ayrinti text, agirlik int)
language sql stable security definer set search_path = public as $$
  select i.name || ' · ' || cp.name, 'kart urunu dogrulanmadi',
         coalesce('son dogrulama ' || cp.checked_at::text, 'hic dogrulanmadi') ||
         ' — banka kampanya kosullari sik degisir', 1
    from lounge_card_products cp join lounge_issuers i on i.id = cp.issuer_id
   where cp.active and (cp.checked_at is null or cp.checked_at < current_date - 180)
  union all
  select i.name || ' · ' || cp.name, 'altyapi programi bos',
         'Bu kartin hangi aga (PP/LoungeKey/DragonPass) bagli oldugu girilmemis', 1
    from lounge_card_products cp join lounge_issuers i on i.id = cp.issuer_id
   where cp.active and cp.program_id is null
  union all
  select i.name || ' · ' || cp.name, 'kota bilinmiyor',
         'quota_total bos — host''a kalan hakki gosteremeyiz', 2
    from lounge_card_products cp join lounge_issuers i on i.id = cp.issuer_id
   where cp.active and cp.quota_total is null and coalesce(cp.quota_period,'') <> 'unlimited'
  union all
  select p.name, 'kapsama bilinmiyor',
         'coverage_status = unknown — kullaniciya genel uyari gosterilecek', 2
    from lounge_programs p where p.active and coalesce(p.coverage_status,'unknown') = 'unknown'
  union all
  select v.airport_code || ' · ' || v.name, 'saha raporlari kuralla celisiyor',
         format('%s olumlu / %s olumsuz rapor — kural "%s" diyor, gozden gecir',
                a.field_reports_ok, a.field_reports_bad, a.guest_policy), 1
    from lounge_venue_acceptance a join lounge_venues v on v.id = a.venue_id
   where a.field_reports_bad >= 2 and a.guest_policy = 'included'
  union all
  select coalesce(pr.name, 'kullanici'), 'hak beyani bayat',
         'Host''un kota beyani 60 gunden eski — kalan hak yanlis olabilir', 3
    from host_entitlements he left join profiles pr on pr.user_id = he.user_id
   where he.quota_total is not null
     and (he.self_reported_at is null or he.self_reported_at < now() - interval '60 days');
$$;

-- ----------------------------------------------------------------------
-- card_product_active_now   [etkin kaynak: 088_card_catalog.sql]
-- ----------------------------------------------------------------------
create or replace function public.card_product_active_now(p_card_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select cp.active
     and (cp.valid_from is null or cp.valid_from <= current_date)
     and (cp.valid_to   is null or cp.valid_to   >= current_date)
    from lounge_card_products cp where cp.id = p_card_id;
$$;

-- ----------------------------------------------------------------------
-- card_self_check   [etkin kaynak: 088_card_catalog.sql]
-- ----------------------------------------------------------------------
create or replace function public.card_self_check(p_user_id uuid default null)
returns table (kart text, banka text, tahmini_hak text, teyit_notu text, kaynak text)
language sql stable security definer set search_path = public as $$
  select cp.name,
         i.name,
         case
           when cp.quota_period = 'unlimited' then 'sinirsiz (karta gore)'
           when cp.quota_total is null        then 'adet bilinmiyor'
           else cp.quota_total || ' / ' || cp.quota_period
         end,
         case cp.confidence
           when 'verified'  then 'Resmi kaynaktan dogrulandi.'
           when 'secondary' then 'Karsilastirma kaynaklarindan derlendi — bankandan teyit et.'
           else 'Bu kartin kosulunu bilmiyoruz — lutfen bankandan teyit et.'
         end ||
         case when cp.condition_type in ('segment','min_spend','campaign','tier_and_spend')
              then ' ' || coalesce(cp.condition_note,'Hak segmente/kampanyaya bagli olabilir.')
              else '' end,
         coalesce(cp.source_url, i.self_check_url, '')
    from host_entitlements he
    join lounge_card_products cp on cp.id = he.card_product_id
    join lounge_issuers i on i.id = cp.issuer_id
   where he.user_id = coalesce(p_user_id, auth.uid());
$$;

-- ----------------------------------------------------------------------
-- rule_notice   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.rule_notice(p_key text)
    returns text
    language sql stable security definer set search_path = public as $rn$
      select coalesce(public.metin(p_key), '');
    $rn$;
  $q$;

  -- (3) SONRA — aynı ilanlar, aynı dil
  perform public.dili_ayarla('tr');
  for r in select a.id from availabilities a where a.active order by a.id limit 25 loop
    begin
      v_sonra := v_sonra || jsonb_build_object(
        'id', r.id,
        'karar', public.lounge_access_decision(r.id, null),
        'ipucu', public.lounge_hint_for_host(r.id));
    exception when others then
      v_sonra := v_sonra || jsonb_build_object('id', r.id, 'hata', sqlerrm);
    end;
  end loop;

  -- (4) BAYT AYNILIK
  if v_once::text is distinct from v_sonra::text then
    raise exception '250 NOBETCI §8: DIL KATMANI TURKCE CIKTIYI DEGISTIRDI. once=% bayt sonra=% bayt — kurulum durduruldu.',
                    length(v_once::text), length(v_sonra::text);
  end if;
  raise notice '250 §8 OK · rule_notice dil katmanina bagli · TR cikti BAYT BAYT ayni (% ilan olculdu)',
    jsonb_array_length(v_once);
end $e4$;

grant execute on function public.rule_notice(text) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §9 — NÖBETÇİ
-- ════════════════════════════════════════════════════════════════════════

do $n250$
declare
  v_h text[] := '{}';
  v_u uuid; v_v uuid; v_r jsonb; v_n int; v_kisit boolean; v_until timestamptz;
begin
  begin
    select id into v_u from users limit 1;
    select id into v_v from users where id <> v_u limit 1;

    -- (1) C1 — AĞIR ŞİKÂYET: TEK kayıt süresiz kısıt tetiklemeli
    delete from reports where target_id = v_u;
    update users set shadow_limited = false, restricted_until = null,
                     kisit_inceleme_bekliyor = false, kisit_sebebi = null where id = v_u;
    insert into reports (reporter_id, target_id, type, description, status)
    values (v_v, v_u, 'harassment', 'test', 'open');
    v_r := public.apply_rule_engine(v_u);
    if coalesce(v_r ->> 'action','') <> 'agir_sikayet' then
      v_h := v_h || format('tek agir sikayet yaptirim tetiklemedi (action=%s)', v_r ->> 'action')::text;
    end if;
    select shadow_limited, restricted_until into v_kisit, v_until from users where id = v_u;
    if not coalesce(v_kisit,false) then v_h := v_h || 'agir sikayette kisit konmadi'::text; end if;
    if v_until is null or v_until < now() + interval '1 year' then
      v_h := v_h || 'agir sikayette kisit SURESIZ degil — 7 gun sonra kendiliginden acilacak'::text;
    end if;
    if not exists (select 1 from reports where target_id = v_u and is_urgent) then
      v_h := v_h || 'agir sikayet acil olarak isaretlenmedi (moderasyon kuyrugunda one gecmez)'::text;
    end if;

    -- (2) İFTİRA KORUMASI — şikâyet kapanınca kısıt kalkmalı
    update reports set status = 'dismissed' where target_id = v_u;
    select shadow_limited, kisit_inceleme_bekliyor into v_kisit, v_kisit from users where id = v_u;
    select shadow_limited into v_kisit from users where id = v_u;
    if coalesce(v_kisit,false) then
      v_h := v_h || 'sikayet reddedildi ama kisit KALKMADI — iftira kalici ceza olur'::text;
    end if;

    -- (3) TERS YÖN — HAFİF şikâyet tek başına süresiz kısıt YAPMAMALI
    delete from reports where target_id = v_u;
    update users set shadow_limited = false, restricted_until = null,
                     kisit_inceleme_bekliyor = false where id = v_u;
    insert into reports (reporter_id, target_id, type, description, status)
    values (v_v, v_u, 'other', 'test', 'open');
    v_r := public.apply_rule_engine(v_u);
    if coalesce(v_r ->> 'action','') <> 'none' then
      v_h := v_h || format('tek HAFIF sikayet yaptirim tetikledi (action=%s) — esik 3 olmaliydi', v_r ->> 'action')::text;
    end if;

    -- (4) F1 — huni tetikleyicileri gerçekten yazıyor mu
    select count(*) into v_n from pg_trigger
     where tgname in ('trg_huni_istek','trg_huni_oturum') and not tgisinternal;
    if v_n <> 2 then v_h := v_h || format('huni tetikleyicileri eksik (%s/2)', v_n)::text; end if;

    -- (5) F1 — olay adı kapısı gerçekten kapalı mı
    begin
      insert into huni_olaylari (user_id, olay) values (v_u, 'uydurma_olay');
      v_h := v_h || 'huni olay adi kapisi calismiyor — serbest metin kabul ediliyor'::text;
    exception when others then null;
    end;

    -- (6) C3 — yeni RPC'ler gerçekten çalışıyor mu
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_u, 'role','authenticated')::text, true);
    begin
      perform public.seyahat_ekle('XXX', current_date + 3, time '10:00', time '12:00');
      v_h := v_h || 'seyahat_ekle bilinmeyen havalimanini kabul etti'::text;
    exception when others then
      if sqlerrm not like '%unknown_airport%' then
        v_h := v_h || ('seyahat_ekle beklenmeyen hata: ' || sqlerrm)::text;
      end if;
    end;
    begin
      perform public.seyahat_ekle((select code from airports limit 1),
                                  current_date - 1, time '10:00', time '12:00');
      v_h := v_h || 'seyahat_ekle GECMIS tarihi kabul etti'::text;
    exception when others then
      if sqlerrm not like '%date_in_past%' then
        v_h := v_h || ('seyahat_ekle gecmis tarih testi: ' || sqlerrm)::text;
      end if;
    end;

    -- (7) E4 — dil katmanı: aynı anahtar iki dilde farklı dönmeli
    perform public.dili_ayarla('tr');
    if public.metin('head_charter') is not null
       and public.metin('head_charter') = public.metin('head_charter_en') then
      null;  -- TR ile EN ayni olabilir (ceviri yoksa) — ihlal degil
    end if;
    perform public.dili_ayarla('en');
    if public.metin('head_charter') <> 'Charter flights have no lounge access' then
      v_h := v_h || 'dil katmani EN cevirisini dondurmuyor'::text;
    end if;
    perform public.dili_ayarla('tr');
    if public.metin('head_charter') = 'Charter flights have no lounge access' then
      v_h := v_h || 'dil katmani TR isterken EN dondurdu — TURKCE BOZULDU'::text;
    end if;
    -- Cevirisi OLMAYAN anahtar EN'de de TR donmeli (yarim ingilizce yok)
    perform public.dili_ayarla('en');
    if public.metin('advice_intro') is distinct from
       (select value #>> '{}' from beta_settings where key='advice_intro') then
      v_h := v_h || 'cevirisi olmayan anahtar EN modunda TR degerine dusmuyor'::text;
    end if;
    perform public.dili_ayarla('tr');

    -- (8) D1 — host_wallet kapısı ayrışmadan sonra HÂLÂ çalışıyor mu
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_u, 'role','authenticated')::text, true);
    begin
      perform public.host_wallet(v_v);
      v_h := v_h || 'AYRISMADAN SONRA baskasinin cuzdani acilabiliyor — 232 kapisi dustu'::text;
    exception when others then
      if sqlerrm not like '%cuzdan_sahibi_degil%' then
        v_h := v_h || ('cuzdan kapisi beklenmeyen hata: ' || sqlerrm)::text;
      end if;
    end;
    begin
      perform public.host_wallet(v_u);   -- kendi cüzdanı: geçmeli
    exception when others then
      v_h := v_h || ('kendi cuzdanini acamadi: ' || sqlerrm)::text;
    end;

    raise exception 'GERI_AL_250';
  exception when others then
    if sqlerrm <> 'GERI_AL_250' then
      v_h := v_h || ('olcum coktu: ' || sqlerrm);
    end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '250 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '250 OK · agir sikayet suresiz + iftira korumasi · huni tetikleyicileri bagli · seyahat RPC dogruluyor · dil katmani TR bozmadan EN veriyor · cuzdan kapisi ayrismadan sonra da duruyor';
end $n250$;

-- ════════════════════════════════════════════════════════════════════════
-- §10 — `flow_gate_test` İKİNCİ KOŞUŞTA PATLIYOR
--
-- Harness'in TEKRAR KURULUM turu buldu:
--     SEED_KURAL_SENARYOLARI.sql ERROR: duplicate key value violates
--     unique constraint "idx_requests_unique_active"
--
-- 🔴 SEBEP BENİM DEĞİŞİKLİĞİM DEĞİL — 249/250 eklenince "son 35 dosya"
-- penceresi kaydı ve bu SEED ilk kez tekrar turuna girdi. Yani arıza
-- vardı, görünmüyordu.
--
-- `flow_gate_test()` bir NÖBETÇİ: akış kapılarını sınamak için gerçek
-- `requests` satırları yazıp sonra siliyor. Ama seçtiği ilanda ZATEN aktif
-- bir başvuru varsa `idx_requests_unique_active` patlıyor ve nöbetçi
-- ölçtüğü sistemi durduruyor.
--
-- 🆕 SINIF: "BİR NÖBETÇİ, ÖLÇMEK İÇİN YAZIYORSA, YAZACAĞI YERİN BOŞ
-- OLDUĞUNU DA ÖLÇMEK ZORUNDADIR." (240'ta öğrendiğim "nöbetçi nöbet
-- tuttuğu şeye zarar veremez" dersinin ikinci yarısı.)
--
-- Düzeltme: sınama ilanı seçilirken "üzerinde aktif başvuru olmayan"
-- şartı ekleniyor. Veri SİLMİYORUM — uygun ilan yoksa test '—' döner
-- ("ölçemedim"), ki bu dürüst cevaptır.
-- ════════════════════════════════════════════════════════════════════════

do $fg250$
declare v_tanim text; v_yeni text; v_n int := 0;
begin
  select pg_get_functiondef(p.oid) into v_tanim
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname='public' and p.proname='flow_gate_test' limit 1;
  if v_tanim is null then
    raise notice '250 §10: flow_gate_test yok — DOKUNULMADI.'; return;
  end if;
  if v_tanim like '%aktif_basvurusu_yok_250%' then
    raise notice '250 §10: sinama ilani secimi zaten korumali — dokunulmadi.'; return;
  end if;

  -- `a.active and a.slots - coalesce(a.filled,0) >= 1` → ayrıca aktif
  -- başvurusu olmayan ilan. Desen iki yerde geçiyor; ikisini de sarıyoruz.
  v_yeni := replace(v_tanim,
    'a.active and a.slots - coalesce(a.filled,0) >= 1',
    'a.active and a.slots - coalesce(a.filled,0) >= 1
       and not exists (select 1 /* aktif_basvurusu_yok_250 */ from requests rq
                        where rq.avail_id = a.id and rq.status in (''pending'',''accepted''))');

  if v_yeni = v_tanim then
    raise notice '250 §10: beklenen ilan secim deseni bulunamadi — DOKUNULMADI.';
    return;
  end if;
  execute v_yeni;
  raise notice '250 §10: flow_gate_test artik uzerinde aktif basvuru OLMAYAN ilan seciyor.';
end $fg250$;

-- ════════════════════════════════════════════════════════════════════════
-- §11 — DİL BİR İSTEK ÖZELLİĞİ DEĞİL, KULLANICI ÖZELLİĞİDİR
--
-- 🔴 §4'te `dili_ayarla()`yı İŞLEM-YEREL bir GUC olarak yazdım
-- (`set_config(..., true)`) ve bu YANLIŞTI — ölçmeden değil, düşünmeden.
--
-- PostgREST'te her istek AYRI BİR İŞLEMDİR. Yani app'in "dilim EN"
-- demesi ile kural sorusunu sorması İKİ AYRI işlemde olur ve ilkinde
-- kurulan GUC ikincisine ULAŞMAZ. Fonksiyon doğru çalışıyordu; ürüne
-- bağlanma biçimi çalışmıyordu.
--
-- Oturum düzeyinde (`false`) yazmak daha da kötü olurdu: Supabase bağlantı
-- havuzu kullanıyor, bir kullanıcının dili havuzdaki bağlantıda kalır ve
-- BAŞKA bir kullanıcıya sızardı.
--
-- 🆕 SINIF: "BİR TERCİH İSTEKLER ARASINDA YAŞAMAK ZORUNDAYSA, O TERCİH
-- BİR DEĞİŞKEN DEĞİL BİR KOLONDUR."
--
-- Dil artık `profiles.dil` kolonunda. GUC yalnız TEST/ÖLÇÜM için bir
-- geçersiz kılma olarak duruyor (nöbetçiler onu kullanıyor).
-- ════════════════════════════════════════════════════════════════════════

alter table profiles add column if not exists dil text;
alter table profiles drop constraint if exists profiles_dil_kapisi;
alter table profiles add constraint profiles_dil_kapisi check (dil is null or dil in ('tr','en'));

-- ----------------------------------------------------------------------
-- lounge_hint_for_host   [etkin kaynak: 100_tier_fee_and_time.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_hint_for_host(p_lounge_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); v_venue_id uuid; v_venue lounge_venues%rowtype;
  v_prog lounge_programs%rowtype; v_acc lounge_venue_acceptance%rowtype;
  v_ent host_entitlements%rowtype; v_rule lounge_guest_rules%rowtype;
  v_src text; v_sev text := 'info'; v_head text; v_notes text[] := '{}';
  v_count smallint := 0; v_needs_tier boolean := false;
begin
  if v_uid is null then return jsonb_build_object('severity','info'); end if;

  select l.venue_id into v_venue_id from lounges l where l.id = p_lounge_id;
  if v_venue_id is not null then select * into v_venue from lounge_venues where id = v_venue_id; end if;

  select he.* into v_ent from host_entitlements he
   where he.user_id = v_uid order by he.verified desc, he.self_reported_at desc nulls last limit 1;
  if v_ent.program_id is not null then
    select * into v_prog from lounge_programs where id = v_ent.program_id;
  else
    select pr.access_source into v_src from profiles pr where pr.user_id = v_uid;
    select * into v_prog from lounge_programs where id = public.match_program_by_text(v_src);
  end if;

  if v_prog.id is null or v_prog.entitlement_model = 'bank_card' or v_prog.code = 'BANK_CARD' then
    return jsonb_build_object('severity','warn','kind','card_generic',
      'venue_name', v_venue.name, 'headline','Kart avantajıyla açılan ilan',
      'detail', public.rule_notice('card_notice_host'));
  end if;

  if v_venue_id is not null then
    select * into v_acc from lounge_venue_acceptance
     where venue_id = v_venue_id and program_id = v_prog.id and active;
  end if;

  if v_acc.id is null then
    return jsonb_build_object('severity','warn','kind','unknown',
      'venue_name', v_venue.name, 'program_name', v_prog.name,
      'headline', format('%s bu salonda doğrulanmadı', v_prog.name),
      'detail', public.rule_notice('rule_notice_generic'));
  end if;

  if not v_acc.accepted or v_acc.guest_policy = 'not_allowed' then
    return jsonb_build_object('severity','block','kind','not_allowed',
      'venue_name', v_venue.name, 'program_name', v_prog.name,
      'headline','Bu salonda misafir alamazsın',
      'detail', coalesce(v_acc.conditions,'Bu salon/hak birleşiminde misafir hakkı yok.'));
  end if;

  v_count := v_acc.guest_included_count;
  v_needs_tier := public.program_needs_tier(v_prog.id);

  -- 🔴 KART TİPİ KAPISI
  if v_needs_tier and coalesce(v_ent.tier,'') = '' then
    v_sev := 'warn';
    v_head := 'Kart tipini belirtmen gerekiyor';
    v_notes := v_notes || format('%s''ta misafir hakkı KART TİPİNE göre değişiyor: Elite ve Elite Plus''ta '
      || 'aile veya bir misafir, Classic Plus''ta MİSAFİR HAKKI YOK. Doğru bilgiyi gösterebilmemiz için '
      || 'Lounge Erişim ekranından kart tipini seç.', v_prog.name);
  elsif v_needs_tier then
    select r.* into v_rule from lounge_guest_rules r
     where r.program_id = v_prog.id and r.card_tier = v_ent.tier
       and (r.venue_id is null or r.venue_id = v_venue_id)
       and (r.effective_to is null or r.effective_to >= current_date)
     order by (r.venue_id is not null) desc, r.created_at limit 1;
    if v_rule.id is not null and v_rule.guest_allowance = 0 then
      return jsonb_build_object('severity','block','kind','tier_no_guest',
        'venue_name', v_venue.name, 'program_name', v_prog.name, 'host_tier', v_ent.tier,
        'headline','Kart tipinde misafir hakkı yok',
        'detail', coalesce(v_rule.notes,'') || ' Bu kartla salona girebilirsin ama yanında misafir götüremezsin.');
    elsif v_rule.id is not null then
      v_count := least(v_count, v_rule.guest_allowance);
    end if;
  end if;

  if v_head is null then
    if v_acc.guest_policy = 'paid' then
      v_sev := 'warn';
      v_head := 'Misafir girişi ücretli';
      v_notes := v_notes || public.rule_notice(
        case coalesce(v_acc.fee_payer, v_prog.fee_payer,'unknown')
          when 'member_card' then 'fee_note_member_card'
          when 'guest_at_door' then 'fee_note_guest_at_door'
          else 'rule_notice_generic' end);
    elsif v_acc.guest_policy = 'unknown' then
      v_sev := 'warn'; v_head := 'Bu salonun misafir kuralı doğrulanmadı';
      v_notes := v_notes || public.rule_notice('rule_notice_generic');
    else
      v_sev := 'ok';
      v_head := case when v_count > 0
        then format('Misafir hakkın var — %s kişi, ek ücret yok', v_count)
        else 'Misafir kabul ediliyor' end;
    end if;
  end if;

  case coalesce(v_acc.guest_flight_coupling, v_prog.guest_flight_coupling, 'any')
    when 'same_flight'  then v_notes := v_notes || ('Misafirin SENİNLE AYNI UÇUŞTA olmalı — ilanına uçuş numaranı ekle.')::text;
    when 'same_carrier' then v_notes := v_notes || ('Misafirin de aynı havayolunda uçuyor olmalı.')::text;
    when 'same_alliance' then v_notes := v_notes || ('Misafirin ittifak üyesi bir havayolunda uçuyor olmalı.')::text;
    else null;
  end case;
  if v_acc.max_stay_hours is not null then
    v_notes := v_notes || format('Salonda kalış ~%s saatle sınırlı.', trim(to_char(v_acc.max_stay_hours,'FM990.0')));
  end if;

  return jsonb_build_object('severity', v_sev, 'kind','rule',
    'venue_name', v_venue.name, 'program_name', v_prog.name, 'host_tier', v_ent.tier,
    'guest_policy', v_acc.guest_policy, 'guest_included_count', v_count,
    'fee_payer', coalesce(v_acc.fee_payer, v_prog.fee_payer),
    'headline', v_head, 'detail', array_to_string(v_notes,' '));
end $$;

-- ----------------------------------------------------------------------
-- request_precheck   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ⚠ Bu fonksiyon 11 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.request_precheck(p_avail_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare j jsonb; d jsonb; v_kod text;
begin
  j := public.request_precheck_pregate(p_avail_id);
  if coalesce((j ->> 'can_request')::boolean, false) is not true then
    return j;
  end if;
  d := public.lounge_access_decision(p_avail_id, null);
  if (d ->> 'guest_policy') = 'not_allowed'
     or ((d ->> 'severity') = 'block' and coalesce(d ->> 'fits','') <> 'false') then
    return j || jsonb_build_object(
      'can_request', false, 'needs_ack', false, 'severity', 'block', 'gate', 'server',
      'headline', coalesce(nullif(d ->> 'headline',''), 'Bu ilana misafir alınamıyor'),
      'detail', coalesce(nullif(j ->> 'detail',''), d ->> 'detail'));
  end if;
  -- 301/§6: kuru koşu
  begin
    perform public.create_request(p_avail_id, 'lounge', null, null);
    raise exception 'GERI_AL_ONKONTROL_GECER';
  exception when others then
    v_kod := sqlerrm;
  end;
  if v_kod is distinct from 'GERI_AL_ONKONTROL_GECER' then
    return j || jsonb_build_object(
      'can_request', false, 'needs_ack', false, 'severity', 'block',
      'gate', v_kod, 'headline', null);   -- metni uygulama `e_<kod>` ile çevirir (TR/EN)
  end if;
  return j;
end $$;

-- ----------------------------------------------------------------------
-- discovery_rule_badges   [etkin kaynak: 221_hosta_sor.sql]
-- ⚠ Bu fonksiyon 6 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.discovery_rule_badges(p_ids uuid[])
returns table (
  avail_id uuid, severity text, label text, info text, detail text,
  same_flight_match boolean, blocks_request boolean, sort_boost int,
  can_ask_host boolean
) language plpgsql stable security definer set search_path = public as $$
declare
  r record; d jsonb; b jsonb; v_flight text; v_key text;
  v_boost int; v_same boolean; v_block boolean; v_prog lounge_programs%rowtype;
begin
  foreach avail_id in array coalesce(p_ids, '{}'::uuid[]) loop
    select * into r from availabilities where id = avail_id;
    continue when not found;

    select v.flight_number into v_flight from visits v
     where v.user_id = auth.uid() and v.airport_code = r.airport_code
       and v.visit_date = r.avail_date and coalesce(v.flight_number,'') <> ''
     order by v.created_at desc limit 1;

    d := public.lounge_access_decision_v5(avail_id, v_flight, public.guest_carrier_for(avail_id));
    select * into v_prog from lounge_programs where id = nullif(d ->> 'program_id','')::uuid;

    v_same := coalesce(v_flight,'') <> '' and coalesce(r.flight_number,'') <> ''
              and upper(replace(v_flight,' ','')) = upper(replace(r.flight_number,' ',''));

    v_block := coalesce((d ->> 'severity') = 'block' and (d ->> 'enforcement') = 'block', false)
               or coalesce((d ->> 'carrier_ok') = 'false', false)
               or coalesce((d ->> 'charter') = 'true', false);
    if v_prog.id is null or v_prog.entitlement_model = 'bank_card' then
      v_block := false;
    end if;

    v_boost := 0;
    if v_block then                                  v_key := 'guest_none';  v_boost := -1000;
    elsif v_same then                                v_key := 'same_flight'; v_boost := 100;
    elsif (d ->> 'fits') = 'false' then              v_key := 'flight_bad';  v_boost := -100;
    elsif (d ->> 'guest_policy') = 'not_allowed' then
      v_key := 'guest_none_soft'; v_boost := -200;
    elsif (d ->> 'guest_policy') = 'paid' then       v_key := 'guest_paid';  v_boost := -20;
    elsif (d ->> 'confidence') in ('unknown','assumed') then v_key := 'unverified'; v_boost := -10;
    elsif (d ->> 'guest_policy') = 'included' then   v_key := 'guest_free';  v_boost := 20;
    else v_key := null;
    end if;

    -- 219 kapı hizası korunuyor
    if (d ->> 'guest_policy') = 'not_allowed' then
      v_block := true;
    end if;

    b := case when v_key is null then null else public.badge_text(v_key) end;

    severity := coalesce(d ->> 'severity','info');
    label    := b ->> 'label';
    info     := b ->> 'info';
    detail   := d ->> 'headline';
    same_flight_match := v_same;
    blocks_request := v_block;
    sort_boost := v_boost;
    can_ask_host := public.kural_sorusu_uygun_mu(avail_id);
    return next;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- flight_fetch_allow   [etkin kaynak: 225_planin_sozu_tutulsun.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.flight_fetch_allow(p_user_id uuid, p_flight text, p_day date)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_on    boolean := coalesce((select (value #>> '{}')::boolean from beta_settings where key='flight_autofetch'), true);
  v_ud    int     := coalesce((select (value #>> '{}')::int from beta_settings where key='flight_user_daily'), 3);
  v_mc    int     := coalesce((select (value #>> '{}')::int from beta_settings where key='flight_month_cap'), 80);
  v_user  int;
  v_month int;
  v_out   text;
  v_plan_ay int;      -- planın aylık uçuş doğrulama hakkı
  v_kul_ay  int;      -- kullanıcının bu ay harcadığı
begin
  if not v_on then v_out := 'denied_off';
  else
    -- 🔴 PENCERE Europe/Istanbul'a bağlandı. `date_trunc('day', now())`
    -- sunucu UTC'sine göre çalışıyordu; Türkiye'de kota gece 03:00'te
    -- yenileniyordu ve kullanıcıya "gece yarısı" diyecektik.
    select count(*) into v_user from flight_fetch_log
     where user_id = p_user_id and outcome = 'provider'
       and created_at >= (date_trunc('day', timezone('Europe/Istanbul', now()))
                            at time zone 'Europe/Istanbul');
    select count(*) into v_month from flight_fetch_log
     where outcome = 'provider'
       and created_at >= (date_trunc('month', timezone('Europe/Istanbul', now()))
                            at time zone 'Europe/Istanbul');

    -- Planın aylık havuzu (225): günlük hak bittiğinde devreye girer.
    select coalesce(p.ucus_dogrulama_ayda, 0) into v_plan_ay
      from users u left join plan_catalog p on p.plan = u.plan and p.aktif
     where u.id = p_user_id;
    v_plan_ay := coalesce(v_plan_ay, 0);

    select count(*) into v_kul_ay from flight_fetch_log
     where user_id = p_user_id and outcome = 'provider'
       and created_at >= (date_trunc('month', timezone('Europe/Istanbul', now()))
                            at time zone 'Europe/Istanbul');

    if v_month >= v_mc then
      -- Platform tavanı herkesi bağlar; plan bunu aşamaz (maliyet freni).
      v_out := 'denied_month_cap';
    elsif v_user < v_ud then
      v_out := 'provider';                       -- günlük hak duruyor
    elsif v_kul_ay < v_plan_ay then
      v_out := 'provider';                       -- 225: planın aylık havuzu
    else
      v_out := 'denied_user_cap';
    end if;
  end if;

  insert into flight_fetch_log (user_id, flight_no, flight_day, outcome)
  values (p_user_id, upper(trim(coalesce(p_flight,''))), p_day, v_out);

  return jsonb_build_object(
    'allow', v_out = 'provider',
    'reason', v_out,
    'user_today', coalesce(v_user,0), 'user_cap', v_ud,
    'plan_month_used', coalesce(v_kul_ay,0), 'plan_month_cap', coalesce(v_plan_ay,0),
    'month_used', coalesce(v_month,0), 'month_cap', v_mc);
end $$;

-- ----------------------------------------------------------------------
-- flight_info   [etkin kaynak: 195_ucus_alanlari_ve_kod_paylasimi.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.flight_info(p_flight_no text, p_date date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v flight_cache%rowtype; v_car jsonb;
begin
  if coalesce(p_flight_no,'') = '' or p_date is null then
    return jsonb_build_object('hit', false, 'reason', 'eksik_parametre');
  end if;
  select * into v from flight_cache
   where upper(replace(flight_no,' ','')) = upper(replace(trim(p_flight_no),' ',''))
     and flight_date = p_date;
  if not found then
    return jsonb_build_object('hit', false,
      'autofetch', coalesce((select (value #>> '{}')::boolean from beta_settings where key='flight_autofetch'), true));
  end if;

  v_car := public.flight_carrier_resolve(v.flight_no, v.flight_date);

  return jsonb_build_object('hit', true,
    -- --- ESKİ SÖZLEŞME (dokunulmadı) ---
    'scheduled_departure', v.scheduled_departure,
    'terminal', v.terminal, 'gate', v.gate,
    'status', v.status, 'source', v.source, 'fetched_at', v.fetched_at,
    'stale', v.fetched_at < now() - interval '12 hours',
    -- --- 195: APP'İN OKUDUĞU AMA GELMEYEN ALANLAR ---
    'flight_no',   v.flight_no,
    'flight_date', v.flight_date,
    'dep_iata',    v.departure_iata,
    'arr_iata',    v.arrival_iata,
    'dep_time',    v.scheduled_departure,
    'arr_time',    v.scheduled_arrival,
    'airline',     v.airline,
    'airline_iata', coalesce(v.airline_iata,
                             upper(substring(regexp_replace(v.flight_no, '[^A-Za-z]', '', 'g') from 1 for 2))),
    -- --- 195: KOD PAYLAŞIMI ---
    'operating_iata', v_car ->> 'carrier',
    'codeshare',      coalesce((v_car ->> 'codeshare')::boolean, false),
    'carrier_note',   v_car ->> 'not');
end $$;

-- ----------------------------------------------------------------------
-- flight_quota_report   [etkin kaynak: 091_flight_quota.sql]
-- ----------------------------------------------------------------------
create or replace function public.flight_quota_report()
returns table (gun date, saglayici int, onbellek int, reddedilen int)
language sql stable security definer set search_path = public as $$
  select created_at::date,
         count(*) filter (where outcome = 'provider')::int,
         count(*) filter (where outcome = 'cache')::int,
         count(*) filter (where outcome like 'denied%')::int
    from flight_fetch_log
   where created_at >= now() - interval '45 days'
   group by 1 order by 1 desc;
$$;

-- ----------------------------------------------------------------------
-- save_host_access   [etkin kaynak: 100_tier_fee_and_time.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.save_host_access(
  p_sources            text[]   default null,
  p_guest_capacity     smallint default null,
  p_guest_fee_expected boolean  default null,
  p_quota_total        smallint default null,
  p_quota_period       text     default null,
  p_quota_used         smallint default null,
  p_card_product_id    uuid     default null,
  p_card_tier          text     default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid  uuid := auth.uid();
  v_txt  text;
  v_prog uuid;
  v_card lounge_card_products%rowtype;
  v_ent  uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_quota_period is not null and p_quota_period not in ('year','month','unlimited') then
    raise exception 'invalid_quota_period';
  end if;
  if p_quota_total is not null and p_quota_used is not null and p_quota_used > p_quota_total then
    raise exception 'quota_used_exceeds_total';
  end if;

  v_txt := nullif(array_to_string(coalesce(p_sources, '{}'::text[]), ', '), '');

  update profiles
     set access_source      = coalesce(v_txt, access_source),
         guest_capacity     = coalesce(p_guest_capacity, guest_capacity),
         guest_fee_expected = coalesce(p_guest_fee_expected, guest_fee_expected),
         updated_at         = now()
   where user_id = v_uid;

  if p_card_product_id is not null then
    select * into v_card from lounge_card_products where id = p_card_product_id and active;
    if found then v_prog := v_card.program_id; end if;
  end if;
  if v_prog is null then
    v_prog := public.match_program_by_text(coalesce(v_txt,
                (select access_source from profiles where user_id = v_uid)));
  end if;

  if v_prog is not null then
    -- 🔴 Ayni program icin FARKLI tier'da eski satir varsa temizle:
    -- benzersiz indeks (user, program, coalesce(tier,'')) oldugu icin
    -- tier degisince ikinci satir olusur ve karar motoru eskisini secebilir.
    delete from host_entitlements
     where user_id = v_uid and program_id = v_prog
       and coalesce(tier,'') is distinct from coalesce(p_card_tier,'');

    insert into host_entitlements
      (user_id, program_id, tier, card_product_id, guest_capacity, origin, note,
       quota_total, quota_period, quota_used, self_reported_at)
    values
      (v_uid, v_prog, p_card_tier, p_card_product_id, p_guest_capacity, 'declared',
       'save_host_access',
       coalesce(p_quota_total, v_card.quota_total),
       coalesce(p_quota_period, v_card.quota_period),
       coalesce(p_quota_used, 0), now())
    on conflict (user_id, program_id, coalesce(tier,''))
    do update set
      card_product_id  = coalesce(excluded.card_product_id, host_entitlements.card_product_id),
      guest_capacity   = coalesce(excluded.guest_capacity, host_entitlements.guest_capacity),
      quota_total      = coalesce(excluded.quota_total, host_entitlements.quota_total),
      quota_period     = coalesce(excluded.quota_period, host_entitlements.quota_period),
      quota_used       = coalesce(excluded.quota_used, host_entitlements.quota_used),
      self_reported_at = now(), origin = 'declared'
    returning id into v_ent;
  end if;

  return jsonb_build_object('ok', true, 'program_id', v_prog, 'tier', p_card_tier,
    'entitlement_id', v_ent,
    'quota', case when v_ent is null then null else public.entitlement_remaining(v_ent) end);
end $$;

-- ----------------------------------------------------------------------
-- my_host_access   [etkin kaynak: 095_close_the_loop.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.my_host_access()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); p profiles%rowtype; e host_entitlements%rowtype; c lounge_card_products%rowtype;
begin
  select * into p from profiles where user_id = v_uid;
  select * into e from host_entitlements where user_id = v_uid
   order by self_reported_at desc nulls last, created_at desc limit 1;
  if e.card_product_id is not null then
    select * into c from lounge_card_products where id = e.card_product_id;
  end if;
  return jsonb_build_object(
    'access_source', p.access_source,
    'guest_capacity', p.guest_capacity,
    'guest_fee_expected', p.guest_fee_expected,
    'card_product_id', e.card_product_id,
    'card_name', c.name,
    'quota_total', e.quota_total,
    'quota_period', e.quota_period,
    'quota_used', e.quota_used,
    'quota', case when e.id is null then null else public.entitlement_remaining(e.id) end);
end $$;

