-- host_declares_paid_guest   [etkin kaynak: 092_host_access_declaration.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_declares_paid_guest(p_host uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select guest_fee_expected from profiles where user_id = p_host), false);
$$;

-- ----------------------------------------------------------------------
-- set_featured_reward   [etkin kaynak: 093_reward_featured.sql]
-- ----------------------------------------------------------------------
create or replace function public.set_featured_reward(p_reward_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_title text; v_active boolean;
begin
  if p_reward_id is null then
    update rewards set is_featured = false where is_featured;
    return jsonb_build_object('ok', true, 'featured', null);
  end if;

  select title, coalesce(active, true) into v_title, v_active
    from rewards where id = p_reward_id;
  if not found then raise exception 'reward_not_found'; end if;
  if not v_active then raise exception 'reward_inactive'; end if;

  update rewards set is_featured = false where is_featured and id <> p_reward_id;
  update rewards set is_featured = true  where id = p_reward_id;
  return jsonb_build_object('ok', true, 'featured', p_reward_id, 'title', v_title);
end $$;

-- ----------------------------------------------------------------------
-- admin_anonymize_user   [etkin kaynak: 258_olmayan_kolonlar.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_anonymize_user(p_user_id uuid, p_admin text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tag text;
begin
  perform 1 from users where id = p_user_id;
  if not found then raise exception 'user_not_found'; end if;
  if (select anonymized_at from users where id = p_user_id) is not null then
    return jsonb_build_object('ok', true, 'already', true);
  end if;

  -- Silinen kişiyi arayanların bir şey bulabilmesi için kısa bir etiket.
  -- Ham e-postanın hiçbir izi kalmaz; yalnız "kimdi" değil "kaçıncı"ydı.
  v_tag := 'silinmis-' || left(replace(p_user_id::text, '-', ''), 8);

  -- 1) KİMLİK
  update users
     set email = v_tag || '@silinmis.loungelink',
         phone = null,
         anonymized_at = now(),
         anonymized_by = p_admin
   where id = p_user_id;

  -- 2) PROFİL — serbest metinlerin hepsi kişisel veri taşıyabilir
  update profiles
     set name = 'Silinmiş kullanıcı',
         bio = null, profession = null, photo_url = null,
         linkedin_url = null, linkedin_verified = false,
         access_source = null,
         show_on_discovery = false, profile_visibility = 'Connections',
         updated_at = now()
   where user_id = p_user_id;

  -- 3) DOĞRULAMA İZLERİ
  update verifications
     set phone_verified = false, id_verified = false
   where user_id = p_user_id;

  -- 4) SERBEST METİN İÇEREN KAYITLAR
  -- Mesajlar SİLİNMEZ: karşı tarafın sohbeti delik deşik olur ve bir
  -- itiraz durumunda bağlam kaybolur. İçerik yerine yazarı anonimleşir.
  update reports set description = '[anonimlestirildi]'
   where reporter_id = p_user_id;
  update ratings set comment = null
   where rater_id = p_user_id;
  delete from push_tokens      where user_id = p_user_id;
  delete from otp_tokens       where user_id = p_user_id;
  delete from visits           where user_id = p_user_id and visit_date >= current_date;
  delete from availabilities   where host_id = p_user_id and avail_date >= current_date;
  delete from host_entitlements where user_id = p_user_id;

  -- 5) OTURUMU KAPAT — kullanıcı bir daha giremesin
  delete from auth.sessions  where user_id = p_user_id;
  delete from auth.identities where user_id = p_user_id;
  update auth.users
     set email = v_tag || '@silinmis.loungelink',
         phone = null,
         raw_user_meta_data = '{}'::jsonb,
         banned_until = 'infinity'
   where id = p_user_id;

  -- 🔴 Denetim kaydını BURADA yazmıyoruz. audit_log'un kolonları
  -- (actor_id uuid, entity_type, before_data, after_data) BO'nun audit()
  -- yardımcısıyla yazılıyor; buradan ikinci bir yol açmak iki farklı
  -- şemayla iki farklı kayıt üretirdi. Çağıran BO action'ı audit() çağırır.

  return jsonb_build_object('ok', true, 'tag', v_tag);
end $function$;

-- ── request_account_deletion ──
CREATE OR REPLACE FUNCTION public.request_account_deletion(p_email text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(p_email,'') !~ '^[^@]+@[^@]+\.[^@]+$' then
    raise exception 'invalid_email';
  end if;
  -- 🔴 SILME OTOMATIK DEGIL. E-postasini bilen herkesin baskasinin
  -- hesabini silebilmesi demek olurdu. Talep kaydedilir, BO'da
  -- kullanici dogrulandiktan SONRA islenir.
  insert into deletion_requests (email, note)
  values (lower(trim(p_email)), nullif(trim(coalesce(p_reason,'')),''))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id,
    'note', 'Talebin alindi. Kimligini dogruladiktan sonra 30 gun icinde islenecek.');
end $function$;

-- ── bo_plan_ata ──
CREATE OR REPLACE FUNCTION public.bo_plan_ata(p_user uuid, p_plan text, p_sebep text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_eski text;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select plan::text into v_eski from users where id = p_user;
  if v_eski is null then raise exception 'kullanici_yok'; end if;

  update users set plan = p_plan::plan_type, updated_at = now() where id = p_user;

  insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
  values (auth.uid(), 'plan_ata', 'user', p_user,
          jsonb_build_object('eski', v_eski, 'yeni', p_plan, 'sebep', p_sebep));

  return jsonb_build_object('ok', true, 'eski', v_eski, 'yeni', p_plan);
end $function$;

-- ── trg_cinsiyet_kilidi ──
CREATE OR REPLACE FUNCTION public.trg_cinsiyet_kilidi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.gender is not null and new.gender is distinct from old.gender then
    -- Yönetim değiştirebilir; kullanıcı değiştiremez.
    if auth.uid() is not null
       and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
      raise exception 'cinsiyet_degistirilemez';
    end if;
    insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
    values (auth.uid(), 'cinsiyet_degisti', 'user', new.id,
            jsonb_build_object('eski', old.gender, 'yeni', new.gender));
  end if;
  return new;
end $function$;

-- ── 3 · NÖBETÇİ ─────────────────────────────────────────────────────
-- 🔴 Bu blok kolonların VARLIĞINI değil, YAZILABİLİRLİĞİNİ ölçüyor.
-- "information_schema'da var mı" sorusu bu hatayı yakalamazdı: hata
-- zaten ifade ÇÖZÜMLENDİĞİNDE çıkıyor. O yüzden her düzeltilen yol
-- gerçekten bir kez çalıştırılıyor ve sonra geri alınıyor.
--
-- 🆕 SINIF: "BİR KOLONUN ŞEMADA GÖRÜNMESİ, O KOLONA YAZAN KODUN
-- ÇALIŞTIĞI ANLAMINA GELMEZ — YAZMA YOLUNU BİR KEZ YÜRÜT."
do $n258$
declare
  v_h text[] := '{}';
  v_u uuid; v_r uuid;
begin
  begin
    select id into v_u from users limit 1;

    -- points_ledger.balance_after gerçekten yazılabiliyor mu
    insert into points_ledger (user_id, delta, reason, ref_id, balance_after)
    values (v_u, 1, 'n258_olcum', null, 1);

    -- requests.decision_note gerçekten yazılabiliyor mu
    select id into v_r from requests limit 1;
    if v_r is not null then
      update requests set decision_note = coalesce(decision_note, 'n258 ölçüm')
       where id = v_r;
    end if;

    -- audit_log'un doğru kolonları
    insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
    values (v_u, 'n258_olcum', 'user', v_u, jsonb_build_object('olcum', true));

    -- reports.description ve deletion_requests.note
    insert into deletion_requests (email, note)
    values ('n258@olcum.invalid', 'olcum');

    raise exception 'GERI_AL_258';
  exception when others then
    if sqlerrm <> 'GERI_AL_258' then
      v_h := v_h || ('olcum coktu: ' || sqlerrm);
    end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '258 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '258 OK · eksik iki kolon eklendi · alti etkin fonksiyonun kolon adlari duzeltildi · yazma yollari calistirilarak dogrulandi';
end $n258$;

commit;

select '258 OLMAYAN KOLONLAR' as sonuc,
       (select count(*) from information_schema.columns
         where table_name='points_ledger' and column_name='balance_after') as pl_balance_after,
       (select count(*) from information_schema.columns
         where table_name='requests' and column_name='decision_note') as req_decision_note;

-- ----------------------------------------------------------------------
-- anonymized_users   [etkin kaynak: 094_admin_erasure.sql]
-- ----------------------------------------------------------------------
create or replace function public.anonymized_users()
returns table (user_id uuid, tag text, at timestamptz, by_admin text)
language sql stable security definer set search_path = public as $$
  select id, email, anonymized_at, anonymized_by
    from users where anonymized_at is not null
   order by anonymized_at desc;
$$;

-- ----------------------------------------------------------------------
-- submit_field_report   [etkin kaynak: 187_kanitlanmis_kusurlar.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.submit_field_report(
  p_session_id uuid,
  p_entered boolean,
  p_guest_accepted boolean default null,
  p_fee_charged boolean default null,
  p_fee_amount text default null,
  p_quota_left text default null,
  p_note text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  s sessions%rowtype;
  r requests%rowtype;          -- 🔴 187: host/guest/avail BURADA
  v_venue uuid; v_prog uuid; v_tier text; v_outcome text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into s from sessions where id = p_session_id;
  if not found then raise exception 'session_not_found'; end if;
  select * into r from requests where id = s.request_id;
  if not found then raise exception 'session_not_found'; end if;

  -- 152'nin taşıdığı iki garanti KORUNUYOR (drift_check bunları
  -- bir kez kaybettiğimizi yakalamıştı; bir daha kaybetmiyoruz).
  if v_uid not in (r.host_id, r.guest_id) then raise exception 'not_party'; end if;
  if p_entered is null then raise exception 'invalid_outcome'; end if;

  -- Salon: önce katalog yolu, tutmazsa 161'in venue çözümleyicisi.
  -- Tek yola güvenmek 158/160/161'in katalog uzlaştırmasından sonra
  -- bir ortamda boş dönebiliyor; yedek yol veriyi kurtarır.
  select l.venue_id into v_venue
    from availabilities a join lounges l on l.id = a.lounge_id
   where a.id = r.avail_id;
  if v_venue is null then
    v_venue := public.resolve_venue_for_availability(r.avail_id);
  end if;

  select he.program_id, he.tier into v_prog, v_tier
    from host_entitlements he where he.user_id = r.host_id limit 1;

  -- 🔴 187 (İKİNCİ KATMAN): `outcome` NOT NULL (087:231) ve
  -- lfr_outcome_chk ile dört değere kısıtlı. 152 bu kolonu HİÇ
  -- yazmıyordu → 23502. İlk hata (`s.host_id`) düzeltilince ikincisi
  -- ortaya çıktı: aynı fonksiyonda İKİ ayrı şema-hafızadan-yazma
  -- hatası üst üste duruyormuş. Boolean cevaplar buradan türetilir.
  v_outcome := case
    when p_entered is not true                      then 'refused'
    when coalesce(p_fee_charged, false)             then 'admitted_paid'
    else                                                 'admitted_free'
  end;

  insert into lounge_field_reports
    (session_id, reporter_id, venue_id, program_id, card_tier,
     outcome, fee_paid, fee_currency,
     entered, guest_accepted, fee_charged, fee_amount, quota_left, note)
  values (p_session_id, v_uid, v_venue, v_prog, v_tier,
          v_outcome,
          nullif(regexp_replace(coalesce(p_fee_amount, ''), '[^0-9.]', '', 'g'), '')::numeric,
          case when coalesce(p_fee_amount, '') = '' then null
               when p_fee_amount ~* 'usd|\\$'      then 'USD'
               when p_fee_amount ~* 'eur|€'         then 'EUR'
               else 'TRY' end,
          p_entered, p_guest_accepted, p_fee_charged, p_fee_amount, p_quota_left, p_note)
  on conflict (session_id, reporter_id) do update set
    outcome = excluded.outcome, fee_paid = excluded.fee_paid,
    fee_currency = excluded.fee_currency,
    entered = excluded.entered, guest_accepted = excluded.guest_accepted,
    fee_charged = excluded.fee_charged, fee_amount = excluded.fee_amount,
    quota_left = excluded.quota_left, note = excluded.note;

  return jsonb_build_object('ok', true,
    'note', 'Teşekkürler — bu bilgi kural tablomuzu güncelliyor.');
end $$;

-- ----------------------------------------------------------------------
-- card_product_options   [etkin kaynak: 145_null_sort_guard.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.card_product_options()
returns table (
  id uuid, issuer text, name text, program text, segment text,
  quota_total smallint, quota_period text, conditions text,
  confidence text, verified boolean, source_url text
) language sql stable security definer set search_path = public as $$
  select cp.id, i.name, cp.name, p.name, cp.segment,
         cp.quota_total, cp.quota_period, cp.conditions,
         coalesce(cp.confidence, 'unknown'),
         (coalesce(cp.confidence,'') = 'verified' and cp.checked_at is not null),
         cp.source_url
    from lounge_card_products cp
    join lounge_issuers i on i.id = cp.issuer_id and i.active
    left join lounge_programs p on p.id = cp.program_id
   where cp.active and (cp.valid_to is null or cp.valid_to >= current_date)
   -- 🔴 coalesce SART: `null = 'verified'` -> NULL -> DESC'te EN BASA.
   -- Guven derecesi bilinmeyen kart, dogrulanmis kartin ustune cikardi.
   order by coalesce(cp.confidence = 'verified', false) desc,
            i.name, cp.name;
$$;

-- ----------------------------------------------------------------------
-- autofill_venue_acceptance   [etkin kaynak: 096_rule_autofill.sql]
-- ----------------------------------------------------------------------
create or replace function public.autofill_venue_acceptance(
  p_venue_id uuid default null,     -- null = tüm aktif salonlar
  p_dry_run  boolean default false
) returns table (venue text, program text, policy text, eylem text)
language plpgsql security definer set search_path = public as $$
declare r record;
begin
  for r in
    select v.id as vid, v.name as vname, v.airport_code, v.section,
           p.id as pid, p.code as pcode, p.name as pname,
           p.guest_default, p.guest_included_count, p.guest_flight_coupling,
           p.typical_guest_fee, p.guest_fee_currency, p.max_stay_hours,
           p.entitlement_model
      from lounge_venues v
      cross join lounge_programs p
     where v.active and p.active
       and (p_venue_id is null or v.id = p_venue_id)
       -- Zaten satırı olan hücreye DOKUNMA (elle girilmiş olabilir)
       and not exists (select 1 from lounge_venue_acceptance a
                        where a.venue_id = v.id and a.program_id = p.id)
       -- 🔴 HAVAYOLU PROGRAMLARINI OTOMATİK YAYMA. "TK Miles&Smiles
       -- Plaza Premium'da geçerlidir" gibi bir varsayım üretmek,
       -- bilmemekten kötüdür: havayolu salonları programa BAĞLIDIR,
       -- kart programları ise genellikle geniş ağlıdır.
       and p.entitlement_model in ('card_membership','paid_entry','operator_program')
       -- İşletmeci programı yalnız KENDİ salonuna uygulanır
       and (p.entitlement_model <> 'operator_program'
            or lower(v.name) like '%' || lower(split_part(p.name, ' ', 1)) || '%')
  loop
    if not p_dry_run then
      insert into lounge_venue_acceptance
        (venue_id, program_id, accepted, guest_policy, guest_included_count,
         guest_fee_amount, guest_fee_currency, guest_flight_coupling,
         max_stay_hours, enforcement, conditions, checked_at)
      values
        (r.vid, r.pid, true,
         -- 🔴 GOKBERK'İN KARARI (7 Ağu): bilmediğimiz hücrede program
         -- varsayılanını GERÇEK gibi yazmıyoruz. Bilinmeyen "unknown"
         -- kalır → karar motoru confidence='unknown' üretir → kullanıcıya
         -- BO'dan düzenlenebilen GENEL UYARI çıkar.
         --
         -- Neden: bir salonun bir programı kabul edip etmediği, o programın
         -- kendi kuralından BAĞIMSIZ bir olgudur. "Priority Pass ziyaret
         -- başı ücretlidir" doğrudur; "bu salon Priority Pass kabul eder"
         -- ise AYRI bir iddiadır ve elimizde kanıtı yoktur. İkisini
         -- karıştırmak, bilmediğimizi biliyormuş gibi göstermektir.
         'unknown',
         0, null, null,
         r.guest_flight_coupling,      -- program olgusu: bunu biliyoruz
         r.max_stay_hours,
         'warn',                       -- otomatik satır ASLA engellemez
         'Bu salonun bu programı kabul edip etmediği DOĞRULANMADI (096 otomatik satır). '
         || 'Programın kendi kuralı: '
         || case r.guest_default
              when 'paid'     then 'misafir girişi ziyaret başı ÜCRETLİDİR'
              when 'included' then 'misafir hakkı programa dahildir'
              when 'not_allowed' then 'program misafir kabul etmiyor'
              else 'misafir politikası tanımsız' end
         || coalesce(' (yaklaşık ' || r.typical_guest_fee::text || ' ' || r.guest_fee_currency || ')', '')
         || '. Salon kabulü sahada doğrulanınca "Doğruladım" ile işaretle.',
         null)                         -- checked_at NULL = doğrulanmadı
      on conflict (venue_id, program_id) do nothing;
    end if;

    venue   := r.airport_code || ' · ' || r.vname
               || case when r.section is not null then ' (' || r.section || ')' else '' end;
    program := r.pcode;
    policy  := coalesce(nullif(r.guest_default,''), 'unknown');
    eylem   := case when p_dry_run then 'eklenecek' else 'eklendi' end;
    return next;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- card_tier_options   [etkin kaynak: 233_statu_listesi_tekillesiyor.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.card_tier_options(p_program_code text)
returns table (tier text, label text, guest_allowance smallint,
               family_allowed boolean, note text)
language sql stable security definer set search_path = public as $cto$
  -- Statü başına TEK satır. Hangi satırın kazanacağı rastgele değil:
  --   1) en cömert misafir hakkı (kullanıcı kendi tavanını görsün)
  --   2) aile hakkı olan
  --   3) koşulsuz olan (carrier/venue/scope null = "her durumda")
  -- Böylece kurulum ekranı statünün EN GENİŞ hâlini gösterir; daralma
  -- kararını kural motoru uçuş/salon bilindiğinde zaten veriyor.
  select distinct on (r.card_tier)
         r.card_tier,
         public.card_tier_label(r.card_tier),   -- 184: TEK kaynak
         r.guest_allowance,
         r.family_allowed,
         -- Not artık gruplama anahtarı DEĞİL, yalnız gösterim.
         r.notes
    from lounge_guest_rules r
    join lounge_programs p on p.id = r.program_id
   where p.code = p_program_code
     and r.card_tier is not null
     and (r.effective_to is null or r.effective_to >= current_date)
   order by r.card_tier,
            r.guest_allowance desc nulls last,
            r.family_allowed desc nulls last,
            (r.carrier is null) desc,
            (r.venue_id is null) desc,
            (r.venue_scope is null) desc,
            r.notes nulls last;
$cto$;
grant execute on function public.card_tier_options(text) to authenticated;

comment on function public.card_tier_options(text) is
  'Kurulum ekranindaki statu listesi. STATU BASINA TEK SATIR: lounge_guest_rules '
  'bir kosul-sonuc matrisidir, statu katalogu degildir. Etiket card_tier_label() '
  'tek kaynagindan gelir (184).';

-- ----------------------------------------------------------------------------
-- NÖBETÇİ — "tekilleşti" bir iddiadır; ölçüyorum
-- ----------------------------------------------------------------------------
do $n233$
declare
  r        record;
  v_cift   int := 0;
  v_toplam int := 0;
  v_prog   int := 0;
  v_etiket int;
  v_ornek  text := '';
begin
  -- Her program için: dönen satır sayısı = farklı statü sayısı olmalı.
  for r in select code from lounge_programs where coalesce(active,true) loop
    v_prog := v_prog + 1;
    declare
      v_satir int; v_farkli int;
    begin
      select count(*), count(distinct tier) into v_satir, v_farkli
        from public.card_tier_options(r.code);
      v_toplam := v_toplam + v_satir;
      if v_satir <> v_farkli then
        v_cift := v_cift + (v_satir - v_farkli);
        v_ornek := v_ornek || r.code || '(' || v_satir || '/' || v_farkli || ') ';
      end if;
    end;
  end loop;

  if v_cift <> 0 then
    raise exception '233 NOBETCI: statu listesinde hala % fazla satir var — %', v_cift, v_ornek;
  end if;

  -- Etiket sürüklenmesi: hiçbir satır card_tier_label()'dan FARKLI ad taşımasın.
  select count(*) into v_etiket
    from lounge_programs p
    cross join lateral public.card_tier_options(p.code) o
   where coalesce(p.active,true)
     and o.label is distinct from public.card_tier_label(o.tier);
  if v_etiket <> 0 then
    raise exception '233 NOBETCI: % statu etiketi card_tier_label() ile uyusmuyor.', v_etiket;
  end if;

  raise notice '233 OK · % program · % statu satiri · cift: 0 · etiket sapmasi: 0',
    v_prog, v_toplam;
  raise notice '233 NOT: lounge_guest_rules TEKILLESTIRILMEDI — matris oldugu gibi duruyor. '
               'Duzelen tek sey kullaniciya sunulan projeksiyon.';
end $n233$;

select '233 STATU LISTESI TEKILLESTI' as sonuc,
       (select count(*) from public.card_tier_options('TK_MS'))    as tk_ms_secenek,
       (select count(distinct tier) from public.card_tier_options('TK_MS')) as tk_ms_farkli;

-- ----------------------------------------------------------------------
-- program_needs_tier   [etkin kaynak: 100_tier_fee_and_time.sql]
-- ----------------------------------------------------------------------
create or replace function public.program_needs_tier(p_program_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from lounge_guest_rules r
                  where r.program_id = p_program_id and r.card_tier is not null
                    and (r.effective_to is null or r.effective_to >= current_date));
$$;

-- ----------------------------------------------------------------------
-- lounge_access_decision_v3   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ⚠ Bu fonksiyon 5 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_access_decision_v3(
  p_avail_id     uuid,
  p_guest_flight text default null
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  d          jsonb;
  v_av       availabilities%rowtype;
  v_ent      host_entitlements%rowtype;
  v_prog_id  uuid;
  v_rule     lounge_guest_rules%rowtype;
  v_venue_id uuid;
  v_needs_tier boolean := false;
  v_extra    text[] := '{}';
  v_sev      text;
  v_policy   text;
  v_count    smallint;
  v_payer    text;
  v_stay     numeric;
  v_entry    numeric;
  v_dur      numeric;
  v_dep      timestamptz;
  v_head     text;
begin
  d := public.lounge_access_decision_v2(p_avail_id, p_guest_flight);
  select * into v_av from availabilities where id = p_avail_id;
  if not found then return d; end if;

  v_venue_id := public.resolve_venue_for_availability(p_avail_id);
  v_prog_id  := nullif(d ->> 'program_id','')::uuid;
  v_sev      := coalesce(d ->> 'severity','info');
  v_policy   := d ->> 'guest_policy';
  v_count    := coalesce((d ->> 'guest_included_count')::smallint, 0);
  v_stay     := nullif(d ->> 'max_stay_hours','')::numeric;
  v_entry    := nullif(d ->> 'earliest_entry_hours','')::numeric;

  select he.* into v_ent from host_entitlements he
   where he.user_id = v_av.host_id
     and (v_prog_id is null or he.program_id = v_prog_id)
   order by he.verified desc, he.self_reported_at desc nulls last limit 1;

  -- ---------- KART TİPİ ----------
  if v_prog_id is not null then
    v_needs_tier := public.program_needs_tier(v_prog_id);
  end if;

  if v_needs_tier and coalesce(v_ent.tier,'') = '' then
    -- 🔴 EN ÖNEMLİ DAVRANIŞ: tier bilinmiyorsa EN İYİ İHTİMALİ VARSAYMA.
    -- Eskiden motor ilk kurali seciyordu (cogu zaman Elite Plus) ve
    -- Classic Plus'li host'a "misafir hakkin var" diyordu.
    v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
    v_extra := v_extra || ('Kart tipini bilmiyoruz. Bu programda misafir hakkı KART TİPİNE göre değişiyor '
                       || '(ör. Classic Plus''ta misafir hakkı YOK). Profil → Lounge Erişim''den kart tipini seç.')::text;
  elsif v_needs_tier then
    select r.* into v_rule
      from lounge_guest_rules r
     where r.program_id = v_prog_id
       and r.card_tier = v_ent.tier
       and (r.venue_id is null or r.venue_id = v_venue_id)
       and (r.effective_from is null or r.effective_from <= current_date)
       and (r.effective_to   is null or r.effective_to   >= current_date)
     order by (r.venue_id is not null) desc, r.created_at
     limit 1;

    if v_rule.id is not null then
      -- Kural, salon kabulunun UZERINE yazar: salon "1 misafir" dese de
      -- Classic Plus'in hakki yoksa hak YOKTUR.
      if v_rule.blocked_reason is not null then
        v_sev := 'block'; v_policy := 'not_allowed'; v_count := 0;
        v_extra := v_extra || v_rule.blocked_reason;
      elsif v_rule.guest_allowance = 0 and v_policy = 'included' then
        v_policy := case when v_rule.paid_entry_allowed then 'paid' else 'not_allowed' end;
        v_count  := 0;
        v_sev    := case when v_policy = 'not_allowed' then 'block' else 'warn' end;
        v_extra  := v_extra || format('Kart tipin (%s): bu kartla misafir hakkı yok.',
                                      coalesce(v_ent.tier,'?'));
        -- 🔴 104: BASLIK DA DEGISMELI. Eskiden yalniz severity ve policy
        -- degisiyordu; baslik salon kabulunden gelen "Misafir hakkın var
        -- (1 kişi)" olarak KALIYORDU. Kullanici "engellendi" rozetiyle
        -- "hakkın var" cumlesini yan yana goruyordu. Celiskili bir ekran,
        -- yanlis ekrandan daha kotudur: hangisine inanacagini bilemez.
        -- 🔴 105: IKI DURUM AYRI CUMLE ISTER.
        -- 'paid': misafir GIREBILIR ama ucret oder. 'not_allowed': giremez.
        -- 104'te ikisini de "goturemezsin" diye yazmistim; kullanici
        -- "ucretli" rozetiyle "goturemezsin" cumlesini yan yana goruyordu.
        -- 🔴 134: HAM KOD DEGIL INSAN DILI. `v_ent.tier` bizim veritabani
        -- kodumuz (CLPL, ELPL...); kullanicinin kartinin uzerinde
        -- "Classic Plus" yaziyor. 120'de precheck'i duzeltmistim ama
        -- BURAYI atlamistim — ve kesif ROZETLERI bu basligi gosteriyor.
        -- Ic kodun bir ekrandan silinmesi yetmez; SIZDIGI HER YERDEN
        -- silinmeli. "Baska nerede uretiliyor" diye sormayi atlamisim.
        v_head := case when v_policy = 'paid'
          then format('%s kartında misafir hakkı yok — misafirin ücret ödeyerek girebilir',
                      coalesce(public.card_tier_label(v_ent.tier), 'Bu kart'))
          else format('%s kartıyla misafir götüremezsin',
                      coalesce(public.card_tier_label(v_ent.tier), 'Bu kart')) end;
      else
        v_count := least(v_count, greatest(v_rule.guest_allowance, 0));
        if v_rule.family_allowed then
          v_extra := v_extra || ('Aile hakkın da var (eş + 25 yaşından gün almamış çocuklar) — '
                             || 'ama aile hakkı, tanışmak için gelen bir misafirin yerine geçmez.')::text;
        end if;
      end if;
      v_entry := coalesce(v_rule.earliest_entry_hours, v_entry);
      if v_rule.notes is not null then v_extra := v_extra || v_rule.notes; end if;
    end if;
  end if;

  -- ---------- KİM ÖDÜYOR ----------
  if v_policy = 'paid' then
    select coalesce(a.fee_payer, p.fee_payer, 'unknown') into v_payer
      from lounge_programs p
      left join lounge_venue_acceptance a
        on a.program_id = p.id and a.venue_id = v_venue_id
     where p.id = v_prog_id;
    v_extra := v_extra || coalesce(
      public.rule_notice(case v_payer
        when 'member_card'   then 'fee_note_member_card'
        when 'guest_at_door' then 'fee_note_guest_at_door'
        else 'rule_notice_generic' end), '');

    -- 🔴 105: BASLIK DA "KIM ODUYOR"A UYMALI.
    -- 086'nin basligi her ucretli durumda "kapida tahsil edilir" diyordu.
    -- Priority Pass / LoungeKey / DragonPass'te ucret KAPIDA MISAFIRDEN
    -- DEGIL, HOST'UN KARTINDAN cekiliyor. Misafire "kapida odeyeceksin"
    -- demek, ona ait olmayan bir maliyeti ustlendirmek olur; host'a da
    -- kendi odeyecegini gizler. Iki taraf da yanlis bilgilenirdi.
    if v_head is null then
      v_head := case v_payer
        when 'member_card'   then 'Misafir girişi ücretli — ücret host''un kartından çekilir'
        when 'guest_at_door' then coalesce(d ->> 'headline', 'Misafir girişi kapıda ücretli')
        else 'Misafir girişi ücretli olabilir — koşulları teyit edin' end;
    end if;
  end if;

  -- ---------- SAAT KONTROLLERİ ----------
  v_dur := extract(epoch from (v_av.time_to - v_av.time_from)) / 3600.0;
  if v_stay is not null and v_dur > v_stay + 0.25 then
    v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
    v_extra := v_extra || format(
      'İlanın %s saatlik ama bu salonda kalış ~%s saatle sınırlı. Süreyi kısaltmayı düşün.',
      trim(to_char(v_dur,'FM990.0')), trim(to_char(v_stay,'FM990.0')));
  end if;

  if v_entry is not null and coalesce(v_av.flight_number,'') <> '' then
    select fc.scheduled_departure into v_dep
      from flight_cache fc
     where upper(replace(fc.flight_no,' ','')) = upper(replace(v_av.flight_number,' ',''))
       and fc.flight_date = v_av.avail_date;
    if v_dep is not null then
      if public.yerel_an(v_av.avail_date, v_av.time_from, v_av.airport_code)
           < (v_dep - make_interval(mins => (v_entry*60)::int)) then
        v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
        v_extra := v_extra || format(
          'Salona en erken kalkıştan %s saat önce girilebiliyor; ilanın bundan erken başlıyor.',
          trim(to_char(v_entry,'FM990.0')));
      end if;
    else
      v_extra := v_extra || format(
        'Salona en erken kalkıştan %s saat önce girilebiliyor — uçuş saatini doğrulayamadığımız için kontrol edilemedi.',
        trim(to_char(v_entry,'FM990.0')));
    end if;
  end if;

  -- ---------- SLOT × MİSAFİR HAKKI ----------
  if v_policy = 'included' and v_count > 0 and coalesce(v_av.slots,1) > v_count then
    v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
    v_extra := v_extra || format(
      'İlanında %s kişilik yer var ama bu hakla en fazla %s misafir sokabilirsin.',
      v_av.slots, v_count);
  end if;

  return d || jsonb_build_object(
    'severity', v_sev,
    'headline', coalesce(v_head, d ->> 'headline'),
    'guest_policy', v_policy,
    'guest_included_count', v_count,
    'host_tier', v_ent.tier,
    'tier_required', v_needs_tier,
    'fee_payer', v_payer,
    'listing_hours', round(v_dur, 1),
    'detail', trim(both ' ' from coalesce(d ->> 'detail','') || ' ' || array_to_string(v_extra, ' ')));
end $$;

-- ----------------------------------------------------------------------
-- charter_note   [etkin kaynak: 119_precheck_v5_and_charter.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.charter_note(p_avail_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare a availabilities%rowtype; v_model text; v_guest_charter boolean;
begin
  select * into a from availabilities where id = p_avail_id;
  if not found then return jsonb_build_object('blocked', false, 'note', null); end if;

  select p.entitlement_model into v_model
    from lounge_venue_acceptance lva
    join lounge_programs p on p.id = lva.program_id
    join lounge_venues v on v.id = lva.venue_id
    left join lounges l on l.venue_id = v.id
   where l.id = a.lounge_id and lva.active
   order by coalesce(p.entitlement_model = 'airline_status', false) desc limit 1;

  select v.is_charter into v_guest_charter
    from visits v where v.user_id = auth.uid()
      and v.airport_code = a.airport_code and v.visit_date = a.avail_date
    order by v.created_at desc limit 1;

  -- 🔴 KART AGI / ISLETMECI SALONU: charter ONEMSIZ.
  -- Uyelik KISIYE baglidir, ucusa degil. Havayolunun charter yasagini
  -- buraya uygulamak, yanlis kaynaktan kural cikarmak olurdu.
  if v_model is not null and v_model <> 'airline_status' then
    if coalesce(a.is_charter,false) or coalesce(v_guest_charter,false) then
      return jsonb_build_object('blocked', false,
        'note', 'Seferlerden biri charter. Bu salona giris HAVAYOLU statusune degil '
             || 'UYELIGE bagli oldugu icin charter olmasi sorun degildir — gecerli '
             || 'binis karti yeterlidir.');
    end if;
    return jsonb_build_object('blocked', false, 'note', null);
  end if;

  -- Havayolu salonu: charter HAK VERMEZ (iki taraf icin de)
  if coalesce(a.is_charter,false) then
    return jsonb_build_object('blocked', true,
      'note', 'Host''un seferi CHARTER. Havayolu salonlarinda charter seferde bilet '
           || 'sinifi ya da statu karti ne olursa olsun salon kullanim hakki yoktur. '
           || 'Istisna: charter anlasmasi yapan acente yolcularina salon hakki satin '
           || 'almissa gecerlidir.');
  end if;
  if coalesce(v_guest_charter,false) then
    return jsonb_build_object('blocked', true,
      'note', 'SENIN seferin charter. Havayolu salonlarinda charter yolcusu misafir '
           || 'olarak da kabul edilmez. Kart agi (Priority Pass / LoungeKey / '
           || 'DragonPass) kaynakli bir ilan ararsan giris mumkun olabilir.');
  end if;
  if a.is_charter is null then
    return jsonb_build_object('blocked', false,
      'note', 'Seferin tarifeli mi charter mi belirtilmemis. Charter seferde havayolu '
           || 'salonu hakki olmaz — emin degilsen biletini kontrol et.');
  end if;
  return jsonb_build_object('blocked', false, 'note', null);
end $$;

-- ----------------------------------------------------------------------
-- rules_expiring   [etkin kaynak: 101_sections_charter_expiry.sql]
-- ----------------------------------------------------------------------
create or replace function public.rules_expiring(p_days int default 45)
returns table (program text, card_tier text, effective_to date, kalan_gun int)
language sql stable security definer set search_path = public as $$
  select p.name, r.card_tier, r.effective_to,
         (r.effective_to - current_date)::int
    from lounge_guest_rules r join lounge_programs p on p.id = r.program_id
   where r.effective_to is not null
     and r.effective_to <= current_date + p_days
   order by r.effective_to, p.name;
$$;

-- ----------------------------------------------------------------------
-- lounge_access_decision_v4   [etkin kaynak: 224_borclar_ve_ilan_neden_yok.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_access_decision_v4('
    'p_avail_id uuid, p_guest_flight text default null) returns jsonb '
    'language plpgsql stable security definer set search_path = public as %L',
    v_yeni);
  raise notice '224: charter kurali tek yere indi (taban)';
end
$charter$;

-- ── NÖBETÇİ · v4 ile TABAN charter''da aynı şeyi söylüyor mu ─────────
do $$
declare v_ayrisan int := 0; v_ornek text := ''; v_bakilan int := 0; r record; d0 jsonb; d4 jsonb;
begin
  for r in select id from availabilities where active loop
    v_bakilan := v_bakilan + 1;
    d0 := public.lounge_access_decision(r.id, null);
    d4 := public.lounge_access_decision_v4(r.id, null);
    if coalesce(d0 ->> 'guest_policy','') = 'not_allowed'
       and coalesce((d0 ->> 'charter')::boolean, false)
       and coalesce(d4 ->> 'guest_policy','') <> 'not_allowed' then
      v_ayrisan := v_ayrisan + 1;
      if v_ornek = '' then v_ornek := left(r.id::text,8); end if;
    end if;
  end loop;
  if v_bakilan = 0 then
    raise notice '224: aktif ilan yok — charter hizasi OLCULEMEDI';
  elsif v_ayrisan > 0 then
    raise exception '224: charter''da taban ile v4 AYRISIYOR → % ilan, ornek %', v_ayrisan, v_ornek;
  else
    raise notice '224: % ilanda charter cevabi taban ile v4''te ayni', v_bakilan;
  end if;
end $$;

-- ----------------------------------------------------------------------
-- set_availability_charter   [etkin kaynak: 101_sections_charter_expiry.sql]
-- ----------------------------------------------------------------------
create or replace function public.set_availability_charter(
  p_avail_id uuid, p_is_charter boolean
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_host uuid;
begin
  select host_id into v_host from availabilities where id = p_avail_id;
  if not found then raise exception 'not_found'; end if;
  if v_host <> auth.uid() then raise exception 'not_owner'; end if;
  update availabilities set is_charter = p_is_charter where id = p_avail_id;
  return jsonb_build_object('ok', true, 'is_charter', p_is_charter);
end $$;

-- ----------------------------------------------------------------------
-- badge_text   [etkin kaynak: 102_badge_wording.sql]
-- ----------------------------------------------------------------------
create or replace function public.badge_text(p_key text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select value -> p_key from beta_settings where key = 'badge_labels'),
                  jsonb_build_object('label', p_key, 'info', null));
$$;

-- ----------------------------------------------------------------------
-- venue_norm   [etkin kaynak: 113_dedupe_and_wording.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.venue_norm(p_name text)
returns text language sql immutable as $$
  -- 🔴 KOK HATA DUZELTILDI (v133 dogrulamasinda bulundu).
  -- Onceki hal 'dis hat' ve 'ic hat' ifadelerini de SILIYORDU. Sonuc:
  -- "Turkish Airlines Lounge — Dış Hat" ile "— İç Hat" AYNI salon
  -- sayiliyor, birlestirmede biri kapaniyordu. IST'te dis hat salonu
  -- katalogdan tamamen kayboldu ve bunu ancak seed dogrulamasi gosterdi.
  --
  -- Terminal, salonu AYIRT EDEN bir ozelliktir — iki ayri fiziksel
  -- salondan bahsediyoruz. Normalizasyon BOLUM eklerini (Business /
  -- Miles&Smiles) silmeli, TERMINALI degil.
  --
  -- Ders: normalizasyon "farkı yok say" degil, "ayni seyi ayni yaz"
  -- demektir. Fazla silen bir normalizasyon, ayri seyleri birlestirir.
  select regexp_replace(
    replace(replace(replace(replace(replace(
      lower(translate(coalesce(p_name,''), 'ıİşŞğĞüÜöÖçÇÂâÎî', 'iisSgGuUoOcCAaIi')),
      '(business)',''), '(miles&smiles)',''), 'miles&smiles',''), 'business',''),
      -- ASCII/Turkce farki translate ile zaten kapandi (dış->dis, iç->ic);
      -- geriye yalniz bolum ekleri kaliyor. Terminal KORUNUYOR.
      'lounge lounge','lounge'),
    '[^a-z0-9]+', '', 'g');
$$;

-- ----------------------------------------------------------------------
-- paid_guest_credit   [etkin kaynak: 219_kredi_ve_ucret_dili.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.paid_guest_credit(p_avail_id uuid)
returns int language plpgsql stable security definer set search_path = public as $$
declare v_n int; v_paid boolean;
begin
  select coalesce((public.lounge_access_decision(p_avail_id, null) ->> 'guest_policy') = 'paid', false)
    into v_paid;
  if not coalesce(v_paid, false) then return 0; end if;

  -- 🔴 219: üç yedeğin ÜÇÜ de 1. Ayar okunamazsa da doğru sayı çıkar.
  select coalesce((value)::text::int, 1) into v_n
    from beta_settings where key = 'paid_guest_credits';
  return coalesce(v_n, 1);
exception when others then
  return 1;
end $$;

-- ----------------------------------------------------------------------
-- trg_settle_paid_guest   [etkin kaynak: 108_paid_guest_settlement.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_settle_paid_guest()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_n int; v_bal int;
begin
  -- 🔴 `coalesce(old.status,'')` YANLIS: status bir ENUM ve '' o enum'da
  -- YOK. PostgreSQL bos dizeyi request_status'a cevirmeye calisip
  -- "invalid input value for enum" veriyordu — yani KABUL ETME AKISI
  -- TAMAMEN KIRILIYORDU. Iki hesapli E2E testi bunu ilk kosuda yakaladi;
  -- statik denetimlerin hicbiri goremezdi.
  -- Enumlarda null kontrolu icin `is distinct from` kullanilir.
  if new.status <> 'accepted' or old.status is not distinct from 'accepted' then
    return new;
  end if;
  v_n := public.paid_guest_credit(new.avail_id);
  if v_n <= 0 then return new; end if;

  -- Ayni istek icin IKI KEZ aktarma. Kabul geri alinip tekrar
  -- verilirse kullanici iki kez odemesin.
  if exists (select 1 from credit_ledger
              where reason = 'paid_guest_thanks:' || new.id::text) then
    return new;
  end if;

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = new.guest_id;
  -- Kredisi yetmiyorsa AKISI DURDURMA. Bulusma zaten kabul edildi;
  -- burada hata firlatmak, kural disi bir sebeple kabulu iptal ederdi.
  if v_bal < v_n then
    insert into notifications (user_id, category, title, body)
    values (new.guest_id, 'credits', 'Kredi yetersiz',
            'Ucretli misafir ilanina kabul edildin ama tesekkur kredin yetmedi. '
         || 'Host''a bunu sohbette belirtmen iyi olur.');
    return new;
  end if;

  insert into credit_ledger (user_id, delta, reason, balance_after)
  values (new.guest_id, -v_n, 'paid_guest_thanks:' || new.id::text, v_bal - v_n);

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = new.host_id;
  insert into credit_ledger (user_id, delta, reason, balance_after)
  values (new.host_id, v_n, 'paid_guest_thanks:' || new.id::text, v_bal + v_n);

  insert into notifications (user_id, category, title, body) values
    (new.host_id, 'credits', 'Tesekkur kredisi',
     'Ucretli misafir ilanin icin ' || v_n || ' kredi aktarildi.'),
    (new.guest_id, 'credits', 'Tesekkur kredisi gonderildi',
     'Host senin icin giris ucreti odeyecek; ' || v_n || ' kredi ona aktarildi.');
  return new;
end $$;

-- ----------------------------------------------------------------------
-- disable_push_token   [etkin kaynak: 111_push_direct_expo.sql]
-- ----------------------------------------------------------------------
create or replace function public.disable_push_token(p_token text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  update push_tokens set active = false, updated_at = now()
   where token = p_token and user_id = auth.uid();
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- is_blocked_pair   [etkin kaynak: 112_blocks_in_discovery.sql]
-- ----------------------------------------------------------------------
create or replace function public.is_blocked_pair(p_a uuid, p_b uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from blocks b
     where (b.blocker = p_a and b.blocked = p_b)
        or (b.blocker = p_b and b.blocked = p_a));
$$;

-- ----------------------------------------------------------------------
-- card_confidence_note   [etkin kaynak: 114_card_confidence_visible.sql]
-- ----------------------------------------------------------------------
create or replace function public.card_confidence_note(p_user_id uuid)
returns text language sql stable security definer set search_path = public as $$
  select case
    when cp.id is null then null
    when cp.confidence = 'verified' and cp.checked_at is not null then null
    else 'Host''un kart bilgisi bizde DOĞRULANMAMIŞ olarak kayıtlı ('
      || coalesce(i.name,'') || ' ' || coalesce(cp.name,'') || '). Aşağıdaki '
      || 'misafir hakkı bilgisi kesin değildir; girişten önce host ile teyit edin.'
  end
  from host_entitlements he
  left join lounge_card_products cp on cp.id = he.card_product_id
  left join lounge_issuers i on i.id = cp.issuer_id
 where he.user_id = p_user_id
 order by he.self_reported_at desc nulls last
 limit 1;
$$;

-- ----------------------------------------------------------------------
-- my_quota_line   [etkin kaynak: 115_quota_who_says.sql]
-- ----------------------------------------------------------------------
create or replace function public.my_quota_line()
returns text language plpgsql stable security definer set search_path = public as $$
declare q jsonb; v text;
begin
  select public.entitlement_remaining(he.id) into q
    from host_entitlements he
   where he.user_id = auth.uid()
   order by he.self_reported_at desc nulls last limit 1;
  if q is null or (q ->> 'known') is distinct from 'true' then return null; end if;
  if (q ->> 'unlimited')::boolean then return null; end if;
  v := public.rule_notice('quota_note_host');
  return replace(replace(v, '{left}', coalesce(q ->> 'left','?')),
                 '{total}', coalesce(q ->> 'total','?'));
end $$;

-- ----------------------------------------------------------------------
-- guest_quota_note   [etkin kaynak: 115_quota_who_says.sql]
-- ----------------------------------------------------------------------
create or replace function public.guest_quota_note(p_host_id uuid)
returns text language plpgsql stable security definer set search_path = public as $$
declare q jsonb;
begin
  select public.entitlement_remaining(he.id) into q
    from host_entitlements he
   where he.user_id = p_host_id
   order by he.self_reported_at desc nulls last limit 1;
  if q is null or (q ->> 'known') is distinct from 'true' then return null; end if;
  if (q ->> 'unlimited')::boolean then return null; end if;
  -- 🔴 SAYIYI DEGIL, DURUMU dondururuz. Tek istisna: hak TUKENMISSE
  -- bu bir UYARIDIR, vaat degil — misafirin bilmesi onu korur.
  if coalesce((q ->> 'left')::int, 1) <= 0 then
    return public.rule_notice('quota_note_guest_exhausted');
  end if;
  return public.rule_notice('quota_note_guest_shape');
end $$;

-- ----------------------------------------------------------------------
-- carrier_from_flight   [etkin kaynak: 117_carrier_field.sql]
-- ----------------------------------------------------------------------
create or replace function public.carrier_from_flight(p_flight text)
returns text language sql stable as $$
  -- 🔴 Bu fonksiyon artik TEK KAYNAK DEGIL, yalniz bir ONERI.
  -- Kullanici tasiyiciyi secmediyse tahminde bulunuruz ama kararin
  -- dayanagi olmaz. "AJ" gibi yaygin ama YANLIS yazimlar da eslenir:
  -- AJet'in gercek IATA kodu VF, ama kullanicilar AJ yaziyor.
  select case
    when coalesce(p_flight,'') = '' then null
    when upper(p_flight) like 'AJ%' then 'VF'
    else (select c.code from carriers c
           where c.active and c.code <> 'OTHER'
             and upper(replace(p_flight,' ','')) like c.code || '%'
           order by length(c.code) desc limit 1)
  end;
$$;

-- ----------------------------------------------------------------------
-- carrier_options   [etkin kaynak: 117_carrier_field.sql]
-- ----------------------------------------------------------------------
create or replace function public.carrier_options()
returns table (code text, name text, alliance text, is_lowcost boolean)
language sql stable security definer set search_path = public as $$
  select c.code, c.name, c.alliance, c.is_lowcost
    from carriers c where c.active
   order by c.sort_order, c.name;
$$;

-- ----------------------------------------------------------------------
-- set_availability_carrier   [etkin kaynak: 198_thy_ajet_ms_yeniden_dogrulama.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.set_availability_carrier(p_avail_id uuid, p_carrier text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_code text := nullif(upper(btrim(coalesce(p_carrier,''))), '');
begin
  if (select host_id from availabilities where id = p_avail_id) <> auth.uid() then
    raise exception 'not_owner';
  end if;
  -- İKİ KOLONA BİRDEN: carrier_code katalog/FK için, carrier motor için.
  update availabilities
     set carrier_code = v_code,
         carrier      = v_code
   where id = p_avail_id;
  return jsonb_build_object('ok', true, 'carrier', v_code);
end $$;

-- ----------------------------------------------------------------------
-- set_visit_carrier   [etkin kaynak: 117_carrier_field.sql]
-- ----------------------------------------------------------------------
create or replace function public.set_visit_carrier(p_visit_id uuid, p_carrier text)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if (select user_id from visits where id = p_visit_id) <> auth.uid() then
    raise exception 'not_owner';
  end if;
  update visits set carrier_code = nullif(p_carrier,'') where id = p_visit_id;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- carrier_match   [etkin kaynak: 118_carrier_in_rules.sql]
-- ----------------------------------------------------------------------
create or replace function public.carrier_match(
  p_host_carrier text, p_guest_carrier text, p_coupling text
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare a1 text; a2 text;
begin
  if coalesce(p_coupling,'any') = 'any' then
    return jsonb_build_object('ok', true, 'known', true, 'note', null);
  end if;
  if coalesce(p_host_carrier,'') = '' or coalesce(p_guest_carrier,'') = '' then
    -- Bilinmiyor: AKIS DURMAZ, uyari cikar.
    return jsonb_build_object('ok', true, 'known', false,
      'note', 'Havayolu bilgisi eksik. Bu salonun kurali misafirin belirli bir '
           || 'havayolunda olmasini istiyor; giristen once birbirinizin ucusunu teyit edin.');
  end if;
  if p_host_carrier = p_guest_carrier then
    return jsonb_build_object('ok', true, 'known', true, 'note', null);
  end if;

  if p_coupling = 'same_alliance' then
    select alliance into a1 from carriers where code = p_host_carrier;
    select alliance into a2 from carriers where code = p_guest_carrier;
    if a1 is not null and a1 = a2 then
      return jsonb_build_object('ok', true, 'known', true,
        'note', 'Farkli havayollari ama AYNI ITTIFAK (' || a1 || ') — bu salon icin yeterli.');
    end if;
    return jsonb_build_object('ok', false, 'known', true,
      'note', 'Bu salon ittifak uyesi bir havayolunda ucmani istiyor; '
           || 'senin havayolun host''unkiyle ayni ittifakta degil.');
  end if;

  -- 🔴 TK <-> AJet: AYNI SIRKET, FARKLI TASIYICI. Kullanicilarin en cok
  -- yanildigi yer burasi ve iki resmi metin de acikca yasakliyor.
  if (p_host_carrier = 'TK' and p_guest_carrier = 'VF')
     or (p_host_carrier = 'VF' and p_guest_carrier = 'TK') then
    return jsonb_build_object('ok', false, 'known', true,
      'note', 'Turk Hava Yollari ve AJet AYRI TASIYICI sayilir: THY yolcusu AJet '
           || 'yolcusunu misafir edemez, AJet yolcusu da THY yolcusunu. Ikisi ayni '
           || 'gruba ait olsa da salon kurali boyle (THY md.17 ve AJet CIP kurallari).');
  end if;

  return jsonb_build_object('ok', false, 'known', true,
    'note', 'Bu salon misafirin host ile AYNI HAVAYOLUNDA ucmasini istiyor; '
         || 'sizin havayollariniz farkli.');
end $$;

-- ----------------------------------------------------------------------
-- lounge_access_decision_v5   [etkin kaynak: 129_conflict_surfaced.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounge_access_decision_v5(
  p_avail_id uuid, p_guest_flight text default null, p_guest_carrier text default null
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  d jsonb; v_av availabilities%rowtype; m jsonb; v_conf text;
  v_host text; v_guest text; v_coupling text; v_sev text; v_extra text[] := '{}';
begin
  d := public.lounge_access_decision_v4(p_avail_id, p_guest_flight);
  select * into v_av from availabilities where id = p_avail_id;
  if not found then return d; end if;

  -- 🔴 KAYNAK CELISKISI: varsa kullaniciya SOYLE ve severity'yi warn'a cek.
  -- Celiskiyi bilip susmak, kullanici adina karar vermektir.
  select a.source_conflict into v_conf
    from lounge_venue_acceptance a
    join lounges l on l.venue_id = a.venue_id
   where l.id = v_av.lounge_id and a.active
     and a.program_id = nullif(d ->> 'program_id','')::uuid
     and coalesce(a.source_conflict,'') <> ''
   limit 1;

  v_coupling := d ->> 'flight_coupling';
  v_host  := coalesce(v_av.carrier_code, public.carrier_from_flight(v_av.flight_number));
  v_guest := coalesce(nullif(p_guest_carrier,''), public.carrier_from_flight(p_guest_flight));
  v_sev := coalesce(d ->> 'severity','info');

  if coalesce(v_coupling,'any') in ('same_carrier','same_alliance') then
    m := public.carrier_match(v_host, v_guest, v_coupling);
    if not (m ->> 'ok')::boolean then
      v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
    elsif not (m ->> 'known')::boolean then
      v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
    end if;
    if (m ->> 'note') is not null then v_extra := v_extra || (m ->> 'note')::text; end if;
  end if;

  if v_conf is not null then
    v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
    v_extra := v_extra || v_conf::text;
  end if;

  return d || jsonb_build_object(
    'severity', v_sev,
    'carrier_ok', case when m is null then null else (m ->> 'ok')::boolean end,
    'carrier_known', case when m is null then null else (m ->> 'known')::boolean end,
    'source_conflict', v_conf,
    'host_carrier', v_host, 'guest_carrier', v_guest,
    'detail', trim(both ' ' from coalesce(d ->> 'detail','') || ' ' || array_to_string(v_extra,' ')));
end $$;

-- ----------------------------------------------------------------------
-- guest_carrier_for   [etkin kaynak: 118_carrier_in_rules.sql]
-- ----------------------------------------------------------------------
create or replace function public.guest_carrier_for(p_avail_id uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce(v.carrier_code, public.carrier_from_flight(v.flight_number))
    from visits v, availabilities a
   where a.id = p_avail_id and v.user_id = auth.uid()
     and v.airport_code = a.airport_code and v.visit_date = a.avail_date
   order by v.created_at desc limit 1;
$$;

-- ----------------------------------------------------------------------
-- set_visit_charter   [etkin kaynak: 119_precheck_v5_and_charter.sql]
-- ----------------------------------------------------------------------
create or replace function public.set_visit_charter(p_visit_id uuid, p_is_charter boolean)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if (select user_id from visits where id = p_visit_id) <> auth.uid() then
    raise exception 'not_owner';
  end if;
  update visits set is_charter = p_is_charter where id = p_visit_id;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- card_tier_label   [etkin kaynak: 184_ms_status_language.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.card_tier_label(p_tier text)
returns text language sql immutable as $$
  select case p_tier
    when 'ELPL'     then 'Elite Plus'
    when 'ELITE'    then 'Elite'
    when 'CLPL'     then 'Classic Plus'
    when 'CLASSIC'  then 'Classic'
    when 'CORP'     then 'Corporate Club'
    when 'MS_EC'    then 'Elite Corporate'
    when 'SAG'      then 'Star Alliance Gold'
    when 'PLM'      then 'Program Üyesi'
    -- 🔴 184: "ABD Kredi Kartı" yanlış addı; doğrusu Amex.
    when 'MS_US_CC' then 'Miles&Smiles Amex'
    when 'PP_STANDARD'      then 'Priority Pass Standard'
    when 'PP_STANDARD_PLUS' then 'Priority Pass Standard Plus'
    when 'PP_PRESTIGE'      then 'Priority Pass Prestige'
    when 'DP_CLASSIC'       then 'DragonPass Classic'
    when 'DP_PREFERENTIAL'  then 'DragonPass Preferential'
    else p_tier
  end;
$$;

-- ----------------------------------------------------------------------
-- short_detail   [etkin kaynak: 120_human_text.sql]
-- ----------------------------------------------------------------------
create or replace function public.short_detail(p_parts text[], p_max int default 2)
returns text language sql immutable as $$
  -- Parcalari sirayla alir, ILK p_max cumleyi dondurur. Onem sirasi
  -- cagiran taraftadir: en kritik not basa yazilir.
  select nullif(trim(both ' ' from array_to_string(
           (select array_agg(x) from (
              select unnest(p_parts) as x limit p_max
            ) t where x is not null and trim(x) <> ''), ' ')), '');
$$;

-- ----------------------------------------------------------------------
-- access_source_summary   [etkin kaynak: 162_source_truth_and_founder_badge.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.access_source_summary(p_source text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_pid uuid; v_tier text; v_cost jsonb; v_prog lounge_programs%rowtype;
        v_rules int; v_fresh boolean;
begin
  -- Eşleştirme genişletildi: cihazda "Kredi Kartı Avantajı" ve
  -- "Banka / Özel Bankacılık" seçenekleri hiçbir programa bağlanmıyordu
  -- (yalnız '%kart%' vardı ve 'Havayolu Statüsü' TK_MS'e gidiyordu).
  select p.id into v_pid from lounge_programs p
   where p.active and (
     (p_source ilike '%priority%'   and p.code = 'PRIORITY_PASS') or
     (p_source ilike '%dragon%'     and p.code = 'DRAGONPASS')    or
     (p_source ilike '%loungekey%'  and p.code = 'LOUNGEKEY')     or
     (p_source ilike '%miles%'      and p.code = 'TK_MS')         or
     (p_source ilike '%ajet%'       and p.code = 'AJET_MS')       or
     (p_source ilike '%star%'       and p.code = 'STAR_GOLD')     or
     (p_source ilike '%pegasus%'    and p.code = 'PGS_PAID')      or
     (p_source ilike '%business%'   and p.code = 'BUSINESS_TICKET') or
     (p_source ilike '%havayolu%'   and p.code = 'TK_MS')         or
     ((p_source ilike '%kredi kart%' or p_source ilike '%banka%')
                                    and p.code = 'BANK_CARD'))
   limit 1;
  if v_pid is null then return jsonb_build_object('known', false); end if;

  select * into v_prog from lounge_programs where id = v_pid;
  select he.tier into v_tier from host_entitlements he
   where he.user_id = auth.uid() and he.program_id = v_pid limit 1;
  v_cost := public.entry_cost_note(v_pid, v_tier);

  -- Doğrulanmış sayılmanın İKİ şartı var ve ikisi de veriye dayanır:
  -- (a) programın kuralları resmî kaynaktan okunmuş (checked_at + url)
  -- (b) o programa ait EN AZ BİR kural satırı gerçekten modellenmiş
  select count(*) into v_rules from lounge_guest_rules r where r.program_id = v_pid;
  v_fresh := v_prog.checked_at is not null
             and v_prog.checked_at >= current_date - 180
             and coalesce(v_prog.source_url,'') <> ''
             and v_rules > 0;

  return jsonb_build_object(
    'known', true,
    'program', v_prog.name,
    'verified', v_fresh,
    'checked_at', v_prog.checked_at,
    'source_url', nullif(v_prog.source_url,''),
    'rule_count', v_rules,
    'summary', coalesce(v_cost ->> 'detail',
                        'Bu hakkın koşulları kartını veren kuruma göre değişir.'),
    'cost_warning', case when (v_cost ->> 'has_cost')::boolean
                         then v_cost ->> 'headline' end,
    'member_fee', v_cost ->> 'member_fee',
    'guest_fee', v_cost ->> 'guest_fee',
    'free_visits', v_cost -> 'free_visits');
end $$;

-- ----------------------------------------------------------------------
-- alternatives_for   [etkin kaynak: 122_what_can_i_do.sql]
-- ----------------------------------------------------------------------
create or replace function public.alternatives_for(p_avail_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid(); a availabilities%rowtype;
  v_n int := 0; v_reason text; d jsonb; v_ids uuid[];
begin
  select * into a from availabilities where id = p_avail_id;
  if not found then return jsonb_build_object('count', 0); end if;

  d := public.lounge_access_decision_v5(p_avail_id, null, null);

  -- Ayni havalimani + ayni tarih + acik slot + KENDISI DEGIL
  select array_agg(x.id) into v_ids from (
    select av.id from availabilities av
     where av.airport_code = a.airport_code
       and av.avail_date = a.avail_date
       and av.id <> p_avail_id
       and av.host_id <> v_uid
       and coalesce(av.filled,0) < coalesce(av.slots,1)
       and not public.is_blocked_pair(av.host_id, v_uid)
     limit 40
  ) x;

  if v_ids is null then return jsonb_build_object('count', 0); end if;

  -- 🔴 GERCEKTEN basvurabilecegi olanlari say. Rozet fonksiyonu
  -- precheck ile ayni mantigi kullaniyor; burada da onu cagirarak
  -- UC YERDE AYNI cevabi garanti ediyoruz.
  select count(*) into v_n
    from public.discovery_rule_badges(v_ids) b
   where not b.blocks_request;

  v_reason := case
    when (d ->> 'carrier_ok') = 'false'
      then 'Bu salon misafirin aynı havayolunda uçmasını istiyor.'
    when coalesce((d ->> 'charter'),'false') = 'true'
      then 'Havayolu salonları charter seferde hak vermiyor — ama kart ağı '
        || '(Priority Pass / LoungeKey / DragonPass) kaynaklı ilanlar charter''ı umursamaz.'
    when (d ->> 'guest_policy') = 'not_allowed'
      then 'Bu ilandaki hak misafir götürmeye izin vermiyor.'
    else null end;

  return jsonb_build_object(
    'count', v_n,
    'reason', v_reason,
    'airport', a.airport_code,
    'date', a.avail_date);
end $$;

-- ----------------------------------------------------------------------
-- venue_partners   [etkin kaynak: 126_partners_visible.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_partners(p_lounge_id uuid)
returns table (scope text, partner_kind text, partner_name text,
               program_code text, terms_known boolean)
language sql stable security definer set search_path = public as $$
  select vp.scope, vp.partner_kind, vp.partner_name, pr.code, vp.terms_known
    from lounges l
    join lounge_venues v on v.id = l.venue_id
    join lounge_venue_partners vp on vp.venue_id = v.id and vp.active
    left join lounge_programs pr on pr.id = vp.program_id
   where l.id = p_lounge_id
   -- 🔴 SIRA ANLAM TASIR: once BANKALAR (kullanicilarin cogunda banka
   -- karti var), sonra kart aglari, sonra havayolu, en sonda kurumsal.
   -- Alfabetik siralama en olasi secenegi listenin ortasina gomerdi.
   order by case vp.partner_kind when 'bank' then 1 when 'global' then 2
                                 when 'airline' then 3 else 4 end,
            vp.partner_name;
$$;

-- ----------------------------------------------------------------------
-- venue_partner_count   [etkin kaynak: 126_partners_visible.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_partner_count(p_lounge_id uuid)
returns int language sql stable security definer set search_path = public as $$
  select count(distinct vp.partner_name)::int
    from lounges l
    join lounge_venues v on v.id = l.venue_id
    join lounge_venue_partners vp on vp.venue_id = v.id and vp.active
   where l.id = p_lounge_id;
$$;

-- ----------------------------------------------------------------------
-- venue_amenities   [etkin kaynak: 130_amenities.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_amenities(p_lounge_id uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(v.amenities, '{}'::jsonb)
    from lounges l join lounge_venues v on v.id = l.venue_id
   where l.id = p_lounge_id;
$$;

-- ----------------------------------------------------------------------
-- amenities_for   [etkin kaynak: 130_amenities.sql]
-- ----------------------------------------------------------------------
create or replace function public.amenities_for(p_ids uuid[])
returns table (avail_id uuid, amenities jsonb)
language sql stable security definer set search_path = public as $$
  select a.id, coalesce(v.amenities, '{}'::jsonb)
    from availabilities a
    left join lounges l on l.id = a.lounge_id
    left join lounge_venues v on v.id = l.venue_id
   where a.id = any (coalesce(p_ids, '{}'::uuid[]));
$$;

-- ----------------------------------------------------------------------
-- card_advice_for_lounge   [etkin kaynak: 131_card_advisor.sql]
-- ----------------------------------------------------------------------
create or replace function public.card_advice_for_lounge(p_lounge_id uuid)
returns table (
  issuer text, card text, program text, segment text,
  quota text, guest_note text, confidence text, source_url text, rank int
) language sql stable security definer set search_path = public as $$
  with venue as (
    select v.id from lounges l join lounge_venues v on v.id = l.venue_id
     where l.id = p_lounge_id
  ),
  -- Bu salonda GERCEKTEN kabul edilen programlar
  ok_programs as (
    select distinct a.program_id
      from lounge_venue_acceptance a, venue
     where a.venue_id = venue.id and a.active and a.accepted
  )
  select i.name, cp.name, p.name, cp.segment,
         case
           when cp.quota_total is null then 'Adet belirtilmemiş'
           else cp.quota_total::text || ' kullanım / ' ||
                case cp.quota_period when 'year' then 'yıl' when 'month' then 'ay'
                                     when 'visit' then 'ziyaret' else 'dönem' end
         end,
         case
           when cp.guest_consumes_quota
             then '⚠ Misafirin AYNI HAKTAN düşer — eşinle gidersen hakkın yarıya iner.'
           when cp.guest_quota_total is not null
             then cp.guest_quota_total::text || ' misafir hakkı (ayrı havuzdan)'
           else 'Misafir hakkı belirtilmemiş — bankandan teyit et.'
         end,
         coalesce(cp.confidence, 'unknown'),
         cp.source_url,
         -- 🔴 SIRALAMA BIR TAVSIYEDIR. Once DOGRULANMIS, sonra MISAFIR
         -- HAKKI OLAN, sonra kotasi buyuk olan. Kullanici ustteki
         -- secenegi "onerilen" sanir; en zayif veriyi basa koymak
         -- ona zarar verir.
         (case when cp.confidence = 'verified' and cp.checked_at is not null then 0 else 10 end
          + case when cp.guest_quota_total is not null and not cp.guest_consumes_quota then 0
                 when cp.guest_consumes_quota then 3 else 5 end
          + case when coalesce(cp.quota_total, 0) >= 10 then 0 else 1 end)::int
    from lounge_card_products cp
    join lounge_issuers i on i.id = cp.issuer_id and i.active
    join lounge_programs p on p.id = cp.program_id
    join ok_programs op on op.program_id = cp.program_id
   where cp.active
     and (cp.valid_to is null or cp.valid_to >= current_date)
   -- 🔴 `rank` bir SIRALAMA FONKSIYONU adi; PostgreSQL onu ORDER BY'da
   -- kolon takma adi olarak cozmez. Ifadeyi tekrar yaziyoruz.
   order by (case when cp.confidence = 'verified' and cp.checked_at is not null then 0 else 10 end
             + case when cp.guest_quota_total is not null and not cp.guest_consumes_quota then 0
                    when cp.guest_consumes_quota then 3 else 5 end
             + case when coalesce(cp.quota_total, 0) >= 10 then 0 else 1 end),
            i.name
   limit 6;
$$;

-- ----------------------------------------------------------------------
-- card_advice_for_airport   [etkin kaynak: 131_card_advisor.sql]
-- ----------------------------------------------------------------------
create or replace function public.card_advice_for_airport(p_airport text)
returns table (issuer text, card text, program text, lounges int,
               confidence text, source_url text)
language sql stable security definer set search_path = public as $$
  select i.name, cp.name, p.name,
         count(distinct a.venue_id)::int,
         coalesce(cp.confidence,'unknown'), cp.source_url
    from lounge_card_products cp
    join lounge_issuers i on i.id = cp.issuer_id and i.active
    join lounge_programs p on p.id = cp.program_id
    join lounge_venue_acceptance a on a.program_id = cp.program_id and a.active and a.accepted
    join lounge_venues v on v.id = a.venue_id and v.active
   where cp.active and v.airport_code = upper(p_airport)
   group by i.name, cp.name, p.name, cp.confidence, cp.source_url
   -- Kac SALONA girdigi belirleyici: bir kart o havalimaninda tek
   -- salona giriyorsa "burada ise yarar" demek yaniltici olur.
   order by count(distinct a.venue_id) desc,
            coalesce(cp.confidence = 'verified', false) desc, i.name
   limit 5;
$$;

-- ----------------------------------------------------------------------
-- travel_style_options   [etkin kaynak: 132_travel_style.sql]
-- ----------------------------------------------------------------------
create or replace function public.travel_style_options()
returns table (code text, label text, sub text, sort_order int)
language sql stable as $$
  select * from (values
    ('social',   'Sohbete açığım',      'Bir şeyler içip muhabbet edelim', 1),
    ('zen',      'Sessiz eşlik',        'Yanımda biri olsun ama sessiz olsun', 2),
    ('foodie',   'İkramlar için buradayım', 'Büfeyi keşfetmeyi severim', 3),
    ('explorer', 'Havalimanı kaşifi',   'Her köşeyi bilirim, gezmeyi severim', 4)
  ) as t(code, label, sub, sort_order) order by sort_order;
$$;

-- ----------------------------------------------------------------------
-- style_fit   [etkin kaynak: 132_travel_style.sql]
-- ----------------------------------------------------------------------
create or replace function public.style_fit(p_a text, p_b text)
returns int language sql immutable as $$
  select case
    when p_a is null or p_b is null then 0        -- bilinmiyor: NOTR
    when p_a = p_b then 12
    when (p_a = 'social'  and p_b = 'zen')      or (p_a = 'zen'      and p_b = 'social')  then -10
    when (p_a = 'foodie'  and p_b = 'explorer') or (p_a = 'explorer' and p_b = 'foodie')  then 8
    when (p_a = 'social'  and p_b in ('foodie','explorer'))
      or (p_b = 'social'  and p_a in ('foodie','explorer')) then 6
    when (p_a = 'zen'     and p_b in ('foodie','explorer'))
      or (p_b = 'zen'     and p_a in ('foodie','explorer')) then 2
    else 0 end;
$$;

-- ----------------------------------------------------------------------
-- style_note   [etkin kaynak: 132_travel_style.sql]
-- ----------------------------------------------------------------------
create or replace function public.style_note(p_a text, p_b text)
returns text language sql stable security definer set search_path = public as $$
  select case
    when p_a is null or p_b is null then null
    when p_a = p_b and p_a = 'social' then 'İkiniz de sohbete açıksınız.'
    when p_a = p_b and p_a = 'zen'    then 'İkiniz de sessiz eşlik tercih ediyorsunuz.'
    when p_a = p_b then 'Seyahat tarzınız aynı.'
    when public.style_fit(p_a, p_b) < 0
      then '⚠ Tarzlarınız farklı: biriniz sohbet, diğeriniz sessizlik istiyor. '
        || 'Buluşmadan önce beklentinizi konuşmanız iyi olur.'
    when public.style_fit(p_a, p_b) >= 6 then 'Seyahat tarzlarınız uyumlu.'
    else null end;
$$;

-- ----------------------------------------------------------------------
-- verification_state   [etkin kaynak: 138_email_otp.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.verification_state(p_user uuid default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'email_verified', coalesce(v.email_verified, false),
    'phone_declared', coalesce(u.phone,'') <> '',
    'phone_verified', coalesce(v.phone_verified, false)
                      and coalesce(v.phone_verified_method,'bypass') <> 'bypass',
    'id_verified', coalesce(v.id_verified, false),
    'channel', coalesce((select value #>> '{}' from beta_settings where key = 'otp_channel'), 'none'),
    -- Rozette YAZACAK metin: ne dogrulandiysa o.
    'badge', case
      when coalesce(v.email_verified, false) then 'E-posta doğrulandı'
      when coalesce(u.phone,'') <> '' then 'Telefon eklendi (doğrulanmadı)'
      else null end)
    from users u
    left join verifications v on v.user_id = u.id
   where u.id = coalesce(p_user, auth.uid());
$$;

-- ----------------------------------------------------------------------
-- mark_email_verified   [etkin kaynak: 203_guvenlik_siniri.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.mark_email_verified()
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_uid uuid := auth.uid(); v_conf timestamptz;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- KANIT: Supabase e-postayı gerçekten onayladı mı?
  select email_confirmed_at into v_conf from auth.users where id = v_uid;
  if v_conf is null then raise exception 'email_not_confirmed'; end if;

  insert into verifications (user_id, email_verified, email_verified_at)
  values (v_uid, true, now())
  on conflict (user_id) do update
    set email_verified = true, email_verified_at = now();
  perform public.recompute_trust(v_uid);
  return jsonb_build_object('ok', true);
end $fn$;


-- ============================================================
-- 5) send_otp — demo kodu ARTIK BİR KAPININ ARKASINDA
-- ============================================================
-- Fonksiyon üretilen 6 haneli kodu cevapta DÖNDÜRÜYORDU
-- (`'demo_code', v_code`). Beta'da SMS sağlayıcısı yokken bu
-- BİLİNÇLİ bir tercihti; sorun, canlıya çıkarken bunu hatırlamanın
-- İNSAN HAFIZASINA bırakılmış olması. Artık bir ayar:
-- `beta_settings.otp_demo_mode`. SMS bağlandığı gün BO'dan 'no'
-- yapılır, deploy gerekmez — 202'deki AJet anahtarıyla aynı desen.
-- ⚠️ `beta_settings` yalnız (key, value, updated_at, updated_by) taşır.
-- İlk yazışımda `note` kolonu varsaydım ve harness 42703 verdi. Aynı
-- sınıf ondördüncü kez: ŞEMAYI OKUMADAN KOLON ADI UYDURMA. Açıklama
-- artık burada, kodun yanında duruyor:
--   yes → send_otp üretilen kodu cevapta döndürür (SMS sağlayıcısı
--         bağlanana kadar telefon doğrulaması başka türlü test edilemez)
--   no  → döndürmez. SMS sağlayıcısı bağlandığı gün BO'dan 'no' yapılır.
insert into beta_settings (key, value)
values ('otp_demo_mode', to_jsonb('yes'::text))
on conflict (key) do nothing;

-- ============================================================
-- 5b) 🔴 BEKLENMEDİK BULGU — TELEFON DOĞRULAMA CANLIDA HİÇ ÇALIŞMIYOR
-- ============================================================
-- Nöbetçiyi yazarken harness `gen_salt(unknown) does not exist` dedi.
-- İlk refleksim "harness eksik" demekti. ÖLÇTÜM, öyle değilmiş:
--
--   select extname, nspname from pg_extension e
--     join pg_namespace n on n.oid = e.extnamespace;
--   → pgcrypto | extensions
--
-- pgcrypto `extensions` şemasında (Supabase'in varsayılanı, harness de
-- aynısını taklit ediyor). Ama iki fonksiyonun tanımında
-- `SET search_path TO 'public'` yazıyor ve bu, veritabanının
-- `"$user", public, extensions` yolunu EZİYOR. Yani `crypt` ve
-- `gen_salt` çözülemiyor:
--
--   send_otp   → 42883, kod hiç üretilemiyor
--   verify_otp → 42883, kod hiç doğrulanamıyor
--
-- Bunu kimse fark etmemiş çünkü beta'da doğrulama kapısı e-postadan
-- geçiyor (`is_contact_verified` = telefon VEYA e-posta) ve telefon
-- yolu hiç kullanılmamış. SMS sağlayıcısı bağlandığı gün akış ilk
-- çağrıda patlardı.
--
-- DERS (yeni hata sınıfı): `SET search_path` bir güvenlik önlemidir
-- ama aynı zamanda bir KISITLAMADIR — eklenti şemasını dışarıda
-- bırakırsa fonksiyon çalışmaz. Güvenli hâli `public, extensions`.
alter function public.verify_otp(text, text) set search_path = public, extensions;

-- ----------------------------------------------------------------------
-- declare_phone   [etkin kaynak: 268_telefon_tekilligi.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.declare_phone(p_phone text)
returns jsonb
language plpgsql security definer set search_path = public as $dp268$
declare
  v_uid uuid := auth.uid();
  v_kan text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if coalesce(p_phone, '') = '' then raise exception 'empty_phone'; end if;

  v_kan := public.telefon_kanonik(p_phone);
  if v_kan is null then raise exception 'invalid_phone'; end if;

  -- 🔴 ÖNCE SOR, SONRA YAZ — ama indeks de arkada duruyor. Bu kontrol
  -- kullanıcıya İYİ BİR MESAJ vermek için; yarışı KAZANAN taraf indekstir.
  -- (Sadece kontrole güvenmek, iki eşzamanlı kaydın ikisinin de "boş"
  --  görüp ikisinin de yazması demekti — 138'in yaptığı tam buydu.)
  -- 🆕 SINIF: "UYGULAMA KONTROLÜ MESAJ İÇİNDİR, KISIT KURAL İÇİN —
  -- BİRİ DİĞERİNİN YERİNE GEÇEMEZ."
  if exists (select 1 from users
              where phone_kanonik = v_kan and deleted_at is null and id <> v_uid) then
    raise exception 'phone_taken';
  end if;

  begin
    update users
       set phone = p_phone, phone_e164 = v_kan, phone_kanonik = v_kan
     where id = v_uid;
  exception when unique_violation then
    raise exception 'phone_taken';
  end;

  -- 🔴 phone_verified'a DOKUNMUYORUZ. Numarayi girmek dogrulamak degil.
  insert into verifications (user_id, phone_verified_method)
  values (v_uid, null)
  on conflict (user_id) do nothing;

  return jsonb_build_object('ok', true, 'verified', false,
    'note', (select value #>> '{}' from beta_settings where key = 'otp_notice_phone_declared'));
end $dp268$;
grant execute on function public.declare_phone(text) to authenticated;

-- `verify_otp` de kanonik kolonu yazsın: doğrulama sonrası numara
-- kanonikleşmezse indeks o hesabı hiç görmez.
do $vo268$
declare v_tanim text;
begin
  select pg_get_functiondef(p.oid) into v_tanim
    from pg_proc p where p.oid = to_regprocedure('public.verify_otp(text, text)');
  if v_tanim is null then
    raise notice '268: verify_otp yok — atlandi.'; return;
  end if;
  if v_tanim like '%phone_kanonik%' then
    raise notice '268: verify_otp zaten kanonik yaziyor.'; return;
  end if;
  v_tanim := replace(v_tanim,
    'update users set phone = p_phone, phone_e164 = p_phone where id = v_uid;',
    'update users set phone = p_phone, phone_e164 = public.telefon_kanonik(p_phone),'
    || ' phone_kanonik = public.telefon_kanonik(p_phone) where id = v_uid;');
  if v_tanim not like '%phone_kanonik%' then
    raise warning '268: verify_otp govdesi beklenen satiri TASIMIYOR — elle bakilmali.';
    return;
  end if;
  execute v_tanim;
  raise notice '268: verify_otp kanonik kolona da yaziyor. ✓';
end $vo268$;

-- ════════════════════════════════════════════════════════════════════════
-- §5 — `phone_in_use` ANON LİSTESİNDEN ÇIKIYOR
--
-- Gövdesi zaten anon'u reddediyor (ÖLÇÜM 1). İzni bırakmak, listeye
-- bakan bir sonraki insana "burası anon'a açık" diye YANLIŞ bilgi verir.
-- İzin listesi bir belge de olduğu için, yanlış satırı silmek koruma
-- kadar önemlidir.
-- ════════════════════════════════════════════════════════════════════════
revoke execute on function public.phone_in_use(text) from anon;

-- ════════════════════════════════════════════════════════════════════════
-- §6 — NÖBETÇİ: ÇAKIŞMAYI GERÇEKTEN DENİYORUZ
--
-- 🔴 "İndeks kuruldu" yazmak kanıt değil. İki hesaba aynı numarayı
-- yazmayı DENİYORUZ ve reddedildiğini görüyoruz. Ters yön de var:
-- numarası olmayan iki hesap birbirini engellememeli, yoksa kayıt
-- akışı ilk kullanıcıdan sonra kilitlenir.
-- ════════════════════════════════════════════════════════════════════════
do $nb268$
declare
  a uuid; b uuid; v_engellendi boolean := false; v_bos int;
begin
  select id into a from users where deleted_at is null order by id limit 1;
  select id into b from users where deleted_at is null and id <> a order by id limit 1;
  if a is null or b is null then
    raise notice '268 NOBETCI: iki hesap yok — canli disinda atlandi.';
    return;
  end if;

  -- (a) AYNI NUMARA İKİ HESABA YAZILAMAMALI
  begin
    update users set phone_kanonik = '905550009988' where id = a;
    update users set phone_kanonik = '905550009988' where id = b;
  exception when unique_violation then
    v_engellendi := true;
  end;
  if not v_engellendi then
    raise exception '268 NOBETCI: AYNI NUMARA HALA IKI HESAPTA OLABILIYOR.';
  end if;
  raise notice '268 NOBETCI: ayni numara ikinci hesaba yazilamadi. ✓';

  -- (b) TERS YÖN: numarasız hesaplar birbirini engellemiyor
  select count(*) into v_bos from users
   where deleted_at is null and phone_kanonik is null;
  raise notice '268 NOBETCI: numarasiz % hesap yan yana duruyor (kisitlanmadi). ✓', v_bos;

  -- (c) anon `phone_in_use` çağıramıyor
  begin
    set local role anon;
    perform public.phone_in_use('+905551112233');
    reset role;
    raise exception '268 NOBETCI: anon phone_in_use CAGIRABILIYOR.';
  exception when insufficient_privilege or raise_exception then
    reset role;
    raise notice '268 NOBETCI: anon phone_in_use cagiramiyor. ✓';
  end;

  raise exception 'NOBETCI_GERI_AL';
exception when others then
  if sqlerrm = 'NOBETCI_GERI_AL' then
    raise notice '268 NOBETCI OK — deney satirlari geri alindi.';
  else
    raise;
  end if;
end $nb268$;

commit;

-- ----------------------------------------------------------------------
-- rate_ok   [etkin kaynak: 140_rls_and_ratelimit.sql]
-- ----------------------------------------------------------------------
create or replace function public.rate_ok(p_action text, p_limit int, p_hours int default 1)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_win timestamptz; v_n int;
begin
  if v_uid is null then return false; end if;
  v_win := date_trunc('hour', now()) - make_interval(hours => greatest(p_hours,1) - 1);

  select coalesce(sum(count),0) into v_n from rate_limits
   where user_id = v_uid and action = p_action and window_start >= v_win;
  if v_n >= p_limit then return false; end if;

  insert into rate_limits (user_id, action, count)
  values (v_uid, p_action, 1)
  on conflict (user_id, action, window_start) do update set count = rate_limits.count + 1;
  return true;
end $$;

-- ----------------------------------------------------------------------
-- otp_attempt_ok   [etkin kaynak: 140_rls_and_ratelimit.sql]
-- ----------------------------------------------------------------------
create or replace function public.otp_attempt_ok()
returns boolean language sql security definer set search_path = public as $$
  select public.rate_ok('otp_verify', 5, 1);
$$;

-- ----------------------------------------------------------------------
-- prune_rate_limits   [etkin kaynak: 140_rls_and_ratelimit.sql]
-- ----------------------------------------------------------------------
create or replace function public.prune_rate_limits()
returns int language sql security definer set search_path = public as $$
  with d as (delete from rate_limits where window_start < now() - interval '2 days' returning 1)
  select count(*)::int from d;
$$;

-- ----------------------------------------------------------------------
-- create_request_impl   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ⚠ Bu fonksiyon 6 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_request_impl(p_avail_id uuid, p_type text DEFAULT 'lounge'::text, p_intro text DEFAULT NULL::text, p_idem text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare v_acik boolean; v_kalan int; v_tavan int;
      begin
        -- (a) ACİL DURDURMA
        select f.enabled into v_acik from feature_flags f where f.key = 'marketplace';
        if not coalesce(v_acik, true) then
          raise exception 'marketplace_closed';
        end if;

        -- (b) AYNI ANDA AÇIK İSTEK TAVANI — 029'da tohumlanmış ama
        -- yedi ay boyunca hiçbir yerde uygulanmamış bir eşik.
        select value into v_tavan from rule_thresholds where key = 'max_active_requests';
        select count(*) into v_kalan from requests
         where guest_id = auth.uid() and status = 'pending';
        if v_kalan >= coalesce(v_tavan, 5) then
          raise exception 'too_many_active_requests';
        end if;

        -- 🔴 300/B5: iki kapı, ikisi de ÖLÇÜLDÜ (SEED8 §5):
        --  · aynı ilana ikinci başvuru ham bir kısıt hatası döndürüyordu:
        --    "duplicate key value violates unique constraint …" — uygulama
        --    bunu "Bir şeyler ters gitti" diye gösteriyordu.
        --  · tarih bugünse ama SAAT geçmişse başvuru kabul ediliyordu.
        --  · 🔴 AYNI İLANA YENİDEN İSTEK SESSİZCE HİÇBİR ŞEY YAPMIYORDU.
        --    Uygulama tekrar-deneme anahtarını `uid:ilan` olarak üretiyor; iptal
        --    ettiğin (ya da reddedilen) isteğin anahtarı aynı kalıyordu. Yeni
        --    istek bu anahtarla gelince `preflag` ESKİ, KAPALI isteği
        --    `{"ok":true,"idempotent":true}` diye döndürüyordu — ekran "gönderildi"
        --    diyor, host hiçbir şey görmüyor. (Ölçüldü: ilk → iptal → tekrar =
        --    aynı id, durum `cancelled`.)
        --    Kapalı bir isteğin anahtarı artık serbest bırakılıyor: çift dokunuş
        --    korunur (açık istek), yeni deneme yeni istek olur.
        -- 🆕 SINIF: "BİR TEKRAR-DENEME ANAHTARI, KORUDUĞU İŞLEMDEN UZUN
        -- YAŞARSA, SONRAKİ HER GERÇEK İSTEĞİ BİR TEKRAR SANIR."
        if p_idem is not null then
          update requests set idempotency_key = null
           where idempotency_key = p_idem and guest_id = auth.uid()
             and status not in ('pending', 'accepted');
        end if;
        -- Tekrar deneme anahtarı (p_idem) ile gelen AÇIK istek dokunulmadan geçer.
        if p_idem is null or not exists (select 1 from requests
                                          where idempotency_key = p_idem and guest_id = auth.uid()) then
          if exists (select 1 from requests where guest_id = auth.uid() and avail_id = p_avail_id
                                              and status in ('pending','accepted')) then
            raise exception 'already_requested';
          end if;
          if exists (select 1 from availabilities a where a.id = p_avail_id
                      and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()) then
            raise exception 'availability_expired';
          end if;
        end if;

        return public.create_request_impl_preflag(p_avail_id, p_type, p_intro, p_idem);
      end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B6 · trg_bakiye_negatife_dusemez  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.trg_bakiye_negatife_dusemez()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_bal int;
begin
  if new.delta >= 0 then return new; end if;
  if new.reason like 'paid_guest_thanks_reversal:%' or new.reason like 'admin%' then
    return new;
  end if;

  -- 🔴 300/B6: KİLİT TETİKLEYİCİNİN İÇİNDE. 299/B2 kilidi dört yola
  -- koymuştu; `misafir_hakki_hediye_et` beşinciydi ve kilitsizdi. İki
  -- eşzamanlı hediye aynı 3 krediyi iki kez harcayabiliyordu (ölçüldü:
  -- ikinci oturum birincinin commit'ini beklemeden geçti).
  -- Kilit burada olunca YOL SAYISI önemsizleşiyor: bakiyeyi eksilten her
  -- satır, aynı kullanıcının diğer eksiltmesini commit'e kadar bekler ve
  -- sonra GÜNCEL toplamı okur.
  perform pg_advisory_xact_lock(hashtextextended('kredi:' || new.user_id::text, 0));
  select coalesce(sum(delta), 0) into v_bal
    from credit_ledger where user_id = new.user_id;

  if v_bal + new.delta < 0 then
    raise exception 'insufficient_credits'
      using detail = format('kullanıcı %s: bakiye %s, denenen %s (%s)',
                            new.user_id, v_bal, new.delta, new.reason),
            hint   = 'Bu satır bakiyeyi negatife düşürürdü; 299/B1 reddetti.';
  end if;
  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ. Açık kalan kapı varsa DUR.
-- ════════════════════════════════════════════════════════════════════════
do $z300$
declare v_n int; v_liste text;
begin
  -- A1: kilitli olanlar authenticated/anon tarafından çağrılamaz
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('change_plan','kredi_akis_raporu','anonymized_users',
                       'host_kota_durumu','doluluk_reddi_sayisi','oturum_kural_hedefi',
                       'kural_guncelligi','access_options_for_user','bo_slot_asimlari')
     and (has_function_privilege('authenticated', p.oid, 'execute')
          or has_function_privilege('anon', p.oid, 'execute'));
  if v_n > 0 then raise exception '300 §Z/A1: hâlâ açık: %', v_liste; end if;

  -- A2: PUBLIC'e açık SECURITY DEFINER fonksiyon kalmadı
  select count(distinct p.oid), string_agg(distinct p.proname, ', ') into v_n, v_liste
    from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef
     and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '300 §Z/A2: PUBLIC''e açık % fonksiyon: %', v_n, v_liste; end if;

  -- A2: küresel varsayılan gerçekten yazıldı mı?
  if not exists (select 1 from pg_default_acl d
                  where d.defaclnamespace = 0 and d.defaclobjtype = 'f'
                    and d.defaclrole = 'postgres'::regrole) then
    raise exception '300 §Z/A2: küresel varsayılan yetki kaydı yok';
  end if;

  -- Uygulamanın çağırdığı beş fonksiyon authenticated'da KALDI mı?
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('cancel_availability','binis_karti_kaydet','ilani_yeniden_yayinla',
                       'hikaye_davetini_ertele','kesifte_gorun','profil_karti',
                       'create_request','respond_request','confirm_session')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '300 §Z: uygulama fonksiyonu KAPANDI: %', v_liste; end if;

  -- A3 / B6 tetikleyicileri yerinde mi?
  if not exists (select 1 from pg_trigger where tgname = 'trg_visit_0_beyan_temizle') then
    raise exception '300 §Z/A3: tetikleyici yok';
  end if;
  if position('pg_advisory_xact_lock' in
       (select prosrc from pg_proc where proname = 'trg_bakiye_negatife_dusemez')) = 0 then
    raise exception '300 §Z/B6: kredi kilidi tetikleyicide yok';
  end if;
  if position('availability_expired' in
       (select prosrc from pg_proc where proname = 'respond_request')) = 0 then
    raise exception '300 §Z/B1: kabul kapısı yok';
  end if;
  if position('already_requested' in
       (select prosrc from pg_proc where proname = 'create_request_impl')) = 0 then
    raise exception '300 §Z/B5: mükerrer başvuru kapısı yok';
  end if;

  raise notice '300 §Z: bütün kapılar ölçüldü — kapalı';
end $z300$;

select '300 OK — uçtan uca denetim bulguları kapatıldı' as sonuc;

-- ----------------------------------------------------------------------
-- request_account_deletion   [etkin kaynak: 258_olmayan_kolonlar.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.request_account_deletion(p_email text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(p_email,'') !~ '^[^@]+@[^@]+\.[^@]+$' then
    raise exception 'invalid_email';
  end if;
  -- 🔴 SILME OTOMATIK DEGIL. E-postasini bilen herkesin baskasinin
  -- hesabini silebilmesi demek olurdu. Talep kaydedilir, BO'da
  -- kullanici dogrulandiktan SONRA islenir.
  insert into deletion_requests (email, note)
  values (lower(trim(p_email)), nullif(trim(coalesce(p_reason,'')),''))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id,
    'note', 'Talebin alindi. Kimligini dogruladiktan sonra 30 gun icinde islenecek.');
end $function$;

-- ── bo_plan_ata ──
CREATE OR REPLACE FUNCTION public.bo_plan_ata(p_user uuid, p_plan text, p_sebep text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_eski text;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select plan::text into v_eski from users where id = p_user;
  if v_eski is null then raise exception 'kullanici_yok'; end if;

  update users set plan = p_plan::plan_type, updated_at = now() where id = p_user;

  insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
  values (auth.uid(), 'plan_ata', 'user', p_user,
          jsonb_build_object('eski', v_eski, 'yeni', p_plan, 'sebep', p_sebep));

  return jsonb_build_object('ok', true, 'eski', v_eski, 'yeni', p_plan);
end $function$;

-- ── trg_cinsiyet_kilidi ──
CREATE OR REPLACE FUNCTION public.trg_cinsiyet_kilidi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.gender is not null and new.gender is distinct from old.gender then
    -- Yönetim değiştirebilir; kullanıcı değiştiremez.
    if auth.uid() is not null
       and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
      raise exception 'cinsiyet_degistirilemez';
    end if;
    insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
    values (auth.uid(), 'cinsiyet_degisti', 'user', new.id,
            jsonb_build_object('eski', old.gender, 'yeni', new.gender));
  end if;
  return new;
end $function$;

-- ── 3 · NÖBETÇİ ─────────────────────────────────────────────────────
-- 🔴 Bu blok kolonların VARLIĞINI değil, YAZILABİLİRLİĞİNİ ölçüyor.
-- "information_schema'da var mı" sorusu bu hatayı yakalamazdı: hata
-- zaten ifade ÇÖZÜMLENDİĞİNDE çıkıyor. O yüzden her düzeltilen yol
-- gerçekten bir kez çalıştırılıyor ve sonra geri alınıyor.
--
-- 🆕 SINIF: "BİR KOLONUN ŞEMADA GÖRÜNMESİ, O KOLONA YAZAN KODUN
-- ÇALIŞTIĞI ANLAMINA GELMEZ — YAZMA YOLUNU BİR KEZ YÜRÜT."
do $n258$
declare
  v_h text[] := '{}';
  v_u uuid; v_r uuid;
begin
  begin
    select id into v_u from users limit 1;

    -- points_ledger.balance_after gerçekten yazılabiliyor mu
    insert into points_ledger (user_id, delta, reason, ref_id, balance_after)
    values (v_u, 1, 'n258_olcum', null, 1);

    -- requests.decision_note gerçekten yazılabiliyor mu
    select id into v_r from requests limit 1;
    if v_r is not null then
      update requests set decision_note = coalesce(decision_note, 'n258 ölçüm')
       where id = v_r;
    end if;

    -- audit_log'un doğru kolonları
    insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
    values (v_u, 'n258_olcum', 'user', v_u, jsonb_build_object('olcum', true));

    -- reports.description ve deletion_requests.note
    insert into deletion_requests (email, note)
    values ('n258@olcum.invalid', 'olcum');

    raise exception 'GERI_AL_258';
  exception when others then
    if sqlerrm <> 'GERI_AL_258' then
      v_h := v_h || ('olcum coktu: ' || sqlerrm);
    end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '258 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '258 OK · eksik iki kolon eklendi · alti etkin fonksiyonun kolon adlari duzeltildi · yazma yollari calistirilarak dogrulandi';
end $n258$;

commit;

select '258 OLMAYAN KOLONLAR' as sonuc,
       (select count(*) from information_schema.columns
         where table_name='points_ledger' and column_name='balance_after') as pl_balance_after,
       (select count(*) from information_schema.columns
         where table_name='requests' and column_name='decision_note') as req_decision_note;

-- ----------------------------------------------------------------------
-- clip_text   [etkin kaynak: 142_short_detail_hard.sql]
-- ----------------------------------------------------------------------
create or replace function public.clip_text(p_text text, p_max int)
returns text language sql immutable as $$
  -- 🔴 Kelime ortasindan kesmek okumayi bozar; son bosluktan kes.
  -- Kesilmisse "…" koy: kullanici devaminin oldugunu ANLAMALI.
  select case
    when p_text is null or length(p_text) <= p_max then p_text
    else rtrim(left(p_text, coalesce(
           nullif(strpos(reverse(left(p_text, p_max)), ' '), 0),
           0) * -1 + p_max), ' .,;') || '…'
  end;
$$;

-- ----------------------------------------------------------------------
-- guide_airports   [etkin kaynak: 143_lounge_guide.sql]
-- ----------------------------------------------------------------------
create or replace function public.guide_airports()
returns table (code text, city text, name text, lounges int, has_rules boolean)
language sql stable security definer set search_path = public as $$
  select a.code::text, a.city, a.name,
         count(distinct v.id)::int,
         -- 🔴 "Kural var mi" ayri bir soru: salon listelemek kolay,
         -- kuralini bilmek zor. Kullaniciya hangi havalimaninda GERCEK
         -- cevap verebildigimizi durustce gosteriyoruz.
         bool_or(exists (select 1 from lounge_venue_acceptance x
                          where x.venue_id = v.id and x.active and not x.is_placeholder))
    from airports a
    left join lounge_venues v on v.airport_code = a.code and v.active and v.venue_kind = 'lounge'
   group by a.code, a.city, a.name
  having count(distinct v.id) > 0
   order by count(distinct v.id) desc, a.code;
$$;

-- ----------------------------------------------------------------------
-- guide_lounges   [etkin kaynak: 187_kanitlanmis_kusurlar.sql]
-- ⚠ Bu fonksiyon 5 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.guide_lounges(' || v_args
       || ') returns ' || v_res
       || ' language plpgsql stable security definer set search_path = public as $BODY$'
       || v_new || '$BODY$';
  raise notice '187: rehber artik salon kisitina uyuyor';
end $$;

-- ----------------------------------------------------------------------
-- guide_programs   [etkin kaynak: 154_membership_tiers.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.guide_programs()
returns table (code text, name text, tiers jsonb, popular boolean, kind text)
language sql stable security definer set search_path = public as $$
  select p.code, p.name,
         coalesce((select jsonb_agg(jsonb_build_object(
                     'code', r.card_tier,
                     'label', public.card_tier_label(r.card_tier))
                     order by r.card_tier)
                     from (select distinct card_tier from lounge_guest_rules
                            where program_id = p.id and card_tier is not null
                              and (effective_to is null or effective_to >= current_date)) r), '[]'::jsonb),
         p.code in ('TK_MS','AJET_MS','PRIORITY_PASS','LOUNGEKEY','DRAGONPASS','BANK_CARD','STAR_GOLD'),
         -- Kullanicinin zihnindeki ayrim: havayolu statusu mu, bagimsiz
         -- uyelik mi, banka avantaji mi. Liste bu basliklarla gruplanir.
         case when p.code in ('TK_MS','AJET_MS','PGS_PAID','STAR_GOLD') then 'airline'
              when p.code = 'BANK_CARD' then 'bank'
              else 'membership' end
    from lounge_programs p
   -- 🔴 `p.code <> 'BANK_CARD'` FILTRESI KALDIRILDI.
   -- 143'te "banka karti bir program degil" diye elemistim. Kullanicinin
   -- gozunden ise en yaygin hak kaynaklarindan biri. Kendi kartini
   -- listede bulamayan kullanici, urunun ona hitap etmedigini dusunur.
   where p.active
   order by (p.code in ('TK_MS','AJET_MS','PRIORITY_PASS','LOUNGEKEY','DRAGONPASS','BANK_CARD','STAR_GOLD')) desc,
            p.name;
$$;

-- ----------------------------------------------------------------------
-- guide_hosts_today   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.guide_hosts_today(p_airport text, p_date date default null)
returns jsonb language sql stable security definer set search_path = public as $$
  -- 🔴 301/§4: `active` ve `visibility` yoktu — kaldırılmış ve gizli ilanlar
  -- "bugün X host" sayısına giriyordu. Test hesapları da (§3) düşüyor.
  select jsonb_build_object(
    'airport', upper(p_airport),
    'date', coalesce(p_date, current_date),
    'count', (select count(*) from availabilities a
               where a.airport_code = upper(p_airport)
                 and a.active and coalesce(a.visibility::text, 'Public') <> 'Hidden'
                 and a.avail_date >= coalesce(p_date, current_date)
                 and a.avail_date <= coalesce(p_date, current_date) + 2
                 and coalesce(a.filled,0) < coalesce(a.slots,1)
                 and not public.test_hesabi_gizli_mi(a.host_id)),
    'next_date', (select min(a.avail_date) from availabilities a
                   where a.airport_code = upper(p_airport)
                     and a.active and coalesce(a.visibility::text, 'Public') <> 'Hidden'
                     and a.avail_date >= current_date
                     and coalesce(a.filled,0) < coalesce(a.slots,1)
                     and not public.test_hesabi_gizli_mi(a.host_id)));
$$;

-- ----------------------------------------------------------------------
-- resolve_guest_rule   [etkin kaynak: 187_kanitlanmis_kusurlar.sql]
-- ⚠ Bu fonksiyon 7 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.resolve_guest_rule(' || v_args
       || ') returns ' || v_res
       || ' language plpgsql stable security definer set search_path = public as $BODY$'
       || v_new || '$BODY$';

  select count(*) into v_n from regexp_matches(v_new, 'effective_from', 'g');
  raise notice '187: resolve_guest_rule % geciste effective_from kontrol ediyor', v_n;
end $$;

-- ----------------------------------------------------------------------
-- rule_matrix_check   [etkin kaynak: 148_rule_matrix_test.sql]
-- ----------------------------------------------------------------------
create or replace function public.rule_matrix_check()
returns table (senaryo text, beklenen text, gercek text, sonuc text)
language plpgsql stable security definer set search_path = public as $$
declare c record; g jsonb; v_tk uuid; v_aj uuid; v_got text;
begin
  select id into v_tk from lounge_programs where code = 'TK_MS';
  select id into v_aj from lounge_programs where code = 'AJET_MS';

  for c in select * from (values
    -- ---- TABLO-1/2: TK SEFERINDE ----
    ('TK · Elite Plus',        v_tk,'ELPL','TK',   null, 'aile+1'),
    ('TK · Elite',             v_tk,'ELITE','TK',  null, 'aile+1'),   -- Elite = ELPL (Tablo-1)
    ('TK · M&S Elite Corp',    v_tk,'MS_EC','TK',  null, 'aile+1'),
    ('TK · Star Alliance Gold',v_tk,'SAG','TK',    null, '1'),        -- aile YOK
    ('TK · Miles&More',        v_tk,'PLM','TK',    null, '1'),
    ('TK · Corporate Club',    v_tk,'CORP','TK',   null, '1'),
    ('TK · Classic Plus',      v_tk,'CLPL','TK',   null, '0'),        -- Tablo-1: Yok
    ('TK · Classic',           v_tk,'CLASSIC','TK',null, '0-ucretli'),-- ucretle girer
    ('TK · M&S ABD Kart',      v_tk,'MS_US_CC','TK',null,'0'),
    -- ---- TABLO-2 alt blok: STAR ALLIANCE UYESI BASKA HAVAYOLU ----
    -- 🔴 AYNI KART, AILE HAKKI DUSUYOR. Fark yalniz tasiyici.
    ('LH · Elite Plus',        v_tk,'ELPL','LH',   null, '1'),
    ('LH · Elite',             v_tk,'ELITE','LH',  null, '1'),
    ('LX · Star Alliance Gold',v_tk,'SAG','LX',    null, '1'),
    -- ---- KABIN SINIFI (kartsiz) ----
    ('Kartsiz Business',       v_tk, null,'TK','business','0'),
    ('Kartsiz First',          v_tk, null,'TK','first',   '1'),
    -- ---- AJET ----
    ('AJet · Elite Plus',      v_aj,'ELPL','VF',   null, 'aile+1'),
    ('AJet · Elite',           v_aj,'ELITE','VF',  null, 'aile+1'),
    ('AJet · Classic Plus',    v_aj,'CLPL','VF',   null, '0-ucretli'),
    ('AJet · Classic',         v_aj,'CLASSIC','VF',null, '0-ucretli')
  ) as t(ad, pid, tier, carrier, cabin, bek)
  loop
    g := public.resolve_guest_rule(c.pid, null, c.tier, c.carrier, c.cabin);
    v_got := case
      when (g ->> 'family_allowed')::boolean then 'aile+' || (g ->> 'guest_allowance')
      when (g ->> 'guest_allowance')::int = 0 and (g ->> 'paid_entry_allowed')::boolean then '0-ucretli'
      else (g ->> 'guest_allowance') end;
    senaryo := c.ad; beklenen := c.bek; gercek := v_got;
    sonuc := case when v_got = c.bek then '✓' else '✗ SAPMA' end;
    return next;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- best_entitlement   [etkin kaynak: 149_multi_entitlement.sql]
-- ----------------------------------------------------------------------
create or replace function public.best_entitlement(
  p_venue_id uuid,
  p_program_codes text[],
  p_tier text default null,
  p_carrier text default null,
  p_cabin text default null
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c record; g jsonb; best jsonb := null; best_score int := -1; v_score int;
  alts jsonb := '[]'::jsonb; n_valid int := 0;
begin
  for c in
    select p.id, p.code, p.name, a.guest_policy, a.is_placeholder,
           a.checked_at, a.fee_payer, a.conditions
      from unnest(coalesce(p_program_codes, '{}'::text[])) pc
      join lounge_programs p on p.code = pc and p.active
      left join lounge_venue_acceptance a
             on a.venue_id = p_venue_id and a.program_id = p.id and a.active
  loop
    if c.guest_policy is null then
      -- Bu program BU SALONDA gecmiyor. Sessizce atlamak yerine
      -- alternatif listesine "gecmiyor" diye yaziyoruz: kullanici
      -- neden o kartinin kullanilmadigini gormeli.
      alts := alts || jsonb_build_object('program', c.name, 'valid', false,
                                          'why', 'Bu salonda geçerli değil');
      continue;
    end if;
    n_valid := n_valid + 1;
    g := public.resolve_guest_rule(c.id, p_venue_id, p_tier, p_carrier, p_cabin);

    -- 🔴 PUANLAMA: once GECERLILIK ve GUVEN, sonra misafir sayisi.
    -- "En cok misafir veren"i secmek cazip ama yanlis: dogrulanmamis
    -- bir kaynaga dayanip 2 misafir vaat etmektense, dogrulanmis bir
    -- kaynaga dayanip 1 misafir demek daha az zarar verir.
    v_score := 0
      + case when not c.is_placeholder and c.checked_at is not null then 40 else 0 end
      + case when c.guest_policy = 'included' then 20
             when c.guest_policy = 'paid' then 8 else 0 end
      + least(coalesce((g ->> 'guest_allowance')::int, 0), 3) * 5
      + case when coalesce((g ->> 'family_allowed')::boolean, false) then 6 else 0 end
      + case when coalesce(c.fee_payer,'') = '' then 3 else 0 end;

    alts := alts || jsonb_build_object(
      'program', c.name, 'valid', true,
      'guests', (g ->> 'guest_allowance')::int,
      'family', (g ->> 'family_allowed')::boolean,
      'headline', g ->> 'headline');

    if v_score > best_score then
      best_score := v_score;
      best := g || jsonb_build_object('program_code', c.code, 'program', c.name,
                                      'guest_policy', c.guest_policy,
                                      'fee_payer', c.fee_payer,
                                      'verified', (not c.is_placeholder and c.checked_at is not null));
    end if;
  end loop;

  if best is null then
    return jsonb_build_object('found', false, 'valid_count', 0, 'alternatives', alts,
      'headline', 'Bu salonda geçerli bir hakkın görünmüyor',
      'detail', 'Seçtiğin hakların hiçbiri bu salonda kabul edilmiyor.');
  end if;

  return best || jsonb_build_object(
    'found', true, 'valid_count', n_valid, 'alternatives', alts,
    -- Birden fazla gecerli hak varsa kullaniciya SOYLE: hangisini
    -- kullandigimizi bilmezse, kapida farkli bir kart uzatabilir.
    'multi_note', case when n_valid > 1
      then 'Birden fazla hakkın geçerli; en güvenlisini gösteriyoruz: ' || (best ->> 'program')
      end);
end $$;

-- ----------------------------------------------------------------------
-- multi_entitlement_check   [etkin kaynak: 149_multi_entitlement.sql]
-- ----------------------------------------------------------------------
create or replace function public.multi_entitlement_check()
returns table (senaryo text, secilen text, misafir text, sonuc text)
language plpgsql stable security definer set search_path = public as $$
declare c record; g jsonb; v_ist_tk uuid; v_iga uuid;
begin
  select v.id into v_ist_tk from lounge_venues v
   where v.airport_code='IST' and v.active and v.name ilike '%turkish%'
     and coalesce(v.section,'') = 'miles_smiles' limit 1;
  select v.id into v_iga from lounge_venues v
   where v.airport_code='IST' and v.active and v.name ilike '%iga lounge%' limit 1;

  for c in select * from (values
    ('THY salonu · ELPL + PriorityPass', v_ist_tk, array['TK_MS','PRIORITY_PASS'],'ELPL','TK'),
    ('THY salonu · CLPL + PriorityPass', v_ist_tk, array['TK_MS','PRIORITY_PASS'],'CLPL','TK'),
    ('THY salonu · yalniz PriorityPass', v_ist_tk, array['PRIORITY_PASS'],        null,  'TK'),
    ('iGA salonu · CLPL + PriorityPass', v_iga,    array['TK_MS','PRIORITY_PASS'],'CLPL','TK'),
    ('iGA salonu · ELPL tek basina',     v_iga,    array['TK_MS'],                'ELPL','TK'),
    ('THY salonu · uc hak birden',       v_ist_tk, array['TK_MS','PRIORITY_PASS','DRAGONPASS'],'ELITE','TK')
  ) as t(ad, vid, progs, tier, carrier)
  loop
    g := public.best_entitlement(c.vid, c.progs, c.tier, c.carrier, null);
    senaryo := c.ad;
    secilen := coalesce(g ->> 'program', '(yok)');
    misafir := coalesce(g ->> 'guest_allowance','-')
            || case when coalesce((g ->> 'family_allowed')::boolean,false) then ' +aile' else '' end;
    sonuc := coalesce(g ->> 'headline','-');
    return next;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- rule_contamination_check   [etkin kaynak: 199_ucus_saati_terminal_ve_katalog.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.rule_contamination_check()
returns table (program text, kart text, sorun text, ornek text)
language sql stable security definer set search_path = public as $$
  select p.name, coalesce(r.card_tier,'(genel)'),
         'Kural notu BAŞKA bir programa ait görünüyor',
         left(r.notes, 70)
    from lounge_guest_rules r
    join lounge_programs p on p.id = r.program_id
   where (r.effective_to is null or r.effective_to >= current_date)
     and (
       -- 🔴 "Miles&Smiles bölüm" DESENİ KALDIRILDI: bölüm bir odadır.
       -- Yerine HAK iddiası aranıyor: statü/kart/üyelik/hakkı.
       (p.code not in ('TK_MS','AJET_MS')
        and r.notes ~* '(THY seferinde|AJet seferinde|Miles&Smiles (statü|kartı|üyeliğ|hakkı))')
       or (p.code <> 'PGS_PAID'      and r.notes ~* 'Pegasus biniş kartı')
       or (p.code <> 'PRIORITY_PASS' and r.notes ~* 'Priority Pass üyelik')
       or (p.code <> 'IGA_PASS'      and r.notes ~* 'İGA Pass kişiye')
     );
$$;

-- ----------------------------------------------------------------------
-- pick_host_program   [etkin kaynak: 151_deterministic_program_pick.sql]
-- ----------------------------------------------------------------------
create or replace function public.pick_host_program(p_host uuid, p_venue_id uuid)
returns uuid language sql stable security definer set search_path = public as $$
  select a2.program_id
    from host_entitlements he
    join lounge_venue_acceptance a2
      on a2.program_id = he.program_id and a2.venue_id = p_venue_id
     -- 🔴 `accepted` NULL olabiliyor ve `and a2.accepted` NULL'da
     -- satiri ELIYOR. 086'dan devraldigim kosuldu; belirli siralamayi
     -- kurarken aynen tasidim ve fonksiyon BOS donmeye basladi.
     -- Ucuncu kez ayni ders: NULL, boolean baglamda false degil NULL'dir.
     and coalesce(a2.accepted, true) and a2.active
   where he.user_id = p_host
   -- 🔴 SIRALAMA TAM BELIRLI OLMALI. Her satir en az bir anahtarda
   -- digerinden farkli olmali; yoksa PostgreSQL istedigini secer ve
   -- ayni sorgu iki kez farkli cevap verir.
   order by coalesce(a2.guest_policy = 'included', false) desc,
            coalesce(a2.guest_policy = 'paid', false) desc,
            coalesce(he.verified, false) desc,
            coalesce(a2.is_placeholder, false) asc,     -- arastirilmis olan once
            a2.checked_at desc nulls last,              -- yeni dogrulanan once
            a2.program_id                               -- 🔴 SON CARE: benzersiz,
                                                        -- beraberligi kesin bitirir
   limit 1;
$$;

-- ----------------------------------------------------------------------
-- determinism_check   [etkin kaynak: 151_deterministic_program_pick.sql]
-- ----------------------------------------------------------------------
create or replace function public.determinism_check()
returns table (avail_id uuid, farkli_cevap int)
language sql stable security definer set search_path = public as $$
  select a.id, count(distinct x.pol)::int
    from availabilities a
    cross join lateral (
      select (public.lounge_access_decision_v5(a.id, null, null) ->> 'guest_policy') as pol
        from generate_series(1, 20)
    ) x
   group by a.id having count(distinct x.pol) > 1;
$$;

-- ----------------------------------------------------------------------
-- field_consensus   [etkin kaynak: 152_field_reports_loop.sql]
-- ----------------------------------------------------------------------
create or replace function public.field_consensus(p_venue_id uuid, p_program_id uuid default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'reports', count(*),
    'entered_rate', round(avg(case when r.entered then 1 else 0 end)::numeric, 2),
    'guest_ok_rate', round(avg(case when r.guest_accepted then 1
                                    when r.guest_accepted is false then 0 end)::numeric, 2),
    'fee_rate', round(avg(case when r.fee_charged then 1
                               when r.fee_charged is false then 0 end)::numeric, 2),
    'quota_reports', (select jsonb_agg(distinct x.quota_left)
                        from lounge_field_reports x
                       where x.venue_id = p_venue_id and coalesce(x.quota_left,'') <> ''),
    -- 5+ rapor ve %80+ uzlasma -> DOGRULANDI sayilir
    'verdict', case
      when count(*) < 3 then 'insufficient'
      when avg(case when r.entered then 1 else 0 end) >= 0.8 then 'confirmed'
      when avg(case when r.entered then 1 else 0 end) <= 0.2 then 'contradicted'
      else 'mixed' end)
    from lounge_field_reports r
   where r.venue_id = p_venue_id
     and (p_program_id is null or r.program_id = p_program_id);
$$;

-- ----------------------------------------------------------------------
-- apply_field_consensus   [etkin kaynak: 152_field_reports_loop.sql]
-- ----------------------------------------------------------------------
create or replace function public.apply_field_consensus()
returns int language plpgsql security definer set search_path = public as $$
declare c record; n int := 0;
begin
  for c in
    select r.venue_id, r.program_id, count(*) k,
           avg(case when r.guest_accepted then 1 when r.guest_accepted is false then 0 end) g
      from lounge_field_reports r
     where r.program_id is not null and r.guest_accepted is not null
     group by r.venue_id, r.program_id
    having count(*) >= 5
  loop
    -- 🔴 SAHA VERISI RESMI KAYNAGI EZMEZ, ONU TAMAMLAR.
    -- Yalniz `is_placeholder` (arastirilmamis) satirlari yukseltiyoruz.
    -- Bankanin kendi sayfasindan gelen bir kurali bes kullanici
    -- beyaniyla degistirmek, dogrulanmis veriyi anekdotla ezmek olur.
    update lounge_venue_acceptance a
       set guest_policy = case when c.g >= 0.8 then 'included'
                               when c.g <= 0.2 then 'not_allowed'
                               else a.guest_policy end,
           is_placeholder = false,
           checked_at = current_date,
           conditions = coalesce(a.conditions,'')
                     || format(' [saha] %s kullanıcı raporu ile doğrulandı.', c.k)
     where a.venue_id = c.venue_id and a.program_id = c.program_id
       and a.active and a.is_placeholder;
    if found then n := n + 1; end if;
  end loop;
  return n;
end $$;

-- ----------------------------------------------------------------------
-- claim_founding_host   [etkin kaynak: 153_host_motivation.sql]
-- ----------------------------------------------------------------------
create or replace function public.claim_founding_host()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_no int; v_has int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select founding_host_no into v_has from profiles where user_id = v_uid;
  if v_has is not null then
    return jsonb_build_object('ok', true, 'no', v_has, 'already', true);
  end if;
  -- Ilan acmamis birine verilmez: rozet NIYETI degil EYLEMI odullendirir.
  if not exists (select 1 from availabilities where host_id = v_uid) then
    return jsonb_build_object('ok', false, 'reason', 'no_listing');
  end if;

  select coalesce(max(founding_host_no), 0) + 1 into v_no from profiles;
  if v_no > 100 then
    return jsonb_build_object('ok', false, 'reason', 'closed',
      'note', 'Kurucu Host kontenjanı doldu.');
  end if;
  update profiles set founding_host_no = v_no where user_id = v_uid;
  return jsonb_build_object('ok', true, 'no', v_no,
    'note', 'Kurucu Host #' || v_no || ' — bu rozet kalıcıdır.');
end $$;

-- ----------------------------------------------------------------------
-- host_unused_rights   [etkin kaynak: 153_host_motivation.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_unused_rights(p_user uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := coalesce(p_user, auth.uid()); he record; v_used int; v_year int;
begin
  select * into he from host_entitlements where user_id = v_uid
   order by coalesce(verified,false) desc limit 1;
  if not found or he.quota_total is null then
    return jsonb_build_object('known', false);
  end if;

  v_year := extract(year from current_date);
  select count(*) into v_used from sessions s
    join availabilities a on a.id = s.avail_id
   where a.host_id = v_uid and s.status = 'completed'
     and extract(year from s.created_at) = v_year;

  return jsonb_build_object(
    'known', true,
    'total', he.quota_total,
    'used', v_used,
    'left', greatest(he.quota_total - v_used, 0),
    -- 🔴 KAYIP CERCEVESI: "8 hakkin kaldi" degil "8 hakkin bosa gidecek".
    -- Ayni sayi, farkli cumle — ve kayip, kazanctan cok harekete gecirir.
    'headline', case
      when he.quota_total - v_used <= 0 then 'Bu yılki misafir hakkını kullandın.'
      else format('Bu yıl %s misafir hakkın kullanılmadan duruyor.', he.quota_total - v_used) end,
    'sub', case when he.quota_total - v_used > 0
      then 'Kullanılmayan haklar yıl sonunda siliniyor. Bir yolcuyu içeri alarak değerlendirebilirsin.' end,
    'note', 'Bu sayı SENİN beyanına dayanır; kartını veren kurumdan teyit et.');
end $$;

-- ----------------------------------------------------------------------
-- founding_host_status   [etkin kaynak: 153_host_motivation.sql]
-- ----------------------------------------------------------------------
create or replace function public.founding_host_status()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'taken', (select count(*) from profiles where founding_host_no is not null),
    'left', greatest(100 - (select count(*) from profiles where founding_host_no is not null), 0),
    'mine', (select founding_host_no from profiles where user_id = auth.uid()));
$$;

-- ----------------------------------------------------------------------
-- entry_cost_note   [etkin kaynak: 155_member_cost_visible.sql]
-- ----------------------------------------------------------------------
create or replace function public.entry_cost_note(
  p_program_id uuid, p_tier text default null
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare r lounge_guest_rules%rowtype; p lounge_programs%rowtype;
begin
  select * into p from lounge_programs where id = p_program_id;
  select * into r from lounge_guest_rules x
   where x.program_id = p_program_id
     and (p_tier is null or x.card_tier = p_tier or x.card_tier is null)
     and (x.effective_to is null or x.effective_to >= current_date)
   order by coalesce(x.card_tier = p_tier, false) desc, x.card_tier nulls last
   limit 1;

  if not found or (coalesce(r.member_entry_fee,'') = '' and coalesce(r.guest_entry_fee,'') = '') then
    return jsonb_build_object('has_cost', false);
  end if;

  return jsonb_build_object(
    'has_cost', true,
    'program', p.name,
    'tier', public.card_tier_label(r.card_tier),
    'member_fee', nullif(r.member_entry_fee,''),
    'guest_fee', nullif(r.guest_entry_fee,''),
    'free_visits', r.member_free_visits,
    -- 🔴 BASLIK EN KOTU DURUMU SOYLER, ortalamayi degil.
    -- "Bazen ucretsiz olabilir" demek, host'u ucretsiz sanmaya iter.
    -- Beklenenden ucuza cikmak surpriz degil; pahaliya cikmak surprizdir.
    'headline', case
      when coalesce(r.member_entry_fee,'') <> '' and coalesce(r.guest_entry_fee,'') <> ''
        then 'Bu hakla hem kendi girişin hem misafirin ücretli olabilir'
      when coalesce(r.guest_entry_fee,'') <> ''
        then 'Misafir girişi ücretli — ücret senin kartından çekilir'
      else 'Kendi girişin ücretli olabilir' end,
    'detail', r.notes);
end $$;

-- ----------------------------------------------------------------------
-- guide_cost   [etkin kaynak: 155_member_cost_visible.sql]
-- ----------------------------------------------------------------------
create or replace function public.guide_cost(p_program_code text, p_tier text default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select public.entry_cost_note(
    (select id from lounge_programs where code = p_program_code), p_tier);
$$;

-- ----------------------------------------------------------------------
-- mixed_case_check   [etkin kaynak: 156_official_alignment_and_scope.sql]
-- ----------------------------------------------------------------------
create or replace function public.mixed_case_check()
returns table (senaryo text, beklenen text, gercek text, sonuc text)
language plpgsql stable security definer set search_path = public as $$
declare
  v_ic uuid; v_dis_ms uuid; v_dis_biz uuid; v_iga uuid;
  p_tk uuid; g jsonb; ok boolean;
begin
  select v.id into v_ic from lounge_venues v
   where v.airport_code='IST' and v.operator='THY' and v.scope='domestic' and v.active limit 1;
  select v.id into v_dis_ms from lounge_venues v
   where v.airport_code='IST' and v.operator='THY' and v.section='miles_smiles' and v.active limit 1;
  select v.id into v_dis_biz from lounge_venues v
   where v.airport_code='IST' and v.operator='THY' and v.section='business' and v.active limit 1;
  select v.id into v_iga from lounge_venues v
   where v.airport_code='IST' and v.name ilike '%iga%' and v.active limit 1;
  select id into p_tk from lounge_programs where code='TK_MS';

  -- (ad · venue · tier · carrier · cabin · beklenen_misafir · beklenen_aile)
  for senaryo, beklenen, gercek, ok in
    with t(ad, vid, tier, carrier, cabin, exp_g, exp_fam) as (values
      ('CLPL İÇ hat: kendisi girer, misafir yok',            v_ic,     'CLPL', 'TK', null::text, 0, false),
      ('CLPL DIŞ hat M&S: hak YOK',                          v_dis_ms, 'CLPL', 'TK', null, 0, false),
      ('ELPL TK iç hat: aile veya 1 misafir',                v_ic,     'ELPL', 'TK', null, 1, true),
      ('ELPL DIŞ hat M&S, TK: aile hakkı korunur',           v_dis_ms, 'ELPL', 'TK', null, 1, true),
      ('ELPL, LH (Star) DIŞ hat: 1 misafir, AİLE YOK',       v_dis_ms, 'ELPL', 'LH', null, 1, false),
      ('MS_EC, LH, IST M&S bölümü İSTİSNA: aile VAR',        v_dis_ms, 'MS_EC','LH', null, 1, true),
      ('SAG, TK: 1 misafir aile yok',                        v_dis_ms, 'SAG',  'TK', null, 1, false),
      ('Kartsız Business kabin: misafir yok',                v_dis_biz, null,  'TK', 'business', 0, false),
      ('Kartsız First (Star): 1 misafir',                    v_dis_biz, null,  'LH', 'first', 1, false),
      ('CLASSIC: ücretle girer, misafir yok',                v_ic,     'CLASSIC','TK', null, 0, false)
    )
    select t.ad,
           t.exp_g::text || case when t.exp_fam then '+aile' else '' end,
           coalesce((public.resolve_guest_rule(p_tk, t.vid, t.tier, t.carrier, t.cabin) ->> 'guest_allowance'),'?')
             || case when coalesce((public.resolve_guest_rule(p_tk, t.vid, t.tier, t.carrier, t.cabin) ->> 'family_allowed')::boolean,false) then '+aile' else '' end,
           coalesce((public.resolve_guest_rule(p_tk, t.vid, t.tier, t.carrier, t.cabin) ->> 'guest_allowance')::int,-1) = t.exp_g
           and coalesce((public.resolve_guest_rule(p_tk, t.vid, t.tier, t.carrier, t.cabin) ->> 'family_allowed')::boolean,false) = t.exp_fam
      from t
  loop
    sonuc := case when ok then '✓' else '✗ UYUŞMUYOR' end;
    return next;
  end loop;

  -- Çoklu hak mix'i: CLPL + Priority Pass
  g := public.best_entitlement(v_ic, array['TK_MS','PRIORITY_PASS'], 'CLPL', 'TK', null);
  senaryo := 'MIX: CLPL + PP, THY İÇ hat → TK_MS kazanır';
  beklenen := 'Miles&Smiles'; gercek := coalesce(g ->> 'program','?');
  sonuc := case when (g ->> 'program_code') = 'TK_MS' then '✓' else '✗ UYUŞMUYOR' end;
  return next;

  g := public.best_entitlement(v_iga, array['TK_MS','PRIORITY_PASS'], 'CLPL', 'TK', null);
  senaryo := 'MIX: CLPL + PP, iGA → PP kazanır (CLPL orada geçmez)';
  beklenen := 'Priority Pass'; gercek := coalesce(g ->> 'program','?');
  sonuc := case when (g ->> 'program_code') = 'PRIORITY_PASS' then '✓' else '✗ UYUŞMUYOR' end;
  return next;
end $$;

-- ----------------------------------------------------------------------
-- decision_chain_check   [etkin kaynak: 157_decision_uses_resolver.sql]
-- ----------------------------------------------------------------------
create or replace function public.decision_chain_check()
returns table (senaryo text, beklenen text, gercek text, sonuc text)
language plpgsql stable security definer set search_path = public as $$
declare d jsonb; v_av uuid;
begin
  -- CLPL + IST dış hat: misafir alınamaz (156'nın kuralı KARARA aktı mı?)
  select a.id into v_av from availabilities a join users u on u.id=a.host_id
   where u.email='kural2@seed.loungelink.test'
   order by a.avail_date, a.time_from, a.id limit 1;
  if v_av is null then
    senaryo:='SEED yüklenmemiş'; beklenen:='-'; gercek:='-'; sonuc:='atlandı'; return next; return;
  end if;
  d := public.lounge_access_decision(v_av, 'TK714');
  senaryo := 'CLPL host, IST DIŞ hat: misafir ALINAMAZ + tier kararda';
  beklenen := 'not_allowed · tier=CLPL';
  gercek := coalesce(d->>'guest_policy','?') || ' · tier=' || coalesce(d->>'tier','YOK');
  sonuc := case when d->>'guest_policy'='not_allowed' and d->>'tier'='CLPL'
                then '✓' else '✗ UYUŞMUYOR' end;
  return next;

  -- ELPL + TK dış hat: aile hakkı kararda görünür
  select a.id into v_av from availabilities a join users u on u.id=a.host_id
   where u.email='kural1@seed.loungelink.test'
   order by a.avail_date, a.time_from, a.id limit 1;
  d := public.lounge_access_decision(v_av, 'TK712');
  senaryo := 'ELPL host, TK dış hat: 1 misafir + AİLE kararda';
  beklenen := 'included 1 · family=true';
  gercek := coalesce(d->>'guest_policy','?')||' '||coalesce(d->>'guest_included_count','?')
         || ' · family=' || coalesce(d->>'family_allowed','?');
  sonuc := case when d->>'guest_policy'='included'
                 and (d->>'guest_included_count')::int=1
                 and (d->>'family_allowed')::boolean
                then '✓' else '✗ UYUŞMUYOR' end;
  return next;

  -- ELPL + LH ilanı: Star Alliance satırı ARTIK erişilebilir → aile YOK
  select a.id into v_av from availabilities a join users u on u.id=a.host_id
   where u.email='kural10@seed.loungelink.test'
   order by a.avail_date, a.time_from, a.id limit 1;
  d := public.lounge_access_decision(v_av, 'LH1302');
  senaryo := 'Star Gold host, LH ilanı: misafir var, karar bilinir';
  beklenen := 'included 1';
  gercek := coalesce(d->>'guest_policy','?')||' '||coalesce(d->>'guest_included_count','?');
  sonuc := case when d->>'guest_policy'='included'
                 and coalesce((d->>'guest_included_count')::int,0)>=1
                then '✓' else '✗ UYUŞMUYOR' end;
  return next;

  -- CLASSIC: ücretli giriş yolu, misafir yok
  select a.id into v_av from availabilities a join users u on u.id=a.host_id
   where u.email='kural11@seed.loungelink.test'
   order by a.avail_date, a.time_from, a.id limit 1;
  if v_av is not null then
    d := public.lounge_access_decision(v_av, null);
    senaryo := 'CLASSIC host: misafir alınamaz (ücretli kendi girişi notta)';
    beklenen := 'not_allowed';
    gercek := coalesce(d->>'guest_policy','?');
    sonuc := case when d->>'guest_policy'='not_allowed' then '✓' else '✗ UYUŞMUYOR' end;
    return next;
  end if;

  -- guide_lounges: tek aşırı yükleme kaldı mı? (PostgREST belirsizliği ölçümü)
  senaryo := 'guide_lounges TEK imza (PostgREST belirsizliği yok)';
  beklenen := '1';
  select count(*)::text into gercek from pg_proc
   where proname='guide_lounges' and pronamespace='public'::regnamespace;
  sonuc := case when gercek='1' then '✓' else '✗ UYUŞMUYOR' end;
  return next;
end $$;

-- ----------------------------------------------------------------------
-- home_connections   [etkin kaynak: 159_grants_home_flows_request_gate.sql]
-- ----------------------------------------------------------------------
create or replace function public.home_connections()
returns table (conn_id uuid, peer_id uuid, peer_name text, peer_photo text,
               channel_id uuid, last_msg_at timestamptz)
language sql stable security definer set search_path = public as $$
  select cr.id, 
         case when cr.from_id = auth.uid() then cr.to_id else cr.from_id end,
         p.name, p.photo_url, ch.id,
         (select max(m.created_at) from messages m where m.channel_id = ch.id)
    from connection_requests cr
    left join chat_channels ch on ch.connection_id = cr.id
    left join profiles p
      on p.user_id = case when cr.from_id = auth.uid() then cr.to_id else cr.from_id end
   where cr.status = 'accepted'
     and (cr.from_id = auth.uid() or cr.to_id = auth.uid())
     and (
       coalesce(cr.responded_at, cr.created_at) > now() - interval '24 hours'
       or exists (select 1 from messages m
                   where m.channel_id = ch.id
                     and m.created_at > now() - interval '24 hours')
     )
   order by coalesce((select max(m.created_at) from messages m where m.channel_id = ch.id),
                     cr.responded_at, cr.created_at) desc
   limit 10
$$;

