-- ----------------------------------------------------------------------
-- rule_matrix_test   [etkin kaynak: 177_official_table_reconciliation.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.rule_matrix_test(p_only_fail boolean default true)
returns table (vaka text, seviye text, beklenen text, gercek text, sonuc text)
language plpgsql stable security definer set search_path = public as $$
declare r record; v_pid uuid; v_venue uuid; v_carr text; j jsonb;
        v_g int; v_f boolean; v_p boolean; v_found boolean;
begin
  for r in select * from rule_test_cases
            order by program_code, card_tier nulls first, venue_scope, carrier_class loop
    select id into v_pid from lounge_programs where code = r.program_code and active;
    continue when v_pid is null;

    -- 🔴 177: kapsam içinde HERHANGİ bir salon değil, programın
    -- MİSAFİRLE kabul edildiği bölüm seçilir. Aynı havalimanında
    -- bölümler meşru olarak farklı davranır (Business vs M&S).
    select v.id into v_venue
      from lounge_venues v
      join airports a on a.code = v.airport_code
      left join lounge_venue_acceptance ac
        on ac.venue_id = v.id and ac.program_id = v_pid and ac.active
     where v.active
       and case r.venue_scope
             when 'abroad' then coalesce(a.country,'TR') not in ('TR','Türkiye','Turkiye','Turkey')
             else v.scope = r.venue_scope
                  and coalesce(a.country,'TR') in ('TR','Türkiye','Turkiye','Turkey')
           end
     order by (ac.id is not null and coalesce(ac.guest_policy,'') <> 'not_allowed') desc,
              (ac.id is not null) desc, v.id
     limit 1;
    continue when v_venue is null;

    v_carr := case r.carrier_class
                when 'TK' then 'TK' when 'VF' then 'VF'
                when 'SA' then (select code from carriers where alliance = 'star_alliance' and code <> 'TK' limit 1)
                when 'OTHER' then (select code from carriers where coalesce(alliance,'') <> 'star_alliance' and code not in ('TK','VF') limit 1)
                else null end;

    j := public.resolve_guest_rule(v_pid, v_venue, r.card_tier, v_carr, null);
    v_found := coalesce((j ->> 'found')::boolean, false);
    v_g := coalesce((j ->> 'guest_allowance')::int, -1);
    v_f := coalesce((j ->> 'family_allowed')::boolean, false);
    v_p := coalesce((j ->> 'paid_entry_allowed')::boolean, false);

    vaka := r.program_code || ' · ' || coalesce(r.card_tier,'(tier yok)')
            || ' · ' || r.venue_scope || ' · ' || r.carrier_class;
    seviye := r.level;

    if r.level = 'exact' then
      beklenen := 'misafir=' || r.exp_guests
                  || case when r.exp_family is not null then ' aile=' || r.exp_family else '' end
                  || case when coalesce(r.exp_paid,false) then ' ücretli=✓' else '' end;
      gercek := 'misafir=' || v_g || ' aile=' || v_f || case when v_p then ' ücretli=✓' else '' end;
      sonuc := case
        when not v_found then '✗ KURAL ÇÖZÜLMEDİ'
        when v_g <> r.exp_guests then '✗ MİSAFİR SAYISI'
        when r.exp_family is not null and v_f <> r.exp_family then '✗ AİLE HAKKI'
        when coalesce(r.exp_paid,false) and not v_p then '✗ ÜCRETLİ GİRİŞ KAPALI'
        else '✓' end;
    else
      beklenen := 'bir kural çözülmeli';
      gercek := case when v_found then 'çözüldü (misafir=' || v_g || ')' else 'program varsayılanına düştü' end;
      sonuc := case when v_found then '✓' else '✗ ÇÖZÜLMEDİ' end;
    end if;

    if (not p_only_fail) or sonuc not like '✓%' then return next; end if;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- rule_matrix_summary   [etkin kaynak: 167_rule_expectation_matrix.sql]
-- ----------------------------------------------------------------------
create or replace function public.rule_matrix_summary()
returns table (toplam int, gecen int, kalan int, exact_vaka int, defined_vaka int)
language sql stable security definer set search_path = public as $$
  select (select count(*)::int from rule_test_cases),
         (select count(*)::int from rule_test_cases)
           - (select count(*)::int from public.rule_matrix_test(true)),
         (select count(*)::int from public.rule_matrix_test(true)),
         (select count(*)::int from rule_test_cases where level = 'exact'),
         (select count(*)::int from rule_test_cases where level = 'defined');
$$;

-- ----------------------------------------------------------------------
-- rule_venue_test   [etkin kaynak: 174_venue_beats_program_rule.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.rule_venue_test(p_only_fail boolean default true)
returns table (havalimani text, salon text, program text, tier text, tasiyici text,
               motor text, kabul text, sonuc text)
language plpgsql stable security definer set search_path = public as $$
declare r record; v_pid uuid; v_carr text; j jsonb; v_g int; v_found boolean;
        v_pol text; v_venue_ozel boolean;
begin
  for r in select * from rule_venue_cases
            order by airport, venue_adi, program_code, card_tier nulls first, carrier_class loop
    select id into v_pid from lounge_programs where code = r.program_code;
    v_carr := case r.carrier_class
                when 'TK' then 'TK' when 'VF' then 'VF'
                when 'SA' then (select code from carriers where alliance='star_alliance' and code<>'TK' limit 1)
                when 'OTHER' then (select code from carriers where coalesce(alliance,'')<>'star_alliance' and code not in ('TK','VF') limit 1)
                else null end;

    j := public.resolve_guest_rule(v_pid, r.venue_id, r.card_tier, v_carr, null);
    v_found := coalesce((j ->> 'found')::boolean, false);
    v_g := coalesce((j ->> 'guest_allowance')::int, 0);
    v_venue_ozel := (j ->> 'venue_scope') is not null;
    select a.guest_policy into v_pol from lounge_venue_acceptance a
     where a.venue_id = r.venue_id and a.program_id = v_pid and a.active limit 1;

    havalimani := r.airport; salon := r.venue_adi; program := r.program_code;
    tier := coalesce(r.card_tier,'—'); tasiyici := r.carrier_class;
    motor := case when v_found then 'kural: ' else 'VARSAYILAN: ' end || v_g || ' misafir'
             || case when v_venue_ozel then ' (salona özel)' else '' end;
    kabul := coalesce(v_pol,'—');

    sonuc := case
      when not v_found then '✗ KURAL YOK (tahmin sunuluyor)'
      -- Yalnız SALONA ÖZEL kural kabul satırıyla çelişebilir.
      when v_venue_ozel and v_pol = 'not_allowed' and v_g > 0 then '✗ SALON KURALI ÇELİŞİYOR'
      when r.beklenti = 'engel' and v_venue_ozel and v_g > 0 then '✗ KABUL YOK AMA MİSAFİR VAR'
      else '✓' end;

    if (not p_only_fail) or sonuc not like '✓%' then return next; end if;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- rule_full_report   [etkin kaynak: 179_flow_test_skip_semantics.sql]
-- ⚠ Bu fonksiyon 4 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.rule_full_report()
returns table (bolum text, kalem text, toplam int, gecen int, kalan int, durum text)
language plpgsql security definer set search_path = public as $$
declare r record; v_top int; v_kalan int; v_atlanan int; v_ad text;
begin
  for r in
    select split_part(m.vaka, ' · ', 1) as prog,
           count(*)::int as toplam,
           count(*) filter (where m.sonuc like '✓%')::int as gecen
      from (select vaka, sonuc from public.rule_matrix_test(false)) m
     group by 1
  loop
    bolum := 'A · Beklenti matrisi (program × tier × kapsam × taşıyıcı)';
    kalem := r.prog; toplam := r.toplam; gecen := r.gecen; kalan := r.toplam - r.gecen;
    durum := case when kalan = 0 then '✓' else '✗ ' || kalan || ' uyuşmazlık' end;
    return next;
  end loop;

  select count(*)::int into v_top from rule_venue_cases;
  select count(*)::int into v_kalan from public.rule_venue_test(true);
  bolum := 'B · Salon bazlı tutarlılık (salon × program × tier × taşıyıcı)';
  kalem := 'tüm aktif salonlar'; toplam := v_top; kalan := v_kalan; gecen := v_top - v_kalan;
  durum := case when kalan = 0 then '✓' else '✗ ' || kalan || ' tutarsızlık' end;
  return next;

  for r in select kontrol, sinif, deger, esik, sonuc from public.rule_coverage_audit() loop
    bolum := 'C · Kapsam denetimi'; kalem := r.kontrol || ' [' || r.sinif || ']';
    toplam := r.deger; gecen := r.esik; kalan := greatest(0, r.deger - r.esik);
    durum := r.sonuc; return next;
  end loop;

  bolum := 'D · Karar zinciri senaryoları'; kalem := 'decision_chain_check';
  toplam := (select count(*)::int from public.decision_chain_check());
  kalan := (select count(*)::int from public.decision_chain_check() where sonuc not like '✓%');
  gecen := toplam - kalan; durum := case when kalan = 0 then '✓' else '✗' end; return next;

  bolum := 'D · Karışık senaryolar'; kalem := 'mixed_case_check';
  toplam := (select count(*)::int from public.mixed_case_check());
  kalan := (select count(*)::int from public.mixed_case_check() where sonuc like '✗%');
  gecen := toplam - kalan; durum := case when kalan = 0 then '✓' else '✗' end; return next;

  create temp table if not exists _akis on commit drop as
    select * from public.flow_gate_test();
  select count(*)::int into v_top from _akis;
  select count(*)::int into v_kalan from _akis where sonuc like '✗%';
  select count(*)::int into v_atlanan from _akis where sonuc like '⊘%' or sonuc = '—';
  select string_agg(senaryo || ' → ' || gercek, ' | ') into v_ad
    from _akis where sonuc like '✗%';

  bolum := 'E · Akış kapıları';
  kalem := case
    when v_kalan > 0 then 'flow_gate_test — ' || left(coalesce(v_ad,''), 90)
    when v_atlanan > 0 then 'flow_gate_test (' || v_atlanan || ' senaryo ortam nedeniyle atlandı)'
    else 'flow_gate_test' end;
  toplam := v_top; kalan := v_kalan; gecen := v_top - v_kalan;
  durum := case when v_kalan = 0 then '✓' else '✗' end;
  return next;
end $$;

-- ----------------------------------------------------------------------
-- flow_test_cleanup   [etkin kaynak: 175_flow_test_cleanup_fix.sql]
-- ----------------------------------------------------------------------
create or replace function public.flow_test_cleanup(p_ids uuid[])
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_ids is null or array_length(p_ids, 1) is null then return; end if;
  delete from messages m using chat_channels c
   where m.channel_id = c.id and c.request_id = any(p_ids);
  delete from chat_channels where request_id = any(p_ids);
  delete from ratings r using sessions s
   where r.session_id = s.id and s.request_id = any(p_ids);
  delete from sessions where request_id = any(p_ids);
  delete from requests where id = any(p_ids);
exception when others then
  -- Temizlik testi ASLA düşürmemeli: eksik silinen kayıt bir sonraki
  -- koşuda görülür, ama çöken bir test hiçbir şey ölçmez.
  null;
end $$;

-- ----------------------------------------------------------------------
-- rebuild_rule_test_cases   [etkin kaynak: 178_expectations_single_source.sql]
-- ----------------------------------------------------------------------
create or replace function public.rebuild_rule_test_cases()
returns int language plpgsql security definer set search_path = public as $$
declare
  v_scopes text[] := array['domestic','international','abroad'];
  v_carr   text[] := array['TK','VF','SA','OTHER','UNKNOWN'];
  s text; c text; t text; n int := 0;
  v_lvl text; v_g int; v_f boolean; v_p boolean; v_src text;
begin
  delete from rule_test_cases;

  -- ============ TK MILES&SMILES ============
  -- Kaynak: THY Tablo-1 (iç hat), Tablo-2 (dış hat), Tablo-5 (yurt dışı).
  --   TK taşıyıcı → ELPL/Elite/M&S EC: "Aile veya bir misafir"
  --                 SAG/PLM/CORP     : "Bir misafir"
  --                 CLPL / M&S U.S. Kredi Kartı : "Yok"
  --   Star Alliance taşıyıcı → hepsi "Bir misafir" (aile YOK)
  --   Yurt dışı anlaşmalı (Tablo-5) → aile YOK, tek misafir
  --   AJet uçuşu (VF) → hak AJET_MS tablosundan gelir, burada iddia yok
  foreach s in array v_scopes loop
  foreach c in array v_carr loop
    foreach t in array array['ELPL','ELITE','CLPL','CLASSIC','CORP','MS_EC','SAG','PLM','MS_US_CC'] loop
      v_lvl := 'defined'; v_g := null; v_f := null; v_p := null;
      v_src := 'THY Tablo-1/2/5';

      if t in ('CLPL','CLASSIC') then
        v_lvl := 'exact'; v_g := 0; v_f := false;
        v_src := 'Tablo-1/2: "Yok" — hiçbir kapsamda misafir hakkı yok';

      elsif t = 'MS_US_CC' then
        v_lvl := 'exact'; v_g := 0; v_f := false;
        v_src := 'Tablo-1/2: M&S U.S. Kredi Kartı → "Yok"';

      elsif c = 'VF' then
        v_lvl := 'defined';
        v_src := 'AJet seferinde hak AJET_MS tablosundan gelir';

      elsif c = 'UNKNOWN' then
        v_lvl := 'defined';
        v_src := '163 ilkesi: taşıyıcı bilinmiyorsa en kısıtlayıcı kural';

      elsif t in ('ELPL','ELITE','MS_EC') then
        if s = 'abroad' then
          v_lvl := 'exact'; v_g := 1; v_f := false;
          v_src := 'Tablo-5: yurt dışı anlaşmalı salonda aile hakkı yok';
        elsif s = 'international' and c in ('SA','OTHER') and t = 'MS_EC' then
          -- Tablo-2 "aile yok" der; Tablo-4 IST M&S bölümü için istisna
          -- tanır. İkisi çelişmez, biri diğerinin istisnasıdır — kesin
          -- cevap SALON düzeyinde verilir (B testi).
          v_lvl := 'defined';
          v_src := 'Tablo-2 kapsam kuralı + Tablo-4 M&S bölümü istisnası';
        elsif c = 'TK' then
          v_lvl := 'exact'; v_g := 1; v_f := true;
          v_src := 'Tablo-1/2 (TK): "Aile veya bir misafir"';
        else
          v_lvl := 'exact'; v_g := 1; v_f := false;
          v_src := 'Tablo-2 (Star Alliance): "Bir misafir"';
        end if;

      elsif t in ('SAG','PLM','CORP') then
        if s = 'abroad' then v_lvl := 'defined';
        else
          v_lvl := 'exact'; v_g := 1; v_f := false;
          v_src := 'Tablo-1/2: "Bir misafir"';
        end if;
      end if;

      insert into rule_test_cases
        (program_code, card_tier, venue_scope, carrier_class, level,
         exp_guests, exp_family, kaynak, needs_review)
      values ('TK_MS', t, s, c, v_lvl, v_g, v_f, v_src, false)
      on conflict do nothing;
      n := n + 1;
    end loop;
  end loop;
  end loop;

  -- ============ AJET MILES&SMILES ============
  foreach s in array v_scopes loop
  foreach c in array v_carr loop
    foreach t in array array['ELPL','ELITE','CLPL','CLASSIC','MS_EC'] loop
      if t in ('CLPL','CLASSIC') then
        insert into rule_test_cases
          (program_code, card_tier, venue_scope, carrier_class, level,
           exp_guests, exp_family, kaynak, needs_review)
        values ('AJET_MS', t, s, c, 'exact', 0, false, 'AJet kart matrisi', false)
        on conflict do nothing;
      else
        insert into rule_test_cases
          (program_code, card_tier, venue_scope, carrier_class, level, kaynak, needs_review)
        values ('AJET_MS', t, s, c, 'defined', 'AJet kart matrisi', false)
        on conflict do nothing;
      end if;
      n := n + 1;
    end loop;
  end loop;
  end loop;

  -- ============ PRIORITY PASS · DRAGONPASS ============
  -- Hiçbir planda misafir ücretsiz dahil değil; kapıda ücretli girer.
  foreach s in array v_scopes loop
  foreach c in array v_carr loop
    foreach t in array array['PP_STANDARD','PP_STANDARD_PLUS','PP_PRESTIGE'] loop
      insert into rule_test_cases
        (program_code, card_tier, venue_scope, carrier_class, level,
         exp_guests, exp_family, exp_paid, kaynak, needs_review)
      values ('PRIORITY_PASS', t, s, c, 'exact', 0, false, true,
              'PP plan sayfası 2026: misafir ücretli', false)
      on conflict do nothing;
      n := n + 1;
    end loop;
    foreach t in array array['DP_CLASSIC','DP_PREFERENTIAL'] loop
      insert into rule_test_cases
        (program_code, card_tier, venue_scope, carrier_class, level,
         exp_guests, exp_family, exp_paid, kaynak, needs_review)
      values ('DRAGONPASS', t, s, c, 'exact', 0, false, true,
              'DP şartları: ek üye veya misafir ücretli, aynı uçuş şartı', false)
      on conflict do nothing;
      n := n + 1;
    end loop;
  end loop;
  end loop;

  -- ============ BUSINESS BİLETİ ============
  foreach s in array v_scopes loop
  foreach c in array v_carr loop
    insert into rule_test_cases
      (program_code, card_tier, venue_scope, carrier_class, level,
       exp_guests, exp_family, kaynak, needs_review)
    values ('BUSINESS_TICKET', null, s, c, 'exact', 0, false,
            'Tablo-4: Business bölümünde misafir/aile hakkı yok', false)
    on conflict do nothing;
    n := n + 1;
  end loop;
  end loop;

  -- ============ OPERATÖR SALONLARI ============
  foreach s in array v_scopes loop
  foreach c in array v_carr loop
    foreach t in array array['PRIMECLASS','IGA_LOUNGE','PLAZA_PREMIUM','PGS_PAID'] loop
      insert into rule_test_cases
        (program_code, card_tier, venue_scope, carrier_class, level,
         exp_guests, exp_family, exp_paid, kaynak, needs_review)
      values (t, null, s, c, 'exact', 0, false, true,
              'Operatör kapı tarifesi: misafir de aynı tarifeden girer', false)
      on conflict do nothing;
      n := n + 1;
    end loop;
  end loop;
  end loop;

  -- ============ BANKA / KART AĞLARI ============
  foreach s in array v_scopes loop
  foreach c in array v_carr loop
    foreach t in array array['AMEX_GLOBAL','BANK_CARD','LOUNGEKEY','DREAMFOLKS','EVERYLOUNGE','ONPASS','ST_PASS','STAR_GOLD'] loop
      insert into rule_test_cases
        (program_code, card_tier, venue_scope, carrier_class, level, kaynak, needs_review)
      values (t, null, s, c, 'defined',
              'Koşullar kartı verene göre değişir; yalnız kural çözülmeli', false)
      on conflict do nothing;
      n := n + 1;
    end loop;
  end loop;
  end loop;

  return (select count(*)::int from rule_test_cases);
end $$;

-- ----------------------------------------------------------------------
-- flow_env_block   [etkin kaynak: 180_flow_test_future_availability.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.flow_env_block(p_err text)
returns boolean language sql immutable as $$
  select p_err ilike any (array[
    '%insufficient_credit%',
    '%already_requested%',
    '%duplicate key%',
    '%rate_limited%',
    '%not_verified%',
    '%no_matching_trip%',
    '%own_availability%',
    '%self_request%',
    -- 180: ilan geçmişte kalmışsa test konusuna ulaşamaz. Motorun
    -- süre kapısı doğru çalışmıştır; senaryo ölçülememiştir.
    '%availability_expired%',
    '%availability_not_found%',
    '%not_active%'
  ]);
$$;

