create or replace function public.discover_availabilities_base('
       || 'p_airport text default null, p_sector text default null, '
       || 'p_flight text default null, p_date date default null) returns '
       || v_res || ' language plpgsql stable security definer set search_path = public as $BODY$'
       || v_src || '$BODY$';
  raise notice '182: orijinal gövde _base olarak taşındı';
end $$;

-- ----------------------------------------------------------------------
-- lounges_for_airport   [etkin kaynak: 190_salon_tekillestirme_ve_bolum.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.lounges_for_airport(p_airport text)
returns table (
  id uuid, name text, terminal text, access_types text[],
  scope text, accepts_guests boolean, note text,
  section text, display_name text
) language plpgsql stable security definer set search_path = public as $$
declare v_ap text := upper(btrim(coalesce(p_airport, '')));
begin
  return query
  with c as (
    select l.id, l.name, l.terminal, l.access_types,
           v.scope, v.section, v.id as vid,
           exists (select 1 from lounge_venue_acceptance a
                    where a.venue_id = v.id and a.active and a.accepted
                      and coalesce(a.guest_policy,'') <> 'not_allowed') as ag
      from lounges l
      join lounge_venues v on v.id = l.venue_id and v.active
                          and coalesce(v.venue_kind,'lounge') = 'lounge'
     where l.active and upper(btrim(l.airport_code)) = v_ap
  ), n as (
    select c.*, count(*) over (partition by lower(c.name)) as ayni_ad from c
  )
  select n.id, n.name, n.terminal, n.access_types, n.scope, n.ag, null::text,
         n.section,
         -- Aynı ad birden çok kez geçiyorsa kapsam/bölüm ekiyle ayır.
         case when n.ayni_ad > 1 then
                n.name || ' — ' ||
                case n.scope when 'domestic' then 'İç Hat'
                             when 'international' then 'Dış Hat'
                             else 'Tüm Terminaller' end ||
                case when n.section = 'business' then ' (Business)'
                     when n.section = 'miles_smiles' then ' (Miles&Smiles)'
                     else '' end
              else n.name end
    from n
   -- 🔴 coalesce ŞART: NULL karşılaştırma DESC'te en başa çıkar (145).
   order by coalesce(n.scope = 'domestic', false) desc, n.name;

  if not found then
    -- YEDEK YOL: katalog o havalimanı için boşsa doğrudan venue'dan üret.
    return query
    select v.id, v.name, v.terminal, null::text[], v.scope,
           exists (select 1 from lounge_venue_acceptance a
                    where a.venue_id = v.id and a.active and a.accepted
                      and coalesce(a.guest_policy,'') <> 'not_allowed'),
           null::text, v.section, v.name
      from lounge_venues v
     where v.active and upper(btrim(v.airport_code)) = v_ap
       and coalesce(v.venue_kind, 'lounge') = 'lounge'
     order by coalesce(v.scope = 'domestic', false) desc, v.name;
  end if;
end $$;

-- ----------------------------------------------------------------------
-- device_flow_check   [etkin kaynak: 185_device_flow_proofs.sql]
-- ----------------------------------------------------------------------
create or replace function public.device_flow_check()
returns table (akis text, olcum text, sonuc text)
language plpgsql security definer set search_path = public as $$
declare r record; n int; v_bos int := 0; v_top int := 0;
        v_uid uuid; v_other uuid; v_req uuid; v_gorunen int;
        v_badge int := 0; v_block int := 0; v_carrier int := 0; v_list int := 0;
begin
  -- ---------- 1) SALON LİSTELERİ ----------
  for r in select distinct upper(btrim(airport_code)) ap from lounges where active loop
    v_top := v_top + 1;
    if (select count(*) from public.lounges_for_airport(r.ap)) = 0 then
      v_bos := v_bos + 1;
    end if;
  end loop;
  akis := '1 · Salon listeleri';
  olcum := v_top || ' havalimanı, ' || v_bos || ' tanesi boş';
  sonuc := case when v_top = 0 then '✗ KATALOG BOŞ'
                when v_bos > 0 then '✗ BOŞ LİSTE VAR'
                else '✓' end;
  return next;

  -- Kod normalize gerçekten çalışıyor mu (app 'ist' gönderirse)
  akis := '1b · Havalimanı kodu normalize';
  select count(*) into n from public.lounges_for_airport('ist');
  olcum := 'küçük harfle IST → ' || n || ' salon';
  sonuc := case when n > 0 then '✓' else '✗ NORMALİZE ÇALIŞMIYOR' end;
  return next;

  -- ---------- 2) KEŞFET KARARI ----------
  select id into v_uid from users where email like 'kmisafir1%' limit 1;
  if v_uid is null then
    akis := '2 · Keşfet kararı'; olcum := 'seed misafiri yok'; sonuc := '—'; return next;
  else
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_uid, 'role', 'authenticated')::text, true);
    for r in select * from public.discover_availabilities(null, null, null, null) loop
      v_list := v_list + 1;
      if r.guest_policy is not null and r.guest_policy <> 'unknown' then v_badge := v_badge + 1; end if;
      if r.blocks_request then v_block := v_block + 1; end if;
      if r.carrier_note is not null then v_carrier := v_carrier + 1; end if;
    end loop;

    akis := '2 · Keşfet rozet verisi';
    olcum := v_list || ' ilan, ' || v_badge || ' tanesinde karar var';
    sonuc := case when v_list = 0 then '—'
                  when v_badge = 0 then '✗ ROZET VERİSİ GELMİYOR'
                  else '✓' end;
    return next;

    akis := '2b · Kapalı ilanda buton kilidi';
    olcum := v_block || ' ilan istek almaya kapalı';
    sonuc := case when v_list = 0 then '—' else '✓' end;
    return next;

    akis := '2c · Taşıyıcı uyarısı (AJet/THY)';
    olcum := v_carrier || ' ilanda uyarı üretildi';
    sonuc := '✓';
    return next;
  end if;

  -- ---------- 3) BAĞLANTI İSTEĞİ ALICIDA GÖRÜNÜYOR MU ----------
  select id into v_other from users
   where id <> v_uid and coalesce(is_staff,false) = false
     and email not like '%@vitrin.loungelink.test'
   limit 1;

  if v_uid is null or v_other is null then
    akis := '3 · Bağlantı isteği'; olcum := 'iki hesap bulunamadı'; sonuc := '—'; return next;
  else
    delete from connection_requests
     where from_id = v_uid and to_id = v_other and status = 'pending';

    insert into connection_requests (from_id, to_id, status, intent)
    values (v_uid, v_other, 'pending', 'lounge')
    returning id into v_req;

    -- ALICININ gözünden oku: app tam bu sorguyu yapıyor.
    select count(*) into v_gorunen from connection_requests
     where to_id = v_other and status = 'pending';

    akis := '3 · Bağlantı isteği alıcıda';
    olcum := 'alıcının bekleyen istek sayısı: ' || v_gorunen;
    sonuc := case when v_gorunen > 0 then '✓' else '✗ ALICI GÖRMÜYOR' end;
    return next;

    -- Alıcı profili okunabiliyor mu (liste kartı için şart)
    select count(*) into n from profiles where user_id = v_uid;
    akis := '3b · Gönderenin profili okunabiliyor';
    olcum := n || ' profil satırı';
    sonuc := case when n > 0 then '✓' else '✗ PROFİL YOK — kart çizilemez' end;
    return next;

    delete from connection_requests where id = v_req;
  end if;

  perform set_config('request.jwt.claims', '{}', true);
end $$;

-- ----------------------------------------------------------------------
-- my_sent_requests   [etkin kaynak: 187_kanitlanmis_kusurlar.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.my_sent_requests()
returns table (
  id uuid, status text, created_at timestamptz, responded_at timestamptz,
  host_id uuid, host_name text, host_badge text,
  avail_id uuid, airport_code text, lounge_name text,
  avail_date date, time_from time, time_to time,
  flight_number text, carrier text, slots int, filled int,
  guest_policy text, decision_note text
)
language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  return query
  with mine as (
    select r.id as rid, r.status, r.created_at, r.responded_at,
           r.host_id, r.avail_id,
           -- 🔴 187: MİSAFİRİN kendi uçuşu. Eskiden a.flight_number
           -- (host'un uçuşu) geçiliyordu ve taşıyıcı kontrolü daima
           -- geçiyordu. 142'nin request_precheck'i ile aynı kaynak.
           (select v.flight_number from visits v
             where v.user_id = v_uid
               and v.airport_code = a2.airport_code
               and v.visit_date = a2.avail_date
               and coalesce(v.flight_number, '') <> ''
             order by v.created_at desc limit 1) as my_flight
      from requests r
      join availabilities a2 on a2.id = r.avail_id
     where r.guest_id = v_uid and r.status in ('pending', 'accepted')
  )
  select m.rid, m.status::text, m.created_at, m.responded_at,
         m.host_id, coalesce(p.name, 'Host'), ts.badge,
         a.id, a.airport_code::text, a.lounge_name, a.avail_date,
         a.time_from, a.time_to, a.flight_number, a.carrier,
         a.slots::int, a.filled::int,     -- 🔴 smallint -> int
         coalesce(public.lounge_access_decision(a.id, m.my_flight) ->> 'guest_policy', 'unknown'),
         nullif(public.lounge_access_decision(a.id, m.my_flight) ->> 'headline', '')
    from mine m
    join availabilities a on a.id = m.avail_id
    left join profiles p on p.user_id = m.host_id
    left join trust_scores ts on ts.user_id = m.host_id
   order by coalesce(m.status = 'accepted', false) desc, a.avail_date, a.time_from;
end $$;

-- ----------------------------------------------------------------------
-- rpc_smoke_test   [etkin kaynak: 193_kart_etiketi_ve_kabin_yazma.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.rpc_smoke_test() returns '
       || pg_get_function_result(v_oid)
       || ' language plpgsql volatile security definer set search_path = public as $BODY$'
       || v_new || '$BODY$';
  raise notice '193: my_access_cards canlilik testine eklendi';
end $$;

-- ----------------------------------------------------------------------
-- rule_full_report_v2   [etkin kaynak: 187_kanitlanmis_kusurlar.sql]
-- ----------------------------------------------------------------------
create or replace function public.rule_full_report_v2()
returns table (bolum text, kalem text, toplam int, gecen int, kalan int, durum text)
language plpgsql volatile security definer set search_path = public as $$
declare v_top int; v_kalan int;
begin
  return query select r.bolum, r.kalem, r.toplam, r.gecen, r.kalan, r.durum
                 from public.rule_full_report() r;

  -- 187-smoke: çağrılabilen RPC'ler GERÇEKTEN çalışıyor mu?
  -- Bu satır 186'nın iki ölü RPC'sini yakalardı.
  select count(*)::int, count(*) filter (where s.sonuc like '✗%')::int
    into v_top, v_kalan
    from public.rpc_smoke_test() s;
  bolum := 'F · RPC canlılık'; kalem := 'rpc_smoke_test';
  toplam := v_top; kalan := v_kalan; gecen := v_top - v_kalan;
  durum := case when v_kalan = 0 then '✓' else '✗' end;
  return next;
end $$;

-- ----------------------------------------------------------------------
-- access_options_for_user   [etkin kaynak: 189_coklu_hak_ve_kaynak_hizalama.sql]
-- ----------------------------------------------------------------------
create or replace function public.access_options_for_user(
  p_user_id  uuid,
  p_venue_id uuid,
  p_carrier  text default null,
  p_flight   text default null
) returns table (
  program_code   text,
  program_name   text,
  tier           text,
  accepted       boolean,
  guest_allowance int,
  family_allowed boolean,
  guest_policy   text,
  fee_payer      text,
  guest_fee      text,
  confidence     text,
  headline       text,
  note           text,
  bank_dependent boolean,
  rank_no        int
) language plpgsql stable security definer set search_path = public as $$
declare r record; g jsonb; a lounge_venue_acceptance%rowtype; v_i int := 0;
begin
  for r in
    select he.program_id, he.tier, he.verified, he.carrier,
           p.code, p.name, p.entitlement_model, p.fee_payer
      from host_entitlements he
      join lounge_programs p on p.id = he.program_id
     where he.user_id = p_user_id and p.active
     order by he.verified desc, p.code
  loop
    -- Salon bu programı kabul ediyor mu?
    select * into a from lounge_venue_acceptance x
     where x.venue_id = p_venue_id and x.program_id = r.program_id and x.active
     order by x.is_placeholder, x.checked_at desc nulls last
     limit 1;

    program_code := r.code;
    program_name := r.name;
    tier         := r.tier;
    accepted     := coalesce(a.accepted, false);
    fee_payer    := r.fee_payer;
    -- 🔴 BANKAYA BAĞLI PROGRAMLAR: Priority Pass md.4/md.11, DragonPass
    -- 5.4 — ziyaret sayısını, ücreti ve misafir hakkını KARTI VEREN
    -- BANKA belirler. Bu programlarda motorun verebileceği en dürüst
    -- cevap "bankana göre değişir".
    -- İLK YAZIMDA bu satır yalnız KABUL EDİLEN dalda vardı; kabul
    -- etmeyen dalda false kalıyordu ve ölçümde Priority Pass
    -- "bank_dependent: false" göründü. Kullanıcı bundan "kartım
    -- bankaya bağlı değil" sonucunu çıkarırdı. İki dalda da doğru olmalı.
    bank_dependent := r.entitlement_model in ('card_network', 'bank_card')
                      or r.code in ('PRIORITY_PASS', 'DRAGONPASS', 'LOUNGEKEY',
                                    'DREAMFOLKS', 'EVERYLOUNGE', 'ONPASS',
                                    'AMEX_GLOBAL', 'BANK_CARD');

    if not coalesce(a.accepted, false) then
      -- NEGATİF CASE: kabul etmiyor. Listeden ATMIYORUZ — kullanıcı
      -- "bu kartım neden işe yaramadı" sorusunun cevabını görmeli.
      guest_allowance := 0; family_allowed := false;
      guest_policy := 'not_accepted'; guest_fee := null;
      confidence := 'verified';
      headline := 'Bu salon bu programı kabul etmiyor';
      note := null;
      v_i := v_i + 1; rank_no := 1000 + v_i;
      return next; continue;
    end if;

    g := public.resolve_guest_rule(r.program_id, p_venue_id, r.tier,
                                   coalesce(p_carrier, r.carrier), null);

    guest_allowance := coalesce((g ->> 'guest_allowance')::int, 0);
    family_allowed  := coalesce((g ->> 'family_allowed')::boolean, false);
    guest_policy    := coalesce(a.guest_policy, g ->> 'guest_policy', 'unknown');
    guest_fee       := g ->> 'guest_fee';
    confidence      := case when a.is_placeholder then 'unknown'
                            when a.checked_at is not null then 'verified'
                            else 'assumed' end;
    headline        := g ->> 'headline';
    note            := g ->> 'note';
    v_i := v_i + 1; rank_no := v_i;
    return next;
  end loop;
end $$;

-- ----------------------------------------------------------------------
-- best_access_for_user   [etkin kaynak: 189_coklu_hak_ve_kaynak_hizalama.sql]
-- ----------------------------------------------------------------------
create or replace function public.best_access_for_user(
  p_user_id  uuid,
  p_venue_id uuid,
  p_carrier  text default null,
  p_flight   text default null
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_best record; v_all jsonb; v_n int; v_kabul int;
begin
  select count(*), count(*) filter (where o.accepted)
    into v_n, v_kabul
    from public.access_options_for_user(p_user_id, p_venue_id, p_carrier, p_flight) o;

  if v_n = 0 then
    return jsonb_build_object(
      'found', false, 'options', '[]'::jsonb,
      'headline', 'Henüz bir lounge hakkı eklemedin',
      'note', 'Kartını ya da statünü ekle — hangi salona girebileceğini söyleyelim.');
  end if;

  select * into v_best
    from public.access_options_for_user(p_user_id, p_venue_id, p_carrier, p_flight) o
   where o.accepted
   order by
     -- 🔴 SIRALAMA GEREKÇESİ (yukarıdaki ilke listesiyle birebir):
     -- 🔴 coalesce ŞART: NULL bir karşılaştırma DESC sıralamada EN BAŞA
     -- çıkar (145'in dersi). guest_policy ve confidence NULL olabilir;
     -- coalesce'siz yazınca "bilinmeyen" kayıt "en iyi hak" seçilirdi.
     -- sql_lint bunu kendi dosyamda yakaladı.
     coalesce(o.guest_allowance, 0) desc,                            -- 2
     coalesce(o.guest_policy = 'included', false) desc,              -- 3
     coalesce(o.family_allowed, false) desc,                         -- 4
     coalesce(o.confidence = 'verified', false) desc,                -- 5
     o.rank_no                                                       -- 6
   limit 1;

  select jsonb_agg(jsonb_build_object(
           'program', o.program_code, 'name', o.program_name, 'tier', o.tier,
           'accepted', o.accepted, 'guest_allowance', o.guest_allowance,
           'guest_policy', o.guest_policy, 'fee_payer', o.fee_payer,
           'guest_fee', o.guest_fee, 'confidence', o.confidence,
           'headline', o.headline, 'bank_dependent', o.bank_dependent)
           order by o.rank_no)
    into v_all
    from public.access_options_for_user(p_user_id, p_venue_id, p_carrier, p_flight) o;

  if v_best is null then
    -- NEGATİF CASE: hakkı var ama HİÇBİRİ bu salonu açmıyor.
    -- "Giremezsin" demek yerine ne GEREKTİĞİNİ söylüyoruz (marka §2).
    return jsonb_build_object(
      'found', false, 'options', coalesce(v_all, '[]'::jsonb),
      'total_rights', v_n, 'accepted_rights', 0,
      'headline', 'Bu salon eklediğin hakların hiçbirini kabul etmiyor',
      'note', 'Aynı havalimanındaki başka salonlara bakalım — bir tanesi seni alıyor olabilir.');
  end if;

  return jsonb_build_object(
    'found', true,
    'program', v_best.program_code,
    'program_name', v_best.program_name,
    'tier', v_best.tier,
    'guest_allowance', v_best.guest_allowance,
    'family_allowed', v_best.family_allowed,
    'guest_policy', v_best.guest_policy,
    'fee_payer', v_best.fee_payer,
    'guest_fee', v_best.guest_fee,
    'confidence', v_best.confidence,
    'bank_dependent', v_best.bank_dependent,
    'headline', v_best.headline,
    'total_rights', v_n,
    'accepted_rights', v_kabul,
    -- Çoklu hak varsa kullanıcıya SÖYLE. Sessizce en iyisini seçip
    -- geçmek, kapıda yanlış kartı uzatmasına yol açar.
    'multi_note', case when v_kabul > 1
      then 'Bu salonda ' || v_kabul || ' hakkın geçerli. En çok misafir hakkı veren: '
           || v_best.program_name || '. Kapıda bunu uzat.'
      else null end,
    'options', coalesce(v_all, '[]'::jsonb));
end $$;

-- ----------------------------------------------------------------------
-- carrier_mismatch_note   [etkin kaynak: 189_coklu_hak_ve_kaynak_hizalama.sql]
-- ----------------------------------------------------------------------
create or replace function public.carrier_mismatch_note(
  p_host_carrier  text,
  p_guest_carrier text
) returns jsonb language plpgsql immutable set search_path = public as $$
declare h text := upper(nullif(btrim(coalesce(p_host_carrier, '')), ''));
        g text := upper(nullif(btrim(coalesce(p_guest_carrier, '')), ''));
begin
  -- Bilinmiyorsa YARGI VERME. 163'ün ilkesi: bilmemek cömert davranmak
  -- için gerekçe değil — ama uydurmak için de gerekçe değil.
  if h is null or g is null then
    return jsonb_build_object('state', 'unknown', 'blocks', false,
      'title', 'Uçuş numaranı ekle, kesin cevabı verelim',
      'body', 'Misafirin host ile aynı havayolunda uçuyor olması gerekebilir. '
              'Uçuş numaranı yazarsan bunu senin yerine kontrol ederiz.');
  end if;

  if h = g then
    return jsonb_build_object('state', 'match', 'blocks', false,
      'title', 'Aynı havayolu — bu şart tamam',
      'body', 'İkiniz de ' || h || ' ile uçuyorsunuz.');
  end if;

  -- THY ↔ AJet: aynı statü programı ama AYRI taşıyıcı. En sık
  -- karıştırılan durum bu; adıyla söylüyoruz.
  if (h in ('TK') and g in ('VF', 'AJ')) or (h in ('VF', 'AJ') and g in ('TK')) then
    return jsonb_build_object('state', 'tk_ajet', 'blocks', true,
      'title', 'Biletler farklı havayolunda',
      'body', 'Senin biletin ' || case when g = 'TK' then 'Turkish Airlines'
                                       else 'AJet' end ||
              ', ilan sahibininki ' || case when h = 'TK' then 'Turkish Airlines'
                                            else 'AJet' end ||
              '. Miles&Smiles statüsü ikisini de kapsıyor ama salon kuralı '
              'misafirin host ile AYNI havayolunda uçmasını istiyor — bu '
              'ilandan kabul alamazsın.',
      'fix', 'Aynı havayolunda uçan bir ilan ara — keşifte havayolu filtresi var.');
  end if;

  return jsonb_build_object('state', 'mismatch', 'blocks', true,
    'title', 'Biletler farklı havayolunda',
    'body', 'Senin biletin ' || g || ', ilan sahibininki ' || h ||
            '. Bu salon misafirin host ile aynı havayolunda uçmasını istiyor.',
    'fix', 'Aynı havayolunda uçan bir ilan ara.');
end $$;

-- ----------------------------------------------------------------------
-- brand_key   [etkin kaynak: 190_salon_tekillestirme_ve_bolum.sql]
-- ----------------------------------------------------------------------
create or replace function public.brand_key(p_operator text, p_name text)
returns text language sql immutable set search_path = public as $$
  select case
    when coalesce(p_operator,'') ~* 'turkish|thy'      then 'thy'
    when coalesce(p_operator,'') ~* 'iga'              then 'iga'
    when coalesce(p_operator,'') ~* 'primeclass'       then 'primeclass'
    when coalesce(p_operator,'') ~* 'plaza'            then 'plaza'
    when coalesce(p_operator,'') <> ''                 then lower(btrim(p_operator))
    when coalesce(p_name,'')     ~* 'turkish|thy'      then 'thy'
    when coalesce(p_name,'')     ~* 'iga'              then 'iga'
    when coalesce(p_name,'')     ~* 'primeclass'       then 'primeclass'
    when coalesce(p_name,'')     ~* 'plaza'            then 'plaza'
    else lower(regexp_replace(coalesce(p_name,''), '[^a-zA-Z0-9]+', '', 'g'))
  end
$$;

-- ----------------------------------------------------------------------
-- terminal_key   [etkin kaynak: 190_salon_tekillestirme_ve_bolum.sql]
-- ----------------------------------------------------------------------
create or replace function public.terminal_key(p_terminal text)
returns text language sql immutable set search_path = public as $$
  select coalesce(
    (regexp_match(lower(coalesce(p_terminal,'')), '(concourse\s*[a-z0-9]+)'))[1],
    (regexp_match(lower(coalesce(p_terminal,'')), '\b(t[0-9])\b'))[1],
    '')
$$;

-- ----------------------------------------------------------------------
-- bank_override_for   [etkin kaynak: 191_kaynak_celiskileri_ve_bosluklar.sql]
-- ----------------------------------------------------------------------
create or replace function public.bank_override_for(
  p_program_id uuid, p_bank_code text, p_card_product text default null
) returns jsonb language sql stable security definer set search_path = public as $$
  select case when b.id is null then null else jsonb_build_object(
    'bank', b.bank_name, 'card_product', b.card_product,
    'member_free_visits', b.member_free_visits,
    'guest_included_count', b.guest_included_count,
    'guest_fee', b.guest_fee, 'fee_payer', b.fee_payer,
    'source_url', b.source_url, 'checked_at', b.checked_at) end
    from bank_program_overrides b
   where b.active and b.program_id = p_program_id
     and upper(btrim(b.bank_code)) = upper(btrim(coalesce(p_bank_code,'')))
     and (b.card_product is null
          or upper(btrim(b.card_product)) = upper(btrim(coalesce(p_card_product,''))))
   order by (b.card_product is not null) desc, b.checked_at desc nulls last
   limit 1
$$;

-- ----------------------------------------------------------------------
-- cabin_rule_reach   [etkin kaynak: 191_kaynak_celiskileri_ve_bosluklar.sql]
-- ----------------------------------------------------------------------
create or replace function public.cabin_rule_reach()
returns table (kural_sayisi int, erisilebilir int, not_metni text)
language plpgsql stable security definer set search_path = public as $$
declare v_top int; v_ok int;
begin
  select count(*) into v_top from lounge_guest_rules where cabin_class is not null;
  select count(*) into v_ok from availabilities where cabin_class is not null;
  kural_sayisi := v_top;
  erisilebilir := v_ok;
  not_metni := case
    when v_top = 0 then 'Kabin bazlı kural yok.'
    when v_ok = 0 then 'Kabin kuralları TANIMLI ama hiçbir ilanda kabin girilmemiş — '
                       'kurallar henüz devrede değil. App ilan formuna kabin alanı ekleyince açılır.'
    else 'Kabin kuralları devrede: ' || v_ok || ' ilanda kabin bilgisi var.' end;
  return next;
end $$;

-- ----------------------------------------------------------------------
-- save_host_card   [etkin kaynak: 193_kart_etiketi_ve_kabin_yazma.sql]
-- ----------------------------------------------------------------------
create or replace function public.save_host_card(
  p_program_code   text,
  p_tier           text default null,
  p_card_label     text default null,
  p_guest_capacity smallint default null,
  p_bank_code      text default null,
  p_card_product   text default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid  uuid := auth.uid();
  v_prog uuid;
  v_id   uuid;
  v_n    int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select id into v_prog from lounge_programs
   where active and upper(btrim(code)) = upper(btrim(coalesce(p_program_code,'')));
  if v_prog is null then raise exception 'unknown_program'; end if;

  -- Kapasite makul olmalı; kural motoru zaten üst sınırı belirler ama
  -- saçma bir sayı veriye girmemeli.
  if p_guest_capacity is not null and (p_guest_capacity < 0 or p_guest_capacity > 6) then
    raise exception 'invalid_guest_capacity';
  end if;

  -- 🔴 Aynı kişide sınırsız kart olmamalı: beyan bir güven kaynağı,
  -- sınırsız beyan güveni değersizleştirir. Program başına 4 kart.
  select count(*) into v_n from host_entitlements
   where user_id = v_uid and program_id = v_prog
     and coalesce(card_label,'') is distinct from coalesce(nullif(btrim(p_card_label),''),'');
  if v_n >= 4 then raise exception 'too_many_cards'; end if;

  insert into host_entitlements
    (user_id, program_id, tier, card_label, guest_capacity,
     bank_code, card_product, origin, self_reported_at)
  values
    (v_uid, v_prog, nullif(btrim(coalesce(p_tier,'')),''),
     nullif(btrim(coalesce(p_card_label,'')),''),
     p_guest_capacity,
     nullif(btrim(upper(coalesce(p_bank_code,''))),''),
     nullif(btrim(coalesce(p_card_product,'')),''),
     'declared', now())
  on conflict (user_id, program_id, coalesce(tier,''), coalesce(card_label,''))
  do update set
    guest_capacity   = coalesce(excluded.guest_capacity, host_entitlements.guest_capacity),
    bank_code        = coalesce(excluded.bank_code, host_entitlements.bank_code),
    card_product     = coalesce(excluded.card_product, host_entitlements.card_product),
    origin           = 'declared',
    self_reported_at = now()
  returning id into v_id;

  select count(*) into v_n from host_entitlements
   where user_id = v_uid and program_id = v_prog;

  return jsonb_build_object(
    'ok', true, 'entitlement_id', v_id, 'cards_for_program', v_n,
    'note', case when v_n > 1
      then 'Bu programdan ' || v_n || ' kartın kayıtlı. Kural motoru her salonda '
           'en çok hak vereni seçer ve kapıda hangisini uzatacağını söyler.'
      else null end);
end $$;

-- ----------------------------------------------------------------------
-- remove_host_card   [etkin kaynak: 193_kart_etiketi_ve_kabin_yazma.sql]
-- ----------------------------------------------------------------------
create or replace function public.remove_host_card(p_entitlement_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_n int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  delete from host_entitlements
   where id = p_entitlement_id and user_id = v_uid;   -- 🔴 sahiplik şartı
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'not_found_or_not_yours'; end if;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- my_access_cards   [etkin kaynak: 201_banka_karti_tek_cerceve.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.my_access_cards()
returns table (
  id uuid, program_code text, program_name text, tier text, card_label text,
  guest_capacity smallint, bank_code text, card_product text,
  verified boolean, bank_dependent boolean,
  -- 201:
  bank_covers_fee text, bank_note jsonb
)
language plpgsql stable security definer set search_path = public as $$
begin
  return query
  select he.id, p.code::text, p.name::text, he.tier::text, he.card_label::text,
         he.guest_capacity, he.bank_code::text, he.card_product::text,
         coalesce(he.verified, false),
         (p.entitlement_model in ('card_network','bank_card')
          or p.code in ('PRIORITY_PASS','DRAGONPASS','LOUNGEKEY','DREAMFOLKS',
                        'EVERYLOUNGE','ONPASS','AMEX_GLOBAL','BANK_CARD','HIGHPASS','LOUNGEME')),
         he.bank_covers_fee::text,
         public.bank_card_note(p.code, he.id)
    from host_entitlements he
    join lounge_programs p on p.id = he.program_id
   where he.user_id = auth.uid() and p.active
   order by he.verified desc nulls last, p.code, coalesce(he.card_label,'');
end $$;

-- ----------------------------------------------------------------------
-- set_availability_cabin   [etkin kaynak: 193_kart_etiketi_ve_kabin_yazma.sql]
-- ----------------------------------------------------------------------
create or replace function public.set_availability_cabin(
  p_avail_id uuid,
  p_cabin    text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_host uuid; v_c text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select host_id into v_host from availabilities where id = p_avail_id;
  if v_host is null then raise exception 'not_found'; end if;
  if v_host <> v_uid then raise exception 'not_host'; end if;

  v_c := nullif(btrim(lower(coalesce(p_cabin,''))), '');
  if v_c is not null and v_c not in ('economy','business','first') then
    raise exception 'invalid_cabin';
  end if;

  update availabilities set cabin_class = v_c, updated_at = now()
   where id = p_avail_id;

  return jsonb_build_object(
    'ok', true, 'cabin_class', v_c,
    -- Resmî kural: misafir hakkı BİLETE değil STATÜ kartına bağlı
    -- (Tablo-4 Business bölümü notu). Business seçen host'a bunu
    -- söylemek, kapıda sürprizi önler.
    'note', case when v_c = 'business'
      then 'Business bileti seni içeri alır ama misafir hakkı kart tipinden gelir.'
                 when v_c = 'first'
      then 'First Class bileti Business bölümünde bir misafir hakkı verir.'
      else null end);
end $$;

-- ----------------------------------------------------------------------
-- trg_waitlist_rate   [etkin kaynak: 194_bekleme_listesi.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_waitlist_rate()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  select count(*) into v_n from waitlist
   where created_at > now() - interval '1 minute';
  if v_n > 20 then
    raise exception 'rate_limited_waitlist'
      using hint = 'Dakikada 20 kayıt sınırı aşıldı, biraz sonra tekrar dene.';
  end if;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- waitlist_summary   [etkin kaynak: 194_bekleme_listesi.sql]
-- ----------------------------------------------------------------------
create or replace function public.waitlist_summary()
returns table (toplam int, host int, misafir int, bugun int, davet_bekleyen int)
language sql stable security definer set search_path = public as $$
  select count(*)::int,
         count(*) filter (where role = 'host')::int,
         count(*) filter (where role = 'misafir')::int,
         count(*) filter (where created_at::date = current_date)::int,
         count(*) filter (where invited_at is null)::int
    from waitlist
$$;

-- ----------------------------------------------------------------------
-- flight_carrier_resolve   [etkin kaynak: 195_ucus_alanlari_ve_kod_paylasimi.sql]
-- ----------------------------------------------------------------------
create or replace function public.flight_carrier_resolve(p_flight_no text, p_date date default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_no   text := upper(replace(trim(coalesce(p_flight_no,'')), ' ', ''));
  v_pref text;
  v      flight_cache%rowtype;
begin
  if v_no = '' then
    return jsonb_build_object('carrier', null, 'kaynak', 'yok', 'codeshare', false);
  end if;
  v_pref := upper(substring(regexp_replace(v_no, '[^A-Za-z]', '', 'g') from 1 for 2));

  select * into v from flight_cache
   where upper(replace(flight_no,' ','')) = v_no
     and (p_date is null or flight_date = p_date)
   order by flight_date desc nulls last
   limit 1;

  if found and coalesce(v.operating_iata, '') <> '' then
    return jsonb_build_object(
      'carrier',    v.operating_iata,
      'marketing',  coalesce(v.airline_iata, v_pref),
      'kaynak',     'onbellek',
      'codeshare',  (v.codeshared is not null
                     and coalesce(v.codeshared ->> 'airline_iata','') <> ''
                     and coalesce(v.codeshared ->> 'airline_iata','') is distinct from coalesce(v.airline_iata,'')),
      'not',        case when v.codeshared is not null
                          and coalesce(v.codeshared ->> 'airline_iata','') is distinct from coalesce(v.airline_iata,'')
                    then 'Bu bir kod paylaşımlı uçuş: bileti '
                         || coalesce(v.airline_iata, v_pref)
                         || ' satıyor, uçağı '
                         || coalesce(v.codeshared ->> 'airline_name', v.codeshared ->> 'airline_iata')
                         || ' uçuruyor. Salon hakkı UÇURAN havayoluna göre değerlendirilir.'
                    else null end);
  end if;

  -- Önbellek yok: önek. Bu bir VARSAYIMDIR ve öyle etiketlenir.
  return jsonb_build_object(
    'carrier',   nullif(v_pref, ''),
    'marketing', nullif(v_pref, ''),
    'kaynak',    'onek',
    'codeshare', false,
    'not',       'Uçuş numarasının önekine bakıldı. Kod paylaşımlı bir '
                 || 'uçuşsa uçağı başka bir havayolu uçuruyor olabilir; '
                 || 'biniş kartında "operated by" ibaresi varsa oradaki '
                 || 'havayolu geçerlidir.');
end $$;

-- ----------------------------------------------------------------------
-- plan_options   [etkin kaynak: 196_plan_ucretleri_ve_celiski_kapanisi.sql]
-- ----------------------------------------------------------------------
create or replace function public.plan_options(p_program_code text)
returns table (plan_code text, plan_name text, annual_fee numeric, currency text,
               member_free_visits int, member_visit_fee numeric,
               guest_visit_fee numeric, extras text, ozet text,
               source_url text, checked_at date)
language sql stable security definer set search_path = public as $$
  select pl.plan_code, pl.plan_name, pl.annual_fee, pl.currency,
         pl.member_free_visits, pl.member_visit_fee, pl.guest_visit_fee, pl.extras,
         pl.plan_name || ' · yıllık ' || pl.annual_fee::text || ' ' || pl.currency
           || ' · ' || case when pl.member_free_visits is null then 'sınırsız üye ziyareti'
                            when pl.member_free_visits = 0 then 'ücretsiz ziyaret yok'
                            else pl.member_free_visits::text || ' ücretsiz ziyaret' end
           || ' · misafir ' || pl.guest_visit_fee::text || ' ' || pl.currency,
         pl.source_url, pl.checked_at
    from program_plans pl
   where pl.active and pl.program_code = upper(btrim(coalesce(p_program_code,'')))
   order by pl.annual_fee nulls last
$$;

