-- ----------------------------------------------------------------------
-- trg_venue_catalog_row   [etkin kaynak: 199_ucus_saati_terminal_ve_katalog.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_venue_catalog_row()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    if new.active and new.venue_kind = 'lounge'
       and new.section is null and new.section_of is null
       and new.legacy_lounge_id is null
       and not exists (select 1 from lounges l where l.venue_id = new.id) then
      insert into lounges (airport_code, name, terminal, access_types, active, venue_id)
      values (new.airport_code, new.name, new.terminal,
              array['Bilgi girilmedi']::text[], true, new.id);
    end if;
  exception when others then
    null;
  end;
  return null;
end $$;

-- ----------------------------------------------------------------------
-- trg_airport_country_canon   [etkin kaynak: 200_ulke_sozlugu_tekillestirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_airport_country_canon()
returns trigger language plpgsql as $$
declare v_c text;
begin
  begin
    select ca.canonical into v_c from country_aliases ca
     where lower(btrim(ca.alias)) = lower(btrim(coalesce(new.country,'')));
    if v_c is not null then new.country := v_c; end if;
  exception when others then
    null;
  end;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- coverage_summary   [etkin kaynak: 200_ulke_sozlugu_tekillestirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.coverage_summary()
returns table (havalimani int, salon int, ulke int, tr_havalimani int, tr_salon int)
language sql stable security definer set search_path = public as $$
  with v as (
    select vv.airport_code, ap.country
      from lounge_venues vv
      join airports ap on ap.code = vv.airport_code
     where vv.active and vv.venue_kind = 'lounge' and vv.section_of is null
  )
  select count(distinct airport_code)::int,
         count(*)::int,
         count(distinct country)::int,
         count(distinct airport_code) filter (where country = 'Türkiye')::int,
         count(*) filter (where country = 'Türkiye')::int
    from v
$$;

-- ----------------------------------------------------------------------
-- set_card_bank_coverage   [etkin kaynak: 201_banka_karti_tek_cerceve.sql]
-- ----------------------------------------------------------------------
create or replace function public.set_card_bank_coverage(p_entitlement_id uuid, p_value text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_owner uuid; v_val text := nullif(btrim(lower(coalesce(p_value,''))),'');
begin
  if v_val is not null and v_val not in ('yes','no','unknown') then
    raise exception 'gecersiz_deger';
  end if;
  select user_id into v_owner from host_entitlements where id = p_entitlement_id;
  if v_owner is null then raise exception 'kart_yok'; end if;
  if v_owner <> auth.uid() then raise exception 'not_owner'; end if;

  update host_entitlements
     set bank_covers_fee = v_val,
         self_reported_at = now()
   where id = p_entitlement_id;

  return jsonb_build_object('ok', true, 'bank_covers_fee', v_val);
end $$;

-- ----------------------------------------------------------------------
-- bank_card_note   [etkin kaynak: 201_banka_karti_tek_cerceve.sql]
-- ----------------------------------------------------------------------
create or replace function public.bank_card_note(
  p_program_code   text,
  p_entitlement_id uuid default null
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_code  text := upper(btrim(coalesce(p_program_code,'')));
  p       lounge_programs%rowtype;
  v_plan  record;
  v_he    host_entitlements%rowtype;
  v_ovr   record;
  v_bilinen text;
  v_beyan   text := null;
  v_kaynak  text := null;
  v_guven   text := 'genel';
begin
  select * into p from lounge_programs where code = v_code and active;
  if not found then
    return jsonb_build_object('bank_dependent', false);
  end if;

  -- Bankaya bağlı olmayan programlarda (THY statüsü gibi) bu çerçeve
  -- HİÇ gösterilmez. Yanlış yerde gösterilen doğru bir uyarı, gürültüdür.
  if not (p.entitlement_model in ('card_network','bank_card')
          or v_code in ('PRIORITY_PASS','DRAGONPASS','LOUNGEKEY','DREAMFOLKS',
                        'EVERYLOUNGE','ONPASS','AMEX_GLOBAL','BANK_CARD','HIGHPASS','LOUNGEME')) then
    return jsonb_build_object('bank_dependent', false);
  end if;

  -- ---- KATMAN 1: BİLİYORUZ (kaynaklı) ----
  select pl.guest_visit_fee, pl.currency, pl.source_url
    into v_plan
    from program_plans pl
   where pl.active and pl.program_code = v_code
   order by pl.annual_fee nulls last
   limit 1;

  if v_plan.guest_visit_fee is not null then
    v_bilinen := p.name || ' plan sayfasına göre misafir ziyareti ziyaret başına '
              || v_plan.guest_visit_fee::text || ' ' || v_plan.currency
              || ' ve tutar ÜYENİN kartından tahsil edilir.';
    v_kaynak  := v_plan.source_url;
  elsif p.typical_guest_fee is not null then
    v_bilinen := p.name || ': misafir ziyareti ücretlidir (yaklaşık '
              || p.typical_guest_fee::text || ' ' || coalesce(p.guest_fee_currency,'EUR') || ').';
    v_kaynak  := p.source_url;
  else
    v_bilinen := p.name || ': misafir hakkının ve ücretinin ne olduğu program '
              || 'sayfasında tutara bağlanmamış.';
    v_kaynak  := p.source_url;
  end if;

  -- ---- KATMAN 3'ÜN ÜSTÜNE: KULLANICI BEYANI ----
  if p_entitlement_id is not null then
    select * into v_he from host_entitlements
     where id = p_entitlement_id and user_id = auth.uid();
    if found then
      if v_he.bank_covers_fee = 'yes' then
        v_beyan := (select value #>> '{}' from beta_settings where key = 'bank_frame_declared_yes');
        v_guven := 'beyan_var';
      elsif v_he.bank_covers_fee = 'no' then
        v_beyan := (select value #>> '{}' from beta_settings where key = 'bank_frame_declared_no');
        v_guven := 'beyan_var';
      else
        v_beyan := (select value #>> '{}' from beta_settings where key = 'bank_frame_ask_user');
        v_guven := 'beyan_yok';
      end if;

      -- ---- İSTEĞE BAĞLI ÜSTÜNE YAZMA (191'in tablosu) ----
      -- Tablo BOŞSA hiçbir şey olmaz; doluysa genel çerçeveyi EZER.
      if coalesce(v_he.bank_code,'') <> '' then
        select bo.guest_fee, bo.fee_payer, bo.source_url, bo.bank_name
          into v_ovr
          from bank_program_overrides bo
         where bo.active and bo.program_id = p.id
           and upper(bo.bank_code) = upper(v_he.bank_code)
           and (bo.card_product is null or bo.card_product = v_he.card_product)
         order by (bo.card_product is null)
         limit 1;
        if found then
          v_bilinen := coalesce(v_ovr.bank_name, v_he.bank_code) || ' için kayıtlı koşul: '
                    || case when v_ovr.guest_fee is not null
                            then 'misafir ücreti ' || v_ovr.guest_fee::text || ' EUR'
                            else 'misafir ücreti belirtilmemiş' end
                    || case when v_ovr.fee_payer is not null
                            then ' · ödeyen: ' || v_ovr.fee_payer else '' end || '.';
          v_kaynak := coalesce(v_ovr.source_url, v_kaynak);
          v_guven  := 'banka_kayitli';
        end if;
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'bank_dependent', true,
    'program', p.name,
    'guven', v_guven,                        -- genel | beyan_yok | beyan_var | banka_kayitli
    'biliyoruz', v_bilinen,
    'banka_degistirebilir', (select value #>> '{}' from beta_settings where key = 'bank_frame_can_change'),
    'ne_yapmalisin', (select value #>> '{}' from beta_settings where key = 'bank_frame_action'),
    'kisa', (select value #>> '{}' from beta_settings where key = 'bank_frame_short'),
    'beyan', v_beyan,
    'beyan_degeri', v_he.bank_covers_fee,
    'kaynak_url', v_kaynak);
end $$;

-- ----------------------------------------------------------------------
-- apply_ajet_intl_policy   [etkin kaynak: 202_saat_dilimi_ajet_anahtari_pencere.sql]
-- ----------------------------------------------------------------------
create or replace function public.apply_ajet_intl_policy()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_pol text := coalesce((select value #>> '{}' from beta_settings where key='ajet_intl_guest_right'), 'unknown');
  v_g int; v_f boolean; v_note text; v_n int;
begin
  if v_pol not in ('unknown','yes','no') then
    raise exception 'gecersiz_politika';
  end if;

  if v_pol = 'yes' then
    v_g := 1; v_f := true;
    v_note := 'AJet dış hat / yurt dışı salonlarında da aile veya bir misafir hakkın var '
           || '(AJet''ten teyit alındı — BO ayarı: ajet_intl_guest_right=yes). '
           || 'Misafirin de AJet seferinde seyahat etmesi gerekir.';
  elsif v_pol = 'no' then
    v_g := 0; v_f := false;
    v_note := 'AJet dış hat / yurt dışı salonlarında misafir hakkı YOKTUR '
           || '(AJet''ten teyit alındı — BO ayarı: ajet_intl_guest_right=no). '
           || 'Kendi girişin etkilenmez.';
  else
    v_g := 0; v_f := false;
    v_note := 'Miles&Smiles statü sayfası "AJet uçuşlarında eş ile çocuklar veya bir '
           || 'misafirle özel yolcu salonlarından yararlanabilme" diyor ve kapsam '
           || 'koymuyor — yani HAKKIN VAR. Ancak AJet''in salon listesi yalnız İÇ HAT '
           || 'salonlarını sayıyor; bu salonun listede olup olmadığı kaynakta YAZMIYOR. '
           || 'Bu yüzden burada söz vermiyoruz: misafirle girmeyi planlıyorsan kapıda '
           || 'ya da AJet''e teyit ettir.';
  end if;

  update lounge_guest_rules r
     set guest_allowance = v_g, family_allowed = v_f, notes = v_note
    from lounge_programs p
   where r.program_id = p.id and p.code = 'AJET_MS'
     and r.card_tier in ('ELITE','ELPL','MS_EC')
     and coalesce(r.venue_scope,'') in ('international','abroad')
     and (r.effective_to is null or r.effective_to >= current_date);
  get diagnostics v_n = row_count;

  return jsonb_build_object('politika', v_pol, 'guncellenen_kural', v_n,
                            'guest_allowance', v_g, 'family_allowed', v_f);
end $$;

-- ----------------------------------------------------------------------
-- trg_ajet_intl_setting   [etkin kaynak: 202_saat_dilimi_ajet_anahtari_pencere.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_ajet_intl_setting()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    if new.key = 'ajet_intl_guest_right' then
      perform public.apply_ajet_intl_policy();
    end if;
  exception when others then
    null;   -- ayar yazımı ASLA düşmez
  end;
  return null;
end $$;

-- ----------------------------------------------------------------------
-- entry_window_relevant   [etkin kaynak: 202_saat_dilimi_ajet_anahtari_pencere.sql]
-- ----------------------------------------------------------------------
create or replace function public.entry_window_relevant(p_avail_id uuid, p_user_id uuid default null)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare
  v_uid uuid := coalesce(p_user_id, auth.uid());
  a     availabilities%rowtype;
  v_dec jsonb;
  v_best jsonb;
begin
  select * into a from availabilities where id = p_avail_id;
  if not found then return false; end if;

  -- Kişinin bu salonda GEÇERLİ bir hakkı var mı ve ücretsiz mi?
  begin
    v_best := public.best_access_for_user(v_uid, a.venue_id, a.carrier, a.flight_number);
    if coalesce(v_best ->> 'guest_policy','') = 'included' then
      return false;   -- statüyle ücretsiz giriyor → ücretli pencere ONU İLGİLENDİRMİYOR
    end if;
  exception when others then
    v_best := null;   -- çözülemezse aşağıdaki genel karara düş
  end;

  begin
    v_dec := public.lounge_access_decision(p_avail_id, a.flight_number);
    if coalesce(v_dec ->> 'guest_policy','') = 'included' then
      return false;
    end if;
  exception when others then
    null;
  end;

  return true;   -- ücretli ya da bilinmiyor → pencere BİLGİSİ İŞE YARAR
end $$;

-- ----------------------------------------------------------------------
-- apply_rpc_surface   [etkin kaynak: 203_guvenlik_siniri.sql]
-- ----------------------------------------------------------------------
create or replace function public.apply_rpc_surface()
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_hedef text[];
  v_ad    text[] := '{}';
  i       int;
  v_kilit int := 0;
begin
  -- 🔴 ÖNCE TOPLA, SONRA DEĞİŞTİR. `for r in select ...` bir imleçtir;
  -- döngü sürerken revoke yapmak, imlecin okuduğu koşulu
  -- (`has_function_privilege`) altından çeker. Klasik "iterate ederken
  -- mutate etme" hatası: sonuç sessizce EKSİK kalır, hata VERMEZ.
  -- Bu yüzden tam liste önce diziye alınıyor.
  select array_agg(format('%I(%s)', proname, args) order by proname),
         array_agg(proname order by proname)
    into v_hedef, v_ad
    from (
      select p.proname::text as proname,
             pg_get_function_identity_arguments(p.oid) as args
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
       where n.nspname = 'public'
         and p.prokind = 'f'
         and not exists (select 1 from rpc_client_surface s where s.fn_name = p.proname)
         and (
           has_function_privilege('authenticated', p.oid, 'EXECUTE')
           or has_function_privilege('anon', p.oid, 'EXECUTE')
         )
    ) topla;

  if v_hedef is null then
    return jsonb_build_object('kilitlenen', 0, 'ornekler', '[]'::jsonb);
  end if;

  for i in 1 .. array_length(v_hedef, 1) loop
    execute 'revoke all on function public.' || v_hedef[i] || ' from public, anon, authenticated';
    execute 'grant execute on function public.' || v_hedef[i] || ' to service_role';
    v_kilit := v_kilit + 1;
  end loop;

  return jsonb_build_object('kilitlenen', v_kilit, 'ornekler', to_jsonb(v_ad[1:12]));
end $fn$;

comment on function public.apply_rpc_surface() is
  'rpc_client_surface disinda kalan her public fonksiyonu istemci rollerinden alir, service_role a verir. Yeni migration sonrasi tekrar calistirilabilir (idempotent).';

-- ⚠️ ÇAĞRI BURADA DEĞİL, DOSYANIN SONUNDA. İlk yazışımda buraya
-- koymuştum ve 3. nöbetçi patladı: bu satırdan SONRA oluşturulan
-- `rpc_surface_violations` kendisi açık kalmıştı. Nöbetçi kendi
-- yazarını yakaladı — sınırın işe yaradığının ilk kanıtı bu oldu.
-- KURAL: `apply_rpc_surface()` her zaman, fonksiyon oluşturan her
-- migration'ın EN SONUNDA çağrılır.


-- ============================================================
-- 3) KALICI DENETİM — sınır bir daha sessizce açılmasın
-- ============================================================
-- Yeni bir migration `create function` yazıp grant verirse, bu
-- fonksiyon onu görür. pg_run.py bunu her koşuda çağırıyor.

-- ----------------------------------------------------------------------
-- rpc_surface_violations   [etkin kaynak: 203_guvenlik_siniri.sql]
-- ----------------------------------------------------------------------
create or replace function public.rpc_surface_violations()
returns table (fn_name text, arglist text, neden text)
language sql stable security definer set search_path = public as $fn$
  -- (a) yüzeyde OLMAYAN ama istemciye AÇIK olan
  select p.proname::text,
         pg_get_function_identity_arguments(p.oid)::text,
         'yuzeyde yok ama istemciye acik'::text
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.prokind = 'f'
     and not exists (select 1 from rpc_client_surface s where s.fn_name = p.proname)
     and (has_function_privilege('authenticated', p.oid, 'EXECUTE')
          or has_function_privilege('anon', p.oid, 'EXECUTE'))
  union all
  -- (b) yüzeyde OLAN ama artık VAR OLMAYAN (uygulama 404 alır)
  select s.fn_name, ''::text, 'yuzeyde yazili ama fonksiyon YOK'::text
    from rpc_client_surface s
   where not exists (
     select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = s.fn_name)
  union all
  -- (c) yüzeyde OLAN ama istemci ÇAĞIRAMAYAN (sessiz 42501)
  select s.fn_name, ''::text, 'yuzeyde yazili ama istemci CAGIRAMIYOR'::text
    from rpc_client_surface s
   where exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname='public' and p.proname = s.fn_name)
     and not exists (
       select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
        where n.nspname='public' and p.proname = s.fn_name
          and has_function_privilege('authenticated', p.oid, 'EXECUTE'));
$fn$;

grant execute on function public.rpc_surface_violations() to service_role;


-- ============================================================
-- 4) mark_email_verified — KANITSIZ DOĞRULAMA KAPANDI
-- ============================================================
-- 🔴 ÖLÇÜM: harness'te oturum açmış bir kullanıcı olarak çağırdım:
--     select mark_email_verified();          → {"ok": true}
--     select is_contact_verified(<uid>);     → t
-- Yani e-postasını hiç açmamış biri, tek çağrıyla `create_availability`
-- kapısını (`contact_not_verified`) açabiliyordu. Host olmanın TEK
-- doğrulama şartıydı bu.
--
-- Doğru yol zaten VARDI: `verify_email_contact()` auth.users içindeki
-- `email_confirmed_at`e bakıyor. Uygulama İKİSİNİ DE çağırıyor
-- (screens.js:2864 ve 2871) — ikincisi yalnız yedek. O yüzden imzayı
-- KORUYUP gövdeyi kanıta bağlıyorum: uygulamanın tek satırı değişmiyor,
-- saldırı yüzeyi kapanıyor.

-- ----------------------------------------------------------------------
-- blok_kapisi   [etkin kaynak: 204_blok_eylem_sinirinda.sql]
-- ----------------------------------------------------------------------
create or replace function public.blok_kapisi()
returns trigger language plpgsql security definer set search_path = public as $fn$
declare v_a uuid; v_b uuid;
begin
  -- Her tabloda taraf kolonları farklı ad taşıyor; tetikleyici
  -- argümanıyla veriliyor ki fonksiyon tek olsun.
  execute format('select ($1).%I, ($1).%I', TG_ARGV[0], TG_ARGV[1])
    into v_a, v_b using new;

  if v_a is not null and v_b is not null and public.is_blocked_pair(v_a, v_b) then
    raise exception 'blocked_pair'
      using hint = 'Bu kisiyle iletisim engellenmis.';
  end if;
  return new;
end $fn$;

comment on function public.blok_kapisi() is
  'Iliski tablolarina giren satirda taraflardan biri digerini engellemisse INSERT i durdurur. TG_ARGV[0] ve [1] taraf kolon adlaridir.';

drop trigger if exists trg_blok_requests on requests;
create trigger trg_blok_requests
  before insert on requests
  for each row execute function public.blok_kapisi('guest_id', 'host_id');

drop trigger if exists trg_blok_connection_requests on connection_requests;
create trigger trg_blok_connection_requests
  before insert on connection_requests
  for each row execute function public.blok_kapisi('from_id', 'to_id');

drop trigger if exists trg_blok_invites on invites;
create trigger trg_blok_invites
  before insert on invites
  for each row execute function public.blok_kapisi('host_id', 'guest_id');


-- ============================================================
-- A2) ENGEL ANINDA GEÇMİŞİ DE TEMİZLE
-- ============================================================
-- Tetikleyici YENİ satırı durdurur; peki engellemeden ÖNCEKİ bekleyen
-- istek ne olacak? Bugün öylece duruyor ve iki tarafın da ekranında
-- görünüyor. Engelleyen kişi "engelledim" der ama karşı taraf hâlâ
-- listesinde. Blok satırı yazılınca aradaki BEKLEYEN her şey kapanır.

-- ----------------------------------------------------------------------
-- blok_gecmisi_kapat   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.blok_gecmisi_kapat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- 🔴 301/§9: 204'ten beri bekleyen istek KAPANIYOR ama tutulan kredi
  -- İADE EDİLMİYORDU (tam akış testi: defterde yalnız `request_hold:-1`).
  -- Engelleme uygulamadan yapılamadığı için bu hiç görünmemişti; 301 §1
  -- engellemeyi açınca canlı hataya dönüşecekti. Artık her kapanan istek
  -- iade yolundan geçiyor (tekrar iadeyi `istek_kredisi_iade` kendisi önler).
  declare v_r record;
  begin
    for v_r in
      update requests set status = 'cancelled', responded_at = now()
       where status = 'pending'
         and ((guest_id = new.blocker and host_id = new.blocked)
           or (guest_id = new.blocked and host_id = new.blocker))
      returning id
    loop
      perform public.istek_kredisi_iade(v_r.id, 'request_refund');
    end loop;
  end;

  -- ⚠️ `connection_status` = pending | accepted | declined | blocked.
  -- İlk yazışımda 'rejected' yazdım — enum'da YOK, 22P02 aldım. Enum'un
  -- kendisinde zaten 'blocked' var ve burada 'declined'dan DAHA DOĞRU:
  -- kullanıcı reddetmedi, engelledi. Sebep kayıtta kalsın.
  update connection_requests set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((from_id = new.blocker and to_id = new.blocked)
       or (from_id = new.blocked and to_id = new.blocker));

  update invites set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((host_id = new.blocker and guest_id = new.blocked)
       or (host_id = new.blocked and guest_id = new.blocker));

  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ
-- ════════════════════════════════════════════════════════════════════════
do $z301$
declare v_n int; v_l text;
begin
  select count(*), string_agg(p.proname, ', ') into v_n, v_l
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('engelle','engeli_kaldir','engellediklerim','gelmedi_bildir','gelmedi_esigi')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '301 §Z: authenticated çağıramıyor: %', v_l; end if;
  select count(*) into v_n from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '301 §Z: PUBLIC''e açık % fonksiyon (300 §A2 geriledi)', v_n; end if;
  if position('test_hesabi_gizli_mi' in (select prosrc from pg_proc where proname = 'is_visible')) = 0 then
    raise exception '301 §Z: is_visible yamasız';
  end if;
  if not exists (select 1 from pg_trigger where tgname = 'trg_mesaj_engel') then
    raise exception '301 §Z: mesaj engel tetikleyicisi yok';
  end if;
  raise notice '301 §Z: kapılar ölçüldü';
end $z301$;

select '301 OK — engelleme · gelmedi · test hesabı gizleme · rehber sayacı' as sonuc;

-- ----------------------------------------------------------------------
-- blok_filtresi_ekle   [etkin kaynak: 204_blok_eylem_sinirinda.sql]
-- ----------------------------------------------------------------------
create or replace function public.blok_filtresi_ekle(p_fn text, p_peer_col text)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v_oid  oid;
  v_args text;
  v_args_full text;
  v_res  text;
  v_cagri text;
  v_yeni text := p_fn || '_prebfilter';
begin
  -- Zaten sarmalanmışsa tekrar sarmalama (idempotent).
  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
              where n.nspname = 'public' and p.proname = v_yeni) then
    return p_fn || ': zaten sarmalanmis';
  end if;

  -- ⚠️ create icin VARSAYILANLI imza (pg_get_function_arguments),
  -- alter/revoke/grant icin KIMLIK imzasi (identity). Ikisini
  -- karistirmak sarmalayiciyi varsayilansiz dogurur ve daha az
  -- argumanla cagiran her yer 42883 alir (207'de tam bunu yasadim).
  select p.oid, pg_get_function_identity_arguments(p.oid),
         pg_get_function_arguments(p.oid), pg_get_function_result(p.oid)
    into v_oid, v_args, v_args_full, v_res
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = p_fn and p.prokind = 'f';
  if v_oid is null then raise exception 'blok_filtresi_ekle: % bulunamadi', p_fn; end if;

  -- Çağrı listesi: `p_airport text, p_date date` → `p_airport, p_date`
  select coalesce(string_agg(split_part(btrim(x), ' ', 1), ', '), '')
    into v_cagri
    from unnest(string_to_array(v_args, ',')) x
   where btrim(x) <> '';

  execute format('alter function public.%I(%s) rename to %I', p_fn, v_args, v_yeni);

  execute format($sql$
    create function public.%I(%s) returns %s
    language sql stable security definer set search_path = public as $body$
      select q.* from public.%I(%s) q
       where auth.uid() is null
          or not public.is_blocked_pair(auth.uid(), q.%I)
    $body$
  $sql$, p_fn, v_args_full, v_res, v_yeni, v_cagri, p_peer_col);

  -- İstemci yüzeyindeyse hakkı korunur; değilse 203'ün sınırı geçerli.
  if exists (select 1 from rpc_client_surface s where s.fn_name = p_fn) then
    execute format('grant execute on function public.%I(%s) to public', p_fn, v_args);
  else
    execute format('revoke all on function public.%I(%s) from public, anon, authenticated', p_fn, v_args);
    execute format('grant execute on function public.%I(%s) to service_role', p_fn, v_args);
  end if;
  -- İç fonksiyon artık istemciye AÇIK OLMAMALI, yoksa filtre atlanır.
  execute format('revoke all on function public.%I(%s) from public, anon, authenticated', v_yeni, v_args);
  execute format('grant execute on function public.%I(%s) to service_role', v_yeni, v_args);

  return p_fn || ': sarmalandi (' || p_peer_col || ')';
end $fn$;

do $$
begin
  raise notice '204: %', public.blok_filtresi_ekle('discover_people', 'user_id');
  raise notice '204: %', public.blok_filtresi_ekle('invitable_guests', 'guest_id');
  raise notice '204: %', public.blok_filtresi_ekle('home_connections', 'peer_id');
end $$;

-- ----------------------------------------------------------------------
-- blok_kapsam_denetimi   [etkin kaynak: 204_blok_eylem_sinirinda.sql]
-- ----------------------------------------------------------------------
create or replace function public.blok_kapsam_denetimi()
returns table (tablo text, neden text)
language sql stable security definer set search_path = public as $fn$
  select t.tablo::text, 'iliski tablosunda blok tetikleyicisi YOK'::text
    from (values ('requests'), ('connection_requests'), ('invites')) t(tablo)
   where not exists (
     select 1 from pg_trigger g join pg_class c on c.oid = g.tgrelid
      where c.relname = t.tablo and not g.tgisinternal
        and g.tgfoid = 'public.blok_kapisi()'::regprocedure)
  union all
  select f.fn::text, 'listeleme yuzeyi blok filtresiz'::text
    from (values ('discover_people'), ('invitable_guests'), ('home_connections')) f(fn)
   where not exists (
     select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = f.fn || '_prebfilter');
$fn$;

grant execute on function public.blok_kapsam_denetimi() to service_role;


