-- ════════════════════════════════════════════════════════════════════════
-- §8 — DİL KATMANINI KURAL ZİNCİRİNE BAĞLA — TR BAYT BAYT AYNI KALARAK
--
-- §4 yardımcıyı kurdu. Şimdi üç fonksiyondaki satır içi ayar okumalarını
-- `metin()` üzerinden geçiriyorum:
--     lounge_access_decision_v3 · lounge_hint_for_host · request_precheck_pregate
--
-- 🔴 BU DOSYADAKİ EN RİSKLİ İŞ BU. Ürünün tek cümlesi ("kapıda ne olacak")
-- bu üç fonksiyondan çıkıyor. Bu yüzden iddia etmiyorum, KANITLIYORUM:
--   (1) değişiklikten ÖNCE gerçek ilanlar için TR çıktısını topla
--   (2) değiştir
--   (3) SONRA aynı ilanlar için tekrar topla
--   (4) TEK BAYT farkı varsa kurulumu DURDUR
--
-- 🆕 SINIF: "BİR METNİ ÇEVİRİLEBİLİR YAPMAK, O METNİ DEĞİŞTİRMEK DEĞİLDİR
-- — VE BUNU ANCAK ÖNCE/SONRA KARŞILAŞTIRARAK SÖYLEYEBİLİRSİN."
-- ════════════════════════════════════════════════════════════════════════

do $e4$
declare
  v_once   jsonb := '[]'::jsonb;
  v_sonra  jsonb := '[]'::jsonb;
  r        record;
begin
  -- 🔴 İLK YAKLAŞIMIM YANLIŞTI VE KENDİ KORUMAM SÖYLEDİ.
  -- Üç fonksiyonun gövdesinde `select value #>> '{}' from beta_settings`
  -- aradım; hiçbirinde YOKTU ve blok "desen bulunamadi — DOKUNULMADI"
  -- deyip durdu. (Sessizce "yaptım" demediği için hatayı gördüm.)
  --
  -- Okuyunca çıktı: bu proje o soruyu ZATEN tek bir yere toplamış —
  -- `public.rule_notice(anahtar)`. Beş fonksiyon kural cümlelerini yalnız
  -- oradan alıyor. Yani üç gövdeyi metin cerrahisiyle yeniden yazmama
  -- HİÇ GEREK YOK: tek bir yardımcıyı dile duyarlı yapmak yetiyor.
  --
  -- 🆕 SINIF: "BİR DEĞİŞİKLİĞİ KAÇ YERE UYGULAYACAĞINI SORMADAN ÖNCE,
  -- O YERLERİN ZATEN TEK BİR KAPIDAN GEÇİP GEÇMEDİĞİNE BAK."
  -- Riskli üç gövde ameliyatı, tek bir güvenli fonksiyon değişikliğine indi.

  -- (1) ÖNCE — TR çıktısı
  perform public.dili_ayarla('tr');
  for r in select a.id from availabilities a where a.active order by a.id limit 25 loop
    begin
      v_once := v_once || jsonb_build_object(
        'id', r.id,
        'karar', public.lounge_access_decision(r.id, null),
        'ipucu', public.lounge_hint_for_host(r.id));
    exception when others then
      v_once := v_once || jsonb_build_object('id', r.id, 'hata', sqlerrm);
    end;
  end loop;

  -- (2) DEĞİŞTİR — tek fonksiyon, tek satır.
  --     `metin()` dil GUC'u yoksa ya da 'tr' ise BİREBİR eski davranış.
  execute $q$

-- ----------------------------------------------------------------------
-- host_missed_value   [etkin kaynak: 206_host_motoru.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_missed_value(p_gun int default 30)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid uuid := auth.uid();
  v_hava text[];
  v_kisi int := 0;
  v_liste jsonb;
begin
  if v_uid is null then return jsonb_build_object('known', false); end if;

  -- Host'un gerçekten bulunduğu havalimanları: geçmiş ilanları + seyahatleri
  select array_agg(distinct kod) into v_hava from (
    select airport_code::text as kod from availabilities where host_id = v_uid
    union
    select airport_code::text from visits where user_id = v_uid
  ) x;
  if v_hava is null or array_length(v_hava,1) is null then
    return jsonb_build_object('known', false,
      'bos_baslik', 'Henüz bir havalimanı bilmiyoruz.',
      'bos_alt', 'Bir seyahat ekle; o havalimanında seni bekleyen var mı söyleyelim.');
  end if;

  -- Host bulamamış yolcular: seyahati var, o gün o havalimanında
  -- TAMAMLANMIŞ oturumu yok ve host'un ilanı da yoktu.
  select count(*), jsonb_agg(jsonb_build_object('havalimani', kod, 'kisi', n) order by n desc)
    into v_kisi, v_liste
  from (
    select vs.airport_code::text as kod, count(distinct vs.user_id) as n
      from visits vs
      join users gu on gu.id = vs.user_id
     where vs.airport_code = any(v_hava)
       and vs.visit_date between current_date - p_gun and current_date
       and vs.user_id <> v_uid
       and coalesce(gu.is_staff,false) = false
       and gu.deleted_at is null
       and not exists (
         select 1 from requests r join sessions s on s.request_id = r.id
          where r.guest_id = vs.user_id and s.status = 'completed'
            and s.completed_at::date = vs.visit_date)
       and not exists (
         select 1 from availabilities a
          where a.host_id = v_uid and a.active
            and a.airport_code = vs.airport_code
            and a.avail_date = vs.visit_date
            and a.time_from < vs.time_to and vs.time_from < a.time_to)
     group by vs.airport_code
  ) q;

  return jsonb_build_object(
    'known', true,
    'gun', p_gun,
    'kisi', coalesce(v_kisi,0),
    'havalimanlari', coalesce(v_liste, '[]'::jsonb),
    'baslik', case when coalesce(v_kisi,0) = 0
      then 'Son ' || p_gun || ' günde kaçırdığın kimse yok.'
      else format('Son %s günde %s kişi senin bulunduğun havalimanlarında host bulamadı.',
                  p_gun, v_kisi) end,
    'alt', case when coalesce(v_kisi,0) > 0
      then 'İlan açmak 20 saniye. Sen zaten oradaydın.' end);
end $fn$;


-- ============================================================
-- 5) MERTEBE — puan değil, STATÜ
-- ============================================================
-- 🔴 Bu kitle statü peşinde koşmaya ALIŞIK: Elite, Elite Plus,
-- Platinum. Onlara "500 puan kazandın" demek, dilini konuşmamaktır.
-- "Kâhya oldun" demek konuşmaktır.
--
-- ⚠️ AMA: ayrıcalık GERÇEK olmalı. Sahte rozet, rozet olmamasından
-- kötüdür — kullanıcı bir kez "bu hiçbir şey yapmıyor" derse tüm
-- sistem inandırıcılığını kaybeder. Her mertebenin ölçülebilir bir
-- karşılığı var ve `host_standing()` onu METİN olarak da döndürüyor
-- ki ekran uydurmasın.
create table if not exists host_tiers (
  code        text primary key,
  ad          text not null,
  min_oturum  int  not null,
  siralama_ek int  not null default 0,   -- keşifte sıralama artışı
  ekstra_slot int  not null default 0,   -- görünür slot artışı
  istek_bedava boolean not null default false,
  aciklama    text not null,
  sira        int  not null
);

insert into host_tiers (code, ad, min_oturum, siralama_ek, ekstra_slot, istek_bedava, aciklama, sira) values
  ('yolcu',     'Yolcu',     0,  0, 0, false,
   'Henüz kimseyi ağırlamadın. İlk ağırlaman seni Ev Sahibi yapar.', 1),
  ('evsahibi',  'Ev Sahibi', 1,  5, 0, false,
   'Bir kişiyi içeri aldın. Keşifte önüne geçiyorsun.', 2),
  ('kahya',     'Kâhya',     5, 12, 1, false,
   'Beş kişiyi ağırladın. İlanlarında bir kişilik ek görünürlük ve keşifte belirgin öncelik.', 3),
  ('konsiyerj', 'Konsiyerj',15, 25, 1, true,
   'On beş kişiyi ağırladın. Kendi misafir isteklerin artık kredi harcamıyor.', 4)
on conflict (code) do update set
  ad = excluded.ad, min_oturum = excluded.min_oturum,
  siralama_ek = excluded.siralama_ek, ekstra_slot = excluded.ekstra_slot,
  istek_bedava = excluded.istek_bedava, aciklama = excluded.aciklama, sira = excluded.sira;

-- ----------------------------------------------------------------------
-- host_standing   [etkin kaynak: 249_is_modeli_ve_soguk_ag.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.host_standing(p_user uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $hs249$
declare
  v_uid uuid := coalesce(p_user, auth.uid());
  v_n   int; v_su host_tiers%rowtype; v_son host_tiers%rowtype; v_kredi int;
  v_esik int; v_plan text; v_gun int; v_plan_ad text;
  v_hediye_aktif boolean; v_hediye_biter timestamptz; v_hediye_kalan int;
  v_karsilik text; v_parcalar text[] := '{}';
begin
  if v_uid is null then return jsonb_build_object('known', false); end if;

  select count(*) into v_n from sessions s join requests r on r.id = s.request_id
   where r.host_id = v_uid and s.status = 'completed';

  select * into v_su  from host_tiers where min_oturum <= v_n order by min_oturum desc limit 1;
  select * into v_son from host_tiers where min_oturum >  v_n order by min_oturum asc  limit 1;

  select coalesce(sum(delta),0) into v_kredi
    from credit_ledger where user_id = v_uid and reason = 'hosted_session';

  -- ---- PLAN HEDİYESİ: ürünün en somut karşılığı, hiçbir yerde yazmıyordu
  v_esik := coalesce((select (value #>> '{}')::int  from beta_settings where key='host_free_upgrade_sessions'), 2);
  v_plan := coalesce((select  value #>> '{}'        from beta_settings where key='host_free_upgrade_plan'), 'sik_ucan');
  v_gun  := coalesce((select (value #>> '{}')::int  from beta_settings where key='host_free_upgrade_days'), 30);
  select coalesce(nullif(btrim(ad),''), plan::text) into v_plan_ad
    from plan_catalog where plan::text = v_plan;

  select true, biter_at into v_hediye_aktif, v_hediye_biter
    from plan_grants
   where user_id = v_uid and bitti_at is null and iptal_at is null and biter_at > now()
   order by biter_at desc limit 1;
  v_hediye_aktif := coalesce(v_hediye_aktif, false);
  v_hediye_kalan := greatest(0, v_esik - v_n);

  -- ---- KARŞILIK CÜMLESİ: mertebeye bağlı, gerçek ayrıcalıkları sayar
  if v_su.siralama_ek > 0 then
    v_parcalar := v_parcalar || format('keşifte %s sıra öne geçiyorsun', v_su.siralama_ek)::text;
  end if;
  if coalesce(v_su.one_cikar_saat,0) > 0 then
    v_parcalar := v_parcalar || format('her yeni ilanın %s saat öne çıkıyor', v_su.one_cikar_saat)::text;
  end if;
  if coalesce(v_su.istek_bedava,false) then
    v_parcalar := v_parcalar || 'kendi misafir isteklerin kredi harcamıyor'::text;
  end if;
  if v_kredi > 0 then
    v_parcalar := v_parcalar || format('%s misafir hakkın birikti', v_kredi)::text;
  end if;

  if v_hediye_aktif then
    v_karsilik := format('%s planın %s tarihine kadar ücretsiz — ağırladığın için.',
                         coalesce(v_plan_ad, v_plan), to_char(v_hediye_biter, 'DD.MM.YYYY'));
    if array_length(v_parcalar,1) is not null then
      v_karsilik := v_karsilik || ' Ayrıca ' || array_to_string(v_parcalar, ', ') || '.';
    end if;
  elsif array_length(v_parcalar,1) is not null then
    v_karsilik := initcap(left(v_parcalar[1],1)) || substr(array_to_string(v_parcalar, ', '), 2) || '.';
    if v_hediye_kalan > 0 then
      v_karsilik := v_karsilik || format(' %s ağırlama daha: %s planı %s gün ücretsiz.',
                                         v_hediye_kalan, coalesce(v_plan_ad, v_plan), v_gun);
    end if;
  else
    -- Henüz hiç ağırlamamış. BU CÜMLE EN ÖNEMLİSİ: merdiveni ilk basamağa
    -- çıkmadan önce göstermek zorundayız.
    v_karsilik := format('İlk ağırlaman seni %s yapar: keşifte %s sıra öne geçersin. '
                      || '%s ağırlamada %s planı %s gün ücretsiz olur.',
                         coalesce(v_son.ad,'Ev Sahibi'), coalesce(v_son.siralama_ek,5),
                         v_esik, coalesce(v_plan_ad, v_plan), v_gun);
  end if;

  return jsonb_build_object(
    'known', true,
    'agirlama', v_n,
    'mertebe', v_su.code, 'mertebe_adi', v_su.ad, 'mertebe_aciklama', v_su.aciklama,
    'siralama_ek', v_su.siralama_ek,
    'one_cikar_saat', v_su.one_cikar_saat,
    'istek_bedava', v_su.istek_bedava,
    'sonraki', v_son.code, 'sonraki_adi', v_son.ad,
    'sonraki_kalan', case when v_son.code is null then null else v_son.min_oturum - v_n end,
    'sonraki_aciklama', v_son.aciklama,
    'kazanilan_kredi', v_kredi,
    -- ▼ 249: plan hediyesi artık sözleşmenin parçası
    'plan_hediyesi', jsonb_build_object(
        'aktif', v_hediye_aktif,
        'biter_at', v_hediye_biter,
        'plan', v_plan, 'plan_adi', v_plan_ad, 'gun', v_gun,
        'esik', v_esik, 'kalan_agirlama', v_hediye_kalan),
    'karsilik_cumlesi', v_karsilik);
end $hs249$;

grant execute on function public.host_standing(uuid) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §2 — "HOST OLSAN NE OLUR" — MERDİVENİ TIRMANMADAN ÖNCE GÖSTER
--
-- `host_standing` var olan host'a bakıyor. Bu fonksiyon HENÜZ HOST OLMAYAN
-- kişiye bakıyor ve tek bir soruya cevap veriyor: "ağırlarsam ne kazanırım?"
--
-- Neden ayrı fonksiyon: `host_standing` bir DURUM raporu, bu bir TEKLİF.
-- İkisini tek fonksiyona sıkıştırmak, çağıran ekranın hangi hâlde olduğunu
-- tahmin etmesini gerektirirdi.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- host_rank_bonus   [etkin kaynak: 206_host_motoru.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_rank_bonus(p_host uuid)
returns int language sql stable security definer set search_path = public as $fn$
  select coalesce((
    select t.siralama_ek from host_tiers t
     where t.min_oturum <= (
       select count(*) from sessions s join requests r on r.id = s.request_id
        where r.host_id = p_host and s.status = 'completed')
     order by t.min_oturum desc limit 1), 0);
$fn$;

-- Konsiyerj ayrıcalığı: kendi misafir isteği kredi harcamaz.

-- ----------------------------------------------------------------------
-- request_credit_cost   [etkin kaynak: 252_ulasilabilirlik_ve_push_izni.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.request_credit_cost(p_user uuid, p_avail uuid default null)
returns int
language plpgsql stable security definer set search_path = public as $rcc252$
declare v_ham int;
begin
  -- Önce eski kural aynen çalışır: Konsiyerj ayrıcalığı + soğuk ağ indirimi.
  v_ham := public.request_credit_cost_ham(p_user, p_avail);
  if coalesce(v_ham, 1) = 0 then return 0; end if;

  -- Sonra 252: ilan belliyse ve o ilanın sahibine ANLIK ulaşamıyorsak,
  -- zamana bağlı bir eşleşmeyi satmıyoruz — bedel almıyoruz.
  -- 🔴 `ilan_ulasilabilir_mi` DEĞİL. Para kararı kanıt ister: yalnız host'un
  -- kendi cihazı bize "bildirim kapalı" dediyse bedeli düşürüyoruz.
  -- (Gerekçesi §2b'de; hatayı e2e nöbetçisi buldu.)
  if p_avail is not null and exists (
       select 1 from availabilities a
        where a.id = p_avail and public.kesin_ulasilamaz(a.host_id)) then
    return 0;
  end if;
  return v_ham;
end $rcc252$;

-- 🔴 249 bunu `authenticated`e AÇMIŞTI ve nöbetçi "yüzeyde yok ama istemciye
-- açık" diye uyarıyordu. Ölçtüm: ne app ne BO bu fonksiyonu çağırıyor
-- (grep: 0 sonuç). Tüm çağıranlar sunucu tarafında SECURITY DEFINER
-- fonksiyonlar — yani hak kapanınca hiçbir akış bozulmuyor.
-- Kimsenin kullanmadığı bir hak, güvenlik yüzeyi olmaktan başka iş görmez.
revoke all on function public.request_credit_cost(uuid, uuid) from public;
revoke all on function public.request_credit_cost(uuid, uuid) from authenticated;
revoke all on function public.request_credit_cost(uuid, uuid) from anon;
grant execute on function public.request_credit_cost(uuid, uuid) to service_role;

-- Misafire NEDEN bedava olduğunu söyleyen cümle, isteği göndermeden önce
-- okunabilsin. `ilan_ozeti` zaten ilan başına çağrılıyor (248 §4).

-- ----------------------------------------------------------------------
-- host_feature_hours   [etkin kaynak: 207_kopruler_ve_verilen_sozler.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_feature_hours(p_host uuid)
returns int language sql stable security definer set search_path = public as $fn$
  select coalesce((
    select t.one_cikar_saat from host_tiers t
     where t.min_oturum <= (
       select count(*) from sessions s join requests r on r.id = s.request_id
        where r.host_id = p_host and s.status = 'completed')
     order by t.min_oturum desc limit 1), 0);
$fn$;

-- İlan açıldığında mertebeye göre ücretsiz öne çıkarma.

-- ----------------------------------------------------------------------
-- trg_tier_feature   [etkin kaynak: 207_kopruler_ve_verilen_sozler.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_tier_feature()
returns trigger language plpgsql security definer set search_path = public as $fn$
declare v_saat int;
begin
  v_saat := public.host_feature_hours(new.host_id);
  if v_saat > 0 and new.featured_until is null then
    update availabilities set featured_until = now() + make_interval(hours => v_saat)
     where id = new.id;
  end if;
  return null;
end $fn$;

drop trigger if exists trg_tier_feature_on_insert on availabilities;
create trigger trg_tier_feature_on_insert
  after insert on availabilities
  for each row execute function public.trg_tier_feature();

-- `host_standing` artık gerçek alanı döndürsün (ekran uydurmasın).

-- ----------------------------------------------------------------------
-- tier_promise_check   [etkin kaynak: 207_kopruler_ve_verilen_sozler.sql]
-- ----------------------------------------------------------------------
create or replace function public.tier_promise_check()
returns table (mertebe text, soz text, neden text)
language sql stable security definer set search_path = public as $fn$
  select t.code::text, 'siralama_ek'::text, 'kimse host_rank_bonus okumuyor'::text
    from host_tiers t where t.siralama_ek > 0
     and not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                      where n.nspname='public' and p.prokind='f'
                        and p.proname <> 'host_rank_bonus'
                        and pg_get_functiondef(p.oid) ~ 'host_rank_bonus')
  union all
  select t.code::text, 'istek_bedava'::text, 'kimse request_credit_cost okumuyor'::text
    from host_tiers t where t.istek_bedava
     and not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                      where n.nspname='public' and p.prokind='f'
                        and p.proname <> 'request_credit_cost'
                        and pg_get_functiondef(p.oid) ~ 'request_credit_cost')
  union all
  select t.code::text, 'one_cikar_saat'::text, 'kimse host_feature_hours okumuyor'::text
    from host_tiers t where t.one_cikar_saat > 0
     and not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                      where n.nspname='public' and p.prokind='f'
                        and p.proname <> 'host_feature_hours'
                        and pg_get_functiondef(p.oid) ~ 'host_feature_hours')
  union all
  select t.code::text, 'ekstra_slot'::text, 'bu soz KALDIRILDI, hala 0 disinda deger var'::text
    from host_tiers t where coalesce(t.ekstra_slot,0) <> 0;
$fn$;

grant execute on function public.tier_promise_check() to service_role;

do $$
declare v text;
begin
  select string_agg(mertebe || '.' || soz || ': ' || neden, ' · ') into v from public.tier_promise_check();
  if v is not null then raise exception '207: TUTULMAYAN SOZ → %', v; end if;
  raise notice '207: host_tiers''teki her soz bir yerde UYGULANIYOR';
end $$;

-- ----------------------------------------------------------------------
-- request_credit_topup   [etkin kaynak: 208_donem_devri_ve_kalibrasyon.sql]
-- ----------------------------------------------------------------------
create or replace function public.request_credit_topup(p_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_uid uuid := auth.uid(); v_son timestamptz; v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select max(created_at) into v_son from credit_requests
   where user_id = v_uid and status = 'pending';
  if v_son is not null and v_son > now() - interval '24 hours' then
    return jsonb_build_object('ok', false, 'neden', 'zaten_bekliyor',
      'mesaj', 'Bekleyen bir kredi talebin zaten var. Sonuçlanınca haber vereceğiz.');
  end if;

  insert into credit_requests (user_id, note) values (v_uid, left(coalesce(p_note,''), 280))
  returning id into v_id;

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_uid, 'system', 'Kredi talebin alındı',
          'Beta döneminde talepler elle değerlendiriliyor. Sonuçlanınca burada göreceksin.',
          'credit_request', v_id);

  return jsonb_build_object('ok', true, 'id', v_id,
    'mesaj', 'Talebin alındı. Beta döneminde elle değerlendiriliyor.');
end $fn$;

insert into rpc_client_surface (fn_name, client, note)
values ('request_credit_topup','app','Kredi talebi — dogrudan notifications insert''in yerine')
on conflict (fn_name) do nothing;


-- ============================================================
-- 3) KALİBRASYON — kredi oranı TAHMİNLE değil ÖLÇÜMLE ayarlansın
-- ============================================================
-- 206'da "ağırlama = 3 kredi" dedim ve gerekçesi şuydu: bir istek 1
-- kredi harcar, her istek oturuma dönüşmez, ~1/3 dönüşümle 3 kredi ≈
-- bir tamamlanmış misafir deneyimi.
--
-- ⚠️ O "1/3" BİR TAHMİNDİ. Gerçek dönüşümü ölçmeden oranı sabitlemek,
-- bu ürünün en sık hatasının (ölçmeden karar) ekonomiye taşınmış hâli
-- olurdu. Bu fonksiyon gerçek sayıyı verir; BO onu gösterir ve oran
-- deploy'suz değişir.

-- ----------------------------------------------------------------------
-- host_credit_stats   [etkin kaynak: 208_donem_devri_ve_kalibrasyon.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_credit_stats(p_gun int default 90)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_istek int; v_kabul int; v_oturum int;
  v_basilan int; v_harcanan int; v_oran numeric; v_onerilen int;
  v_mevcut int := coalesce((select (value #>> '{}')::int from beta_settings
                             where key='host_credit_per_session'), 3);
begin
  select count(*) into v_istek from requests where created_at >= now() - make_interval(days => p_gun);
  select count(*) into v_kabul from requests
   where created_at >= now() - make_interval(days => p_gun) and status in ('accepted','completed');
  select count(*) into v_oturum from sessions s
   where s.status = 'completed' and s.completed_at >= now() - make_interval(days => p_gun);

  select coalesce(sum(delta),0) into v_basilan from credit_ledger
   where reason = 'hosted_session' and created_at >= now() - make_interval(days => p_gun);
  select coalesce(-sum(delta),0) into v_harcanan from credit_ledger
   where reason = 'request_hold' and created_at >= now() - make_interval(days => p_gun);

  -- Dönüşüm: kaç istek bir tamamlanmış oturuma dönüştü?
  v_oran := case when v_istek > 0 then v_oturum::numeric / v_istek else null end;

  -- Önerilen oran = 1 / dönüşüm (yani "bir deneyim için kaç istek gerekir").
  -- Veri yoksa ÖNERİ YOK — uydurulmuş bir sayı, mevcut tahminden kötüdür.
  v_onerilen := case when v_oran is null or v_oran = 0 then null
                     else greatest(1, least(10, round(1 / v_oran)::int)) end;

  return jsonb_build_object(
    'gun', p_gun,
    'istek', v_istek, 'kabul', v_kabul, 'oturum', v_oturum,
    'donusum', v_oran,
    'basilan_kredi', v_basilan, 'harcanan_kredi', v_harcanan,
    'net', v_basilan - v_harcanan,
    'mevcut_oran', v_mevcut,
    'onerilen_oran', v_onerilen,
    'yeterli_veri', v_istek >= 30,
    'yorum', case
      when v_istek < 30 then format('Henüz %s istek var; oran değiştirmek için en az 30 gerekir.', v_istek)
      when v_onerilen is null then 'Hiç tamamlanmış oturum yok; dönüşüm hesaplanamıyor.'
      when v_onerilen = v_mevcut then format('Ölçülen dönüşüm mevcut oranı (%s) doğruluyor.', v_mevcut)
      else format('Ölçülen dönüşüm %s%%. Bir deneyim ≈ %s istek; oranı %s → %s yapmayı düşün.',
                  round(v_oran * 100), v_onerilen, v_mevcut, v_onerilen) end);
end $fn$;


-- ============================================================
-- 4) SINIR
-- ============================================================
do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '208: sinir uygulandi — % fonksiyon kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- partner_k   [etkin kaynak: 209_saglayici_modulu.sql]
-- ----------------------------------------------------------------------
create or replace function public.partner_k()
returns int language sql stable security definer set search_path = public as $fn$
  select coalesce((select (value #>> '{}')::int from beta_settings where key='partner_k_threshold'), 5);
$fn$;


-- ============================================================
-- 2) ORTAK KAPI — tek yerde, üç ekranda aynı
-- ============================================================
-- Her sağlayıcı fonksiyonuna aynı `if not exists ... raise` bloğunu
-- kopyalamak, 204'te öğrendiğimiz hatanın aynısı: dördüncü fonksiyon
-- yazıldığında unutulur.

-- ----------------------------------------------------------------------
-- partner_gate   [etkin kaynak: 213_saglayici_kurumsal_katman.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.partner_gate(p_user uuid, p_lounge uuid)
    returns boolean language plpgsql stable security definer set search_path = public as $fn$
    declare v_acik boolean; v_uid uuid;
    begin
      select f.enabled into v_acik from feature_flags f where f.key = 'partner_channel';
      if not coalesce(v_acik, true) then
        return false;                       -- kill switch: kanal kapalı
      end if;
      begin
        v_uid := public.partner_gate_preflag(p_user, p_lounge);
      exception when others then
        if sqlerrm = 'not_partner' then
          return false;                     -- yetkisiz: veri yok, hata da yok
        end if;
        raise;                              -- başka her hata GÖRÜNÜR kalır
      end;
      return v_uid is not null;
    end $fn$;
  $ddl$;
  raise notice '213: partner_gate govdesi onarildi (bayrak ACIK iken de calisiyor)';
end $blok$;


-- ------------------------------------------------------------
-- 0b) 209'UN BEŞ ÇAĞIRICISI — kaynak üzerinden ONARIM
-- ------------------------------------------------------------
-- 🔴 NEDEN GÖVDELERİ BU DOSYAYA KOPYALAMIYORUM: beş fonksiyonun
-- toplam ~220 satırlık iş mantığını 213'e kopyalasaydım, 209 ile 213
-- iki ayrı gerçek taşımaya başlardı ve bir sonraki düzeltme birinde
-- yapılıp diğerinde unutulurdu. Aynı veriyi iki dosyanın iki farklı
-- yolla taşıması, er ya da geç ikisinin ayrışması demektir (bu dersi
-- `app/partner/actions.js` zaten yazmış).
--
-- Bunun yerine tek satırlık çağrı kalıbı, `pg_get_functiondef` ile
-- okunan GERÇEK gövde üzerinde değiştiriliyor. Yama körlemesine
-- değil: kalıp bulunamazsa DO bloğu EXCEPTION fırlatır. Sessizce
-- hiçbir şey yapmayan bir onarım, onarım değildir — yeşil yanan bir
-- yalandır.
do $$
declare
  v_hedef text[] := array['partner_payout','venue_gate_report','venue_lost_demand',
                          'venue_inbound_wave','venue_rule_compliance'];
  v_ad    text;
  v_def   text;
  v_yeni  text;
  v_ret   text;
  v_eski  constant text := 'v_uid := public.partner_gate(p_user, p_lounge_id);';
  v_yama  constant text :=
    'if not coalesce(public.partner_gate(p_user, p_lounge_id), false) then '
 || 'return jsonb_build_object(''known'', false, ''yetki'', false, ''satirlar'', ''[]''::jsonb, '
 || '''not'', ''Bu salon icin yetkiniz yok ya da partner_channel bayragi kapali.''); end if; '
 || 'v_uid := coalesce(p_user, auth.uid());';
  v_sayac int := 0;
begin
  foreach v_ad in array v_hedef loop
    select pg_get_functiondef(p.oid), pg_get_function_result(p.oid)
      into v_def, v_ret
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = v_ad
     limit 1;

    if v_def is null then
      raise exception '213: onarilacak fonksiyon YOK → %', v_ad;
    end if;

    -- Yama yalnız jsonb dönen fonksiyonlara uygulanabilir; başka bir
    -- dönüş tipi varsa `return jsonb_build_object(...)` derlenmez.
    if v_ret <> 'jsonb' then
      raise exception '213: % jsonb DEGIL (%) — yama gecersiz', v_ad, v_ret;
    end if;

    if position(v_yama in v_def) > 0 then
      raise notice '213: % zaten onarilmis — atlandi', v_ad;
      continue;
    end if;

    if position(v_eski in v_def) = 0 then
      raise exception '213: % icinde beklenen kapi cagrisi BULUNAMADI — kalip degismis olabilir; yama korlemesine uygulanmayacak.', v_ad;
    end if;

    v_yeni := replace(v_def, v_eski, v_yama);
    execute v_yeni;
    v_sayac := v_sayac + 1;
  end loop;
  raise notice '213: 209 kapi cagrisi % fonksiyonda onarildi', v_sayac;
end $$;

-- ----------------------------------------------------------------------
-- venue_gate_report   [etkin kaynak: 209_saglayici_modulu.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_gate_report(
  p_lounge_id uuid, p_gun int default 90, p_user uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid uuid; v_ven uuid; v_k int := public.partner_k();
  v_satir jsonb; v_toplam int;
begin
  v_uid := public.partner_gate(p_user, p_lounge_id);
  select venue_id into v_ven from lounges where id = p_lounge_id;
  if v_ven is null then
    return jsonb_build_object('known', false, 'neden', 'salon bir venue kaydina bagli degil');
  end if;

  select jsonb_agg(x order by (x ->> 'toplam')::int desc), sum((x ->> 'toplam')::int)
    into v_satir, v_toplam
  from (
    select jsonb_build_object(
             'program', coalesce(p.name, 'Bilinmiyor'),
             'program_kodu', p.code,
             'tier', r.card_tier,
             'toplam', count(*)::int,
             'girdi', count(*) filter (where r.entered)::int,
             'geri_cevrildi', count(*) filter (where not coalesce(r.entered,true))::int,
             'misafir_kabul', count(*) filter (where r.guest_accepted)::int,
             'ucret_alindi', count(*) filter (where r.fee_charged)::int,
             -- ⚠️ `fee_amount` TEXT (ölçüldü: information_schema).
             -- `avg(text)` yok — nöbetçi 42883 verdi. Sayıya çevrilebilen
             -- değerleri süzüyoruz; "30 EUR" gibi serbest metin girilmiş
             -- olabilir ve onu sayı sanmak, uydurmanın en sinsi hâli.
             'ortalama_ucret', round(avg(
                 case when r.fee_amount ~ '^[0-9]+([.,][0-9]+)?$'
                      then replace(r.fee_amount, ',', '.')::numeric end)
               filter (where r.fee_charged))
           ) as x
      from lounge_field_reports r
      left join lounge_programs p on p.id = r.program_id
     where r.venue_id = v_ven
       and r.created_at >= now() - make_interval(days => p_gun)
     group by p.name, p.code, r.card_tier
    having count(*) >= v_k          -- k-anonimite, SATIR düzeyinde
  ) q;

  return jsonb_build_object(
    'known', true,
    'gun', p_gun,
    'k_esigi', v_k,
    'toplam', coalesce(v_toplam, 0),
    'satirlar', coalesce(v_satir, '[]'::jsonb),
    'not', case when v_satir is null
      then format('Son %s günde %s kişiden az veri taşıyan satırlar gizlendi; gösterilecek satır kalmadı.', p_gun, v_k)
      else 'Her satır en az ' || v_k || ' kayıt taşıyor. Daha az veri taşıyan programlar gizlendi.' end);
end $fn$;


-- ============================================================
-- 5) Ö2 · KAÇAN TALEP — "girmek isteyip giremeyen kaç kişi vardı?"
-- ============================================================
-- Panel bugün yalnız GERÇEKLEŞENİ gösteriyor. İşletmecinin sorduğu
-- soru gerçekleşmeyen. Yeni veri gerekmiyor: `visits` × `availabilities`.

-- ----------------------------------------------------------------------
-- venue_lost_demand   [etkin kaynak: 209_saglayici_modulu.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_lost_demand(
  p_lounge_id uuid, p_gun int default 30, p_user uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid uuid; v_ap text; v_k int := public.partner_k();
  v_satir jsonb; v_kacan int; v_karsilanan int;
begin
  v_uid := public.partner_gate(p_user, p_lounge_id);
  select airport_code into v_ap from lounges where id = p_lounge_id;
  if v_ap is null then return jsonb_build_object('known', false); end if;

  select jsonb_agg(x order by (x ->> 'tarih')), sum((x ->> 'kacan')::int), sum((x ->> 'karsilanan')::int)
    into v_satir, v_kacan, v_karsilanan
  from (
    select jsonb_build_object(
             'tarih', v.visit_date,
             'yolcu', count(distinct v.user_id)::int,
             'karsilanan', count(distinct v.user_id) filter (where exists (
                 select 1 from requests r join sessions s on s.request_id = r.id
                  where r.guest_id = v.user_id and s.status = 'completed'
                    and s.completed_at::date = v.visit_date))::int,
             'kacan', count(distinct v.user_id) filter (where not exists (
                 select 1 from requests r join sessions s on s.request_id = r.id
                  where r.guest_id = v.user_id and s.status = 'completed'
                    and s.completed_at::date = v.visit_date))::int,
             'bos_slot', coalesce((
                 select sum(greatest(a.slots - coalesce(a.filled,0), 0))::int
                   from availabilities a
                  where a.lounge_id = p_lounge_id and a.avail_date = v.visit_date and a.active), 0)
           ) as x
      from visits v
      join users u on u.id = v.user_id
     where v.airport_code = v_ap
       and v.visit_date between current_date - p_gun and current_date
       and coalesce(u.is_staff,false) = false
       and u.deleted_at is null
     group by v.visit_date
    having count(distinct v.user_id) >= v_k     -- k-anonimite, GÜN düzeyinde
  ) q;

  return jsonb_build_object(
    'known', true, 'havalimani', v_ap, 'gun', p_gun, 'k_esigi', v_k,
    'kacan', coalesce(v_kacan,0), 'karsilanan', coalesce(v_karsilanan,0),
    'gunler', coalesce(v_satir, '[]'::jsonb),
    'baslik', case when coalesce(v_kacan,0) = 0
      then 'Bu dönemde kaçan talep görünmüyor.'
      else format('Son %s günde %s yolcu %s''te salon bulamadı.', p_gun, v_kacan, v_ap) end);
end $fn$;


-- ============================================================
-- 6) Ö3 · 72 SAATLİK GELEN DALGA — tek ileriye dönük ekran
-- ============================================================
-- Vardiya planlayan müdürün abonelik ödeme sebebi. `visits` +
-- `flight_cache` zaten dolu; yeni veri yok.

-- ----------------------------------------------------------------------
-- venue_inbound_wave   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.venue_inbound_wave(
  p_lounge_id uuid, p_saat int default 72, p_user uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid uuid; v_ap text; v_k int := public.partner_k(); v_satir jsonb;
begin
  v_uid := public.partner_gate(p_user, p_lounge_id);
  select airport_code into v_ap from lounges where id = p_lounge_id;
  if v_ap is null then return jsonb_build_object('known', false); end if;

  select jsonb_agg(x order by (x ->> 'saat'))
    into v_satir
  from (
    -- 🔴 `group by 1` YAZMIŞTIM VE NÖBETÇİ YAKALADI:
    --     ERROR: aggregate functions are not allowed in GROUP BY
    -- Çünkü 1. seçim öğesi, İÇİNDE toplama fonksiyonu barındıran
    -- `jsonb_build_object(...)`. Konum numarasıyla gruplamak kısa
    -- yoldur ama ifadenin ne olduğunu gizler; ifadeyi AÇIKÇA yazmak
    -- hem çalışır hem okunur.
    select jsonb_build_object(
             'saat', to_char(date_trunc('hour',
                 coalesce(v.scheduled_departure, public.yerel_an(v.visit_date, v.time_from, v.airport_code))),
               'YYYY-MM-DD HH24:00'),
             'yolcu', count(distinct v.user_id)::int,
             'terminal', coalesce(mode() within group (order by v.terminal), '—')
           ) as x
      from visits v
      join users u on u.id = v.user_id
     where v.airport_code = v_ap
       and coalesce(v.scheduled_departure, public.yerel_an(v.visit_date, v.time_from, v.airport_code))
           between now() and now() + make_interval(hours => p_saat)
       and coalesce(u.is_staff,false) = false
       and u.deleted_at is null
     group by date_trunc('hour',
         coalesce(v.scheduled_departure, public.yerel_an(v.visit_date, v.time_from, v.airport_code)))
    having count(distinct v.user_id) >= v_k
  ) q;

  return jsonb_build_object(
    'known', true, 'havalimani', v_ap, 'saat', p_saat, 'k_esigi', v_k,
    'saatler', coalesce(v_satir, '[]'::jsonb),
    'not', 'Yalnız uygulamaya seyahat girmiş yolcular sayılır — havalimanının toplam trafiği DEĞİLDİR.');
end $fn$;

-- ── lounge_access_decision_v3 ─────────────────────────────────────────────

-- ----------------------------------------------------------------------
-- venue_rule_compliance   [etkin kaynak: 209_saglayici_modulu.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_rule_compliance(
  p_lounge_id uuid, p_gun int default 180, p_user uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_uid uuid; v_ven uuid; v_k int := public.partner_k(); v_satir jsonb;
begin
  v_uid := public.partner_gate(p_user, p_lounge_id);
  select venue_id into v_ven from lounges where id = p_lounge_id;
  if v_ven is null then return jsonb_build_object('known', false); end if;

  select jsonb_agg(x order by (x ->> 'sapma')::int desc)
    into v_satir
  from (
    select jsonb_build_object(
             'program', p.name,
             'resmi_kabul', a.accepted,
             'kapida_giren', count(*) filter (where r.entered)::int,
             'kapida_cevrilen', count(*) filter (where not coalesce(r.entered,true))::int,
             -- SAPMA: resmî kural "kabul" diyor ama kapıda çevrilmiş,
             -- ya da tersi. İki yön de bizim için bilgi.
             'sapma', case when a.accepted
                           then count(*) filter (where not coalesce(r.entered,true))::int
                           else count(*) filter (where r.entered)::int end,
             'yon', case when a.accepted then 'kabul deniyor ama cevriliyor'
                                          else 'kabul edilmiyor deniyor ama giriliyor' end
           ) as x
      from lounge_field_reports r
      join lounge_programs p on p.id = r.program_id
      left join lounge_venue_acceptance a on a.venue_id = r.venue_id and a.program_id = r.program_id
     where r.venue_id = v_ven
       and r.created_at >= now() - make_interval(days => p_gun)
     group by p.name, a.accepted
    having count(*) >= v_k
  ) q;

  return jsonb_build_object(
    'known', true, 'gun', p_gun, 'k_esigi', v_k,
    'satirlar', coalesce(v_satir, '[]'::jsonb),
    'not', 'Sapma iki yönlü okunur: resmî kural yanlış olabilir ya da kapıda uygulama farklı olabilir. İkisi de düzeltilmeye değer.');
end $fn$;


-- ============================================================
-- 8) OPERATÖR ROLL-UP — çok salonlu işletmeci bugün dışarıda
-- ============================================================
-- IGA / TAV / Çelebi gibi işletmeciler hedef müşteri ama panel
-- `links[0]` diyerek yalnız BİRİNCİ salonu gösteriyordu.

-- ----------------------------------------------------------------------
-- partner_lounges   [etkin kaynak: 209_saglayici_modulu.sql]
-- ----------------------------------------------------------------------
create or replace function public.partner_lounges(p_user uuid default null)
returns table (lounge_id uuid, ad text, havalimani text, terminal text, isletmeci text, rol text)
language sql stable security definer set search_path = public as $fn$
  select l.id, l.name::text, l.airport_code::text, l.terminal::text,
         coalesce(v.operator, '—')::text, lp.role::text
    from lounge_partners lp
    join lounges l on l.id = lp.lounge_id
    left join lounge_venues v on v.id = l.venue_id
   where lp.user_id = coalesce(p_user, auth.uid())
   order by l.airport_code, l.name;
$fn$;


-- ============================================================
-- 9) YÜZEY — sağlayıcı fonksiyonları BO oturumundan çağrılacak
-- ============================================================
-- 🔴 Bunlar `service_role` ile DEĞİL, sağlayıcının KENDİ oturumuyla
-- çağrılmalı — ancak o zaman `auth.uid()` dolar ve RLS arka duvar
-- görevi görür. BO tarafı `sbSession()`'a çevrildi.
insert into rpc_client_surface (fn_name, client, note) values
  ('partner_demand','backoffice_session','Saglayici paneli — sbSession ile'),
  ('partner_payout','backoffice_session','Hakedis'),
  ('partner_lounges','backoffice_session','Cok salonlu isletmeci secici'),
  ('venue_gate_report','backoffice_session','Kapi raporu'),
  ('venue_lost_demand','backoffice_session','Kacan talep'),
  ('venue_inbound_wave','backoffice_session','72 saatlik gelen dalga'),
  ('venue_rule_compliance','backoffice_session','Kural uyum denetimi')
on conflict (fn_name) do update set client = excluded.client, note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '209: sinir uygulandi — % fonksiyon kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- my_plan   [etkin kaynak: 287_planim_enum_metin_karsilastirma.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.my_plan(p_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := public.kimlik(p_user);
  -- 🔴 22 AGUSTOS: `text` idi, `etkin_plan()` `plan_type` donuyor.
  -- plpgsql atamada ortuk cevirdigi icin PATLAMIYORDU ama nobetci
  -- hakli: cagirici, cagirdigi seyin sozlesmesini yazmalidir —
  -- yoksa donus tipi degistigi gun sessizce yanlis calisir.
  v_satin text; v_etkin plan_type; v_p plan_catalog%rowtype;
  v_esik int; v_plan_hediye text; v_gun int;
  v_agir int; v_neden text;
  v_g plan_grants%rowtype;
  v_son timestamptz;
  v_kaldi int;
begin
  if v_uid is null then return jsonb_build_object('known', false); end if;

  select coalesce(u.plan::text,'yolcu') into v_satin from users u where u.id = v_uid;
  if not exists (select 1 from plan_catalog where plan::text = v_satin and aktif) then
    v_satin := 'yolcu';
  end if;

  v_esik := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_sessions'), 2);
  v_plan_hediye := coalesce((select value #>> '{}' from beta_settings where key='host_free_upgrade_plan'), 'sik_ucan');
  v_gun := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_days'), 30);

  v_etkin := public.etkin_plan(v_uid)::text;

  select * into v_g from plan_grants
   where user_id = v_uid and bitti_at is null and iptal_at is null and biter_at > now()
   limit 1;

  -- İlerleme sayacı: son hediyeden BU YANA (takvim ayı değil).
  select coalesce(max(coalesce(bitti_at, biter_at)), '-infinity'::timestamptz)
    into v_son from plan_grants where user_id = v_uid and kaynak='agirlama';
  select count(*) into v_agir
    from sessions s join requests r on r.id = s.request_id
   where r.host_id = v_uid and s.status='completed' and s.completed_at > v_son;

  if v_g.id is not null then
    v_kaldi := greatest(0, ceil(extract(epoch from (v_g.biter_at - now()))/86400)::int);
    v_neden := format('%s ayrıcalıkları %s gün daha senin — ücretsiz. %s tarihinde eski planına dönersin.',
                      (select ad from plan_catalog where plan = v_etkin),
                      v_kaldi,
                      to_char(timezone('Europe/Istanbul', v_g.biter_at), 'DD.MM.YYYY'));
  else
    v_kaldi := null;
    v_neden := case
      when v_agir > 0 then format('%s kişi ağırladın. %s ağırlamada üst plan 1 ay ücretsiz açılıyor.', v_agir, v_esik)
      else format('Birini ağırla — %s ağırlamada üst plan %s gün boyunca ücretsiz açılır.', v_esik, v_gun) end;
  end if;

  select * into v_p from plan_catalog where plan = v_etkin;

  return jsonb_build_object(
    'known', true,
    'satin_alinan', v_satin,
    'etkin', v_etkin,
    'ad', v_p.ad,
    'aylik_kredi', v_p.monthly_credits,
    'fiyat_try', v_p.price_try,
    'yillik_try', v_p.yillik_try,
    'haklar', v_p.perks,
    'kacirilan_sikligi', v_p.kacirilan_sikligi,
    'one_cikarma_ayda', v_p.one_cikarma_ayda,
    'yanma_uyarilari', to_jsonb(v_p.yanma_uyarilari),
    'ucus_dogrulama_ayda', v_p.ucus_dogrulama_ayda,
    'kart_siniri', v_p.kart_siniri,
    'oncelikli_destek', v_p.oncelikli_destek,
    'bu_ay_agirlama', v_agir,
    'esik', v_esik,
    'hediye_gun', v_gun,
    'ucretsiz_yukseltme', (v_g.id is not null and v_etkin::text <> v_satin),
    'hediye_biter', v_g.biter_at,
    'hediye_gun_kaldi', v_kaldi,
    'hediye_kaynak', v_g.kaynak,
    'neden', v_neden);
end $function$

-- ----------------------------------------------------------------------
-- subscription_plans   [etkin kaynak: 220_plan_katalogu_ve_dil.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.subscription_plans(p_lang text default 'tr')
returns jsonb language sql stable security definer set search_path = public as $fn$
  select jsonb_agg(jsonb_build_object(
           'plan', p.plan, 'ad',
             case when lower(coalesce(p_lang,'tr')) = 'en'
                  then coalesce(nullif(p.ad_en,''), p.ad)
                  else p.ad end,
           'aylik_kredi', p.monthly_credits,
           'aylik_fiyat', p.price_try, 'yillik_fiyat', p.yillik_try,
           'yillik_indirim_yuzde', case when p.price_try > 0 and p.yillik_try > 0
             then round(100 - (p.yillik_try::numeric / (p.price_try * 12) * 100)) end,
           'haklar',
             case when lower(coalesce(p_lang,'tr')) = 'en'
                       and jsonb_array_length(coalesce(p.perks_en,'[]'::jsonb)) > 0
                  then p.perks_en else p.perks end,
           'sira', p.sort_order,
           'kacirilan_sikligi', p.kacirilan_sikligi,
           'oncelikli_destek', p.oncelikli_destek)
         order by p.sort_order)
    from plan_catalog p where p.aktif;
$fn$;
grant execute on function public.subscription_plans(text) to authenticated;


-- ════════════════════════════════════════════════════════════════════════
-- NÖBETÇİ — varsayılan bir daha ölü plana bakmasın
--
-- Bu kusur "sil değil pasife al" kararının yan etkisiydi ve iki sürüm
-- boyunca kimse görmedi. Bir daha görünmez kalmasın.
-- ════════════════════════════════════════════════════════════════════════
do $$
declare v_def text; v_olu int; v_aktif_plan int;
begin
  select column_default into v_def from information_schema.columns
   where table_schema='public' and table_name='users' and column_name='plan';

  if v_def is null or not exists (
       select 1 from plan_catalog p
        where p.aktif and v_def like '%''' || p.plan::text || '''%') then
    raise exception '220: users.plan varsayilani (%) AKTIF bir plana bakmiyor', coalesce(v_def,'(yok)');
  end if;

  select count(*) into v_olu from users u
   where exists (select 1 from plan_catalog p
                  where p.plan = u.plan and coalesce(p.aktif,false) = false);
  if v_olu > 0 then
    raise exception '220: % kullanici hala PASIF planda', v_olu;
  end if;

  select count(*) into v_aktif_plan from plan_catalog where aktif;
  if v_aktif_plan = 0 then
    raise exception '220: aktif plan YOK — katalog bos';
  end if;

  raise notice '220: varsayilan % · pasif planda kullanici 0 · aktif plan %', v_def, v_aktif_plan;
end $$;

-- ----------------------------------------------------------------------
-- send_missed_value_digest   [etkin kaynak: 210_abonelik_push_ve_kapsam.sql]
-- ----------------------------------------------------------------------
create or replace function public.send_missed_value_digest(p_zorla boolean default false)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  r record;
  v_gonderilen int := 0;
  v_atlanan int := 0;
  v_v jsonb;
  v_sik text;
begin
  for r in
    select distinct u.id as uid
      from users u
     where u.deleted_at is null
       and coalesce(u.is_staff, false) = false
       and exists (select 1 from availabilities a where a.host_id = u.id)
  loop
    -- Plan sıklığı
    select coalesce(p.kacirilan_sikligi, 'aylik') into v_sik
      from users u left join plan_catalog p on p.plan = u.plan and p.aktif
     where u.id = r.uid;

    if not p_zorla then
      -- (a) tekrar kapısı — sıklığa göre
      if exists (
        select 1 from notifications n
         where n.user_id = r.uid and n.ref_type = 'missed_digest'
           and n.created_at > now() - case v_sik
                 when 'anlik'    then interval '1 day'
                 when 'haftalik' then interval '7 days'
                 else                 interval '30 days' end
      ) then
        v_atlanan := v_atlanan + 1;
        continue;
      end if;
    end if;

    -- Kişinin kendi gözünden hesapla
    perform set_config('request.jwt.claims',
      json_build_object('sub', r.uid, 'role', 'authenticated')::text, true);
    v_v := public.host_missed_value(case v_sik when 'anlik' then 3 when 'haftalik' then 7 else 30 end);
    perform set_config('request.jwt.claims', '', true);

    -- (b) sıfırsa gönderme
    if coalesce((v_v ->> 'kisi')::int, 0) = 0 then
      v_atlanan := v_atlanan + 1;
      continue;
    end if;

    insert into notifications (user_id, category, title, body, ref_type)
    values (r.uid, 'system',
            format('%s kişi seni bulamadı', v_v ->> 'kisi'),
            coalesce(v_v ->> 'baslik', '') || ' İlan açmak 20 saniye.',
            'missed_digest');
    v_gonderilen := v_gonderilen + 1;
  end loop;

  return jsonb_build_object('gonderilen', v_gonderilen, 'atlanan', v_atlanan);
end $fn$;

comment on function public.send_missed_value_digest(boolean) is
  'Haftalik "kacirdiklarin" hatirlatmasi. BO cron ya da pg_cron ile gunde bir kez cagrilir; sıklık kapısı fonksiyonun kendi icinde. Yalniz service_role.';


-- ============================================================
-- 4) KAPSAM BOŞLUĞU — ÖLÇÜLÜYOR, UYDURULMUYOR
-- ============================================================
-- 🔴 "Kart ağları kapsamını 9 havalimanından 20'ye çıkar" maddesi
-- listede vardı. YAPMADIM VE SEBEBİ ÖNEMLİ:
--
-- Priority Pass'in belirli bir salonu kabul edip etmediği, KAYNAĞI
-- olan bir olgudur. Elimde o kaynak yok. 11 havalimanı için kabul
-- satırı yazmak, ürünün tek cümlesini ("kapıda ne olacağını
-- biliyoruz") bir yalana çevirirdi — ve bunu kullanıcı kapıda,
-- reddedilerek öğrenirdi. Bu ürün için yapılabilecek en pahalı hata
-- budur.
--
-- YAPTIĞIM ŞEY: boşluğu GÖRÜNÜR ve ÖLÇÜLEBİLİR kılmak. Hangi salonun
-- hangi kart ağı için verisi eksik — liste burada. Kaynak bulundukça
-- BO'dan girilir ve bu fonksiyonun çıktısı kendiliğinden küçülür.

-- ----------------------------------------------------------------------
-- coverage_gaps   [etkin kaynak: 210_abonelik_push_ve_kapsam.sql]
-- ----------------------------------------------------------------------
create or replace function public.coverage_gaps(p_ulke text default 'Türkiye')
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_hava int; v_kapsanan int; v_bosluk jsonb; v_eksik int;
begin
  select count(distinct v.airport_code) into v_hava
    from lounge_venues v join airports a on a.code = v.airport_code
   where v.active and (p_ulke is null or a.country = p_ulke);

  select count(distinct v.airport_code) into v_kapsanan
    from lounge_venue_acceptance ac
    join lounge_venues v on v.id = ac.venue_id
    join lounge_programs p on p.id = ac.program_id
    join airports a on a.code = v.airport_code
   where ac.active and ac.accepted and p.kind = 'card_program'
     and v.active and (p_ulke is null or a.country = p_ulke);

  select jsonb_agg(x order by (x ->> 'salon')::int desc), sum((x ->> 'salon')::int)
    into v_bosluk, v_eksik
  from (
    select jsonb_build_object(
             'havalimani', v.airport_code,
             'sehir', max(a.city),
             'salon', count(*)::int,
             'ornek', max(v.name)
           ) as x
      from lounge_venues v
      join airports a on a.code = v.airport_code
     where v.active and (p_ulke is null or a.country = p_ulke)
       and not exists (
         select 1 from lounge_venue_acceptance ac
         join lounge_programs p on p.id = ac.program_id
          where ac.venue_id = v.id and ac.active and p.kind = 'card_program')
     group by v.airport_code
  ) q;

  return jsonb_build_object(
    'ulke', p_ulke,
    'havalimani', v_hava,
    'kart_agi_kapsanan', v_kapsanan,
    'kapsama_yuzde', case when v_hava > 0 then round(v_kapsanan::numeric / v_hava * 100) end,
    'eksik_salon', coalesce(v_eksik, 0),
    'bosluklar', coalesce(v_bosluk, '[]'::jsonb),
    'not', 'Bu liste EKSİK VERİYİ gösterir, "kabul edilmiyor"u DEĞİL. Kaynak bulunmadan kabul satırı yazılmaz.');
end $fn$;


