-- ============================================================
insert into rpc_client_surface (fn_name, client, note) values
  ('my_plan','app','Etkin plan + ucretsiz yukseltme durumu'),
  ('subscription_plans','app','Abonelik planlari — plan_catalog yerine')
on conflict (fn_name) do nothing;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '210: sinir uygulandi — % fonksiyon kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- cns_merge_venue   [etkin kaynak: 211_kart_aglari_kaynaktan.sql]
-- ----------------------------------------------------------------------
create or replace function public.cns_merge_venue(p_kaynak uuid, p_hedef uuid, p_gerekce text)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if p_kaynak is null or p_hedef is null or p_kaynak = p_hedef then return; end if;

  update lounge_venue_acceptance a set venue_id = p_hedef
   where a.venue_id = p_kaynak
     and not exists (select 1 from lounge_venue_acceptance b
                      where b.venue_id = p_hedef and b.program_id = a.program_id);
  delete from lounge_venue_acceptance where venue_id = p_kaynak;

  update lounge_guest_rules set venue_id = p_hedef where venue_id = p_kaynak;
  update availabilities      set venue_id = p_hedef where venue_id = p_kaynak;
  -- ⚠️ `lounges` (katalog kaydı) taşınırken TEKİLLEŞTİRİLMELİ.
  -- İlk sürümde taşıdım ama tekilleştirmedim: hedef salonun iki aktif
  -- katalog kaydı oldu ve "Bir salona bağlı BİRDEN ÇOK aktif katalog
  -- kaydı" değişmezi kırmızıya döndü. Ürün karşılığı: host, keşifte
  -- AYNI salonu iki kez görürdü — Gökberk'in "duplicate olma" dediği
  -- şeyin tam olarak kendisi, üstelik birleştirme işleminin YAN ETKİSİ.
  update lounges set venue_id = p_hedef where venue_id = p_kaynak;
  update lounges l set active = false,
         name = l.name || ' (211 kopya)'
   where l.venue_id = p_hedef and l.active
     and l.id <> (select x.id from lounges x
                   where x.venue_id = p_hedef and x.active
                   -- `lounges`te created_at YOK (id, airport_code, name,
                   -- terminal, access_types, active, venue_id). Kanoniği
                   -- kullanım sayısı, sonra id belirler.
                   order by (select count(*) from availabilities a where a.lounge_id = x.id) desc, x.id
                   limit 1);
  -- ⚠️ Benzersizlik (venue_id, scope, partner_kind, partner_name);
  -- `partner_id` diye bir sütun YOK. Şemayı okumadan sütun adı
  -- uydurmanın bedeli 42703. Çakışanı taşımıyorum, arşivde kalıyor.
  update lounge_venue_partners p set venue_id = p_hedef
   where p.venue_id = p_kaynak
     and not exists (select 1 from lounge_venue_partners q
                      where q.venue_id = p_hedef and q.scope = p.scope
                        and q.partner_kind = p.partner_kind
                        and q.partner_name = p.partner_name);
  update lounge_venue_partners set active = false where venue_id = p_kaynak;

  update lounge_venues set active = false,
         name  = name || ' (211 birleştirildi → ' || left(p_hedef::text, 8) || ')',
         notes = coalesce(notes || ' · ', '') || '211: ' || p_gerekce
   where id = p_kaynak;
end $fn$;

-- KANITLI TEK BİRLEŞTİRME — ESB Primeclass
-- Priority Pass ESB sayfası: "2 Deneyimler", iki Primeclass kartı
--   (International Terminal + Domestic Terminal).
-- LoungeKey ESB sayfası: "2", iki Primeclass kartı (Dış + İç Hatlar).
-- İki bağımsız ağ AYNI SAYIYI söylüyor: ESB'de iki Primeclass var.
-- Katalogda ÜÇ vardı: "Primeclass Lounge — İç Hat", "— Dış Hat" ve
-- eski nesil "Primeclass CIP Lounge" (scope=both, "Int. Terminal").
-- Üçüncüsü dış hat kaydının kopyası; dış hattakine birleştiriliyor.
do $$
declare v_eski uuid; v_hedef uuid;
begin
  select id into v_eski   from lounge_venues
   where active and airport_code='ESB' and name = 'Primeclass CIP Lounge';
  select id into v_hedef  from lounge_venues
   where active and airport_code='ESB' and name = 'Primeclass Lounge — Dış Hat';
  if v_eski is not null and v_hedef is not null then
    perform public.cns_merge_venue(v_eski, v_hedef,
      'PP ve LoungeKey ESB''de iki Primeclass listeliyor; katalogda uc kayit vardi.');
    raise notice '211: ESB "Primeclass CIP Lounge" → "Primeclass Lounge — Dis Hat" (iki bagimsiz kaynak)';
  end if;
end $$;

-- ----------------------------------------------------------------------
-- venue_review_list   [etkin kaynak: 211_kart_aglari_kaynaktan.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_review_list()
returns table (id uuid, havalimani text, salon text, konu text, gerekce text, durum text)
language sql stable security definer set search_path = public as $fn$
  select q.id, v.airport_code::text, v.name, q.konu, q.gerekce, q.durum
    from venue_review_queue q join lounge_venues v on v.id = q.venue_id
   order by q.durum, v.airport_code, v.name;
$fn$;
grant execute on function public.venue_review_list() to service_role;


-- ============================================================
-- (3) EŞLEŞTİRME — kaynak satırı hangi salona denk geliyor?
-- ============================================================
-- 🔴 İLK SÜRÜM 59 SATIRIN 21'İNİ EŞLEŞTİREMEDİ. Sebep tek bir kaba
-- kuraldı: "havalimanı + marka + kapsam tek adaya inmezse vazgeç."
-- Ölçünce üç ayrı kök sebep çıktı ve üçü de çözülebilir:
--
--   (i)  `cns_brand` "Turkish Airlines CIP Lounge"u 'cip' sayıyordu.
--        Bir kart ağının "CIP Lounge"u HİÇBİR ZAMAN THY salonu
--        değildir; havayolu salonu rakip adaydı ve her seferinde
--        belirsizlik üretiyordu. Havayolu kontrolü 'cip'ten ÖNCE.
--   (ii) Kapsamı KESİN olan kaynak satırı, scope='both' eski nesil
--        kayıtla yarışıyordu. Kesin kapsam eşleşmesi öncelikli olmalı.
--   (iii)DragonPass kapsam yazmıyor ama KART SAYISI yazıyor. Aynı
--        markadan iki kart + katalogda o markadan tam iki salon =
--        ikisi de o ağa açık demektir. Bu bir tahmin değil, sayım.
--
-- KADEMELER (her kademe bir öncekinden daha zayıf kanıt, sırayla):
--   K1  kapsam AYNI + terminal jetonu AYNI          → tek aday
--   K2  kapsam AYNI                                  → tek aday
--   K3  kapsam AYNI ∪ 'both'                         → tek aday
--   K4  kapsam serbest (kaynak 'bilinmiyor' dediyse) → tek aday
--   K5  SAYI DENKLİĞİ: (ağ,havalimanı,marka) satır sayısı = aday
--       sayısı → hepsi eşleşir (kapsam sırasına göre birebir)
-- Hiçbiri tutmazsa satır EŞLEŞMEZ ve `match_note` sebebi yazar.

-- ----------------------------------------------------------------------
-- cns_brand   [etkin kaynak: 211_kart_aglari_kaynaktan.sql]
-- ----------------------------------------------------------------------
create or replace function public.cns_brand(p text)
returns text language sql immutable as $fn$
  select case
    -- ⚠️ HAVAYOLU SALONU EN ÜSTTE. "Turkish Airlines CIP Lounge"
    -- 'cip' değildir; kart ağının CIP'i ile yarışırsa her AYT/DLM/DIY
    -- satırını belirsizleştirir. Bu, ilk koşudaki 21 eşleşmeyenin
    -- en büyük tek sebebiydi.
    when p ilike '%turkish airlines%' or p ilike '%thy %' then 'havayolu-tk'
    when p ilike '%pegasus%'           then 'havayolu-pgs'
    when p ilike '%ajet%'              then 'havayolu-ajet'
    when p ilike '%pop%up%'            then 'pop-up'
    when p ilike '%sleepod%'           then 'sleepod'
    when p ilike '%shower%'            then 'shower'
    when p ilike '%xpresspa%'          then 'xpresspa'
    when p ilike '%kepler%'            then 'kepler'
    when p ilike '%bosphorus%'         then 'plaza-bosphorus'
    when p ilike '%marmara%'           then 'plaza-marmara'
    when p ilike '%plaza premium%'     then 'plaza'
    when p ilike '%primeclass%'        then 'primeclass'
    when p ilike '%çelebi%' or p ilike '%celebi%' or p ilike '%platinum%' then 'celebi-platinum'
    when p ilike '%comfort%'           then 'comfort'
    when p ilike '%elite%'             then 'elite'
    when p ilike '%anatolia%'          then 'anatolia'
    when p ilike '%aeroport%'          then 'aeroport'
    when p ilike '%dlm lounge%'        then 'dlm'
    when p ilike '%iga%'               then 'iga'
    when p ilike '%cip%'               then 'cip'
    else lower(btrim(p)) end;
$fn$;

-- Terminal JETONU: "Dış Hatlar Terminali 2" · "Terminal 2" ·
-- "T1 International" · "Dış Hat (T2)" hepsinden 1/2/3 çıkarır.
-- "Int. Terminal" gibi numarasızlarda null döner (jeton yok = kıyas yok).

-- ----------------------------------------------------------------------
-- cns_term   [etkin kaynak: 211_kart_aglari_kaynaktan.sql]
-- ----------------------------------------------------------------------
create or replace function public.cns_term(p text)
returns text language sql immutable as $fn$
  select (regexp_match(coalesce(p,''), '(?:t|terminal[iı]?)\s*\(?\s*([123])', 'i'))[1];
$fn$;

-- Aday kümesi: aynı havalimanı, aynı marka, aynı TESİS TİPİ.
-- Tesis tipi neden şart: PP'nin "IGA Sleepod"u bir uyku kapsülü;
-- onu "iGA Lounge"a eşlemek 190'ın hatasının aynısı olurdu.

-- ----------------------------------------------------------------------
-- cns_adaylar   [etkin kaynak: 214_misafir_hakki_kaynaktan.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.cns_adaylar(
  p_airport text, p_brand text, p_kind text, p_scopes text[])
returns uuid[] language sql stable as $fn$
  select coalesce(array_agg(v.id order by coalesce(v.scope,'both'), v.id), '{}'::uuid[])
    from lounge_venues v
   where v.active
     and not v.is_umbrella                     -- 214
     and v.airport_code = p_airport
     and public.cns_brand(v.name) = p_brand
     and coalesce(v.venue_kind,'lounge') = p_kind
     and (p_scopes is null or coalesce(v.scope,'both') = any (p_scopes));
$fn$;

-- ----------------------------------------------------------------------
-- venue_duplicate_suspects   [etkin kaynak: 214_misafir_hakki_kaynaktan.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.venue_duplicate_suspects()
returns table (havalimani text, marka text, kapsam text, adet int, adlar text)
language sql stable security definer set search_path = public as $fn$
  select v.airport_code::text, public.cns_brand(v.name), coalesce(v.scope,'both')::text,
         count(*)::int, string_agg(v.name, ' | ' order by v.name)
    from lounge_venues v
   where v.active and coalesce(v.venue_kind,'lounge') = 'lounge'
     and not v.is_umbrella                     -- 214: semsiye kayit mukerrer degildir
   group by v.airport_code, public.cns_brand(v.name), coalesce(v.scope,'both')
  having count(*) > 1;
$fn$;
grant execute on function public.venue_duplicate_suspects() to service_role;

-- Kural motorunun okuduğu kart-ağı görünümü de şemsiyeyi atlasın.
-- ⚠️ SÜTUN EKLİYORUM (`belirsiz`) → `create or replace` YETMEZ:
--     "cannot change return type of existing function"
-- `returns table(...)` OUT parametre satır tipidir; tipi değiştiren her
-- fonksiyonun önüne DROP gerekir. Bu kural `returns_check.py` ile zaten
-- denetleniyordu; ben yine unuttum ve harness yakaladı — nöbetçinin
-- işini yapması tam olarak bu.
drop function if exists public.cns_kapsam_haritasi();

-- ----------------------------------------------------------------------
-- cns_bekleyenler   [etkin kaynak: 211_kart_aglari_kaynaktan.sql]
-- ----------------------------------------------------------------------
create or replace function public.cns_bekleyenler()
returns table (ag text, havalimani text, salon text, kapsam text, kart_no int,
               tesis_tipi text, durum text, aday_sayisi int, adaylar text)
language sql stable security definer set search_path = public as $fn$
  select s.network, s.airport, s.venue_name, s.scope, s.kart_no, s.tesis_tipi,
         coalesce(s.match_note,'?'),
         coalesce(array_length(public.cns_adaylar(s.airport, public.cns_brand(s.venue_name), s.tesis_tipi, null),1),0),
         coalesce((select string_agg(v.name, ' | ' order by v.name) from lounge_venues v
                    where v.id = any (public.cns_adaylar(s.airport, public.cns_brand(s.venue_name), s.tesis_tipi, null))), '-')
    from card_network_source s
   where s.venue_id is null
   order by s.network, s.airport;
$fn$;
grant execute on function public.cns_bekleyenler() to service_role;

-- ----------------------------------------------------------------------
-- cns_kapsam_haritasi   [etkin kaynak: 214_misafir_hakki_kaynaktan.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.cns_kapsam_haritasi()
returns table (havalimani text, salon text, tesis_tipi text, kapsam text, aglar text, belirsiz boolean)
language sql stable security definer set search_path = public as $fn$
  select v.airport_code::text, v.name, coalesce(v.venue_kind,'lounge')::text,
         coalesce(v.scope,'both')::text, string_agg(p.code, ', ' order by p.code),
         bool_or(a.enforcement = 'warn' and a.conditions ilike '%KAYNAK BELIRSIZ%')
    from lounge_venue_acceptance a
    join lounge_programs p on p.id = a.program_id
    join lounge_venues   v on v.id = a.venue_id
   where a.accepted and a.active and not v.is_umbrella
     and p.code in ('PRIORITY_PASS','LOUNGEKEY','DRAGONPASS')
   group by 1,2,3,4
   order by 1,2;
$fn$;
grant execute on function public.cns_kapsam_haritasi() to service_role;


-- ============================================================
-- (10) MİSAFİR HAKKI KARŞILAŞTIRMA — ÜRÜNÜN ASIL CEVABI
-- ============================================================
-- 🔴 GÖKBERK'İN SORDUĞU ŞEY BU: aynı salona farklı kaynaklarla
-- girilebiliyorsa, MİSAFİR HAKKI hangi kaynakta ne oluyor?
-- Bu fonksiyon bir salon için TÜM kaynakları yan yana koyuyor.
-- Host'un ekranında "hangi kartını kullanmalısın" cevabı budur.

-- ----------------------------------------------------------------------
-- client_flags   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ----------------------------------------------------------------------
create or replace function public.client_flags()
returns jsonb language sql stable security definer set search_path = public as $fn$
  select coalesce(jsonb_object_agg(f.key,
           f.enabled and (
             f.rollout_pct >= 100
             or auth.uid() is null
             or (('x' || substr(md5(f.key || coalesce(auth.uid()::text,'')), 1, 8))::bit(32)::bigint
                  % 100) < f.rollout_pct
           )), '{}'::jsonb)
    from feature_flags f;
$fn$;
grant execute on function public.client_flags() to authenticated, anon;

-- Sunucu tarafı okuma yardımcısı (029'daki `flag_enabled` duruyor,
-- ama artık gerçekten çağrılıyor).
-- ⚠️ `create_request_impl`in gövdesini yeniden yazmıyorum. 204/207'de
-- öğrendiğim desen: yeniden adlandır, aynı imzalı sarmalayıcı koy.
-- Gövdeyi kopyalamak, 207'nin mertebe/kredi mantığını sessizce eski
-- bir sürüme döndürme riskidir.
--
-- ⚠️ İMZA `pg_get_function_arguments` İLE ALINIR (DEFAULT'lar korunur).
-- `identity_arguments` DEFAULT'ları düşürür ve sarmalayıcı
-- `create_request(p_avail_id)` çağrısını 42883 ile kırar — bu turda
-- bir kez yaşandı.
do $$
declare v_args text; v_ident text;
begin
  if not exists (select 1 from pg_proc where proname = 'create_request_impl_preflag') then
    select pg_get_function_arguments(p.oid), pg_get_function_identity_arguments(p.oid)
      into v_args, v_ident
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = 'create_request_impl';

    execute format('alter function public.create_request_impl(%s) rename to create_request_impl_preflag', v_ident);

    execute format($f$

-- ----------------------------------------------------------------------
-- i18n_overrides   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ----------------------------------------------------------------------
create or replace function public.i18n_overrides(p_lang text default null)
returns table (anahtar text, dil text, metin text)
language sql stable security definer set search_path = public as $fn$
  select s.key, s.lang, s.value
    from i18n_strings s
   where s.active
     and s.value is not null and btrim(s.value) <> ''
     and (p_lang is null or s.lang = p_lang);
$fn$;
grant execute on function public.i18n_overrides(text) to authenticated, anon;

-- Sürüm damgası: uygulama her açılışta tüm listeyi çekmesin diye
-- "en son ne zaman değişti" tek sayı olarak okunabilsin.

-- ----------------------------------------------------------------------
-- i18n_version   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ----------------------------------------------------------------------
create or replace function public.i18n_version()
returns text language sql stable security definer set search_path = public as $fn$
  select coalesce(to_char(max(updated_at), 'YYYYMMDDHH24MISS'), '0') from i18n_strings where active;
$fn$;
grant execute on function public.i18n_version() to authenticated, anon;


-- ============================================================
-- (3) rule_thresholds — EKRANIN ADI NE DİYORSA ONU YÖNETSİN
-- ============================================================
-- 🔴 EKRAN YANLIŞ VERİYİ DÜZENLİYORDU. Başlık "Güven Puanı Eşikleri",
-- yardım metni "değişiklik ANINDA etkili" diyor; ama tabloda rozet
-- anahtarı YOK, rozet eşikleri `compute_trust_badge` içinde SABİT:
--     >=88 trusted_plus · >=72 trusted · >=56 verified
-- Ekranın "BUGÜN KAÇ KİŞİ" sütunu, güven puanını `max_active_requests`
-- (=5) gibi bambaşka birimdeki sayılarla kıyaslıyordu. Anlamsız
-- aritmetik, güven verici bir tabloda.
insert into rule_thresholds (key, value, description) values
  ('badge_verified',     56, 'Bu puandan itibaren "Dogrulanmis" rozeti'),
  ('badge_trusted',      72, 'Bu puandan itibaren "Guvenilir" rozeti'),
  ('badge_trusted_plus', 88, 'Bu puandan itibaren "Guvenilir+" rozeti')
on conflict (key) do update set description = excluded.description;

update rule_thresholds set description = 'Bir misafirin ayni anda acik tutabilecegi en fazla istek (create_request_impl uygular)'
 where key = 'max_active_requests';
update rule_thresholds set description = 'Kac no-show sonrasi otomatik golge kisit (apply_rule_engine uygular)'
 where key = 'no_show_limit';
update rule_thresholds set description = 'Kac ACIK sikayet sonrasi otomatik golge kisit (sikayet acilinca tetiklenir)'
 where key = 'report_threshold';

-- ⚠️ `compute_trust_badge` IMMUTABLE idi; tablo okuyunca STABLE olmalı.
-- IMMUTABLE bir fonksiyon tablo okursa PostgreSQL sonucu önbelleğe
-- alabilir ve eşik değişikliği görünmez. Volatiliteyi düşürmek
-- CREATE OR REPLACE ile serbest; indekste kullanılmadığını ölçtüm.
do $$
declare v_n int;
begin
  select count(*) into v_n from pg_index i
    join pg_class c on c.oid = i.indexrelid
   where pg_get_indexdef(i.indexrelid) ilike '%compute_trust_badge%';
  if v_n > 0 then
    raise exception '212: compute_trust_badge % indekste kullaniliyor; STABLE yapmak indeksi kirar', v_n;
  end if;
end $$;

-- ----------------------------------------------------------------------
-- rozetleri_yenile   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ----------------------------------------------------------------------
create or replace function public.rozetleri_yenile()
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_n int;
begin
  update trust_scores set badge = public.compute_trust_badge(score)
   where badge is distinct from public.compute_trust_badge(score);
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'guncellenen', v_n);
end $fn$;
revoke all on function public.rozetleri_yenile() from public, anon, authenticated;
grant execute on function public.rozetleri_yenile() to service_role;

-- `apply_rule_engine` ARTIK ÇAĞRILIYOR: şikayet açıldığı anda.
-- 029'dan beri tanımlıydı ve sıfır çağıranı vardı — yani "3 şikayet
-- sonrası otomatik kısıt" kuralı hiç işlemedi.

-- ----------------------------------------------------------------------
-- trg_rule_engine   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_rule_engine()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  perform public.apply_rule_engine(new.target_id);
  return new;
end $fn$;
drop trigger if exists trg_rule_engine_report on reports;
create trigger trg_rule_engine_report after insert on reports
  for each row execute function public.trg_rule_engine();

-- ⚠️ SIRA: tetiği fonksiyondan ÖNCE yazmıştım (kopyala-yapıştır) ve
-- 42883 aldım. PostgreSQL `create trigger ... execute function f()`
-- derken f'in VAR OLMASINI ister; "sonra tanımlarım" yok.

-- ----------------------------------------------------------------------
-- trg_rule_engine_noshow   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_rule_engine_noshow()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  perform public.apply_rule_engine(new.no_show_user_id);
  return new;
end $fn$;
drop trigger if exists trg_rule_engine_noshow on sessions;
create trigger trg_rule_engine_noshow after update of no_show_user_id on sessions
  for each row when (new.no_show_user_id is not null)
  execute function public.trg_rule_engine_noshow();

-- BO'nun eşik ekranı doğru sayıyı göstersin: hangi eşik BUGÜN kaç
-- kişiyi etkiliyor. Öncekinde güven puanı ile istek tavanı
-- karşılaştırılıyordu; artık her eşik kendi birimiyle sayılıyor.

-- ----------------------------------------------------------------------
-- esik_etkisi   [etkin kaynak: 212_yonetilen_ayarlar_gercekten_okunuyor.sql]
-- ----------------------------------------------------------------------
create or replace function public.esik_etkisi()
returns table (anahtar text, deger int, aciklama text, etkilenen int, birim text)
language sql stable security definer set search_path = public as $fn$
  select t.key, t.value, t.description,
    case t.key
      when 'badge_verified'      then (select count(*)::int from trust_scores where score >= t.value)
      when 'badge_trusted'       then (select count(*)::int from trust_scores where score >= t.value)
      when 'badge_trusted_plus'  then (select count(*)::int from trust_scores where score >= t.value)
      when 'max_active_requests' then (select count(*)::int from (
             select guest_id from requests where status='pending'
              group by guest_id having count(*) >= t.value) x)
      when 'report_threshold'    then (select count(*)::int from (
             select target_id from reports where status='open'
              group by target_id having count(*) >= t.value) x)
      when 'no_show_limit'       then (select count(*)::int from (
             select no_show_user_id from sessions
              where cancel_reason='no_show' and no_show_user_id is not null
                and completed_at > now() - interval '90 days'
              group by no_show_user_id having count(*) >= t.value) x)
      when 'restrict_days'       then (select count(*)::int from users
             where shadow_limited and restricted_until > now())
      else 0 end,
    case t.key
      when 'restrict_days' then 'su an kisitli kullanici'
      when 'max_active_requests' then 'tavana dayanmis misafir'
      when 'report_threshold' then 'esigi asmis kullanici'
      when 'no_show_limit' then 'esigi asmis kullanici (90 gun)'
      else 'bu rozeti hak eden kullanici' end
    from rule_thresholds t
   order by t.key;
$fn$;
grant execute on function public.esik_etkisi() to service_role;


-- ============================================================
-- NÖBETÇİLER
-- ============================================================

-- 1) ÜÇ TABLONUN DA ARTIK GERÇEK BİR OKUYUCUSU VAR
-- Bu nöbetçi metin araması yapıyor çünkü ölçmek istediğim şey tam
-- olarak bu: fonksiyon GÖVDESİNDE tablo adı geçiyor mu ve o fonksiyon
-- ÇAĞRILIYOR mu.
do $$
declare r record; v_eksik text := '';
begin
  for r in select * from (values
      ('feature_flags',   'client_flags'),
      ('feature_flags',   'create_request_impl'),
      ('i18n_strings',    'i18n_overrides'),
      ('rule_thresholds', 'compute_trust_badge'),
      ('rule_thresholds', 'apply_rule_engine'),
      ('rule_thresholds', 'create_request_impl')
    ) as t(tablo, fn)
  loop
    if not exists (
      select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
       where n.nspname='public' and p.proname = r.fn and p.prosrc ilike '%' || r.tablo || '%')
    then v_eksik := v_eksik || r.fn || '→' || r.tablo || ' '; end if;
  end loop;
  if v_eksik <> '' then
    raise exception '212: su okuyucular tabloyu okumuyor: %', v_eksik;
  end if;
  raise notice '212: uc tablonun da gercek okuyucusu var';
end $$;

-- ----------------------------------------------------------------------
-- venue_airport_share   [etkin kaynak: 213_saglayici_kurumsal_katman.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_airport_share(
  p_lounge_id uuid, p_user uuid default null, p_gun int default 90)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_k int := public.partner_k();
  v_rakip_esigi constant int := 3;
  v_ap text;
  v_salon int; v_toplam numeric;
  v_benim_talep numeric; v_benim_pay numeric; v_benim_kabul_pay numeric;
  v_medyan numeric; v_max numeric;
  v_ham_salon int; v_ham_talep bigint;
begin
  -- KAPI: yetki yoksa VERİ DEĞİL, boş cevap.
  if not coalesce(public.partner_gate(p_user, p_lounge_id), false) then
    return jsonb_build_object('known', false, 'yetki', false, 'hesaplanabilir', false,
      'neden', 'Bu salon için yetkiniz yok ya da partner_channel bayrağı kapalı.');
  end if;

  select l.airport_code into v_ap from lounges l where l.id = p_lounge_id;
  if v_ap is null then
    return jsonb_build_object('known', false, 'yetki', true, 'hesaplanabilir', false,
      'neden', 'Salonun havalimanı kodu yok.');
  end if;

  -- HAM sayılar: eşik ÖNCESİ. Kapsamı söyleyebilmek için gerekli —
  -- "3 salondan 0'ı eşiği geçti" ile "hiç veri yok" aynı şey değil.
  select count(distinct a.lounge_id), count(*)
    into v_ham_salon, v_ham_talep
    from requests r
    join availabilities a on a.id = r.avail_id
    join users u on u.id = r.guest_id
   where a.airport_code = v_ap
     and r.created_at >= now() - make_interval(days => p_gun)
     and coalesce(u.is_staff, false) = false
     and u.deleted_at is null;

  with t as (
    select a.lounge_id,
           count(*)::numeric as talep,
           count(*) filter (where r.status in ('accepted','completed'))::numeric as kabul
      from requests r
      join availabilities a on a.id = r.avail_id
      join users u on u.id = r.guest_id
     where a.airport_code = v_ap
       and r.created_at >= now() - make_interval(days => p_gun)
       and coalesce(u.is_staff, false) = false
       and u.deleted_at is null
     group by a.lounge_id
    having count(distinct r.guest_id) >= v_k     -- k-anonimite, SALON düzeyinde
  ), pay as (
    select lounge_id, talep, kabul,
           talep * 100 / nullif(sum(talep) over (), 0) as pay,
           kabul * 100 / nullif(sum(kabul) over (), 0) as kabul_pay
      from t
  )
  select (select count(*)::int from pay),
         (select sum(talep) from pay),
         (select talep from pay where lounge_id = p_lounge_id),
         (select round(pay, 1) from pay where lounge_id = p_lounge_id),
         (select round(kabul_pay, 1) from pay where lounge_id = p_lounge_id),
         (select round((percentile_cont(0.5) within group (order by pay::float8))::numeric, 1) from pay),
         (select round(max(pay), 1) from pay)
    into v_salon, v_toplam, v_benim_talep, v_benim_pay, v_benim_kabul_pay, v_medyan, v_max;

  return jsonb_build_object(
    'known', true, 'yetki', true,
    'havalimani', v_ap, 'gun', p_gun,
    'k_esigi', v_k, 'rakip_esigi', v_rakip_esigi,
    'ham_salon', coalesce(v_ham_salon, 0),
    'ham_talep', coalesce(v_ham_talep, 0),
    'karsilastirilan_salon', coalesce(v_salon, 0),
    'esik_ustu_talep', coalesce(v_toplam, 0),
    'benim_talebim', v_benim_talep,
    'benim_payim_yuzde', v_benim_pay,
    'benim_kabul_payim_yuzde', v_benim_kabul_pay,
    'benim_esik_altinda', v_benim_pay is null,
    -- Rakip eşiği altında medyan/maksimum GİZLENİR.
    'havalimani_medyan_pay_yuzde', case when coalesce(v_salon,0) >= v_rakip_esigi then v_medyan end,
    'en_yuksek_pay_yuzde',         case when coalesce(v_salon,0) >= v_rakip_esigi then v_max end,
    'hesaplanabilir', v_benim_pay is not null,
    'neden', case
      when coalesce(v_ham_talep,0) = 0
        then format('Son %s günde %s havalimanında hiç talep kaydı yok.', p_gun, v_ap)
      when v_benim_pay is null
        then format('Bu salon son %s günde %s farklı misafir eşiğini geçemedi; kendi payınız da gizlendi (k=%s). Havalimanında eşik öncesi %s talep, %s salon var.',
                    p_gun, v_k, v_k, v_ham_talep, v_ham_salon)
      when coalesce(v_salon,0) < v_rakip_esigi
        then format('Payınız hesaplandı ama karşılaştırma kümesinde yalnız %s salon var; medyan/en yüksek gizlendi (tek rakibin sayısını ifşa ederdi, eşik %s).',
                    v_salon, v_rakip_esigi)
      end,
    'not', 'Rakip salonların adı hiçbir koşulda paylaşılmaz; yalnız pay dağılımı verilir.');
end $fn$;


-- ============================================================
-- Ö6 · NO-SHOW, İPTAL VE BOŞA GİDEN SLOT
-- ============================================================
-- Salon için boşa giden slot kaybedilen kapasitedir. `cancel_reason`
-- ve `no_show_user_id` (080) zaten yazılıyor; yeni veri gerekmiyor.
--
-- ⚠️ İKİ NO-SHOW SİNYALİ VAR ve ikisi de sayılıyor: `cancel_reason`
-- serbest metin bir kolon, `no_show_user_id` yapısal. Yalnız birine
-- bakmak, diğer yoldan yazılan kayıtları sessizce düşürürdü.

-- ----------------------------------------------------------------------
-- venue_no_show   [etkin kaynak: 213_saglayici_kurumsal_katman.sql]
-- ----------------------------------------------------------------------
create or replace function public.venue_no_show(
  p_lounge_id uuid, p_user uuid default null, p_from date default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_k int := public.partner_k();
  v_from date;
  v_satir jsonb;
  v_ham int; v_gosterilen int;
begin
  if not coalesce(public.partner_gate(p_user, p_lounge_id), false) then
    return jsonb_build_object('known', false, 'yetki', false, 'haftalar', '[]'::jsonb,
      'hesaplanabilir', false,
      'neden', 'Bu salon için yetkiniz yok ya da partner_channel bayrağı kapalı.');
  end if;

  v_from := coalesce(p_from, current_date - 90);

  select count(*) into v_ham
    from sessions s
    join requests r on r.id = s.request_id
    join availabilities a on a.id = r.avail_id
    join users u on u.id = r.guest_id
   where a.lounge_id = p_lounge_id
     and s.started_at >= v_from
     and coalesce(u.is_staff, false) = false
     and u.deleted_at is null;

  select jsonb_agg(x order by x ->> 'hafta'), coalesce(sum((x ->> 'oturum')::int), 0)::int
    into v_satir, v_gosterilen
  from (
    select jsonb_build_object(
             'hafta',       date_trunc('week', s.started_at)::date,
             'oturum',      count(*)::int,
             'kisi',        count(distinct r.guest_id)::int,
             'tamamlanan',  count(*) filter (where s.status = 'completed')::int,
             'no_show',     count(*) filter (where s.cancel_reason = 'no_show'
                                                or s.no_show_user_id is not null)::int,
             'iptal',       count(*) filter (where s.status = 'cancelled'
                                               and coalesce(s.cancel_reason, '') <> 'no_show'
                                               and s.no_show_user_id is null)::int,
             -- 🔴 `avg(...) filter (...)::numeric` YAZMADIM: FILTER'dan
             -- sonra gelen cast sözdizimi tartışmalı ve okuyanı yanıltır.
             -- Süzmeyi CASE ile ifade etmek hem çalışır hem açıktır.
             'ort_kalis_saat', round(avg(case when s.completed_at is not null
                                    then extract(epoch from (s.completed_at - s.started_at)) / 3600.0
                                  end)::numeric, 1)
           ) as x
      from sessions s
      join requests r on r.id = s.request_id
      join availabilities a on a.id = r.avail_id
      join users u on u.id = r.guest_id
     where a.lounge_id = p_lounge_id
       and s.started_at >= v_from
       and coalesce(u.is_staff, false) = false
       and u.deleted_at is null
     group by date_trunc('week', s.started_at)
    having count(distinct r.guest_id) >= v_k      -- k-anonimite, HAFTA düzeyinde
  ) q;

  return jsonb_build_object(
    'known', true, 'yetki', true,
    'baslangic', v_from, 'k_esigi', v_k,
    'haftalar', coalesce(v_satir, '[]'::jsonb),
    'ham_oturum', coalesce(v_ham, 0),
    'gosterilen_oturum', coalesce(v_gosterilen, 0),
    'gizlenen_oturum', coalesce(v_ham, 0) - coalesce(v_gosterilen, 0),
    -- KAPSAM: eşikten geçen oturum / toplam oturum. Bu sayı olmadan
    -- tablo "salonun tamamı" sanılır.
    'kapsam_yuzde', case when coalesce(v_ham, 0) = 0 then null
                    else round(coalesce(v_gosterilen, 0)::numeric * 100 / v_ham, 1) end,
    'hesaplanabilir', v_satir is not null,
    'neden', case
      when coalesce(v_ham, 0) = 0
        then format('%s tarihinden bu yana bu salonda hiç oturum kaydı yok.', v_from)
      when v_satir is null
        then format('%s oturum var ama hiçbir hafta %s farklı misafir eşiğini geçmedi; tamamı gizlendi.', v_ham, v_k)
      end,
    'not', 'Ortalama kalış = completed_at − started_at. Yalnız tamamlanan oturumlarda hesaplanır; iptal ve no-show ortalamaya girmez.');
end $fn$;


-- ============================================================
-- Ö7 · KART PROGRAMI KARMASI — hangi sözleşme trafik getiriyor?
-- ============================================================
-- 🔴 TASLAK SORGU BU ŞEMADA ÇALIŞMAZDI VE ÖLÇTÜM:
--     select count(*) from availabilities where program_id is null → 25/25
-- Yani `join lounge_programs p on p.id = a.program_id` (inner join)
-- HER ZAMAN sıfır satır döndürürdü. Ekran boş görünür, kimse sebebini
-- bilmezdi — en pahalı hata sınıfı: inandırıcı yanlış cevap.
--
-- ÇÖZÜM VE BEDELİ: program `pick_host_program(host, venue)` ile
-- host'un hak beyanından TÜRETİLİYOR (151'in belirli seçicisi).
-- Türetme bir tahmindir; bu yüzden cevap üç oranı BİRDEN taşır:
--   dogrudan_beyan_yuzde  — ilanın kendi `program_id`'si (ölçüm: %0)
--   turetilen_yuzde       — host hakkından türetildi
--   program_bilinmeyen_yuzde — hiçbiri; "program bilinmeyen: %N" satırı
-- Sözleşme yenileme toplantısına giren kişi, sayının ne kadarının
-- beyan ne kadarının çıkarım olduğunu BİLMEK zorundadır.

-- ----------------------------------------------------------------------
-- venue_program_mix   [etkin kaynak: 215_saglayici_veri_yollari.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.venue_program_mix(
  p_lounge_id uuid, p_user uuid default null, p_from date default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_k int := public.partner_k();
  v_from date;
  v_ven uuid;
  v_ilan int; v_host int; v_dogrudan int; v_turetilen int; v_bilinmeyen int;
  v_satir jsonb; v_gosterilen int;
  v_bilinmeyen_yuzde numeric;
begin
  if not coalesce(public.partner_gate(p_user, p_lounge_id), false) then
    return jsonb_build_object('known', false, 'yetki', false, 'satirlar', '[]'::jsonb,
      'hesaplanabilir', false,
      'bilinmeyen_satiri', 'program bilinmeyen: ölçülemedi (yetki yok)',
      'neden', 'Bu salon için yetkiniz yok ya da partner_channel bayrağı kapalı.');
  end if;

  v_from := coalesce(p_from, current_date - 180);
  select l.venue_id into v_ven from lounges l where l.id = p_lounge_id;

  -- 🔴 ÜÇ SAYAÇ ARTIK `program_source` OKUYOR.
  -- Eski gövde `program_id is not null` görünce "beyan" diyordu; 215
  -- kolonu doldurduğu an bu cümle YALAN olurdu.
  select count(*)::int,
         count(distinct a.host_id)::int,
         count(*) filter (where a.program_id is not null
                            and coalesce(a.program_source, 'beyan') = 'beyan')::int,
         count(*) filter (where a.program_id is not null
                            and a.program_source = 'turetildi')::int,
         count(*) filter (where coalesce(a.program_id,
                                public.pick_host_program(a.host_id, coalesce(a.venue_id, v_ven))) is null)::int
    into v_ilan, v_host, v_dogrudan, v_turetilen, v_bilinmeyen
    from availabilities a
   where a.lounge_id = p_lounge_id
     and a.avail_date >= v_from;

  if coalesce(v_host, 0) < v_k then
    return jsonb_build_object(
      'known', true, 'yetki', true, 'satirlar', '[]'::jsonb,
      'baslangic', v_from, 'k_esigi', v_k,
      'toplam_host', coalesce(v_host, 0),
      'hesaplanabilir', false,
      'bilinmeyen_satiri', format('program bilinmeyen: ölçülemedi (salonda %s host var, eşik %s)',
                                  coalesce(v_host, 0), v_k),
      'neden', format('Bu salonda %s tarihinden bu yana %s farklı host ilan açmış; k-anonimite eşiği %s. Oran bile yayımlanmıyor.',
                      v_from, coalesce(v_host, 0), v_k),
      'not', 'Eşik `beta_settings.partner_k_threshold` ile yönetilir.');
  end if;

  v_bilinmeyen_yuzde := round(coalesce(v_bilinmeyen, 0)::numeric * 100 / nullif(v_ilan, 0), 1);

  select jsonb_agg(x order by (x ->> 'dolan_slot')::int desc,
                              (x ->> 'ilan')::int desc,
                              x ->> 'program'),
         coalesce(sum((x ->> 'ilan')::int), 0)::int
    into v_satir, v_gosterilen
  from (
    select jsonb_build_object(
             'program',      coalesce(p.name, 'Program bilinmiyor'),
             'program_kodu', coalesce(p.code, '—'),
             'bilinmiyor',   p.id is null,
             'host_sayisi',  count(distinct a.host_id)::int,
             'ilan',         count(*)::int,
             'toplam_slot',  coalesce(sum(a.slots), 0)::int,
             'dolan_slot',   coalesce(sum(a.filled), 0)::int,
             'ilan_payi_yuzde', round(count(*)::numeric * 100 / nullif(v_ilan, 0), 1),
             -- YENİ: satır düzeyinde de kaynak kırılımı. "Bu programın
             -- 7 ilanının 7'si çıkarım" cümlesi, tablodaki payı okuyan
             -- kişinin bilmesi gereken tek şeydir.
             'beyan_ilan',    count(*) filter (where coalesce(a.program_source, 'beyan') = 'beyan' and a.program_id is not null)::int,
             'turetilen_ilan', count(*) filter (where a.program_source = 'turetildi')::int
           ) as x
      from availabilities a
      left join lounge_programs p
             on p.id = coalesce(a.program_id,
                                public.pick_host_program(a.host_id, coalesce(a.venue_id, v_ven)))
     where a.lounge_id = p_lounge_id
       and a.avail_date >= v_from
     group by p.id, p.name, p.code
    having count(distinct a.host_id) >= v_k
  ) q;

  return jsonb_build_object(
    'known', true, 'yetki', true,
    'baslangic', v_from, 'k_esigi', v_k,
    'toplam_ilan', coalesce(v_ilan, 0),
    'toplam_host', coalesce(v_host, 0),
    'dogrudan_beyan', coalesce(v_dogrudan, 0),
    'turetilen', coalesce(v_turetilen, 0),
    'program_bilinmeyen', coalesce(v_bilinmeyen, 0),
    'dogrudan_beyan_yuzde', round(coalesce(v_dogrudan, 0)::numeric * 100 / nullif(v_ilan, 0), 1),
    'turetilen_yuzde',      round(coalesce(v_turetilen, 0)::numeric * 100 / nullif(v_ilan, 0), 1),
    'program_bilinmeyen_yuzde', v_bilinmeyen_yuzde,
    -- YENİ: kolonun kendi doluluk oranı. "Ekran neden böyle" sorusunun
    -- cevabı artık ekranın İÇİNDE.
    'kolon_dolulugu', jsonb_build_object(
      'program_id_dolu', coalesce(v_dogrudan, 0) + coalesce(v_turetilen, 0),
      'toplam', coalesce(v_ilan, 0)),
    'bilinmeyen_satiri', format('program bilinmeyen: %%%s', coalesce(v_bilinmeyen_yuzde, 0)),
    'satirlar', coalesce(v_satir, '[]'::jsonb),
    'gosterilen_ilan', coalesce(v_gosterilen, 0),
    'gizlenen_ilan', coalesce(v_ilan, 0) - coalesce(v_gosterilen, 0),
    'kapsam_yuzde', round(coalesce(v_gosterilen, 0)::numeric * 100 / nullif(v_ilan, 0), 1),
    'hesaplanabilir', v_satir is not null,
    'neden', case when v_satir is null
      then format('%s ilan var ama hiçbir program %s farklı host eşiğini geçmedi.', v_ilan, v_k) end,
    'not', format('İlanların %%%s''i programını host hak beyanından TÜRETİLMİŞ olarak taşıyor (215''ten beri kolonda `program_source` ile işaretli). Türetim bir çıkarımdır, beyan değildir.',
                  round(coalesce(v_turetilen, 0)::numeric * 100 / nullif(v_ilan, 0), 1)));
end $fn$;


-- ------------------------------------------------------------
-- 1f) NÖBETÇİ — GERÇEK RPC İLE YAZ, GERİ OKU, BOŞSA PATLA
-- ------------------------------------------------------------
-- 🔴 "Tetikleyiciyi yazdım" bir kanıt DEĞİLDİR. Kanıt: gerçek
-- `create_availability` çağrısıyla satır açmak ve `program_id`'yi geri
-- okumak. Yazmayan bir yazma yolu, olmayan yazma yolundan kötüdür —
-- çünkü yazıldığını sanırsınız.
--
-- 🔴 SAHNEYİ NÖBETÇİ KENDİ KURUYOR VE AYNEN GERİ BIRAKIYOR.
-- İlk yazımda var olan bir host'u seçtim ve nöbetçi `no_access_source`
-- ile düştü. Sonra eleme sayaçları koydum ve GERÇEK SEBEP çıktı:
--     Eleme: ilan=7 · venue'su olan=7 · profili olan=7 · kapasiteli=0
-- Yani 215 çalışırken sistemde YALNIZ 7 ilan var ve hiçbirinin host'u
-- erişim kaynağı beyan etmemiş. 25 ilanlı zengin sahne
-- `SEED_KURAL_SENARYOLARI.sql` ile geliyor — o dosya 215'ten SONRA
-- çalışıyor. "Veri var" varsayımı, o verinin NE ZAMAN geldiğini
-- bilmeden kurulmuş bir varsayımdı.
--
-- Çözüm 213'ün N1 nöbetçisiyle aynı: sahneyi kur, ölç, ESKİ HÂLİNE
-- DÖNDÜR. Kalıcı bir kapasite/doğrulama bırakmak, üründe olmayan bir
-- kullanıcı durumunu üretmek olurdu.
do $blok$
declare
  v_host uuid; v_lounge uuid; v_ven uuid; v_gun date;
  v jsonb; v_id uuid; v_pg uuid; v_src text;
  v_eski_kap int; v_dogrulama_vardi boolean; v_eski_email boolean; v_gecici_prog uuid;
begin
  -- Program çözülebilen ilk (host, salon) — kapasite/doğrulama ARANMIYOR,
  -- onları sahne olarak biz kuracağız.
  select a.host_id, a.lounge_id, l.venue_id
    into v_host, v_lounge, v_ven
    from availabilities a
    join lounges l on l.id = a.lounge_id
    join profiles pr on pr.user_id = a.host_id
   where l.venue_id is not null
     and public.pick_host_program(a.host_id, l.venue_id) is not null
   order by a.host_id, a.lounge_id
   limit 1;

  -- 🔴 SAHNEYİ TAM KURMAK — 214 SONRASI ÖĞRENİLDİ.
  -- Bu blok "programı çözülebilen bir ilan zaten VAR" varsayıyordu ve o
  -- varsayım 214 ile çöktü: 214, kaynaklarda listelenmeyen üç Primeclass
  -- kaydını pasife aldı ve Anatolia/Aeroport'un KAYNAKSIZ TK_MS kabul
  -- satırlarını geri çekti. 215 çalışırken elde kalan yedi ilanın
  -- hiçbirinin programı çözülmüyor — çünkü artık çözülmemesi DOĞRU.
  --
  -- Ders, 213'ün N1 nöbetçisinde yazılanın aynısı ve ikinci kez ısırdı:
  -- bir nöbetçi ÖLÇTÜĞÜ şeyi kendisi kurmalı. Var olan veriye yaslanan
  -- nöbetçi, veri değiştiği gün ürünü değil KENDİNİ kırar.
  -- Aşağısı eksik kalan yarısı: host'a, o salonun GERÇEKTEN kabul ettiği
  -- bir programdan geçici bir hak veriyoruz; blok sonunda geri alınıyor.
  if v_host is null then
    select a.host_id, a.lounge_id, l.venue_id
      into v_host, v_lounge, v_ven
      from availabilities a
      join lounges l  on l.id = a.lounge_id
      join lounge_venues v on v.id = l.venue_id and v.active
      join profiles pr on pr.user_id = a.host_id
     where exists (select 1 from lounge_venue_acceptance x
                    where x.venue_id = l.venue_id and x.accepted and x.active)
     order by a.host_id, a.lounge_id
     limit 1;
    if v_host is not null then
      select x.program_id into v_gecici_prog
        from lounge_venue_acceptance x
        join lounge_programs p on p.id = x.program_id
       where x.venue_id = v_ven and x.accepted and x.active
         and p.kind <> 'airline'          -- kart programı seç, havayolu statüsü değil
       order by p.code limit 1;
      if v_gecici_prog is null then
        select x.program_id into v_gecici_prog from lounge_venue_acceptance x
         where x.venue_id = v_ven and x.accepted and x.active limit 1;
      end if;
      insert into host_entitlements (user_id, program_id, verified, self_reported_at)
      values (v_host, v_gecici_prog, false, now())
      on conflict do nothing;
      raise notice '215: Ö7 sahnesi kuruldu — host''a gecici hak verildi (blok sonunda geri alinacak)';
    end if;
  end if;

  if v_host is null then
    raise exception '215: Ö7 nobetcisi CALISTIRILAMADI. Eleme: ilan=% · venue''su olan=% · profili olan=% · programi cozulen=%',
      (select count(*) from availabilities),
      (select count(*) from availabilities a join lounges l on l.id = a.lounge_id where l.venue_id is not null),
      (select count(*) from availabilities a join lounges l on l.id = a.lounge_id join profiles pr on pr.user_id = a.host_id where l.venue_id is not null),
      (select count(*) from availabilities a join lounges l on l.id = a.lounge_id join profiles pr on pr.user_id = a.host_id where l.venue_id is not null and public.pick_host_program(a.host_id, l.venue_id) is not null);
  end if;

  -- --- SAHNE KURULUYOR (eski hâl kaydediliyor) ---
  select guest_capacity into v_eski_kap from profiles where user_id = v_host;
  select true, email_verified into v_dogrulama_vardi, v_eski_email
    from verifications where user_id = v_host;

  if coalesce(v_eski_kap, 0) < 1 then
    update profiles set guest_capacity = 1 where user_id = v_host;
  end if;
  insert into verifications (user_id, email_verified, email_verified_at)
  values (v_host, true, now())
  on conflict (user_id) do update set email_verified = true, email_verified_at = now();

  -- Gelecekte, çakışmayan bir saat aralığı seç (create_availability
  -- geçmiş tarihi ve örtüşen slotu reddediyor — haklı olarak).
  v_gun := current_date + 300;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_host, 'role', 'authenticated')::text, true);

  v := public.create_availability(v_lounge, (select airport_code from lounges where id = v_lounge),
                                  v_gun, time '03:00', time '04:00', 1, null, 'hidden', null);
  perform set_config('request.jwt.claims', '', true);

  v_id := nullif(v ->> 'id', '')::uuid;
  if v_id is null then
    raise exception '215: Ö7 nobetcisi — create_availability id DONDURMEDI → %', v;
  end if;

  select program_id, program_source into v_pg, v_src from availabilities where id = v_id;

  if v_pg is null then
    raise exception '215: Ö7 KIRIK — gercek RPC ile acilan ilanin program_id degeri HALA NULL (ilan %). Tetikleyici yazmiyor.', v_id;
  end if;
  if v_src is distinct from 'turetildi' then
    raise exception '215: Ö7 KIRIK — program_source "turetildi" olmali, bulunan "%"; cikarim beyan gibi kaydediliyor.', v_src;
  end if;
  if (v ->> 'program_kaynagi') <> 'turetildi' then
    raise exception '215: Ö7 — RPC cevabi kaynagi SOYLEMIYOR → %', v;
  end if;

  raise notice '215: Ö7 KANIT — gercek create_availability cagrisi program_id=% (kaynak=%) yazdi', v_pg, v_src;

  -- --- SAHNE TOPLANIYOR — üründe hiçbir iz kalmıyor ---
  delete from availabilities where id = v_id;
  if v_gecici_prog is not null then
    delete from host_entitlements where user_id = v_host and program_id = v_gecici_prog;
  end if;
  update profiles set guest_capacity = v_eski_kap where user_id = v_host;
  if coalesce(v_dogrulama_vardi, false) then
    update verifications set email_verified = v_eski_email where user_id = v_host;
  else
    delete from verifications where user_id = v_host;
  end if;
end $blok$;


-- ============================================================
-- 2) Ö8 · FİYAT KATALOĞU — KAYNAKTAN, SATIR SATIR ALINTIYLA
-- ============================================================
-- 🔴 TEK KURAL: BU DOSYAYA UYDURULMUŞ TEK BİR FİYAT GİRMEZ.
-- Her satır /home/claude/kaynak/tur11/THY_AJET_PGS_KURAL.md içinde
-- BİREBİR YAZAN bir cümleden geliyor ve o cümle `note` kolonunda
-- tırnak içinde duruyor. Kaynağı olmayan salon LİSTEDE YOK — ve
-- raporun "bu salonun fiyat kaydı yok" demesi doğru davranıştır.
--
-- KAYNAKTA OLUP BURAYA GİRMEYENLER (ve sebebi — gizlemiyoruz):
--   · "Primeclass Lounge / Zürih Havalimanı : 40 CHF"  → ZRH'de
--     katalogda Primeclass YOK (yalnız "Aspire Lounge"). Salon eşleşmezse
--     fiyatı bir başkasına yazmak, fiyatı uydurmakla aynı şeydir.
--   · "Primeclass Lounge /Frankfurt Havalimanı : 36 EUR" → FRA'da
--     katalogda Primeclass YOK.
--   · "HelloSky Lounge / Milan Bergamo : 28 EUR", "… / Roma Fiumicino :
--     20 EUR" → katalogda HelloSky adlı salon YOK (FCO'da Plaza Premium var).
--   · AJet'in "Sabiha Gökçen Uluslararası Havalimanı*" satırı → fiyat
--     hücresi kaynakta "-" (salon geçici kapalı). Boş hücre fiyat değildir.
--
-- ⚠️ PARA BİRİMİ ÇEVRİLMİYOR. 27 EUR ile 2.800 TL aynı satırda
-- toplanmaz; `venue_price_position` zaten para birimine göre gruplar.
-- Kur uydurmak, fiyat uydurmaktır.

-- Kaynak eşlemesi salon ADI + HAVALİMANI ile yapılıyor, UUID ile değil:
-- `lounge_venues.id` her tam kurulumda yeniden üretiliyor (uuid_generate_v4),
-- sabit uuid yazmak dosyayı ikinci çalıştırmada sessizce boşa düşürürdü.
do $blok$
declare
  v_kayit int := 0;
  v_eslesmeyen text;
  v_pgs constant text := 'https://www.flypgs.com/seyahat-hizmetlerimiz/diger-seyahat-hizmetlerimiz/lounge';
  v_thy constant text := 'https://www.turkishairlines.com/tr-tr/bilgi-edin/lounge/kurallar-ve-kosullar/';
  v_tarih constant date := date '2026-08-17';
