-- 7) BACKOFFICE
-- ----------------------------------------------------------------------------
drop function if exists public.bo_plan_hediyeleri(text);

-- ----------------------------------------------------------------------
-- bekleyen_teslimler   [etkin kaynak: 229_odul_teslim_sozu.sql]
-- ----------------------------------------------------------------------
create or replace function public.bekleyen_teslimler()
returns table (
  id uuid, takip_no text, odul text, tedarikci text,
  kullanici uuid, eposta text, puan int,
  alindi timestamptz, son_tarih timestamptz, gecikti boolean, kalan_saat int
) language plpgsql stable security definer set search_path = public as $bt$
begin
  -- 🔴 YETKİ İKİ KATMANLI, ama KATMANLAR FARKLI ŞEYLERE BAKAR:
  --  (1) Bu fonksiyon istemci rollerine HİÇ verilmiyor (aşağıda yalnız
  --      service_role'a grant var + apply_rpc_surface() sınırı uyguluyor).
  --      BO `sbAdmin()` yani service_role ile çağırıyor.
  --  (2) Yine de biri bir gün authenticated'a grant verirse, aşağıdaki
  --      kontrol devreye girer. auth.uid() null ise service_role
  --      bağlamındayız (BO); doluysa gerçek bir kullanıcıdır ve
  --      admin_roles'ta olmak ZORUNDA.
  -- 205'in kalıbı yalnız (1)'e güveniyordu; bir grant hatası orada
  -- sessiz bir açık bırakırdı.
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  return query
  select d.id, d.voucher_code, r.title, r.supplier,
         d.user_id, u.email, d.cost_points,
         d.created_at, d.due_at,
         (d.due_at < now()),
         greatest(0, extract(epoch from (d.due_at - now()))/3600)::int
    from redemptions d
    join rewards r on r.id = d.reward_id
    left join users u on u.id = d.user_id
   where d.durum = 'bekliyor'
   order by d.due_at asc;
end $bt$;
grant execute on function public.bekleyen_teslimler() to service_role;   -- BO sbAdmin() ile cagirir

drop function if exists public.teslim_isaretle(uuid, text);

-- ----------------------------------------------------------------------
-- teslim_isaretle   [etkin kaynak: 229_odul_teslim_sozu.sql]
-- ----------------------------------------------------------------------
create or replace function public.teslim_isaretle(p_redemption uuid, p_ref text)
returns jsonb language plpgsql security definer set search_path = public as $ti$
declare v_d redemptions%rowtype; v_baslik text;
begin
  -- 🔴 YETKİ İKİ KATMANLI, ama KATMANLAR FARKLI ŞEYLERE BAKAR:
  --  (1) Bu fonksiyon istemci rollerine HİÇ verilmiyor (aşağıda yalnız
  --      service_role'a grant var + apply_rpc_surface() sınırı uyguluyor).
  --      BO `sbAdmin()` yani service_role ile çağırıyor.
  --  (2) Yine de biri bir gün authenticated'a grant verirse, aşağıdaki
  --      kontrol devreye girer. auth.uid() null ise service_role
  --      bağlamındayız (BO); doluysa gerçek bir kullanıcıdır ve
  --      admin_roles'ta olmak ZORUNDA.
  -- 205'in kalıbı yalnız (1)'e güveniyordu; bir grant hatası orada
  -- sessiz bir açık bırakırdı.
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select * into v_d from redemptions where id = p_redemption for update;
  if not found then raise exception 'redemption_not_found'; end if;
  if v_d.durum <> 'bekliyor' then raise exception 'already_settled'; end if;
  if coalesce(btrim(p_ref),'') = '' then raise exception 'ref_required'; end if;

  update redemptions
     set durum = 'teslim', fulfilled_at = now(), tedarikci_ref = btrim(p_ref)
   where id = p_redemption;

  select title into v_baslik from rewards where id = v_d.reward_id;
  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_d.user_id, 'system', 'Ödülün gönderildi 🎁',
          v_baslik || ' · e-posta adresine gönderildi. Kod: ' || btrim(p_ref),
          'reward', v_d.id);
  return jsonb_build_object('ok', true);
end $ti$;
grant execute on function public.teslim_isaretle(uuid, text) to service_role;   -- BO sbAdmin() ile cagirir

-- İptal = puan İADE. Teslim edemediğimiz bir ödül için puanı tutmak,
-- kullanıcıdan bedelsiz almak demektir.
drop function if exists public.teslim_iptal(uuid, text);

-- ----------------------------------------------------------------------
-- teslim_iptal   [etkin kaynak: 229_odul_teslim_sozu.sql]
-- ----------------------------------------------------------------------
create or replace function public.teslim_iptal(p_redemption uuid, p_neden text)
returns jsonb language plpgsql security definer set search_path = public as $tp$
declare v_d redemptions%rowtype; v_baslik text;
begin
  -- 🔴 YETKİ İKİ KATMANLI, ama KATMANLAR FARKLI ŞEYLERE BAKAR:
  --  (1) Bu fonksiyon istemci rollerine HİÇ verilmiyor (aşağıda yalnız
  --      service_role'a grant var + apply_rpc_surface() sınırı uyguluyor).
  --      BO `sbAdmin()` yani service_role ile çağırıyor.
  --  (2) Yine de biri bir gün authenticated'a grant verirse, aşağıdaki
  --      kontrol devreye girer. auth.uid() null ise service_role
  --      bağlamındayız (BO); doluysa gerçek bir kullanıcıdır ve
  --      admin_roles'ta olmak ZORUNDA.
  -- 205'in kalıbı yalnız (1)'e güveniyordu; bir grant hatası orada
  -- sessiz bir açık bırakırdı.
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select * into v_d from redemptions where id = p_redemption for update;
  if not found then raise exception 'redemption_not_found'; end if;
  if v_d.durum <> 'bekliyor' then raise exception 'already_settled'; end if;

  update redemptions
     set durum = 'iptal', iptal_notu = left(coalesce(p_neden,''), 300)
   where id = p_redemption;

  insert into points_ledger (user_id, delta, reason, ref_id)
  values (v_d.user_id, v_d.cost_points, 'reward_refund', v_d.reward_id);

  update rewards set stock = stock + 1
   where id = v_d.reward_id and stock is not null;

  select title into v_baslik from rewards where id = v_d.reward_id;
  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_d.user_id, 'system', 'Puanın iade edildi',
          v_baslik || ' teslim edilemedi (' || left(coalesce(p_neden,'sebep belirtilmedi'),120)
       || '). ' || v_d.cost_points || ' LoungePuan hesabına geri yüklendi.',
          'reward', v_d.id);
  return jsonb_build_object('ok', true, 'iade', v_d.cost_points);
end $tp$;
grant execute on function public.teslim_iptal(uuid, text) to service_role;   -- BO sbAdmin() ile cagirir

-- ----------------------------------------------------------------------------
-- 5) NÖBETÇİ
-- ----------------------------------------------------------------------------
do $n229$
declare
  v_sozsuz  int;
  v_kisit   int;
  v_geciken int;
  v_aktif   int;
begin
  select count(*) into v_sozsuz from rewards
   where coalesce(active,true)
     and (teslim_sekli is null or teslim_saat is null or supplier is null);
  if v_sozsuz <> 0 then
    raise exception '229 NOBETCI: % aktif odul teslim sozu olmadan magazada duruyor.', v_sozsuz;
  end if;

  select count(*) into v_kisit from pg_constraint
   where conname in ('rewards_teslim_sozu_chk','redemptions_durum_chk','redemptions_teslim_zamani_chk');
  if v_kisit <> 3 then
    raise exception '229 NOBETCI: 3 kisit bekleniyordu, % kuruldu.', v_kisit;
  end if;

  -- Kupon kelimesi artık kodda kalmamalı: eski metin geri sızarsa
  -- kullanıcı yine kullanılabilir bir kod sanır.
  if exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
              where n.nspname='public' and p.proname='redeem_reward'
                and p.prosrc like '%Kupon: %') then
    raise exception '229 NOBETCI: redeem_reward hala "Kupon:" diye sunuyor.';
  end if;

  select count(*) into v_aktif from rewards where coalesce(active,true);
  select count(*) into v_geciken from redemptions
   where durum='bekliyor' and due_at < now();

  raise notice '229 OK · aktif odul: % (hepsi teslim sozlu) · bekleyen gecikmis teslim: %',
    v_aktif, v_geciken;
  raise notice '229 OLCULMEDI: tedarikci entegrasyonu YOK. Bugun teslim MANUEL — '
               'bekleyen_teslimler() kuyrugunu birinin acmasi gerekiyor. '
               'Kuyruk bos kalmazsa soz tutulmuyor demektir.';
end $n229$;

-- ----------------------------------------------------------------------------
-- 6) RPC YÜZEYİ — 203'ün kuralı: fonksiyon üreten her dosya SONUNDA çağırır
-- ----------------------------------------------------------------------------
-- 🔴 Bu bölümü İLK YAZIMDA UNUTTUM ve harness yakaladı:
--     ⚠ RPC yuzeyi ihlali: teslim_isaretle -> yuzeyde yok ama istemciye acik
-- `redeem_reward` zaten yüzeydeydi (017'den beri). Yeni BO fonksiyonları
-- yüzeye GİRMEZ — onlar yalnız service_role. apply_rpc_surface() bunu
-- zorluyor; aşağıdaki çağrı olmasaydı grant'lar açık kalırdı.
do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '229: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- host_hikaye_yaz   [etkin kaynak: 230_host_hikayeleri.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_hikaye_yaz(
  p_session uuid, p_metin text, p_gorunen_ad text,
  p_gorunen_not text default null, p_riza boolean default false)
returns jsonb language plpgsql security definer set search_path = public as $hy$
declare v_uid uuid := auth.uid(); v_s sessions%rowtype; v_r requests%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_s from sessions where id = p_session;
  if not found or v_s.status <> 'completed' then
    raise exception 'session_not_completed';
  end if;
  select * into v_r from requests where id = v_s.request_id;
  if not found or v_r.host_id <> v_uid then
    raise exception 'not_host_of_session';   -- misafirin hikâyesi ayrı bir şey
  end if;

  if coalesce(btrim(p_gorunen_ad),'') = '' then raise exception 'display_name_required'; end if;

  insert into host_stories (user_id, session_id, metin, gorunen_ad, gorunen_not, riza_at)
  values (v_uid, p_session, btrim(p_metin), btrim(p_gorunen_ad),
          nullif(btrim(coalesce(p_gorunen_not,'')),''),
          case when p_riza then now() else null end)
  on conflict (session_id) do update
     set metin = excluded.metin,
         gorunen_ad = excluded.gorunen_ad,
         gorunen_not = excluded.gorunen_not,
         -- Rızayı GERİ ALMAK mümkün: false gönderilirse riza_at silinir
         -- ve kısıt yayından düşürür.
         riza_at = excluded.riza_at,
         yayinda = case when excluded.riza_at is null then false else host_stories.yayinda end;

  return jsonb_build_object('ok', true, 'riza', p_riza,
    'not', case when p_riza then 'Yayınlanmak üzere sıraya alındı — önce biz okuyacağız.'
                else 'Kaydedildi. Yayınlanması için izin vermen gerekiyor.' end);
end $hy$;
grant execute on function public.host_hikaye_yaz(uuid, text, text, text, boolean) to authenticated;

-- ----------------------------------------------------------------------------
-- 2) Site okuması — anon, yalnız yayındakiler, kişisel veri YOK
-- ----------------------------------------------------------------------------
drop function if exists public.yayindaki_host_hikayeleri(int);

-- ----------------------------------------------------------------------
-- yayindaki_host_hikayeleri   [etkin kaynak: 230_host_hikayeleri.sql]
-- ----------------------------------------------------------------------
create or replace function public.yayindaki_host_hikayeleri(p_limit int default 3)
returns table (metin text, gorunen_ad text, gorunen_not text)
language sql stable security definer set search_path = public as $yh$
  select s.metin, s.gorunen_ad, s.gorunen_not
    from host_stories s
   where s.yayinda and s.riza_at is not null and s.onay_at is not null
   order by s.onay_at desc
   limit greatest(1, least(coalesce(p_limit,3), 12));
$yh$;
grant execute on function public.yayindaki_host_hikayeleri(int) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2b) DAVET — app'in soracağı tek soru
-- ----------------------------------------------------------------------------
-- 🔴 KURULAN MAKİNE, KİMSE TETİKLEMEZSE ÇALIŞMAZ.
-- 228'in dersi buydu: kuralı metne yazmak onu sistemde uygulamak
-- değildir. Aynısı burada geçerli — `host_hikaye_yaz()` var ama hiçbir
-- ekran host'a "bir cümle yazar mısın?" demiyorsa tablo boş kalır ve
-- sitedeki bölüm hiç açılmaz.
--
-- Bu RPC app'in ana sayfasında sorulacak TEK daveti döndürür:
--   · oturum TAMAMLANMIŞ
--   · çağıran kişi o oturumun HOST'u
--   · o oturum için henüz hikâye YOK
--   · en fazla BİR tane (üst üste davet, davet değil baskıdır)

-- ----------------------------------------------------------------------
-- bekleyen_hikaye_daveti   [etkin kaynak: 296_hikaye_daveti_erteleme.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.bekleyen_hikaye_daveti()
returns table (session_id uuid, salon text, tarih date, misafir text)
language plpgsql
stable
security definer
set search_path to 'public'
as $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  return query
  select s.id,
         coalesce(a.lounge_name, a.airport_code),
         a.avail_date,
         coalesce(p.name, 'Misafirin')
    from sessions s
    join requests r      on r.id = s.request_id
    left join availabilities a on a.id = r.avail_id
    left join profiles p on p.user_id = r.guest_id
   where s.status = 'completed'
     and r.host_id = v_uid
     and not exists (select 1 from host_stories h where h.session_id = s.id)
     -- 🔴 296 — "Şimdi değil" burada karşılığını buluyor.
     and not exists (
       select 1 from public.hikaye_ertelemeleri e
        where e.session_id = s.id and e.user_id = v_uid
          and e.ertelendi_at > now() - interval '30 days')
   order by s.completed_at desc nulls last
   limit 1;
end $function$;

grant execute on function public.bekleyen_hikaye_daveti() to authenticated;

-- ── Kendi sınaması ──────────────────────────────────────────────────────
-- ════════════════════════════════════════════════════════════════════════
-- 🔴 21 EYLÜL — BU SINAMA GÖKBERK'İN VERİTABANINDA DÜŞTÜ, ÜRÜN DOĞRUYKEN.
--
--     ERROR:  P0001: 296: 31 gun sonra tekrar sorulmadi (erteleme kalici oldu)
--
-- Yerelde geçiyordu. Sebebini bulup BİREBİR ürettim: `bekleyen_hikaye_daveti()`
-- TEK bir davet döndürür (`order by completed_at desc ... limit 1`) — çünkü
-- ürün aynı anda tek davet gösteriyor. Sınama ise BAŞKA bir `limit 1` ile,
-- SIRASIZ olarak rastgele bir tamamlanmış oturum seçip "fonksiyon TAM BU
-- oturumu döndürecek" diye varsayıyordu.
--
-- Bir host'un birden çok hikâyesiz tamamlanmış oturumu varsa iki `limit 1`
-- FARKLI satırı gösterir ve sınama, ürün kusursuz çalışırken patlar.
-- Ölçtüm: yerelde bir host'ta 3 bekleyen oturum var; sınamayı o host'a
-- sabitleyip en ESKİ oturumu seçtirdiğimde Gökberk'in aldığı hatanın
-- AYNISI çıktı.
--
-- ⚠️ BU SINIF BU PROJEDE İKİNCİ KEZ: SQL 211'in kendi sınama bloğu da
-- sırasız `limit 1` yüzünden bir kez düşmüştü. O zaman "sıra sabitlendi"
-- diye çözülmüştü — yani SEMPTOM düzeltilmiş, SINIF düzeltilmemişti.
-- `order by` eklemek de yetmez: doğru cevap, sınamanın kendi satırını
-- SEÇMEMESİ, FONKSİYONUN DÖNDÜRDÜĞÜ satırı almasıdır. Fonksiyonun sırası
-- yarın değişse bile sınama yine doğru satıra bakar.
--
-- 🆕 SINIF: "BİR FONKSİYONUN DÖNDÜRECEĞİ SATIRI SINAMADA YENİDEN SEÇERSEN,
-- İKİ SEÇİMİN AYNI SATIRA DÜŞTÜĞÜNÜ DE VARSAYMIŞ OLURSUN — SEÇME, SOR."
-- ════════════════════════════════════════════════════════════════════════
do $$
declare v_sid uuid; v_host uuid; v_ikinci uuid; v_sonra int;
begin
  -- Yalnız KİMLİK için bir aday: hangi host'un bekleyen daveti var?
  select r.host_id into v_host
    from sessions s join requests r on r.id = s.request_id
   where s.status = 'completed'
     and not exists (select 1 from host_stories h where h.session_id = s.id)
   order by r.host_id
   limit 1;
  if v_host is null then raise notice '296 sinama: uygun tamamlanmis oturum yok, atlandi'; return; end if;

  perform set_config('request.jwt.claims',
    json_build_object('sub', v_host::text, 'role','authenticated')::text, true);

  -- ⚠️ SATIRI SEÇMİYORUZ, SORUYORUZ. Sınamanın tamamı bu satıra dayanıyor.
  select session_id into v_sid from public.bekleyen_hikaye_daveti();
  if v_sid is null then raise notice '296 sinama: davet zaten gorunmuyor, atlandi'; return; end if;

  perform public.hikaye_davetini_ertele(v_sid);

  -- 1) Ertelenen davet ARTIK SORULMAMALI.
  select count(*) into v_sonra from public.bekleyen_hikaye_daveti()
   where session_id = v_sid;
  if v_sonra <> 0 then
    raise exception '296: ertelenen davet HALA soruluyor';
  end if;

  -- 2) "Şimdi değil" TEK daveti erteler, HEPSİNİ SUSTURMAZ.
  --    (Bu ölçü eskiden yoktu; ürünün asıl vaadi bu ve sınanmıyordu.)
  select session_id into v_ikinci from public.bekleyen_hikaye_daveti();
  if v_ikinci is not null and v_ikinci = v_sid then
    raise exception '296: erteleme sonrasi AYNI davet geri geldi';
  end if;

  -- 3) 30 günden eski bir erteleme TEKRAR sorulabilmeli.
  --    Diğer bekleyenleri de erteleyip alanı boşaltıyoruz ki fonksiyonun
  --    tek satırlık penceresi v_sid'i göstermek zorunda kalsın — yoksa
  --    bu adım yine "hangi satır döndü" kumarına dönerdi.
  insert into public.hikaye_ertelemeleri (session_id, user_id, ertelendi_at)
  select s.id, v_host, now()
    from sessions s join requests r on r.id = s.request_id
   where s.status = 'completed' and r.host_id = v_host and s.id <> v_sid
     and not exists (select 1 from host_stories h where h.session_id = s.id)
  on conflict do nothing;

  update public.hikaye_ertelemeleri set ertelendi_at = now() - interval '31 days'
   where session_id = v_sid and user_id = v_host;

  select count(*) into v_sonra from public.bekleyen_hikaye_daveti()
   where session_id = v_sid;
  if v_sonra = 0 then
    raise exception '296: 31 gun sonra tekrar sorulmadi (erteleme kalici oldu)';
  end if;

  raise notice '296 sinama: erteleme 30 gun tutuyor, tek daveti susturuyor, sonra geri geliyor — OK';
  raise exception 'GERI_AL_SINAMA';
exception
  when others then
    if SQLERRM <> 'GERI_AL_SINAMA' then raise; end if;
end $$;

-- ----------------------------------------------------------------------
-- host_hikaye_onayla   [etkin kaynak: 230_host_hikayeleri.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_hikaye_onayla(p_id uuid, p_yayinla boolean default true)
returns jsonb language plpgsql security definer set search_path = public as $ho$
declare v_h host_stories%rowtype;
begin
  -- 🔴 YETKİ İKİ KATMANLI, ama KATMANLAR FARKLI ŞEYLERE BAKAR:
  --  (1) Bu fonksiyon istemci rollerine HİÇ verilmiyor (aşağıda yalnız
  --      service_role'a grant var + apply_rpc_surface() sınırı uyguluyor).
  --      BO `sbAdmin()` yani service_role ile çağırıyor.
  --  (2) Yine de biri bir gün authenticated'a grant verirse, aşağıdaki
  --      kontrol devreye girer. auth.uid() null ise service_role
  --      bağlamındayız (BO); doluysa gerçek bir kullanıcıdır ve
  --      admin_roles'ta olmak ZORUNDA.
  -- 205'in kalıbı yalnız (1)'e güveniyordu; bir grant hatası orada
  -- sessiz bir açık bırakırdı.
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select * into v_h from host_stories where id = p_id for update;
  if not found then raise exception 'story_not_found'; end if;
  if p_yayinla and v_h.riza_at is null then
    raise exception 'consent_missing';   -- kısıt da engelliyor; burada AÇIKÇA söylüyoruz
  end if;

  update host_stories
     set onay_at = case when p_yayinla then now() else null end,
         yayinda = p_yayinla
   where id = p_id;
  return jsonb_build_object('ok', true, 'yayinda', p_yayinla);
end $ho$;
grant execute on function public.host_hikaye_onayla(uuid, boolean) to service_role;   -- BO sbAdmin() ile cagirir

drop function if exists public.bekleyen_host_hikayeleri();

-- ----------------------------------------------------------------------
-- bekleyen_host_hikayeleri   [etkin kaynak: 230_host_hikayeleri.sql]
-- ----------------------------------------------------------------------
create or replace function public.bekleyen_host_hikayeleri()
returns table (id uuid, metin text, gorunen_ad text, gorunen_not text,
               riza_at timestamptz, created_at timestamptz)
language plpgsql stable security definer set search_path = public as $bh$
begin
  -- 🔴 YETKİ İKİ KATMANLI, ama KATMANLAR FARKLI ŞEYLERE BAKAR:
  --  (1) Bu fonksiyon istemci rollerine HİÇ verilmiyor (aşağıda yalnız
  --      service_role'a grant var + apply_rpc_surface() sınırı uyguluyor).
  --      BO `sbAdmin()` yani service_role ile çağırıyor.
  --  (2) Yine de biri bir gün authenticated'a grant verirse, aşağıdaki
  --      kontrol devreye girer. auth.uid() null ise service_role
  --      bağlamındayız (BO); doluysa gerçek bir kullanıcıdır ve
  --      admin_roles'ta olmak ZORUNDA.
  -- 205'in kalıbı yalnız (1)'e güveniyordu; bir grant hatası orada
  -- sessiz bir açık bırakırdı.
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  return query
  select h.id, h.metin, h.gorunen_ad, h.gorunen_not, h.riza_at, h.created_at
    from host_stories h
   where h.riza_at is not null and h.onay_at is null
   order by h.riza_at asc;
end $bh$;
grant execute on function public.bekleyen_host_hikayeleri() to service_role;   -- BO sbAdmin() ile cagirir

-- ----------------------------------------------------------------------------
-- 4) NÖBETÇİ — mutasyona dayanıklı
-- ----------------------------------------------------------------------------
do $n230$
declare v_kisit int; v_yayin int; v_riza_yok int; v_test uuid;
begin
  select count(*) into v_kisit from pg_constraint
   where conname in ('hs_yayin_riza_chk','hs_metin_uzunluk_chk');
  if v_kisit <> 2 then
    raise exception '230 NOBETCI: 2 kisit bekleniyordu, % kuruldu.', v_kisit;
  end if;

  -- Rızasız yayın gerçekten imkânsız mı? Deneyerek ölç.
  begin
    insert into host_stories (user_id, session_id, metin, gorunen_ad, yayinda)
    select u.id, s.id, 'Riza olmadan yayina almayi deniyorum, engellenmeli.', 'Test', true
      from users u, sessions s limit 1;
    -- Buraya düşmek kısıtın çalışmadığı anlamına gelir.
    raise exception '230 NOBETCI: RIZASIZ YAYIN GECTI — kisit calismiyor.';
  exception
    when check_violation then
      null;  -- beklenen
    when others then
      -- Boş veritabanında users/sessions yoksa insert hiç satır üretmez;
      -- o durumda kısıt sınanamaz. Sustuğumu SÖYLÜYORUM.
      raise notice '230 OLCULMEDI: rizasiz-yayin mutasyonu calistirilamadi (%). Kisit tanimi yerinde.', sqlerrm;
  end;

  select count(*) into v_yayin from host_stories where yayinda;
  select count(*) into v_riza_yok from host_stories where yayinda and riza_at is null;
  if v_riza_yok <> 0 then
    raise exception '230 NOBETCI: % hikaye RIZASIZ yayinda.', v_riza_yok;
  end if;

  raise notice '230 OK · yayindaki host hikayesi: % · rizasiz yayin: 0', v_yayin;
  raise notice '230 NOT: bugun 0 hikaye var ve bu DOGRU — site bolumu bos oldugu icin '
               'HIC GORUNMUYOR. Ilk oturum tamamlaninca host_hikaye_yaz() ile toplanacak.';
end $n230$;

-- ----------------------------------------------------------------------------
-- 5) RPC YÜZEYİ
-- ----------------------------------------------------------------------------
-- App host'un hikâyesini yazacak, site yayındakileri okuyacak: ikisi de
-- yüzeye giriyor. Moderasyon fonksiyonları GİRMİYOR (BO = service_role).
insert into rpc_client_surface (fn_name, client, note) values
  ('host_hikaye_yaz','app','Host tamamlanan oturumdan sonra tek cumlesini yazar (230)'),
  ('bekleyen_hikaye_daveti','app','App ana sayfasi: hikayesi yazilmamis TEK tamamlanmis oturum (230)'),
  ('yayindaki_host_hikayeleri','public_web','Site: yalnizca riza+onay almis hikayeler (230)')
on conflict (fn_name) do update set note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '230: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- kurucu_cember   [etkin kaynak: 231_kurucu_cember_sayaci.sql]
-- ----------------------------------------------------------------------
create or replace function public.kurucu_cember()
returns jsonb language plpgsql stable security definer set search_path = public as $kc$
declare
  v_kontenjan int := coalesce((select (value #>> '{}')::int from beta_settings where key='kurucu_kontenjan'), 100);
  v_esik      int := coalesce((select (value #>> '{}')::int from beta_settings where key='kurucu_gosterim_esigi'), 10);
  v_host      int;
begin
  select count(*)::int into v_host from waitlist where role = 'host';

  if v_host < v_esik then
    -- 🔴 SAYI DÖNMÜYOR. Eşik altındayken ham sayıyı döndürüp "sen
    -- gizle" demek, sızıntıyı zaman meselesi yapardı.
    return jsonb_build_object(
      'goster', false,
      'kontenjan', v_kontenjan,
      'neden', 'esik_alti'
    );
  end if;

  return jsonb_build_object(
    'goster', true,
    'kontenjan', v_kontenjan,
    -- Kontenjan dolduysa sayı kontenjanı AŞMIŞ gösterilmez: "100/100"
    -- doğrudur, "137/100" saçmadır.
    'dolan', least(v_host, v_kontenjan),
    'kalan', greatest(v_kontenjan - v_host, 0)
  );
end $kc$;
grant execute on function public.kurucu_cember() to anon, authenticated;

comment on function public.kurucu_cember() is
  'Site sayaci. Esik altinda HAM SAYI DONDURMEZ (goster=false) — 3 kisilik bir '
  'liste gostermek sosyal kanitin tersini yapar. Karar burada verilir ki sitede '
  'gevsetilemesin.';

-- ----------------------------------------------------------------------------
-- NÖBETÇİ — eşik davranışını GERÇEKTEN dener
-- ----------------------------------------------------------------------------
do $n231$
declare
  v_cevap jsonb;
  v_host  int;
  v_esik  int;
begin
  select count(*)::int into v_host from waitlist where role='host';
  select coalesce((value #>> '{}')::int, 10) into v_esik from beta_settings where key='kurucu_gosterim_esigi';

  v_cevap := public.kurucu_cember();

  if (v_cevap->>'goster')::boolean then
    if v_cevap ? 'dolan' = false then
      raise exception '231 NOBETCI: goster=true ama dolan alani yok.';
    end if;
    if (v_cevap->>'dolan')::int > (v_cevap->>'kontenjan')::int then
      raise exception '231 NOBETCI: dolan (%) kontenjani (%) asiyor.',
        v_cevap->>'dolan', v_cevap->>'kontenjan';
    end if;
  else
    -- 🔴 EN ÖNEMLİ SINAMA: eşik altındayken ham sayı SIZMAMALI.
    if v_cevap ? 'dolan' or v_cevap ? 'kalan' then
      raise exception '231 NOBETCI: esik altinda ham sayi sizdi: %', v_cevap::text;
    end if;
  end if;

  raise notice '231 OK · host kaydi: % · esik: % · sayac gosteriliyor mu: %',
    v_host, v_esik, (v_cevap->>'goster');
  raise notice '231 NOT: bugun sayac muhtemelen GIZLI (esik alti) ve bu DOGRU. '
               'Liste % kisiye ulasinca site kendiliginden gostermeye baslar — '
               'kod degistirmeye gerek yok.', v_esik;
end $n231$;

-- ----------------------------------------------------------------------------
-- RPC YÜZEYİ
-- ----------------------------------------------------------------------------
insert into rpc_client_surface (fn_name, client, note) values
  ('kurucu_cember','public_web','Site sayaci — esik altinda ham sayi DONDURMEZ (231)')
on conflict (fn_name) do update set note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '231: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- rolumu_sec   [etkin kaynak: 232_rol_kapisi_ve_cuzdan_sizintisi.sql]
-- ----------------------------------------------------------------------
create or replace function public.rolumu_sec(p_role text, p_gender text default null)
returns jsonb language plpgsql security definer set search_path = public as $rs$
declare
  v_uid   uuid := auth.uid();
  v_eski  user_role;
  v_yeni  user_role;
  v_kay   text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_role is null or p_role not in ('guest','host') then
    raise exception 'gecersiz_rol';
  end if;

  select role into v_eski from users where id = v_uid;
  v_yeni := p_role::user_role;

  if v_eski = v_yeni then
    -- Cinsiyet beyanı gelmişse yine de yaz; boşa dönüş verme.
    if p_gender is not null then
      update users set gender = p_gender::user_gender where id = v_uid;
    end if;
    return jsonb_build_object('ok', true, 'rol', v_yeni::text, 'degisti', false);
  end if;

  v_kay := case when v_yeni = 'host' then 'beyan' else 'geri' end;

  update users
     set role = v_yeni,
         role_source = v_kay,
         role_changed_at = now(),
         gender = coalesce(p_gender::user_gender, gender)
   where id = v_uid;

  insert into audit_log (actor_id, action, entity_type, entity_id, before_data, after_data)
  values (v_uid, 'user.role_change', 'users', v_uid,
          jsonb_build_object('role', v_eski::text),
          jsonb_build_object('role', v_yeni::text, 'source', v_kay));

  return jsonb_build_object('ok', true, 'rol', v_yeni::text, 'degisti', true);
end $rs$;
grant execute on function public.rolumu_sec(text, text) to authenticated;

-- `create_availability` terfisi de kaynağını yazsın. Fonksiyonun gövdesine
-- DOKUNMUYORUM (bu projede en çok dokunulan fonksiyon ve her dokunuşta bir
-- şey bozuldu — 206'nın notu). Tetikleyiciyle ekliyorum.

-- ----------------------------------------------------------------------
-- trg_rol_kaynagi   [etkin kaynak: 232_rol_kapisi_ve_cuzdan_sizintisi.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_rol_kaynagi()
returns trigger language plpgsql security definer set search_path = public as $rk$
begin
  if new.role is distinct from old.role then
    new.role_changed_at := now();
    if new.role_source is not distinct from old.role_source then
      -- rolumu_sec kaynağı zaten yazdıysa dokunma; yazmayan tek yol
      -- create_availability'nin doğrudan update'i.
      new.role_source := case when new.role = 'host' then 'ilan' else 'geri' end;
    end if;
  end if;
  return new;
end $rk$;
drop trigger if exists trg_users_rol_kaynagi on users;
create trigger trg_users_rol_kaynagi before update of role on users
  for each row execute function public.trg_rol_kaynagi();

-- ----------------------------------------------------------------------------
-- 3) profiles: KOLON DÜZEYİNDE YAZMA
-- ----------------------------------------------------------------------------
-- `guest_capacity` ve `access_source` artık yalnız `save_host_access()`
-- üzerinden yazılır — o fonksiyon kotayı, statüyü ve kart ürününü birlikte
-- tutarlı yazıyor; doğrudan update ise yalnız bir kolonu değiştirip geri
-- kalanı tutarsız bırakıyordu.
revoke update on public.profiles from authenticated;
revoke update on public.profiles from anon;          -- ← v2: eksik olan satır
revoke update (guest_capacity, access_source, guest_fee_expected)
  on public.profiles from authenticated;
revoke update (guest_capacity, access_source, guest_fee_expected)
  on public.profiles from anon;
grant update (
  name, profession, bio, languages, linkedin_url, photo_url,
  updated_at
) on public.profiles to authenticated;

-- 🔴 Yukarıdaki listeye SONRADAN eklenen kolonlar dahil değil; hangileri
-- var, ölçerek ekliyorum. Elle liste tutmak bu projede üç kez eksik kaldı
-- (site paleti dersi). Aşağıdaki blok "istemcinin yazması ZARARSIZ" olan
-- kolonları veriden türetir: kapı kolonları hariç HEPSİ.
do $pg$
declare
  v_kolon text;
  v_kapi  text[] := array[
    'user_id','guest_capacity','access_source','guest_fee_expected',
    'created_at','trust_score','show_on_discover'
  ];
  v_n int := 0;
begin
  for v_kolon in
    select column_name from information_schema.columns
     where table_schema='public' and table_name='profiles'
       and column_name <> all (v_kapi)
       and is_generated = 'NEVER'
  loop
    execute format('grant update (%I) on public.profiles to authenticated', v_kolon);
    v_n := v_n + 1;
  end loop;
  raise notice '232: profiles uzerinde % kolon istemciye yazilabilir, % kapi kolonu kapali',
    v_n, array_length(v_kapi,1);
end $pg$;

-- ----------------------------------------------------------------------------
-- 4) host_wallet: BAŞKASININ CÜZDANI KAPANDI
-- ----------------------------------------------------------------------------
-- sqlcheck: allow-replace host_wallet  (returns jsonb — 206/208 ile AYNI tip)
--
-- Gövdeyi yeniden yazmıyorum: 208'in hesabı (kalan hak, değer, dönem devri)
-- olduğu gibi kalsın. Yaptığım tek şey ÖNÜNE BİR KAPI KOYMAK — sarmalayıcı
-- değil, aynı fonksiyonun başına eklenen üç satır.
do $hw$
declare v_govde text;
begin
  select pg_get_functiondef(p.oid) into v_govde
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   -- 🔴 250'DE AYRIŞTIRILDI: kapı artık `host_wallet`te, hesap
   -- `host_wallet_hesap`ta. Bu nöbetçi İKİSİNE BİRDEN bakar; aksi hâlde
   -- doğru bir mimari düzeltmeyi ihlal sanardı.
   -- 🆕 SINIF: "BİR NÖBETÇİ TEK BİR FONKSİYON ADINA KİLİTLİYSE, O
   -- FONKSİYON BÖLÜNDÜĞÜ GÜN KÖRLEŞİR."
   where n.nspname='public' and p.proname in ('host_wallet','host_wallet_hesap') limit 1;

  if v_govde is null then
    raise notice '232: host_wallet bulunamadi — kapi kurulamadi (bos veritabani?)';
    return;
  end if;

  -- Zaten kapı varsa iki kez ekleme (idempotent).
  if v_govde like '%cuzdan_sahibi_degil%' then
    raise notice '232: host_wallet kapisi ZATEN var — dokunulmadi';
    return;
  end if;

  -- İlk `begin`den sonraya kapıyı yerleştir.
  v_govde := regexp_replace(
    v_govde,
    '(\mbegin\M)',
    'begin' || E'\n' ||
    '  if p_user is not null and p_user <> auth.uid()' || E'\n' ||
    '     and not exists (select 1 from admin_roles where user_id = auth.uid()) then' || E'\n' ||
    '    raise exception ''cuzdan_sahibi_degil'';' || E'\n' ||
    '  end if;',
    ''   -- yalnız İLK eşleşme
  );
  execute v_govde;
  raise notice '232: host_wallet kapisi kuruldu (p_user yalniz kendisi ya da admin)';
end $hw$;

-- ----------------------------------------------------------------------------
-- 5) NÖBETÇİ — üç açığı da DENEYEREK ölç
-- ----------------------------------------------------------------------------
do $n232$
declare
  v_rol_grant int;
  v_prof_grant int;
  v_kapi int;
begin
  -- (a) rol kolonu istemciye kapalı mı?
  select count(*) into v_rol_grant
    from information_schema.column_privileges
   where table_schema='public' and table_name='users' and column_name='role'
     and privilege_type='UPDATE' and grantee in ('authenticated','anon');
  if v_rol_grant <> 0 then
    raise exception '232 NOBETCI: users.role hala istemciye YAZILABILIR (% grant) → %',
      v_rol_grant,
      (select string_agg(grantee, ', ' order by grantee)
         from information_schema.column_privileges
        where table_schema='public' and table_name='users' and column_name='role'
          and privilege_type='UPDATE' and grantee in ('authenticated','anon'));
  end if;

  -- (b) profiles kapı kolonları kapalı mı?
  select count(*) into v_prof_grant
    from information_schema.column_privileges
   where table_schema='public' and table_name='profiles'
     and column_name in ('guest_capacity','access_source','guest_fee_expected')
     and privilege_type='UPDATE' and grantee in ('authenticated','anon');
  if v_prof_grant <> 0 then
    -- 🔴 v1'DE BU SATIR YALNIZ SAYIYORDU: "3 grant". Hangi rol, hangi
    -- kolon — hiçbiri yoktu. Gökberk'e teşhis değil bilmece gönderdim.
    -- Bir nöbetçi kusuru bulup ADINI söylemiyorsa, işin yarısını
    -- yapıp diğer yarısını okuyana bırakıyor demektir.
    raise exception '232 NOBETCI: profiles kapi kolonlari hala yazilabilir (% grant) → %',
      v_prof_grant,
      (select string_agg(grantee || '.' || column_name, ', ' order by grantee, column_name)
         from information_schema.column_privileges
        where table_schema='public' and table_name='profiles'
          and column_name in ('guest_capacity','access_source','guest_fee_expected')
          and privilege_type='UPDATE' and grantee in ('authenticated','anon'));
  end if;

  -- (c) host_wallet kapısı gerçekten gövdede mi?
  select count(*) into v_kapi
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   -- 🔴 250'DE AYRIŞTIRILDI: kapı artık `host_wallet`te, hesap
   -- `host_wallet_hesap`ta. Bu nöbetçi İKİSİNE BİRDEN bakar; aksi hâlde
   -- doğru bir mimari düzeltmeyi ihlal sanardı.
   -- 🆕 SINIF: "BİR NÖBETÇİ TEK BİR FONKSİYON ADINA KİLİTLİYSE, O
   -- FONKSİYON BÖLÜNDÜĞÜ GÜN KÖRLEŞİR."
   where n.nspname='public' and p.proname in ('host_wallet','host_wallet_hesap')
     and p.prosrc like '%cuzdan_sahibi_degil%';
  if v_kapi < 1 then
    raise exception '232 NOBETCI: host_wallet kapisi govdede YOK.';
  end if;

  raise notice '232 OK · rol istemciden kapali · profiles kapi kolonlari kapali · host_wallet sahiplik kapisi kurulu';
  raise notice '232 OLCULMEDI: gercek Supabase''te `anon`/`authenticated` rollerine SEMA duzeyinde '
               'toplu grant verilmis olabilir. Canlida sunu calistirip bos donmeli: '
               'select * from information_schema.column_privileges where table_name=''users'' and column_name=''role'';';
end $n232$;

-- ----------------------------------------------------------------------------
-- 6) RPC YÜZEYİ
-- ----------------------------------------------------------------------------
insert into rpc_client_surface (fn_name, client, note) values
  ('rolumu_sec','app','Rol degisiminin TEK kapisi — istemci artik users.role yazamaz (232)')
on conflict (fn_name) do update set note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '232: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- aktif_oturum_detay   [etkin kaynak: 234_aktif_oturum_kendini_anlatsin.sql]
-- ----------------------------------------------------------------------
create or replace function public.aktif_oturum_detay(p_request_id uuid)
returns table (
  session_id uuid, request_id uuid, durum text,
  other_id uuid, other_name text, i_am_host boolean,
  lounge text, airport_code text, avail_date date,
  time_from time, time_to time, flight_number text, carrier text,
  started_at timestamptz, completed_at timestamptz,
  host_confirmed boolean, guest_confirmed boolean,
  cancel_grace_until timestamptz
)
language plpgsql stable security definer set search_path = public as $ao$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  return query
  select s.id, r.id, s.status::text,
         case when r.host_id = v_uid then r.guest_id else r.host_id end,
         -- 🔴 `coalesce(p.name, 'Yolcu')` — 187'nin kalıbı. Ham uuid ya da
         -- boş string ekrana DÜŞMEZ; düşerse kullanıcı "Guest" görür ve
         -- bu ekranın tamamı güvenilmez olur.
         coalesce(nullif(btrim(p.name), ''), 'Yolcu'),
         (r.host_id = v_uid),
         -- Salon adı: serbest metin → katalog adı → havalimanı kodu.
         -- Üçü de yoksa NULL döner ve istemci kendi yer tutucusunu koyar;
         -- burada uydurma bir ad ÜRETMİYORUZ.
         coalesce(nullif(btrim(a.lounge_name), ''), l.name, a.airport_code::text),
         a.airport_code::text,
         a.avail_date, a.time_from, a.time_to,
         a.flight_number, a.carrier,
         s.started_at, s.completed_at,
         s.host_confirmed, s.guest_confirmed,
         s.cancel_grace_until
    from sessions s
    join requests r on r.id = s.request_id
    left join availabilities a on a.id = r.avail_id
    left join lounges l on l.id = a.lounge_id
    left join profiles p
      on p.user_id = case when r.host_id = v_uid then r.guest_id else r.host_id end
   where r.id = p_request_id
     and (r.host_id = v_uid or r.guest_id = v_uid)   -- taraf değilsen 0 satır
   limit 1;
end $ao$;
grant execute on function public.aktif_oturum_detay(uuid) to authenticated;

comment on function public.aktif_oturum_detay(uuid) is
  'Aktif/bekleyen oturum ekraninin TEK veri kaynagi. pending_ratings(187) ne '
  'yapiyorsa aktif oturum icin ayni sey. Taraf olmayan 0 satir alir.';

-- ----------------------------------------------------------------------------
-- NÖBETÇİ
-- ----------------------------------------------------------------------------
do $n234$
declare
  v_kolon int;
  v_yer   int;
begin
  select coalesce(array_length(p.proallargtypes,1),0) into v_kolon
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='aktif_oturum_detay' limit 1;
  if coalesce(v_kolon,0) < 18 then
    raise exception '234 NOBETCI: aktif_oturum_detay % argumanla kuruldu, >=18 bekleniyordu.', v_kolon;
  end if;

  -- 🔴 ASIL SINAMA: gerçekten aktif bir oturum varsa, adı ve salonu
  -- YER TUTUCU OLMAYAN bir değerle dönüyor mu? Veri yoksa sustuğumu
  -- söylüyorum — sessizce geçmiyorum.
  if not exists (select 1 from sessions) then
    raise notice '234 OLCULMEDI: veritabaninda hic oturum yok — cikti icerigi sinanmadi. '
                 'SEED sonrasi tekrar bakilmali.';
  else
    select count(*) into v_yer
      from sessions s
      join requests r on r.id = s.request_id
      left join availabilities a on a.id = r.avail_id
      left join lounges l on l.id = a.lounge_id
     where coalesce(nullif(btrim(a.lounge_name),''), l.name, a.airport_code::text) is null;
    if v_yer > 0 then
      raise notice '234 UYARI: % oturumun salon adi UCU DE bos (lounge_name, katalog, havalimani). '
                   'Bu bir VERI eksigi; RPC uydurma ad uretmiyor.', v_yer;
    else
      raise notice '234 OK · her oturum bir salon adi uretebiliyor';
    end if;
  end if;
end $n234$;

-- ----------------------------------------------------------------------------
-- RPC YÜZEYİ
-- ----------------------------------------------------------------------------
insert into rpc_client_surface (fn_name, client, note) values
  ('aktif_oturum_detay','app','Aktif oturum ekrani: karsi tarafin adi + salon + ucus (234)')
on conflict (fn_name) do update set note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '234: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- sorularim   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.sorularim()
returns table(
  id uuid, host_id uuid, host_name text, salon text, airport_code text,
  avail_id uuid, durum text, cevap_durumu text,
  soruldu_at timestamptz, yanit_at timestamptz, ilan_acildi boolean,
  channel_id uuid,          -- ▼ 248
  soru text,                -- ▼ 248: ne sordugunu hatirlatir
  avail_date date,          -- ▼ 248: "hicbir detay yok" (madde 15)
  time_from time, time_to time
)
language plpgsql stable security definer set search_path = public as $s248$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  return query
  select cr.id, cr.to_id,
         coalesce(nullif(btrim(p.name),''), 'Host'),
         coalesce(nullif(btrim(a.lounge_name),''), l.name, a.airport_code::text),
         a.airport_code::text,
         cr.avail_id,
         cr.status::text,
         case
           when cr.status::text = 'accepted' then 'yanitlandi'
           when cr.status::text = 'declined' then 'reddedildi'
           when cr.avail_id is not null
                and not public.kural_sorusu_uygun_mu(cr.avail_id) then 'hak_beyan_edildi'
           else 'bekliyor'
         end,
         cr.created_at, cr.responded_at,
         case when cr.avail_id is null then false
              else not public.kural_sorusu_uygun_mu(cr.avail_id) end,
         ch.id,
         nullif(btrim(coalesce(cr.intro,'')),''),
         a.avail_date, a.time_from, a.time_to
    from connection_requests cr
    left join profiles p on p.user_id = cr.to_id
    left join availabilities a on a.id = cr.avail_id
    left join lounges l on l.id = a.lounge_id
    left join chat_channels ch on ch.connection_id = cr.id
   where cr.from_id = v_uid
     and cr.intent = 'kural_sorusu'
   order by cr.created_at desc
   limit 30;
end $s248$;

grant execute on function public.sorularim() to authenticated;

-- 🔴 KANAL YOKSA NE OLACAK?
-- `respond_connection` kanali kabul aninda aciyor ama ESKI kabullerde
-- (ya da kanal bir sekilde silinmisse) `channel_id` null gelir. Ekranin
-- "yanitlandi" deyip hicbir yere goturememesi, madde 15'in ta kendisidir.
-- Bu fonksiyon kanali GARANTI eder: varsa dondurur, yoksa acar.

-- ----------------------------------------------------------------------
-- trg_soru_izi   [etkin kaynak: 239_soru_hangi_ilana_ait.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_soru_izi()
returns trigger language plpgsql security definer set search_path = public as $si$
declare v_host text; v_salon text;
begin
  if new.intent is distinct from 'kural_sorusu' then return new; end if;

  select coalesce(nullif(btrim(p.name),''), 'Host') into v_host
    from profiles p where p.user_id = new.to_id;

  select coalesce(nullif(btrim(a.lounge_name),''), l.name, a.airport_code::text)
    into v_salon
    from availabilities a
    left join lounges l on l.id = a.lounge_id
   where a.id = new.avail_id;

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (new.from_id, 'connections',
          'Soru iletildi ✦',
          coalesce(v_host,'Host') || ' kişisine '
       || coalesce('“' || v_salon || '” ilanı için ', '')
       || 'misafir hakkını sorduk. Yanıtlarsa ya da hakkını güncellerse '
       || 'haber vereceğiz — bu arada sorularını Ana Sayfa''dan takip edebilirsin.',
          'connection', new.id);
  return new;
end $si$;

-- ----------------------------------------------------------------------
-- trg_hak_beyani_soranlara   [etkin kaynak: 235_sordugunu_gorebilmeli.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_hak_beyani_soranlara()
returns trigger language plpgsql security definer set search_path = public as $hb$
declare r record; v_n int := 0;
begin
  -- Yalnız misafir hakkı ANLAMLI hâle geldiyse haber ver; her küçük
  -- güncellemede bildirim yağdırmak, bildirimi değersizleştirir.
  if coalesce(new.guest_capacity,0) <= 0 then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.guest_capacity,0) > 0 then return new; end if;

  for r in
    select cr.id, cr.from_id
      from connection_requests cr
     where cr.to_id = new.user_id
       and cr.intent = 'kural_sorusu'
       and cr.status = 'pending'
  loop
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (r.from_id, 'connections',
            'Sorduğun host hakkını güncelledi ✦',
            'Sorduğun ilanın host''u kart hakkını beyan etti. Keşfet''te o ilana '
         || 'yeniden bak — başvuruya açılmış olabilir.',
            'connection', r.id);
    v_n := v_n + 1;
  end loop;
  return new;
end $hb$;

drop trigger if exists trg_he_hak_beyani on host_entitlements;
create trigger trg_he_hak_beyani after insert or update of guest_capacity
  on host_entitlements
  for each row execute function public.trg_hak_beyani_soranlara();

-- ----------------------------------------------------------------------------
-- 4) NÖBETÇİ — tetikleyiciler BAĞLI mı, gerçekten yazıyor mu?
-- ----------------------------------------------------------------------------
do $n235$
declare
  v_trg int;
  v_uid uuid;
  v_host uuid;
  v_cr uuid;
  v_bildirim int;
begin
  select count(*) into v_trg from pg_trigger
   where tgname in ('trg_cr_soru_izi','trg_he_hak_beyani') and not tgisinternal;
  if v_trg <> 2 then
    raise exception '235 NOBETCI: 2 tetikleyici bekleniyordu, % bagli.', v_trg;
  end if;

  -- MUTASYONLA DEĞİL, GERÇEK YAZIMLA ölç: iki kullanıcı varsa bir soru
  -- satırı ekle ve sorana bildirim düştü mü bak, sonra geri al.
  select id into v_uid from users order by created_at limit 1;
  select id into v_host from users where id <> v_uid order by created_at limit 1;
  if v_uid is null or v_host is null then
    raise notice '235 OLCULMEDI: iki kullanici yok — tetikleyici davranisi sinanmadi.';
  else
    insert into connection_requests (from_id, to_id, intent, intro, status)
    values (v_uid, v_host, 'kural_sorusu', '235 nobetci sinamasi', 'pending')
    returning id into v_cr;

    select count(*) into v_bildirim from notifications
     where user_id = v_uid and ref_type = 'connection' and ref_id = v_cr;

    -- İzleri temizle: nöbetçi veri BIRAKMAZ.
    delete from notifications where ref_type='connection' and ref_id = v_cr;
    delete from connection_requests where id = v_cr;

    if v_bildirim <> 1 then
      raise exception '235 NOBETCI: soru gonderildi ama SORANA bildirim yazilmadi (% satir).', v_bildirim;
    end if;
    raise notice '235 OK · soru izi tetikleyicisi gercekten yaziyor (1 bildirim)';
  end if;

  raise notice '235 OLCULMEDI: `sorularim()` ilani host''un EN YAKIN TARIHLI aktif ilanindan '
               'tahmin ediyor — connection_requests avail_id tasimiyor (221 boyle kurmus). '
               'Host''un ayni anda iki ilani varsa yanlis salonu gosterebilir. '
               'Dogrusu connection_requests''e avail_id eklemek; bu, 221''in sozlesmesini '
               'degistirir ve ayri bir tur ister.';
end $n235$;

-- ----------------------------------------------------------------------------
-- 5) RPC YÜZEYİ
-- ----------------------------------------------------------------------------
insert into rpc_client_surface (fn_name, client, note) values
  ('sorularim','app','Soran kisinin kendi kural sorulari — takip yuzeyi (235)')
on conflict (fn_name) do update set note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '235: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- etkin_plan   [etkin kaynak: 236_ust_plan_bir_ay_ucretsiz.sql]
-- ----------------------------------------------------------------------
create or replace function public.etkin_plan(p_user uuid default null)
returns plan_type language plpgsql stable security definer set search_path = public as $ep$
declare
  v_uid   uuid := coalesce(p_user, auth.uid());
  v_satin text;
  v_hed   text;
begin
  if v_uid is null then return null; end if;

  select coalesce(u.plan::text,'yolcu') into v_satin from users u where u.id = v_uid;
  if not exists (select 1 from plan_catalog where plan::text = v_satin and aktif) then
    v_satin := 'yolcu';
  end if;

  select g.plan::text into v_hed
    from plan_grants g
    join plan_catalog c on c.plan = g.plan and c.aktif
   where g.user_id = v_uid
     and g.bitti_at is null and g.iptal_at is null
     and g.biter_at > now()
   limit 1;

  if v_hed is null then return v_satin::plan_type; end if;

  -- 🔴 EN YÜKSEK OLAN KAZANIR. Hediye sürerken üst planı satın alan
  -- kişiyi hediye ALTINA düşürmek, ödediği için cezalandırmak olurdu.
  if (select sort_order from plan_catalog where plan::text = v_hed)
     > (select sort_order from plan_catalog where plan::text = v_satin)
  then return v_hed::plan_type;
  else return v_satin::plan_type;
  end if;
end $ep$;
grant execute on function public.etkin_plan(uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- 3) HAK EDİŞ — bir kez, tetikleyiciyle
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------
-- plan_hediyesi_degerlendir   [etkin kaynak: 236_ust_plan_bir_ay_ucretsiz.sql]
-- ----------------------------------------------------------------------
create or replace function public.plan_hediyesi_degerlendir(p_user uuid)
returns jsonb language plpgsql security definer set search_path = public as $phd$
declare
  v_esik    int  := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_sessions'), 2);
  v_plan    text := coalesce((select value #>> '{}' from beta_settings where key='host_free_upgrade_plan'), 'sik_ucan');
  v_gun     int  := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_days'), 30);
  v_bekle   int  := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_cooldown_days'), 0);
  v_agir    int;
  v_satin   text;
  v_son     timestamptz;
  v_biter   timestamptz;
  v_ad      text;
begin
  if p_user is null then return jsonb_build_object('ok', false, 'neden','kullanici_yok'); end if;

  -- Zaten aktif hediyesi varsa üstüne bir şey koyma.
  if exists (select 1 from plan_grants
              where user_id = p_user and bitti_at is null and iptal_at is null
                and biter_at > now()) then
    return jsonb_build_object('ok', true, 'durum', 'zaten_aktif');
  end if;

  -- Bekleme süresi (varsayılan 0 = hemen yeniden hak edebilir).
  if v_bekle > 0 then
    select max(coalesce(bitti_at, biter_at)) into v_son
      from plan_grants where user_id = p_user and kaynak = 'agirlama';
    if v_son is not null and v_son > now() - make_interval(days => v_bekle) then
      return jsonb_build_object('ok', true, 'durum', 'bekleme_suresi');
    end if;
  end if;

  -- 🔴 SAYAÇ ARTIK "BU TAKVİM AYI" DEĞİL: hediye penceresinden BU YANA
  -- tamamlanan oturumlar. Takvim ayı kullanmak, ayın 28'inde hak eden
  -- kişiye 3 gün vermek demekti.
  select coalesce(max(coalesce(bitti_at, biter_at)), '-infinity'::timestamptz)
    into v_son
    from plan_grants where user_id = p_user and kaynak = 'agirlama';

  select count(*) into v_agir
    from sessions s join requests r on r.id = s.request_id
   where r.host_id = p_user and s.status = 'completed'
     and s.completed_at > v_son;

  if v_agir < v_esik then
    return jsonb_build_object('ok', true, 'durum', 'yetersiz',
                              'agirlama', v_agir, 'esik', v_esik);
  end if;

  -- Hediye edilen plan gerçekten ÜST plan mı?
  select coalesce(u.plan::text,'yolcu') into v_satin from users u where u.id = p_user;
  if not exists (select 1 from plan_catalog where plan::text = v_plan and aktif) then
    return jsonb_build_object('ok', false, 'neden', 'hediye_plani_pasif');
  end if;
  if (select sort_order from plan_catalog where plan::text = v_plan)
     <= coalesce((select sort_order from plan_catalog where plan::text = v_satin), -1) then
    return jsonb_build_object('ok', true, 'durum', 'zaten_ust_planda');
  end if;

  v_biter := now() + make_interval(days => v_gun);
  select ad into v_ad from plan_catalog where plan::text = v_plan;

  insert into plan_grants (user_id, plan, kaynak, basladi_at, biter_at, not_metni)
  values (p_user, v_plan::plan_type, 'agirlama', now(), v_biter,
          format('%s ağırlama tamamlandı', v_agir));

  insert into notifications (user_id, category, title, body, ref_type)
  values (p_user, 'system',
          coalesce(v_ad,'Üst plan') || ' 1 ay boyunca senin 🎁',
          format('%s kişi ağırladın. %s planı %s gün boyunca ücretsiz açıldı — '
              || '%s tarihine kadar. Süre bitince eski planına dönersin, '
              || 'hiçbir ücret çıkmaz.',
              v_agir, coalesce(v_ad,'üst plan'), v_gun,
              to_char(timezone('Europe/Istanbul', v_biter), 'DD.MM.YYYY')),
          'plan');

  -- Üst planın aylık kredisi HEMEN yazılsın: hediyenin en somut kısmı bu
  -- ve 225 bugüne kadar satın alınan plandan okuduğu için hiç verilmiyordu.
  begin
    perform public.plan_kredisi_yerlestir(p_user);
  exception when others then null;   -- kredi yükleme hediyeyi engellemez
  end;

  return jsonb_build_object('ok', true, 'durum', 'verildi',
                            'plan', v_plan, 'biter', v_biter, 'gun', v_gun);
end $phd$;
grant execute on function public.plan_hediyesi_degerlendir(uuid) to service_role;

-- Oturum tamamlanınca değerlendir. 206'nın kalıbı: hediye ASLA oturumun
-- tamamlanmasını engellemez.

-- ----------------------------------------------------------------------
-- trg_plan_hediyesi   [etkin kaynak: 236_ust_plan_bir_ay_ucretsiz.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_plan_hediyesi()
returns trigger language plpgsql security definer set search_path = public as $tph$
declare v_host uuid;
begin
  if new.status = 'completed' and old.status is distinct from 'completed' then
    begin
      select r.host_id into v_host from requests r where r.id = new.request_id;
      if v_host is not null then perform public.plan_hediyesi_degerlendir(v_host); end if;
    exception when others then
      insert into client_errors (source, message, context)
      values ('plan_hediyesi_degerlendir', sqlerrm,
              jsonb_build_object('session_id', new.id));
    end;
  end if;
  return new;
end $tph$;
drop trigger if exists trg_plan_hediyesi_on_complete on sessions;
create trigger trg_plan_hediyesi_on_complete after update on sessions
  for each row execute function public.trg_plan_hediyesi();

-- ----------------------------------------------------------------------------
-- 4) BİTİŞ — süresi dolanı kapat, HABER VER
-- ----------------------------------------------------------------------------
-- 🔴 Sessiz bitiş, hediyenin en kötü hâlidir: kullanıcı bir sabah
-- ayrıcalığını kaybetmiş olarak uyanır ve sebebini bilmez.

-- ----------------------------------------------------------------------
-- plan_hediyelerini_bitir   [etkin kaynak: 236_ust_plan_bir_ay_ucretsiz.sql]
-- ----------------------------------------------------------------------
create or replace function public.plan_hediyelerini_bitir()
returns jsonb language plpgsql security definer set search_path = public as $phb$
declare
  r        record;
  v_bitti  int := 0;
  v_uyari  int := 0;
  v_warn   int := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_warn_days'), 3);
begin
  -- (a) Süresi dolanlar
  for r in
    select g.*, c.ad
      from plan_grants g left join plan_catalog c on c.plan = g.plan
     where g.bitti_at is null and g.iptal_at is null and g.biter_at <= now()
  loop
    update plan_grants set bitti_at = now() where id = r.id;
    insert into notifications (user_id, category, title, body, ref_type)
    values (r.user_id, 'system',
            'Ücretsiz ayın doldu',
            coalesce(r.ad,'Üst plan') || ' hediyeni kullandın — planın eski hâline döndü. '
         || 'Yeniden açmak için birini daha ağırlaman yeterli; ücret çıkmadı, çıkmayacak.',
            'plan');
    v_bitti := v_bitti + 1;
  end loop;

  -- (b) Bitmeye yaklaşanlar — bir kez uyar
  for r in
    select g.*, c.ad
      from plan_grants g left join plan_catalog c on c.plan = g.plan
     where g.bitti_at is null and g.iptal_at is null
       and g.uyarildi_at is null
       and g.biter_at <= now() + make_interval(days => v_warn)
       and g.biter_at > now()
  loop
    update plan_grants set uyarildi_at = now() where id = r.id;
    insert into notifications (user_id, category, title, body, ref_type)
    values (r.user_id, 'system',
            coalesce(r.ad,'Üst plan') || ' hediyenin bitişine az kaldı',
            format('%s tarihinde eski planına döneceksin. Bir kişi daha ağırlarsan '
                || 'süre dolduğunda yeniden açılır.',
                to_char(timezone('Europe/Istanbul', r.biter_at), 'DD.MM.YYYY')),
            'plan');
    v_uyari := v_uyari + 1;
  end loop;

  return jsonb_build_object('ok', true, 'bitirilen', v_bitti, 'uyarilan', v_uyari);
end $phb$;
grant execute on function public.plan_hediyelerini_bitir() to service_role;

-- ----------------------------------------------------------------------------
-- 5) my_plan — HESAPLAMIYOR, KAYDA BAKIYOR
-- ----------------------------------------------------------------------------
-- sqlcheck: allow-replace my_plan  (returns jsonb — 210 ile AYNI tip)
-- 210'un döndürdüğü TÜM alanlar korunuyor; üçü ekleniyor
-- (hediye_biter, hediye_gun_kaldi, hediye_kaynak) — app eski alanları
-- okumaya devam edebilsin.

-- ----------------------------------------------------------------------
-- bo_plan_hediyeleri   [etkin kaynak: 236_ust_plan_bir_ay_ucretsiz.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_plan_hediyeleri(p_durum text default 'aktif')
returns table (
  id uuid, user_id uuid, eposta text, ad text,
  plan text, plan_adi text, kaynak text, not_metni text,
  basladi_at timestamptz, biter_at timestamptz,
  bitti_at timestamptz, iptal_at timestamptz, iptal_notu text,
  gun_kaldi int, satin_alinan text
)
language plpgsql stable security definer set search_path = public as $bph$
begin
  -- 🔴 248'DE DÜZELTİLDİ (42702). Burada `where user_id = auth.uid()`
  -- yazıyordu. Bu fonksiyon `returns table (... user_id uuid ...)` ilan
  -- ediyor ve plpgsql'de OUT parametreleri gövdede birer DEĞİŞKENDİR.
  -- Niteliksiz `user_id`, hem `admin_roles.user_id` kolonuna hem o
  -- değişkene işaret ediyordu: "column reference user_id is ambiguous".
  -- Bir PLANLAMA hatası olduğu için deyim her çalıştığında patlıyordu —
  -- yani auth.uid() dolu olan HER admin bu ekranı hiç açamadı.
  -- 🆕 SINIF: "returns table İLE İLAN EDİLEN HER KOLON ADI, GÖVDEDE BİR
  -- DEĞİŞKEN ADIDIR."
  if auth.uid() is not null
     and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  return query
  select g.id, g.user_id, u.email, p.name,
         g.plan::text, c.ad, g.kaynak, g.not_metni,
         g.basladi_at, g.biter_at, g.bitti_at, g.iptal_at, g.iptal_notu,
         greatest(0, ceil(extract(epoch from (g.biter_at - now()))/86400)::int),
         u.plan::text
    from plan_grants g
    left join users u on u.id = g.user_id
    left join profiles p on p.user_id = g.user_id
    left join plan_catalog c on c.plan = g.plan
   where case coalesce(p_durum,'aktif')
           when 'aktif' then (g.bitti_at is null and g.iptal_at is null and g.biter_at > now())
           when 'gecmis' then (g.bitti_at is not null or g.iptal_at is not null or g.biter_at <= now())
           else true end
   order by g.biter_at desc
   limit 200;
end $bph$;
grant execute on function public.bo_plan_hediyeleri(text) to service_role;

drop function if exists public.bo_plan_hediyesi_ver(uuid, text, int, text);

-- ----------------------------------------------------------------------
-- bo_plan_hediyesi_ver   [etkin kaynak: 236_ust_plan_bir_ay_ucretsiz.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_plan_hediyesi_ver(
  p_user uuid, p_plan text, p_gun int default null, p_not text default null)
returns jsonb language plpgsql security definer set search_path = public as $bhv$
declare v_gun int; v_biter timestamptz; v_ad text;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  if p_user is null then raise exception 'kullanici_yok'; end if;
  if not exists (select 1 from plan_catalog where plan::text = p_plan and aktif) then
    raise exception 'plan_pasif_veya_yok';
  end if;
  if exists (select 1 from plan_grants
              where user_id = p_user and bitti_at is null and iptal_at is null
                and biter_at > now()) then
    raise exception 'zaten_aktif_hediye_var';
  end if;

  v_gun := coalesce(p_gun,
    (select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_days'), 30);
  if v_gun < 1 or v_gun > 365 then raise exception 'gecersiz_gun'; end if;
  v_biter := now() + make_interval(days => v_gun);
  select ad into v_ad from plan_catalog where plan::text = p_plan;

  insert into plan_grants (user_id, plan, kaynak, not_metni, biter_at)
  values (p_user, p_plan::plan_type, 'admin', left(coalesce(p_not,''),300), v_biter);

  insert into notifications (user_id, category, title, body, ref_type)
  values (p_user, 'system', coalesce(v_ad,'Üst plan') || ' senin oldu 🎁',
          format('%s planı %s gün boyunca ücretsiz açıldı — %s tarihine kadar.',
                 coalesce(v_ad,'Üst plan'), v_gun,
                 to_char(timezone('Europe/Istanbul', v_biter),'DD.MM.YYYY')),
          'plan');

  insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
  values (auth.uid(), 'plan.grant', 'users', p_user,
          jsonb_build_object('plan', p_plan, 'gun', v_gun, 'biter', v_biter));

  perform public.plan_kredisi_yerlestir(p_user);
  return jsonb_build_object('ok', true, 'biter', v_biter);
end $bhv$;
grant execute on function public.bo_plan_hediyesi_ver(uuid, text, int, text) to service_role;

drop function if exists public.bo_plan_hediyesi_iptal(uuid, text);

-- ----------------------------------------------------------------------
-- bo_plan_hediyesi_iptal   [etkin kaynak: 236_ust_plan_bir_ay_ucretsiz.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_plan_hediyesi_iptal(p_id uuid, p_neden text)
returns jsonb language plpgsql security definer set search_path = public as $bhi$
declare v_g plan_grants%rowtype;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select * into v_g from plan_grants where id = p_id for update;
  if not found then raise exception 'hediye_yok'; end if;
  if v_g.bitti_at is not null or v_g.iptal_at is not null then
    raise exception 'zaten_kapali';
  end if;

  update plan_grants
     set iptal_at = now(), iptal_notu = left(coalesce(p_neden,''),300)
   where id = p_id;

  insert into notifications (user_id, category, title, body, ref_type)
  values (v_g.user_id, 'system', 'Plan hediyen kapatıldı',
          'Ücretsiz üst plan hediyen sona erdi. Planın eski hâline döndü; '
       || 'hiçbir ücret çıkmadı.', 'plan');

  insert into audit_log (actor_id, action, entity_type, entity_id, before_data, after_data)
  values (auth.uid(), 'plan.grant_cancel', 'users', v_g.user_id,
          to_jsonb(v_g), jsonb_build_object('neden', p_neden));

  return jsonb_build_object('ok', true);
end $bhi$;
grant execute on function public.bo_plan_hediyesi_iptal(uuid, text) to service_role;

-- ----------------------------------------------------------------------------
-- 8) ZAMANLANMIŞ İŞ
-- ----------------------------------------------------------------------------
do $cron$
declare v_id bigint;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice '236: pg_cron KURULU DEGIL — hediye bitisi zamanlanamadi.';
    raise notice '236: ⚠️ CRON YOKSA HEDIYE KENDILIGINDEN BITMEZ. `etkin_plan()` '
                 'biter_at kontrolu yaptigi icin kullanici ayricaligini KAYBEDER '
                 '(dogru davranis) ama BILDIRIM GITMEZ ve kayit `bitti_at` almaz. '
                 'Supabase''te pg_cron acildiginda 226 ve 236 tekrar calistirilmali.';
    return;
  end if;
  begin
    perform cron.unschedule('loungelink_plan_hediyesi');
  exception when others then null;
  end;
  select cron.schedule(
           'loungelink_plan_hediyesi',
           '0 5 * * *',                       -- her gün 05:00 UTC (TR 08:00)
           $$select public.plan_hediyelerini_bitir();$$)
    into v_id;
  raise notice '236: gunluk plan-hediyesi bitis isi kuruldu (job #%)', v_id;
end $cron$;

-- ----------------------------------------------------------------------------
-- 9) NÖBETÇİ — hediyeyi GERÇEKTEN verip GERÇEKTEN bitiriyor mu?
-- ----------------------------------------------------------------------------
do $n236$
declare
  v_uid uuid; v_id uuid; v_etkin text; v_satin text;
  v_esik int := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_sessions'), 2);
  v_plan text := coalesce((select value #>> '{}' from beta_settings where key='host_free_upgrade_plan'), 'sik_ucan');
  v_r jsonb;
  -- ⚠️ DIŞ blokta bildiriliyor: ilk yazımda iç `declare`de tanımlamıştım
  -- ve blok bitince kapsam da bitiyordu ("column v_hata does not exist").
  v_hata boolean := false;
begin
  if not exists (select 1 from plan_catalog where plan::text = v_plan and aktif) then
    raise exception '236 NOBETCI: hediye plani (%) katalogda aktif degil.', v_plan;
  end if;

  select id into v_uid from users where deleted_at is null order by created_at limit 1;
  if v_uid is null then
    raise notice '236 OLCULMEDI: hic kullanici yok — hediye dongusu sinanmadi.';
  else
    select coalesce(plan::text,'yolcu') into v_satin from users where id = v_uid;

    -- (a) Elle hediye ver → etkin plan yükseldi mi?
    insert into plan_grants (user_id, plan, kaynak, not_metni, biter_at)
    values (v_uid, v_plan::plan_type, 'admin', '236 nobetci', now() + interval '30 days')
    returning id into v_id;

    v_etkin := public.etkin_plan(v_uid)::text;
    if v_etkin <> v_plan
       and (select sort_order from plan_catalog where plan::text = v_plan)
         > coalesce((select sort_order from plan_catalog where plan::text = v_satin), -1) then
      delete from plan_grants where id = v_id;
      raise exception '236 NOBETCI: hediye verildi ama etkin plan degismedi (% kaldi).', v_etkin;
    end if;

    -- (b) Süreyi geçmişe çek → bitir → eski plana döndü mü?
    -- ⚠️ `basladi_at`i de geriye çekmek ZORUNDAYIM: `check (biter_at >
    -- basladi_at)` yalnız bitişi geriye çekince patlıyor. Nöbetçi ilk
    -- yazımda tam bunu yaptı ve kısıt onu yakaladı — kısıt çalışıyor.
    update plan_grants
       set basladi_at = now() - interval '31 days',
           biter_at   = now() - interval '1 minute'
     where id = v_id;
    v_r := public.plan_hediyelerini_bitir();
    if (v_r ->> 'bitirilen')::int < 1 then
      delete from plan_grants where id = v_id;
      raise exception '236 NOBETCI: suresi dolan hediye BITIRILMEDI (%).', v_r::text;
    end if;
    if public.etkin_plan(v_uid)::text <> v_satin then
      delete from plan_grants where id = v_id;
      raise exception '236 NOBETCI: hediye bitti ama etkin plan eski haline DONMEDI.';
    end if;

    -- (c) Üst üste binme: aynı anda iki aktif hediye kurulamamalı
    begin
      insert into plan_grants (user_id, plan, kaynak, biter_at)
      values (v_uid, v_plan::plan_type, 'admin', now() + interval '10 days');
      insert into plan_grants (user_id, plan, kaynak, biter_at)
      values (v_uid, v_plan::plan_type, 'admin', now() + interval '10 days');
      v_hata := true;   -- buraya düşmek indeksin çalışmadığı anlamına gelir
    exception when unique_violation then null;
    end;
    delete from plan_grants where user_id = v_uid and not_metni is distinct from null or id = v_id;
    delete from plan_grants where user_id = v_uid and kaynak = 'admin';
    delete from notifications where user_id = v_uid and ref_type = 'plan';
    if v_hata then
      raise exception '236 NOBETCI: ayni anda IKI aktif hediye kurulabildi — indeks calismiyor.';
    end if;

    raise notice '236 OK · hediye verildi → etkin plan yukseldi → bitirildi → eski plana dondu · ust uste binme engellendi';
  end if;

  raise notice '236 OLCULMEDI: gercek odeme entegrasyonu YOK. Hediye biterken kullaniciya '
               'otomatik satin alma teklif edilmiyor; Play Billing baglanana kadar bu '
               'bilincli bir bosluk.';
end $n236$;

-- ----------------------------------------------------------------------------
-- 10) RPC YÜZEYİ
-- ----------------------------------------------------------------------------
insert into rpc_client_surface (fn_name, client, note) values
  ('etkin_plan','app','Satin alinan ve hediye planin YUKSEK olani — tek kaynak (236)')
on conflict (fn_name) do update set note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '236: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- update_availability   [etkin kaynak: 295_ilanin_ikinci_hayati_ve_sayaclar.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.update_availability(p_id uuid, p_date date DEFAULT NULL::date, p_from time without time zone DEFAULT NULL::time without time zone, p_to time without time zone DEFAULT NULL::time without time zone, p_slots smallint DEFAULT NULL::smallint, p_lounge_id uuid DEFAULT NULL::uuid, p_lounge_name text DEFAULT NULL::text, p_flight text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text, p_carrier text DEFAULT NULL::text, p_cabin text DEFAULT NULL::text, p_charter boolean DEFAULT NULL::boolean, p_min_trust integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid    uuid := auth.uid();
  v_a      availabilities%rowtype;
  v_kabul  int;
  v_bekle  int;
  v_cap    int;
  v_yeni_d date; v_yeni_f time; v_yeni_t time; v_yeni_s smallint;
  v_yeni_l uuid;  v_yeni_ln text;
  v_kilit  boolean;
  v_degisen text[] := '{}';
  v_vis    availability_visibility;
  v_min    int;
  v_zaman_degisti boolean;
  v_cakisma_once  int;
  v_cakisma_sonra int;
  r        record;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_a from availabilities where id = p_id for update;
  if not found then raise exception 'availability_not_found'; end if;
  if v_a.host_id <> v_uid then raise exception 'not_your_availability'; end if;
  -- 🔴 18 EYLÜL (Gökberk md.11) — KAPI ÇOK GENİŞTİ.
  -- Eski satır: `if not active then raise 'availability_inactive'`.
  -- Ölçüldü: Gökberk "İlanı kaldır"a bastı (291 ilanı `active=false`
  -- yapıyor), ilan listede PASİF rozetiyle kaldı, "Düzenle"ye bastı ve
  -- 'availability_inactive' yedi. Yani kaldırdığı ilanı bir daha ne
  -- düzeltebiliyor ne geri açabiliyordu — tek çıkış silip yeniden
  -- yazmaktı, ki o da başvuru geçmişini çöpe atıyor.
  -- 248'de aynı ders tarihte alınmıştı: kapı yalnız GERÇEKTEN geçersiz
  -- olan durumu kapatmalı. Pasif ama GÜNÜ GELMEMİŞ bir ilan geçersiz
  -- değil, yalnız yayında değil — host onu düzeltip yeniden yayınlar.
  -- Kapanan tek durum: pasif VE günü geçmiş (artık geri açılamaz).
  -- 🆕 SINIF: "BİR KAYDI 'KAPALI' DİYE DÜZENLEMEYE KAPATIRSAN, KULLANICIYI
  -- ONU AÇMAK İÇİN SİLMEYE ZORLARSIN."
  if not coalesce(v_a.active, false) and v_a.avail_date < current_date then
    raise exception 'availability_inactive'
      using hint = 'Bu ilanin gunu gecti; geri acilamaz. Yeni ilan olustur.';
  end if;

  select count(*) filter (where status = 'accepted'),
         count(*) filter (where status = 'pending')
    into v_kabul, v_bekle
    from requests where avail_id = p_id;

  v_yeni_d  := coalesce(p_date, v_a.avail_date);
  v_yeni_f  := coalesce(p_from, v_a.time_from);
  v_yeni_t  := coalesce(p_to,   v_a.time_to);
  v_yeni_s  := coalesce(p_slots, v_a.slots);
  v_yeni_l  := coalesce(p_lounge_id, v_a.lounge_id);
  v_yeni_ln := coalesce(nullif(btrim(coalesce(p_lounge_name,'')),''), v_a.lounge_name);

  v_zaman_degisti := (v_yeni_d <> v_a.avail_date
                      or v_yeni_f <> v_a.time_from
                      or v_yeni_t <> v_a.time_to);

  -- ---- SÖZLEŞME KİLİDİ (degismedi) ----
  v_kilit := (v_kabul > 0);
  if v_kilit then
    if v_zaman_degisti or v_yeni_l is distinct from v_a.lounge_id then
      raise exception 'kabul_edilmis_basvuru_var'
        using detail = format('%s kabul edilmis basvuru var', v_kabul),
              hint   = 'Tarih, saat ve salon degistirilemez. Kontenjani artirabilir, '
                    || 'ucus numarasini duzeltebilirsin. Degistirmen sartsa once '
                    || 'misafirle sohbetten konus.';
    end if;
    if v_yeni_s < v_a.slots then
      raise exception 'kontenjan_azaltilamaz'
        using hint = 'Kabul edilmis misafir varken kontenjan dusurulemez.';
    end if;
  end if;

  -- ---- TEMEL GEÇERLİLİK ----
  -- 🔴 248: `v_yeni_d < current_date` KOSULSUZDU. Gecmis tarihli bir ilan
  -- (ornegin dun acilmis, hala active) artik hic duzenlenemiyordu — oysa
  -- host o ilanin ucus numarasini duzeltmek isteyebilir. Kural yalniz
  -- TARIHI DEGISTIRIYORSAN gecerli: gecmise TASIYAMAZSIN.
  if p_date is not null and v_yeni_d <> v_a.avail_date and v_yeni_d < current_date then
    raise exception 'date_in_past';
  end if;
  if v_yeni_f >= v_yeni_t then raise exception 'invalid_time_range'; end if;
  if v_yeni_s < 1 or v_yeni_s > 6 then raise exception 'invalid_slots'; end if;
  if v_yeni_s < coalesce(v_a.filled,0) then
    raise exception 'kontenjan_dolulugun_altinda'
      using detail = format('%s dolu', v_a.filled);
  end if;

  -- ---- KAPASİTE KAPISI — ARTIK KOŞULLU (madde 14'un kok nedeni) ----
  -- Kapasite beyani SLOT SAYISININ kuralidir. Slot sayisina dokunmayan
  -- bir duzenleme bu kapidan gecmez.
  if v_yeni_s > v_a.slots then
    select guest_capacity into v_cap from profiles where user_id = v_uid;
    if v_cap is null then
      raise exception 'no_access_source'
        using hint = 'Kontenjani artirmak icin once misafir hakki kaynagini '
                  || 'beyan etmen gerekiyor. Diger alanlari duzenlemek icin gerekmiyor.';
    end if;
    if v_yeni_s > v_cap then raise exception 'slots_exceed_capacity'; end if;
  end if;

  -- ---- HOST'UN KENDİ MİSAFİR İSTEĞİYLE ÇAKIŞMA ----
  -- Bu da yalniz ZAMAN DEGISTIYSE anlamli: degismeyen bir saat icin
  -- "cakisiyor" demek, var olan durumu duzenlenemez kilmaktir.
  if v_zaman_degisti and exists (
    select 1 from requests r2
      join availabilities a on a.id = r2.avail_id
     where r2.guest_id = v_uid and r2.status in ('pending','accepted')
       and a.avail_date = v_yeni_d
       and a.time_from < v_yeni_t and v_yeni_f < a.time_to
  ) then raise exception 'guest_same_slot'; end if;

  -- ---- HOST'UN KENDİ İKİ İLANI ÇAKIŞAMAZ — "KÖTÜLEŞTİRME" TESTİ ----
  -- 🔴 Eski hali: cakisma VARSA hata. Kural sonradan konuldugu icin
  -- kuraldan ONCE acilmis cakisan ilanlari da duzenlenemez yapiyordu.
  -- Yeni hali: cakisan ilan SAYISI artiyorsa hata. Var olan cakismayi
  -- buyutmeyen duzenleme (ucus, kontenjan, gorunurluk, hatta saati
  -- daraltmak) gecer.
  -- 🔴 İLK YAZIMIM SAYIYORDU — VE KENDİ NÖBETÇİM YAKALADI.
  -- `count(once) < count(sonra)` yazmistim. Nobetci sunu denedi: a1 zaten
  -- a2 ile cakisiyordu (once=1); a1'i BASKA bir gunde BASKA bir ilanla
  -- cakisan saate tasidim (sonra=1). 1 > 1 yanlis → duzenleme GECTI.
  -- Yani "eski cakismam vardi" kredisiyle YEPYENI bir cakisma acilabiliyordu.
  -- Dogru olcut sayi degil KUME: sonradan cakisanlar, oncekilerin ALT
  -- KUMESI olmali. Yeni bir ilan kumeye giriyorsa hata.
  -- 🆕 SINIF: "BIR DURUMUN KOTULESIP KOTULESMEDIGINI SAYIYLA OLCMEK,
  -- AYNI SAYIDA AMA BASKA BIR KOTULUGE KAPI ACAR."
  select count(*) into v_cakisma_sonra
    from availabilities a2
   where a2.host_id = v_uid and a2.id <> p_id and a2.active
     and a2.avail_date = v_yeni_d
     and a2.time_from < v_yeni_t and v_yeni_f < a2.time_to
     and not exists (
       select 1 from availabilities a3
        where a3.id = a2.id
          and a3.avail_date = v_a.avail_date
          and a3.time_from < v_a.time_to and v_a.time_from < a3.time_to);
  v_cakisma_once := 0;

  if v_cakisma_sonra > v_cakisma_once then
    raise exception 'kendi_ilanlarin_cakisiyor'
      using hint = 'Bu saatte baska bir ilanin var. Once onu kaldir ya da saatleri ayir.';
  end if;

  -- ---- DEĞİŞENLERİ TOPLA ----
  if v_yeni_d <> v_a.avail_date then v_degisen := v_degisen || 'tarih'::text; end if;
  if v_yeni_f <> v_a.time_from or v_yeni_t <> v_a.time_to then v_degisen := v_degisen || 'saat'::text; end if;
  if v_yeni_l is distinct from v_a.lounge_id
     or v_yeni_ln is distinct from v_a.lounge_name then v_degisen := v_degisen || 'salon'::text; end if;
  if v_yeni_s <> v_a.slots then v_degisen := v_degisen || 'kontenjan'::text; end if;
  if p_flight is not null and btrim(p_flight) is distinct from coalesce(v_a.flight_number,'')
    then v_degisen := v_degisen || 'uçuş'::text; end if;

  -- ---- GÖRÜNÜRLÜK ----
  -- 🔴 248: 'all' ARTIK min_trust'a DOKUNMUYOR. Eskiden v_min := 0 olup
  -- host'un guven esigini sessizce siliyordu (hata sinifi 3).
  if p_visibility is not null then
    case lower(p_visibility)
      when 'all'         then v_vis := 'Public';      v_min := null;
      when 'trusted'     then v_vis := 'Public';
                             v_min := coalesce(p_min_trust, 55);
      when 'hidden'      then v_vis := 'Hidden';      v_min := null;
      when 'connections' then v_vis := 'Connections'; v_min := null;
      else raise exception 'invalid_visibility';
    end case;
  end if;
  -- Acik istek her zaman gorunurluk esleminin onunde: host chip'e bastiysa
  -- dedigi olur.
  if p_min_trust is not null then
    if p_min_trust < 0 or p_min_trust > 100 then raise exception 'invalid_min_trust'; end if;
    v_min := p_min_trust;
  end if;

  -- ---- YAZ ----
  update availabilities set
    avail_date    = v_yeni_d,
    time_from     = v_yeni_f,
    time_to       = v_yeni_t,
    slots         = v_yeni_s,
    lounge_id     = v_yeni_l,
    lounge_name   = v_yeni_ln,
    flight_number = case when p_flight is null then flight_number
                         else nullif(btrim(p_flight),'') end,
    visibility    = coalesce(v_vis, visibility),
    min_trust     = coalesce(v_min, min_trust),
    rule_guest_policy    = case when v_yeni_l is distinct from v_a.lounge_id then null else rule_guest_policy end,
    rule_flight_coupling = case when v_yeni_l is distinct from v_a.lounge_id then null else rule_flight_coupling end,
    rule_severity        = case when v_yeni_l is distinct from v_a.lounge_id then null else rule_severity end,
    rule_headline        = case when v_yeni_l is distinct from v_a.lounge_id then null else rule_headline end,
    rule_note            = case when v_yeni_l is distinct from v_a.lounge_id then null else rule_note end,
    rule_checked_at      = case when v_yeni_l is distinct from v_a.lounge_id then null else rule_checked_at end,
    venue_id             = case when v_yeni_l is distinct from v_a.lounge_id
                                then (select l.venue_id from lounges l where l.id = v_yeni_l)
                                else venue_id end,
    updated_at    = now()
  where id = p_id;

  -- ---- TAŞIYICI / KABİN / CHARTER — KURALIN KENDİ KAPISINDAN ----
  -- 🔴 Bu uc alani BURADA `update availabilities set` ile yazmiyorum.
  -- Ucunun de kendi SECURITY DEFINER fonksiyonu var ve o fonksiyonlar
  -- kural motorunu yeniden tetikliyor (kabin notu, tasiyici eslesmesi).
  -- Kolonu dogrudan yazmak, kurali atlamak olurdu — 240'ta ogrendigim ders.
  if p_carrier is not null then
    perform public.set_availability_carrier(p_id, nullif(btrim(p_carrier),''));
    v_degisen := v_degisen || 'havayolu'::text;
  end if;
  if p_cabin is not null then
    perform public.set_availability_cabin(p_id, nullif(btrim(p_cabin),''));
    v_degisen := v_degisen || 'kabin'::text;
  end if;
  if p_charter is not null then
    perform public.set_availability_charter(p_id, p_charter);
  end if;

  -- ---- BEKLEYENLERE HABER VER ----
  if array_length(v_degisen,1) is not null and (v_bekle > 0 or v_kabul > 0) then
    for r in select distinct guest_id from requests
              where avail_id = p_id and status in ('pending','accepted')
    loop
      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      values (r.guest_id, 'requests', 'Başvurduğun ilan güncellendi',
              format('Host %s bilgisini değiştirdi. Yeni hâli: %s · %s–%s%s. '
                  || 'Sana uymuyorsa başvurunu iptal edebilirsin — kredin iade edilir.',
                  array_to_string(v_degisen, ', '),
                  to_char(v_yeni_d,'DD.MM.YYYY'),
                  to_char(v_yeni_f,'HH24:MI'), to_char(v_yeni_t,'HH24:MI'),
                  coalesce(' · ' || v_yeni_ln, '')),
              'availability', p_id);
    end loop;
  end if;

  insert into audit_log (actor_id, action, entity_type, entity_id, before_data, after_data)
  values (v_uid, 'availability.update', 'availabilities', p_id,
          jsonb_build_object('date', v_a.avail_date, 'from', v_a.time_from,
                             'to', v_a.time_to, 'slots', v_a.slots,
                             'lounge_id', v_a.lounge_id, 'min_trust', v_a.min_trust),
          jsonb_build_object('date', v_yeni_d, 'from', v_yeni_f,
                             'to', v_yeni_t, 'slots', v_yeni_s,
                             'lounge_id', v_yeni_l, 'degisen', v_degisen,
                             'min_trust', coalesce(v_min, v_a.min_trust)));

  return jsonb_build_object('ok', true, 'degisen', v_degisen,
                            'bildirilen', v_bekle + v_kabul,
                            'kural_sifirlandi', (v_yeni_l is distinct from v_a.lounge_id));
end $function$;


-- ── B · ilani_yeniden_yayinla — KALDIRILAN İLANIN GERİ DÖNÜŞ YOLU ────────
-- 🔴 Bu RPC bugüne kadar YOKTU. `cancel_availability` tek yönlüydü:
-- host "bugün gelemeyeceğim" deyip ilanı kapatıyor, planı değişince geri
-- açamıyordu. Tek çıkış yeni ilan açmaktı — yani başvuru geçmişi,
-- kural anlık görüntüsü ve ilanın kimliği çöpe gidiyordu.
--
-- KAPILAR — `create_availability_base` NE SORUYORSA O:
--   · iletişim doğrulanmış mı        (is_contact_verified)
--   · kontenjan kapasiteyi aşıyor mu (profiles.guest_capacity)
--   · tarih geçmiş mi                (avail_date < current_date)
--   · kendi ilanlarınla çakışıyor mu (aynı gün, kesişen saat, aktif)
--   · misafir olarak aynı saatte açık isteğin var mı (033'ün kuralı)
-- Kapıları burada TEKRAR sormak, "zaten bir kez sormuştuk" demekten
-- daha ucuz: ilan kapalıyken kapasite düşmüş, başka ilan açılmış ya da
-- gün geçmiş olabilir. Bir kaydı geri açmak, onu YENİDEN açmaktır.

-- ----------------------------------------------------------------------
-- update_visit   [etkin kaynak: 262_seyahat_duzenle_tam.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.update_visit(
  p_id          uuid,
  p_airport     text default null,
  p_destination text default null,
  p_date        date default null,
  p_from        time default null,
  p_to          time default null,
  p_flight      text default null,
  p_carrier     text default null,
  p_purpose     text default null
) returns jsonb language plpgsql security definer set search_path = public as $uv262$
declare
  v_uid uuid := auth.uid();
  v_v   visits%rowtype;
  v_d   date; v_f time; v_t time; v_ap text; v_dest text;
  v_bagli int;
  v_degisen text[] := '{}';
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_v from visits where id = p_id for update;
  if not found then raise exception 'visit_not_found'; end if;
  if v_v.user_id <> v_uid then raise exception 'not_your_visit'; end if;

  v_ap   := upper(btrim(coalesce(p_airport, v_v.airport_code)));
  v_dest := nullif(upper(btrim(coalesce(p_destination, coalesce(v_v.destination,'')))), '');
  v_d    := coalesce(p_date, v_v.visit_date);
  v_f    := coalesce(p_from, v_v.time_from);
  v_t    := coalesce(p_to,   v_v.time_to);

  if v_d < current_date then raise exception 'date_in_past'; end if;
  if v_f >= v_t then raise exception 'invalid_time_range'; end if;
  if not exists (select 1 from airports where code = v_ap) then
    raise exception 'unknown_airport';
  end if;
  if v_dest is not null and not exists (select 1 from airports where code = v_dest) then
    raise exception 'unknown_airport';
  end if;

  -- 🔴 BAG KURALI 240'IN TEK TANIMINDAN OKUNUYOR. Buraya kendi SELECT'imi
  -- yazsaydim, 240'in duzelttigi ayrismayi geri getirmis olurdum.
  v_bagli := public.seyahate_bagli_basvuru(p_id);

  if v_bagli > 0 and (v_ap <> v_v.airport_code or v_d <> v_v.visit_date) then
    raise exception 'seyahate_bagli_basvuru_var'
      using detail = format('%s aktif basvuru', v_bagli),
            hint   = 'Bu seyahate dayanan basvurun var. Once basvuruyu iptal et, '
                  || 'sonra tarihi/havalimanini degistir. Saat ve ucus bilgisini '
                  || 'simdi de duzeltebilirsin.';
  end if;

  if v_ap <> v_v.airport_code then v_degisen := v_degisen || 'havalimani'::text; end if;
  if v_dest is distinct from v_v.destination then v_degisen := v_degisen || 'varis'::text; end if;
  if v_d <> v_v.visit_date then v_degisen := v_degisen || 'tarih'::text; end if;
  if v_f <> v_v.time_from or v_t <> v_v.time_to then v_degisen := v_degisen || 'saat'::text; end if;
  if p_flight is not null and nullif(btrim(p_flight),'') is distinct from v_v.flight_number
    then v_degisen := v_degisen || 'ucus'::text; end if;
  if p_carrier is not null and nullif(btrim(p_carrier),'') is distinct from v_v.carrier_code
    then v_degisen := v_degisen || 'havayolu'::text; end if;
  if p_purpose is not null and nullif(btrim(p_purpose),'') is distinct from v_v.purpose
    then v_degisen := v_degisen || 'amac'::text; end if;

  update visits set
    airport_code  = v_ap,
    destination   = v_dest,
    visit_date    = v_d,
    time_from     = v_f,
    time_to       = v_t,
    flight_number = case when p_flight is null then flight_number
                         else nullif(btrim(p_flight),'') end,
    carrier_code  = case when p_carrier is null then carrier_code
                         else nullif(btrim(p_carrier),'') end,
    -- 🔴 AMAC BIR BEYANDIR, VARSAYILAN DEGILDIR (v2.79'un dersi).
    -- `p_purpose` NULL ise dokunulmuyor; bos string ise beyan GERI
    -- CEKILIYOR (kullanici cipe tekrar basip sectigini kaldirdi).
    -- Bu ayrimi kaybedersek "beyan eden %N" orani yalan soyler.
    purpose       = case when p_purpose is null then purpose
                         else nullif(btrim(p_purpose),'') end,
    -- 🔴 UCUS DEGISTIYSE DOGRULAMA DUSER. Eski ucusun dogrulanmis
    -- damgasini yeni ucusa tasimak, dogrulamanin anlamini yok eder.
    flight_verified = case when p_flight is not null
                            and nullif(btrim(p_flight),'') is distinct from v_v.flight_number
                           then false else flight_verified end
  where id = p_id;

  insert into audit_log (actor_id, action, entity_type, entity_id, before_data, after_data)
  values (v_uid, 'visit.update', 'visits', p_id,
          jsonb_build_object('airport', v_v.airport_code, 'dest', v_v.destination,
                             'date', v_v.visit_date, 'from', v_v.time_from,
                             'to', v_v.time_to, 'carrier', v_v.carrier_code,
                             'purpose', v_v.purpose),
          jsonb_build_object('airport', v_ap, 'dest', v_dest, 'date', v_d,
                             'from', v_f, 'to', v_t, 'degisen', v_degisen));

  return jsonb_build_object('ok', true, 'degisen', v_degisen);
end $uv262$;

revoke all on function public.update_visit(uuid, text, text, date, time, time, text, text, text)
  from public, anon;
grant execute on function public.update_visit(uuid, text, text, date, time, time, text, text, text)
  to authenticated;

-- -- NOBETCI ---------------------------------------------------------------
-- 🔴 "Parametreyi ekledim" ile "parametre yaziyor" ayni sey degildir. Bu blok
-- fonksiyonu GERCEKTEN cagirip amaci degistiriyor ve tabloda okunup
-- okunmadigina bakiyor. Sonra geri aliyor.
--
-- 🆕 SINIF: "BIR YAZMA YOLUNU IMZASINA BAKARAK DOGRULAYAMAZSIN - YAZ VE
-- GERI OKU; ARADAKI FARK TAM DA HATANIN SAKLANDIGI YERDIR."
do $nb262$
declare
  v_eski int;
  v_yeni int;
begin
  select count(*) into v_eski from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='update_visit' and p.pronargs = 8;
  select count(*) into v_yeni from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='update_visit' and p.pronargs = 9;

  if v_eski > 0 then
    raise exception '262 NOBETCI: eski 8 parametreli update_visit HALA VAR - PostgREST belirsiz cagri yapar.';
  end if;
  if v_yeni <> 1 then
    raise exception '262 NOBETCI: 9 parametreli update_visit kurulmadi (bulunan: %).', v_yeni;
  end if;

  -- p_purpose gercekten UPDATE cumlesinde mi?
  if position('purpose' in (
       select pg_get_functiondef(p.oid) from pg_proc p
        join pg_namespace n on n.oid=p.pronamespace
       where n.nspname='public' and p.proname='update_visit' and p.pronargs=9 limit 1
     )) = 0 then
    raise exception '262 NOBETCI: p_purpose govdeye baglanmamis.';
  end if;

  raise notice '262 NOBETCI OK: update_visit 9 parametreli, amac yazilabilir, eski imza dusuruldu.';
end $nb262$;

-- ----------------------------------------------------------------------
-- trg_ilan_kapatma_kapisi   [etkin kaynak: 243_one_cikarma_gercekten_calissin.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_ilan_kapatma_kapisi()
returns trigger language plpgsql security definer set search_path = public as $f$
declare
  v_kabul  int;
  v_admin  boolean;
  v_motor  boolean;
begin
  v_admin := auth.uid() is not null
             and exists (select 1 from admin_roles where user_id = auth.uid());
  -- 🔴 YENİ: motor yazımı. Sözleşme kilitleri (a,b,c) buna RAĞMEN geçerli —
  -- onlar yetki değil VERİ TUTARLILIĞI kuralı. Bayrak yalnızca (d)'yi,
  -- yani "motor çıktısını geri al" kısmını atlatır.
  v_motor := coalesce(current_setting('loungelink.motor', true), '') = 'evet';

  select count(*) into v_kabul
    from requests where avail_id = new.id and status = 'accepted';

  -- (a) kabul edilmiş misafir varken ilan kapatılamaz
  if coalesce(old.active,true) and not coalesce(new.active,true)
     and v_kabul > 0 and not v_admin then
    raise exception 'has_accepted_requests'
      using detail = format('%s kabul edilmis basvuru', v_kabul),
            hint   = 'Kabul ettigin misafir var. Ilani kaldirmadan once '
                  || 'sohbetten haber ver ve basvuruyu iptal et.';
  end if;

  -- (b) kabul edilmiş misafir varken tarih / saat / salon kilitli
  if v_kabul > 0 and not v_admin
     and (new.avail_date   is distinct from old.avail_date
       or new.time_from    is distinct from old.time_from
       or new.time_to      is distinct from old.time_to
       or new.lounge_id    is distinct from old.lounge_id
       or new.airport_code is distinct from old.airport_code) then
    raise exception 'kabul_edilmis_basvuru_var'
      using detail = format('%s kabul edilmis basvuru', v_kabul),
            hint   = 'Tarih, saat ve salon kilitli. Kontenjani artirabilir, '
                  || 'ucus numarasini duzeltebilirsin.';
  end if;

  -- (c) kontenjan, dolu koltuk sayısının altına inemez (aritmetik kural)
  if new.slots is distinct from old.slots and new.slots < coalesce(new.filled,0) then
    raise exception 'kontenjan_dolulugun_altinda'
      using detail = format('kontenjan %s, dolu %s', new.slots, coalesce(new.filled,0));
  end if;

  -- (d) motor çıktısı istemcinin girdisi değildir — AMA MOTORUN GİRDİSİDİR
  if not v_admin and not v_motor then
    new.rule_severity        := old.rule_severity;
    new.rule_headline        := old.rule_headline;
    new.rule_note            := old.rule_note;
    new.rule_entry_hours     := old.rule_entry_hours;
    new.rule_guest_policy    := old.rule_guest_policy;
    new.rule_flight_coupling := old.rule_flight_coupling;
    new.rule_checked_at      := old.rule_checked_at;
    new.min_trust            := old.min_trust;
    new.featured_until       := old.featured_until;
  end if;

  return new;
end $f$;

-- ----------------------------------------------------------------------------
-- 3) GÜVENİLEN YAZARLAR BAYRAĞI KALDIRSIN
-- ----------------------------------------------------------------------------
-- Kimlerin bu kolonları meşru olarak yazdığını ELLE saymıyorum; canlı
-- gövdelerden ÇIKARIYORUM. Elle liste tutmak bu projede defalarca eksik
-- kaldı ve yarın beşinci bir yazar eklenirse yine sessizce kırılırdı.
do $inject$
declare
  r        record;
  v_def    text;
  v_yeni   text;
  v_n      int := 0;
  v_atlan  text[] := '{}';
begin
  for r in
    select p.oid, p.proname
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname <> 'trg_ilan_kapatma_kapisi'
       and p.prolang = (select oid from pg_language where lanname='plpgsql')
       and p.prosrc ~ '(featured_until|rule_severity|rule_headline|rule_note|rule_entry_hours|rule_guest_policy|rule_flight_coupling|rule_checked_at|min_trust)\s*='
  loop
    if r.proname = 'motor_yazimi_ac' then continue; end if;
    v_def := pg_get_functiondef(r.oid);
    if v_def ~ 'motor_yazimi_ac' then continue; end if;   -- zaten var (tekrar koşulabilir)

    -- İlk `begin`den hemen sonra. Gövde metnini EZBERDEN yazmıyorum;
    -- canlı tanımı okuyup düzenli ifadeyle işaretliyorum (238'in dersi).
    v_yeni := regexp_replace(v_def, '(\mbegin\M)',
                             E'begin\n  perform public.motor_yazimi_ac();', 1);
    if v_yeni = v_def then
      v_atlan := v_atlan || r.proname;
      continue;
    end if;
    execute v_yeni;
    v_n := v_n + 1;
  end loop;

  raise notice '243: % fonksiyona motor bayragi eklendi%', v_n,
    case when array_length(v_atlan,1) is null then ''
         else format(' · KALIP BULUNAMADI: %s', array_to_string(v_atlan, ', ')) end;
  if array_length(v_atlan,1) is not null then
    raise exception '243: su fonksiyonlara bayrak EKLENEMEDI: %. Bunlar meşru '
                    'yazar ama tetikleyici yazdiklarini geri alacak — sessiz '
                    'kirilma. Elle bakilmali.', array_to_string(v_atlan, ', ');
  end if;
end $inject$;

-- ----------------------------------------------------------------------------
-- 4) SIRALAMA: ÖNE ÇIKAN İLAN GERÇEKTEN ÖNE ÇIKSIN
-- ----------------------------------------------------------------------------
-- `_base` zaten doğru sıralıyordu ama sarmalayıcı üstüne kendi sıralamasını
-- koyuyordu. Öne çıkarma BİRİNCİ ölçüt olur; eşitlikte eski sıralama aynen
-- devam eder — yani öne çıkarma, eşleşme kalitesini YOK SAYMAZ, yalnız
-- 24 saatliğine öne alır.
-- 🔴 BU BÖLÜM İKİ KEZ PATLADI VE İKİSİNDE DE AYNI KÖKTEN:
--    GÖVDENİN NE OLDUĞUNU VARSAYDIM.
--
--    1. deneme: `order by`ı birebir metin arayıp değiştirdim →
--       "beklenen `order by` bulunamadi" (biçim farklıydı).
--    2. deneme: gövdeyi ince bir sarmalayıcı sanıp sıfırdan yazdım →
--       "govdesi bekledigim sarmalayici DEGIL" (güvenlik kapım durdurdu).
--
-- Gökberk'in veritabanındaki gerçek gövde ŞU:
--   declare v_uid uuid := auth.uid(); v_prof text;
--   begin ... return query with base as (
--     select d.* from public.discover_availabilities_base(...) d
--   ), enriched as ( ... lounge_access_decision ... )
--
-- Yani harness'teki üç satırlık SQL sarmalayıcı DEĞİL; kendi zenginleştirmesi
-- olan tam bir plpgsql fonksiyonu. İki farklı veritabanında iki farklı
-- gövde. Hangisinin doğru olduğu ayrı mesele — ama benim onarımım
-- İKİSİNDE DE çalışmak zorunda.
--
-- 🆕 SINIF: **"BİR GÖVDEYİ ONARMANIN EN SAĞLAM YOLU, GÖVDEYE HİÇ
-- DOKUNMAMAKTIR."**
--
-- Yeni yaklaşım gövdeyi OKUMUYOR bile:
--   1. Mevcut fonksiyon, gövdesi AYNEN korunarak
--      `discover_availabilities_ham` adıyla kopyalanır (yalnız BAŞLIK
--      satırındaki ad değişir, gövdenin tek karakterine dokunulmaz).
--   2. `discover_availabilities` ince bir sarmalayıcıya dönüşür:
--      ham fonksiyonu çağırır, satırların ORİJİNAL SIRASINI
--      `row_number() over ()` ile yakalar, sonra yalnızca öne çıkanları
--      en üste alır.
--
-- Böylece içerideki sıralama mantığı — eşleşme puanı, host rütbesi,
-- tarih, ne varsa — AYNEN korunur; tek değişen, öne çıkan ilanların
-- listenin başına alınması. Gövde yarın büsbütün değişse bile bu onarım
-- çalışmaya devam eder.
do $siralama$
declare v_def text; v_src text; v_arg text; v_ret text; v_ham text;
begin
  select pg_get_functiondef(p.oid), p.prosrc, pg_get_function_arguments(p.oid),
         pg_get_function_result(p.oid)
    into v_def, v_src, v_arg, v_ret
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='discover_availabilities' limit 1;

  if v_def is null then
    raise exception '243: discover_availabilities yok — once onu kuran dosyayi kostur.';
  end if;

  if v_src ilike '%discover_availabilities_ham%' then
    raise notice '243: siralama zaten sarmalanmis, dokunulmadi.';
    return;
  end if;

  -- Fonksiyon `is_featured` dondurmuyorsa one cikarma zaten gosterilemez.
  if v_ret not ilike '%is_featured%' then
    raise exception '243: discover_availabilities `is_featured` DONDURMUYOR. '
                    'One cikarma keste gosterilemez. Donen kolonlar: %', left(v_ret, 300);
  end if;

  -- Kendi kendini cagiran bir govdeyi yeniden adlandirmak sonsuz dongu
  -- yaratirdi. Olcuyorum, varsaymiyorum.
  if v_src ~ '\mdiscover_availabilities\s*\(' then
    raise exception '243: govde kendi adini cagiriyor — yeniden adlandirma guvenli degil. Elle bakilmali.';
  end if;

  -- (1) Gövdeyi AYNEN koru, yalnız başlıktaki adı değiştir.
  v_ham := regexp_replace(v_def,
    'FUNCTION\s+public\.discover_availabilities\s*\(',
    'FUNCTION public.discover_availabilities_ham(', 'i');
  if v_ham = v_def then
    raise exception '243: fonksiyon basligi beklenen bicimde degil, kopyalanamadi.';
  end if;
  execute v_ham;

  -- (2) Sarmalayıcı. `row_number() over ()` ham fonksiyonun KENDİ çıktı
  -- sırasını yakalar; ikinci sıralama ölçütü olarak kullanınca içerideki
  -- bütün mantık korunur.
  execute format(
    '

-- ----------------------------------------------------------------------
-- bo_ilan_degisiklikleri   [etkin kaynak: 237_ilan_ve_seyahat_duzenlenebilsin.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_ilan_degisiklikleri(p_limit int default 100)
returns table (
  created_at timestamptz, actor_id uuid, eposta text,
  entity_type text, entity_id uuid, oncesi jsonb, sonrasi jsonb
)
language plpgsql stable security definer set search_path = public as $bod$
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles where user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  return query
  select a.created_at, a.actor_id, u.email, a.entity_type, a.entity_id,
         a.before_data, a.after_data
    from audit_log a left join users u on u.id = a.actor_id
   where a.action in ('availability.update','visit.update')
   order by a.created_at desc
   limit greatest(1, least(coalesce(p_limit,100), 500));
end $bod$;
grant execute on function public.bo_ilan_degisiklikleri(int) to service_role;

-- ----------------------------------------------------------------------------
-- 5) NÖBETÇİ — düzenleme GERÇEKTEN çalışıyor, kilitler GERÇEKTEN kilitliyor
-- ----------------------------------------------------------------------------
do $n237$
declare
  v_host uuid; v_guest uuid; v_av uuid; v_vis uuid;
  v_r jsonb; v_hata boolean;
begin
  select r.host_id, r.guest_id into v_host, v_guest
    from requests r where r.status = 'accepted' limit 1;

  if v_host is null then
    raise notice '237 OLCULMEDI: kabul edilmis basvurusu olan ilan yok — sozlesme kilidi sinanmadi.';
  else
    select id into v_av from requests where host_id = v_host and status='accepted' limit 1;
    select avail_id into v_av from requests where id = v_av;

    -- (a) Kabul edilmiş başvuru varken TARİH değiştirilemez
    v_hata := false;
    begin
      perform set_config('request.jwt.claim.sub', v_host::text, true);
      v_r := public.update_availability(v_av, current_date + 30);
      v_hata := true;
    exception
      when others then
        if sqlerrm not like '%kabul_edilmis_basvuru_var%' and sqlerrm not like '%not_authenticated%' then
          raise notice '237: beklenmeyen hata (tarih kilidi): %', sqlerrm;
        end if;
    end;
    if v_hata then
      raise exception '237 NOBETCI: kabul edilmis basvuru varken TARIH degistirilebildi.';
    end if;

    -- (b) Aktif ilan, kabul edilmiş başvuru varken KAPATILAMAZ
    v_hata := false;
    begin
      update availabilities set active = false where id = v_av;
      v_hata := true;
    exception when others then
      if sqlerrm not like '%has_accepted_requests%' then
        raise notice '237: beklenmeyen hata (kapatma kapisi): %', sqlerrm;
      end if;
    end;
    if v_hata then
      raise exception '237 NOBETCI: kabul edilmis basvuru varken ilan DOGRUDAN kapatilabildi (tetikleyici calismiyor; app tam bunu yapiyor).';
    end if;

    raise notice '237 OK · sozlesme kilidi tutuyor · dogrudan kapatma engellendi';
  end if;

  -- (c) Fonksiyonlar gerçekten kuruldu mu?
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                  where n.nspname='public' and p.proname='update_availability') then
    raise exception '237 NOBETCI: update_availability kurulmadi.';
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                  where n.nspname='public' and p.proname='update_visit') then
    raise exception '237 NOBETCI: update_visit kurulmadi.';
  end if;

  raise notice '237 OLCULMEDI: `update_availability` icindeki auth.uid() bagimli yollar '
               'harness''te tam sinanamiyor (auth.uid() null). Sahiplik ve kilit mantigi '
               'kod duzeyinde; canlida host1 ile denenmeli.';
end $n237$;

-- ----------------------------------------------------------------------------
-- 6) RPC YÜZEYİ
-- ----------------------------------------------------------------------------
-- 🔴 224'ÜN NÖBETÇİSİ BENİ YAKALADI: `cancel_availability`i yüzeye
-- yazdım ama GRANT vermedim → "yuzeyde yazili ama istemci CAGIRAMIYOR".
-- App bugüne kadar tabloyu doğrudan yazdığı için grant hiç gerekmemiş.
-- Artık RPC'yi çağıracak; grant şart.
grant execute on function public.cancel_availability(uuid) to authenticated;

insert into rpc_client_surface (fn_name, client, note) values
  ('update_availability','app','Ilan duzenleme — kabul edilmis basvuru varsa tarih/saat/salon kilitli (237)'),
  ('update_visit','app','Seyahat duzenleme — bagli basvuru varsa havalimani/tarih kilitli (237)'),
  ('cancel_availability','app','Ilan kaldirma — app artik dogrudan tablo yazmiyor (237)')
on conflict (fn_name) do update set note = excluded.note;

do $$
declare v jsonb;
begin
  v := public.apply_rpc_surface();
  raise notice '237: sinir uygulandi — % kapatildi', v ->> 'kilitlenen';
end $$;

-- ----------------------------------------------------------------------
-- trg_soru_metni   [etkin kaynak: 239_soru_hangi_ilana_ait.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_soru_metni()
returns trigger language plpgsql security definer set search_path = public as $sm$
declare v_salon text; v_metin text;
begin
  if new.intent is distinct from 'kural_sorusu' then return new; end if;

  select coalesce(nullif(btrim(a.lounge_name),''), l.name, a.airport_code::text)
    into v_salon
    from availabilities a
    left join lounges l on l.id = a.lounge_id
   where a.id = new.avail_id;

  select value #>> '{}' into v_metin from beta_settings where key = 'soru_intro_tr';
  if v_metin is null then return new; end if;

  new.intro := left(replace(v_metin, '{salon}', coalesce(v_salon, 'bu')), 400);
  return new;
end $sm$;

-- ----------------------------------------------------------------------
-- trg_soru_bildirimi_host   [etkin kaynak: 239_soru_hangi_ilana_ait.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_soru_bildirimi_host()
returns trigger language plpgsql security definer set search_path = public as $sbh$
declare v_salon text; v_b text; v_g text;
begin
  if new.intent is distinct from 'kural_sorusu' then return new; end if;

  select coalesce(nullif(btrim(a.lounge_name),''), l.name, a.airport_code::text)
    into v_salon
    from availabilities a
    left join lounges l on l.id = a.lounge_id
   where a.id = new.avail_id;

  select value #>> '{}' into v_b from beta_settings where key='soru_bildirim_baslik_tr';
  select value #>> '{}' into v_g from beta_settings where key='soru_bildirim_govde_tr';
  if v_b is null or v_g is null then return new; end if;

  update notifications
     set title = v_b,
         body  = replace(v_g, '{salon}', coalesce(v_salon, 'bu'))
   where user_id = new.to_id and ref_type = 'connection' and ref_id = new.id;

  return new;
end $sbh$;

-- ----------------------------------------------------------------------------
-- 6) NÖBETÇİ — tahmin gerçekten kalktı mı?
-- ----------------------------------------------------------------------------
do $n239$
declare
  v_kolon int; v_tahmin int; v_yazar int;
begin
  select count(*) into v_kolon from information_schema.columns
   where table_schema='public' and table_name='connection_requests' and column_name='avail_id';
  if v_kolon <> 1 then
    raise exception '239 NOBETCI: connection_requests.avail_id kolonu YOK.';
  end if;

  -- 🔴 ASIL SINAMA: hiçbir okuyucu artık "host'un ilk ilanı" tahminini
  -- taşımamalı. Dört fonksiyonun gövdesinde o desen kaldıysa tahmin
  -- sürüyor demektir.
  select count(*) into v_tahmin
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public'
     and p.proname in ('sorularim','trg_soru_izi','trg_soru_metni','trg_soru_bildirimi_host')
     and p.prosrc like '%a.host_id = %active%order by%limit 1%';
  if v_tahmin <> 0 then
    raise exception '239 NOBETCI: % fonksiyon hala ilani TAHMIN ediyor.', v_tahmin;
  end if;

  select count(*) into v_yazar
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='ilan_kurali_sor'
     and p.prosrc like '%avail_id%';
  if v_yazar <> 1 then
    raise notice '239 UYARI: ilan_kurali_sor gövdesinde avail_id gorunmuyor — '
                 'yeni sorular ilansiz kaydedilecek. 221/223 degismis olabilir.';
  else
    raise notice '239 OK · kolon var · yazan taraf avail_id yaziyor · 4 okuyucuda tahmin yok';
  end if;

  raise notice '239 OLCULMEDI: GECMIS sorularin avail_id si yalniz host un TEK aktif ilani '
               'varsa dolduruldu. Birden cok ilani olan hostlarin eski sorulari BOS kaldi — '
               'bilerek: yanlis doldurmaktansa bos birakmak.';
end $n239$;

select '239 SORU ARTIK ILANI BILIYOR' as sonuc,
       (select count(*) from connection_requests where intent='kural_sorusu') as toplam_soru,
       (select count(*) from connection_requests where intent='kural_sorusu' and avail_id is not null) as ilani_bilinen;

-- ----------------------------------------------------------------------
-- trg_seyahat_sozlesme_kapisi   [etkin kaynak: 240_kural_kapida_degil_odada.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_seyahat_sozlesme_kapisi()
returns trigger language plpgsql security definer set search_path = public as $f$
declare
  v_satir  visits%rowtype;
  v_bagli  int;
  v_admin  boolean;
begin
  v_satir := case when tg_op = 'DELETE' then old else new end;

  v_admin := auth.uid() is not null
             and exists (select 1 from admin_roles where user_id = auth.uid());
  if v_admin then
    return v_satir;
  end if;

  -- 🔴 BURAYI BİR KEZ YANLIŞ YAZDIM VE KENDİ HARNESS'İM YAKALADI.
  -- İlk sürümde bağı "aynı kişi + aynı havalimanı + aynı gün" diye
  -- TAHMİN ediyordum. SEED_KURAL_SENARYOLARI tekrar kurulumda patladı:
  --   ERROR: seyahat_silinemez_basvuru_var
  -- çünkü o seyahate bağlı OLMAYAN, sadece aynı gün/havalimanına denk
  -- gelen bir başvuru vardı.
  --
  -- Daha kötüsü: bu, 239'da tam olarak SÖKTÜĞÜM hatanın aynısıydı.
  -- Orada "sorunun hangi ilana ait olduğunu tahmin etme, KAYDET" dedim;
  -- burada seyahat bağını tahmin ediyordum. `requests.visit_id` zaten
  -- var ve app onu yazıyor (ölçüldü: 18 başvurunun 13'ünde dolu).
  --
  -- 🆕 SINIF: **"BİR BAĞI TAHMİN ETMEK, O BAĞ KAYITLIYKEN, KAYDI
  -- OKUMAMAYI SEÇMEKTİR."**
  select count(*) into v_bagli
    from requests r
   where r.visit_id = old.id
     and r.status in ('pending','accepted');

  if v_bagli = 0 then
    return v_satir;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'seyahat_silinemez_basvuru_var'
      using detail = format('%s aktif basvuru', v_bagli),
            hint   = 'Bu seyahate dayanan basvurun var. Once basvuruyu iptal et.';
  end if;

  if new.airport_code is distinct from old.airport_code
     or new.visit_date is distinct from old.visit_date then
    -- Aynı bağ tanımı UPDATE için de geçerli: kayıtlı bağ, tahmin değil.
    raise exception 'seyahate_bagli_basvuru_var'
      using detail = format('%s aktif basvuru', v_bagli),
            hint   = 'Havalimani ve tarih kilitli. Saat ve ucus bilgisini '
                  || 'simdi de duzeltebilirsin.';
  end if;

  return v_satir;
end $f$;

-- ----------------------------------------------------------------------------
-- 1b) 🔴 GÖVDEYİ GENİŞLETMEK YETMEDİ — TETİKLEYİCİ SÜTUN KAPSAMLIYDI
-- ----------------------------------------------------------------------------
-- Yukarıdaki gövdeyi yazıp ölçtüm ve nöbetçi kırmızı yandı:
--   "kabul edilmis basvuru varken ilan TARIHI dogrudan degistirilebildi"
--
-- Sebep, gövde değil TANIMdı:
--   CREATE TRIGGER trg_avail_kapatma_kapisi
--     BEFORE UPDATE **OF active** ON availabilities
--
-- `UPDATE OF active` — yani tetikleyici yalnızca SET listesinde `active`
-- geçtiğinde çalışıyor. `set avail_date=...` yazan bir sorgu onu HİÇ
-- uyandırmıyor. Gövdesine ne yazarsam yazayım, o kod hiç koşmayacaktı.
--
-- 🆕 SINIF: **"BİR TETİKLEYİCİYİ GÖVDESİNDEN OKUMAK, NE ZAMAN
-- ÇALIŞTIĞINI OKUMAK DEĞİLDİR."** Gövde "if active değiştiyse" diyordu;
-- ben bunu "her güncellemede çalışır, içeride ayıklar" diye okudum.
-- Oysa ayıklama tanımın kendisindeydi.
drop trigger if exists trg_avail_kapatma_kapisi on public.availabilities;
create trigger trg_avail_kapatma_kapisi
  before update on public.availabilities
  for each row execute function public.trg_ilan_kapatma_kapisi();

drop trigger if exists trg_visit_sozlesme on public.visits;
create trigger trg_visit_sozlesme
  before update or delete on public.visits
  for each row execute function public.trg_seyahat_sozlesme_kapisi();

-- ----------------------------------------------------------------------------
-- 2b) TEK TANIM, İKİ KAPI — RPC VE TETİKLEYİCİ AYNI CÜMLEYİ OKUSUN
-- ----------------------------------------------------------------------------
-- 237'nin `update_visit()`'i bağı "aynı havalimanı + aynı gün" diye
-- TAHMİN ediyordu; yukarıdaki tetikleyici artık `requests.visit_id`'yi
-- OKUYOR. İkisi farklı cümle kurarsa, kullanıcı hangi kapıdan girdiğine
-- göre farklı cevap alır — bu dosyanın varlık sebebi tam olarak buydu.
--
-- Çözüm: tanım TEK bir fonksiyona taşınır, iki kapı da onu çağırır.

-- ----------------------------------------------------------------------
-- seyahate_bagli_basvuru   [etkin kaynak: 240_kural_kapida_degil_odada.sql]
-- ----------------------------------------------------------------------
create or replace function public.seyahate_bagli_basvuru(p_visit_id uuid)
returns int language sql stable security definer set search_path = public as $f$
  select count(*)::int from requests
   where visit_id = p_visit_id and status in ('pending','accepted');
$f$;
revoke execute on function public.seyahate_bagli_basvuru(uuid) from public, anon, authenticated;

-- Önce KAYITSIZ bağları kapat: `visit_id` boş kalmış başvuruları, YALNIZ
-- tek bir seyahatle eşleşiyorsa doldur. 239'un kuralı: tahmini kalıcı
-- veri olarak yazma — iki aday varsa boş bırak.
with aday as (
  select r.id as req_id, (array_agg(v.id))[1] as visit_id, count(*) as kac
    from requests r
    join availabilities a on a.id = r.avail_id
    join visits v on v.user_id = r.guest_id
                 and v.airport_code = a.airport_code
                 and v.visit_date   = a.avail_date
   where r.visit_id is null
   group by r.id
  having count(*) = 1
)
update requests r set visit_id = aday.visit_id
  from aday where aday.req_id = r.id;

do $u$
declare v_def text; v_yeni text; v_kalan int;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='update_visit' limit 1;

  if v_def is null then
    raise notice '240: update_visit yok (237 kosulmamis) — atlaniyor.';
  else
    -- 🔴 METNİ EZBERDEN YAZMIYORUM (238'in dersi): canlı gövdeyi okuyup
    -- düzenli ifadeyle değiştiriyorum. Değişmediyse haber veriyorum.
    v_yeni := regexp_replace(
      v_def,
      'select count\(\*\) into v_bagli\s*from requests r join availabilities a on a\.id = r\.avail_id[\s\S]*?and a\.avail_date   = v_v\.visit_date;',
      'v_bagli := public.seyahate_bagli_basvuru(p_id);');
    if v_yeni = v_def then
      raise notice '240 OLCULMEDI: update_visit govdesinde beklenen kalip bulunamadi — '
                   'RPC hala kendi tanimini kullaniyor olabilir. 237 surumunu kontrol et.';
    else
      execute v_yeni;
      raise notice '240: update_visit artik ortak tanimi okuyor.';
    end if;
  end if;

  select count(*) into v_kalan from requests
   where visit_id is null and status in ('pending','accepted');
  if v_kalan > 0 then
    raise notice '240: % aktif basvurunun seyahat bagi HALA bos (birden fazla '
                 'aday seyahat var, tahmin yazmadim). Bunlar silme kapisinin '
                 'disinda kalir.', v_kalan;
  end if;
end $u$;

-- ----------------------------------------------------------------------------
-- 3) KAPILARI KAPAT — İSTEMCİNİN DOĞRUDAN YAZMA HAKKI
-- ----------------------------------------------------------------------------
-- Ölçüldü: app'te `from("availabilities").update/insert/delete` HİÇ YOK
-- (237 hepsini RPC'ye taşıdı) ve `from("visits").update` de yok.
-- Yani bu grant'lar bugün KİMSE tarafından kullanılmıyor — yalnız
-- kötüye kullanım için duruyorlar.
revoke update on public.availabilities from authenticated;
revoke update on public.availabilities from anon;
revoke insert, delete on public.availabilities from authenticated;
revoke insert, delete on public.availabilities from anon;

revoke update on public.visits from authenticated;
revoke update on public.visits from anon;
-- INSERT ve DELETE KALIYOR: app ikisini de kullanıyor. DELETE artık
-- yukarıdaki tetikleyiciyle korunuyor; INSERT'ün bozacağı bir sözleşme yok.

-- Bildirim: kullanıcı kendi bildirimini OKUNDU işaretleyebilmeli, ama
-- bildirimin METNİNİ değiştirebilmemeli. Bugün tablo düzeyinde UPDATE
-- vardı, yani başlık ve gövde de yazılabiliyordu.
revoke update on public.notifications from authenticated;
revoke update on public.notifications from anon;
grant update (read, read_at) on public.notifications to authenticated;

-- ----------------------------------------------------------------------------
-- 4) NÖBETÇİ — HER İKİ YOLU DA ÖLÇ, HİÇBİR VERİYİ BOZMADAN
-- ----------------------------------------------------------------------------
-- 🔴 İLK YAZDIĞIMDA BU NÖBETÇİ SENİN VERİNİ SİLİYORDU. "Bağsız bir seyahat
-- silinebiliyor mu?" diye ölçmek için gerçekten siliyordu — harness'te
-- zararsız, CANLIDA senin seyahatin. Bir ölçüm, ölçtüğü şeyi bozuyorsa
-- ölçüm değil, hasardır.
--
-- 🆕 SINIF: **"BİR NÖBETÇİ, NÖBET TUTTUĞU ŞEYE ZARAR VEREMEZ."**
--
-- Çözüm: bütün yazma denemeleri BİR ALT İŞLEMİN içinde yapılır ve o alt
-- işlem SONUNDA HER HÂLÜKÂRDA geri alınır. PL/pgSQL değişkenleri geri
-- alınmaz — bu yüzden ölçüm sonuçları hayatta kalır, veri değişikliği
-- kalmaz.
do $n240$
declare
  v_av      uuid;
  v_vis     uuid;
  v_bos     uuid;
  v_dolu    uuid;
  v_eski    date;
  v_hatalar text[] := '{}';
  v_notlar  text[] := '{}';
  v_gecti   boolean;
begin
  -- ═══ ÖLÇÜM ALT İŞLEMİ — sonunda geri alınır ═══
  begin
    ------------------------------------------------------------------ İLAN
    select a.id, a.avail_date into v_av, v_eski
      from availabilities a
     where exists (select 1 from requests r where r.avail_id=a.id and r.status='accepted')
     limit 1;

    if v_av is null then
      v_notlar := v_notlar || 'ilan yolu OLCULMEDI (kabul edilmis basvurusu olan ilan yok)'::text;
    else
      -- (A1) tarih doğrudan değiştirilememeli
      v_gecti := false;
      begin
        update availabilities set avail_date = v_eski + 30 where id = v_av;
        v_gecti := true;
      exception when others then
        if sqlerrm not like '%kabul_edilmis_basvuru_var%' then
          v_hatalar := v_hatalar || ('tarih kapisinda beklenmeyen hata: ' || sqlerrm);
        end if;
      end;
      if v_gecti then
        v_hatalar := v_hatalar || 'kabul edilmis basvuru varken ilan TARIHI dogrudan degistirilebildi'::text;
      end if;

      -- (A2) kural motorunun çıktısı yazılamamalı
      begin
        update availabilities set rule_severity='ok', rule_headline='Kesinlikle girersin'
         where id = v_av;
        if exists (select 1 from availabilities where id=v_av and rule_headline='Kesinlikle girersin') then
          v_hatalar := v_hatalar || 'KURAL MOTORUNUN CIKTISI istemci yolundan yazilabildi'::text;
        end if;
      exception when others then
        v_hatalar := v_hatalar || ('motor cikitisi kapisinda beklenmeyen hata: ' || sqlerrm);
      end;

      -- (A3) kontenjan, doluluğun altına inememeli.
      -- 🔴 İLK DENEMEMDE `slots = 0` yazdım; o `slots >= 1` CHECK kısıtına
      -- takıldı ve benim kapımı hiç sınamadı. Bir sınama, sınadığı kapıya
      -- VARMADAN başka bir duvara çarpıyorsa o kapıyı ölçmemiştir.
      -- Doğrusu: dolu koltuk 2+ olan bir ilanda `slots = filled - 1`.
      select a.id into v_dolu from availabilities a where coalesce(a.filled,0) >= 2 limit 1;
      if v_dolu is null then
        v_notlar := v_notlar || 'kontenjan kapisi OLCULMEDI (2+ dolu ilan yok)'::text;
      else
        v_gecti := false;
        begin
          update availabilities a set slots = (a.filled - 1)::smallint where a.id = v_dolu;
          v_gecti := true;
        exception when others then
          if sqlerrm not like '%kontenjan_dolulugun_altinda%' then
            v_hatalar := v_hatalar || ('kontenjan kapisinda beklenmeyen hata: ' || sqlerrm);
          end if;
        end;
        if v_gecti then
          v_hatalar := v_hatalar || 'kontenjan dolulugun ALTINA indirilebildi'::text;
        end if;
      end if;

      -- (A4) 🔴 TERSTEN ÖLÇÜM: meşru değişiklik HÂLÂ geçebilmeli.
      -- Yalnızca "engelledi mi" diye bakan bir nöbetçi, HER ŞEYİ engelleyen
      -- bir tetikleyiciyi de yeşil yakar. Uçuş numarası kilitli DEĞİL.
      begin
        update availabilities set flight_number = 'TK9999' where id = v_av;
        if not exists (select 1 from availabilities where id=v_av and flight_number='TK9999') then
          v_hatalar := v_hatalar || 'mesru degisiklik (ucus no) da engellendi — kapi fazla genis'::text;
        end if;
      exception when others then
        v_hatalar := v_hatalar || ('mesru degisiklik engellendi: ' || sqlerrm);
      end;

      -- (A5) BO'nun tek yazdığı kolon (`filled`) hâlâ yazılabilmeli
      begin
        update availabilities set filled = coalesce(filled,0) where id = v_av;
      exception when others then
        v_hatalar := v_hatalar || ('BO nun filled yazmasi engellendi: ' || sqlerrm);
      end;

      v_notlar := v_notlar || 'ilan yolu olculdu'::text;
    end if;

    --------------------------------------------------------------- SEYAHAT
    select v.id into v_vis from visits v
     where exists (select 1 from requests r
                    where r.visit_id = v.id and r.status in ('pending','accepted'))
     limit 1;

    if v_vis is null then
      v_notlar := v_notlar || 'seyahat yolu OLCULMEDI (bagli basvurusu olan seyahat yok)'::text;
    else
      v_gecti := false;
      begin
        delete from visits where id = v_vis;
        v_gecti := true;
      exception when others then
        if sqlerrm not like '%seyahat_silinemez_basvuru_var%' then
          v_hatalar := v_hatalar || ('silme kapisinda beklenmeyen hata: ' || sqlerrm);
        end if;
      end;
      if v_gecti then
        v_hatalar := v_hatalar || 'bagli basvurusu olan seyahat SILINEBILDI (app tam bunu cagiriyor)'::text;
      end if;

      -- TERSTEN: bağsız seyahat silinebilmeli
      select v.id into v_bos from visits v
       where not exists (select 1 from requests r where r.visit_id = v.id)
       limit 1;
      if v_bos is not null then
        begin
          delete from visits where id = v_bos;
          if exists (select 1 from visits where id = v_bos) then
            v_hatalar := v_hatalar || 'bagsiz seyahat de silinemedi — kapi fazla genis'::text;
          end if;
        exception when others then
          v_hatalar := v_hatalar || ('bagsiz seyahat silinemedi: ' || sqlerrm);
        end;
      end if;

      v_notlar := v_notlar || 'seyahat yolu olculdu'::text;
    end if;

    -- ═══ HER ŞEYİ GERİ AL ═══
    raise exception 'GERI_AL_240';
  exception when others then
    if sqlerrm <> 'GERI_AL_240' then
      v_hatalar := v_hatalar || ('olcum alt islemi coktu: ' || sqlerrm);
    end if;
  end;

  ------------------------------------------------------------------ GRANTLAR
  -- (veri yazmaz — alt işlemin dışında)
  if exists (select 1 from information_schema.table_privileges
              where table_schema='public' and table_name='availabilities'
                and grantee in ('authenticated','anon')
                and privilege_type in ('INSERT','UPDATE','DELETE')) then
    v_hatalar := v_hatalar || 'availabilities uzerinde istemci yazma hakki DURUYOR'::text;
  end if;
  if exists (select 1 from information_schema.table_privileges
              where table_schema='public' and table_name='visits'
                and grantee in ('authenticated','anon') and privilege_type='UPDATE') then
    v_hatalar := v_hatalar || 'visits uzerinde istemci UPDATE hakki DURUYOR'::text;
  end if;
  if not exists (select 1 from information_schema.column_privileges
                  where table_schema='public' and table_name='visits'
                    and grantee='authenticated' and privilege_type='INSERT') then
    v_hatalar := v_hatalar || 'visits INSERT de kalkti — app seyahat ekleyemez, fazla kestim'::text;
  end if;
  if not exists (select 1 from information_schema.column_privileges
                  where table_schema='public' and table_name='notifications'
                    and grantee='authenticated' and privilege_type='UPDATE'
                    and column_name='read') then
    v_hatalar := v_hatalar || 'bildirim OKUNDU isaretlenemez oldu — fazla kestim'::text;
  end if;
  -- 🔴 İLK YAZDIĞIMDA `privilege_type` filtresini KOYMADIM ve bu kontrol
  -- SELECT haklarını da sayıp yanlış alarm verdi. Bir nöbetçi, aradığı
  -- şeyi tam söylemezse bulduğu şeyi yanlış adlandırır.
  if exists (select 1 from information_schema.column_privileges
              where table_schema='public' and table_name='notifications'
                and grantee='authenticated' and privilege_type='UPDATE'
                and column_name in ('title','body')) then
    v_hatalar := v_hatalar || 'bildirim METNI hala istemciden yazilabiliyor'::text;
  end if;

  ------------------------------------------------------------------ RAPOR
  if array_length(v_hatalar,1) is not null then
    raise exception '240 NOBETCI: %', array_to_string(v_hatalar, ' | ');
  end if;
  raise notice '240 OK · % · grantlar temiz · olcum geri alindi (veri degismedi)',
               array_to_string(v_notlar, ' · ');
end $n240$;

select '240 KURAL ODAYA TASINDI' as sonuc,
       (select count(*) from information_schema.table_privileges
         where table_schema='public' and table_name='availabilities'
           and grantee in ('authenticated','anon')
           and privilege_type in ('INSERT','UPDATE','DELETE'))            as acik_ilan_yazma,
       (select count(*) from pg_trigger where tgname='trg_visit_sozlesme' and not tgisinternal) as seyahat_kapisi,
       (select count(*) from information_schema.column_privileges
         where table_schema='public' and table_name='notifications'
           and grantee='authenticated' and privilege_type='UPDATE')       as bildirim_yazilabilir_kolon;

-- ----------------------------------------------------------------------
-- motor_yazimi_ac   [etkin kaynak: 243_one_cikarma_gercekten_calissin.sql]
-- ----------------------------------------------------------------------
create or replace function public.motor_yazimi_ac()
returns void language plpgsql security definer set search_path = public as $f$
begin
  perform set_config('loungelink.motor', 'evet', true);   -- true = işlem sonunda düşer
end $f$;
revoke execute on function public.motor_yazimi_ac() from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2) TETİKLEYİCİ: KURAL AYNI, İSTİSNA DOĞRU YERDE
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------
-- odul_puan_onerisi   [etkin kaynak: 244_odul_ekonomisi.sql]
-- ----------------------------------------------------------------------
create or replace function public.odul_puan_onerisi(p_maliyet_try numeric, p_tur text default 'nakit')
returns int language sql stable set search_path = public as $f$
  -- Ortaklik odullerinde maliyet ~0 oldugu icin tavan uygulanmaz; orada
  -- fiyat bir ERISILEBILIRLIK kararidir, maliyet karari degil.
  select case
    when p_maliyet_try is null then null
    when p_tur = 'ortaklik' then greatest(500, (ceil(p_maliyet_try * 10 / 100.0) * 100)::int)
    else greatest(500, (ceil(
           p_maliyet_try * 100.0
           / nullif(coalesce((select (value #>> '{}')::numeric from beta_settings
                               where key='puan_basina_kurus'), 2), 0)
           / 100) * 100)::int)
  end;
$f$;

-- ----------------------------------------------------------------------------
-- 3) NÖBETÇİ TETİKLEYİCİ — BATIRAN ÖDÜL YAYINLANAMAZ
-- ----------------------------------------------------------------------------
-- Bu kural BO'nun ekranında değil, VERİNİN KENDİSİNDE duruyor. Ekrana
-- koysaydım, ekranı atlayan her yol (SQL Editor, ileride bir betik) onu
-- atlardı — 240'ın dersi.

-- ----------------------------------------------------------------------
-- trg_odul_ekonomi_kapisi   [etkin kaynak: 245_vitrin_gokberkin_listesi.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_odul_ekonomi_kapisi()
returns trigger language plpgsql security definer set search_path = public as $f$
declare v_asgari int;
begin
  if not coalesce(new.active, false) then return new; end if;
  if coalesce(new.maliyet_turu,'nakit') in ('ortaklik','kendi') then return new; end if;

  if new.supplier_cost_try is null then
    raise exception 'odul_maliyeti_yazilmamis'
      using detail = format('"%s" nakit odulu, maliyeti bilinmeden yayinlanamaz', new.title),
            hint   = 'BO > Odul Ekonomisi ekranindan maliyeti gir.';
  end if;

  v_asgari := public.odul_puan_onerisi(new.supplier_cost_try, 'nakit');
  if new.cost_points < v_asgari and not coalesce(new.bilerek_zararina, false) then
    raise exception 'odul_fiyati_maliyetin_altinda'
      using detail = format('"%s": %s puan, maliyet ₺%s → asgari %s puan',
                            new.title, new.cost_points, new.supplier_cost_try, v_asgari),
            hint   = 'Fiyati yukselt, ya da BILEREK zararina isaretleyip gerekce yaz.';
  end if;
  return new;
end $f$;

-- ----------------------------------------------------------------------------
-- 2) VİTRİN — GÖKBERK'İN LİSTESİ + İKİ EKLEME
-- ----------------------------------------------------------------------------
-- Rozet vitrinden çıkıyor: puanla satın alınan bir rozet, rozet değil
-- etikettir. Rozetler kullanımla hak edilir (aşağıda 4. bölüm).
update rewards set active = false;

do $vitrin$
declare
  v_kur numeric := coalesce((select (value #>> '{}')::numeric from beta_settings
                              where key='odul_kur_usd_try'), 41);
  r record;
begin
  for r in select * from (values
    -- baslik, altbaslik, kategori, puan, sira, saglayici, tur, maliyet_try, gerekce
    ('Havalimanı Kahvesi',        'Ortak kafelerde',    'yeme',    500,  1, 'Ortak kafe',
     'nakit',    60.0,  'Ilk odul bir PAZARLAMA GIDERI: kullanici sistemin gercekten odedigini gorsun diye. Kullanici basina bir kez.'),
    ('+2 Misafir İsteği Kredisi', 'Hemen hesabına',     'kendi',   500,  2, 'LoungeLink',
     'kendi',     0.0,  null),
    ('Amazon Hediye Kartı ₺500',  'Dijital kod',        'hediye', 1000,  3, 'Amazon',
     'nakit',   500.0,  'Vitrin ornegi — bilerek zararina. Gercek maliyet 50 kurus/puan; surdurulebilir degil, lansman kararidir.'),
    ('İlan Öne Çıkarma · 3 gün',  'Keşifte en üstte',   'kendi',   750,  4, 'LoungeLink',
     'kendi',     0.0,  null),
    ('Airalo eSIM 3 GB',          'Küresel veri',       'esim',   1500,  5, 'Airalo',
     'nakit',   349.0,  'Vitrin ornegi — bilerek zararina (23 kurus/puan).'),
    ('Sık Uçan Planı · 1 ay',     'Aylık 6 kredi',      'kendi',  2000,  6, 'LoungeLink',
     'kendi',     0.0,  null),
    ('Marriott Bonvoy 20 $ Kredi','Bonvoy otelleri',    'hotel',  2500,  7, 'Marriott Bonvoy',
     'nakit',   820.0,  'Vitrin ornegi — bilerek zararina (33 kurus/puan).'),
    ('Booking.com 25 $ Kredi',    'Her konaklama',      'hotel',  3000,  8, 'Booking.com',
     'nakit',  1025.0,  'Vitrin ornegi — bilerek zararina (34 kurus/puan).'),
    ('Türk Hava Yolları 1000 Mil','Miles&Smiles',       'miles',  5000,  9, 'Miles&Smiles',
     'nakit',  1230.0,  'Vitrin ornegi — bilerek zararina (25 kurus/puan). Hedef pazar Turkiye: vitrinin tepesi THY.')
  ) as t(baslik, alt, kat, puan, sira, saglayici, tur, maliyet, gerekce)
  loop
    update rewards
       set subtitle = r.alt, category = r.kat, cost_points = r.puan, sort_order = r.sira,
           supplier = r.saglayici, maliyet_turu = r.tur,
           supplier_cost_try = round(r.maliyet)::int,
           maliyet_kaynagi = 'tahmin', maliyet_guncel_at = now(),
           bilerek_zararina = (r.gerekce is not null),
           zarar_gerekce = r.gerekce,
           teslim_sekli = coalesce(teslim_sekli, 'manuel'),
           teslim_saat  = coalesce(teslim_saat, 48),
           active = true
     where title = r.baslik;

    if not found then
      insert into rewards (title, subtitle, category, cost_points, active, sort_order,
                           supplier, teslim_sekli, teslim_saat, maliyet_turu, maliyet_kaynagi,
                           supplier_cost_try, maliyet_guncel_at, bilerek_zararina, zarar_gerekce)
      values (r.baslik, r.alt, r.kat, r.puan, true, r.sira, r.saglayici,
              case when r.tur = 'kendi' then 'otomatik' else 'manuel' end,
              case when r.tur = 'kendi' then 1 else 48 end,
              r.tur, 'tahmin', round(r.maliyet)::int, now(),
              (r.gerekce is not null), r.gerekce);
    end if;
  end loop;
end $vitrin$;

-- Eski, artık vitrinde olmayanlar: silinmiyor, pasif duruyor.
-- (Emirates, SafetyWing, Airalo 10GB, Booking 50$, eski THY 500 mil,
--  LoungeLink rozeti, PP/DragonPass kartlari.)

-- ----------------------------------------------------------------------------
-- 3) SÜRDÜRÜLEBİLİRLİK — SAYIYI EKRANA YAZ
-- ----------------------------------------------------------------------------
-- Bir kararın bedelini görünmez kılmak, o kararı savunmak değil
-- ertelemektir. Bu fonksiyon "bu vitrin ayda ne yakar" sorusunu
-- cevaplıyor ve BO'da her açılışta görünüyor.

-- ----------------------------------------------------------------------
-- bo_odul_ekonomisi   [etkin kaynak: 244_odul_ekonomisi.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_odul_ekonomisi()
returns table(
  id uuid, baslik text, aktif boolean, tur text, kaynak text,
  maliyet_try numeric, puan int, asgari_puan int,
  kurus_basina_puan numeric, agirlama_sayisi numeric, durum text)
language sql stable security definer set search_path = public as $f$
  -- 🔴 `supplier_cost_try` INTEGER; burada `numeric` ilan ettim ve tip
  -- nobetcisi yakaladi. Ilan ile kaynak arasindaki her sessiz cevrim,
  -- bir gun 22P02 olarak canliya cikar. Acik cast yaziyorum.
  select r.id, r.title, r.active, coalesce(r.maliyet_turu,'nakit'), r.maliyet_kaynagi,
         r.supplier_cost_try::numeric, r.cost_points,
         public.odul_puan_onerisi(r.supplier_cost_try, coalesce(r.maliyet_turu,'nakit')),
         case when r.cost_points > 0 and r.supplier_cost_try is not null
              then round(r.supplier_cost_try::numeric * 100.0 / r.cost_points, 2) end,
         round(r.cost_points / nullif(
           coalesce((select (value #>> '{}')::numeric from beta_settings where key='host_session_points'), 500)
           + coalesce((select (value #>> '{}')::numeric from beta_settings where key='guest_session_points'), 200), 0), 1),
         case
           when coalesce(r.maliyet_turu,'nakit') = 'ortaklik' then 'ortaklik — tavan disi'
           when r.supplier_cost_try is null then 'MALIYET YAZILMAMIS'
           when r.cost_points < public.odul_puan_onerisi(r.supplier_cost_try,'nakit') then 'ZARARINA'
           when r.maliyet_kaynagi = 'tahmin' then 'tahmini maliyet — teyit bekliyor'
           else 'saglikli'
         end
    from rewards r
   order by r.active desc, r.sort_order, r.cost_points;
$f$;
revoke execute on function public.bo_odul_ekonomisi() from public, anon, authenticated;
grant execute on function public.bo_odul_ekonomisi() to service_role;

-- ----------------------------------------------------------------------
-- bo_odul_maliyet_yaz   [etkin kaynak: 244_odul_ekonomisi.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_odul_maliyet_yaz(
  p_id uuid, p_maliyet numeric, p_tur text default null, p_teyitli boolean default true)
returns jsonb language plpgsql security definer set search_path = public as $f$
declare v_r rewards%rowtype; v_yeni int;
begin
  select * into v_r from rewards where id = p_id;
  if not found then raise exception 'odul_yok'; end if;
  if p_maliyet < 0 then raise exception 'gecersiz_maliyet'; end if;

  v_yeni := public.odul_puan_onerisi(p_maliyet, coalesce(p_tur, v_r.maliyet_turu, 'nakit'));

  update rewards
     set supplier_cost_try = round(p_maliyet)::int,
         maliyet_turu      = coalesce(p_tur, maliyet_turu, 'nakit'),
         maliyet_kaynagi   = case when p_teyitli then 'teyitli' else 'tahmin' end,
         maliyet_guncel_at = now(),
         -- Fiyat maliyetin altındaysa OTOMATİK yükseltiyorum. Aksi hâlde
         -- tetikleyici kaydı reddeder ve admin "neden kaydolmadı"
         -- diye kalırdı; sebebi anlaşılmayan bir ret, ret değil duvardır.
         cost_points       = greatest(cost_points, coalesce(v_yeni, cost_points))
   where id = p_id;

  return jsonb_build_object('ok', true, 'asgari_puan', v_yeni,
                            'yeni_puan', (select cost_points from rewards where id=p_id));
end $f$;
revoke execute on function public.bo_odul_maliyet_yaz(uuid, numeric, text, boolean)
  from public, anon, authenticated;
grant execute on function public.bo_odul_maliyet_yaz(uuid, numeric, text, boolean) to service_role;

-- ----------------------------------------------------------------------------
-- 6) NÖBETÇİ
-- ----------------------------------------------------------------------------
do $n244$
declare
  v_hatalar text[] := '{}';
  v_gecti   boolean;
  v_aktif   int;
  v_zarar   int;
  v_id      uuid;
begin
  -- (1) Aktif hiçbir NAKİT ödül zararına olmamalı
  select count(*) into v_zarar from rewards r
   where r.active and coalesce(r.maliyet_turu,'nakit')='nakit'
     and (r.supplier_cost_try is null
          or r.cost_points < public.odul_puan_onerisi(r.supplier_cost_try,'nakit'));
  if v_zarar > 0 then
    v_hatalar := v_hatalar || format('%s aktif nakit odul zararina', v_zarar);
  end if;

  -- (2) 🔴 TERS YÖN: vitrin BOŞALMAMALI. Her şeyi pasife alan bir
  -- düzeltme de birinci kontrolden yeşil geçer ve mağazayı öldürür.
  select count(*) into v_aktif from rewards where active;
  if v_aktif < 5 then
    v_hatalar := v_hatalar || format('vitrinde yalniz %s aktif odul kaldi — fazla kestim', v_aktif);
  end if;

  -- (3) Kapı gerçekten kapıyor mu: zararına bir ödülü aktif etmeyi dene
  begin
    select id into v_id from rewards where coalesce(maliyet_turu,'nakit')='nakit'
       and supplier_cost_try is not null limit 1;
    if v_id is not null then
      v_gecti := false;
      begin
        update rewards set cost_points = 1, active = true where id = v_id;
        v_gecti := true;
      exception when others then
        if sqlerrm not like '%odul_fiyati_maliyetin_altinda%' then
          v_hatalar := v_hatalar || ('beklenmeyen hata (ekonomi kapisi): ' || sqlerrm);
        end if;
      end;
      if v_gecti then
        v_hatalar := v_hatalar || 'zararina odul AKTIF EDILEBILDI — kapi calismiyor'::text;
      end if;
    end if;
    raise exception 'GERI_AL_244';
  exception when others then
    if sqlerrm <> 'GERI_AL_244' then
      v_hatalar := v_hatalar || ('olcum coktu: ' || sqlerrm);
    end if;
  end;

  -- (4) En ucuz ödül gerçekten ULAŞILABİLİR olmalı (ilk basamak)
  if (select min(cost_points) from rewards where active) > 1500 then
    v_hatalar := v_hatalar || 'en ucuz odul 1500 puandan pahali — ilk basamak yok, kimse baslamaz'::text;
  end if;

  if array_length(v_hatalar,1) is not null then
    raise exception '244 NOBETCI: %', array_to_string(v_hatalar, ' | ');
  end if;
  raise notice '244 OK · % aktif odul · zararina 0 · en ucuz % puan',
    v_aktif, (select min(cost_points) from rewards where active);
end $n244$;

select '244 ODUL EKONOMISI KURULDU' as sonuc,
       (select count(*) from rewards where active)                        as aktif_odul,
       (select count(*) from rewards where active and maliyet_turu='nakit') as nakit_odul,
       (select count(*) from rewards where active and supplier_cost_try is null
          and coalesce(maliyet_turu,'nakit')='nakit')                     as maliyetsiz_nakit,
       (select min(cost_points) from rewards where active)                as en_ucuz_puan,
       (select max(cost_points) from rewards where active)                as en_pahali_puan;

-- ----------------------------------------------------------------------
-- odul_surdurulebilirlik   [etkin kaynak: 245_vitrin_gokberkin_listesi.sql]
-- ----------------------------------------------------------------------
create or replace function public.odul_surdurulebilirlik(p_agirlama_ay int default 1)
returns jsonb language sql stable security definer set search_path = public as $f$
  with a as (
    select coalesce((select (value #>> '{}')::numeric from beta_settings where key='host_session_points'), 500)
         + coalesce((select (value #>> '{}')::numeric from beta_settings where key='guest_session_points'), 200) as puan_agirlama
  ),
  o as (
    select avg(r.supplier_cost_try::numeric * 100.0 / nullif(r.cost_points,0)) as ort_kurus
      from rewards r
     where r.active and coalesce(r.maliyet_turu,'nakit') = 'nakit' and r.supplier_cost_try is not null
  )
  select jsonb_build_object(
    'puan_agirlama',        (select puan_agirlama from a),
    'ortalama_kurus_puan',  round(coalesce((select ort_kurus from o), 0), 1),
    'odul_maliyeti_agirlama_try',
        round(coalesce((select ort_kurus from o), 0) * (select puan_agirlama from a) / 100.0, 2),
    'aylik_maliyet_try',
        round(coalesce((select ort_kurus from o), 0) * (select puan_agirlama from a) / 100.0 * p_agirlama_ay, 2),
    'sik_ucan_ayligi_try',  (select price_try from plan_catalog where plan='sik_ucan'),
    'yorum', case
      when coalesce((select ort_kurus from o), 0) = 0 then 'Aktif nakit odul yok — odul maliyeti sifir.'
      else format('Ayda %s agirlayan bir host icin odul maliyeti ~₺%s. Sik Ucan abonelik geliri ₺%s. %s',
                  p_agirlama_ay,
                  round(coalesce((select ort_kurus from o),0) * (select puan_agirlama from a) / 100.0 * p_agirlama_ay, 0),
                  coalesce((select price_try from plan_catalog where plan='sik_ucan'), 0),
                  case when coalesce((select ort_kurus from o),0) * (select puan_agirlama from a) / 100.0 * p_agirlama_ay
                            > coalesce((select price_try from plan_catalog where plan='sik_ucan'), 0)
                       then 'ODUL MALIYETI ABONELIK GELIRINI ASIYOR.'
                       else 'Abonelik geliri odul maliyetini karsiliyor.' end)
    end);
$f$;
revoke execute on function public.odul_surdurulebilirlik(int) from public, anon, authenticated;
grant execute on function public.odul_surdurulebilirlik(int) to service_role;

-- ----------------------------------------------------------------------------
-- 4) ROZETLER PUANLA SATILMAZ — HAK EDİLİR
-- ----------------------------------------------------------------------------
-- "Rozetleri kullanım karşılığı biz tanımlamalıyız zaten." Katılıyorum.
-- Bir rozet SATIN ALINABİLİYORSA, taşıdığı bilgi "bu kişi bunu yaptı"
-- değil "bu kişi bunu aldı" olur — yani rozetin bütün anlamı gider.
create table if not exists rozet_katalogu (
  kod        text primary key,
  ad         text not null,
  aciklama   text not null,
  kosul_tur  text not null check (kosul_tur in ('agirlama','misafirlik','dogrulama','kidem')),
  esik       int  not null check (esik >= 1),
  sira       int  not null default 0
);
revoke all on public.rozet_katalogu from anon, authenticated;
grant select on public.rozet_katalogu to authenticated;
alter table public.rozet_katalogu enable row level security;
drop policy if exists rozet_okuma on public.rozet_katalogu;
create policy rozet_okuma on public.rozet_katalogu for select using (true);

insert into rozet_katalogu (kod, ad, aciklama, kosul_tur, esik, sira) values
  ('ilk_kapi',    'İlk Kapı',      'İlk misafirini ağırladın',                  'agirlama',   1, 1),
  ('kapi_acan',   'Kapı Açan',     '5 kez ağırladın',                           'agirlama',   5, 2),
  ('ev_sahibi',   'Ev Sahibi',     '15 kez ağırladın',                          'agirlama',  15, 3),
  ('ilk_misafir', 'İlk Misafir',   'İlk kez birinin misafiri oldun',            'misafirlik', 1, 4),
  ('kimlik',      'Doğrulanmış',   'Kimliğini doğruladın',                      'dogrulama',  1, 5),
  ('kurucu',      'Kurucu Çember', 'İlk 100 host arasındasın',                  'kidem',    100, 6)
on conflict (kod) do update set ad = excluded.ad, aciklama = excluded.aciklama;

-- ----------------------------------------------------------------------------
-- 5) NÖBETÇİ
-- ----------------------------------------------------------------------------
do $n245$
declare
  v_h text[] := '{}';
  v_aktif int; v_ucuz int; v_kendi int; v_gecti boolean; v_id uuid;
begin
  select count(*) into v_aktif from rewards where active;
  select min(cost_points) into v_ucuz from rewards where active;
  select count(*) into v_kendi from rewards where active and maliyet_turu='kendi';

  if v_aktif < 6 then v_h := v_h || format('vitrinde yalniz %s odul var', v_aktif); end if;
  if v_ucuz > 500 then v_h := v_h || format('en ucuz odul %s puan — ilk basamak cok yuksek', v_ucuz); end if;
  if v_kendi = 0 then v_h := v_h || 'kendi urunumuzden HIC odul yok — vitrin tamamen disariya bagimli'::text; end if;

  -- Rozet vitrinden gercekten cikti mi
  if exists (select 1 from rewards where active and category = 'rozet') then
    v_h := v_h || 'rozet HALA puanla satiliyor'::text;
  end if;
  if (select count(*) from rozet_katalogu) < 4 then
    v_h := v_h || 'rozet katalogu bos — rozetler hicbir sekilde hak edilemiyor'::text;
  end if;

  -- Kapi hala calisiyor mu: gerekcesiz zararina odul GECMEMELI
  begin
    select id into v_id from rewards where active and maliyet_turu='nakit' limit 1;
    if v_id is not null then
      v_gecti := false;
      begin
        update rewards set bilerek_zararina = false, zarar_gerekce = null, cost_points = 1
         where id = v_id;
        v_gecti := true;
      exception when others then
        if sqlerrm not like '%odul_fiyati_maliyetin_altinda%'
           and sqlerrm not like '%rewards_zarar_gerekce_chk%' then
          v_h := v_h || ('beklenmeyen hata: ' || sqlerrm);
        end if;
      end;
      if v_gecti then
        v_h := v_h || 'GEREKCESIZ zararina odul gecti — kapi calismiyor'::text;
      end if;
    end if;
    raise exception 'GERI_AL_245';
  exception when others then
    if sqlerrm <> 'GERI_AL_245' then v_h := v_h || ('olcum coktu: ' || sqlerrm); end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '245 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '245 OK · % odul (% tanesi kendi urunumuz) · en ucuz % puan · rozetler hak edilir',
    v_aktif, v_kendi, v_ucuz;
  raise notice '245 SURDURULEBILIRLIK · %',
    (public.odul_surdurulebilirlik(1) ->> 'yorum');
end $n245$;

select '245 VITRIN KURULDU' as sonuc,
       (select count(*) from rewards where active)                              as aktif_odul,
       (select count(*) from rewards where active and maliyet_turu='kendi')     as kendi_urun_odulu,
       (select count(*) from rewards where active and bilerek_zararina)         as bilerek_zararina,
       (public.odul_surdurulebilirlik(1) ->> 'odul_maliyeti_agirlama_try')      as agirlama_basina_odul_try,
       (select count(*) from rozet_katalogu)                                    as hak_edilen_rozet;

-- ----------------------------------------------------------------------
-- acik_istek_tavanim   [etkin kaynak: 274_istek_tavani_kilidi.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.acik_istek_tavanim()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_tavan int; v_acik int;
  v_saat int := coalesce((select (value #>> '{}')::int from beta_settings
                           where key = 'bayat_istek_saat'), 72);
begin
  if v_uid is null then return jsonb_build_object('acik', 0, 'tavan', 0); end if;

  select coalesce(
    (select p.acik_istek_tavani from plan_catalog p
       join users u on u.plan = p.plan where u.id = v_uid and p.aktif),
    (select p.acik_istek_tavani from plan_catalog p
       join users u on u.plan = p.plan where u.id = v_uid),
    1)
  into v_tavan;
  v_tavan := greatest(coalesce(v_tavan, 1), 1);

  select count(*) into v_acik
    from requests r
    join availabilities a on a.id = r.avail_id
   where r.guest_id = v_uid
     and r.status = 'pending'
     and a.avail_date >= current_date
     and r.created_at >= now() - make_interval(hours => v_saat);

  return jsonb_build_object('acik', v_acik, 'tavan', v_tavan);
end $$;

-- ----------------------------------------------------------------------
-- trg_acik_istek_tavani   [etkin kaynak: 274_istek_tavani_kilidi.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_acik_istek_tavani()
returns trigger language plpgsql security definer set search_path = public as $f$
declare
  v_tavan int;
  v_acik  int;
  v_saat  int := coalesce((select (value #>> '{}')::int from beta_settings
                            where key = 'bayat_istek_saat'), 72);
begin
  if new.status <> 'pending' then return new; end if;

  select coalesce(
    (select p.acik_istek_tavani from plan_catalog p
       join users u on u.plan = p.plan
      where u.id = new.guest_id and p.aktif),
    (select p.acik_istek_tavani from plan_catalog p
       join users u on u.plan = p.plan
      where u.id = new.guest_id),
    1)
  into v_tavan;
  v_tavan := greatest(coalesce(v_tavan, 1), 1);

  select count(*) into v_acik
    from requests r
    join availabilities a on a.id = r.avail_id
   where r.guest_id = new.guest_id
     and r.status = 'pending'
     and r.id <> new.id
     and a.avail_date >= current_date
     and r.created_at >= now() - make_interval(hours => v_saat);

  if v_acik >= v_tavan then
    raise exception 'acik_istek_tavani'
      using detail = format('%s/%s acik istek', v_acik, v_tavan),
            hint   = 'Bekleyen isteklerinden birini iptal edip yenisini gonderebilirsin.';
  end if;
  return new;
end $f$;


-- ════════════════════════════════════════════════════════════════════════
-- §3 — SAYAÇ İLE VİTRİN AYNI CÜMLEYİ KURMALI
--
-- `acik_istek_tavanim()` uygulamadaki "Açık istek 1/1" çipini besliyor.
-- Tavanla AYNI koşulu kullanmazsa çip, kapının yalanını doğrular.
--
-- 🆕 SINIF: "BİR KAPI İLE O KAPIYI ANLATAN GÖSTERGE FARKLI SORGU
-- KULLANIYORSA, GÖSTERGE KAPIYI DEĞİL KENDİNİ ANLATIR."
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- ilan_guven_esigi_yaz   [etkin kaynak: 288_guven_esigi_kolonu.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.ilan_guven_esigi_yaz(p_avail_id uuid, p_esik int)
returns jsonb language plpgsql security definer set search_path = public as $f$
declare v_uid uuid := auth.uid(); v_host uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_esik is null or p_esik < 0 or p_esik > 100 then
    raise exception 'gecersiz_deger' using hint = 'Guven esigi 0 ile 100 arasinda olmali.';
  end if;
  select host_id into v_host from availabilities where id = p_avail_id;
  if v_host is null then raise exception 'availability_not_found'; end if;
  if v_host <> v_uid then raise exception 'not_owner'; end if;

  perform public.motor_yazimi_ac();   -- 243: min_trust motor kolonlari arasinda
  update availabilities set min_trust = p_esik where id = p_avail_id;

  return jsonb_build_object('ok', true, 'min_trust', p_esik,
    'su_an_gorebilen', (select count(*) from trust_scores ts
                         where coalesce(ts.score, 0) >= p_esik));
end $f$;
grant execute on function public.ilan_guven_esigi_yaz(uuid, int) to authenticated;

-- ----------------------------------------------------------------------
-- trg_istek_guven_esigi   [etkin kaynak: 288_guven_esigi_kolonu.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_istek_guven_esigi()
returns trigger language plpgsql security definer set search_path = public as $f$
declare v_esik int; v_puan int;
begin
  select coalesce(a.min_trust, 0) into v_esik from availabilities a where a.id = new.avail_id;
  if coalesce(v_esik, 0) = 0 then return new; end if;
  select coalesce(ts.score, 0) into v_puan from trust_scores ts where ts.user_id = new.guest_id;
  if coalesce(v_puan, 0) < v_esik then
    raise exception 'guven_esigi_altinda'
      using detail = format('guven skoru %s, esik %s', coalesce(v_puan,0), v_esik),
            hint   = 'Bu ilan icin gereken guven skoruna henuz ulasmadin. '
                  || 'Kimligini dogrulayarak ve oturum tamamlayarak yukseltebilirsin.';
  end if;
  return new;
end $f$;

-- ----------------------------------------------------------------------
-- kredi_akis_raporu   [etkin kaynak: 246_ekonomi_ayari.sql]
-- ----------------------------------------------------------------------
create or replace function public.kredi_akis_raporu(p_gun int default 30)
returns jsonb language sql stable security definer set search_path = public as $f$
  select jsonb_build_object(
    'gun', p_gun,
    'basilan_kredi', coalesce((select sum(delta) from credit_ledger
                                where delta > 0 and created_at >= now() - make_interval(days => p_gun)), 0),
    'harcanan_kredi', coalesce((select -sum(delta) from credit_ledger
                                 where delta < 0 and created_at >= now() - make_interval(days => p_gun)), 0),
    'iade_edilen', coalesce((select sum(delta) from credit_ledger
                              where reason = 'request_refund' and created_at >= now() - make_interval(days => p_gun)), 0),
    'istek', (select count(*) from requests where created_at >= now() - make_interval(days => p_gun)),
    'kabul', (select count(*) from requests where status in ('accepted','completed')
                and created_at >= now() - make_interval(days => p_gun)),
    'tavana_takilan_kullanici',
      (select count(distinct guest_id) from requests r
        where r.status = 'pending'
          and (select count(*) from requests r2
                where r2.guest_id = r.guest_id and r2.status='pending')
              >= coalesce((select p.acik_istek_tavani from users u
                            left join plan_catalog p on p.plan=u.plan and p.aktif
                           where u.id = r.guest_id), 1)),
    'ayar', jsonb_build_object(
      'host_kredi', (select (value #>> '{}')::int from beta_settings where key='host_credit_per_session'),
      'ucretsiz_aylik', (select monthly_credits from plan_catalog where plan='yolcu')));
$f$;
revoke execute on function public.kredi_akis_raporu(int) from public, anon, authenticated;
grant execute on function public.kredi_akis_raporu(int) to service_role;

-- ----------------------------------------------------------------------------
-- 5) NÖBETÇİ
-- ----------------------------------------------------------------------------
do $n246$
declare v_h text[] := '{}'; v_gecti boolean; v_g uuid; v_a uuid; v_n int;
begin
  if (select (value #>> '{}')::int from beta_settings where key='host_credit_per_session') <> 1 then
    v_h := v_h || 'host kredisi 1 e inmedi'::text;
  end if;
  if (select monthly_credits from plan_catalog where plan='yolcu') <> 1 then
    v_h := v_h || 'ucretsiz plan aylik kredisi 1 e inmedi'::text;
  end if;
  if (select one_cikarma_ayda from plan_catalog where plan='kahya') > 12 then
    v_h := v_h || 'kahya one cikarma hakki hala sinirsiza yakin'::text;
  end if;
  -- TERS YÖN: ucretli planlar SIFIRLANMAMALI
  if (select monthly_credits from plan_catalog where plan='sik_ucan') < 3
     or (select monthly_credits from plan_catalog where plan='kahya') < 6 then
    v_h := v_h || 'ucretli planlarin kredisi de dustu — fazla kestim'::text;
  end if;
  if (select count(*) from plan_catalog where aktif and acik_istek_tavani is null) > 0 then
    v_h := v_h || 'bazi aktif planlarda acik istek tavani YOK'::text;
  end if;

  -- Tavan gercekten calisiyor mu
  begin
    select r.guest_id into v_g from requests r where r.status='pending' group by r.guest_id
     order by count(*) desc limit 1;
    if v_g is not null then
      select a.id into v_a from availabilities a where a.active
        and not exists (select 1 from requests q where q.avail_id=a.id and q.guest_id=v_g)
       limit 1;
      select count(*) into v_n from requests where guest_id=v_g and status='pending';
      if v_a is not null and v_n >= 1 then
        -- Tavani 1 e cekip ikinci istegi denemeliyim
        update plan_catalog set acik_istek_tavani = 1 where plan = (select plan from users where id=v_g);
        v_gecti := false;
        begin
          -- 🔴 `'lounge'` yazmistim; `request_type` enum'unun degerleri
          -- `standard` ve `direct_invite`. Bu turda ucuncu kez enum
          -- degerini EZBERDEN yazdim — katalogdan okumak zorunda degilim
          -- ama en azindan bakmaliyim.
          insert into requests (guest_id, host_id, avail_id, status, type)
          select v_g, a.host_id, a.id, 'pending', 'standard' from availabilities a where a.id=v_a;
          v_gecti := true;
        exception when others then
          if sqlerrm not like '%acik_istek_tavani%' then
            v_h := v_h || ('beklenmeyen hata (tavan): ' || sqlerrm);
          end if;
        end;
        if v_gecti then v_h := v_h || 'acik istek tavani ASILDI — tetikleyici calismiyor'::text; end if;
      end if;
    end if;
    raise exception 'GERI_AL_246';
  exception when others then
    if sqlerrm <> 'GERI_AL_246' then v_h := v_h || ('olcum coktu: ' || sqlerrm); end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '246 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '246 OK · host kredisi 1 · ucretsiz aylik 1 · acik istek tavani plana bagli';
end $n246$;

select '246 EKONOMI AYARLANDI' as sonuc,
       (select (value #>> '{}')::int from beta_settings where key='host_credit_per_session') as host_kredi,
       (select monthly_credits from plan_catalog where plan='yolcu')    as ucretsiz_aylik,
       (select acik_istek_tavani from plan_catalog where plan='yolcu')  as ucretsiz_acik_tavan,
       (select one_cikarma_ayda from plan_catalog where plan='kahya')   as kahya_one_cikarma;

-- ----------------------------------------------------------------------
-- talep_birak   [etkin kaynak: 247_haber_ver.sql]
-- ----------------------------------------------------------------------
create or replace function public.talep_birak(
  p_airport text, p_bas date, p_bit date default null)
returns jsonb language plpgsql security definer set search_path = public as $f$
declare
  v_uid uuid := auth.uid();
  v_ap  text := upper(btrim(p_airport));
  v_bit date := coalesce(p_bit, p_bas);
  v_tavan int := coalesce((select (value #>> '{}')::int from beta_settings
                            where key='talep_kayit_tavani'), 5);
  v_n int; v_id uuid; v_bekleyen int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_bas is null then raise exception 'tarih_zorunlu'; end if;
  if p_bas < current_date then raise exception 'date_in_past'; end if;
  if v_bit < p_bas then raise exception 'invalid_time_range'; end if;
  if v_bit - p_bas > 60 then
    raise exception 'talep_araligi_uzun'
      using hint = 'En fazla 60 gunluk bir aralik birakabilirsin.';
  end if;
  if not exists (select 1 from airports where code = v_ap) then
    raise exception 'unknown_airport';
  end if;

  select count(*) into v_n from talep_kayitlari where user_id = v_uid and aktif;
  if v_n >= v_tavan then
    raise exception 'talep_kayit_tavani'
      using detail = format('%s/%s kayit', v_n, v_tavan),
            hint   = 'Once eski kayitlarindan birini kaldir.';
  end if;

  insert into talep_kayitlari (user_id, airport_code, tarih_bas, tarih_bit)
  values (v_uid, v_ap::char(3), p_bas, v_bit)
  on conflict (user_id, airport_code, tarih_bas, tarih_bit) where aktif
  do update set aktif = true
  returning id into v_id;

  -- 🔴 KULLANICIYA YALNIZ "kaydettim" DEMEK YETMEZ. O anda merak ettiği
  -- şey "ben kaçıncı kişiyim, umut var mı". Aynı aralıkta kaç kişinin
  -- beklediğini geri döndürüyoruz — bu hem dürüst hem motive edici.
  select count(*) into v_bekleyen from talep_kayitlari t
   where t.aktif and t.airport_code = v_ap::char(3)
     and t.tarih_bas <= v_bit and t.tarih_bit >= p_bas;

  return jsonb_build_object('ok', true, 'id', v_id,
                            'bekleyen_kisi', v_bekleyen,
                            'havalimani', v_ap, 'bas', p_bas, 'bit', v_bit);
end $f$;
grant execute on function public.talep_birak(text, date, date) to authenticated;

-- ----------------------------------------------------------------------
-- taleplerim   [etkin kaynak: 247_haber_ver.sql]
-- ----------------------------------------------------------------------
create or replace function public.taleplerim()
returns table(id uuid, airport_code text, tarih_bas date, tarih_bit date,
              bekleyen_kisi int, eslesen_ilan int, created_at timestamptz)
language sql stable security definer set search_path = public as $f$
  select t.id, t.airport_code::text, t.tarih_bas, t.tarih_bit,
         (select count(*)::int from talep_kayitlari o
           where o.aktif and o.airport_code = t.airport_code
             and o.tarih_bas <= t.tarih_bit and o.tarih_bit >= t.tarih_bas),
         (select count(*)::int from availabilities a
           where a.active and a.airport_code = t.airport_code
             and a.avail_date between t.tarih_bas and t.tarih_bit),
         t.created_at
    from talep_kayitlari t
   where t.user_id = auth.uid() and t.aktif
   order by t.tarih_bas;
$f$;
grant execute on function public.taleplerim() to authenticated;

-- ----------------------------------------------------------------------
-- talebi_kaldir   [etkin kaynak: 247_haber_ver.sql]
-- ----------------------------------------------------------------------
create or replace function public.talebi_kaldir(p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $f$
declare v_n int;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  update talep_kayitlari set aktif = false
   where id = p_id and user_id = auth.uid() and aktif;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'talep_bulunamadi'; end if;
  return jsonb_build_object('ok', true);
end $f$;
grant execute on function public.talebi_kaldir(uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- 3) İLAN AÇILINCA BEKLEYENE HABER GİT
-- ----------------------------------------------------------------------------
-- ⚠️ Bildirim çöpü üretmemek için iki fren var: aynı kayda en fazla
-- `talep_bildirim_ara_saat` saatte bir, ve yalnız GÖRÜNÜR (Public)
-- ilanlar için. Bir söz verip onu spam'e çevirmek, hiç söz vermemekten
-- kötüdür.

-- ----------------------------------------------------------------------
-- trg_talep_haber_ver   [etkin kaynak: 247_haber_ver.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_talep_haber_ver()
returns trigger language plpgsql security definer set search_path = public as $f$
declare
  v_ara int := coalesce((select (value #>> '{}')::int from beta_settings
                          where key='talep_bildirim_ara_saat'), 12);
  v_n int := 0;
  r record;
begin
  if not coalesce(new.active, true) then return new; end if;
  if coalesce(new.visibility::text, 'Public') <> 'Public' then return new; end if;

  for r in
    select t.id, t.user_id from talep_kayitlari t
     where t.aktif
       and t.airport_code = new.airport_code
       and new.avail_date between t.tarih_bas and t.tarih_bit
       and t.user_id <> new.host_id
       and (t.son_bildirim_at is null
            or t.son_bildirim_at < now() - make_interval(hours => v_ara))
  loop
    -- 🔴 `'discovery'` yazmistim; `notif_category` enum'unda yok
    -- (requests/sessions/invites/connections/system/safety/credits/ratings).
    -- Bu turda DORDUNCU kez bir enum degerini ezberden yazdim. Katalogdan
    -- okumak zorunda degilim ama BAKMAK zorundayim.
    insert into notifications (user_id, category, title, body, ref_type, ref_id)
    values (r.user_id, 'system',
            'Beklediğin gün için ilan açıldı',
            format('%s · %s — haber ver dediğin aralıkta yeni bir ilan var.',
                   new.airport_code, to_char(new.avail_date, 'DD.MM.YYYY')),
            'availability', new.id);
    update talep_kayitlari set son_bildirim_at = now() where id = r.id;
    v_n := v_n + 1;
  end loop;

  if v_n > 0 then
    raise notice 'talep haberi: % kisiye gonderildi', v_n;
  end if;
  return new;
end $f$;

drop trigger if exists trg_talep_haber on public.availabilities;
create trigger trg_talep_haber
  after insert on public.availabilities
  for each row execute function public.trg_talep_haber_ver();

-- ----------------------------------------------------------------------------
-- 4) ARZ TARAFINA GÖSTERİLECEK KANIT
-- ----------------------------------------------------------------------------
-- Host'a "bu tarihte 14 kişi bekliyor" demek, ilan açma sebebinin
-- kendisi. Bu fonksiyon o cümleyi üretiyor.

-- ----------------------------------------------------------------------
-- talep_yogunlugu   [etkin kaynak: 247_haber_ver.sql]
-- ----------------------------------------------------------------------
create or replace function public.talep_yogunlugu(p_airport text, p_date date)
returns jsonb language sql stable security definer set search_path = public as $f$
  select jsonb_build_object(
    'havalimani', upper(btrim(p_airport)),
    'tarih', p_date,
    'bekleyen', (select count(*) from talep_kayitlari t
                  where t.aktif and t.airport_code = upper(btrim(p_airport))::char(3)
                    and p_date between t.tarih_bas and t.tarih_bit),
    'acik_ilan', (select count(*) from availabilities a
                   where a.active and a.airport_code = upper(btrim(p_airport))::char(3)
                     and a.avail_date = p_date));
$f$;
grant execute on function public.talep_yogunlugu(text, date) to authenticated;

-- ----------------------------------------------------------------------
-- bo_talep_yogunlugu   [etkin kaynak: 247_haber_ver.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_talep_yogunlugu(p_gun int default 45)
returns table(airport_code text, tarih date, bekleyen int, acik_ilan int, aciklik int)
language sql stable security definer set search_path = public as $f$
  with gunler as (
    select t.airport_code, g::date as tarih
      from talep_kayitlari t,
           lateral generate_series(greatest(t.tarih_bas, current_date),
                                   least(t.tarih_bit, current_date + p_gun),
                                   interval '1 day') g
     where t.aktif
  )
  select gu.airport_code::text, gu.tarih, count(*)::int as bekleyen,
         (select count(*)::int from availabilities a
           where a.active and a.airport_code = gu.airport_code and a.avail_date = gu.tarih),
         count(*)::int - (select count(*)::int from availabilities a
                           where a.active and a.airport_code = gu.airport_code
                             and a.avail_date = gu.tarih)
    from gunler gu
   group by gu.airport_code, gu.tarih
   order by 5 desc, 3 desc, 2;
$f$;
revoke execute on function public.bo_talep_yogunlugu(int) from public, anon, authenticated;
grant execute on function public.bo_talep_yogunlugu(int) to service_role;

-- ----------------------------------------------------------------------------
-- 5) RPC YÜZEYİ
