end $$;

-- ----------------------------------------------------------------------
-- baglanti_sohbeti_ac   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.baglanti_sohbeti_ac(p_conn_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $b248$
declare v_uid uuid := auth.uid(); v_cr connection_requests%rowtype; v_ch uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_cr from connection_requests where id = p_conn_id;
  if not found then raise exception 'connection_not_found'; end if;
  if v_uid not in (v_cr.from_id, v_cr.to_id) then raise exception 'not_participant'; end if;
  if v_cr.status <> 'accepted' then
    raise exception 'baglanti_kabul_edilmedi'
      using hint = 'Sohbet, karsi taraf kabul edince acilir.';
  end if;
  -- Engellenmis ciftte sohbet acilmaz: kabul eski olabilir, engel yenidir.
  if public.is_blocked_pair(v_cr.from_id, v_cr.to_id) then
    raise exception 'blocked_pair';
  end if;
  select id into v_ch from chat_channels where connection_id = p_conn_id;
  if v_ch is null then
    insert into chat_channels (connection_id, kind, created_at)
    values (p_conn_id, 'companion', now())
    returning id into v_ch;
  end if;
  return jsonb_build_object('ok', true, 'channel_id', v_ch);
end $b248$;

grant execute on function public.baglanti_sohbeti_ac(uuid) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §3 — BAĞLANTI İSTEKLERİ (madde 9)
--
-- Gokberk: "baglanti kur ile gonderilen baglanti istekleri ana sayfada
-- gozukmuyor. Tanis ekraninda Kesfet ve Baglantilar yaninda bir
-- 'Baglanti istekleri' tabi da olusturabiliriz."
--
-- Olctum, iki ayri boslugu var:
--  (a) GONDERDIGIN istegi gosteren HICBIR sorgu yok. Meet ekrani yalniz
--      `to_id = ben and status = pending` cekiyor. Gonderen taraf icin
--      istek gonderdikten sonra ORTADA HICBIR IZ KALMIYOR.
--  (b) Ana sayfada `home_connections` var ama o yalniz KABUL EDILMIS
--      baglantilarin sohbetlerini donduruyor. Bekleyen hicbir yerde yok.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- baglanti_istekleri   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.baglanti_istekleri()
returns table(
  id uuid, yon text, peer_id uuid, peer_name text, peer_photo text,
  peer_badge text, peer_score int, peer_profession text,
  intent text, intro text, durum text,
  gonderildi_at timestamptz, yanit_at timestamptz,
  channel_id uuid,
  -- Bir baglanti istegi bir ILANDAN dogmus olabilir (kural sorusu degil,
  -- duz baglanti da avail_id tasiyabiliyor). Baglami tasimak, karti
  -- "bir isim ve bir kelime" olmaktan cikarir.
  salon text, airport_code text, avail_date date
)
language plpgsql stable security definer set search_path = public as $c248$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  return query
  select cr.id,
         case when cr.from_id = v_uid then 'giden' else 'gelen' end,
         case when cr.from_id = v_uid then cr.to_id else cr.from_id end,
         coalesce(nullif(btrim(p.name),''), 'Yolcu'),
         p.photo_url, ts.badge, ts.score, p.profession,
         coalesce(cr.intent,'connect'),
         nullif(btrim(coalesce(cr.intro,'')),''),
         cr.status::text,
         cr.created_at, cr.responded_at,
         ch.id,
         coalesce(nullif(btrim(a.lounge_name),''), l.name),
         a.airport_code::text, a.avail_date
    from connection_requests cr
    left join profiles p
      on p.user_id = case when cr.from_id = v_uid then cr.to_id else cr.from_id end
    left join trust_scores ts
      on ts.user_id = case when cr.from_id = v_uid then cr.to_id else cr.from_id end
    left join availabilities a on a.id = cr.avail_id
    left join lounges l on l.id = a.lounge_id
    left join chat_channels ch on ch.connection_id = cr.id
   where (cr.from_id = v_uid or cr.to_id = v_uid)
     -- Kural sorulari AYRI bir akis (sorularim) — burada tekrar etmiyoruz.
     and coalesce(cr.intent,'connect') <> 'kural_sorusu'
     -- Bekleyenler her zaman; yanitlanmislar 7 gun. Sonsuza kadar biriken
     -- liste, listenin kendisini oldurur.
     and (cr.status = 'pending'
          or coalesce(cr.responded_at, cr.created_at) > now() - interval '7 days')
     and not public.is_blocked_pair(v_uid,
           case when cr.from_id = v_uid then cr.to_id else cr.from_id end)
   -- 🔴 `(cr.status = 'pending') desc` YAZMIŞTIM; nöbetçi yakaladı.
   -- `status` kolonu NULL olabilir ve NULL = 'pending' ifadesi NULL döner;
   -- DESC sıralamada NULL EN BAŞA çıkar. Yani durumu bilinmeyen bir kayıt,
   -- bekleyen isteklerin de üstünde listenin tepesine otururdu.
   -- `coalesce` ile ifade artık her zaman boolean.
   order by (coalesce(cr.status::text,'') = 'pending') desc, cr.created_at desc
   limit 50;
end $c248$;

grant execute on function public.baglanti_istekleri() to authenticated;

-- ---- REDDEDİLDİKTEN SONRA TEKRAR GÖNDERME ----
-- 🔴 KENDİ BAŞIMA BULDUĞUM ARIZA (Gokberk'in listesinde YOK).
-- `connection_requests` tablosunda UNIQUE (from_id, to_id) var — DURUMDAN
-- BAGIMSIZ. `send_connection` ise yalniz 'pending'/'accepted' varsa
-- engelliyor. Yani REDDEDILMIS bir istek varsa:
--     fonksiyon "gonderebilirsin" diyor → insert 23505 ile patliyor
--     → kullaniciya ham Postgres metni dusuyor.
-- Ayrica bu, kural sorusu ile baglanti istegini birbirine KILITLIYOR:
-- bir host'a kural sorusu sorup reddedildiysen, o kisiyle bir daha ASLA
-- baglanti kuramiyorsun. Iki ayri urun akisi tek satiri paylasiyor.
--
-- Cozum: ayni yonde reddedilmis satir varsa YENIDEN ISLET (update), ama
-- 7 GUN SOGUMA SURESIYLE. Kilidi acarken tacizi acmiyoruz — mevcut
-- durumun tek erdemi kazara olan bu korumaydi, bilerek koruyoruz.

-- ----------------------------------------------------------------------
-- ilan_ozeti   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.ilan_ozeti(p_avail_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $i248$
declare v_uid uuid := auth.uid(); v_a availabilities%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_a from availabilities where id = p_avail_id and active;
  if not found then return jsonb_build_object('ok', false); end if;
  -- Gizli ilanin ozeti verilmez: keste gorunmeyen bir ilanin saatini
  -- sizdirmak, gorunurluk ayarini anlamsiz kilar.
  if v_a.visibility = 'Hidden' and v_a.host_id <> v_uid then
    return jsonb_build_object('ok', false);
  end if;
  return jsonb_build_object(
    'ok', true,
    'id', v_a.id,
    'airport_code', v_a.airport_code,
    'avail_date', v_a.avail_date,
    'time_from', v_a.time_from,
    'time_to', v_a.time_to,
    'lounge_name', v_a.lounge_name,
    'host_id', v_a.host_id);
end $i248$;

grant execute on function public.ilan_ozeti(uuid) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §5 — DEĞERLENDİRMELER (madde 11)
--
-- Gokberk: "ana sayfadaki agirlaman nasil gecti alani daraltilip
-- genisletilemiyor... Simdi degile tiklaninca da bir daha bulunamiyor.
-- Profil tabinda Oturum gecmisi ile Bildirimler arasina Degerlendirmeler
-- diye bir alan olsun; bekleyen / tamamlanan iki sekme."
--
-- `pending_ratings()` BEKLEYENI veriyor; VERILMIS degerlendirmeyi
-- donduren hicbir fonksiyon yok. "Tamamlanan" sekmesi icin veri lazim.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- degerlendirmelerim   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.degerlendirmelerim()
returns table(
  durum text,                 -- 'bekleyen' | 'tamamlanan'
  session_id uuid, request_id uuid,
  other_id uuid, other_name text,
  salon text, airport_code text, avail_date date,
  time_from time, time_to time,
  completed_at timestamptz,
  i_am_host boolean,
  rating_id uuid, puan smallint, yorum text, verildi_at timestamptz
)
language plpgsql stable security definer set search_path = public as $d248$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  return query
  select
    case when rt.id is null then 'bekleyen' else 'tamamlanan' end,
    s.id, r.id,
    case when r.host_id = v_uid then r.guest_id else r.host_id end,
    coalesce(nullif(btrim(p.name),''), 'Yolcu'),
    coalesce(nullif(btrim(a.lounge_name),''), l.name, a.airport_code::text),
    a.airport_code::text, a.avail_date, a.time_from, a.time_to,
    s.completed_at,
    (r.host_id = v_uid),
    rt.id, rt.score, nullif(btrim(coalesce(rt.comment,'')),''), rt.created_at
  from sessions s
  join requests r on r.id = s.request_id
  left join availabilities a on a.id = r.avail_id
  left join lounges l on l.id = a.lounge_id
  left join profiles p
    on p.user_id = case when r.host_id = v_uid then r.guest_id else r.host_id end
  left join ratings rt
    on rt.session_id = s.id and rt.rater_id = v_uid
 where s.status = 'completed'
   and (r.host_id = v_uid or r.guest_id = v_uid)
 order by (rt.id is null) desc, s.completed_at desc nulls last
 limit 60;
end $d248$;

grant execute on function public.degerlendirmelerim() to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §6 — KREDİ PAKETLERİ (madde 1)
--
-- Gokberk: "cuzdan sayfasinda kredi paketleri yer aliyor, DOLARLA
-- satiliyor ve 20000 kredi vs satiyoruz. Bunu dogru sekilde duzenle...
-- uyelik plani disinda ek bir satin alma gibi konumlandirilmali."
--
-- Haklı ve rakam saçmaydı: app'te PACKS sabiti "3000 / 8000 / 20000 kredi,
-- $4.99 / $11.99 / $24.99" diyordu. Oysa BU URUNDE:
--     1 istek = 1 kredi   (request_credit_cost)
--     Yolcu (ucretsiz) ayda 1 kredi · Sik Ucan 99₺/6 · Kahya 249₺/12
-- 20.000 kredi = 20.000 lounge istegi. Rakam bir oyun para birimi gibi
-- yazilmis; urunun kendi ekonomisiyle ILGISIZ.
--
-- FİYATLAMA KARARI VE GEREKÇESİ:
--   abonelikte kredi basina: 99/6 = 16,5₺ · 249/12 = 20,75₺
--   pakette kredi basina   : 39 · 33 · 29,8₺
-- Paket HER ZAMAN abonelikten pahali. Bu bilerek: paket bir ALTERNATIF
-- degil, TAKVIYE. Ucuz olsaydi abonelik anlamsizlasirdi ve tekrar eden
-- gelirimizi kendi elimizle bozardik.
--
-- Fiyatlar TABLODA, kodda degil: BO'dan degistirilebilir olmasi sart.
-- Uygulamaya gomulu fiyat, her degisiklikte yeni bir build demektir.
-- ════════════════════════════════════════════════════════════════════════

create table if not exists kredi_paketleri (
  kod           text primary key,
  ad            text not null,
  kredi         int  not null check (kredi between 1 and 50),
  fiyat_try     int  not null check (fiyat_try > 0),
  sira          int  not null default 0,
  aktif         boolean not null default true,
  one_cikan     boolean not null default false,
  aciklama      text,
  guncellendi   timestamptz not null default now()
);

alter table kredi_paketleri enable row level security;
drop policy if exists kredi_paketleri_oku on kredi_paketleri;
create policy kredi_paketleri_oku on kredi_paketleri for select using (true);

insert into kredi_paketleri (kod, ad, kredi, fiyat_try, sira, one_cikan, aciklama) values
  ('tek',  'Tek hak',   1, 39,  1, false, 'Bu ay bir istek daha göndermek için.'),
  ('uclu', 'Üç hak',    3, 99,  2, true,  'Aynı anda birkaç ilana başvurmak için.'),
  ('altili','Altı hak', 6, 179, 3, false, 'Yoğun bir seyahat dönemi için.')
on conflict (kod) do update
  set ad = excluded.ad, kredi = excluded.kredi, fiyat_try = excluded.fiyat_try,
      sira = excluded.sira, one_cikan = excluded.one_cikan,
      aciklama = excluded.aciklama, guncellendi = now();

-- 🔴 NÖBETÇİ DEĞİL, KURAL: paket kredisi ABONELIK kredisinden UCUZ OLAMAZ.
-- Bu bir fiyat tercihi degil, is modelinin tasiyici kolonu. Tabloya
-- yazilabilir olmasi, yanlis yazilabilir olmasi demek — kapiyi koyuyorum.

-- ----------------------------------------------------------------------
-- trg_kredi_paketi_kapisi   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_kredi_paketi_kapisi() returns trigger
language plpgsql as $tkp$
declare v_en_ucuz_abonelik numeric;
begin
  select min(price_try::numeric / nullif(monthly_credits,0))
    into v_en_ucuz_abonelik
    from plan_catalog where aktif and price_try > 0 and monthly_credits > 0;
  if v_en_ucuz_abonelik is not null
     and (new.fiyat_try::numeric / new.kredi) <= v_en_ucuz_abonelik then
    raise exception 'paket_abonelikten_ucuz'
      using detail = format('paket %s₺/kredi · en ucuz abonelik %s₺/kredi',
                            round(new.fiyat_try::numeric / new.kredi, 2),
                            round(v_en_ucuz_abonelik, 2)),
            hint = 'Paket takviyedir, alternatif degil. Abonelikten ucuz bir paket '
                || 'tekrar eden geliri kendi elimizle bozar.';
  end if;
  return new;
end $tkp$;

drop trigger if exists trg_kredi_paketi_kapisi on kredi_paketleri;
create trigger trg_kredi_paketi_kapisi
  before insert or update on kredi_paketleri
  for each row execute function public.trg_kredi_paketi_kapisi();

-- ----------------------------------------------------------------------
-- kredi_paketleri   [etkin kaynak: 248_duzenleme_baglanti_degerlendirme.sql]
-- ----------------------------------------------------------------------
create or replace function public.kredi_paketleri()
returns jsonb
language plpgsql stable security definer set search_path = public as $kp248$
declare v_uid uuid := auth.uid(); v_bal int; v_plan text; v_plan_kredi int; v_plan_fiyat int;
begin
  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  select u.plan::text into v_plan from users u where u.id = v_uid;
  select pc.monthly_credits, pc.price_try into v_plan_kredi, v_plan_fiyat
    from plan_catalog pc where pc.plan::text = v_plan;

  return jsonb_build_object(
    'bakiye', v_bal,
    'plan', v_plan,
    'plan_aylik_kredi', v_plan_kredi,
    -- Cuzdan ekraninin en onemli cumlesi: "1 kredi = 1 lounge istegi".
    -- Rakamin BIRIMI yoksa rakam bilgi degildir.
    'kredi_bedeli', public.request_credit_cost(v_uid),
    'paketler', coalesce((
      select jsonb_agg(jsonb_build_object(
               'kod', k.kod, 'ad', k.ad, 'kredi', k.kredi,
               'fiyat_try', k.fiyat_try,
               'kredi_basina', round(k.fiyat_try::numeric / k.kredi, 1),
               'one_cikan', k.one_cikan, 'aciklama', k.aciklama)
             order by k.sira)
        from kredi_paketleri k where k.aktif), '[]'::jsonb),
    -- Abonelige yonlendirme, paketin yaninda ve DURUST: paket pahali
    -- oldugu icin pahali oldugunu biz soyluyoruz.
    'abonelik_ipucu', (
      select jsonb_build_object('plan', pc.ad, 'fiyat_try', pc.price_try,
                                'aylik_kredi', pc.monthly_credits,
                                'kredi_basina', round(pc.price_try::numeric / pc.monthly_credits, 1))
        from plan_catalog pc
       where pc.aktif and pc.price_try > 0 and pc.monthly_credits > 0
       order by pc.price_try::numeric / pc.monthly_credits asc limit 1)
  );
end $kp248$;

grant execute on function public.kredi_paketleri() to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §7 — YÜZEY KAYITLARI
-- 🔴 "Yazip cagirmamak, yazmamaktan kotudur" nobetcisi (v2.94) bu
-- kayitlardan besleniyor. Buraya yazilan her satir, app'te GERCEKTEN
-- cagrilmak zorunda; cagrilmazsa `npm run verify` kirmizi yanar.
-- ════════════════════════════════════════════════════════════════════════

insert into rpc_client_surface (fn_name, client, note) values
  ('baglanti_istekleri',  'app', 'Tanis > Istekler sekmesi + ana sayfa paneli (madde 9)'),
  ('baglanti_sohbeti_ac', 'app', 'Sorduklarim/Istekler karti > sohbeti ac (madde 15)'),
  ('ilan_ozeti',          'app', 'Seyahat ekle on doldurma (madde 8)'),
  ('degerlendirmelerim',  'app', 'Profil > Degerlendirmeler ekrani (madde 11)'),
  ('kredi_paketleri',     'app', 'Cuzdan > kredi paketleri, TRY (madde 1)')
on conflict (fn_name) do update set client = excluded.client, note = excluded.note;

-- ════════════════════════════════════════════════════════════════════════
-- §8 — NÖBETÇİ
-- Kod METNI degil DAVRANIS olcuyor (243'te ogrendigim ders). Butun
-- yazmalar geri alinan bir alt islemin icinde — bir nobetci, nobet
-- tuttugu seye zarar veremez (240'ta ogrendigim ders).
-- ════════════════════════════════════════════════════════════════════════

do $n248$
declare
  v_h text[] := '{}';
  v_host uuid; v_guest uuid; v_ap text; v_lounge uuid;
  v_a1 uuid; v_a2 uuid; v_d date;
  v_r jsonb; v_cnt int; v_min int; v_cap int;
begin
  begin
    select code into v_ap from airports order by code limit 1;
    select l.id into v_lounge from lounges l
      where l.airport_code = v_ap::char(3) and l.active limit 1;

    -- ══════════════════════════════════════════════════════════════════
    -- 🔴 26 AĞUSTOS 2026 — BU NÖBETÇİ GÖKBERK'İN VERİTABANINDA ÇÖKTÜ,
    --    BENİMKİNDE GEÇMİŞTİ.
    --
    --    Hata:  update or delete on table "chat_channels" violates
    --           foreign key constraint "messages_channel_id_fkey"
    --
    --    Sebep zinciri ölçüldü:
    --      connection_requests  --ON DELETE CASCADE-->  chat_channels
    --      chat_channels        --CASCADE YOK       -->  messages
    --    Nöbetçi sahneyi temizlemek için `delete from connection_requests`
    --    diyordu. Onun kanallarında GERÇEK MESAJ vardı; benimkinde yoktu.
    --
    --    Ama asıl kusur o delete değil: NÖBETÇİNİN OYUNCULARI ÖDÜNÇ
    --    ALMASIYDI. `select id from users limit 1` demek, ölçümü
    --    veritabanındaki ilk satırın kim olduğuna bağlamaktır — o kişi
    --    admin olabilir, silinmiş olabilir, karşı tarafla geçmişi
    --    olabilir. (Bu projede aynı sınıfa iki kez düştüm: "kapıyı
    --    anahtarı olan biriyle denedim".)
    --
    --    Nöbetçi artık KENDİ OYUNCULARINI KURUYOR. Geçmişleri yok,
    --    dolayısıyla silinecek bir şey de yok: `delete` cümlesi tamamen
    --    kalktı. Her şey geri alınan alt işlemin içinde.
    --
    -- 🆕 SINIF: "OYUNCULARINI SAHNEDE BULDUĞU KİŞİLERDEN SEÇEN BİR ÖLÇÜM,
    --    O SAHNENİN GEÇMİŞİNİ DE ÖLÇER — VE EN DOLU VERİTABANINDA EN
    --    KÖTÜ SONUCU VERİR."
    -- ══════════════════════════════════════════════════════════════════
    insert into auth.users (id, email)
    values (gen_random_uuid(), 'n248-host-'  || gen_random_uuid() || '@nobetci.test')
    returning id into v_host;
    insert into auth.users (id, email)
    values (gen_random_uuid(), 'n248-guest-' || gen_random_uuid() || '@nobetci.test')
    returning id into v_guest;

    if v_host is null or v_guest is null then
      v_h := v_h || 'nobetci kendi oyuncularini kuramadi (auth.users yazilamiyor)'::text;
    end if;
    -- Köprü tetikleyicisi (004) profiles/verifications/trust satirlarini
    -- kurar; kurmadiysa ölçüm zaten anlamsiz — burada görelim.
    if not exists (select 1 from profiles where user_id = v_host) then
      v_h := v_h || 'auth kaydi acildi ama profiles satiri olusmadi (004 kopru tetikleyicisi)'::text;
    end if;

    update users set role = 'host' where id = v_host;
    v_d := current_date + 12;

    -- Kapasite beyanini BILEREK bosaltiyoruz: madde 14'un sahnesi bu.
    update profiles set guest_capacity = null where user_id = v_host;

    insert into availabilities (host_id, lounge_id, airport_code, avail_date,
                                time_from, time_to, slots, filled, active,
                                visibility, min_trust)
    values (v_host, v_lounge, v_ap::char(3), v_d, time '10:00', time '16:00',
            2, 0, true, 'Public', 60)
    returning id into v_a1;

    -- Gokberk'in ekranindaki durum: AYNI SAATTE ikinci bir ilan. Kural
    -- sonradan konuldu, veri once vardi.
    insert into availabilities (host_id, lounge_id, airport_code, avail_date,
                                time_from, time_to, slots, filled, active, visibility)
    values (v_host, v_lounge, v_ap::char(3), v_d, time '10:00', time '16:00',
            2, 0, true, 'Public')
    returning id into v_a2;

    perform set_config('request.jwt.claims',
      json_build_object('sub', v_host, 'role','authenticated')::text, true);

    -- (1) MADDE 14'ÜN TA KENDİSİ: yalniz ucus numarasi degisiyor.
    --     Kapasite NULL, ayni saatte ikinci ilan VAR. Eskiden iki ayri
    --     sebeple patliyordu.
    begin
      v_r := public.update_availability(p_id => v_a1, p_flight => 'TK1234');
      if coalesce(v_r ->> 'ok','') <> 'true' then
        v_h := v_h || 'sadece-ucus duzenlemesi ok donmedi'::text;
      end if;
    exception when others then
      v_h := v_h || ('sadece-ucus duzenlemesi HALA PATLIYOR: ' || sqlerrm)::text;
    end;

    -- (2) GÜVEN EŞİĞİ SESSİZCE SİLİNMİYOR (hata sinifi 3)
    begin
      perform public.update_availability(p_id => v_a1, p_visibility => 'all');
      select min_trust into v_min from availabilities where id = v_a1;
      if coalesce(v_min,0) <> 60 then
        v_h := v_h || format('gorunurluk degisince guven esigi %s oldu (60 olmaliydi)', v_min)::text;
      end if;
    exception when others then
      v_h := v_h || ('gorunurluk duzenlemesi patladi: ' || sqlerrm)::text;
    end;

    -- (3) TERS YÖN — kapasite kurali HALA CALISIYOR: slot ARTIRMAK,
    --     beyan yokken reddedilmeli. Kapiyi acmadigimizi kanitlar.
    begin
      perform public.update_availability(p_id => v_a1, p_slots => 3::smallint);
      v_h := v_h || 'kapasite beyani YOKKEN slot artirildi — kapi tamamen acilmis'::text;
    exception when others then
      if sqlerrm not like '%no_access_source%' then
        v_h := v_h || ('slot artirma beklenen hatayi vermedi: ' || sqlerrm)::text;
      end if;
    end;

    -- (4) TERS YÖN — cakismayi KOTULESTIREN duzenleme hala reddedilmeli.
    begin
      insert into availabilities (host_id, lounge_id, airport_code, avail_date,
                                  time_from, time_to, slots, filled, active, visibility)
      values (v_host, v_lounge, v_ap::char(3), v_d + 1, time '08:00', time '09:00',
              1, 0, true, 'Public');
      -- a1'i o saate tasimak, YENI bir cakisma yaratir.
      perform public.update_availability(p_id => v_a1, p_date => v_d + 1,
                                         p_from => time '08:00', p_to => time '09:00');
      v_h := v_h || 'YENI cakisma yaratan duzenleme gecti — kural tamamen kalkmis'::text;
    exception when others then
      if sqlerrm not like '%cakisiyor%' then
        v_h := v_h || ('cakisma testi beklenmeyen hata: ' || sqlerrm)::text;
      end if;
    end;

    -- (5) MADDE 15 — sorularim SOHBET KANALINI donduruyor mu
    if not exists (
      select 1 from information_schema.columns
       where table_schema='public' and table_name='sorularim') then
      -- fonksiyon; kolon adlarini pg_proc'tan dogrula
      if position('channel_id' in pg_get_function_result(
           (select oid from pg_proc where proname='sorularim'
             and pronamespace='public'::regnamespace))) = 0 then
        v_h := v_h || 'sorularim() hala channel_id dondurmuyor (madde 15)'::text;
      end if;
    end if;

    -- (6) MADDE 9 — baglanti istekleri IKI YONU de goruyor mu
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_guest, 'role','authenticated')::text, true);
    -- (delete kalktı — oyuncular yeni, geçmişleri yok. Yukarıdaki
    --  26 Ağustos notuna bak.)
    update verifications set email_verified = true where user_id = v_guest;
    insert into verifications (user_id, email_verified) values (v_guest, true)
      on conflict (user_id) do update set email_verified = true;
    perform public.send_connection(v_host, 'coffee', 'Merhaba');
    select count(*) into v_cnt from public.baglanti_istekleri() where yon = 'giden';
    if v_cnt < 1 then
      v_h := v_h || 'GONDERDIGIM baglanti istegi hicbir yerde gorunmuyor (madde 9)'::text;
    end if;
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_host, 'role','authenticated')::text, true);
    select count(*) into v_cnt from public.baglanti_istekleri() where yon = 'gelen';
    if v_cnt < 1 then
      v_h := v_h || 'GELEN baglanti istegi baglanti_istekleri()nde yok'::text;
    end if;

    -- (7) REDDEDİLDİKTEN SONRA TEKRAR — soguma suresi calisiyor mu
    update connection_requests set status = 'declined', responded_at = now()
     where from_id = v_guest and to_id = v_host;
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_guest, 'role','authenticated')::text, true);
    begin
      perform public.send_connection(v_host, 'coffee', 'Tekrar');
      v_h := v_h || 'reddedilen istek ANINDA tekrar gonderilebildi — taciz kapisi'::text;
    exception when others then
      if sqlerrm not like '%soguma%' then
        v_h := v_h || ('soguma testi beklenmeyen hata: ' || sqlerrm)::text;
      end if;
    end;
    -- soguma dolunca GECMELI (yoksa eski "asla" durumunu korumus oluruz)
    update connection_requests set responded_at = now() - interval '10 days'
     where from_id = v_guest and to_id = v_host;
    begin
      perform public.send_connection(v_host, 'coffee', 'Tekrar');
    exception when others then
      v_h := v_h || ('soguma dolduktan sonra da gonderilemedi: ' || sqlerrm)::text;
    end;

    -- (8) MADDE 1 — paket abonelikten ucuz olamaz
    begin
      insert into kredi_paketleri (kod, ad, kredi, fiyat_try)
      values ('bedava_gibi', 'Test', 10, 50);
      v_h := v_h || 'abonelikten UCUZ paket eklenebildi — is modeli kapisi yok'::text;
    exception when others then
      if sqlerrm not like '%paket_abonelikten_ucuz%' then
        v_h := v_h || ('paket kapisi beklenmeyen hata: ' || sqlerrm)::text;
      end if;
    end;

    -- (9) MADDE 11 — degerlendirmelerim iki durumu da tanimliyor mu
    if position('tamamlanan' in coalesce(
         (select prosrc from pg_proc where proname='degerlendirmelerim'
           and pronamespace='public'::regnamespace), '')) = 0 then
      v_h := v_h || 'degerlendirmelerim() tamamlanan durumunu uretmiyor'::text;
    end if;

    raise exception 'GERI_AL_248';
  exception when others then
    if sqlerrm <> 'GERI_AL_248' then
      v_h := v_h || ('olcum coktu: ' || sqlerrm);
    end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '248 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '248 OK · sadece-ucus duzenlemesi geciyor · guven esigi korunuyor · kapasite kapisi duruyor · baglanti istekleri iki yonlu · paket kapisi calisiyor';
end $n248$;

commit;

select '248 KURULDU' as sonuc,
       (select count(*) from kredi_paketleri where aktif) as kredi_paketi,
       (select count(*) from rpc_client_surface
         where fn_name in ('baglanti_istekleri','baglanti_sohbeti_ac','ilan_ozeti',
                           'degerlendirmelerim','kredi_paketleri')) as yeni_yuzey;

-- ════════════════════════════════════════════════════════════════════════
-- §9 — CÜZDAN TANITIM CÜMLESİ HÂLÂ "3 KREDİ" DİYORDU (madde 10)
--
-- Gokberk: "cuzdaninda X misafir hakki bulunuyor tanitim ekraninda hala
-- 1 agirlamaya 3 kredi kazanilacagi yaziyor."
--
-- Olctum, dogru. Cumle SQL 238'de `host_wallet` govdesine METIN olarak
-- gomulmus:
--     'Agirladigin her kisi sana 3 kredi birakiyor: hakkin olmayan bir
--      salonda uc kez misafir olursun.'
-- SQL 246 ekonomiyi degistirdi (host_credit_per_session 3 → 1) ama bu
-- cumleye dokunmadi. Yani sunucu 1 kredi yaziyor, urun 3 kredi vaat
-- ediyordu. Kullanicinin gorecegi ilk celiski bu olurdu ve gelen ilk
-- soru "hani 3 krediydi?" olacakti.
--
-- 🆕 SINIF: "BİR ORANI DEĞİŞTİRİRKEN O ORANI CÜMLEYLE ANLATAN METNİ
-- DEĞİŞTİRMEZSEN, ÜRÜN KENDİ KURALINI YALANLAR."
--
-- Cozum iki katmanli:
--  (1) Cumleyi AYARDAN uret — sabit yazma. Oran bir daha degisirse cumle
--      kendiliginden dogru kalir.
--  (2) Nobetci: `host_wallet` govdesindeki sayi ile beta_settings'teki
--      oran AYNI olmak zorunda. Ayrilirlarsa kurulum durur.
-- ════════════════════════════════════════════════════════════════════════

do $w248$
declare
  v_tanim text;
  v_oran  int;
  v_yeni  text;
  v_eski_sayi text;
begin
  select (value #>> '{}')::int into v_oran
    from beta_settings where key = 'host_credit_per_session';
  if v_oran is null then
    raise notice '248 §9: host_credit_per_session ayari yok — cumleye DOKUNULMADI.';
    return;
  end if;

  -- 🔴 İLK YAZIMIM `prosrc` OKUYUP BAŞLIĞI KENDİM YAZDI VE ORTALIĞI YAKTI.
  --

-- ----------------------------------------------------------------------
-- host_daveti   [etkin kaynak: 249_is_modeli_ve_soguk_ag.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_daveti()
returns jsonb
language plpgsql stable security definer set search_path = public as $hd249$
declare
  v_uid uuid := auth.uid();
  v_n int; v_esik int; v_plan text; v_gun int; v_plan_ad text; v_fiyat int;
  v_basamaklar jsonb;
begin
  if v_uid is null then return jsonb_build_object('ok', false); end if;

  select count(*) into v_n from sessions s join requests r on r.id = s.request_id
   where r.host_id = v_uid and s.status = 'completed';

  v_esik := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_sessions'), 2);
  v_plan := coalesce((select  value #>> '{}'      from beta_settings where key='host_free_upgrade_plan'), 'sik_ucan');
  v_gun  := coalesce((select (value #>> '{}')::int from beta_settings where key='host_free_upgrade_days'), 30);
  select coalesce(nullif(btrim(ad),''), plan::text), price_try
    into v_plan_ad, v_fiyat
    from plan_catalog where plan::text = v_plan;

  -- Merdivenin TAMAMI, ödülleriyle. Katalogdan geliyor — burada sabit
  -- metin yok, çünkü BO'dan mertebe değişince bu ekran da değişmeli.
  select jsonb_agg(jsonb_build_object(
           'code', t.code, 'ad', t.ad, 'agirlama', t.min_oturum,
           'aciklama', t.aciklama,
           'siralama_ek', t.siralama_ek,
           'one_cikar_saat', t.one_cikar_saat,
           'istek_bedava', t.istek_bedava,
           'ulasildi', (v_n >= t.min_oturum))
         order by t.min_oturum)
    into v_basamaklar
    from host_tiers t;

  return jsonb_build_object(
    'ok', true,
    'agirlamam', v_n,
    'basamaklar', coalesce(v_basamaklar, '[]'::jsonb),
    'plan_hediyesi', jsonb_build_object(
        'esik', v_esik, 'gun', v_gun,
        'plan', v_plan, 'plan_adi', v_plan_ad, 'aylik_try', v_fiyat,
        'kalan_agirlama', greatest(0, v_esik - v_n)),
    -- 🔴 EN ÖNEMLİ CÜMLE. Host'a "iyilik yap" demiyoruz; "kimi ağırlayacağını
    -- SEN seçiyorsun" diyoruz. Ağırlamak bir bağış değil, bir seçim.
    -- Bu çerçeve ürünün elindeki en güçlü ve en ucuz koz: veriyi zaten
    -- topluyoruz (meslek, amaç, aynı uçuş, güven puanı) ama host'a
    -- "seçiyorsun" dilini hiç kurmadık.
    'cerceve', 'Kimseyi kabul etmek zorunda değilsin. Başvuranları görür, '
            || 'mesleğine, seyahat amacına ve güven puanına bakar, '
            || 'yanında kimin oturacağına sen karar verirsin.');
end $hd249$;

grant execute on function public.host_daveti() to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §3 — HAVALİMANI NABZI (A2)
--
-- Gokberk: "hiçbir yerde 'bu havalimanında şu an kaç host var' sayısı bir
-- hedef olarak takip edilmiyor... BO ve gerekiyorsa app'e gerekli
-- geliştirmeyi yap."
--
-- Ürünün TEK sağlık göstergesi bu: iki taraflı ve zamana sıkışmış bir
-- pazarda tek soru "bu havalimanında bugün buluşma olabilir mi".
--
-- Üç sayı, üçü de aynı pencerede: arz (canlı ilan / açık slot),
-- talep (bekleyen istek + haber-ver kaydı) ve ikisinin oranı.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- havalimani_nabzi   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.havalimani_nabzi(p_gun integer DEFAULT 14)
 RETURNS TABLE(airport_code text, sehir text, canli_ilan integer, acik_slot integer, host_sayisi integer, bekleyen_istek integer, talep_kaydi integer, aktif_seyahat integer, tamamlanan_oturum integer, doluluk numeric, karsilanma numeric, durum text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_son date := current_date + greatest(1, coalesce(p_gun,14));
begin
  return query
  with arz as (
    select a.airport_code::text as ap,
           count(*)::int                                   as ilan,
           coalesce(sum(greatest(0, a.slots - coalesce(a.filled,0))),0)::int as slot,
           coalesce(sum(a.slots),0)::int                    as toplam_slot,
           coalesce(sum(coalesce(a.filled,0)),0)::int       as dolu,
           count(distinct a.host_id)::int                   as hostlar
      from availabilities a
     where a.active and a.avail_date between current_date and v_son
       and a.visibility <> 'Hidden'
       and not public.test_hesabi_gizli_mi(a.host_id)   -- 301/§3
     group by a.airport_code
  ), talep as (
    select a.airport_code::text as ap, count(*)::int as bekleyen
      from requests r join availabilities a on a.id = r.avail_id
     where r.status = 'pending' and a.avail_date between current_date and v_son
     group by a.airport_code
  ), haber as (
    select t.airport_code::text as ap, count(*)::int as kayit
      from talep_kayitlari t
     where t.aktif and t.tarih_bit >= current_date and t.tarih_bas <= v_son
     group by t.airport_code
  ), seyahat as (
    select v.airport_code::text as ap, count(*)::int as gezi
      from visits v
     where v.visit_date between current_date and v_son
       and not public.test_hesabi_gizli_mi(v.user_id)   -- 301/§3
     group by v.airport_code
  ), oturum as (
    select a.airport_code::text as ap, count(*)::int as bitmis
      from sessions s join requests r on r.id = s.request_id
      join availabilities a on a.id = r.avail_id
     where s.status = 'completed'
     group by a.airport_code
  )
  select ap.code::text,
         coalesce(ap.city, ap.name),
         coalesce(arz.ilan,0), coalesce(arz.slot,0), coalesce(arz.hostlar,0),
         coalesce(talep.bekleyen,0), coalesce(haber.kayit,0), coalesce(seyahat.gezi,0),
         coalesce(oturum.bitmis,0),
         case when coalesce(arz.toplam_slot,0) = 0 then null
              else round(arz.dolu::numeric / arz.toplam_slot, 2) end,
         -- 🔴 SIFIRA BÖLME DEĞİL, ANLAMSIZ ORAN KORUMASI:
         -- talep yoksa "karşılanma" diye bir şey yoktur; 0 yazmak
         -- "hiç karşılamıyoruz" gibi okunurdu. null = ölçülemedi.
         case when (coalesce(talep.bekleyen,0) + coalesce(haber.kayit,0)) = 0 then null
              else round(coalesce(arz.slot,0)::numeric
                         / (coalesce(talep.bekleyen,0) + coalesce(haber.kayit,0)), 2) end,
         case when coalesce(arz.hostlar,0) = 0 then 'soguk'
              when coalesce(arz.hostlar,0) < 3 then 'isiniyor'
              else 'canli' end
    from airports ap
    left join arz     on arz.ap     = ap.code::text
    left join talep   on talep.ap   = ap.code::text
    left join haber   on haber.ap   = ap.code::text
    left join seyahat on seyahat.ap = ap.code::text
    left join oturum  on oturum.ap  = ap.code::text
   where coalesce(arz.ilan,0) > 0 or coalesce(talep.bekleyen,0) > 0
      or coalesce(haber.kayit,0) > 0 or coalesce(seyahat.gezi,0) > 0
   order by coalesce(arz.hostlar,0) desc, coalesce(haber.kayit,0) desc, ap.code;
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §5 · create_availability (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.create_availability(p_lounge_id uuid, p_airport text, p_date date, p_from time without time zone, p_to time without time zone, p_slots integer, p_flight text DEFAULT NULL::text, p_visibility text DEFAULT 'all'::text, p_carrier text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb; v_id uuid;
  v_pg uuid; v_kaynak text; v_kod text; v_ad text;
begin
  -- ══════════════════════════════════════════════════════════════════
  -- 🔴 261 — ROL KAPISI. ILAN ACMAK ARTIK KIMSEYI SESSIZCE HOST YAPMAZ.
  --
  -- Kapi EN USTTE: `_base` cagrilmadan once. Boylece `_base` icindeki
  -- 055 terfisi (`update users set role='host'`) ULASILAMAZ hale
  -- geliyor — buraya gelen zaten host.
  --
  -- Host olmanin TEK yolu artik acik niyet: `rolumu_sec('host')`
  -- (uygulamadaki "Host ol" dugmesi) ya da onaylanmis host basvurusu.
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from users u where u.id = auth.uid() and u.role = 'host')
     and not exists (select 1 from host_applications ha
                      where ha.user_id = auth.uid() and ha.status = 'approved')
  then
    raise exception 'not_a_host';
  end if;
  -- 🔴 301/§5: KENDİ İLANIYLA ÇAKIŞAN İLAN açılabiliyordu (tam akış testi,
  -- 10–13 varken 12–15 GEÇTİ). `update_availability` bunu 'kendi_ilanlarin_
  -- cakisiyor' ile zaten reddediyordu — açma yolu reddetmiyordu. Aynı kişi
  -- aynı saatte iki salonda olamaz; ikinci ilana kabul edilen misafir kapıda kalır.
  if exists (select 1 from availabilities a
              where a.host_id = auth.uid() and a.active
                and a.avail_date = p_date
                and a.time_from < p_to and p_from < a.time_to) then
    raise exception 'kendi_ilanlarin_cakisiyor'
      using hint = 'Bu saatte başka bir ilanın var. Önce onu kaldır ya da saatleri ayır.';
  end if;
  -- ══════════════════════════════════════════════════════════════════

  -- Butun kapilar, kotalar, bildirimler _base zincirinde.
  -- Buraya tek bir is kaldi: SONUCU ANLATMAK.
  v := public.create_availability_base(
         p_lounge_id, p_airport, p_date, p_from, p_to, p_slots,
         p_flight, p_visibility, p_carrier);

  v_id := nullif(v ->> 'id', '')::uuid;
  if v_id is null then
    return v;   -- _base bir sey dondurmediyse uydurmuyoruz
  end if;

  select a.program_id, a.program_source, p.code, p.name
    into v_pg, v_kaynak, v_kod, v_ad
    from availabilities a
    left join lounge_programs p on p.id = a.program_id
   where a.id = v_id;

  return v || jsonb_build_object(
    'program_id',     v_pg,
    'program_kodu',   v_kod,
    'program_adi',    v_ad,
    'program_kaynagi', coalesce(v_kaynak, 'bilinmiyor'),
    'program_notu', case
      when v_pg is null then
        'Bu ilan bir kart programına bağlanamadı: hak beyanınız bu salonun kabul listesiyle eşleşmiyor. İlan yayında; yalnız sağlayıcı raporunda "program bilinmeyen" sayılacak.'
      when coalesce(v_kaynak, '') = 'turetildi' then
        format('Bu ilan "%s" programı altında sayılacak. Bu bir ÇIKARIM: doğrulanmış hak beyanınızdan türetildi, sizin beyanınız değil.', coalesce(v_ad, v_kod))
      else
        format('Bu ilan "%s" programı altında sayılacak (beyan).', coalesce(v_ad, v_kod))
      end);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §8 · seyahat_sil (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.seyahat_sil(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_sahip uuid;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select user_id into v_sahip from visits where id = p_id;
  if v_sahip is null then raise exception 'visit_not_found'; end if;
  if v_sahip <> v_uid then raise exception 'not_your_visit'; end if;
  -- 240'ın sözleşme kilidi: bu seyahate dayanan aktif başvuru varsa silinmez.
  -- 🔴 301/§8: fonksiyon SAYI döndürüyor; `if <sayı> then` 0/1 için
  -- tesadüfen çalışıyor ('0'/'1' geçerli boolean metni), 2+ açık başvuruda
  -- "invalid input syntax for type boolean: "2"" ile patlıyordu (tam akış testi).
  if public.seyahate_bagli_basvuru(p_id) > 0 then
    raise exception 'seyahat_silinemez_basvuru_var';
  end if;
  delete from visits where id = p_id;
  return jsonb_build_object('ok', true);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §9 · blok_gecmisi_kapat (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.blok_gecmisi_kapat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- 🔴 301/§9: 204'ten beri bekleyen istek KAPANIYOR ama tutulan kredi
  -- İADE EDİLMİYORDU (tam akış testi: defterde yalnız `request_hold:-1`).
  -- Engelleme uygulamadan yapılamadığı için bu hiç görünmemişti; 301 §1
  -- engellemeyi açınca canlı hataya dönüşecekti. Artık her kapanan istek
  -- iade yolundan geçiyor (tekrar iadeyi `istek_kredisi_iade` kendisi önler).
  declare v_r record;
  begin
    for v_r in
      update requests set status = 'cancelled', responded_at = now()
       where status = 'pending'
         and ((guest_id = new.blocker and host_id = new.blocked)
           or (guest_id = new.blocked and host_id = new.blocker))
      returning id
    loop
      perform public.istek_kredisi_iade(v_r.id, 'request_refund');
    end loop;
  end;

  -- ⚠️ `connection_status` = pending | accepted | declined | blocked.
  -- İlk yazışımda 'rejected' yazdım — enum'da YOK, 22P02 aldım. Enum'un
  -- kendisinde zaten 'blocked' var ve burada 'declined'dan DAHA DOĞRU:
  -- kullanıcı reddetmedi, engelledi. Sebep kayıtta kalsın.
  update connection_requests set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((from_id = new.blocker and to_id = new.blocked)
       or (from_id = new.blocked and to_id = new.blocker));

  update invites set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((host_id = new.blocker and guest_id = new.blocked)
       or (host_id = new.blocked and guest_id = new.blocker));

  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ
-- ════════════════════════════════════════════════════════════════════════
do $z301$
declare v_n int; v_l text;
begin
  select count(*), string_agg(p.proname, ', ') into v_n, v_l
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('engelle','engeli_kaldir','engellediklerim','gelmedi_bildir','gelmedi_esigi')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '301 §Z: authenticated çağıramıyor: %', v_l; end if;
  select count(*) into v_n from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '301 §Z: PUBLIC''e açık % fonksiyon (300 §A2 geriledi)', v_n; end if;
  if position('test_hesabi_gizli_mi' in (select prosrc from pg_proc where proname = 'is_visible')) = 0 then
    raise exception '301 §Z: is_visible yamasız';
  end if;
  if not exists (select 1 from pg_trigger where tgname = 'trg_mesaj_engel') then
    raise exception '301 §Z: mesaj engel tetikleyicisi yok';
  end if;
  raise notice '301 §Z: kapılar ölçüldü';
end $z301$;

select '301 OK — engelleme · gelmedi · test hesabı gizleme · rehber sayacı' as sonuc;

-- ----------------------------------------------------------------------
-- bo_havalimani_nabzi   [etkin kaynak: 249_is_modeli_ve_soguk_ag.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_havalimani_nabzi(p_gun int default 14)
returns jsonb
language plpgsql stable security definer set search_path = public as $bhn249$
declare v_satirlar jsonb; v_ozet jsonb;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;

  select jsonb_agg(to_jsonb(x)) into v_satirlar
    from public.havalimani_nabzi(p_gun) x;

  select jsonb_build_object(
      'gun', greatest(1, coalesce(p_gun,14)),
      'havalimani', count(*),
      'canli_havalimani', count(*) filter (where x.durum = 'canli'),
      'isinan',           count(*) filter (where x.durum = 'isiniyor'),
      'soguk',            count(*) filter (where x.durum = 'soguk'),
      'toplam_host',      coalesce(sum(x.host_sayisi),0),
      'toplam_acik_slot', coalesce(sum(x.acik_slot),0),
      'toplam_bekleyen',  coalesce(sum(x.bekleyen_istek),0),
      'toplam_talep',     coalesce(sum(x.talep_kaydi),0))
    into v_ozet
    from public.havalimani_nabzi(p_gun) x;

  return jsonb_build_object('ozet', v_ozet, 'satirlar', coalesce(v_satirlar,'[]'::jsonb));
end $bhn249$;

grant execute on function public.bo_havalimani_nabzi(int) to service_role;

-- ════════════════════════════════════════════════════════════════════════
-- §4 — SOĞUK AĞDA İSTEK KREDİ HARCAMASIN (A4)
--
-- Gokberk: "zaten yaptık sanki bir şeyler. Şu anki hali ok değil mi?"
--
-- 🔴 HAYIR. ÖLÇTÜM:
--     request_credit_cost(uid) = case when <Konsiyerj mertebesi> then 0 else 1 end
-- Yani ağın boş olup olmadığına HİÇ BAKMIYOR. Tek indirim yolu 15 ağırlama
-- yapmış olmak — ki tam da ağ boşken kimse ağırlayamıyor.
--
-- Erken dönemde bu şu demek: host olmadığı için cevap alamayan kullanıcıdan
-- ücret alıyoruz. Ürünün en kırılgan anında, en yanlış tarafı cezalandırıyor.
--
-- Yeni kural: isteğin gittiği havalimanında CANLI HOST SAYISI eşiğin
-- altındaysa istek ÜCRETSİZ. Defter satırı yine yazılıyor (0 ile) —
-- "bu istek soğuk ağ indirimiyle bedavaydı" bilgisi kaybolmamalı.
-- ════════════════════════════════════════════════════════════════════════

insert into beta_settings (key, value) values
  ('soguk_ag_host_esigi', to_jsonb(3)),
  ('bayat_istek_saat',    to_jsonb(72))
on conflict (key) do nothing;

-- İmza DEĞİŞİYOR (p_avail eklendi) → önce DROP. `create or replace` yeni bir
-- aşırı yükleme yaratır ve tek argümanlı çağrılar belirsizleşirdi.
-- (248 §9'da imzayı ezberden yazıp bir fonksiyonu ikizleyerek öğrendim.)
drop function if exists public.request_credit_cost(uuid);

-- ----------------------------------------------------------------------
-- bayat_istekleri_iade_et   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.bayat_istekleri_iade_et()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saat int := coalesce((select (value #>> '{}')::int from beta_settings
                           where key = 'bayat_istek_saat'), 72);
  r record; v_bal int; v_kapatilan int := 0; v_iade int := 0;
begin
  perform public.motor_yazimi_ac();

  for r in
    select req.id, req.guest_id
      from requests req
      join availabilities a on a.id = req.avail_id
     where req.status = 'pending'
       and req.responded_at is null
       -- 🔴 300/B4: UTC tarihi değil, havalimanının yerel saati. Eskiden
       -- saati geçmiş bir ilanın bekleyen isteği ertesi UTC gününe kadar
       -- açık kalıyordu (kredi tutulu, host cevap veremez).
       and (public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()
            or req.created_at < now() - make_interval(hours => v_saat))
  loop
    -- Satır satır: bir satır bir iş kuralına takılırsa toplu iş çökmesin.
    begin
      update requests
         set status = 'cancelled',
             responded_at = now(),
             decision_note = coalesce(decision_note,
               'Host süresinde yanıtlamadı — istek otomatik kapatıldı (274).')
       where id = r.id and status = 'pending';
      if not found then continue; end if;
      v_kapatilan := v_kapatilan + 1;

      -- İADE yalnız gerçekten kredi düşülmüşse ve daha önce iade
      -- edilmemişse. `request_free_tier` satırları burada kasıtla dışarıda:
      -- harcanmayan kredi iade edilmez.
      if exists (select 1 from credit_ledger cl
                  where cl.ref_id = r.id and cl.reason in ('request_hold','invite_hold') and cl.delta < 0)
         and not exists (select 1 from credit_ledger cl
                          where cl.ref_id = r.id and cl.reason = 'request_stale_refund')
      then
        select coalesce(sum(delta), 0) into v_bal from credit_ledger where user_id = r.guest_id;
        insert into credit_ledger (user_id, delta, reason, ref_id, balance_after, note)
        values (r.guest_id, public.tutulan_kredi(r.id), 'request_stale_refund', r.id,
                v_bal + public.tutulan_kredi(r.id),
                format('%s saat içinde yanıt gelmedi', v_saat));
        v_iade := v_iade + 1;
      end if;

      insert into notifications (user_id, category, title, body, ref_type, ref_id)
      values (r.guest_id, 'requests', 'İsteğin kapandı',
              format('Başvurun %s saat içinde yanıtlanmadı. Artık yeni istek gönderebilirsin.', v_saat),
              'request', r.id);
    exception when others then
      raise notice '274: istek % kapatilamadi: %', r.id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object('ok', true, 'kapatilan', v_kapatilan,
                            'iade_edilen', v_iade, 'esik_saat', v_saat);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B5 · create_request_impl  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.create_request_impl(p_avail_id uuid, p_type text DEFAULT 'lounge'::text, p_intro text DEFAULT NULL::text, p_idem text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare v_acik boolean; v_kalan int; v_tavan int;
      begin
        -- (a) ACİL DURDURMA
        select f.enabled into v_acik from feature_flags f where f.key = 'marketplace';
        if not coalesce(v_acik, true) then
          raise exception 'marketplace_closed';
        end if;

        -- (b) AYNI ANDA AÇIK İSTEK TAVANI — 029'da tohumlanmış ama
        -- yedi ay boyunca hiçbir yerde uygulanmamış bir eşik.
        select value into v_tavan from rule_thresholds where key = 'max_active_requests';
        select count(*) into v_kalan from requests
         where guest_id = auth.uid() and status = 'pending';
        if v_kalan >= coalesce(v_tavan, 5) then
          raise exception 'too_many_active_requests';
        end if;

        -- 🔴 300/B5: iki kapı, ikisi de ÖLÇÜLDÜ (SEED8 §5):
        --  · aynı ilana ikinci başvuru ham bir kısıt hatası döndürüyordu:
        --    "duplicate key value violates unique constraint …" — uygulama
        --    bunu "Bir şeyler ters gitti" diye gösteriyordu.
        --  · tarih bugünse ama SAAT geçmişse başvuru kabul ediliyordu.
        --  · 🔴 AYNI İLANA YENİDEN İSTEK SESSİZCE HİÇBİR ŞEY YAPMIYORDU.
        --    Uygulama tekrar-deneme anahtarını `uid:ilan` olarak üretiyor; iptal
        --    ettiğin (ya da reddedilen) isteğin anahtarı aynı kalıyordu. Yeni
        --    istek bu anahtarla gelince `preflag` ESKİ, KAPALI isteği
        --    `{"ok":true,"idempotent":true}` diye döndürüyordu — ekran "gönderildi"
        --    diyor, host hiçbir şey görmüyor. (Ölçüldü: ilk → iptal → tekrar =
        --    aynı id, durum `cancelled`.)
        --    Kapalı bir isteğin anahtarı artık serbest bırakılıyor: çift dokunuş
        --    korunur (açık istek), yeni deneme yeni istek olur.
        -- 🆕 SINIF: "BİR TEKRAR-DENEME ANAHTARI, KORUDUĞU İŞLEMDEN UZUN
        -- YAŞARSA, SONRAKİ HER GERÇEK İSTEĞİ BİR TEKRAR SANIR."
        if p_idem is not null then
          update requests set idempotency_key = null
           where idempotency_key = p_idem and guest_id = auth.uid()
             and status not in ('pending', 'accepted');
        end if;
        -- Tekrar deneme anahtarı (p_idem) ile gelen AÇIK istek dokunulmadan geçer.
        if p_idem is null or not exists (select 1 from requests
                                          where idempotency_key = p_idem and guest_id = auth.uid()) then
          if exists (select 1 from requests where guest_id = auth.uid() and avail_id = p_avail_id
                                              and status in ('pending','accepted')) then
            raise exception 'already_requested';
          end if;
          if exists (select 1 from availabilities a where a.id = p_avail_id
                      and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now()) then
            raise exception 'availability_expired';
          end if;
        end if;

        return public.create_request_impl_preflag(p_avail_id, p_type, p_intro, p_idem);
      end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §B6 · trg_bakiye_negatife_dusemez  (canlı tanım + 300 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.trg_bakiye_negatife_dusemez()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_bal int;
begin
  if new.delta >= 0 then return new; end if;
  if new.reason like 'paid_guest_thanks_reversal:%' or new.reason like 'admin%' then
    return new;
  end if;

  -- 🔴 300/B6: KİLİT TETİKLEYİCİNİN İÇİNDE. 299/B2 kilidi dört yola
  -- koymuştu; `misafir_hakki_hediye_et` beşinciydi ve kilitsizdi. İki
  -- eşzamanlı hediye aynı 3 krediyi iki kez harcayabiliyordu (ölçüldü:
  -- ikinci oturum birincinin commit'ini beklemeden geçti).
  -- Kilit burada olunca YOL SAYISI önemsizleşiyor: bakiyeyi eksilten her
  -- satır, aynı kullanıcının diğer eksiltmesini commit'e kadar bekler ve
  -- sonra GÜNCEL toplamı okur.
  perform pg_advisory_xact_lock(hashtextextended('kredi:' || new.user_id::text, 0));
  select coalesce(sum(delta), 0) into v_bal
    from credit_ledger where user_id = new.user_id;

  if v_bal + new.delta < 0 then
    raise exception 'insufficient_credits'
      using detail = format('kullanıcı %s: bakiye %s, denenen %s (%s)',
                            new.user_id, v_bal, new.delta, new.reason),
            hint   = 'Bu satır bakiyeyi negatife düşürürdü; 299/B1 reddetti.';
  end if;
  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ. Açık kalan kapı varsa DUR.
-- ════════════════════════════════════════════════════════════════════════
do $z300$
declare v_n int; v_liste text;
begin
  -- A1: kilitli olanlar authenticated/anon tarafından çağrılamaz
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('change_plan','kredi_akis_raporu','anonymized_users',
                       'host_kota_durumu','doluluk_reddi_sayisi','oturum_kural_hedefi',
                       'kural_guncelligi','access_options_for_user','bo_slot_asimlari')
     and (has_function_privilege('authenticated', p.oid, 'execute')
          or has_function_privilege('anon', p.oid, 'execute'));
  if v_n > 0 then raise exception '300 §Z/A1: hâlâ açık: %', v_liste; end if;

  -- A2: PUBLIC'e açık SECURITY DEFINER fonksiyon kalmadı
  select count(distinct p.oid), string_agg(distinct p.proname, ', ') into v_n, v_liste
    from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef
     and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '300 §Z/A2: PUBLIC''e açık % fonksiyon: %', v_n, v_liste; end if;

  -- A2: küresel varsayılan gerçekten yazıldı mı?
  if not exists (select 1 from pg_default_acl d
                  where d.defaclnamespace = 0 and d.defaclobjtype = 'f'
                    and d.defaclrole = 'postgres'::regrole) then
    raise exception '300 §Z/A2: küresel varsayılan yetki kaydı yok';
  end if;

  -- Uygulamanın çağırdığı beş fonksiyon authenticated'da KALDI mı?
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('cancel_availability','binis_karti_kaydet','ilani_yeniden_yayinla',
                       'hikaye_davetini_ertele','kesifte_gorun','profil_karti',
                       'create_request','respond_request','confirm_session')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '300 §Z: uygulama fonksiyonu KAPANDI: %', v_liste; end if;

  -- A3 / B6 tetikleyicileri yerinde mi?
  if not exists (select 1 from pg_trigger where tgname = 'trg_visit_0_beyan_temizle') then
    raise exception '300 §Z/A3: tetikleyici yok';
  end if;
  if position('pg_advisory_xact_lock' in
       (select prosrc from pg_proc where proname = 'trg_bakiye_negatife_dusemez')) = 0 then
    raise exception '300 §Z/B6: kredi kilidi tetikleyicide yok';
  end if;
  if position('availability_expired' in
       (select prosrc from pg_proc where proname = 'respond_request')) = 0 then
    raise exception '300 §Z/B1: kabul kapısı yok';
  end if;
  if position('already_requested' in
       (select prosrc from pg_proc where proname = 'create_request_impl')) = 0 then
    raise exception '300 §Z/B5: mükerrer başvuru kapısı yok';
  end if;

  raise notice '300 §Z: bütün kapılar ölçüldü — kapalı';
end $z300$;

select '300 OK — uçtan uca denetim bulguları kapatıldı' as sonuc;

-- ----------------------------------------------------------------------
-- kabin_sorulmali_mi   [etkin kaynak: 249_is_modeli_ve_soguk_ag.sql]
-- ----------------------------------------------------------------------
create or replace function public.kabin_sorulmali_mi(p_lounge_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $ks249$
declare v_venue uuid; v_var int; v_ornek text;
begin
  if p_lounge_id is null then
    return jsonb_build_object('sor', false, 'neden', 'salon_secilmedi');
  end if;
  select l.venue_id into v_venue from lounges l where l.id = p_lounge_id;

  select count(*), max(coalesce(r.notes, r.blocked_reason))
    into v_var, v_ornek
    from lounge_guest_rules r
   where r.cabin_class is not null
     and (r.venue_id is null or r.venue_id = v_venue);

  if coalesce(v_var,0) = 0 then
    return jsonb_build_object('sor', false, 'neden', 'bu_salonda_kabin_kurali_yok');
  end if;
  return jsonb_build_object(
    'sor', true, 'kural_sayisi', v_var,
    'neden', 'bu_salonda_kabin_misafir_hakkini_degistiriyor',
    'ornek', v_ornek);
end $ks249$;

grant execute on function public.kabin_sorulmali_mi(uuid) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §7 — YENİ FİKİR: AĞIRLAYAN HOST, TANIDIĞINA MİSAFİR HAKKI HEDİYE EDER
--
-- Gokberk: "başka ve ilgi çekici önerilerin varsa öner"
--
-- GEREKÇE: bu kitlenin gerçekten değer verdiği şey KREDİ DEĞİL, CÖMERT
-- GÖRÜNEBİLMEK. Zaten lounge'a girebilen bir insana "sana bir giriş hakkı
-- verdik" demek zayıf; "arkadaşına bir giriş hakkı verebilirsin" demek
-- güçlü. Statü, harcanabildiğinde statüdür.
--
-- MALİYETİ BİZE SIFIR: hediye edilen şey host'un ZATEN kazandığı kredi.
-- Yeni kredi basmıyoruz, var olanı devredilebilir kılıyoruz.
--
-- 🔴 SUİSTİMALE KARŞI ÜÇ KAPI:
--   (a) yalnız AĞIRLAYARAK kazanılmış kredi hediye edilebilir
--       (satın alınan kredi devredilemez → kredi ticareti doğmaz)
--   (b) alıcı, gönderenin KABUL EDİLMİŞ bağlantısı olmalı
--       (rastgele kullanıcıya kredi püskürtmek yok)
--   (c) günlük tavan
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- misafir_hakki_hediye_et   [etkin kaynak: 249_is_modeli_ve_soguk_ag.sql]
-- ----------------------------------------------------------------------
create or replace function public.misafir_hakki_hediye_et(p_to uuid, p_adet int default 1, p_not text default null)
returns jsonb
language plpgsql security definer set search_path = public as $mh249$
declare
  v_uid uuid := auth.uid();
  v_kazanilan int; v_hediye_edilen int; v_bakiye int; v_bugun int; v_bal int; v_ad text;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_to = v_uid then raise exception 'kendine_hediye_olmaz'; end if;
  if coalesce(p_adet,0) < 1 or p_adet > 3 then raise exception 'gecersiz_adet'; end if;
  if public.is_blocked_pair(v_uid, p_to) then raise exception 'blocked_pair'; end if;

  -- (b) kabul edilmiş bağlantı şartı
  if not exists (
    select 1 from connection_requests
     where status = 'accepted'
       and ((from_id = v_uid and to_id = p_to) or (from_id = p_to and to_id = v_uid))
  ) then
    raise exception 'baglanti_yok'
      using hint = 'Misafir hakkini yalniz baglantilarina hediye edebilirsin.';
  end if;

  -- (a) yalnız ağırlayarak kazanılan kredi devredilebilir
  select coalesce(sum(delta),0) into v_kazanilan
    from credit_ledger where user_id = v_uid and reason = 'hosted_session' and delta > 0;
  select coalesce(-sum(delta),0) into v_hediye_edilen
    from credit_ledger where user_id = v_uid and reason = 'hak_hediye_verildi';
  if (v_kazanilan - v_hediye_edilen) < p_adet then
    raise exception 'agirlayarak_kazanilan_kredi_yetersiz'
      using detail = format('agirlayarak %s kazandin, %s hediye ettin', v_kazanilan, v_hediye_edilen),
            hint = 'Yalniz agirlayarak kazandigin haklar hediye edilebilir; satin alinan kredi devredilemez.';
  end if;

  -- Bakiye de yetmeli (hediye ettiğin hakkı harcamış olabilirsin)
  select coalesce(sum(delta),0) into v_bakiye from credit_ledger where user_id = v_uid;
  if v_bakiye < p_adet then raise exception 'insufficient_credits'; end if;

  -- (c) günlük tavan
  select count(*) into v_bugun from credit_ledger
   where user_id = v_uid and reason = 'hak_hediye_verildi' and created_at > now() - interval '24 hours';
  if v_bugun >= 3 then
    raise exception 'gunluk_hediye_tavani' using hint = 'Gunde en fazla 3 hediye gonderebilirsin.';
  end if;

  select coalesce(nullif(btrim(name),''), 'Bir yolcu') into v_ad from profiles where user_id = v_uid;

  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after, note)
  values (v_uid, -p_adet, 'hak_hediye_verildi', p_to, v_bakiye - p_adet, left(coalesce(p_not,''),120));

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = p_to;
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after, note)
  values (p_to, p_adet, 'hak_hediye_alindi', v_uid, v_bal + p_adet, left(coalesce(p_not,''),120));

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (p_to, 'credits', 'Sana misafir hakkı hediye edildi ✦',
          format('%s sana %s misafir hakkı gönderdi.%s', v_ad, p_adet,
                 case when coalesce(btrim(p_not),'') <> '' then ' "' || left(p_not,100) || '"' else '' end),
          'user', v_uid);

  insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
  values (v_uid, 'credit.gift', 'users', p_to, jsonb_build_object('adet', p_adet));

  return jsonb_build_object('ok', true, 'adet', p_adet, 'kalan_hediye_hakki', v_kazanilan - v_hediye_edilen - p_adet);
end $mh249$;

grant execute on function public.misafir_hakki_hediye_et(uuid, int, text) to authenticated;

-- Ekranın "kaç hakkım var" diye sorabilmesi için:

-- ----------------------------------------------------------------------
-- hediye_edilebilir_hakkim   [etkin kaynak: 249_is_modeli_ve_soguk_ag.sql]
-- ----------------------------------------------------------------------
create or replace function public.hediye_edilebilir_hakkim()
returns jsonb
language plpgsql stable security definer set search_path = public as $hh249$
declare v_uid uuid := auth.uid(); v_kaz int; v_ver int; v_bugun int;
begin
  if v_uid is null then return jsonb_build_object('adet', 0); end if;
  select coalesce(sum(delta),0) into v_kaz from credit_ledger
   where user_id = v_uid and reason = 'hosted_session' and delta > 0;
  select coalesce(-sum(delta),0) into v_ver from credit_ledger
   where user_id = v_uid and reason = 'hak_hediye_verildi';
  select count(*) into v_bugun from credit_ledger
   where user_id = v_uid and reason = 'hak_hediye_verildi' and created_at > now() - interval '24 hours';
  return jsonb_build_object(
    'adet', greatest(0, v_kaz - v_ver),
    'agirlayarak_kazanilan', v_kaz,
    'hediye_edilen', v_ver,
    'bugun_kalan', greatest(0, 3 - v_bugun));
end $hh249$;

grant execute on function public.hediye_edilebilir_hakkim() to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §8 — YÜZEY
-- ════════════════════════════════════════════════════════════════════════

insert into rpc_client_surface (fn_name, client, note) values
  ('host_daveti',              'app', 'Host olsan ne kazanirsin — merdiven tirmanmadan once (A1)'),
  ('havalimani_nabzi',         'app', 'Bu havalimaninda kac host var (A2)'),
  ('kabin_sorulmali_mi',       'app', 'Kabin sorusu yalniz kabin kurali olan salonda sorulur (B2)'),
  ('misafir_hakki_hediye_et',  'app', 'Agirlayarak kazanilan hakki baglantina hediye et (A1)'),
  ('hediye_edilebilir_hakkim', 'app', 'Hediye edilebilir hak sayaci')
on conflict (fn_name) do update set client = excluded.client, note = excluded.note;

-- ════════════════════════════════════════════════════════════════════════
-- §9 — NÖBETÇİ · davranış ölçer, geri alınan alt işlemde
-- ════════════════════════════════════════════════════════════════════════

do $n249$
declare
  v_h text[] := '{}';
  v_host uuid; v_guest uuid; v_ap text; v_lounge uuid; v_a uuid; v_r jsonb;
  v_bedel int; v_n int; v_c jsonb; v_alici uuid; v_gonderen uuid;
begin
  begin
    select code into v_ap from airports order by code limit 1;
    select l.id into v_lounge from lounges l where l.airport_code = v_ap::char(3) and l.active limit 1;
    select id into v_host from users limit 1;

    -- 🔴 AKTÖRLER SEÇİLİR, VERİ DEĞİŞTİRİLMEZ.
    -- Eski hâl "hiç ağırlamamış kişi" koşulunu, seçtiği kişinin
    -- OTURUMLARINI SİLEREK kuruyordu. `ratings.session_id` ve
    -- `reports.session_id` cascade'siz (NO ACTION) — yani puanlanmış
    -- bir oturumu olan bir kullanıcı seçildiği anda ölçüm, tam da
    -- `availabilities` silmede aldığımız hatanın aynısını alırdı.
    -- Koşulu kurmanın doğru yolu veriyi bozmak değil, koşulu ZATEN
    -- SAĞLAYAN bir kaydı seçmek.
    select u.id into v_guest
      from users u
     where u.id <> v_host
       and not exists (select 1 from sessions s join requests r on r.id = s.request_id
                        where r.host_id = u.id)
     limit 1;
    if v_guest is null then
      -- Böyle bir kullanıcı yoksa bu ölçüm YAPILAMAZ; uydurmak yerine
      -- söylüyoruz. "Ölçemedim" demek, yanlış ölçmekten iyidir.
      select id into v_guest from users where id <> v_host limit 1;
      raise notice '249: hic agirlamamis kullanici yok — merdiven olcumu atlandi';
    end if;

    -- (1) A1 — merdiven, HİÇ AĞIRLAMAMIŞ kişiye de görünmeli
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_guest, 'role','authenticated')::text, true);
    v_r := public.host_standing();
    if coalesce(v_r ->> 'karsilik_cumlesi','') !~ 'İlk ağırlaman' then
      v_h := v_h || 'hic agirlamamis kisiye merdiven gosterilmiyor'::text;
    end if;
    if coalesce(v_r #>> '{plan_hediyesi,esik}','') = '' then
      v_h := v_h || 'host_standing plan hediyesini dondurmuyor'::text;
    end if;
    v_r := public.host_daveti();
    if jsonb_array_length(coalesce(v_r -> 'basamaklar','[]'::jsonb)) < 2 then
      v_h := v_h || 'host_daveti merdiven basamaklarini dondurmuyor'::text;
    end if;

    -- (2) A4 — SOĞUK AĞDA İSTEK BEDAVA
    --
    -- 🔴 BU ÖLÇÜM GÖKBERK'İN VERİTABANINDA ÇÖKTÜ:
    --     "update or delete on table availabilities violates foreign key
    --      constraint requests_avail_id_fkey on table requests"
    --
    -- Eski hâli, ölçüme temiz bir havalimanı hazırlamak için O HAVALİMANININ
    -- BÜTÜN İLANLARINI SİLİYORDU. Boş bir veritabanında sorunsuz çalışır;
    -- gerçek veride o ilanlara bağlı istekler var ve `requests.avail_id`
    -- NOT NULL + cascade'siz. Yani ölçüm, ölçtüğü sistemin verisini
    -- silmeye çalışıp kendi kendine çarptı.
    --
    -- Asıl kusur "cascade eksik" değil: BİR NÖBETÇİ ÜRETİM VERİSİNE
    -- DOKUNMAMALI. Geri alma (rollback) bir güvenlik ağıdır, izin değil —
    -- blok yarıda kesilirse ya da biri bu SQL'i işlem dışında çalıştırırsa
    -- silinen gerçek satırlar geri gelmez.
    --
    -- 🆕 SINIF: "BİR ÖLÇÜM, İSTEDİĞİ KOŞULU VAR OLAN VERİYİ SİLEREK
    -- KURUYORSA, O ÖLÇÜM BİR RİSKTİR — KOŞULU KENDİ VERİSİNİ YARATARAK
    -- KURMALIDIR."
    --
    -- Artık ölçüm KENDİ havalimanını yaratıyor: hiçbir gerçek satıra
    -- dokunulmuyor, hiçbir şey silinmiyor. (Blok yine `GERI_AL_249` ile
    -- geri alınıyor; yani bu satırlar da kalıcı olmuyor.)
    insert into airports (code, name, city, country, timezone)
    values ('ZZT', '249 ölçüm havalimanı', 'Ölçüm', 'TR', 'Europe/Istanbul')
    on conflict (code) do nothing;
    insert into lounges (airport_code, name, terminal, access_types, active)
    values ('ZZT', '249 ölçüm salonu', 'T1', '{}', true)
    returning id into v_lounge;
    v_ap := 'ZZT';

    insert into availabilities (host_id, lounge_id, airport_code, avail_date,
                                time_from, time_to, slots, filled, active, visibility)
    values (v_host, v_lounge, 'ZZT', current_date + 5, time '10:00', time '14:00',
            2, 0, true, 'Public')
    returning id into v_a;

    v_bedel := public.request_credit_cost(v_guest, v_a);
    if v_bedel <> 0 then
      v_h := v_h || format('soguk agda (1 host) istek bedeli %s — 0 olmaliydi', v_bedel)::text;
    end if;

    -- (3) TERS YÖN — ağ ısınınca bedel geri gelmeli. Aksi hâlde kredi
    --     ekonomisini kalıcı olarak kapatmış oluruz.
    for v_n in 1..4 loop
      insert into availabilities (host_id, lounge_id, airport_code, avail_date,
                                  time_from, time_to, slots, filled, active, visibility)
      select u.id, v_lounge, 'ZZT', current_date + 5, time '10:00', time '14:00',
             2, 0, true, 'Public'
        from users u where u.id <> v_guest
        order by u.id offset v_n limit 1;
    end loop;
    v_bedel := public.request_credit_cost(v_guest, v_a);
    if v_bedel <> 1 then
      v_h := v_h || format('ag isindiginda bedel %s — 1 olmaliydi (indirim kalici olmus)', v_bedel)::text;
    end if;

    -- (4) A2 — nabız gerçekten sayıyor mu
    -- Ölçüm havalimanında 5 ilan var (biri soğuk testinden, dördü ısıtma
    -- turundan); nabız onu görmek ZORUNDA. Gerçek havalimanına bakmıyoruz
    -- çünkü orada ilan olup olmadığı veritabanına göre değişir — ve
    -- veriye bağlı bir nöbetçi, bir gün sessizce yanlış cevap verir.
    select count(*) into v_n from public.havalimani_nabzi(14) where airport_code = 'ZZT';
    if v_n < 1 then
      v_h := v_h || 'havalimani_nabzi ilan olan havalimanini hic dondurmedi'::text;
    end if;
    select host_sayisi into v_n from public.havalimani_nabzi(14) where airport_code = 'ZZT';
    if coalesce(v_n,0) < 1 then
      v_h := v_h || 'havalimani_nabzi host saymiyor'::text;
    end if;

    -- (5) B2 — kabin sorusu yalnız kabin kuralı olan salonda
    v_c := public.kabin_sorulmali_mi(null);
    if coalesce(v_c ->> 'sor','') <> 'false' then
      v_h := v_h || 'salon secilmemisken kabin soruluyor'::text;
    end if;

    -- (6) A1 yeni fikir — hediye kapıları
    perform set_config('request.jwt.claims',
      json_build_object('sub', v_host, 'role','authenticated')::text, true);
    begin
      -- Bağlantı YOK → reddedilmeli.
      -- Bağlantıyı SİLMİYORUZ (silmek `chat_channels`i cascade ile
      -- götürür): bağlantısı OLMAYAN bir alıcı seçiyoruz.
      select u.id into v_alici
        from users u
       where u.id <> v_host
         and not exists (select 1 from connection_requests c
                          where (c.from_id = v_host and c.to_id = u.id)
                             or (c.from_id = u.id   and c.to_id = v_host))
       limit 1;
      if v_alici is null then
        -- 🔴 "ÖLÇEMEDİM" İLE "GEÇTİ" AYNI ŞEY DEĞİL. Uygun aktör yoksa
        -- beklenen hatayı KENDİM fırlatmak, kapının kapalı olduğunu
        -- kanıtlamaz — yalnız testi yeşile boyar. Onun için burada
        -- açıkça "ölçülemedi" deniyor.
        raise notice '249: baglantisiz alici yok — hediye kapisi 1 OLCULEMEDI';
        raise exception 'baglanti_yok';
      end if;
      perform public.misafir_hakki_hediye_et(v_alici, 1);
      v_h := v_h || 'baglanti olmadan hediye gonderilebildi'::text;
    exception when others then
      if sqlerrm not like '%baglanti_yok%' then
        v_h := v_h || ('hediye baglanti testi beklenmeyen hata: ' || sqlerrm)::text;
      end if;
    end;
    begin
      -- Bağlantı VAR ama ağırlayarak kazanılmış kredi YOK → reddedilmeli.
      -- Kredi defterini SİLMİYORUZ (gerçek kredi geçmişi): ağırlayarak
      -- kredi kazanMAMIŞ bir gönderici seçip ona bağlantı kuruyoruz.
      select u.id into v_gonderen
        from users u
       where u.id <> v_guest
         and not exists (select 1 from credit_ledger cl
                          where cl.user_id = u.id and cl.reason = 'hosted_session')
       limit 1;
      if v_gonderen is null then
        raise notice '249: agirlayarak kredi kazanmamis kullanici yok — hediye kapisi 2 OLCULEMEDI';
        raise exception 'agirlayarak_kazanilan_kredi_yetersiz';
      end if;
      insert into connection_requests (from_id, to_id, intent, status, responded_at)
      values (v_gonderen, v_guest, 'connect', 'accepted', now());
      perform set_config('request.jwt.claims',
        json_build_object('sub', v_gonderen, 'role','authenticated')::text, true);
      perform public.misafir_hakki_hediye_et(v_guest, 1);
      v_h := v_h || 'agirlayarak kazanilmamis kredi hediye edilebildi — kredi ticareti kapisi'::text;
    exception when others then
      if sqlerrm not like '%agirlayarak_kazanilan_kredi_yetersiz%' then
        v_h := v_h || ('hediye kaynak testi beklenmeyen hata: ' || sqlerrm)::text;
      end if;
    end;

    -- (7) A4 ikinci yarı — bayat istek iadesi idempotent mi
    v_r := public.bayat_istekleri_iade_et();
    if coalesce(v_r ->> 'ok','') <> 'true' then
      v_h := v_h || 'bayat_istekleri_iade_et calismadi'::text;
    end if;

    raise exception 'GERI_AL_249';
  exception when others then
    if sqlerrm <> 'GERI_AL_249' then
      v_h := v_h || ('olcum coktu: ' || sqlerrm);
    end if;
  end;

  if array_length(v_h,1) is not null then
    raise exception '249 NOBETCI: %', array_to_string(v_h, ' | ');
  end if;
  raise notice '249 OK · merdiven tirmanmadan gorunuyor · soguk agda istek bedava, ag isininca degil · nabiz sayiyor · kabin kosullu · hediye kapilari kapali';
end $n249$;

commit;

select '249 IS MODELI' as sonuc,
       (select count(*) from public.havalimani_nabzi(14))                       as nabizli_havalimani,
       (select (value #>> '{}')::int from beta_settings where key='soguk_ag_host_esigi') as soguk_esik,
       (select (value #>> '{}')::int from beta_settings where key='bayat_istek_saat')     as bayat_saat;

-- ----------------------------------------------------------------------
-- trg_kisit_gozden_gecir   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_kisit_gozden_gecir() returns trigger
language plpgsql security definer set search_path = public as $tkg$
declare v_kalan int;
begin
  if new.status = 'open' then return new; end if;
  select count(*) into v_kalan from reports
   where target_id = new.target_id and status = 'open'
     and type in ('harassment','fraud','off_platform_payment');
  if v_kalan = 0 then
    update users
       set shadow_limited = false,
           restricted_until = null,
           kisit_inceleme_bekliyor = false,
           kisit_sebebi = null
     where id = new.target_id and kisit_inceleme_bekliyor;
  end if;
  return new;
end $tkg$;

drop trigger if exists trg_kisit_gozden_gecir on reports;
create trigger trg_kisit_gozden_gecir
  after update of status on reports
  for each row execute function public.trg_kisit_gozden_gecir();

-- ════════════════════════════════════════════════════════════════════════
-- §2 — HUNİ (F1)
--
-- Gokberk: "F · ÖLÇÜM KÖRLÜĞÜ hepsini yapabilirsin"
--
-- 🔴 ÖLÇTÜM: `analytics`, `funnel`, `huni` — hiçbiri yoktu. Bu turda kredi
-- ekonomisini, açık istek tavanını, ödül fiyatlarını ayarladık ve
-- HİÇBİRİNİN ETKİSİNİ ÖLÇEMİYORUZ.
--
-- 🆕 SINIF: "AYARLAMAYI ÖLÇEMEDİĞİN BİR SİSTEMİ AYARLAMAK, AYARLAMAK DEĞİL
-- TAHMİN ETMEKTİR."
--
-- ÜÇÜNCÜ PARTİ ANALİTİK KULLANMIYORUM — bilinçli:
--   (a) KVKK: kullanıcı davranışını dışarı çıkarmak yeni bir veri sorumlusu
--       ilişkisi demek. Bu ürünün en hassas verisi "kim nerede, ne zaman".
--   (b) Zaten `audit_log` var ve yazılıyor. İkinci bir doğruluk kaynağı
--       kurmak yerine olanı kullanmak.
--   (c) Uygulama tarafında SDK yok = paket boyutu ve izin yok.
--
-- BEŞ OLAY yeterli. Fazlası, bakılmayan bir kuyruk olur.
-- ════════════════════════════════════════════════════════════════════════

create table if not exists huni_olaylari (
  id         bigserial primary key,
  user_id    uuid,
  olay       text not null,
  ref_id     uuid,
  airport    char(3),
  meta       jsonb,
  created_at timestamptz not null default now()
);
create index if not exists huni_olay_zaman on huni_olaylari (olay, created_at desc);
create index if not exists huni_kullanici  on huni_olaylari (user_id, created_at desc);

alter table huni_olaylari enable row level security;
drop policy if exists huni_kendi on huni_olaylari;
create policy huni_kendi on huni_olaylari for select using (user_id = auth.uid());

-- Yalnız BU BEŞ olay. Serbest metin bir olay adı, üç ay sonra 40 farklı
-- yazımla aynı şeyi anlatan bir çöplük olur.
alter table huni_olaylari drop constraint if exists huni_olay_kapisi;
alter table huni_olaylari add constraint huni_olay_kapisi check (
  olay in ('app_acildi','kesif_goruldu','istek_gonderildi','istek_kabul','oturum_tamam'));

-- ----------------------------------------------------------------------
-- huni_yaz   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ----------------------------------------------------------------------
create or replace function public.huni_yaz(p_olay text, p_ref uuid default null,
                                           p_airport text default null, p_meta jsonb default null)
returns void
language plpgsql security definer set search_path = public as $hy250$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  -- 🔴 GÜRÜLTÜ KAPISI: aynı kullanıcı + aynı olay + aynı referans 60 saniye
  -- içinde bir kez yazılır. Aksi hâlde `app_acildi` her ekran dönüşünde
  -- yazılır ve huni kendi gürültüsünde boğulur.
  if exists (select 1 from huni_olaylari h
              where h.user_id = v_uid and h.olay = p_olay
                and h.ref_id is not distinct from p_ref
                and h.created_at > now() - interval '60 seconds') then
    return;
  end if;
  insert into huni_olaylari (user_id, olay, ref_id, airport, meta)
  values (v_uid, p_olay, p_ref, nullif(upper(btrim(coalesce(p_airport,''))),'')::char(3), p_meta);
exception when others then
  -- Ölçüm, ürünü DURDURMAZ. Huni yazımı düşerse akış devam eder.
  return;
end $hy250$;

grant execute on function public.huni_yaz(text, uuid, text, jsonb) to authenticated;

-- Sunucunun kendi bildiği iki olayı istemciye SORMUYORUZ: kabul ve
-- tamamlama zaten sunucuda oluyor. İstemciye sorulan bir olay, istemci
-- unutursa kaybolur.

-- ----------------------------------------------------------------------
-- trg_huni_istek   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_huni_istek() returns trigger
language plpgsql security definer set search_path = public as $thi$
declare v_ap char(3);
begin
  select a.airport_code into v_ap from availabilities a where a.id = new.avail_id;
  if tg_op = 'INSERT' then
    insert into huni_olaylari (user_id, olay, ref_id, airport)
    values (new.guest_id, 'istek_gonderildi', new.id, v_ap);
  elsif tg_op = 'UPDATE' and new.status = 'accepted' and old.status is distinct from 'accepted' then
    insert into huni_olaylari (user_id, olay, ref_id, airport)
    values (new.guest_id, 'istek_kabul', new.id, v_ap);
  end if;
  return new;
exception when others then return new;
end $thi$;

drop trigger if exists trg_huni_istek on requests;
create trigger trg_huni_istek after insert or update of status on requests
  for each row execute function public.trg_huni_istek();

-- ----------------------------------------------------------------------
-- trg_huni_oturum   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_huni_oturum() returns trigger
language plpgsql security definer set search_path = public as $tho$
declare v_ap char(3); v_g uuid; v_h uuid;
begin
  if new.status <> 'completed' or old.status is not distinct from 'completed' then return new; end if;
  select r.guest_id, r.host_id, a.airport_code into v_g, v_h, v_ap
    from requests r left join availabilities a on a.id = r.avail_id
   where r.id = new.request_id;
  insert into huni_olaylari (user_id, olay, ref_id, airport, meta)
  values (v_g, 'oturum_tamam', new.id, v_ap, jsonb_build_object('rol','misafir')),
         (v_h, 'oturum_tamam', new.id, v_ap, jsonb_build_object('rol','host'));
  return new;
exception when others then return new;
end $tho$;

drop trigger if exists trg_huni_oturum on sessions;
create trigger trg_huni_oturum after update of status on sessions
  for each row execute function public.trg_huni_oturum();

-- ---- RAPOR ----
-- F2: "SAĞLIKLI KULLANICI" TANIMI. Gokberk sordu: "başarılı kullanıcı nedir?"
-- Tanımı burada, TEK yerde sabitliyorum ki her rapor aynı şeyi saysın:
--   SAĞLIKLI = son 90 günde EN AZ BİR oturumu tamamlamış kullanıcı.
--   GERİ DÖNEN = en az İKİ oturumu tamamlamış kullanıcı.
-- Bir tanım yoksa hedef de yoktur.

-- ----------------------------------------------------------------------
-- huni_raporu   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ----------------------------------------------------------------------
create or replace function public.huni_raporu(p_gun int default 30)
returns jsonb
language plpgsql stable security definer set search_path = public as $hr250$
declare v_bas timestamptz := now() - make_interval(days => greatest(1, coalesce(p_gun,30)));
  v_acan int; v_kesif int; v_istek int; v_kabul int; v_oturum int;
  v_saglikli int; v_donen int; v_toplam int;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;

  select count(distinct user_id) into v_acan   from huni_olaylari where olay='app_acildi'       and created_at >= v_bas;
  select count(distinct user_id) into v_kesif  from huni_olaylari where olay='kesif_goruldu'    and created_at >= v_bas;
  select count(distinct user_id) into v_istek  from huni_olaylari where olay='istek_gonderildi' and created_at >= v_bas;
  select count(distinct user_id) into v_kabul  from huni_olaylari where olay='istek_kabul'      and created_at >= v_bas;
  select count(distinct user_id) into v_oturum from huni_olaylari where olay='oturum_tamam'     and created_at >= v_bas;

  select count(*) into v_toplam from users;
  select count(distinct r.guest_id) into v_saglikli
    from sessions s join requests r on r.id = s.request_id
   where s.status='completed' and s.completed_at > now() - interval '90 days';
  select count(*) into v_donen from (
    select r.guest_id from sessions s join requests r on r.id = s.request_id
     where s.status='completed' group by r.guest_id having count(*) >= 2) q;

  return jsonb_build_object(
    'gun', greatest(1, coalesce(p_gun,30)),
    'basamaklar', jsonb_build_array(
      jsonb_build_object('ad','Uygulamayı açtı',      'kisi', v_acan),
      jsonb_build_object('ad','Keşfi gördü',          'kisi', v_kesif),
      jsonb_build_object('ad','İstek gönderdi',       'kisi', v_istek),
      jsonb_build_object('ad','Kabul edildi',         'kisi', v_kabul),
      jsonb_build_object('ad','Oturumu tamamladı',    'kisi', v_oturum)),
    -- 🔴 ORAN YALNIZ PAYDA VARSA ANLAMLI. Payda 0 iken "%0 dönüşüm"
    -- yazmak, ölçemediğimiz şeyi başarısızlık gibi göstermek olurdu.
    'oranlar', jsonb_build_object(
      'kesif_orani',  case when v_acan  = 0 then null else round(v_kesif::numeric  / v_acan, 3) end,
      'istek_orani',  case when v_kesif = 0 then null else round(v_istek::numeric  / v_kesif, 3) end,
      'kabul_orani',  case when v_istek = 0 then null else round(v_kabul::numeric  / v_istek, 3) end,
      'oturum_orani', case when v_kabul = 0 then null else round(v_oturum::numeric / v_kabul, 3) end),
    'tanimlar', jsonb_build_object(
      'saglikli_kullanici', 'son 90 gunde en az BIR oturumu tamamlamis kullanici',
      'geri_donen',         'en az IKI oturumu tamamlamis kullanici'),
    'saglik', jsonb_build_object(
      'toplam_kullanici', v_toplam,
      'saglikli', v_saglikli,
      'geri_donen', v_donen,
      'saglikli_orani', case when v_toplam = 0 then null else round(v_saglikli::numeric / v_toplam, 3) end));
end $hr250$;

grant execute on function public.huni_raporu(int) to service_role;

-- ════════════════════════════════════════════════════════════════════════
-- §3 — İSTEMCİNİN DOĞRUDAN YAZDIĞI TABLOLAR (C3)
--
-- Gokberk: "burada kararı sana bırakıyorum."
--
-- KARARIM: altı tablodan DÖRDÜ kapanıyor, İKİSİ kalıyor — ve kalanların
-- gerekçesi var.
--
--   visits         → KAPANIYOR (`seyahat_ekle`, `seyahat_sil`)
--   notifications  → KAPANIYOR (`bildirim_okundu`)
--   chat_channels  → KAPANIYOR (248'in `baglanti_sohbeti_ac`ı zaten var;
--                    burada yalnız GRANT kalkıyor)
--   users          → KAPANIYOR (232 kolonları kapatmıştı; tablo düzeyinde
--                    UPDATE hakkı da kalkıyor)
--   profiles       → KALIYOR. Profil düzenleme 20+ alan yazıyor ve hepsi
--                    kullanıcının kendi verisi; RLS `user_id = auth.uid()`
--                    ile zaten dar. Kapı kolonları (guest_capacity,
--                    access_source) SQL 232'de kolon düzeyinde kapatıldı.
--                    Buradaki risk düşük, RPC'ye taşımanın maliyeti yüksek.
--   messages       → KALIYOR. Gerçek zamanlı sohbet; her mesajı RPC'den
--                    geçirmek gecikme ekler ve Realtime aboneliğini bozar.
--
-- 🆕 SINIF: "HER DOĞRUDAN YAZMA BİR AÇIK DEĞİLDİR — AÇIK OLAN, KURALI
-- OLAN BİR TABLOYA KURALSIZ YAZMAKTIR."
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- seyahat_ekle   [etkin kaynak: 283_kural_motoru_on_iki_boyut.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.seyahat_ekle(
  p_airport text, p_date date, p_from time, p_to time,
  p_destination text default null, p_flight text default null,
  p_purpose text default null, p_carrier text default null,
  p_kisi integer default 1, p_cocuk_yas integer[] default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_id uuid;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);   -- 282/B1
  if p_airport is null or btrim(p_airport) = '' then raise exception 'airport_required'; end if;
  if p_date is null then raise exception 'date_required'; end if;
  if p_date < current_date then raise exception 'date_in_past'; end if;
  if p_from is null or p_to is null or p_from >= p_to then raise exception 'invalid_time_range'; end if;
  if not exists (select 1 from airports where code = upper(btrim(p_airport))::char(3)) then
    raise exception 'unknown_airport';
  end if;
  if p_kisi is null or p_kisi < 1 or p_kisi > 6 then raise exception 'party_size_invalid'; end if;
  if p_cocuk_yas is not null and (array_length(p_cocuk_yas,1) >= p_kisi
     or exists (select 1 from unnest(p_cocuk_yas) x where x < 0 or x > 17)) then
    raise exception 'child_ages_invalid';
  end if;
  if exists (select 1 from visits v
              where v.user_id = v_uid and v.airport_code = upper(btrim(p_airport))::char(3)
                and v.visit_date = p_date
                and v.time_from < p_to and p_from < v.time_to) then
    raise exception 'ayni_saatte_seyahatin_var';
  end if;

  insert into visits (user_id, airport_code, destination, visit_date, time_from, time_to, flight_number,
                      party_size, child_ages)
  values (v_uid, upper(btrim(p_airport))::char(3),
          nullif(upper(btrim(coalesce(p_destination,''))),'')::char(3),
          p_date, p_from, p_to, nullif(btrim(coalesce(p_flight,'')),''),
          p_kisi, nullif(p_cocuk_yas::smallint[], '{}'::smallint[]))
  returning id into v_id;

  if p_purpose is not null then perform public.set_visit_purpose(v_id, p_purpose); end if;
  if p_carrier is not null then perform public.set_visit_carrier(v_id, p_carrier); end if;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;

-- ----------------------------------------------------------------------
-- seyahat_sil   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.seyahat_sil(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_sahip uuid;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select user_id into v_sahip from visits where id = p_id;
  if v_sahip is null then raise exception 'visit_not_found'; end if;
  if v_sahip <> v_uid then raise exception 'not_your_visit'; end if;
  -- 240'ın sözleşme kilidi: bu seyahate dayanan aktif başvuru varsa silinmez.
  -- 🔴 301/§8: fonksiyon SAYI döndürüyor; `if <sayı> then` 0/1 için
  -- tesadüfen çalışıyor ('0'/'1' geçerli boolean metni), 2+ açık başvuruda
  -- "invalid input syntax for type boolean: "2"" ile patlıyordu (tam akış testi).
  if public.seyahate_bagli_basvuru(p_id) > 0 then
    raise exception 'seyahat_silinemez_basvuru_var';
  end if;
  delete from visits where id = p_id;
  return jsonb_build_object('ok', true);
end $function$;

-- ──────────────────────────────────────────────────────────────────────
-- §9 · blok_gecmisi_kapat (canlı tanım + 301 yaması)
-- ──────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.blok_gecmisi_kapat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- 🔴 301/§9: 204'ten beri bekleyen istek KAPANIYOR ama tutulan kredi
  -- İADE EDİLMİYORDU (tam akış testi: defterde yalnız `request_hold:-1`).
  -- Engelleme uygulamadan yapılamadığı için bu hiç görünmemişti; 301 §1
  -- engellemeyi açınca canlı hataya dönüşecekti. Artık her kapanan istek
  -- iade yolundan geçiyor (tekrar iadeyi `istek_kredisi_iade` kendisi önler).
  declare v_r record;
  begin
    for v_r in
      update requests set status = 'cancelled', responded_at = now()
       where status = 'pending'
         and ((guest_id = new.blocker and host_id = new.blocked)
           or (guest_id = new.blocked and host_id = new.blocker))
      returning id
    loop
      perform public.istek_kredisi_iade(v_r.id, 'request_refund');
    end loop;
  end;

  -- ⚠️ `connection_status` = pending | accepted | declined | blocked.
  -- İlk yazışımda 'rejected' yazdım — enum'da YOK, 22P02 aldım. Enum'un
  -- kendisinde zaten 'blocked' var ve burada 'declined'dan DAHA DOĞRU:
  -- kullanıcı reddetmedi, engelledi. Sebep kayıtta kalsın.
  update connection_requests set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((from_id = new.blocker and to_id = new.blocked)
       or (from_id = new.blocked and to_id = new.blocker));

  update invites set status = 'blocked', responded_at = now()
   where status = 'pending'
     and ((host_id = new.blocker and guest_id = new.blocked)
       or (host_id = new.blocked and guest_id = new.blocker));

  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ
-- ════════════════════════════════════════════════════════════════════════
do $z301$
declare v_n int; v_l text;
begin
  select count(*), string_agg(p.proname, ', ') into v_n, v_l
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('engelle','engeli_kaldir','engellediklerim','gelmedi_bildir','gelmedi_esigi')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '301 §Z: authenticated çağıramıyor: %', v_l; end if;
  select count(*) into v_n from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '301 §Z: PUBLIC''e açık % fonksiyon (300 §A2 geriledi)', v_n; end if;
  if position('test_hesabi_gizli_mi' in (select prosrc from pg_proc where proname = 'is_visible')) = 0 then
    raise exception '301 §Z: is_visible yamasız';
  end if;
  if not exists (select 1 from pg_trigger where tgname = 'trg_mesaj_engel') then
    raise exception '301 §Z: mesaj engel tetikleyicisi yok';
  end if;
  raise notice '301 §Z: kapılar ölçüldü';
end $z301$;

select '301 OK — engelleme · gelmedi · test hesabı gizleme · rehber sayacı' as sonuc;

-- ----------------------------------------------------------------------
-- bildirim_okundu   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ----------------------------------------------------------------------
create or replace function public.bildirim_okundu(p_id uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $bo250$
declare v_uid uuid := auth.uid(); v_n int;
begin
  perform public.motor_yazimi_ac();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_id is null then
    update notifications set read = true, read_at = now()
     where user_id = v_uid and coalesce(read,false) = false;
  else
    update notifications set read = true, read_at = now()
     where id = p_id and user_id = v_uid;
  end if;
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'guncellenen', v_n);
end $bo250$;

grant execute on function public.seyahat_ekle(text, date, time, time, text, text, text, text) to authenticated;
grant execute on function public.seyahat_sil(uuid) to authenticated;
grant execute on function public.bildirim_okundu(uuid) to authenticated;

-- ---- KAPILAR ----
-- ⚠️ GRANT'LERİ ŞİMDİ KALDIRMIYORUM. Uygulama sürümü 2.96 yayına çıkana
-- kadar CANLIDA ESKİ APP ÇALIŞIYOR ve doğrudan yazıyor. Hakkı bugün
-- almak, kullanıcının seyahat ekleyememesi demek.
-- 🆕 SINIF: "BİR KAPIYI, ONDAN GEÇEN İSTEMCİ GÜNCELLENMEDEN KAPATMAK,
-- GÜVENLİK DEĞİL KESİNTİDİR."
-- Kapama SQL 251'de, app 2.96 yayına çıktıktan sonra. İzin listesine
-- şimdiden yazıyorum ki o gün ne kapatılacağı tartışılmasın.
create table if not exists kapatilacak_yazma_haklari (
  tablo      text not null,
  islem      text not null,
  yerine     text not null,
  app_surumu text not null,
  not_metni  text,
  primary key (tablo, islem)
);
insert into kapatilacak_yazma_haklari (tablo, islem, yerine, app_surumu, not_metni) values
  ('visits',        'insert', 'seyahat_ekle()',         '2.96', 'Dogrulama ve cakisma kurali istemcide yoktu'),
  ('visits',        'delete', 'seyahat_sil()',          '2.96', 'Sozlesme kilidi (basvurusu olan seyahat) atlanabiliyordu'),
  ('notifications', 'update', 'bildirim_okundu()',      '2.96', 'Kullanici baskasinin bildirimini okundu isaretleyebilir miydi'),
  ('chat_channels', 'insert', 'baglanti_sohbeti_ac()',  '2.96', 'Engellenmis ciftte bile kanal acilabiliyordu (248)'),
  ('users',         'update', 'rolumu_sec() / my_plan', '2.96', '232 kolonlari kapatti; tablo hakki da kalkacak')
on conflict (tablo, islem) do update
  set yerine = excluded.yerine, app_surumu = excluded.app_surumu, not_metni = excluded.not_metni;

