-- ----------------------------------------------------------------------
-- bo_silme_talepleri   [etkin kaynak: 250_yaptirim_huni_dil_ve_kapilar.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_silme_talepleri()
returns jsonb
language plpgsql stable security definer set search_path = public as $sd250$
declare v_gun int; v_rows jsonb;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  v_gun := coalesce((select (value #>> '{}')::int from beta_settings where key='silme_talebi_gun'), 30);
  select jsonb_agg(jsonb_build_object(
           'id', d.id, 'user_id', d.matched_user_id, 'eposta', d.email,
           'talep_at', d.created_at,
           'son_tarih', d.created_at + make_interval(days => v_gun),
           'gecikti', (d.created_at + make_interval(days => v_gun)) < now(),
           'durum', d.status)
         order by d.created_at)
    into v_rows
    from deletion_requests d
   where d.status not in ('done','completed','rejected');
  return jsonb_build_object('sure_gun', v_gun, 'talepler', coalesce(v_rows,'[]'::jsonb));
end $sd250$;

grant execute on function public.bo_silme_talepleri() to service_role;

-- ════════════════════════════════════════════════════════════════════════
-- §6 — D1: host_wallet ARTIK METİN CERRAHİSİYLE ONARILMIYOR
--
-- Gokberk: "mimari kararlarında kararları sana bırakıyorum."
--
-- 🔴 GEÇEN TUR BU FONKSİYON YÜZÜNDEN BİR GÜVENLİK KAPISI DÜŞTÜ.
-- SQL 232 `host_wallet`e sahiplik kapısı enjekte ediyor, 238 içindeki
-- cümleyi değiştiriyor, 248 §9 oranı düzeltiyor. Üç migration AYNI
-- GÖVDEYE sırayla dokunuyor ve her biri diğerini ezebiliyor — 248'de
-- tam da bu oldu.
--
-- KARARIM: kapı ile hesabı AYIR. Artık:
--     host_wallet(p_user)      → YALNIZ kapı + host_wallet_hesap() çağrısı
--     host_wallet_hesap(p_user)→ hesabın kendisi (232'nin dokunduğu gövde)
-- Kapı ayrı bir fonksiyonda olduğu için hesap gövdesi yeniden yazılsa da
-- kapı DÜŞEMEZ. 243'te `discover_availabilities` için aynı deseni
-- kullanmıştım ve orada hiç sorun çıkmadı — desen doğru, her yere
-- uygulanmamıştı.
--
-- 🆕 SINIF: "ÜZERİNE ÜÇ AYRI MIGRATION YAZAN BİR GÖVDE, GÖVDE DEĞİL
-- ÇARPIŞMA ALANIDIR — KURALI GÖVDEDEN ÇIKAR."
-- ════════════════════════════════════════════════════════════════════════

do $d1250$
declare v_tanim text; v_hesap text;
begin
  select pg_get_functiondef(p.oid) into v_tanim
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname='public' and p.proname='host_wallet' limit 1;
  if v_tanim is null then
    raise notice '250 §6: host_wallet yok — DOKUNULMADI.'; return;
  end if;
  if v_tanim like '%host_wallet_hesap%' then
    raise notice '250 §6: ayrisma zaten yapilmis — dokunulmadi.'; return;
  end if;

  -- (1) Mevcut gövdeyi OLDUĞU GİBİ `_hesap` adıyla kopyala.
  v_hesap := replace(v_tanim, 'FUNCTION public.host_wallet(', 'FUNCTION public.host_wallet_hesap(');
  execute v_hesap;

  -- (2) `host_wallet` artık yalnız kapı. Kapı metni 232'nin koyduğu
  --     kuralın AYNISI — burada yeniden yazıyorum ki tek bir yerde dursun.
  execute $q$

-- ----------------------------------------------------------------------
-- zamanli_is_kos   [etkin kaynak: 251_cron_nobeti_ve_kahya_ayricaligi.sql]
-- ----------------------------------------------------------------------
create or replace function public.zamanli_is_kos(p_is text)
returns jsonb
language plpgsql security definer set search_path = public as $zk251$
declare v_id bigint; v_bas timestamptz := clock_timestamp(); v_sonuc jsonb;
begin
  if not exists (select 1 from zamanli_isler where is_adi = p_is) then
    raise exception 'bilinmeyen_is' using detail = p_is;
  end if;
  insert into is_kosum_defteri (is_adi) values (p_is) returning id into v_id;
  begin
    -- Ad `zamanli_isler`den geliyor, serbest metin DEĞİL: birincil anahtar
    -- kontrolünden geçti. Yine de `format(%I)` ile kaçırıyoruz.
    execute format('select public.%I()', p_is) into v_sonuc;
    update is_kosum_defteri
       set bitti_at = now(),
           saniye = extract(epoch from (clock_timestamp() - v_bas)),
           sonuc = v_sonuc
     where id = v_id;
    return jsonb_build_object('ok', true, 'is', p_is, 'sonuc', v_sonuc);
  exception when others then
    -- 🔴 HATA YUTULMUYOR AMA CRON'U DA DURDURMUYOR: kaydediyoruz ve
    -- dönüyoruz. Bir işin patlaması, öteki işlerin koşmasını engellememeli.
    update is_kosum_defteri
       set bitti_at = now(),
           saniye = extract(epoch from (clock_timestamp() - v_bas)),
           hata = sqlerrm
     where id = v_id;
    return jsonb_build_object('ok', false, 'is', p_is, 'hata', sqlerrm);
  end;
end $zk251$;

grant execute on function public.zamanli_is_kos(text) to service_role;

-- ----------------------------------------------------------------------
-- bo_zamanli_isler   [etkin kaynak: 251_cron_nobeti_ve_kahya_ayricaligi.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_zamanli_isler()
returns jsonb
language plpgsql stable security definer set search_path = public as $bzi251$
declare v jsonb;
begin
  if auth.uid() is not null
     and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select jsonb_agg(jsonb_build_object(
      'is_adi', z.is_adi,
      'aciklama', z.aciklama,
      'beklenen_saat', z.beklenen_saat,
      'son_kosum', s.basladi_at,
      'son_saniye', s.saniye,
      'son_hata', s.hata,
      'son_sonuc', s.sonuc,
      'hic_kosmadi', (s.basladi_at is null),
      -- SESSİZ = hiç koşmamış YA DA beklenen aralığın ötesinde
      'sessiz', (s.basladi_at is null
                 or s.basladi_at < now() - make_interval(hours => z.beklenen_saat)))
    order by z.is_adi)
    into v
    from zamanli_isler z
    left join lateral (
      select d.basladi_at, d.saniye, d.hata, d.sonuc
        from is_kosum_defteri d
       where d.is_adi = z.is_adi
       order by d.basladi_at desc limit 1) s on true;
  return jsonb_build_object('isler', coalesce(v, '[]'::jsonb));
end $bzi251$;

grant execute on function public.bo_zamanli_isler() to service_role;

-- ════════════════════════════════════════════════════════════════════════
-- §2 — KÂHYA'YA SINIRSIZ KURAL SORUSU (A1)
--
-- Eleştiri raporunda "sırada" bırakmıştım: host'a verebileceğimiz
-- karşılıklardan biri de ÜRÜNÜN KENDİSİ. Kural motoru host için değerli
-- ve `kural_sorusu_hakkim` zaten günlük bir kota uyguluyor.
--
-- Ağırlayan kişiye o kotayı açmak bize sıfıra mal oluyor ve tam da doğru
-- kişiye veriyor: çok ağırlayan host, çok soru soran host'tur.
--
-- 🆕 SINIF: "EN UCUZ ÖDÜL, ÜRÜNÜN KENDİSİNİN DAHA ÇOĞUDUR."
-- ════════════════════════════════════════════════════════════════════════

alter table host_tiers add column if not exists sinirsiz_kural_sorusu boolean not null default false;
update host_tiers set sinirsiz_kural_sorusu = true where code in ('kahya','konsiyerj');

do $ks251$
declare v_tanim text; v_yeni text;
begin
  select pg_get_functiondef(p.oid) into v_tanim
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname='public' and p.proname='kural_sorusu_hakkim' limit 1;
  if v_tanim is null then
    raise notice '251 §2: kural_sorusu_hakkim yok — DOKUNULMADI.'; return;
  end if;
  if v_tanim like '%sinirsiz_kural_sorusu%' then
    raise notice '251 §2: ayricalik zaten bagli — dokunulmadi.'; return;
  end if;

  -- Gövdeye DOKUNMUYORUM; sarmalıyorum. (243 ve 250 §6'nın dersi:
  -- "bir gövdeyi onarmanın en sağlam yolu gövdeye hiç dokunmamaktır.")
  v_yeni := replace(v_tanim, 'FUNCTION public.kural_sorusu_hakkim(',
                             'FUNCTION public.kural_sorusu_hakkim_ham(');
  execute v_yeni;

  execute $q$

-- ----------------------------------------------------------------------
-- push_izni_bildir   [etkin kaynak: 252_ulasilabilirlik_ve_push_izni.sql]
-- ----------------------------------------------------------------------
create or replace function public.push_izni_bildir(
  p_durum text,
  p_tekrar_sorulabilir boolean default true,
  p_platform text default null,
  p_soruldu boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $pib252$
declare v_uid uuid := auth.uid(); v_durum text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  v_durum := lower(btrim(coalesce(p_durum,'')));
  if v_durum not in ('verildi','reddedildi','sorulmadi','desteklenmiyor') then
    -- Bilinmeyen bir durumu 'sorulmadi' saymak, reddi gizlerdi.
    return jsonb_build_object('ok', false, 'reason', 'bilinmeyen_durum');
  end if;

  insert into push_izinleri (user_id, durum, tekrar_sorulabilir, platform,
                             ilk_sorulma, son_bildirim, soruldu_sayi)
  values (v_uid, v_durum, coalesce(p_tekrar_sorulabilir, true), p_platform,
          case when p_soruldu then now() end, now(),
          case when p_soruldu then 1 else 0 end)
  on conflict (user_id) do update set
    durum              = excluded.durum,
    tekrar_sorulabilir = excluded.tekrar_sorulabilir,
    platform           = coalesce(excluded.platform, push_izinleri.platform),
    ilk_sorulma        = coalesce(push_izinleri.ilk_sorulma, excluded.ilk_sorulma),
    son_bildirim       = now(),
    soruldu_sayi       = push_izinleri.soruldu_sayi + case when p_soruldu then 1 else 0 end;

  -- 🔴 KAPANAN DELİK: kullanıcı izni SONRADAN Ayarlar'dan kapatabilir.
  -- O anda bize hiçbir şey gelmez; token veritabanında sağlam durur ve
  -- gönderdiğimiz her bildirim Expo'da "DeviceNotRegistered" olur — biz
  -- ise ulaşabildiğimizi sanırız. Expo makbuzlarını okumuyoruz (ayrı bir
  -- iş), ama uygulamanın HER AÇILIŞTA durum bildirmesi aynı deliği kapatır:
  -- izin artık yoksa token'ı BİZ pasife alırız.
  if v_durum <> 'verildi' then
    update push_tokens set active = false, updated_at = now()
     where user_id = v_uid and coalesce(active, true);
  end if;

  return jsonb_build_object('ok', true, 'durum', v_durum);
end $pib252$;

grant execute on function public.push_izni_bildir(text, boolean, text, boolean) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §2 — "ULAŞILABİLİR Mİ" TEK BİR YERDE TANIMLANIR
--
-- Aynı sorunun iki farklı yerde iki farklı cevabı olmasın diye tek
-- fonksiyon. Tanım: AKTİF bir Expo token'ı VAR ve izin durumu bunu
-- yalanlamıyor.
--
-- 🔒 GİZLİLİK KARARI: bu fonksiyon `authenticated`e AÇILMIYOR. Kullanıcı
-- kimliği alan bir "ulaşılabilir mi" ucu, herkesin herkesin bildirim
-- durumunu yoklamasına izin verirdi. Misafirin ihtiyacı olan şey zaten
-- kişi değil İLAN: aşağıdaki ilan kapsamlı sarmalayıcı o ihtiyacı görür.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- ulasilabilir_mi   [etkin kaynak: 252_ulasilabilirlik_ve_push_izni.sql]
-- ----------------------------------------------------------------------
create or replace function public.ulasilabilir_mi(p_user uuid)
returns boolean
language sql stable security definer set search_path = public as $um252$
  select exists (
           select 1 from push_tokens t
            where t.user_id = p_user
              and coalesce(t.active, true)
              and coalesce(t.token,'') like 'ExponentPushToken%')
     and not exists (
           select 1 from push_izinleri i
            where i.user_id = p_user
              and i.durum in ('reddedildi','desteklenmiyor'));
$um252$;

-- 🔴 `from public` YETMEDİ — nöbetçi yakaladı. Projede şemaya toplu
-- `grant execute ... to authenticated` uygulanmış; PUBLIC'ten almak o
-- doğrudan hakkı kaldırmıyor. Rolü ADIYLA geri almak gerekiyor.
-- 🆕 SINIF: "BİR HAKKI HERKESTEN ALMAK, ONU ADIYLA ALMIŞ BİRİNDEN ALMAZ."
revoke all on function public.ulasilabilir_mi(uuid) from public;
revoke all on function public.ulasilabilir_mi(uuid) from authenticated;
revoke all on function public.ulasilabilir_mi(uuid) from anon;
grant execute on function public.ulasilabilir_mi(uuid) to service_role;

-- ════════════════════════════════════════════════════════════════════════
-- §2b — "ULAŞAMIYORUZ" İLE "ULAŞTIĞIMIZI BİLMİYORUZ" AYNI ŞEY DEĞİL
--
-- 🔴 BU BÖLÜM BİR HATAMIN ÜZERİNE YAZILDI VE HATAYI E2E NÖBETÇİSİ BULDU.
--
-- §4'ü ilk yazdığımda bedeli `ulasilabilir_mi()`ye bağlamıştım: token yoksa
-- ulaşılamaz, ulaşılamıyorsa istek bedava. Sonra ölçtüm:
--
--     aktif token : 0
--     izin kaydı  : 0
--     ilanlı host : 29
--
-- Yani kural, KURULDUĞU GÜN 29 host'un HEPSİNİ ulaşılamaz ilan edip
-- BÜTÜN İSTEKLERİ BEDAVAYA çevirecekti. App 2.98 mağazaya düşene kadar da
-- öyle kalacaktı: kredi geliri sıfır, sebebi görünmez.
--
-- Üstelik bu dosyanın §1'inde doğru cümleyi ZATEN yazmıştım:
--     "Token'ın YOKLUĞU hiçbir şeyin kanıtı değildir."
-- ve on satır sonra kendi cümlemi çiğnedim.
--
-- 🆕 SINIF: "KANITIN YOKLUĞUNU KANIT SAYAN BİR KURAL, KURULDUĞU GÜN
-- HERKESİ SUÇLU BULUR."
--
-- Bu yüzden İKİ ayrı yüklem var ve ikisi ayrı işler için:
--   `ulasilabilir_mi`   → ÖLÇÜM. "Şu an ulaşabiliyor muyuz?" BO bunu okur.
--   `kesin_ulasilamaz`  → PARA. Yalnız kullanıcının KENDİ cihazı bize
--                          "bildirim kapalı" dediyse doğrudur.
-- Para kararı, ölçüm kararından DAHA YÜKSEK kanıt ister.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- kesin_ulasilamaz   [etkin kaynak: 252_ulasilabilirlik_ve_push_izni.sql]
-- ----------------------------------------------------------------------
create or replace function public.kesin_ulasilamaz(p_user uuid)
returns boolean
language sql stable security definer set search_path = public as $ku252$
  select exists (
    select 1 from push_izinleri i
     where i.user_id = p_user
       and i.durum in ('reddedildi','desteklenmiyor'));
$ku252$;

revoke all on function public.kesin_ulasilamaz(uuid) from public;
revoke all on function public.kesin_ulasilamaz(uuid) from authenticated;
revoke all on function public.kesin_ulasilamaz(uuid) from anon;
grant execute on function public.kesin_ulasilamaz(uuid) to service_role;

-- ----------------------------------------------------------------------
-- ilan_ulasilabilir_mi   [etkin kaynak: 252_ulasilabilirlik_ve_push_izni.sql]
-- ----------------------------------------------------------------------
create or replace function public.ilan_ulasilabilir_mi(p_avail_id uuid)
returns boolean
language sql stable security definer set search_path = public as $ium252$
  select public.ulasilabilir_mi(a.host_id)
    from availabilities a
   where a.id = p_avail_id
     and a.active
     and a.visibility <> 'Hidden';
$ium252$;

-- 🔴 NÖBETÇİ HAKLI ÇIKTI: bunu `authenticated`e açmış ve yüzeye yazmıştım
-- ama app onu HİÇ çağırmıyor — yalnız cümleyi (`..._notu`) okuyor.
-- Kullanılmayan bir hak yalnız yüzey büyütür. İç yapı taşı olarak kalıyor.
revoke all on function public.ilan_ulasilabilir_mi(uuid) from public;
revoke all on function public.ilan_ulasilabilir_mi(uuid) from authenticated;
revoke all on function public.ilan_ulasilabilir_mi(uuid) from anon;
grant execute on function public.ilan_ulasilabilir_mi(uuid) to service_role;

-- ════════════════════════════════════════════════════════════════════════
-- §3 — HOST'A NE SÖYLENECEK: SOYUT DEĞİL, SAYIYLA
--
-- "Bildirimlerin kapalı" bir ayar cümlesidir; kimse umursamaz.
-- "3 aktif ilanın ve 1 bekleyen isteğin var, ve bunu göremeyeceksin"
-- bir KAYIP cümlesidir. Uyarının şiddeti kullanıcının o an KAYBEDECEĞİ
-- şeye göre belirlenir — bizim ne kadar istediğimize göre değil.
-- ════════════════════════════════════════════════════════════════════════

insert into beta_settings (key, value) values
