-- ----------------------------------------------------------------------
-- profil_gorunur_mu   [etkin kaynak: 253_guvenlik_kapanisi.sql]
-- ----------------------------------------------------------------------
create or replace function public.profil_gorunur_mu(p_target uuid)
returns boolean
language plpgsql stable security definer set search_path = public as $pg253$
declare v_ben uuid := auth.uid(); v_gor text; v_esik int; v_puan int;
begin
  if v_ben is null then return false; end if;
  if p_target = v_ben then return true; end if;

  -- Aramızda gerçek bir ilişki varsa görünürlük tercihi devreye girmez:
  -- bir isteği kabul etmiş ya da göndermiş kişi zaten karşılaşmıştır.
  if exists (select 1 from connection_requests c
              where ((c.from_id = v_ben and c.to_id = p_target)
                  or (c.to_id = v_ben and c.from_id = p_target))
                and c.status in ('pending','accepted'))
     or exists (select 1 from requests r
                 where (r.guest_id = v_ben and r.host_id = p_target)
                    or (r.host_id = v_ben and r.guest_id = p_target))
  then
    return true;
  end if;

  select coalesce(profile_visibility::text, 'Everyone') into v_gor
    from profiles where user_id = p_target;
  if v_gor is null then return false; end if;
  if v_gor = 'Everyone' then return true; end if;
  if v_gor = 'Connections' then return false; end if;

  -- 'Trusted+' → bakanın güven puanı eşiği geçmeli.
  v_esik := coalesce((select (value #>> '{}')::int from beta_settings
                       where key = 'profil_trusted_esik'), 40);
  select score into v_puan from trust_scores where user_id = v_ben;
  return coalesce(v_puan, 0) >= v_esik;
end $pg253$;

grant execute on function public.profil_gorunur_mu(uuid) to authenticated;
grant execute on function public.profil_gorunur_mu(uuid) to service_role;

drop policy if exists profiles_read_auth on profiles;
create policy profiles_read_auth on profiles for select to authenticated
  using (public.profil_gorunur_mu(user_id));

drop policy if exists trust_read_auth on trust_scores;
create policy trust_read_auth on trust_scores for select to authenticated
  using (public.profil_gorunur_mu(user_id));

-- ════════════════════════════════════════════════════════════════════════
-- §7 — `chat_channels` POLİTİKASI KENDİNİ DELİYORDU
--
-- `chat_companion_read` ifadesi `(connection_id IS NULL) OR (...)` diye
-- başlıyordu. İstek tabanlı kanallarda `connection_id` HER ZAMAN NULL —
-- yani ilk dal her giriş yapana bütün kanalları açıyordu. RLS politikaları
-- OR'landığı için doğru yazılmış ikinci politika bunu telafi etmiyor.
--
-- 🆕 SINIF: "AYNI TABLODA ÜÇ POLİTİKA, BİRİNİN DİĞERİNİ DELMESİNİ
-- KAÇINILMAZ KILAR — ÇÜNKÜ RLS ONLARI 'VEYA' İLE BİRLEŞTİRİR."
-- ════════════════════════════════════════════════════════════════════════

drop policy if exists chat_companion_read on chat_channels;
drop policy if exists chan_parties on chat_channels;
-- 🔴 KENDİ ADINI DA DÜŞÜR: tekrar kurulumda "already exists" verirdi.
-- Bir dosya yalnız boş veritabanında çalışıyorsa, migration değil kurulumdur.
drop policy if exists chat_taraf_okur on chat_channels;
create policy chat_taraf_okur on chat_channels for select to authenticated
  using (
    (connection_id is not null and exists (
       select 1 from connection_requests c
        where c.id = chat_channels.connection_id
          and (c.from_id = auth.uid() or c.to_id = auth.uid())))
    or
    (request_id is not null and exists (
       select 1 from requests r
        where r.id = chat_channels.request_id
          and (r.guest_id = auth.uid() or r.host_id = auth.uid())))
  );

-- ════════════════════════════════════════════════════════════════════════
-- §8 — `phone_in_use` NUMARA TARAMA SERVİSİ OLMAKTAN ÇIKIYOR
--
-- Sınırsız çağrılabilen bir "bu numara kayıtlı mı" ucu, elindeki numara
-- listesinin hangilerinin kullanıcımız olduğunu söyler. Bu, KVKK açısından
-- "bir kişinin belirli bir hizmeti kullandığı" bilgisidir.
-- ════════════════════════════════════════════════════════════════════════

do $pin253$
declare v_tanim text;
begin
  select pg_get_functiondef(p.oid) into v_tanim
    from pg_proc p where p.oid = to_regprocedure('public.phone_in_use(text)');
  if v_tanim is null then
    raise notice '253 §8: phone_in_use YOK — dokunulmadi.'; return;
  end if;
  if v_tanim like '%rate_limits%' then
    raise notice '253 §8: hiz siniri zaten var — dokunulmadi.'; return;
  end if;
end $pin253$;

-- ----------------------------------------------------------------------
-- bildirim_tercihlerim   [etkin kaynak: 254_urun_bosluklari.sql]
-- ----------------------------------------------------------------------
create or replace function public.bildirim_tercihlerim()
returns jsonb
language plpgsql stable security definer set search_path = public as $bt254$
declare v_uid uuid := auth.uid(); v_p jsonb; v_kap jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select prefs into v_p from notification_prefs where user_id = v_uid;
  select value into v_kap from beta_settings where key = 'bildirim_kapatilabilir';
  return jsonb_build_object(
    'tercihler', coalesce(v_p, '{}'::jsonb),
    'kapatilabilir', coalesce(v_kap, '[]'::jsonb),
    -- Kapatılamayanları da SÖYLÜYORUZ: "neden bu anahtar yok?" sorusunun
    -- cevabı ekranda olmalı.
    'kapatilamaz_not', public.metin('bildirim_zorunlu_not_tr'));
end $bt254$;

-- ----------------------------------------------------------------------
-- bildirim_tercihi_yaz   [etkin kaynak: 254_urun_bosluklari.sql]
-- ----------------------------------------------------------------------
create or replace function public.bildirim_tercihi_yaz(p_kategori text, p_push boolean)
returns jsonb
language plpgsql security definer set search_path = public as $bty254$
declare v_uid uuid := auth.uid(); v_kap jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select value into v_kap from beta_settings where key = 'bildirim_kapatilabilir';
  if not coalesce(v_kap, '[]'::jsonb) ? p_kategori then
    -- Kapatılamaz bir kategoriyi sessizce kabul etmek, ekranda kapalı
    -- görünen ama çalışan bir anahtar üretirdi.
    return jsonb_build_object('ok', false, 'reason', 'kapatilamaz_kategori');
  end if;

  insert into notification_prefs (user_id, prefs, updated_at)
  values (v_uid, jsonb_build_object(p_kategori, jsonb_build_object('push', p_push)), now())
  on conflict (user_id) do update
    set prefs = notification_prefs.prefs
                || jsonb_build_object(p_kategori, jsonb_build_object('push', p_push)),
        updated_at = now();
  return jsonb_build_object('ok', true, 'kategori', p_kategori, 'push', p_push);
end $bty254$;

grant execute on function public.bildirim_tercihlerim() to authenticated;
grant execute on function public.bildirim_tercihi_yaz(text, boolean) to authenticated;

insert into beta_settings (key, value) values
  ('bildirim_zorunlu_not_tr', to_jsonb('İstek, oturum ve güvenlik bildirimleri kapatılamaz: bu üründe eşleşme zamana bağlı, kaçırılan bir bildirim kaçırılan bir buluşmadır.'::text)),
  ('bildirim_zorunlu_not_tr_en', to_jsonb('Request, session and safety notifications cannot be turned off: matches here are time-bound, and a missed notification is a missed meeting.'::text))
on conflict (key) do nothing;

-- ════════════════════════════════════════════════════════════════════════
-- §2 — BİLDİRİM NEREYE GÖTÜRÜR: SUNUCU SÖYLESİN
--
-- 🔴 Bildirime dokunmak yalnız "okundu" işaretliyordu. Kullanıcı push'a
-- basıp uygulamayı açıyor, listeye dokunuyor, satır griye dönüyor ve
-- HİÇBİR ŞEY olmuyordu. İsteği bulmak için kendisi geziniyordu.
--
-- Hedefi istemciye gömmek yerine sunucudan veriyoruz: kategori→ekran
-- eşlemesi ürünün kuralıdır, iki istemcide (app + ileride web) ayrı ayrı
-- yazılmamalı.
--
-- 🆕 SINIF: "ZAMANA BAĞLI BİR ÜRÜNDE BİLDİRİM, HABER DEĞİL KISAYOLDUR."
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- bildirim_hedefi   [etkin kaynak: 266_eksik_bildirimler.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.bildirim_hedefi(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $bh266$
declare v_uid uuid := auth.uid(); n record;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into n from notifications where id = p_id and user_id = v_uid;
  if n.id is null then return jsonb_build_object('ekran', null); end if;

  -- ÖNCE ref_type: en özel eşleşme kazanır.
  if n.ref_type = 'message' then
    return jsonb_build_object('ekran', 'sohbet', 'ref', n.ref_id);
  elsif n.ref_type = 'rate_reminder' then
    return jsonb_build_object('ekran', 'degerlendirmeler', 'ref', n.ref_id);
  elsif n.ref_type = 'trip_reminder' then
    return jsonb_build_object('ekran', 'plan', 'alt', 'seyahat', 'ref', n.ref_id);
  end if;

  return case n.category::text
    when 'requests'    then jsonb_build_object('ekran','plan','alt','ilan','ref', n.ref_id)
    when 'sessions'    then jsonb_build_object('ekran','plan','alt','ilan','ref', n.ref_id)
    when 'invites'     then jsonb_build_object('ekran','plan','alt','seyahat','ref', n.ref_id)
    when 'connections' then jsonb_build_object('ekran','tanis','ref', n.ref_id)
    when 'credits'     then jsonb_build_object('ekran','cuzdan')
    when 'ratings'     then jsonb_build_object('ekran','degerlendirmeler','ref', n.ref_id)
    when 'safety'      then jsonb_build_object('ekran','guvenlik')
    else jsonb_build_object('ekran', null) end;
end $bh266$;

grant execute on function public.bildirim_hedefi(uuid) to authenticated;

-- ════════════════════════════════════════════════════════════════════════
-- §5 — NÖBETÇİ
--
-- 🔴 "Tetikleyici kuruldu" ile "bildirim üretiliyor" aynı şey değil.
-- Nöbetçi GERÇEK BİR MESAJ yazıp bildirimin doğduğunu görüyor, sonra
-- geri alıyor.
-- ════════════════════════════════════════════════════════════════════════
do $nb266$
declare
  v_host uuid; v_guest uuid; v_av uuid; v_req uuid; v_ch uuid;
  v_once int; v_sonra int; v_dil_ok boolean;
begin
  -- Çeviri katmanı yerinde mi
  select exists (select 1 from push_ceviri where tr = 'Yeni istek ✦') into v_dil_ok;
  if not v_dil_ok then
    raise exception '266 NOBETCI: push_ceviri bos — dil katmani kurulmadi.';
  end if;

  if not exists (select 1 from pg_trigger tg join pg_class c on c.oid = tg.tgrelid
                  where c.relname='messages' and tg.tgname='trg_mesaj_bildirimi') then
    raise exception '266 NOBETCI: mesaj bildirim tetikleyicisi kurulmadi.';
  end if;

  -- ══════════════════════════════════════════════════════════════════
  -- GERÇEK AKIŞ DENEMESİ — ALT İŞLEMDE, HER HÂLÜKÂRDA GERİ ALINIYOR.
  --
  -- 🔴 İLK YAZIMIM DENEME KAYITLARINI `delete` İLE TEMİZLİYORDU ve
  -- sıfırdan kurulan bir veritabanında PATLADI:
  --     ERROR: update or delete on table "requests" violates foreign key
  --            constraint "sessions_request_id_fkey"
  -- Çünkü `requests` satırını eklediğim anda bir tetikleyici `sessions`
  -- satırı da üretiyor; benim temizliğim onu bilmiyordu. Yani nöbetçi,
  -- ölçtüğü sistemin kendi yan etkilerini takip etmek zorunda kalıyordu.
  --
  -- 🆕 SINIF: "BİR TESTİN TEMİZLİĞİNİ ELLE YAZARSAN, TEST ETTİĞİN
  -- SİSTEMİN HER YENİ YAN ETKİSİNİ DE ELLE TAKİP ETMEK ZORUNDA
  -- KALIRSIN — GERİ ALMAYI VERİTABANINA BIRAK."
  --
  -- PL/pgSQL'de `begin ... exception` bir ALT İŞLEM açar. Sonunda
  -- bilerek istisna fırlatıyoruz: alt işlem geri alınır, ne eklediysek
  -- (tetikleyicilerin ürettikleri dahil) yok olur.
  begin
    select id into v_host  from users order by created_at limit 1;
    select id into v_guest from users where id <> v_host order by created_at limit 1;
    if v_host is null or v_guest is null then
      raise notice '266 NOBETCI: iki kullanici yok, canli akis denemesi ATLANDI.';
    else
      insert into availabilities (host_id, airport_code, avail_date, time_from, time_to, slots, active)
      values (v_host, (select code from airports limit 1), current_date + 3, '10:00', '12:00', 1, true)
      returning id into v_av;
      insert into requests (avail_id, guest_id, host_id, status)
      values (v_av, v_guest, v_host, 'accepted') returning id into v_req;
      insert into chat_channels (request_id, kind) values (v_req, 'lounge') returning id into v_ch;

      select count(*) into v_once from notifications
       where user_id = v_host and ref_type = 'message';
      insert into messages (channel_id, from_id, body) values (v_ch, v_guest, 'A7 kapisindayim');
      select count(*) into v_sonra from notifications
       where user_id = v_host and ref_type = 'message';

      if v_sonra <= v_once then
        raise exception '266 NOBETCI KIRMIZI: mesaj yazildi ama BILDIRIM URETILMEDI (% → %).', v_once, v_sonra;
      end if;
      raise notice '266 NOBETCI: mesaj → bildirim zinciri CALISIYOR (% → %).', v_once, v_sonra;
    end if;
    -- Denemeyi geri al.
    raise exception 'NOBETCI_GERI_AL';
  exception
    when others then
      if sqlerrm <> 'NOBETCI_GERI_AL' then raise; end if;
  end;

  raise notice '266 NOBETCI OK: mesaj bildirimi · alici dili · iki hatirlatma · hedef cozucu.';
end $nb266$;

-- (Nöbetçinin deneme kayıtları artık ALT İŞLEMDE geri alınıyor — yukarıya
--  bak. Elle `delete` yazan eski blok kaldırıldı: `requests` silmek
--  tetikleyicinin ürettiği `sessions` satırına takılıyordu ve nöbetçi,
--  ölçtüğü sistemin yan etkilerini takip etmek zorunda kalıyordu.)

commit;

-- ----------------------------------------------------------------------
-- sohbet_temizle   [etkin kaynak: 255_magaza_sartlari.sql]
-- ----------------------------------------------------------------------
create or replace function public.sohbet_temizle(p_body text)
returns jsonb
language plpgsql immutable set search_path = public as $st255$
declare v text := coalesce(p_body, ''); v_sebep text[] := '{}';
begin
  -- IBAN (TR + genel) — platform dışı ödeme talebinin en net işareti.
  if v ~* '\m[A-Z]{2}[0-9]{2}[ ]?([0-9A-Z][ ]?){10,30}\M' then
    v := regexp_replace(v, '\m[A-Z]{2}[0-9]{2}[ ]?([0-9A-Z][ ]?){10,30}\M', '••• IBAN gizlendi •••', 'gi');
    v_sebep := v_sebep || 'iban'::text;
  end if;

  -- Kart numarası (13-19 hane, arada boşluk/tire olabilir)
  if v ~ '(\d[ -]?){13,19}' then
    v := regexp_replace(v, '(\d[ -]?){13,19}', '••• kart no gizlendi •••', 'g');
    v_sebep := v_sebep || 'kart_no'::text;
  end if;

  -- Telefon: +90..., 05..., ya da 10+ haneli dizi
  if v ~ '(\+?\d[ ()\-]?){10,15}' then
    v := regexp_replace(v, '(\+?\d[ ()\-]?){10,15}', '••• numara gizlendi •••', 'g');
    v_sebep := v_sebep || 'telefon'::text;
  end if;

  -- E-posta
  if v ~* '[[:alnum:]._%%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}' then
    v := regexp_replace(v, '[[:alnum:]._%%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}', '••• e-posta gizlendi •••', 'gi');
    v_sebep := v_sebep || 'eposta'::text;
  end if;

  -- Platform dışı ödeme dili — MASKELENMEZ, yalnız İŞARETLENİR.
  -- Cümleyi gizlemek konuşmayı anlamsızlaştırırdı; moderasyon görsün yeter.
  if coalesce(p_body,'') ~* '(havale|eft|iban|papara|nakit|elden öde|elden odeme|kapıda öde|dışarıdan öde|whatsapp|telegram|instagram)' then
    v_sebep := v_sebep || 'platform_disi'::text;
  end if;

  return jsonb_build_object('body', v, 'sebep', v_sebep,
                            'degisti', (v is distinct from coalesce(p_body,'')));
end $st255$;

-- ----------------------------------------------------------------------
-- trg_sohbet_suzgeci   [etkin kaynak: 255_magaza_sartlari.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_sohbet_suzgeci() returns trigger
language plpgsql security definer set search_path = public as $tss255$
declare v jsonb;
begin
  v := public.sohbet_temizle(new.body);
  new.body := v ->> 'body';
  if jsonb_array_length(coalesce(v -> 'sebep', '[]'::jsonb)) > 0 then
    new.flagged := true;
    new.flag_reason := array_to_string(
      array(select jsonb_array_elements_text(v -> 'sebep')), ',');
  end if;
  return new;
exception when others then
  -- 🔴 SÜZGEÇ, MESAJI DÜŞÜREMEZ. Bir moderasyon aracının arızası
  -- kullanıcının konuşmasını kesmemeli.
  return new;
end $tss255$;

drop trigger if exists trg_sohbet_suzgeci on messages;
create trigger trg_sohbet_suzgeci before insert on messages
  for each row execute function public.trg_sohbet_suzgeci();

grant execute on function public.sohbet_temizle(text) to authenticated;

