-- ----------------------------------------------------------------------
-- puanlama_hatirlat   [etkin kaynak: 266_eksik_bildirimler.sql]
-- ----------------------------------------------------------------------
create or replace function public.puanlama_hatirlat()
returns jsonb language plpgsql security definer set search_path = public as $ph266$
declare v_n int := 0; r record;
begin
  for r in
    select s.id as session_id, x.uid
      from sessions s
      join requests q on q.id = s.request_id
      cross join lateral (values (q.host_id), (q.guest_id)) as x(uid)
     where s.status = 'completed'
       and s.completed_at between now() - interval '7 days' and now() - interval '24 hours'
       and not exists (select 1 from ratings ra
                        where ra.session_id = s.id and ra.rater_id = x.uid)
       and not exists (select 1 from notifications n
                        where n.user_id = x.uid and n.ref_type = 'rate_reminder'
                          and n.ref_id = s.id)
  loop
    insert into notifications (user_id, category, title, body, ref_id, ref_type)
    values (r.uid, 'ratings', 'Puanlamayı unutma ✦',
            'Dün tamamladığın oturumu puanlarsan karşı tarafın güven puanı oluşur.',
            r.session_id, 'rate_reminder');
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'hatirlatilan', v_n);
end $ph266$;

-- ════════════════════════════════════════════════════════════════════════
-- §4 — YARINKİ LOUNGE GÜNÜ HATIRLATMASI
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- yarinki_lounge_hatirlat   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.yarinki_lounge_hatirlat()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int := 0; r record;
begin
  for r in
    select q.id as req_id, x.uid, a.airport_code, a.time_from
      from requests q
      join availabilities a on a.id = q.avail_id
      cross join lateral (values (q.host_id), (q.guest_id)) as x(uid)
     where q.status = 'accepted'
       and a.avail_date = public.yerel_gun(a.airport_code) + 1
       and not exists (select 1 from notifications n
                        where n.user_id = x.uid and n.ref_type = 'trip_reminder'
                          and n.ref_id = q.id)
  loop
    insert into notifications (user_id, category, title, body, ref_id, ref_type)
    values (r.uid, 'sessions', 'Yarın lounge günün ✈',
            r.airport_code || ' · ' || coalesce(to_char(r.time_from, 'HH24:MI'), '')
              || ' — buluşmadan önce sohbetten haberleşin.',
            r.req_id, 'trip_reminder');
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'hatirlatilan', v_n);
end $function$;


-- ── 4 · KENDİ SINAMASI · GMT+3 / GMT+0 · TK1979 ────────────────────────
-- Brief'teki sınır vakası: aynı duvar saati iki farklı zaman diliminde
-- iki farklı GERÇEK AN'dır. Sınama bunu hem IST (UTC+3) hem LHR (UTC+1/0)
-- üzerinde doğruluyor ve eski davranışın yanlış olduğunu da gösteriyor.
do $$
declare
  v_ist timestamptz; v_utc_gibi timestamptz; v_lhr timestamptz; v_fark numeric;
  v_tz_ist text; v_tz_lhr text;
begin
  select timezone into v_tz_ist from airports where code = 'IST';
  if v_tz_ist is null then raise exception '292: IST havalimani yok'; end if;

  -- 1) IST · 13 Eylül 18:00 duvar saati → 15:00 UTC olmalı (yaz saati UTC+3)
  v_ist := public.yerel_an(date '2026-09-13', time '18:00', 'IST');
  if (v_ist at time zone 'UTC')::time <> time '15:00' then
    raise exception '292: IST 18:00 → UTC % (15:00 bekleniyordu)', (v_ist at time zone 'UTC')::time;
  end if;

  -- 2) ESKİ DAVRANIŞ YANLIŞTI: düz cast 18:00 UTC verir, fark 3 saat
  v_utc_gibi := (date '2026-09-13' + time '18:00') at time zone 'UTC';
  v_fark := extract(epoch from (v_utc_gibi - v_ist)) / 3600.0;
  if v_fark <> 3 then
    raise exception '292: beklenen kayma 3 saat, olculen %', v_fark;
  end if;
  raise notice '292 sinama 1-2: IST duvar 18:00 = 15:00 UTC · eski davranisin kaymasi % saat', v_fark;

  -- 3) AYNI DUVAR SAATİ, BAŞKA DİLİM: LHR varsa 18:00'i farklı ana çevirmeli
  select timezone into v_tz_lhr from airports where code = 'LHR';
  if v_tz_lhr is not null then
    v_lhr := public.yerel_an(date '2026-09-13', time '18:00', 'LHR');
    if v_lhr = v_ist then
      raise exception '292: LHR ve IST ayni ana dustu — dilim okunmuyor';
    end if;
    raise notice '292 sinama 3: ayni duvar saati IST=% LHR=% (fark % saat)',
      v_ist, v_lhr, round(extract(epoch from (v_lhr - v_ist))/3600.0, 2);
  else
    raise notice '292 sinama 3: LHR katalogda yok, atlandi';
  end if;

  -- 4) BİLİNMEYEN HAVALİMANI ÜRÜNÜ PATLATMAZ — İstanbul'a düşer
  if public.yerel_an(date '2026-09-13', time '18:00', 'ZZZ') <> v_ist then
    raise exception '292: bilinmeyen havalimani Istanbul a dusmedi';
  end if;

  -- 5) GÜN DÖNÜMÜ: 01:00 IST = onceki gun 22:00 UTC → `yerel_gun` UTC ile
  --    ayni gunu dondurmemeli. Sabit bir anla dogruluyoruz (now() degil).
  if (timestamptz '2026-09-13 22:00:00+00' at time zone v_tz_ist)::date
     <> date '2026-09-14' then
    raise exception '292: gun donumu yanlis — 22:00 UTC IST de 14 Eylul olmali';
  end if;
  raise notice '292 sinama 5: gun donumu OK (22:00 UTC = IST 14 Eylul 01:00)';

  -- 6) EN ERKEN GİRİŞ KURALI artık doğru tarafta:
  --    ilan 09:00 IST · uçuş 14:20 IST · salon 3 saat önce alıyor → İHLAL
  if not (public.yerel_an(date '2026-09-13', time '09:00', 'IST')
          < public.yerel_an(date '2026-09-13', time '14:20', 'IST') - interval '3 hours') then
    raise exception '292: en erken giris kurali hala ihlali yakalamiyor';
  end if;
  --    ilan 12:00 IST ise UYGUN olmalı (14:20 - 3sa = 11:20)
  if (public.yerel_an(date '2026-09-13', time '12:00', 'IST')
      < public.yerel_an(date '2026-09-13', time '14:20', 'IST') - interval '3 hours') then
    raise exception '292: 12:00 ilani yanlis sekilde ihlal sayildi';
  end if;
  raise notice '292 sinama 6: en erken giris kurali iki yonde de dogru';
end $$;

-- ----------------------------------------------------------------------
-- telefon_kanonik   [etkin kaynak: 268_telefon_tekilligi.sql]
-- ----------------------------------------------------------------------
create or replace function public.telefon_kanonik(p_phone text)
returns text
language sql immutable
set search_path = public as $$
  select case
    when d is null                     then null
    -- Türkiye: ülke kodu 90 yalnız Türkiye'ye ait; uzunluk kesin.
    when left(d, 2) = '90'             then (case when length(d) = 12 then d end)
    when left(d, 1) = '0'              then (case when length(d) = 11 then '90' || substr(d, 2) end)
    when length(d) = 10                then '90' || d
    -- Yabancı numara: E.164 en fazla 15 hane, en az ~11 anlamlı.
    when length(d) between 11 and 15   then d
    else null
  end
  from (select nullif(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), '') as d) x;
$$;

-- ----------------------------------------------------------------------
-- trg_email_onayi_aynala   [etkin kaynak: 269_dogrulama_zinciri.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_email_onayi_aynala()
returns trigger
language plpgsql security definer set search_path = public as $ea269$
begin
  if NEW.email_confirmed_at is not null
     and (OLD.email_confirmed_at is null) then
    insert into verifications (user_id, email_verified, email_verified_at)
    values (NEW.id, true, NEW.email_confirmed_at)
    on conflict (user_id) do update
      set email_verified = true,
          email_verified_at = coalesce(verifications.email_verified_at, excluded.email_verified_at);
    -- Puan ANINDA güncellensin: kullanıcı onay bağlantısına tıklayıp
    -- uygulamaya döndüğünde puanı çoktan artmış olmalı.
    perform public.recompute_trust(NEW.id);
  end if;
  return NEW;
end $ea269$;

drop trigger if exists on_auth_email_confirmed on auth.users;
create trigger on_auth_email_confirmed
  after update of email_confirmed_at on auth.users
  for each row execute function public.trg_email_onayi_aynala();

-- ════════════════════════════════════════════════════════════════════════
-- §3 — PUAN ARTIK KOŞULLU
--
-- `recompute_trust` metin üzerinden yamalanıyor: gövdenin tamamını
-- yeniden yazmak, aradan geçen 8 sürümün (rozet eşikleri, ceza mantığı,
-- oturum sayısı) üstüne yazma riski taşırdı.
--
-- ⚠️ Yamanın TUTTUĞU DOĞRULANIYOR: satır bulunamazsa dosya UYARI verir ve
-- hiçbir şey değiştirmez — sessizce "yaptım" demez.
-- 🆕 SINIF: "METİN ÜZERİNDEN YAMA, YAMANIN TUTTUĞUNU KANITLAMADIĞI SÜRECE
-- BİR DEĞİŞİKLİK DEĞİL BİR TEMENNİDİR."
-- ════════════════════════════════════════════════════════════════════════
do $rt269$
declare
  v_eski text; v_yeni text;
  v_ara  text := 'v_c := v_c || ''{"email":10}''::jsonb;';
  v_yer  text := 'if coalesce(v_v.email_verified,false) then'
              || ' v_c := v_c || ''{"email":10}''::jsonb; end if;';
begin
  select pg_get_functiondef(p.oid) into v_eski
    from pg_proc p where p.oid = to_regprocedure('public.recompute_trust(uuid)');
  if v_eski is null then
    raise exception '269 §3: recompute_trust YOK.';
  end if;

  if v_eski like '%coalesce(v_v.email_verified,false) then v_c%' then
    raise notice '269 §3: e-posta puani zaten kosullu — dokunulmadi.';
    return;
  end if;

  if position(v_ara in v_eski) = 0 then
    raise warning '269 §3: beklenen satir BULUNAMADI — recompute_trust ELLE bakilmali.';
    return;
  end if;

  v_yeni := replace(v_eski, v_ara, v_yer);
  execute v_yeni;
  raise notice '269 §3: e-posta puani artik dogrulamaya bagli. ✓';
end $rt269$;

-- ════════════════════════════════════════════════════════════════════════
-- §4 — KANAL AYARI İSTEMCİYE AÇILIYOR
--
-- `service_endpoints` zaten istemcinin okuyabildiği (265 beyaz listesi)
-- ayar yüzeyi. Doğrulama kanalı oraya taşınıyor: uygulama artık
-- "SMS var mı" sorusunu KOD İÇİNDEN DEĞİL SUNUCUDAN öğrenecek.
--
-- Netgsm/Twilio bağlandığı gün yapılacak tek şey:
--     update beta_settings set value = to_jsonb('sms'::text) where key='otp_channel';
-- Uygulama güncellemesi GEREKMEZ.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- dogrulama_kanali   [etkin kaynak: 269_dogrulama_zinciri.sql]
-- ----------------------------------------------------------------------
create or replace function public.dogrulama_kanali()
returns jsonb
language sql stable security definer set search_path = public as $dk269$
  select jsonb_build_object(
    'kanal', coalesce((select value #>> '{}' from beta_settings where key = 'otp_channel'), 'email'),
    -- 🔴 `sms_hazir`: kanal 'sms' OLSA BİLE gönderici yoksa yalan söylemeyelim.
    -- Bugün gönderici yok; bu bayrak bir gönderici eklendiğinde
    -- `otp_sms_saglayici` ayarıyla açılacak.
    'sms_hazir', coalesce((select value #>> '{}' from beta_settings
                            where key = 'otp_sms_saglayici'), '') <> '',
    'not', coalesce((select value #>> '{}' from beta_settings
                      where key = 'otp_notice_phone_declared'), '')
  );
$dk269$;
revoke execute on function public.dogrulama_kanali() from public;
grant execute on function public.dogrulama_kanali() to authenticated, anon;

insert into beta_settings (key, value)
values ('otp_sms_saglayici', to_jsonb(''::text))
on conflict (key) do nothing;

-- ════════════════════════════════════════════════════════════════════════
-- §5 — `send_otp` ARTIK SESSİZCE BAŞARILI OLMUYOR
--
-- 🔴 EN SİNSİ HALKA BURASIYDI. Fonksiyon kodu üretiyor, saklıyor ve
-- `{ok:true}` dönüyor. Uygulama `ok` görüp kod ekranına geçiyor.
-- Hiçbir yerde hata YOK — ama SMS de yok. Sistem "çalıştı" diyor,
-- kullanıcı boş ekrana bakıyor.
--
-- 🆕 SINIF: "GÖNDERMEYEN BİR GÖNDERİCİNİN 'TAMAM' DEMESİ, HATA VERMESİNDEN
-- DAHA KÖTÜDÜR — HATA GÖRÜLÜR, SESSİZ BAŞARI GÖRÜLMEZ."
--
-- Artık gönderici tanımlı değilse `sms_not_configured` fırlatıyor.
-- ════════════════════════════════════════════════════════════════════════

-- ----------------------------------------------------------------------
-- test_verisi_tazele   [etkin kaynak: 270_test_verisi_gorunur.sql]
-- ----------------------------------------------------------------------
create or replace function public.test_verisi_tazele(p_gun_ileri int default 3)
returns jsonb
language plpgsql security definer set search_path = public as $tvt270$
declare
  r record;
  v_ilan int := 0; v_atlanan int := 0; v_seyahat int := 0; v_hesap int;
  v_yeni date;
begin
  -- Yalnız service_role / staff çalıştırabilir: fikstür tazelemek bir
  -- bakım işidir, istemciye açık bir uç değil.
  if auth.uid() is not null
     and not coalesce((select is_staff from users where id = auth.uid()), false) then
    raise exception 'not_authorized';
  end if;

  -- 🔴 SATIR SATIR, HER BİRİ KENDİ ALT İŞLEMİNDE.
  -- İlk yazışımda tek bir toplu `update` vardı ve ilk engelde TAMAMI
  -- düştü: `kabul_edilmis_basvuru_var` tetikleyicisi, kabul edilmiş
  -- başvurusu olan bir ilanın tarihini değiştirmeye izin vermiyor.
  -- Bu doğru bir iş kuralı — fikstür tazeleyicinin onu ezmeye HAKKI YOK.
  --
  -- Ama tek bir korunan satır yüzünden 26 ilanın hiçbiri tazelenmedi.
  -- Toplu güncelleme "ya hep ya hiç" demektir; bakım işi ise "elinden
  -- geleni yap, dokunamadığını SÖYLE" olmalıdır.
  --
  -- 🆕 SINIF: "BİR BAKIM İŞİ, İŞ KURALLARINI EZMEK YERİNE ONLARA
  -- TAKILDIĞINI RAPORLAMALIDIR — VE TEK BİR ENGEL, GERİ KALAN İŞİ
  -- İPTAL ETMEMELİDİR."
  for r in
    select a.id
      from availabilities a
      join users u on u.id = a.host_id
     where a.active and a.avail_date < current_date
       and u.deleted_at is null
       and (u.email like '%@vitrin.loungelink.test'
         or u.email like '%@seed.loungelink.test'
         or u.email like '%@e2e.test')
  loop
    v_yeni := current_date + (p_gun_ileri + (abs(hashtext(r.id::text)) % 5));
    begin
      update availabilities set avail_date = v_yeni where id = r.id;
      v_ilan := v_ilan + 1;
    exception when others then
      -- Korunan satır (kabul edilmiş başvuru vb.) — dokunmuyoruz.
      v_atlanan := v_atlanan + 1;
    end;
  end loop;

  -- Misafir seyahatleri de tazelensin, yoksa "uçuşun yok" kapısı kapanır
  -- ve talep akışı hiç denenemez.
  for r in
    select v.id
      from visits v
      join users u on u.id = v.user_id
     where v.visit_date < current_date
       and u.deleted_at is null
       and (u.email like '%@vitrin.loungelink.test'
         or u.email like '%@seed.loungelink.test'
         or u.email like '%@e2e.test')
  loop
    begin
      update visits
         set visit_date = current_date + (p_gun_ileri + (abs(hashtext(r.id::text)) % 5))
       where id = r.id;
      v_seyahat := v_seyahat + 1;
    exception when others then
      null;
    end;
  end loop;

  select count(*) into v_hesap from users
   where deleted_at is null
     and (email like '%@vitrin.loungelink.test'
       or email like '%@seed.loungelink.test'
       or email like '%@e2e.test');

  return jsonb_build_object(
    'ok', true,
    'tazelenen_ilan', v_ilan,
    'atlanan_ilan', v_atlanan,
    'tazelenen_seyahat', v_seyahat,
    'test_hesabi', v_hesap,
    'not', case when v_atlanan > 0
                then v_atlanan || ' ilan is kurali korumasi nedeniyle atlandi (kabul edilmis basvuru).'
                else 'Hepsi tazelendi.' end);
end $tvt270$;

revoke execute on function public.test_verisi_tazele(int) from public, anon, authenticated;
grant  execute on function public.test_verisi_tazele(int) to service_role;

-- İlk tazeleme şimdi
select public.test_verisi_tazele();

