-- ----------------------------------------------------------------------------
-- SONUÇ TABLOSU
-- ----------------------------------------------------------------------------
select
  (select count(*) from users where is_staff and deleted_at is null)          as "staff hesap",
  (select count(*) from availabilities a
     join users u on u.id = a.host_id
    where a.active and a.avail_date >= current_date
      and (u.email like '%@seed.loungelink.test'
        or u.email like '%@vitrin.loungelink.test'
        or u.email like '%@e2e.test'))                                        as "canlı fikstür ilanı",
  (select count(*) from availabilities a
     join users u on u.id = a.host_id
    where a.active and a.avail_date < current_date
      and (u.email like '%@seed.loungelink.test'
        or u.email like '%@vitrin.loungelink.test'
        or u.email like '%@e2e.test'))                                        as "hâlâ tarihi geçmiş";

-- ----------------------------------------------------------------------
-- cron_isi_var   [etkin kaynak: 274_istek_tavani_kilidi.sql]
-- ----------------------------------------------------------------------
create or replace function public.cron_isi_var(p_ad text)
returns boolean language plpgsql stable as $ci$
declare v boolean;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    return false;
  end if;
  execute 'select exists (select 1 from cron.job where jobname = $1)'
    into v using p_ad;
  return coalesce(v, false);
end $ci$;

do $cr$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule('loungelink_bayat_istek')
      where exists (select 1 from cron.job where jobname = 'loungelink_bayat_istek');
    perform cron.schedule('loungelink_bayat_istek', '15 * * * *',
                          $q$select public.bayat_istekleri_iade_et();$q$);
    raise notice '274: bayat istek isi saatlik zamanlandi';
  else
    raise notice '274: pg_cron yok — is zamanlanmadi';
  end if;
end $cr$;


-- ════════════════════════════════════════════════════════════════════════
-- §6 — NÖBETÇİ + SONUÇ TABLOSU
--
-- Supabase yalnız SON sorgunun tablosunu gösterir; bu yüzden tek tablo.
-- ════════════════════════════════════════════════════════════════════════
select * from (
  select 1::int as s, 'Kapatilan bayat istek (bu kosuda)' as "kontrol",
         (select count(*)::text from requests
           where decision_note like '%274%') as "deger",
         '—' as "durum"
  union all
  select 2, 'Hala kilitli gorunen hesap (canli sayimla)',
         (select count(*)::text from (
            select r.guest_id
              from requests r join availabilities a on a.id = r.avail_id
             where r.status = 'pending' and a.avail_date >= current_date
               and r.created_at >= now() - interval '72 hours'
             group by r.guest_id having count(*) >= 1
         ) x),
         'bilgi — tavan asilmadikca sorun degil'
  union all
  select 3, 'Zamanlanmis is: loungelink_bayat_istek',
         case when exists (select 1 from pg_extension where extname='pg_cron')
                   and public.cron_isi_var('loungelink_bayat_istek')
              then 'var' else 'YOK' end,
         case when exists (select 1 from pg_extension where extname='pg_cron')
                   and public.cron_isi_var('loungelink_bayat_istek')
              then '✅ saatlik kosacak' else '⚠️ pg_cron yok ya da kurulamadi' end
  union all
  select 4, 'Tavan sayaci zaman kisitli mi',
         case when (select pg_get_functiondef(p.oid) from pg_proc p
                     join pg_namespace n on n.oid=p.pronamespace
                    where n.nspname='public' and p.proname='trg_acik_istek_tavani')
                   like '%avail_date >= current_date%'
              then 'evet' else 'HAYIR' end,
         case when (select pg_get_functiondef(p.oid) from pg_proc p
                     join pg_namespace n on n.oid=p.pronamespace
                    where n.nspname='public' and p.proname='trg_acik_istek_tavani')
                   like '%avail_date >= current_date%'
              then '✅ eski istekler tavani doldurmuyor'
              else '❌ 274 §2 kurulmamis' end
  union all
  select 5, 'Vitrin ile kapi ayni kosulu mu kullaniyor',
         case when (select pg_get_functiondef(p.oid) from pg_proc p
                     join pg_namespace n on n.oid=p.pronamespace
                    where n.nspname='public' and p.proname='acik_istek_tavanim')
                   like '%avail_date >= current_date%'
              then 'evet' else 'HAYIR' end,
         case when (select pg_get_functiondef(p.oid) from pg_proc p
                     join pg_namespace n on n.oid=p.pronamespace
                    where n.nspname='public' and p.proname='acik_istek_tavanim')
                   like '%avail_date >= current_date%'
              then '✅ cip kapiyla ayni' else '❌ 274 §3 kurulmamis' end
  union all
  select 6, 'Supurucu kapatmayi krediden ayirdi mi',
         case when (select pg_get_functiondef(p.oid) from pg_proc p
                     join pg_namespace n on n.oid=p.pronamespace
                    where n.nspname='public' and p.proname='bayat_istekleri_iade_et')
                   not like '%and exists (select 1 from credit_ledger cl%where cl.ref_id = req.id and cl.reason = ''request_hold''%'
              then 'evet' else 'HAYIR' end,
         '✅ ucretsiz istekler de kapaniyor'
) x order by s;

-- ----------------------------------------------------------------------
-- kural_kosullari   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.kural_kosullari(p_avail_id uuid)
 RETURNS TABLE(sira integer, kod text, metin text, durum text, agirlik text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d jsonb; v_av availabilities%rowtype; v_vis visits%rowtype; v_prog lounge_programs%rowtype;
  v_flight text; v_uyum boolean; v_n int; v_i int := 0;
begin
  select * into v_av from availabilities where id = p_avail_id;
  if not found then return; end if;

  -- Misafirin ilanla çakışan seyahati (uçuşlu olan önce)
  select * into v_vis from visits v
   where v.user_id = auth.uid() and v.airport_code = v_av.airport_code
     and v.visit_date = v_av.avail_date
   order by (coalesce(v.flight_number,'') <> '') desc, v.created_at desc
   limit 1;
  v_flight := nullif(v_vis.flight_number, '');

  d := public.lounge_access_decision_v6(p_avail_id, v_flight,
         coalesce(v_vis.carrier_code, public.guest_carrier_for(p_avail_id)), v_vis.id);
  select * into v_prog from lounge_programs where id = nullif(d ->> 'program_id','')::uuid;

  -- ── KAPI SATIRLARI ────────────────────────────────────────────
  -- 1 · misafir hakkı
  v_n := nullif(d ->> 'guest_included_count','')::int;
  v_i := v_i + 1; sira := v_i; kod := 'misafir_hakki'; agirlik := 'kapi';
  if (d ->> 'guest_policy') = 'included' then
    durum := 'ok';
    metin := case when coalesce(v_n,0) > 0 then format('Misafir hakkı var · %s kişilik', v_n) else 'Misafir hakkı var' end;
  elsif (d ->> 'guest_policy') = 'paid' then
    durum := 'ok'; agirlik := 'not';
    metin := coalesce(nullif(d ->> 'guest_fee_note',''), 'Misafir ücretli girer');
  elsif (d ->> 'guest_policy') = 'not_allowed' then
    durum := 'yok'; metin := 'Bu kart misafir almıyor';
  else
    durum := 'bilinmiyor'; metin := 'Misafir hakkı doğrulanmadı';
  end if;
  return next;

  -- 2 · havayolu şartı
  v_i := v_i + 1; sira := v_i; kod := 'havayolu'; agirlik := 'kapi';
  if coalesce(d ->> 'flight_coupling','any') in ('any','none') and (d ->> 'carrier_known') is null then
    durum := 'ok'; agirlik := 'not'; metin := 'Havayolu şartı yok';
  elsif (d ->> 'carrier_known') is null or (d ->> 'carrier_known') = 'false' then
    durum := 'bilinmiyor'; metin := 'Havayolu şartı bilinmiyor · uçuşunu gir';
  elsif (d ->> 'carrier_ok') = 'true' then
    durum := 'ok';
    metin := case when coalesce(d ->> 'host_carrier','') <> ''
                  then format('Aynı havayolu · %s', upper(d ->> 'host_carrier')) else 'Havayolu şartı sağlanıyor' end;
  else
    durum := 'yok';
    metin := format('Havayolu şartı tutmuyor · %s ↔ %s', upper(coalesce(d ->> 'host_carrier','?')), upper(coalesce(d ->> 'guest_carrier','?')));
  end if;
  return next;

  -- 3 · uçuş bağı
  v_i := v_i + 1; sira := v_i; kod := 'ucus_bagi'; agirlik := 'kapi';
  if coalesce(d ->> 'flight_coupling','none') in ('none','any') then
    durum := 'ok'; agirlik := 'not'; metin := 'Uçuş birlikteliği şartı yok';
  else
    v_uyum := coalesce(v_flight,'') <> '' and coalesce(v_av.flight_number,'') <> ''
              and upper(replace(v_flight,' ','')) = upper(replace(v_av.flight_number,' ',''));
    if (d ->> 'flight_coupling') = 'same_flight' then
      durum := case when v_uyum then 'ok' when coalesce(v_flight,'') = '' then 'bilinmiyor' else 'yok' end;
      metin := case when v_uyum then 'Aynı uçuş şartı sağlanıyor'
                    when coalesce(v_flight,'') = '' then 'Aynı uçuş şartı var · uçuşunu gir'
                    else 'Aynı uçuş şartı sağlanmıyor' end;
    else
      durum := 'bilinmiyor'; metin := 'Birlikte varış gerekir · kapıda beraber olun';
    end if;
  end if;
  return next;

  -- 4 · kişi sayısı (283/1)
  v_i := v_i + 1; sira := v_i; kod := 'kisi_sayisi'; agirlik := 'kapi';
  if (d ->> 'party_ok') = 'true' then
    durum := 'ok';
    metin := case when (d ->> 'party_size')::int > 1
                  then format('%s kişi · hak yetiyor', d ->> 'party_size') else 'Tek kişi · hak yetiyor' end;
  elsif (d ->> 'party_ok') = 'false' then
    durum := 'yok'; metin := format('%s kişisin, hak %s kişilik', d ->> 'party_size', d ->> 'party_limit');
  else
    durum := 'bilinmiyor'; metin := 'Kişi sayısı şartı doğrulanamadı';
  end if;
  return next;

  -- 5 · iç hat / dış hat (283/7)
  v_i := v_i + 1; sira := v_i; kod := 'hat'; agirlik := 'kapi';
  if (d ->> 'scope_ok') = 'true' then
    durum := 'ok'; agirlik := 'not';
    metin := case (d ->> 'venue_scope') when 'domestic' then 'İç hatlar salonu · uçuşun iç hat'
                                         when 'international' then 'Dış hatlar salonu · uçuşun dış hat'
                                         else 'Salon her iki hatta da açık' end;
  elsif (d ->> 'scope_ok') = 'false' then
    durum := 'yok';
    metin := case (d ->> 'venue_scope') when 'domestic' then 'Salon iç hatta, uçuşun dış hat' else 'Salon dış hatta, uçuşun iç hat' end;
  else
    durum := 'bilinmiyor';
    metin := case (d ->> 'venue_scope') when 'domestic' then 'İç hatlar salonu · varış noktanı gir'
                                         else 'Dış hatlar salonu · varış noktanı gir' end;
  end if;
  return next;

  -- 6 · host kotası (283/12) — yalnız biliniyorsa
  if coalesce((d #>> '{quota,known}')::boolean, false) then
    v_i := v_i + 1; sira := v_i; kod := 'host_kotasi'; agirlik := 'kapi';
    if (d ->> 'quota_ok') = 'true' then
      durum := 'ok'; metin := format('Host''un bu dönem %s hakkı kaldı', d #>> '{quota,left}');
    else
      durum := 'yok'; metin := format('Host''un dönem hakkı bitmiş · %s/%s', d #>> '{quota,used}', d #>> '{quota,total}');
    end if;
    return next;
  end if;

  -- 7 · bilet sınıfı (283/11) — yalnız bilet sınıfı programında
  if (d ->> 'cabin_required') = 'true' then
    v_i := v_i + 1; sira := v_i; kod := 'bilet_sinifi'; agirlik := 'kapi';
    if (d ->> 'cabin_ok') = 'true' then durum := 'ok'; metin := format('Host %s uçuyor · hak geçerli', upper(d ->> 'host_cabin'));
    elsif (d ->> 'cabin_ok') = 'false' then durum := 'yok'; metin := 'Host ekonomi uçuyor · bilet sınıfı hakkı yok';
    else durum := 'bilinmiyor'; metin := 'Host''un kabin sınıfı bilinmiyor'; end if;
    return next;
  end if;

  -- 8 · çocuk (283/2) — yalnız çocuk varsa
  if (d ->> 'has_child') = 'true' then
    v_i := v_i + 1; sira := v_i; kod := 'cocuk'; agirlik := 'kapi';
    if (d ->> 'children_ok') = 'true' then
      durum := 'ok';
      metin := case when (d ->> 'children_policy') = 'free_under'
                    then format('%s yaş altı haktan sayılmıyor', d ->> 'child_age_limit') else 'Çocuk misafir kabul ediliyor' end;
    elsif (d ->> 'children_ok') = 'false' then
      durum := 'yok';
      metin := case when (d ->> 'children_policy') = 'age_limit'
                    then format('%s yaş altı alınmıyor', d ->> 'child_age_limit') else 'Salon çocuk misafir almıyor' end;
    else durum := 'bilinmiyor'; metin := 'Çocuk kuralı doğrulanmadı · kapıda sor'; end if;
    return next;
  end if;

  -- 9 · varış salonu (283/8) — yalnız salon tek yönlüyse
  if (d ->> 'serves') in ('arrival') then
    v_i := v_i + 1; sira := v_i; kod := 'varis_salonu'; agirlik := 'kapi';
    if (d ->> 'serves_ok') = 'true' then durum := 'ok'; metin := 'Varış salonu · aktarma yolcususun';
    else durum := 'yok'; metin := 'Varış salonu · kalkış öncesi giriş yok'; end if;
    return next;
  end if;

  -- 10 · host yanında (283/9)
  if v_prog.id is not null and coalesce(v_prog.member_must_be_present, false) then
    v_i := v_i + 1; sira := v_i; kod := 'host_yaninda'; agirlik := 'kapi'; durum := 'ok';
    metin := 'Host giriş anında yanında olmalı';
    return next;
  end if;

  -- ── NOTLAR ────────────────────────────────────────────────────
  -- 11 · aynı gün + biniş kartı (283/10)
  v_i := v_i + 1; sira := v_i; kod := 'binis_karti'; agirlik := 'not';
  if (d ->> 'boarding_pass_ok') = 'true' then durum := 'ok'; metin := format('Biniş kartın aynı gün · %s', upper(v_flight));
  elsif (d ->> 'boarding_pass_ok') = 'false' then durum := 'yok'; metin := 'Biniş kartının tarihi ilanla uyuşmuyor';
  else durum := 'yok'; metin := 'Uçuş numarası doğrulanmadı'; end if;
  return next;

  -- 12 · ücret (283/5) — yalnız ücretli politikada
  if (d ->> 'guest_policy') = 'paid' then
    v_i := v_i + 1; sira := v_i; kod := 'ucret'; agirlik := 'not';
    if (d ->> 'fee_payer') = 'member_card' then durum := 'ok'; metin := 'Ücreti host''un kartı karşılıyor';
    elsif (d ->> 'fee_payer') = 'guest_at_door' then
      durum := 'ok';
      metin := case when nullif(d ->> 'guest_fee_amount','') is not null
                    then format('Kapıda ödersin · ~%s %s', trim(to_char((d ->> 'guest_fee_amount')::numeric,'FM999990')), coalesce(d ->> 'guest_fee_currency',''))
                    else 'Ücreti kapıda misafir öder' end;
    else durum := 'bilinmiyor'; metin := 'Ücreti kimin ödediği doğrulanmadı'; end if;
    return next;
  end if;

  -- 13 · kalış süresi (283/6)
  if nullif(d ->> 'max_stay_hours','') is not null then
    v_i := v_i + 1; sira := v_i; kod := 'kalis'; agirlik := 'not';
    if (d ->> 'stay_ok') = 'false' then
      durum := 'yok'; metin := format('Kalış sınırı %s saat · planın %s saat',
                                       trim(to_char((d ->> 'max_stay_hours')::numeric,'FM990.0')),
                                       trim(to_char((d ->> 'planned_hours')::numeric,'FM990.0')));
    else
      durum := 'ok'; metin := format('Kalış sınırı %s saat', trim(to_char((d ->> 'max_stay_hours')::numeric,'FM990.0')));
    end if;
    return next;
  end if;

  -- 14 · doluluk (283/3) — yalnız kayıt varsa
  if coalesce((d ->> 'capacity_refusals_60d')::int, 0) > 0 then
    v_i := v_i + 1; sira := v_i; kod := 'doluluk'; agirlik := 'not';
    durum := case when (d ->> 'capacity_refusals_60d')::int >= 2 then 'yok' else 'ok' end;
    metin := format('Bu saatlerde %s kez doluluk reddi (60 gün)', d ->> 'capacity_refusals_60d');
    return next;
  end if;

  -- 15 · kabin (bilet sınıfı programı değilse yalnız not)
  if (d ->> 'cabin_required') <> 'true' and coalesce(v_av.cabin_class,'') <> '' then
    v_i := v_i + 1; sira := v_i; kod := 'kabin'; agirlik := 'not'; durum := 'ok';
    metin := format('Host kabini · %s', upper(v_av.cabin_class));
    return next;
  end if;

  -- 284 · kural güncelliği (not)
  if (d -> 'freshness') is not null then
    v_i := v_i + 1; sira := v_i; kod := 'guncellik'; agirlik := 'not';
    if (d #>> '{freshness,durum}') = 'supheli' then
      durum := 'yok'; metin := format('Kural kapıda %s kez tutmadı · doğrulanıyor', d #>> '{freshness,acik_suphe}');
    elsif (d #>> '{freshness,durum}') = 'dogrulandi' then
      durum := 'ok'; metin := case when (d #>> '{freshness,gun}') is null then 'Kural kapıda doğrulandı'
                                    else format('Kural %s gün önce doğrulandı', d #>> '{freshness,gun}') end;
    elsif (d #>> '{freshness,durum}') = 'eski' then
      durum := 'bilinmiyor'; metin := format('Kural %s gün önce doğrulandı · eskimiş olabilir', d #>> '{freshness,gun}');
    else durum := 'bilinmiyor'; metin := 'Kural henüz kapıda doğrulanmadı'; end if;
    return next;
  end if;

  -- 16 · biniş kartı & kimlik gerekli
  if v_prog.id is not null and coalesce(v_prog.guest_needs_boarding_pass, false) then
    v_i := v_i + 1; sira := v_i; kod := 'belge'; agirlik := 'not'; durum := 'ok';
    metin := 'Kendi biniş kartın ve kimliğin gerekir';
    return next;
  end if;
end $function$;

do $$
begin
  if pg_get_functiondef('public.lounge_access_decision_v6'::regproc) not like '%kural_guncelligi%' then raise exception '284: v6 guncellik okumuyor'; end if;
  if pg_get_functiondef('public.kural_kosullari'::regproc) not like '%guncellik%' then raise exception '284: kural_kosullari guncellik satiri yok'; end if;
  raise notice '284: v6 + kural_kosullari guncellik (acik tanim)';
end $$;

-- ----------------------------------------------------------------------
-- kural_kart_adi   [etkin kaynak: 275_kural_kosullari.sql]
-- ----------------------------------------------------------------------
create or replace function public.kural_kart_adi(p_avail_id uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce(p.name, p.code, 'Kart')
    from availabilities a
    left join lounge_programs p on p.id = a.program_id
   where a.id = p_avail_id;
$$;

-- ----------------------------------------------------------------------
-- push_kanali   [etkin kaynak: 278_push_kanali_enum.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.push_kanali(p_category notif_category)
returns text
language sql
immutable
set search_path = public
as $$ select public.push_kanali(p_category::text) $$;

comment on function public.push_kanali(notif_category) is
  'ENUM aşırı yüklemesi. `notify_push` tetikleyicisi kategoriyi enum '
  'olarak geçiyor; PostgreSQL enum→text örtük dönüşüm yapmadığı için '
  '276 tek başına çalışma anında patlıyordu (bkz. 278 başlığı).';

revoke all on function public.push_kanali(notif_category) from public;
grant execute on function public.push_kanali(notif_category)
  to authenticated, service_role;

-- ── NÖBETÇİ 1: ÜRÜNÜN ÇAĞIRDIĞI TİPLE ÇAĞIR ─────────────────────
-- 276'nın nöbetçisinin yapmadığı şey tam olarak bu.
do $$
declare v text;
begin
  -- ⚠️ ENUM DEĞERLERİ İNGİLİZCE: requests, sessions, invites,
  -- connections, system, safety, credits, ratings. İlk yazımda
  -- 'sohbet' geçtim ve nöbetçi "invalid input value for enum" dedi —
  -- yani nöbetçi, KENDİ yazarının kategori adlarını bilmediğini
  -- yakaladı. 276'yı yazarken de aynı varsayımı yapabilirdim.
  select public.push_kanali('safety'::notif_category) into v;
  if v <> 'guvenlik' then
    raise exception '278: safety → % (beklenen guvenlik)', v;
  end if;
  select public.push_kanali('requests'::notif_category) into v;
  if v <> 'akis' then
    raise exception '278: requests → % (beklenen akis)', v;
  end if;
  raise notice '278: enum asiri yuklemesi calisiyor (safety→guvenlik, requests→akis)';
end $$;

-- ----------------------------------------------------------------------
-- baglanti_kaldir   [etkin kaynak: 277_baglanti_kaldir.sql]
-- ----------------------------------------------------------------------
create or replace function public.baglanti_kaldir(p_conn_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_conn   connection_requests%rowtype;
  v_other  uuid;
  v_aktif  int;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  select * into v_conn from connection_requests where id = p_conn_id;
  if not found then
    raise exception 'connection_not_found';
  end if;

  -- Yalnız tarafları kaldırabilir. `security definer` olduğu için bu
  -- kontrol ŞART: RLS burada devre dışı.
  if v_uid <> v_conn.from_id and v_uid <> v_conn.to_id then
    raise exception 'not_your_connection';
  end if;

  v_other := case when v_conn.from_id = v_uid then v_conn.to_id else v_conn.from_id end;

  -- Aktif oturum varsa DUR (karar 3).
  select count(*) into v_aktif
    from sessions s
    join requests r on r.id = s.request_id
   where s.status = 'active'
     and ((r.host_id = v_uid and r.guest_id = v_other)
       or (r.guest_id = v_uid and r.host_id = v_other));
  if v_aktif > 0 then
    raise exception 'active_session_exists';
  end if;

  update connection_requests
     set status = 'declined'
   where id = p_conn_id;

  -- Sohbet kanalı kapanır: bağlantı yoksa kanal da yoktur.
  -- ⚠️ MESAJLAR SİLİNMİYOR. Silmek, karşı tarafın bir şikâyette
  -- delil olarak gösterebileceği yazışmayı yok eder — ve kaldırma
  -- eylemi bir delil temizleme aracına dönüşür.
  update chat_channels
     set active = false
   where connection_id = p_conn_id;

  return jsonb_build_object('ok', true, 'other_id', v_other);
end $$;

-- ----------------------------------------------------------------------
-- sogu_baslangic_ozeti   [etkin kaynak: 279_sogu_baslangic.sql]
-- ----------------------------------------------------------------------
create or replace function public.sogu_baslangic_ozeti(p_airport text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_salon    int := 0;
  v_program  int := 0;
  v_hak      int := 0;
  v_benim    boolean := false;
  v_uid      uuid := auth.uid();
begin
  if p_airport is null or length(trim(p_airport)) = 0 then
    return jsonb_build_object('salon', 0, 'program', 0, 'hak', 0,
                              'kartin_uygun', false);
  end if;

  select count(distinct l.id) into v_salon
    from lounges l
   where upper(l.airport_code) = upper(trim(p_airport));

  -- Misafir hakkı VEREN program sayısı. `guest_allowance > 0` tek
  -- ölçüt: "aile serbest" ayrı bir kural ve misafir hakkı değil.
  -- 🔴 İLK YAZIMDA `lounge_guest_rules.venue_id` ÜZERİNDEN BAĞLADIM VE
  -- SONUÇ HER HAVALİMANINDA 0 ÇIKTI. Ölçtüm: 262 kuralın 141'i misafir
  -- hakkı veriyor ama hiçbiri bir SALONA bağlı değil — hepsi PROGRAM
  -- düzeyinde ("bu kart programı N misafir verir, nerede olursa olsun").
  -- Salona bağlanma yolu `lounge_venue_acceptance`: hangi mekân hangi
  -- programı kabul ediyor.
  --
  -- Nöbetçi bunu yakaladı çünkü GERÇEK BİR SAYI bekliyor; "0 döndü ama
  -- çalıştı" diye geçseydi ekran her havalimanında boş bir cümle
  -- kuracaktı.
  --
  -- 🆕 SINIF: "BİR JOIN'İN ÇALIŞMASI, DOĞRU TABLOYA BAĞLANDIĞI ANLAMINA
  -- GELMEZ — SIFIR SATIR DA GEÇERLİ BİR SONUÇTUR VE EN SESSİZ HATADIR."
  select count(distinct r.program_id), coalesce(max(r.guest_allowance), 0)
    into v_program, v_hak
    from lounges l
    join lounge_venue_acceptance a on a.venue_id = l.venue_id
    join lounge_guest_rules r on r.program_id = a.program_id
   where upper(l.airport_code) = upper(trim(p_airport))
     and coalesce(r.guest_allowance, 0) > 0;

  -- ── EN DEĞERLİ SATIR: KULLANICININ KENDİ KARTI UYGUN MU? ──────
  -- 🔴 Bu, boş ekranı bir davete çeviren şey. Kullanıcıya "birileri
  -- host olabilir" demek soyut; "SENİN kartın bu havalimanında
  -- misafir hakkı veriyor" demek somut ve eyleme çağırır.
  if v_uid is not null then
    select exists (
      select 1
        from user_cards uc
        join lounge_guest_rules r on r.program_id = uc.program_id
        join lounge_venue_acceptance a on a.program_id = uc.program_id
        join lounges l on l.venue_id = a.venue_id
       where uc.user_id = v_uid
         and upper(l.airport_code) = upper(trim(p_airport))
         and coalesce(r.guest_allowance, 0) > 0
    ) into v_benim;
  end if;

  return jsonb_build_object(
    'salon',        v_salon,
    'program',      v_program,
    'hak',          v_hak,
    'kartin_uygun', coalesce(v_benim, false));
end $$;

-- ----------------------------------------------------------------------
-- istegin_acik_oturumu_var_mi   [etkin kaynak: 280_kredi_ve_durum_kilidi.sql]
-- ----------------------------------------------------------------------
create or replace function public.istegin_acik_oturumu_var_mi(p_req uuid)
returns boolean language sql stable set search_path = public as $$
  select exists (select 1 from sessions s
                  where s.request_id = p_req and s.status in ('pending','active'))
$$;

-- ----------------------------------------------------------------------
-- istek_kredisi_iade   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ⚠ Bu fonksiyon 3 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.istek_kredisi_iade(p_req uuid, p_reason text, p_ref uuid default null::uuid)
returns integer
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_r      requests%rowtype;
  v_tutulan int;
  v_bal    int;
  v_thanks record;
  v_iade   int := 0;
begin
  select * into v_r from requests where id = p_req;
  if not found then return 0; end if;

  -- İDEMPOTENT: bu istek için herhangi bir iade zaten yazılmışsa DUR.
  if exists (select 1 from credit_ledger
              where ref_id = p_req
                and reason in ('request_refund','request_cancel_refund',
                               'session_cancel_refund','expired_refund',
                               'no_show_refund','request_stale_refund',
                               'kapida_ret_iade','dispute_refund')) then
    return 0;
  end if;

  -- Ne tutulduysa o iade edilir — tek kaynaktan (Bölüm 0).
  -- Tutma kaydı ÜÇ ADLA yazılıyor: `request_hold` (bedel>0),
  -- `request_free_tier` (bedel 0) ve 🔴 `invite_hold` (davet kabulü) —
  -- sonuncusu 299'a kadar hiçbir iade yolunda tanınmıyordu.
  v_tutulan := public.tutulan_kredi(p_req);

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_r.guest_id;

  if v_tutulan > 0 then
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
    values (v_r.guest_id, v_tutulan, p_reason, coalesce(p_ref, p_req), v_bal + v_tutulan);
    v_iade := v_tutulan;
  else
    -- Bedel 0'dı (ya da tutma kaydı yok): iade YOK ama iz bırak —
    -- idempotency bu satıra bakıyor ve "0 iade edildi" de bir karardır.
    insert into credit_ledger (user_id, delta, reason, ref_id, balance_after, note)
    values (v_r.guest_id, 0, p_reason, coalesce(p_ref, p_req), v_bal,
            case when v_r.created_at >= public.tutma_varsayim_esigi()
                 then 'Tutma kaydi bulunamadi — iade 0 yazildi (299/C).' end);
  end if;

  -- K3 · ücretli misafir teşekkür kredisi geri alınır (varsa, bir kez)
  for v_thanks in
    select * from credit_ledger
     where reason = 'paid_guest_thanks:' || p_req::text
  loop
    if not exists (select 1 from credit_ledger
                    where reason = 'paid_guest_thanks_reversal:' || p_req::text
                      and user_id = v_thanks.user_id) then
      select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_thanks.user_id;
      insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
      values (v_thanks.user_id, -v_thanks.delta,
              'paid_guest_thanks_reversal:' || p_req::text, p_req, v_bal - v_thanks.delta);
    end if;
  end loop;

  return v_iade;
end $function$;

-- C2 · `trg_iade_tutulani_asamaz` — aynı iki düzeltme.

-- ----------------------------------------------------------------------
-- trg_iade_tutulani_asamaz   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.trg_iade_tutulani_asamaz()
returns trigger
language plpgsql
as $function$
declare v_tutulan int; v_iade int; v_req uuid;
begin
  if new.delta <= 0 or new.ref_id is null then return new; end if;
  if new.reason not in ('request_refund','request_cancel_refund','session_cancel_refund',
                        'expired_refund','no_show_refund','request_stale_refund',
                        'kapida_ret_iade','dispute_refund') then
    return new;
  end if;

  -- ref_id istek mi oturum mu? Oturumsa isteğe çevir.
  v_req := coalesce((select request_id from sessions where id = new.ref_id), new.ref_id);

  -- Tek kaynak (Bölüm 0). `ref_id` oturum kimliği de olabildiği için
  -- önce isteğe çevirdik; tutma satırı HER ZAMAN isteğe yazılır.
  v_tutulan := public.tutulan_kredi(v_req);

  select coalesce(sum(delta),0) into v_iade
    from credit_ledger
   where delta > 0
     and reason in ('request_refund','request_cancel_refund','session_cancel_refund',
                    'expired_refund','no_show_refund','request_stale_refund',
                    'kapida_ret_iade','dispute_refund')
     and ref_id in (new.ref_id, v_req,
                    (select id from sessions where request_id = new.ref_id));

  if v_iade + new.delta > v_tutulan then
    raise exception 'refund_exceeds_hold'
      using detail = format('istek/oturum %s: tutulan %s, iade edilmis %s, denenen +%s',
                            new.ref_id, v_tutulan, v_iade, new.delta);
  end if;
  return new;
end $function$;

-- C3 · `kapida_giremedim` ve `bayat_istekleri_iade_et` — iki düzeltme:
--      (a) `invite_hold` da tutma sayılıyor,
--      (b) iade tutarı SABİT 1 değil, GERÇEKTEN TUTULAN kadar.
do $$
declare v_def text; v_yeni text; v_capa text; v_ek text; v_n int;
begin
  -- ── kapida_giremedim ────────────────────────────────────────────────
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'kapida_giremedim';
  if v_def is null then raise exception '299/C3: kapida_giremedim bulunamadi'; end if;
  v_yeni := v_def;

  -- Tekrar koşulabilirlik: zaten uygulanmışsa çapa yoktur ve bu bir HATA
  -- DEĞİLDİR. Ama "çapa yok" ile "zaten uygulanmış" ayrı ayrı ölçülmeli —
  -- ikisini aynı sessiz dala koymak, bozulmayı başarı gibi gösterir.
  if position('tutma_sebepleri' in v_def) > 0 then
    raise notice '299/C3: kapida_giremedim zaten duzeltilmis — atlandi.';
  else

  -- (a) tutma adı listesi
  v_capa := 'where cl.ref_id = v_req.id and cl.reason = ''request_hold'' and cl.delta < 0';
  if position(v_capa in v_yeni) = 0 then
    raise exception '299/C3: kapida_giremedim tutma capasi bulunamadi';
  end if;
  v_yeni := replace(v_yeni, v_capa,
    'where cl.ref_id = v_req.id and cl.reason = any (public.tutma_sebepleri()) and cl.delta < 0');

  -- (b) sabit 1 → gerçekten tutulan
  v_capa := 'values (v_req.guest_id, 1, ''kapida_ret_iade'', v_req.id, v_bal + 1,';
  if position(v_capa in v_yeni) = 0 then
    raise exception '299/C3: kapida_giremedim iade tutari capasi bulunamadi';
  end if;
  v_ek :=
    'values (v_req.guest_id, public.tutulan_kredi(v_req.id), ''kapida_ret_iade'', v_req.id,' || E'\n'
 || '            v_bal + public.tutulan_kredi(v_req.id),';
  v_yeni := replace(v_yeni, v_capa, v_ek);

  if v_yeni = v_def then raise exception '299/C3: kapida_giremedim degismedi'; end if;
  execute v_yeni;
  raise notice '299/C3: kapida_giremedim duzeltildi.';
  end if;

  -- ── bayat_istekleri_iade_et ─────────────────────────────────────────
  -- Bu yol yalnız `pending` istekleri kapatır; davetle açılan istek
  -- `accepted` doğar, yani (a) düzeltmesi burada DAVRANIŞ DEĞİŞTİRMEZ.
  -- Yine de listeyi tek kaynağa bağlıyoruz: iki liste = iki gerçek.
  -- (b) düzeltmesi burada GERÇEKTEN gerekli — bedel 2 olabiliyor.
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'bayat_istekleri_iade_et';
  if v_def is null then raise exception '299/C3: bayat_istekleri_iade_et bulunamadi'; end if;
  v_yeni := v_def;

  if position('invite_hold' in v_def) > 0 then
    raise notice '299/C3: bayat_istekleri_iade_et zaten duzeltilmis — atlandi.';
  else

  v_capa := 'where cl.ref_id = r.id and cl.reason = ''request_hold'' and cl.delta < 0';
  if position(v_capa in v_yeni) = 0 then
    raise exception '299/C3: bayat tutma capasi bulunamadi';
  end if;
  -- ⚠️ BURADA `request_free_tier` KASITLA DIŞARIDA: harcanmayan kredi
  -- iade edilmez. Bu yüzden `tutma_sebepleri()` DEĞİL, elle iki ad.
  v_yeni := replace(v_yeni, v_capa,
    'where cl.ref_id = r.id and cl.reason in (''request_hold'',''invite_hold'') and cl.delta < 0');

  v_capa := 'values (r.guest_id, 1, ''request_stale_refund'', r.id, v_bal + 1,';
  if position(v_capa in v_yeni) = 0 then
    raise exception '299/C3: bayat iade tutari capasi bulunamadi';
  end if;
  v_ek :=
    'values (r.guest_id, public.tutulan_kredi(r.id), ''request_stale_refund'', r.id,' || E'\n'
 || '                v_bal + public.tutulan_kredi(r.id),';
  v_yeni := replace(v_yeni, v_capa, v_ek);

  if v_yeni = v_def then raise exception '299/C3: bayat_istekleri_iade_et degismedi'; end if;
  execute v_yeni;
  raise notice '299/C3: bayat_istekleri_iade_et duzeltildi.';
  end if;

  select count(*) into v_n from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname in ('kapida_giremedim','bayat_istekleri_iade_et')
     and p.prosrc like '%tutma_sebepleri%invite_hold%' escape '~';
end $$;

-- ----------------------------------------------------------------------
-- tek_tarafli_oturumlari_kapat   [etkin kaynak: 280_kredi_ve_durum_kilidi.sql]
-- ----------------------------------------------------------------------
create or replace function public.tek_tarafli_oturumlari_kapat()
returns int language plpgsql security definer set search_path = public as $$
declare v_n int := 0; v_s record;
begin
  for v_s in
    select s.id, s.request_id, s.host_confirmed, s.guest_confirmed, r.host_id, r.guest_id
      from sessions s
      join requests r on r.id = s.request_id
      join availabilities a on a.id = r.avail_id
     where s.status = 'active'
       and (a.avail_date + a.time_to)::timestamp
           < (now() at time zone 'Europe/Istanbul') - interval '2 hours'
  loop
    if coalesce(v_s.host_confirmed,false) or coalesce(v_s.guest_confirmed,false) then
      update sessions set status = 'completed', completed_at = now(),
             cancel_reason = 'auto_completed_one_sided' where id = v_s.id;
      update requests set status = 'completed' where id = v_s.request_id;
    else
      update sessions set status = 'expired', completed_at = now(),
             cancel_reason = 'expired' where id = v_s.id;
      update requests set status = 'cancelled' where id = v_s.request_id;
      perform public.istek_kredisi_iade(v_s.request_id, 'expired_refund', v_s.id);
    end if;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- ----------------------------------------------------------------------
-- hesap_kapisi   [etkin kaynak: 282_ban_ve_kvkk_silme.sql]
-- ----------------------------------------------------------------------
create or replace function public.hesap_kapisi(p_uid uuid default auth.uid())
returns void language plpgsql stable security definer set search_path = public as $$
declare v_ban timestamptz; v_del timestamptz;
begin
  if p_uid is null then raise exception 'not_authenticated'; end if;
  select banned_at, deleted_at into v_ban, v_del from users where id = p_uid;
  if v_ban is not null then raise exception 'account_banned'; end if;
  if v_del is not null then raise exception 'account_deleted'; end if;
end $$;

-- ----------------------------------------------------------------------
-- trg_mesaj_hesap_kapisi   [etkin kaynak: 282_ban_ve_kvkk_silme.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_mesaj_hesap_kapisi()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.hesap_kapisi(new.from_id);
  return new;
end $$;

-- ----------------------------------------------------------------------
-- ucus_hatti   [etkin kaynak: 283_kural_motoru_on_iki_boyut.sql]
-- ----------------------------------------------------------------------
create or replace function public.ucus_hatti(p_origin text, p_dest text)
returns text language sql stable set search_path = public as $$
  select case
    when p_dest is null or btrim(p_dest) = '' then null
    when (select a.country from airports a where a.code = p_dest) is null then null
    when (select a.country from airports a where a.code = p_dest) in ('Türkiye','Turkiye','TR','Turkey')
     and coalesce((select a.country from airports a where a.code = p_origin), 'Türkiye')
         in ('Türkiye','Turkiye','TR','Turkey')
      then 'domestic'
    else 'international' end
$$;

-- ----------------------------------------------------------------------
-- doluluk_reddi_sayisi   [etkin kaynak: 283_kural_motoru_on_iki_boyut.sql]
-- ----------------------------------------------------------------------
create or replace function public.doluluk_reddi_sayisi(p_avail_id uuid)
returns int language sql stable security definer set search_path = public as $$
  select count(*)::int
    from kapida_retler k
    join availabilities a on a.id = p_avail_id
    left join sessions s on s.id = k.session_id
    left join requests r on r.id = s.request_id
    left join availabilities a2 on a2.id = r.avail_id
   where k.sebep = 'kapasite_dolu'
     and k.created_at > now() - interval '60 days'
     and (k.lounge_id = a.lounge_id
          or (a.venue_id is not null and a2.venue_id = a.venue_id))
     and (a2.time_from is null
          or abs(extract(epoch from (a2.time_from - a.time_from))) <= 2*3600)
$$;

-- ----------------------------------------------------------------------
-- host_kota_durumu   [etkin kaynak: 283_kural_motoru_on_iki_boyut.sql]
-- ----------------------------------------------------------------------
create or replace function public.host_kota_durumu(p_avail_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_av availabilities%rowtype; v_he host_entitlements%rowtype; v_prog uuid;
begin
  select * into v_av from availabilities where id = p_avail_id;
  if not found then return jsonb_build_object('known', false); end if;
  v_prog := v_av.program_id;
  if v_prog is null then
    v_prog := nullif(public.lounge_access_decision_prebase(p_avail_id) ->> 'program_id','')::uuid;
  end if;
  if v_prog is null then return jsonb_build_object('known', false); end if;
  select * into v_he from host_entitlements
   where user_id = v_av.host_id and program_id = v_prog
   order by verified desc, self_reported_at desc nulls last limit 1;
  if not found then return jsonb_build_object('known', false); end if;
  return public.entitlement_remaining(v_he.id) || jsonb_build_object('entitlement_id', v_he.id);
end $$;

-- ----------------------------------------------------------------------
-- lounge_access_decision_v6   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.lounge_access_decision_v6(p_avail_id uuid, p_guest_flight text DEFAULT NULL::text, p_guest_carrier text DEFAULT NULL::text, p_guest_visit_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d jsonb; v_av availabilities%rowtype; v_vis visits%rowtype; v_venue lounge_venues%rowtype;
  v_prog lounge_programs%rowtype; v_acc lounge_venue_acceptance%rowtype;
  v_sev text; v_block text; v_notes text[] := '{}';
  v_party int; v_limit int; v_party_ok boolean;
  v_child_pol text; v_child_lim int; v_child_ok boolean; v_has_child boolean; v_min_child int;
  v_scope text; v_side text; v_scope_ok boolean;
  v_serves text; v_serves_ok boolean;
  v_fee_payer text;
  v_stay numeric; v_win numeric; v_stay_ok boolean;
  v_cap int;
  v_cabin_ok boolean; v_cabin_req boolean := false;
  v_kota jsonb; v_kota_ok boolean;
  v_flight_ok boolean; v_same_day boolean;
begin
  d := public.lounge_access_decision_v5(p_avail_id, p_guest_flight, p_guest_carrier);
  select * into v_av from availabilities where id = p_avail_id;
  if not found then return d; end if;
  if p_guest_visit_id is not null then
    select * into v_vis from visits where id = p_guest_visit_id;
  end if;
  select * into v_prog from lounge_programs where id = nullif(d ->> 'program_id','')::uuid;
  if (d ->> 'venue_id') is not null then
    select * into v_venue from lounge_venues where id = (d ->> 'venue_id')::uuid;
    if v_prog.id is not null then
      select * into v_acc from lounge_venue_acceptance
       where venue_id = v_venue.id and program_id = v_prog.id and active;
    end if;
  end if;
  v_sev := coalesce(d ->> 'severity', 'info');

  -- 1 · KİŞİ SAYISI. Misafir 1 kişi sayar; visits.party_size yoksa 1.
  v_party := coalesce(v_vis.party_size, 1);
  v_limit := nullif(d ->> 'guest_included_count','')::int;
  if (d ->> 'guest_policy') = 'included' then
    v_party_ok := v_limit is null or v_party <= greatest(v_limit, 1);
    if v_party_ok is false then
      v_block := coalesce(v_block, 'party_too_big');
      v_notes := v_notes || format('Bu hak %s misafir alıyor, sen %s kişisin.', v_limit, v_party);
    end if;
  elsif (d ->> 'guest_policy') = 'paid' then
    v_party_ok := true;   -- ücretli: kişi başı ödenir, kapı kapanmaz
  else
    v_party_ok := null;
  end if;

  -- 2 · ÇOCUK. Politika NULL ise bilinmiyor; uydurmuyoruz.
  v_has_child := v_vis.child_ages is not null and array_length(v_vis.child_ages,1) > 0;
  v_child_pol := coalesce(v_acc.children_policy, v_prog.children_policy);
  v_child_lim := coalesce(v_acc.child_age_limit, v_prog.child_age_limit);
  if v_has_child then
    select min(x) into v_min_child from unnest(v_vis.child_ages) x;
    if v_child_pol is null then v_child_ok := null;
    elsif v_child_pol = 'allowed' then v_child_ok := true;
    elsif v_child_pol = 'not_allowed' then v_child_ok := false;
    elsif v_child_pol = 'age_limit' then v_child_ok := v_child_lim is null or v_min_child >= v_child_lim;
    else v_child_ok := true;  -- free_under: girer, üstelik haktan sayılmaz
    end if;
    if v_child_ok is false then
      v_block := 'children_not_allowed';   -- kişi sayısından ÖNCE gelir: çocuk hiç giremiyorsa sayı anlamsız
      v_notes := v_notes || (case when v_child_pol = 'age_limit'
        then format('Bu salon %s yaş altını almıyor.', v_child_lim)
        else 'Bu salon çocuk misafir almıyor.' end)::text;
    end if;
    -- free_under: küçük çocuklar kişi sayısından düşer
    if v_child_pol = 'free_under' and v_child_lim is not null and v_party_ok is false then
      if v_party - (select count(*) from unnest(v_vis.child_ages) x where x < v_child_lim)
         <= greatest(coalesce(v_limit,0),1) then
        v_party_ok := true; v_block := null;
        v_notes := array_remove(v_notes, v_notes[array_length(v_notes,1)]);
      end if;
    end if;
  end if;

  -- 7 · İÇ HAT / DIŞ HAT. Dış hat salonu pasaport kontrolünün ARKASINDA;
  -- iç hat yolcusu fiziksel olarak ulaşamaz. Bu bir kural değil, duvar.
  v_scope := coalesce(v_venue.scope, 'both');
  v_side  := public.ucus_hatti(v_av.airport_code, v_vis.destination);
  if v_venue.id is null or v_scope = 'both' or v_side is null then
    v_scope_ok := case when v_venue.id is null or v_scope = 'both' then true else null end;
  else
    v_scope_ok := (v_scope = v_side);
    if not v_scope_ok then
      v_block := coalesce(v_block, 'scope_mismatch');
      v_notes := v_notes || (case when v_side = 'domestic'
        then 'Salon dış hatlar tarafında; iç hat uçuşuyla oraya geçilemez.'
        else 'Salon iç hatlar tarafında; dış hat uçuşuyla oraya geçilemez.' end)::text;
    end if;
  end if;

  -- 8 · KALKIŞ / VARIŞ SALONU
  v_serves := v_venue.serves;
  if v_serves is null or v_serves = 'both' then v_serves_ok := case when v_serves = 'both' then true else null end;
  else
    v_serves_ok := case when v_serves = 'arrival' then coalesce(v_vis.purpose,'') = 'connecting' else true end;
    if v_serves_ok is false then
      v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
      v_notes := v_notes || ('Bu bir varış salonu; kalkış öncesi giriş yok.')::text;
    end if;
  end if;

  -- 5 · ÜCRETİ KİM ÖDER (yalnız ücretli politikada anlamlı)
  v_fee_payer := coalesce(v_acc.fee_payer, v_prog.fee_payer);

  -- 6 · AZAMİ KALIŞ × misafirin planladığı pencere
  v_stay := nullif(d ->> 'max_stay_hours','')::numeric;
  if v_stay is not null and v_vis.id is not null then
    v_win := extract(epoch from (v_vis.time_to - v_vis.time_from)) / 3600.0;
    v_stay_ok := v_win <= v_stay + 0.01;
    if not v_stay_ok then
      v_notes := v_notes || format('Planladığın %s saat, salonun %s saatlik sınırını aşıyor; çıkıp yeniden girmek gerekebilir.',
                                   trim(to_char(v_win,'FM990.0')), trim(to_char(v_stay,'FM990.0')));
    end if;
  end if;

  -- 3 · DOLULUK: son 60 günde aynı saat bandında kapasite reddi
  v_cap := public.doluluk_reddi_sayisi(p_avail_id);
  if v_cap >= 2 then
    v_sev := case when v_sev in ('block') then v_sev else 'warn' end;
    v_notes := v_notes || format('Bu salon bu saatlerde son 60 günde %s kez doluluk nedeniyle misafir almadı.', v_cap);
  end if;

  -- 11 · BİLET SINIFI ŞARTI: bilet sınıfından doğan hak, business/first ister
  if v_prog.entitlement_model = 'ticket_class' then
    v_cabin_req := true;
    v_cabin_ok := case when v_av.cabin_class is null then null
                       else v_av.cabin_class in ('business','first') end;
    if v_cabin_ok is false then
      v_block := coalesce(v_block, 'cabin_required');
      v_notes := v_notes || ('Bu hak bilet sınıfından geliyor; host ekonomi uçuyorsa salon hakkı yok.')::text;
    end if;
  end if;

  -- 12 · HOST'UN DÖNEM KOTASI
  v_kota := public.host_kota_durumu(p_avail_id);
  if coalesce((v_kota ->> 'known')::boolean, false) then
    v_kota_ok := coalesce((v_kota ->> 'left')::int, 1) >= v_party;
    if not v_kota_ok then
      v_block := coalesce(v_block, 'quota_exhausted');
      v_notes := v_notes || format('Host''un bu dönem misafir hakkı bitmiş (%s/%s).',
                                   v_kota ->> 'used', v_kota ->> 'total');
    end if;
  end if;

  -- 10 · BİNİŞ KARTI AYNI GÜN: misafirin uçuşu kayıtlı ve tarih ilanla aynı
  v_same_day := v_vis.id is not null and v_vis.visit_date = v_av.avail_date;
  v_flight_ok := case when v_vis.id is null then null
                      when coalesce(v_vis.flight_number,'') = '' then null
                      else v_same_day end;

  -- 284: kural güncelliği — şüpheli kural en az UYARI, hiçbir şeyi değiştirmez
  declare v_g jsonb;
  begin
    if v_venue.id is not null and v_prog.id is not null then
      v_g := public.kural_guncelligi(v_venue.id, v_prog.id);
      if (v_g ->> 'durum') = 'supheli' then
        v_sev := case when v_sev = 'block' then 'block' else 'warn' end;
        v_notes := v_notes || format('Bu kural son 90 günde kapıda %s kez tutmadı — doğrulanıyor.', v_g ->> 'acik_suphe');
      elsif (v_g ->> 'durum') = 'eski' then
        v_notes := v_notes || ('Bu kural 90 günden eski ve yakın zamanda kapıda doğrulanmadı.')::text;
      end if;
      d := d || jsonb_build_object('freshness', v_g);
    end if;
  end;
  if v_block is not null then v_sev := 'block'; end if;

  return d || jsonb_build_object(
    'engine', 'v6',
    'severity', v_sev,
    'block_code', v_block,
    'party_size', v_party, 'party_limit', v_limit, 'party_ok', v_party_ok,
    'has_child', v_has_child, 'children_policy', v_child_pol, 'child_age_limit', v_child_lim, 'children_ok', v_child_ok,
    'venue_scope', v_scope, 'guest_side', v_side, 'scope_ok', v_scope_ok,
    'serves', v_serves, 'serves_ok', v_serves_ok,
    'fee_payer', v_fee_payer,
    'stay_ok', v_stay_ok, 'planned_hours', v_win,
    'capacity_refusals_60d', v_cap,
    'cabin_required', v_cabin_req, 'cabin_ok', v_cabin_ok, 'host_cabin', v_av.cabin_class,
    'quota', v_kota, 'quota_ok', v_kota_ok,
    'same_day', v_same_day, 'boarding_pass_ok', v_flight_ok,
    'detail', trim(both ' ' from coalesce(d ->> 'detail','') || ' ' || array_to_string(v_notes, ' ')));
end $function$;

CREATE OR REPLACE FUNCTION public.kural_kosullari(p_avail_id uuid)
 RETURNS TABLE(sira integer, kod text, metin text, durum text, agirlik text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d jsonb; v_av availabilities%rowtype; v_vis visits%rowtype; v_prog lounge_programs%rowtype;
  v_flight text; v_uyum boolean; v_n int; v_i int := 0;
begin
  select * into v_av from availabilities where id = p_avail_id;
  if not found then return; end if;

  -- Misafirin ilanla çakışan seyahati (uçuşlu olan önce)
  select * into v_vis from visits v
   where v.user_id = auth.uid() and v.airport_code = v_av.airport_code
     and v.visit_date = v_av.avail_date
   order by (coalesce(v.flight_number,'') <> '') desc, v.created_at desc
   limit 1;
  v_flight := nullif(v_vis.flight_number, '');

  d := public.lounge_access_decision_v6(p_avail_id, v_flight,
         coalesce(v_vis.carrier_code, public.guest_carrier_for(p_avail_id)), v_vis.id);
  select * into v_prog from lounge_programs where id = nullif(d ->> 'program_id','')::uuid;

  -- ── KAPI SATIRLARI ────────────────────────────────────────────
  -- 1 · misafir hakkı
  v_n := nullif(d ->> 'guest_included_count','')::int;
  v_i := v_i + 1; sira := v_i; kod := 'misafir_hakki'; agirlik := 'kapi';
  if (d ->> 'guest_policy') = 'included' then
    durum := 'ok';
    metin := case when coalesce(v_n,0) > 0 then format('Misafir hakkı var · %s kişilik', v_n) else 'Misafir hakkı var' end;
  elsif (d ->> 'guest_policy') = 'paid' then
    durum := 'ok'; agirlik := 'not';
    metin := coalesce(nullif(d ->> 'guest_fee_note',''), 'Misafir ücretli girer');
  elsif (d ->> 'guest_policy') = 'not_allowed' then
    durum := 'yok'; metin := 'Bu kart misafir almıyor';
  else
    durum := 'bilinmiyor'; metin := 'Misafir hakkı doğrulanmadı';
  end if;
  return next;

  -- 2 · havayolu şartı
  v_i := v_i + 1; sira := v_i; kod := 'havayolu'; agirlik := 'kapi';
  if coalesce(d ->> 'flight_coupling','any') in ('any','none') and (d ->> 'carrier_known') is null then
    durum := 'ok'; agirlik := 'not'; metin := 'Havayolu şartı yok';
  elsif (d ->> 'carrier_known') is null or (d ->> 'carrier_known') = 'false' then
    durum := 'bilinmiyor'; metin := 'Havayolu şartı bilinmiyor · uçuşunu gir';
  elsif (d ->> 'carrier_ok') = 'true' then
    durum := 'ok';
    metin := case when coalesce(d ->> 'host_carrier','') <> ''
                  then format('Aynı havayolu · %s', upper(d ->> 'host_carrier')) else 'Havayolu şartı sağlanıyor' end;
  else
    durum := 'yok';
    metin := format('Havayolu şartı tutmuyor · %s ↔ %s', upper(coalesce(d ->> 'host_carrier','?')), upper(coalesce(d ->> 'guest_carrier','?')));
  end if;
  return next;

  -- 3 · uçuş bağı
  v_i := v_i + 1; sira := v_i; kod := 'ucus_bagi'; agirlik := 'kapi';
  if coalesce(d ->> 'flight_coupling','none') in ('none','any') then
    durum := 'ok'; agirlik := 'not'; metin := 'Uçuş birlikteliği şartı yok';
  else
    v_uyum := coalesce(v_flight,'') <> '' and coalesce(v_av.flight_number,'') <> ''
              and upper(replace(v_flight,' ','')) = upper(replace(v_av.flight_number,' ',''));
    if (d ->> 'flight_coupling') = 'same_flight' then
      durum := case when v_uyum then 'ok' when coalesce(v_flight,'') = '' then 'bilinmiyor' else 'yok' end;
      metin := case when v_uyum then 'Aynı uçuş şartı sağlanıyor'
                    when coalesce(v_flight,'') = '' then 'Aynı uçuş şartı var · uçuşunu gir'
                    else 'Aynı uçuş şartı sağlanmıyor' end;
    else
      durum := 'bilinmiyor'; metin := 'Birlikte varış gerekir · kapıda beraber olun';
    end if;
  end if;
  return next;

  -- 4 · kişi sayısı (283/1)
  v_i := v_i + 1; sira := v_i; kod := 'kisi_sayisi'; agirlik := 'kapi';
  if (d ->> 'party_ok') = 'true' then
    durum := 'ok';
    metin := case when (d ->> 'party_size')::int > 1
                  then format('%s kişi · hak yetiyor', d ->> 'party_size') else 'Tek kişi · hak yetiyor' end;
  elsif (d ->> 'party_ok') = 'false' then
    durum := 'yok'; metin := format('%s kişisin, hak %s kişilik', d ->> 'party_size', d ->> 'party_limit');
  else
    durum := 'bilinmiyor'; metin := 'Kişi sayısı şartı doğrulanamadı';
  end if;
  return next;

  -- 5 · iç hat / dış hat (283/7)
  v_i := v_i + 1; sira := v_i; kod := 'hat'; agirlik := 'kapi';
  if (d ->> 'scope_ok') = 'true' then
    durum := 'ok'; agirlik := 'not';
    metin := case (d ->> 'venue_scope') when 'domestic' then 'İç hatlar salonu · uçuşun iç hat'
                                         when 'international' then 'Dış hatlar salonu · uçuşun dış hat'
                                         else 'Salon her iki hatta da açık' end;
  elsif (d ->> 'scope_ok') = 'false' then
    durum := 'yok';
    metin := case (d ->> 'venue_scope') when 'domestic' then 'Salon iç hatta, uçuşun dış hat' else 'Salon dış hatta, uçuşun iç hat' end;
  else
    durum := 'bilinmiyor';
    metin := case (d ->> 'venue_scope') when 'domestic' then 'İç hatlar salonu · varış noktanı gir'
                                         else 'Dış hatlar salonu · varış noktanı gir' end;
  end if;
  return next;

  -- 6 · host kotası (283/12) — yalnız biliniyorsa
  if coalesce((d #>> '{quota,known}')::boolean, false) then
    v_i := v_i + 1; sira := v_i; kod := 'host_kotasi'; agirlik := 'kapi';
    if (d ->> 'quota_ok') = 'true' then
      durum := 'ok'; metin := format('Host''un bu dönem %s hakkı kaldı', d #>> '{quota,left}');
    else
      durum := 'yok'; metin := format('Host''un dönem hakkı bitmiş · %s/%s', d #>> '{quota,used}', d #>> '{quota,total}');
    end if;
    return next;
  end if;

  -- 7 · bilet sınıfı (283/11) — yalnız bilet sınıfı programında
  if (d ->> 'cabin_required') = 'true' then
    v_i := v_i + 1; sira := v_i; kod := 'bilet_sinifi'; agirlik := 'kapi';
    if (d ->> 'cabin_ok') = 'true' then durum := 'ok'; metin := format('Host %s uçuyor · hak geçerli', upper(d ->> 'host_cabin'));
    elsif (d ->> 'cabin_ok') = 'false' then durum := 'yok'; metin := 'Host ekonomi uçuyor · bilet sınıfı hakkı yok';
    else durum := 'bilinmiyor'; metin := 'Host''un kabin sınıfı bilinmiyor'; end if;
    return next;
  end if;

  -- 8 · çocuk (283/2) — yalnız çocuk varsa
  if (d ->> 'has_child') = 'true' then
    v_i := v_i + 1; sira := v_i; kod := 'cocuk'; agirlik := 'kapi';
    if (d ->> 'children_ok') = 'true' then
      durum := 'ok';
      metin := case when (d ->> 'children_policy') = 'free_under'
                    then format('%s yaş altı haktan sayılmıyor', d ->> 'child_age_limit') else 'Çocuk misafir kabul ediliyor' end;
    elsif (d ->> 'children_ok') = 'false' then
      durum := 'yok';
      metin := case when (d ->> 'children_policy') = 'age_limit'
                    then format('%s yaş altı alınmıyor', d ->> 'child_age_limit') else 'Salon çocuk misafir almıyor' end;
    else durum := 'bilinmiyor'; metin := 'Çocuk kuralı doğrulanmadı · kapıda sor'; end if;
    return next;
  end if;

  -- 9 · varış salonu (283/8) — yalnız salon tek yönlüyse
  if (d ->> 'serves') in ('arrival') then
    v_i := v_i + 1; sira := v_i; kod := 'varis_salonu'; agirlik := 'kapi';
    if (d ->> 'serves_ok') = 'true' then durum := 'ok'; metin := 'Varış salonu · aktarma yolcususun';
    else durum := 'yok'; metin := 'Varış salonu · kalkış öncesi giriş yok'; end if;
    return next;
  end if;

  -- 10 · host yanında (283/9)
  if v_prog.id is not null and coalesce(v_prog.member_must_be_present, false) then
    v_i := v_i + 1; sira := v_i; kod := 'host_yaninda'; agirlik := 'kapi'; durum := 'ok';
    metin := 'Host giriş anında yanında olmalı';
    return next;
  end if;

  -- ── NOTLAR ────────────────────────────────────────────────────
  -- 11 · aynı gün + biniş kartı (283/10)
  v_i := v_i + 1; sira := v_i; kod := 'binis_karti'; agirlik := 'not';
  if (d ->> 'boarding_pass_ok') = 'true' then durum := 'ok'; metin := format('Biniş kartın aynı gün · %s', upper(v_flight));
  elsif (d ->> 'boarding_pass_ok') = 'false' then durum := 'yok'; metin := 'Biniş kartının tarihi ilanla uyuşmuyor';
  else durum := 'yok'; metin := 'Uçuş numarası doğrulanmadı'; end if;
  return next;

  -- 12 · ücret (283/5) — yalnız ücretli politikada
  if (d ->> 'guest_policy') = 'paid' then
    v_i := v_i + 1; sira := v_i; kod := 'ucret'; agirlik := 'not';
    if (d ->> 'fee_payer') = 'member_card' then durum := 'ok'; metin := 'Ücreti host''un kartı karşılıyor';
    elsif (d ->> 'fee_payer') = 'guest_at_door' then
      durum := 'ok';
      metin := case when nullif(d ->> 'guest_fee_amount','') is not null
                    then format('Kapıda ödersin · ~%s %s', trim(to_char((d ->> 'guest_fee_amount')::numeric,'FM999990')), coalesce(d ->> 'guest_fee_currency',''))
                    else 'Ücreti kapıda misafir öder' end;
    else durum := 'bilinmiyor'; metin := 'Ücreti kimin ödediği doğrulanmadı'; end if;
    return next;
  end if;

  -- 13 · kalış süresi (283/6)
  if nullif(d ->> 'max_stay_hours','') is not null then
    v_i := v_i + 1; sira := v_i; kod := 'kalis'; agirlik := 'not';
    if (d ->> 'stay_ok') = 'false' then
      durum := 'yok'; metin := format('Kalış sınırı %s saat · planın %s saat',
                                       trim(to_char((d ->> 'max_stay_hours')::numeric,'FM990.0')),
                                       trim(to_char((d ->> 'planned_hours')::numeric,'FM990.0')));
    else
      durum := 'ok'; metin := format('Kalış sınırı %s saat', trim(to_char((d ->> 'max_stay_hours')::numeric,'FM990.0')));
    end if;
    return next;
  end if;

  -- 14 · doluluk (283/3) — yalnız kayıt varsa
  if coalesce((d ->> 'capacity_refusals_60d')::int, 0) > 0 then
    v_i := v_i + 1; sira := v_i; kod := 'doluluk'; agirlik := 'not';
    durum := case when (d ->> 'capacity_refusals_60d')::int >= 2 then 'yok' else 'ok' end;
    metin := format('Bu saatlerde %s kez doluluk reddi (60 gün)', d ->> 'capacity_refusals_60d');
    return next;
  end if;

  -- 15 · kabin (bilet sınıfı programı değilse yalnız not)
  if (d ->> 'cabin_required') <> 'true' and coalesce(v_av.cabin_class,'') <> '' then
    v_i := v_i + 1; sira := v_i; kod := 'kabin'; agirlik := 'not'; durum := 'ok';
    metin := format('Host kabini · %s', upper(v_av.cabin_class));
    return next;
  end if;

  -- 284 · kural güncelliği (not)
  if (d -> 'freshness') is not null then
    v_i := v_i + 1; sira := v_i; kod := 'guncellik'; agirlik := 'not';
    if (d #>> '{freshness,durum}') = 'supheli' then
      durum := 'yok'; metin := format('Kural kapıda %s kez tutmadı · doğrulanıyor', d #>> '{freshness,acik_suphe}');
    elsif (d #>> '{freshness,durum}') = 'dogrulandi' then
      durum := 'ok'; metin := case when (d #>> '{freshness,gun}') is null then 'Kural kapıda doğrulandı'
                                    else format('Kural %s gün önce doğrulandı', d #>> '{freshness,gun}') end;
    elsif (d #>> '{freshness,durum}') = 'eski' then
      durum := 'bilinmiyor'; metin := format('Kural %s gün önce doğrulandı · eskimiş olabilir', d #>> '{freshness,gun}');
    else durum := 'bilinmiyor'; metin := 'Kural henüz kapıda doğrulanmadı'; end if;
    return next;
  end if;

  -- 16 · biniş kartı & kimlik gerekli
  if v_prog.id is not null and coalesce(v_prog.guest_needs_boarding_pass, false) then
    v_i := v_i + 1; sira := v_i; kod := 'belge'; agirlik := 'not'; durum := 'ok';
    metin := 'Kendi biniş kartın ve kimliğin gerekir';
    return next;
  end if;
end $function$;

do $$
begin
  if pg_get_functiondef('public.lounge_access_decision_v6'::regproc) not like '%kural_guncelligi%' then raise exception '284: v6 guncellik okumuyor'; end if;
  if pg_get_functiondef('public.kural_kosullari'::regproc) not like '%guncellik%' then raise exception '284: kural_kosullari guncellik satiri yok'; end if;
  raise notice '284: v6 + kural_kosullari guncellik (acik tanim)';
end $$;

-- ----------------------------------------------------------------------
-- request_precheck_pregate   [etkin kaynak: 283_kural_motoru_on_iki_boyut.sql]
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.request_precheck_pregate(p_avail_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_av availabilities%rowtype; v_flight text; v_carrier text;
  v_prog lounge_programs%rowtype; d jsonb; v_can boolean := true; v_ack boolean := false;
  v_credit int; v_tut int := 1; v_bal int; v_qnote text; v_cnote text;
  v_tier text; v_head text; v_key text; v_detail text; v_more text;
begin
  -- 🔴 192-seyahat: SUNUCU KAPISININ AYNISI. create_request
  -- (007:41) ayni havalimani + AYNI TARIH icin seyahat arar.
  -- Precheck bunu hic sormuyordu; ekran "gonderebilirsin" deyip
  -- sunucu ham "no_matching_trip" firlatiyordu.
  if not exists (
       select 1 from visits v
        join availabilities a2 on a2.id = p_avail_id
       where v.user_id = auth.uid()
         and v.airport_code = a2.airport_code
         and v.visit_date  = a2.avail_date)
  then
    return jsonb_build_object(
      'can_request', false, 'kind', 'trip_gate', 'severity', 'block',
      'headline', 'Bu tarihte o havalimanında seyahatin yok',
      'detail', 'Bu ilan ' || (select to_char(a3.avail_date, 'DD.MM.YYYY')
                    || ' tarihinde ' || a3.airport_code
                    from availabilities a3 where a3.id = p_avail_id)
                 || '. O gün için bir seyahat ekle, ilan hemen başvurulabilir olsun.',
      'fix_action', 'add_trip',
      'credit_cost', 0, 'credit_hold', 0, 'credit_total', 0);
  end if;

  select * into v_av from availabilities where id = p_avail_id;
  if not found then return jsonb_build_object('can_request', false, 'headline','İlan bulunamadı.'); end if;

  select v.flight_number, coalesce(v.carrier_code, public.carrier_from_flight(v.flight_number))
    into v_flight, v_carrier
    from visits v
   where v.user_id = v_uid and v.airport_code = v_av.airport_code
     and v.visit_date = v_av.avail_date
   order by v.created_at desc limit 1;

  d := public.lounge_access_decision_v6(p_avail_id, v_flight, v_carrier,
         (select v.id from visits v where v.user_id = v_uid and v.airport_code = v_av.airport_code and v.visit_date = v_av.avail_date order by (coalesce(v.flight_number,'') <> '') desc, v.created_at desc limit 1));   -- 283
  select * into v_prog from lounge_programs where id = nullif(d ->> 'program_id','')::uuid;
  v_credit := public.paid_guest_credit(p_avail_id);
  v_tut := coalesce(public.request_credit_cost(auth.uid(), p_avail_id), 1);
  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  v_qnote := public.guest_quota_note(v_av.host_id);
  v_cnote := public.card_confidence_note(v_av.host_id);
  v_tier  := public.card_tier_label(d ->> 'host_tier');

  v_head := case
    when coalesce((d ->> 'charter'),'false') = 'true' then public.rule_notice('head_charter')
    when (d ->> 'carrier_ok') = 'false' then public.rule_notice('head_carrier_bad')
    when (d ->> 'guest_policy') = 'not_allowed' and v_tier is not null
      then replace(public.rule_notice('head_tier_no_guest'), '{tier}', v_tier)
    when (d ->> 'guest_policy') = 'paid' and v_tier is not null
      then replace(public.rule_notice('head_tier_paid'), '{tier}', v_tier)
    when (d ->> 'guest_policy') = 'paid' and (d ->> 'fee_payer') = 'member_card'
      then public.rule_notice('head_fee_member')
    when (d ->> 'guest_policy') = 'paid' then public.rule_notice('head_fee_door')
    when (d ->> 'confidence') in ('unknown','assumed') then public.rule_notice('head_unverified')
    else d ->> 'headline' end;

  -- 🔴 DETAY: KAPIDA ISE YARAYACAK TEK CUMLE.
  -- Onceligi kullanicinin GERI CEVRILME riskine gore veriyoruz:
  -- engel sebebi > ucret > kota > kart guveni. En kritik olan basa.
  v_key := case
    when coalesce((d ->> 'charter'),'false') = 'true' then 'charter'
    when (d ->> 'carrier_ok') = 'false' then 'carrier'
    when (d ->> 'guest_policy') = 'not_allowed' then 'noguest'
    when (d ->> 'guest_policy') = 'paid' then 'paid'
    else 'generic' end;

  v_detail := public.clip_text(case v_key
    when 'charter' then 'Charter seferde havayolu salonu hakkı yoktur.'
    when 'carrier' then 'Bu salon misafirin host ile aynı havayolunda uçmasını istiyor.'
    when 'noguest' then 'Host girebiliyor ama yanında misafir götüremiyor.'
    when 'paid'    then case (d ->> 'fee_payer')
                          when 'member_card' then 'Ücret host''un kartından çekilir.'
                          else 'Misafir girişi kapıda ücretlidir.' end
    else coalesce(d ->> 'detail', public.rule_notice('rule_notice_generic')) end, 140);

  -- 🔴 GERISI SILINMIYOR, ⓘ ARKASINA GIDIYOR. Kural eksiksiz aktarilir;
  -- yalniz HEPSI AYNI ANDA gosterilmez.
  v_more := public.clip_text(
    trim(both ' ' from concat_ws(' ',
      nullif(d ->> 'detail',''), nullif(v_qnote,''), nullif(v_cnote,''),
      nullif(d ->> 'source_conflict',''))), 400);

  if v_prog.id is null or v_prog.entitlement_model = 'bank_card' or v_prog.code = 'BANK_CARD' then
    return jsonb_build_object(/* 192-kapi: kredi karti dali da SUNUCU KAPISINA uyar.
        159'un create_request_impl'i guest_policy='not_allowed' ya da
        severity=block olan ilanda 'guests_not_allowed' firlatiyor;
        ekran bunu bilmeden 'gonderebilirsin' diyordu. */
      'can_request',
        not (coalesce(d ->> 'guest_policy','') = 'not_allowed'
             or (coalesce(d ->> 'severity','') = 'block'
                 and coalesce(d ->> 'fits','') <> 'false')),
      'needs_ack', true, 'kind','card_generic',
      /* 192-karar: erken donus de kararin politikasini TASIR.
         Eskiden bu dal guest_policy'yi hic dondurmuyordu ve
         kesif "misafir kabul etmiyor" derken istek ekrani susuyordu. */
      'guest_policy', d ->> 'guest_policy',
      'guest_allowance', coalesce((d ->> 'guest_included_count')::int, 0),
      'severity_src', d ->> 'severity',
      'severity','warn','source_label','Kredi kartı avantajı',
      'headline','Bu ilandaki hak kredi kartından geliyor',
      'credit_cost', 0,
      'host_carrier', d ->> 'host_carrier', 'guest_carrier', d ->> 'guest_carrier',
      'detail', public.clip_text(public.rule_notice('card_notice_guest'), 140),
      'more', v_more);
  end if;

  if (d ->> 'severity') = 'block' then
    if (d ->> 'block_code') is not null or (d ->> 'enforcement') = 'block' or (d ->> 'carrier_ok') = 'false'
       or coalesce((d ->> 'charter'),'false') = 'true' then
      v_can := false;
    else v_ack := true; end if;
  elsif (d ->> 'severity') = 'warn' then v_ack := true;
  elsif (d ->> 'confidence') = 'unknown' then v_ack := true;
  end if;
  if v_qnote is not null or v_cnote is not null then v_ack := true; end if;

  return jsonb_build_object(
    'can_request', v_can, 'needs_ack', v_ack, 'kind','rule', 'block_code', d ->> 'block_code',
    'severity', d ->> 'severity', 'confidence', d ->> 'confidence',
    'guest_policy', d ->> 'guest_policy', 'fee_payer', d ->> 'fee_payer',
    'flight_coupling', d ->> 'flight_coupling',
    'host_carrier', d ->> 'host_carrier', 'guest_carrier', d ->> 'guest_carrier',
    'carrier_ok', d -> 'carrier_ok', 'host_tier_label', v_tier,
    'source_label', coalesce(v_prog.name,'Lounge hakkı'),
    'credit_cost', v_credit,
    /* 187-kredi: misafirin cebinden cikan TOPLAM. Ekranda tek
       kutuda gosterilmeli: escrow + aktarim. */
    'credit_hold', v_tut,
    'credit_total', v_tut + coalesce(v_credit, 0), 'credit_balance', v_bal,
    'credit_note', case when v_credit > 0
      then replace(public.rule_notice('paid_guest_notice'), '{n}', v_credit::text) end,
    'headline', public.clip_text(v_head, 70),
    'detail', v_detail,
    'more', v_more);
end $function$;

do $$
begin
  if pg_get_functiondef('public.create_request_impl_preflag'::regproc) not like '%lounge_access_decision_v6%' then
    raise exception '283: create_request_impl_preflag v6 degil'; end if;
  if pg_get_functiondef('public.request_precheck_pregate'::regproc) not like '%block_code%' then
    raise exception '283: request_precheck_pregate block_code dondurmuyor'; end if;
  raise notice '283: create_request_impl_preflag + request_precheck_pregate v6 (acik tanim)';
end $$;

-- ----------------------------------------------------------------------
-- trg_kota_tuket   [etkin kaynak: 283_kural_motoru_on_iki_boyut.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_kota_tuket()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_req requests%rowtype; v_av availabilities%rowtype; v_prog uuid; v_he host_entitlements%rowtype;
        v_start date; v_party int;
begin
  if new.status <> 'completed' or old.status = 'completed' then return new; end if;
  select * into v_req from requests where id = new.request_id;
  select * into v_av from availabilities where id = v_req.avail_id;
  v_prog := v_av.program_id;
  if v_prog is null then
    v_prog := nullif(public.lounge_access_decision_prebase(v_av.id) ->> 'program_id','')::uuid;
  end if;
  if v_prog is null then return new; end if;
  select * into v_he from host_entitlements
   where user_id = v_req.host_id and program_id = v_prog
   order by verified desc, self_reported_at desc nulls last limit 1;
  if not found or v_he.quota_total is null or v_he.quota_period = 'unlimited' then return new; end if;
  select coalesce(v.party_size,1) into v_party from visits v where v.id = v_req.visit_id;
  v_party := coalesce(v_party, 1);
  v_start := coalesce(v_he.quota_period_start,
             case when v_he.quota_period = 'month' then date_trunc('month', current_date)::date
                  else date_trunc('year', current_date)::date end);
  if (v_he.quota_period = 'month' and v_start < date_trunc('month', current_date)::date)
     or (v_he.quota_period = 'year' and v_start < date_trunc('year', current_date)::date) then
    update host_entitlements set quota_used = least(v_party, quota_total),
           quota_period_start = case when v_he.quota_period = 'month' then date_trunc('month', current_date)::date
                                     else date_trunc('year', current_date)::date end
     where id = v_he.id;
  else
    update host_entitlements set quota_used = least(quota_used + v_party, quota_total) where id = v_he.id;
  end if;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- set_visit_party   [etkin kaynak: 283_kural_motoru_on_iki_boyut.sql]
-- ----------------------------------------------------------------------
create or replace function public.set_visit_party(p_visit_id uuid, p_kisi int, p_cocuk_yas int[] default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_kisi is null or p_kisi < 1 or p_kisi > 6 then raise exception 'party_size_invalid'; end if;
  if p_cocuk_yas is not null and (array_length(p_cocuk_yas,1) >= p_kisi
     or exists (select 1 from unnest(p_cocuk_yas) x where x < 0 or x > 17)) then
    raise exception 'child_ages_invalid';
  end if;
  update visits set party_size = p_kisi, child_ages = nullif(p_cocuk_yas::smallint[], '{}'::smallint[])
   where id = p_visit_id and user_id = v_uid;
  if not found then raise exception 'visit_not_found'; end if;
  return jsonb_build_object('ok', true);
end $$;

-- ----------------------------------------------------------------------
-- oturum_kural_hedefi   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ----------------------------------------------------------------------
create or replace function public.oturum_kural_hedefi(p_session_id uuid)
returns table(venue_id uuid, program_id uuid, acceptance_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare v_req requests%rowtype; v_av availabilities%rowtype; d jsonb;
begin
  select * into v_req from requests r join sessions s on s.request_id = r.id where s.id = p_session_id;
  if not found then return; end if;
  select * into v_av from availabilities where id = v_req.avail_id;
  d := public.lounge_access_decision_prebase(v_av.id);
  venue_id   := coalesce(nullif(d ->> 'venue_id','')::uuid, v_av.venue_id,
                         (select l.venue_id from lounges l where l.id = v_av.lounge_id));
  program_id := coalesce(nullif(d ->> 'program_id','')::uuid, v_av.program_id);
  select a.id into acceptance_id from lounge_venue_acceptance a
   where a.venue_id = oturum_kural_hedefi.venue_id and a.program_id = oturum_kural_hedefi.program_id and a.active
   limit 1;
  return next;
end $$;

-- ----------------------------------------------------------------------
-- trg_kapida_ret_suphe   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_kapida_ret_suphe()
returns trigger language plpgsql security definer set search_path = public as $$
declare h record;
begin
  if new.sebep not in ('kural_tutmadi','belge_istendi','kapasite_dolu') then return new; end if;
  select * into h from public.oturum_kural_hedefi(new.session_id);
  if h.venue_id is null and h.program_id is null then return new; end if;
  insert into kural_supheleri (venue_id, program_id, acceptance_id, kaynak, session_id, bildiren_id, sebep, aciklama)
  values (h.venue_id, h.program_id, h.acceptance_id, 'kapida_ret', new.session_id, new.guest_id, new.sebep, new.aciklama);
  return new;
end $$;

-- ----------------------------------------------------------------------
-- trg_saha_raporu_suphe   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_saha_raporu_suphe()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_sebep text; h record;
begin
  v_sebep := case
    when new.outcome = 'refused' or new.guest_accepted is false then 'kural_tutmadi'
    when new.outcome = 'admitted_paid' and coalesce(new.fee_charged,false) then 'ucret_istendi'
    else null end;
  if v_sebep is null then return new; end if;
  -- Aynı oturum için kapı reddi zaten şüphe açtıysa ikinci kayıt açma
  if new.session_id is not null and exists (select 1 from kural_supheleri where session_id = new.session_id and durum = 'acik') then
    return new;
  end if;
  if new.session_id is not null then
    select * into h from public.oturum_kural_hedefi(new.session_id);
  end if;
  insert into kural_supheleri (venue_id, program_id, acceptance_id, kaynak, session_id, bildiren_id, sebep, aciklama)
  values (coalesce(h.venue_id, new.venue_id), coalesce(h.program_id, new.program_id), h.acceptance_id,
          'saha_raporu', new.session_id, new.reporter_id, v_sebep, new.note);
  return new;
end $$;

-- ----------------------------------------------------------------------
-- kural_guncelligi   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ----------------------------------------------------------------------
create or replace function public.kural_guncelligi(p_venue_id uuid, p_program_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_checked date; v_acik int; v_ok int; v_bad int; v_son timestamptz; v_durum text; v_gun int;
begin
  select a.checked_at into v_checked from lounge_venue_acceptance a
   where a.venue_id = p_venue_id and a.program_id = p_program_id and a.active limit 1;
  if v_checked is null then
    select p.checked_at into v_checked from lounge_programs p where p.id = p_program_id;
  end if;
  select count(*) filter (where durum = 'acik' and created_at > now() - interval '90 days'),
         max(created_at) filter (where durum = 'acik')
    into v_acik, v_son
    from kural_supheleri where venue_id = p_venue_id and program_id = p_program_id;
  select count(*) filter (where outcome = 'admitted_free' and created_at > now() - interval '90 days'),
         count(*) filter (where outcome in ('refused','admitted_paid') and created_at > now() - interval '90 days')
    into v_ok, v_bad
    from lounge_field_reports where venue_id = p_venue_id and program_id = p_program_id;
  -- Son insan doğrulaması da checked_at'e sayılır (BO kararı)
  select greatest(v_checked, max(karar_at)::date) into v_checked
    from kural_supheleri where venue_id = p_venue_id and program_id = p_program_id
     and durum in ('dogrulandi','guncellendi');
  v_durum := case
    when coalesce(v_acik,0) >= 1 then 'supheli'
    when v_checked is null and coalesce(v_ok,0) = 0 then 'bilinmiyor'
    when v_checked is null or (v_checked < current_date - 90 and coalesce(v_ok,0) = 0) then 'eski'
    else 'dogrulandi' end;
  v_gun := case when v_checked is null then null else current_date - v_checked end;
  return jsonb_build_object('durum', v_durum, 'checked_at', v_checked, 'gun', v_gun,
                            'acik_suphe', coalesce(v_acik,0), 'son_suphe', v_son,
                            'ok_90', coalesce(v_ok,0), 'bad_90', coalesce(v_bad,0));
end $$;

-- ----------------------------------------------------------------------
-- bo_kural_suphe_kuyrugu   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_kural_suphe_kuyrugu(p_durum text default 'acik', p_limit int default 200)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v jsonb;
begin
  if auth.uid() is not null and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select jsonb_agg(x order by (x->>'acik')::int desc, x->>'son' desc) into v from (
    select jsonb_build_object(
      'venue_id', k.venue_id, 'salon', v.name, 'airport', v.airport_code, 'terminal', v.terminal,
      'program_id', k.program_id, 'program', p.name, 'program_code', p.code,
      'acceptance_id', min(k.acceptance_id::text),
      'guest_policy', max(a.guest_policy), 'checked_at', max(a.checked_at), 'source_url', max(coalesce(a.source_url, p.source_url)),
      'acik', count(*) filter (where k.durum = 'acik'),
      'toplam', count(*),
      'sebepler', (select jsonb_object_agg(s, n) from (select sebep s, count(*) n from kural_supheleri k2
                     where k2.venue_id is not distinct from k.venue_id and k2.program_id is not distinct from k.program_id
                       and (p_durum is null or k2.durum = p_durum) group by sebep) t),
      'son', max(k.created_at),
      'kayitlar', (select jsonb_agg(jsonb_build_object('id', k3.id, 'kaynak', k3.kaynak, 'sebep', k3.sebep,
                     'aciklama', k3.aciklama, 'durum', k3.durum, 'created_at', k3.created_at,
                     'session_id', k3.session_id, 'karar_not', k3.karar_not, 'karar_veren', k3.karar_veren)
                     order by k3.created_at desc)
                   from (select * from kural_supheleri k4
                          where k4.venue_id is not distinct from k.venue_id and k4.program_id is not distinct from k.program_id
                            and (p_durum is null or k4.durum = p_durum)
                          order by created_at desc limit 20) k3),
      'guncellik', case when k.venue_id is not null and k.program_id is not null
                        then public.kural_guncelligi(k.venue_id, k.program_id) end) as x
    from kural_supheleri k
    left join lounge_venues v on v.id = k.venue_id
    left join lounge_programs p on p.id = k.program_id
    left join lounge_venue_acceptance a on a.venue_id = k.venue_id and a.program_id = k.program_id and a.active
    where (p_durum is null or k.durum = p_durum)
    group by k.venue_id, v.name, v.airport_code, v.terminal, k.program_id, p.name, p.code
    limit greatest(coalesce(p_limit,200),1)) t;
  return coalesce(v, '[]'::jsonb);
end $$;

-- ----------------------------------------------------------------------
-- bo_kural_suphe_karar   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_kural_suphe_karar(p_venue_id uuid, p_program_id uuid, p_durum text, p_not text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_n int; v_email text;
begin
  if auth.uid() is not null and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  if p_durum not in ('dogrulandi','guncellendi','reddedildi') then raise exception 'gecersiz_durum'; end if;
  select email into v_email from users where id = auth.uid();
  update kural_supheleri
     set durum = p_durum, karar_not = nullif(btrim(coalesce(p_not,'')),''),
         karar_veren = coalesce(v_email, 'admin'), karar_at = now()
   where venue_id is not distinct from p_venue_id and program_id is not distinct from p_program_id and durum = 'acik';
  get diagnostics v_n = row_count;
  if p_durum in ('dogrulandi','guncellendi') and p_venue_id is not null and p_program_id is not null then
    -- Doğrulama METAVERİSİ: içerik değil, tarih ve imza.
    update lounge_venue_acceptance
       set checked_at = current_date, verified_by = coalesce(v_email,'admin'), updated_at = now()
     where venue_id = p_venue_id and program_id = p_program_id and active;
  end if;
  insert into audit_log (action, entity_type, entity_id, after_data)
  values ('rule.suspicion.' || p_durum, 'lounge_venue_acceptance',
          coalesce(p_venue_id, '00000000-0000-0000-0000-000000000000'::uuid),
          jsonb_build_object('venue_id', p_venue_id, 'program_id', p_program_id, 'kapatilan', v_n, 'not', p_not));
  return jsonb_build_object('ok', true, 'kapatilan', v_n);
end $$;

-- ----------------------------------------------------------------------
-- bo_kural_bilinmeyenler   [etkin kaynak: 284_kural_geri_bildirim_dongusu.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_kural_bilinmeyenler(p_limit int default 100)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v jsonb;
begin
  if auth.uid() is not null and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select jsonb_agg(x order by (x->>'talep')::int desc, x->>'salon') into v from (
    select jsonb_build_object(
      'acceptance_id', a.id, 'venue_id', a.venue_id, 'program_id', a.program_id,
      'salon', v.name, 'airport', v.airport_code, 'program', p.name, 'program_code', p.code,
      'guest_policy', a.guest_policy, 'checked_at', a.checked_at, 'source_url', coalesce(a.source_url, p.source_url),
      'talep', (select count(*) from availabilities av where av.venue_id = a.venue_id and av.created_at > now() - interval '90 days')
             + (select count(*) from visits vi where vi.airport_code = v.airport_code and vi.created_at > now() - interval '90 days')
             + 5 * (select count(*) from host_entitlements he where he.program_id = a.program_id)) as x
    from lounge_venue_acceptance a
    join lounge_venues v on v.id = a.venue_id
    join lounge_programs p on p.id = a.program_id
    where a.active and (a.guest_policy = 'unknown' or a.checked_at is null)
    limit greatest(coalesce(p_limit,100),1)) t;
  return coalesce(v, '[]'::jsonb);
end $$;

-- ----------------------------------------------------------------------
-- kimlik_belgesi_gonder   [etkin kaynak: 285_kyc_belge_ve_karar.sql]
-- ----------------------------------------------------------------------
create or replace function public.kimlik_belgesi_gonder(p_doc_path text, p_selfie_path text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_st text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);
  -- Yol kendi klasöründe olmalı: başkasının belgesini "benim" diye gönderemez
  if p_doc_path is null or p_doc_path !~ ('^' || v_uid::text || '/') then raise exception 'kyc_path_invalid'; end if;
  if p_selfie_path is not null and p_selfie_path !~ ('^' || v_uid::text || '/') then raise exception 'kyc_path_invalid'; end if;
  select id_status into v_st from verifications where user_id = v_uid;
  if v_st = 'approved' then raise exception 'kyc_already_approved'; end if;
  if v_st = 'submitted' then raise exception 'kyc_already_submitted'; end if;
  insert into verifications (user_id) values (v_uid) on conflict (user_id) do nothing;
  update verifications
     set id_status = 'submitted', id_doc_path = p_doc_path, id_selfie_path = p_selfie_path,
         id_submitted_at = now(), id_review_note = null, updated_at = now()
   where user_id = v_uid;
  insert into audit_log (action, entity_type, entity_id, after_data)
  values ('kyc.submitted', 'verifications', v_uid, jsonb_build_object('selfie', p_selfie_path is not null));
  return jsonb_build_object('ok', true, 'status', 'submitted', 'sla_saat', 48);
end $$;

-- ----------------------------------------------------------------------
-- kimlik_durumum   [etkin kaynak: 285_kyc_belge_ve_karar.sql]
-- ----------------------------------------------------------------------
create or replace function public.kimlik_durumum()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select jsonb_build_object('status', v.id_status, 'verified', v.id_verified,
                                             'submitted_at', v.id_submitted_at, 'note', v.id_review_note,
                                             'reviewed_at', v.id_reviewed_at)
                     from verifications v where v.user_id = auth.uid()),
                  jsonb_build_object('status','none','verified',false))
$$;

-- ----------------------------------------------------------------------
-- bo_kyc_kuyrugu   [etkin kaynak: 285_kyc_belge_ve_karar.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_kyc_kuyrugu(p_limit int default 100)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v jsonb;
begin
  if auth.uid() is not null and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  select jsonb_agg(x order by x->>'submitted_at') into v from (
    select jsonb_build_object(
      'user_id', v.user_id, 'email', u.email, 'name', p.name, 'phone_verified', v.phone_verified,
      'doc_path', v.id_doc_path, 'selfie_path', v.id_selfie_path, 'submitted_at', v.id_submitted_at,
      'bekleme_saat', round(extract(epoch from (now() - v.id_submitted_at))/3600)::int,
      'legal_name', null,
      'sikayet', (select count(*) from reports r where r.target_id = v.user_id),
      'onceki_ret', (select count(*) from audit_log a where a.entity_id = v.user_id and a.action = 'kyc.rejected')) as x
    from verifications v
    join users u on u.id = v.user_id
    left join profiles p on p.user_id = v.user_id
    where v.id_status = 'submitted' and coalesce(u.is_staff,false) = false
    limit greatest(coalesce(p_limit,100),1)) t;
  return coalesce(v, '[]'::jsonb);
end $$;

-- ----------------------------------------------------------------------
-- bo_kyc_karar   [etkin kaynak: 285_kyc_belge_ve_karar.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_kyc_karar(p_user_id uuid, p_karar text, p_not text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_email text; v_doc text; v_selfie text; v_before jsonb;
begin
  if auth.uid() is not null and not exists (select 1 from admin_roles ar where ar.user_id = auth.uid()) then
    raise exception 'not_admin';
  end if;
  if p_karar not in ('approved','rejected') then raise exception 'gecersiz_karar'; end if;
  if p_karar = 'rejected' and coalesce(btrim(p_not),'') = '' then raise exception 'ret_notu_zorunlu'; end if;
  select email into v_email from users where id = auth.uid();
  select id_doc_path, id_selfie_path, to_jsonb(v) - 'id_doc_path' - 'id_selfie_path' into v_doc, v_selfie, v_before
    from verifications v where user_id = p_user_id;
  if not found then raise exception 'verification_not_found'; end if;
  update verifications
     set id_status = p_karar,
         id_verified = (p_karar = 'approved'),
         id_verified_at = case when p_karar = 'approved' then now() else id_verified_at end,
         id_provider = case when p_karar = 'approved' then 'manual-backoffice' else id_provider end,
         id_review_note = nullif(btrim(coalesce(p_not,'')),''),
         id_reviewed_by = coalesce(v_email, 'admin'), id_reviewed_at = now(),
         -- KVKK: karar verildi, belge yolu tabloda kalmaz (dosyayı BO siler)
         id_doc_path = null, id_selfie_path = null, updated_at = now()
   where user_id = p_user_id;
  insert into audit_log (action, entity_type, entity_id, before_data, after_data)
  values ('kyc.' || p_karar, 'verifications', p_user_id, v_before,
          jsonb_build_object('karar', p_karar, 'not', p_not, 'karar_veren', coalesce(v_email,'admin')));
  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (p_user_id, 'system',
          case when p_karar = 'approved' then 'Kimliğin doğrulandı ✓' else 'Kimlik belgen kabul edilmedi' end,
          case when p_karar = 'approved' then 'Profilinde doğrulanmış rozeti var; keşifte daha öne çıkıyorsun.'
               else coalesce(nullif(btrim(p_not),''), 'Belge okunamadı.') || ' Yeniden yükleyebilirsin.' end,
          'user', p_user_id);
  return jsonb_build_object('ok', true, 'silinecek', jsonb_strip_nulls(jsonb_build_object('doc', v_doc, 'selfie', v_selfie)));
end $$;

-- ----------------------------------------------------------------------
-- discover_people_prebfilter   [etkin kaynak: 286_tanis_cift_satir.sql]
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.discover_people_prebfilter(p_airport text DEFAULT NULL::text, p_date date DEFAULT NULL::date)
 RETURNS TABLE(user_id uuid, name text, profession text, bio text, badge text, score integer, rel text, photo text, purpose text, same_purpose boolean, airport text, is_hosting boolean, host_avail_id uuid, host_slots_left integer, host_airport text, can_request boolean, req_reason text, visit_date date, flight_number text, same_flight boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_female boolean; v_safe boolean;
  v_phone_ok boolean;
begin
  select (u.gender='female'), coalesce(pr.women_safety_mode,false)
    into v_female, v_safe from users u left join profiles pr on pr.user_id=u.id where u.id=v_uid;

  select coalesce(bool_or(v.phone_verified), false) into v_phone_ok
    from verifications v where v.user_id = v_uid;

  return query
  with
  -- Karşı tarafın en yakın aktif+açık-slotlu ilanı (İstek butonu bilgisi)
  hosting as (
    select distinct on (a.host_id)
           a.host_id, a.id as avail_id, a.airport_code::text as ap,
           a.avail_date, a.time_from, a.time_to,
           greatest(0, a.slots - coalesce(a.filled,0)) as slots_left
      from availabilities a
     where a.active = true
       and a.avail_date >= current_date
       and a.visibility <> 'Hidden'
       and coalesce(a.min_trust,0) = 0
       and greatest(0, a.slots - coalesce(a.filled,0)) > 0
       and (p_airport is null or a.airport_code = p_airport)
       and (p_date is null or a.avail_date = p_date)
     order by a.host_id, a.avail_date, a.time_from
  ),
  -- Karşı tarafın en yakın seyahati — MVP kartında "✈ IST · 15 Haziran" ve
  -- "AYNI UÇUŞ · TK712" bunun üzerinden gösterilir. ESKİ SÜRÜMDE YOKTU:
  -- airport yalnız hosting CTE'sinden geliyordu, dolayısıyla ilanı olmayan
  -- misafirlerde tüm bu alanlar BOŞ kalıyordu (Canlı APP 3).
  trip as (
    select distinct on (v.user_id)
           v.user_id, v.airport_code::text as ap, v.visit_date,
           v.flight_number, v.purpose
      from visits v
     where v.visit_date >= current_date
       and (p_airport is null or v.airport_code = p_airport)
       and (p_date is null or v.visit_date = p_date)
     order by v.user_id, v.visit_date, v.time_from
  ),
  -- Benim seyahatlerim — İstek kapısı için (aynı yer/tarih/±1s örtüşme)
  mine as (
    select v.airport_code::text as ap, v.visit_date, v.time_from, v.time_to,
           v.flight_number, v.purpose
      from visits v
     where v.user_id = v_uid and v.visit_date >= current_date
  )
  select p.user_id, p.name, p.profession, p.bio, ts.badge, ts.score,
         coalesce(cr.status::text, 'none') as rel,
         case when p.photo_url is not null and (
                coalesce(p.photo_connections_only,false) = false
                or coalesce(cr.status::text,'') = 'accepted'
              ) then p.photo_url else null end as photo,
         tr.purpose,
         (tr.purpose is not null and exists (
            select 1 from mine m where m.purpose = tr.purpose)) as same_purpose,
         coalesce(tr.ap, ho.ap) as airport,
         (ho.host_id is not null) as is_hosting,
         ho.avail_id as host_avail_id,
         ho.slots_left as host_slots_left,
         ho.ap as host_airport,
         -- can_request: üç şart birden
         (ho.host_id is not null
          and v_phone_ok
          and exists (
            select 1 from mine m
             where m.ap = ho.ap
               and m.visit_date = ho.avail_date
               -- saat penceresi ±1 saat (ilan from-1s .. to+1s ile örtüşme)
               and m.time_from < (ho.time_to + interval '1 hour')
               and (ho.time_from - interval '1 hour') < m.time_to
          )) as can_request,
         -- req_reason: neden pasif (öncelik: ilan yok > telefon > seyahat)
         case
           when ho.host_id is null then 'noslot'
           when not v_phone_ok then 'phone'
           when not exists (
             select 1 from mine m
              where m.ap = ho.ap and m.visit_date = ho.avail_date
                and m.time_from < (ho.time_to + interval '1 hour')
                and (ho.time_from - interval '1 hour') < m.time_to
           ) then 'trip'
           else null
         end as req_reason,
         tr.visit_date,
         tr.flight_number,
         -- AYNI UÇUŞ: benim uçuş numaramla eşleşiyor mu
         (tr.flight_number is not null and exists (
            select 1 from mine m
             where m.flight_number is not null
               and upper(m.flight_number) = upper(tr.flight_number))) as same_flight
    from profiles p
    join users hu on hu.id = p.user_id
    left join trust_scores ts on ts.user_id = p.user_id
    -- 286: iki yönde de kayıt olabilir (bağlantı isteği + kural sorusu) →
    -- eski LEFT JOIN kişiyi İKİ KEZ listeliyordu. En anlamlı TEK satır seçilir.
    left join lateral (
      select c.status from connection_requests c
       where (c.from_id = v_uid and c.to_id = p.user_id)
          or (c.from_id = p.user_id and c.to_id = v_uid)
       order by (c.status::text = 'accepted') desc,
                (coalesce(c.intent,'') <> 'kural_sorusu') desc,
                c.created_at desc
       limit 1
    ) cr on true
    left join hosting ho on ho.host_id = p.user_id
    left join trip tr on tr.user_id = p.user_id
   where p.user_id <> v_uid
     and coalesce(p.show_on_discovery, true) = true
     and public.is_visible(p.user_id)
     -- KADIN GÜVENLİK — 049 kuralı AYNEN korunur:
     and (not (v_female and v_safe) or hu.gender = 'female')
     and (not coalesce(p.women_safety_mode,false)
          or (v_female and v_phone_ok)
          or exists (select 1 from connection_requests c9 where c9.from_id = p.user_id and c9.to_id = v_uid)
          or exists (select 1 from requests r9 join availabilities a9 on a9.id = r9.avail_id
                     where r9.guest_id = p.user_id and a9.host_id = v_uid)
          or exists (select 1 from invites i9 where i9.host_id = p.user_id and i9.guest_id = v_uid))
   order by (ho.host_id is not null) desc,          -- ilanı olanlar üstte
            ts.score desc nulls last
   limit 100;
end $function$

;

-- ----------------------------------------------------------------------
-- yerel_an   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ----------------------------------------------------------------------
create or replace function public.yerel_an(p_date date, p_time time, p_airport text)
returns timestamptz
language sql stable security definer set search_path = public as $fn$
  select (p_date + p_time) at time zone coalesce(
           (select a.timezone from airports a where a.code = upper(trim(p_airport))),
           'Europe/Istanbul');
$fn$;

-- Havalimanında ŞU AN hangi gün? (UTC'de gün dönmüş olabilir.)

-- ----------------------------------------------------------------------
-- yerel_gun   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ----------------------------------------------------------------------
create or replace function public.yerel_gun(p_airport text)
returns date
language sql stable security definer set search_path = public as $fn$
  select (now() at time zone coalesce(
            (select a.timezone from airports a where a.code = upper(trim(p_airport))),
            'Europe/Istanbul'))::date;
$fn$;

-- Havalimanında ŞU AN saat kaç? (duvar saati)

-- ----------------------------------------------------------------------
-- yerel_saat   [etkin kaynak: 292_zaman_dilimi_yerel_an.sql]
-- ----------------------------------------------------------------------
create or replace function public.yerel_saat(p_airport text)
returns time
language sql stable security definer set search_path = public as $fn$
  select (now() at time zone coalesce(
            (select a.timezone from airports a where a.code = upper(trim(p_airport))),
            'Europe/Istanbul'))::time;
$fn$;

comment on function public.yerel_an(date, time, text) is
  'Havalimanı duvar saatindeki (tarih,saat) → gerçek an. UTC ile kıyas yapacak HER yer bunu kullanır.';
comment on function public.yerel_gun(text) is 'Havalimanında şu anki yerel tarih.';
comment on function public.yerel_saat(text) is 'Havalimanında şu anki yerel duvar saati.';

grant execute on function public.yerel_an(date, time, text) to authenticated, anon;
grant execute on function public.yerel_gun(text) to authenticated, anon;
grant execute on function public.yerel_saat(text) to authenticated, anon;

-- ── 2 · DÖRT NESNE · 12 YER ────────────────────────────────────────────
-- Gövdeler `ETKIN_TANIMLAR.sql`den ALINDI ve yalnız ölçülen satırlar
-- değiştirildi (bkz. uretecler/zaman_dilimi_292.py — değişiklik sayısı
-- doğrulanır, tutmazsa dosya hiç üretilmez).

-- ── lounge_radar_people ─────────────────────────────────────────────

-- ----------------------------------------------------------------------
-- binis_karti_kaydet   [etkin kaynak: 294_binis_karti_dogrulama.sql]
-- ----------------------------------------------------------------------
create or replace function public.binis_karti_kaydet(
  p_request_id uuid,
  p_method text,
  p_passed boolean,
  p_reason_code text default null,
  -- ⚠️ `char(3)`/`char(1)` YAZMIŞTIM — İKİ SEBEPLE `text`E ÇEVİRDİM:
  -- (a) `char(n)` değeri SESSİZCE BOŞLUKLA DOLDURUR; 'IST ' ile 'IST'
  --     karşılaştırması ileride birini şaşırtır.
  -- (b) `contract_check.py` imza ayrıştırıcısı parantezli tipte
  --     parametreyi göremiyor ve çağrıyı "fazla parametre" sanıyor.
  --     Nöbetçiyi gevşetmek yerine imzayı sadeleştirmek doğru olan:
  --     kısıtı zaten gövde uyguluyor.
  -- 🆕 SINIF: "BİR PARAMETRE TİPİ HEM VERİYİ HEM DENETİMİ ŞAŞIRTIYORSA,
  -- SORUN DENETİMDE DEĞİL TİP SEÇİMİNDEDİR."
  p_airport text default null,
  p_flight_date date default null,
  p_carrier_flight text default null,
  p_cabin text default null,
  p_pnr_girdi text default null,
  p_duration_ms int default null
) returns jsonb
language plpgsql security definer set search_path = public as $fn$
declare
  v_uid uuid := auth.uid();
  v_tuz text; v_hash text; v_id uuid; v_diger uuid; v_ad text;
  v_q record;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);

  select * into v_q from requests where id = p_request_id;
  if v_q.id is null then raise exception 'request_not_found'; end if;
  if v_uid not in (v_q.host_id, v_q.guest_id) then raise exception 'not_participant'; end if;

  if p_method not in ('scan', 'gallery', 'file', 'bypass') then
    raise exception 'gecersiz_yontem';
  end if;

  -- Karma: yalnız BAŞARILI ve ham girdisi olan doğrulamalarda
  if p_passed and coalesce(p_pnr_girdi, '') <> '' then
    select deger into v_tuz from sunucu_sirlari where anahtar = 'bp_tuz';
    v_hash := encode(sha256(convert_to(p_pnr_girdi || '|' || coalesce(v_tuz, ''), 'UTF8')), 'hex');
    -- Çifte kullanım: aynı biniş kartı başka bir hesapta doğrulanmışsa
    if exists (select 1 from session_verifications sv
                where sv.bp_hash = v_hash and sv.passed and sv.user_id <> v_uid) then
      raise exception 'zaten_dogrulandi';
    end if;
  end if;

  insert into session_verifications
    (request_id, user_id, method, passed, reason_code, airport_code,
     flight_date, carrier_flight, cabin_code, bp_hash, duration_ms)
  values (p_request_id, v_uid, p_method::public.bp_yontem, p_passed, p_reason_code,
          nullif(upper(trim(coalesce(p_airport, ''))), '')::char(3),
          p_flight_date, p_carrier_flight,
          nullif(upper(trim(coalesce(p_cabin, ''))), '')::char(1),
          v_hash, p_duration_ms)
  returning id into v_id;

  -- ── ESNEK GÜVENCE: karşı tarafa editoryal uyarı ───────────────────
  -- 🔴 METİN GÖKBERK'İN YAZDIĞI GİBİ, KELİMESİ KELİMESİNE.
  -- Akış KESİLMİYOR; yalnız karşı taraf bilgilendiriliyor.
  if p_method = 'bypass' or not p_passed then
    v_diger := case when v_uid = v_q.host_id then v_q.guest_id else v_q.host_id end;
    select coalesce(p.name, 'Yolcu') into v_ad from profiles p where p.user_id = v_uid;
    insert into notifications (user_id, category, title, body, ref_id, ref_type)
    values (v_diger, 'requests', 'Biniş kartı doğrulanamadı',
            'Dijital biniş kartı doğrulaması sistem şartlarından dolayı tamamlanamadı. '
            || 'Lütfen turnike geçişi esnasında salon kurallarına manuel olarak '
            || 'uyduğunuzdan emin olun.',
            p_request_id, 'request');
  end if;

  return jsonb_build_object('ok', true, 'id', v_id, 'method', p_method, 'passed', p_passed);
end $fn$;

drop function if exists public.binis_karti_kaydet(uuid, text, boolean, text, char, date, text, char, text, int);
grant execute on function public.binis_karti_kaydet(uuid, text, boolean, text, text, date, text, text, text, int)
  to authenticated;

-- ── 4 · BU İSTEKTE DOĞRULAMA DURUMU ────────────────────────────────────
-- Sohbet ekranı iki tarafın da durumunu gösterir: kim doğruladı, kim
-- atladı. "Karşı tarafın ekranına düşsün" tam olarak bu.

-- ----------------------------------------------------------------------
-- binis_karti_durumu   [etkin kaynak: 294_binis_karti_dogrulama.sql]
-- ----------------------------------------------------------------------
create or replace function public.binis_karti_durumu(p_request_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid uuid := auth.uid(); v_q record; v_out jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_q from requests where id = p_request_id;
  if v_q.id is null then raise exception 'request_not_found'; end if;
  if v_uid not in (v_q.host_id, v_q.guest_id) then raise exception 'not_participant'; end if;

  select jsonb_object_agg(k, v) into v_out from (
    select case when sv.user_id = v_q.host_id then 'host' else 'guest' end as k,
           jsonb_build_object('method', sv.method, 'passed', sv.passed,
                              'reason', sv.reason_code, 'at', sv.created_at) as v
      from session_verifications sv
     where sv.request_id = p_request_id
       and sv.id = (select sv2.id from session_verifications sv2
                     where sv2.request_id = p_request_id and sv2.user_id = sv.user_id
                     order by sv2.created_at desc limit 1)
  ) x;
  return coalesce(v_out, '{}'::jsonb);
end $fn$;

grant execute on function public.binis_karti_durumu(uuid) to authenticated;

-- ── 5 · KENDİ SINAMASI ─────────────────────────────────────────────────
do $$
declare
  hd uuid; g uuid; lng uuid; av uuid; rq uuid; s jsonb; v_n int; v_ham text;
begin
  select id into hd from users where role = 'host' and deleted_at is null limit 1;
  select id into lng from lounges where airport_code = 'IST' limit 1;
  if hd is null or lng is null then raise notice '294 sinama: veri yok, atlandi'; return; end if;
  select id into g from users where id <> hd and deleted_at is null limit 1;

  insert into availabilities (host_id, airport_code, lounge_id, avail_date, time_from, time_to, slots, active)
    values (hd, 'IST', lng, public.yerel_gun('IST') + 7, time '10:00', time '13:00', 2, true)
    returning id into av;
  insert into requests (guest_id, host_id, avail_id, status) values (g, hd, av, 'accepted') returning id into rq;

  perform set_config('request.jwt.claims',
    json_build_object('sub', g::text, 'role', 'authenticated')::text, true);

  -- 1) Başarılı tarama kaydedilir, karma üretilir
  v_ham := 'ABC123|INAK|2026-09-20';
  s := public.binis_karti_kaydet(rq, 'scan', true, null, 'IST', date '2026-09-20', 'TK1979', 'Y', v_ham, 850);
  if (s ->> 'ok') is distinct from 'true' then raise exception '294: kayit dusru'; end if;
  if (select bp_hash from session_verifications where id = (s ->> 'id')::uuid) is null then
    raise exception '294: karma uretilmedi';
  end if;
  -- HAM DİZE HİÇBİR KOLONDA OLMAMALI
  if exists (select 1 from session_verifications sv where sv.id = (s ->> 'id')::uuid
               and (sv.bp_hash like '%ABC123%' or sv.carrier_flight like '%ABC123%')) then
    raise exception '294: HAM PNR sizdi';
  end if;
  raise notice '294 sinama 1 ✓ basarili tarama · karma uretildi · ham PNR sizmadi';

  -- 2) Aynı biniş kartı BAŞKA hesapta reddedilmeli
  perform set_config('request.jwt.claims',
    json_build_object('sub', hd::text, 'role', 'authenticated')::text, true);
  begin
    perform public.binis_karti_kaydet(rq, 'scan', true, null, 'IST', date '2026-09-20', 'TK1979', 'Y', v_ham, 700);
    raise exception '294: cifte kullanim engellenmedi';
  exception when others then
    if SQLERRM <> 'zaten_dogrulandi' then raise; end if;
    raise notice '294 sinama 2 ✓ ayni binis karti ikinci hesapta reddedildi';
  end;

  -- 3) Bypass akışı KESMEZ ve karşı tarafa uyarı düşer
  select count(*) into v_n from notifications where user_id = g;
  s := public.binis_karti_kaydet(rq, 'bypass', false, 'kullanici_atladi', null, null, null, null, null, null);
  if (s ->> 'ok') is distinct from 'true' then raise exception '294: bypass kaydi dusru'; end if;
  if (select count(*) from notifications where user_id = g) <= v_n then
    raise exception '294: bypassta karsi tarafa uyari gitmedi';
  end if;
  raise notice '294 sinama 3 ✓ bypass kaydedildi · karsi tarafa editoryal uyari gitti';

  -- 4) Durum sorgusu iki tarafı da gösterir
  s := public.binis_karti_durumu(rq);
  if not (s ? 'host' and s ? 'guest') then
    raise exception '294: durum sorgusu iki tarafi gostermiyor (%)', s;
  end if;
  raise notice '294 sinama 4 ✓ durum: %', s;

  -- 5) Katılımcı olmayan kaydedemez
  begin
    perform set_config('request.jwt.claims',
      json_build_object('sub', (select id from users where id not in (hd, g) and deleted_at is null limit 1)::text,
                        'role', 'authenticated')::text, true);
    perform public.binis_karti_kaydet(rq, 'scan', true, null, 'IST', date '2026-09-20', 'TK1979', 'Y', 'XYZ|A|B', 100);
    raise exception '294: yabanci kullanici kaydedebildi';
  exception when others then
    if SQLERRM not in ('not_participant', 'hesap_kapali') then raise; end if;
    raise notice '294 sinama 5 ✓ katilimci olmayan kaydedemiyor (%)', SQLERRM;
  end;

  raise exception 'GERI_AL_SINAMA';
exception
  when others then
    if SQLERRM <> 'GERI_AL_SINAMA' then raise; end if;
    raise notice '294 sinama: tum veri geri alindi';
end $$;

-- ----------------------------------------------------------------------
-- ilani_yeniden_yayinla   [etkin kaynak: 295_ilanin_ikinci_hayati_ve_sayaclar.sql]
-- ----------------------------------------------------------------------
create or replace function public.ilani_yeniden_yayinla(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_uid uuid := auth.uid();
  v_a   availabilities%rowtype;
  v_cap int;
  v_cakisma int;
  v_guest_cakisma boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);

  select * into v_a from availabilities where id = p_id for update;
  if not found then raise exception 'availability_not_found'; end if;
  if v_a.host_id <> v_uid then raise exception 'not_your_availability'; end if;

  -- Zaten yayındaysa bu bir hata değil, bir NO-OP: iki kez basılan düğme
  -- kullanıcıya kırmızı göstermemeli.
  if coalesce(v_a.active, false) then
    return jsonb_build_object('ok', true, 'zaten_yayinda', true);
  end if;

  if v_a.avail_date < current_date then
    raise exception 'date_in_past'
      using hint = 'Bu ilanin gunu gecti; yeniden yayinlanamaz.';
  end if;

  if not public.is_contact_verified(v_uid) then
    raise exception 'contact_not_verified';
  end if;

  select guest_capacity into v_cap from profiles where user_id = v_uid;
  if v_cap is null then raise exception 'no_access_source'; end if;
  if v_a.slots > v_cap then
    raise exception 'slots_exceed_capacity'
      using hint = 'Kapasiten bu ilani acarken oldugundan dusuk. Once kontenjani azalt.';
  end if;

  select count(*) into v_cakisma
    from availabilities a2
   where a2.host_id = v_uid and a2.id <> p_id and a2.active
     and a2.avail_date = v_a.avail_date
     and a2.time_from < v_a.time_to and v_a.time_from < a2.time_to;
  if v_cakisma > 0 then
    raise exception 'kendi_ilanlarin_cakisiyor'
      using hint = 'Bu saatte baska bir aktif ilanin var. Once onu kaldir ya da saatleri ayir.';
  end if;

  select exists (
    select 1 from requests r
      join availabilities a on a.id = r.avail_id
     where r.guest_id = v_uid and r.status in ('pending','accepted')
       and a.avail_date = v_a.avail_date
       and a.time_from < v_a.time_to and v_a.time_from < a.time_to
  ) into v_guest_cakisma;
  if v_guest_cakisma then raise exception 'guest_same_slot'; end if;

  update availabilities
     set active = true, updated_at = now()
   where id = p_id;

  insert into audit_log (actor_id, action, entity_type, entity_id, after_data)
  values (v_uid, 'availability.republish', 'availabilities', p_id,
          jsonb_build_object('date', v_a.avail_date, 'from', v_a.time_from,
                             'to', v_a.time_to, 'slots', v_a.slots));

  return jsonb_build_object('ok', true, 'zaten_yayinda', false,
                            'tarih', v_a.avail_date);
end $function$;

grant execute on function public.ilani_yeniden_yayinla(uuid) to authenticated;

-- ── C · home_connections: 24 SAATLİK PENCERE KALKTI ─────────────────────
-- 🔴 Eski `where` iki koşuldan birini arıyordu:
--       coalesce(responded_at, created_at) > now() - interval '24 hours'
--    or exists (24 saat icinde mesaj)
-- Ölçüm: bu, "bağlantılarım" listesini bir AKIŞ'a çeviriyordu. Bir
-- bağlantı kurulduktan 25 saat sonra, hiç mesaj yazılmadıysa, listeden
-- VE ana sayfadaki sohbet rozetinden düşüyordu. Kullanıcı bunu "verim
-- kayboldu" diye okur — ki Gökberk tam olarak öyle okudu (md.2).
-- Sıralama zaten en son hareketi üste alıyor ve `limit 10` var: yani
-- "yeni olan üstte" işini PENCERE değil SIRALAMA yapıyordu. Pencere
-- yalnız eskiyi siliyordu.

-- ----------------------------------------------------------------------
-- home_connections_prebfilter   [etkin kaynak: 295_ilanin_ikinci_hayati_ve_sayaclar.sql]
-- ----------------------------------------------------------------------
create or replace function public.home_connections_prebfilter()
-- ⚠️ SÜTUN ADLARI BİREBİR KORUNDU (conn_id/last_msg_at). `create or replace`
-- OUT parametre adı değişirse "cannot change return type" ile düşer; ölçtüm,
-- düştü. Bir imzayı "daha okunaklı" yapmak, onu değiştirmektir.
returns table (conn_id uuid, peer_id uuid, peer_name text, peer_photo text,
               channel_id uuid, last_msg_at timestamptz)
language sql
stable
security definer
set search_path to 'public'
as $function$
  select cr.id,
         case when cr.from_id = auth.uid() then cr.to_id else cr.from_id end,
         p.name, p.photo_url, ch.id,
         (select max(m.created_at) from messages m where m.channel_id = ch.id)
    from connection_requests cr
    left join chat_channels ch on ch.connection_id = cr.id
    left join profiles p
      on p.user_id = case when cr.from_id = auth.uid() then cr.to_id else cr.from_id end
   where cr.status = 'accepted'
     and (cr.from_id = auth.uid() or cr.to_id = auth.uid())
   order by coalesce((select max(m.created_at) from messages m where m.channel_id = ch.id),
                     cr.responded_at, cr.created_at) desc
   limit 10
$function$;

-- ── D · ana_sayfa_akisi: `sohbet` artık listeden değil kaynaktan sayılıyor ─
-- 🔴 Eski hâl `select count(*) from home_connections()` idi ve o fonksiyon
-- `limit 10` taşıyor. Yani 30 bağlantısı olan bir kullanıcının rozeti
-- 10'da takılıyordu — rozet, listeyi değil GERÇEĞİ söylemeli. Liste
-- "son 10" göstermeye devam ediyor; ikisi artık FARKLI şeyler söylüyor
-- ve ikisi de doğru.

-- ----------------------------------------------------------------------
-- hikaye_davetini_ertele   [etkin kaynak: 296_hikaye_daveti_erteleme.sql]
-- ----------------------------------------------------------------------
create or replace function public.hikaye_davetini_ertele(p_session uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_uid uuid := auth.uid();
  v_r   requests%rowtype;
  v_s   sessions%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_s from sessions where id = p_session;
  if not found then raise exception 'session_not_found'; end if;
  select * into v_r from requests where id = v_s.request_id;
  if not found or v_r.host_id <> v_uid then raise exception 'not_host_of_session'; end if;

  insert into public.hikaye_ertelemeleri (user_id, session_id)
  values (v_uid, p_session)
  on conflict (user_id, session_id) do update set ertelendi_at = now();

  return jsonb_build_object('ok', true, 'tekrar_sorulacak', (now() + interval '30 days')::date);
end $function$;

grant execute on function public.hikaye_davetini_ertele(uuid) to authenticated;

-- ── bekleyen_hikaye_daveti: ertelenmişi 30 gün sormaz ───────────────────

-- ----------------------------------------------------------------------
-- yonetici_kapisi   [etkin kaynak: 297_yetki_kapilari.sql]
-- ----------------------------------------------------------------------
create or replace function public.yonetici_kapisi()
returns void
language plpgsql
stable
security definer
set search_path to 'public'
as $function$
declare v_uid uuid := auth.uid();
begin
  -- Oturum yoksa çağrı sunucu içinden geliyor (service_role / cron):
  -- `auth.uid()` orada null'dur ve o yol zaten yetkilidir.
  if v_uid is null then return; end if;
  if not exists (select 1 from admin_roles ar where ar.user_id = v_uid) then
    raise exception 'yonetici_degil'
      using hint = 'Bu islem yalniz backoffice yoneticileri icindir.';
  end if;
end $function$;

revoke execute on function public.yonetici_kapisi() from authenticated, anon;

-- Gövdeye kapı eklerken fonksiyonun TAM TANIMINI (`pg_get_functiondef`)
-- alıp yalnız ilk `begin`den sonrasına bir satır ekliyoruz. İlk yazımda
-- imzayı/dönüş tipini/`search_path`i tek tek yeniden kurmaya çalıştım ve
-- `unnest(... ) in WHERE` ile patladı — hata haklıydı: bir tanımı parça
-- parça yeniden inşa etmek, o parçalardan birini unutmaktır.
-- 🆕 SINIF: "BİR TANIMI DEĞİŞTİRECEKSEN ONU YENİDEN KURMA, VAR OLANI AL
-- VE TEK YERİNDEN DOKUN."
do $$
declare r record; tanim text; yeni text; n int := 0;
begin
  for r in
    select p.oid, p.proname, p.prosrc
      from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public'
       and p.proname in ('upsert_admin', 'remove_admin', 'assign_partner')
  loop
    if position('yonetici_kapisi' in r.prosrc) > 0 then
      raise notice '297/B: % zaten kapili, atlandi', r.proname;
      continue;
    end if;
    tanim := pg_get_functiondef(r.oid);
    -- Gövde `AS $function$ ... $function$` içinde; ilk `begin`i orada ara.
    yeni := regexp_replace(tanim,
              '(\$function\$.*?\mbegin\M)',
              E'\\1\n  perform public.yonetici_kapisi();',
              'is');
    if yeni = tanim then
      raise exception '297/B: % govdesinde begin bulunamadi', r.proname;
    end if;
    execute yeni;
    n := n + 1;
    raise notice '297/B: % govdesine yonetici kapisi eklendi', r.proname;
  end loop;
  if n = 0 then raise notice '297/B: eklenecek fonksiyon yok (hepsi kapili)'; end if;
end $$;

-- ----------------------------------------------------------------------
-- bo_slot_asimlari   [etkin kaynak: 298_supurge_kisiti_ve_asim_dedektoru.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_slot_asimlari()
returns table (
  avail_id     uuid,
  host_id      uuid,
  airport_code text,
  avail_date   date,
  slots        int,
  sayac        int,
  gercek       int,
  asim         int
)
language sql
stable
security definer
set search_path to 'public'
as $function$
  select a.id, a.host_id, a.airport_code::text, a.avail_date,
         a.slots::int, a.filled::int, x.gercek::int, (x.gercek - a.slots)::int
    from availabilities a
    join lateral (
      select count(*) as gercek from requests r
       where r.avail_id = a.id and r.status in ('accepted','completed')
    ) x on true
   where x.gercek > a.slots
   order by (x.gercek - a.slots) desc, a.avail_date desc
$function$;

revoke execute on function public.bo_slot_asimlari() from anon, authenticated;
grant execute on function public.bo_slot_asimlari() to service_role;

-- ══ SINAMA ═════════════════════════════════════════════════════════════
do $$
declare v1 jsonb; v2 jsonb; v_asim int;
begin
  -- Damgayı sıfırla ki ilk çağrı gerçekten koşsun.
  delete from public.supurge_damgasi where ad = 'expire_stale_sessions';

  v1 := public.expire_stale_sessions();
  if (v1 ->> 'durum') <> 'kosuldu' then
    raise exception '298: ilk cagri kosmadi (%)', v1;
  end if;

  v2 := public.expire_stale_sessions();
  if (v2 ->> 'durum') <> 'atlandi' then
    raise exception '298: ikinci cagri FRENLENMEDI (%) — supurge hala her cagrida kosuyor', v2;
  end if;

  -- 6 dakika geriye al: fren açılmalı.
  update public.supurge_damgasi set son_kosum = now() - interval '6 minutes'
   where ad = 'expire_stale_sessions';
  v2 := public.expire_stale_sessions();
  if (v2 ->> 'durum') <> 'kosuldu' then
    raise exception '298: fren suresi dolunca kosmadi (%) — supurge kalici kilitlendi', v2;
  end if;

  select count(*) into v_asim from public.bo_slot_asimlari();
  raise notice '298 sinama: fren calisiyor · slot asimi tespit edilen ilan: %', v_asim;
  raise exception 'GERI_AL_SINAMA';
exception
  when others then
    if SQLERRM <> 'GERI_AL_SINAMA' then raise; end if;
end $$;

-- ----------------------------------------------------------------------
-- tutma_sebepleri   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ----------------------------------------------------------------------
create or replace function public.tutma_sebepleri()
returns text[]
language sql
immutable
as $function$
  select array['request_hold', 'invite_hold', 'request_free_tier']::text[]
$function$;

-- Eşik: bu tarihten SONRA açılan istekte tutma kaydı yoksa "1 varsay"
-- dalı KAPALIDIR. Eşikten eski istekler eski davranışı aynen korur.

-- ----------------------------------------------------------------------
-- tutma_varsayim_esigi   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ----------------------------------------------------------------------
create or replace function public.tutma_varsayim_esigi()
returns timestamptz
language sql
immutable
as $function$
  select timestamptz '2026-09-19 00:00:00+03'
$function$;

-- BİR İSTEK İÇİN GERÇEKTEN TUTULAN KREDİ.
--
-- 🔴 NEDEN FONKSİYON — beş yerde beş ayrı kopya vardı:
--   `istek_kredisi_iade`, `trg_iade_tutulani_asamaz`, `kapida_giremedim`,
--   `bayat_istekleri_iade_et`, `expire_stale_sessions`. İkisi sabit `1`
--   yazıyordu, üçü `request_hold` arıyordu, hiçbiri `invite_hold`u
--   tanımıyordu. Bir kuralın beş kopyası, beş farklı kuraldır.
--
-- ⚠️ `request_free_tier` (delta 0) BİLEREK listede: bedelsiz istekte
-- tutulan 0'dır ve iade de 0 olmalıdır — kayıt YOK sayılırsa "varsay"
-- dalına düşer ve olmayan bir kredi iade edilir (bu hata bir kez yaşandı).

-- ----------------------------------------------------------------------
-- tutulan_kredi   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ----------------------------------------------------------------------
create or replace function public.tutulan_kredi(p_req uuid)
returns int
language plpgsql
stable
set search_path to 'public'
as $function$
declare v_tut int; v_olusum timestamptz;
begin
  select -min(delta) into v_tut
    from credit_ledger
   where ref_id = p_req and reason = any (public.tutma_sebepleri());
  if v_tut is not null then return greatest(0, v_tut); end if;

  -- Tutma kaydı yok. Eşikten ESKİ istek → geçmiş veri, 1 varsayılır
  -- (eski davranış aynen korunur). Eşikten YENİ istek → her istek
  -- mutlaka tutma satırı yazıyor; yoksa defter satırı SİLİNMİŞ demektir
  -- ve 1 kredi UYDURMAK yanlış cevaptır.
  select created_at into v_olusum from requests where id = p_req;
  if v_olusum is null or v_olusum < public.tutma_varsayim_esigi() then
    return 1;
  end if;
  return 0;
end $function$;

-- ╔══════════════════════════════════════════════════════════════════════╗
-- ║ BÖLÜM A · SÜPÜRGENİN SAHİBİ                                         ║
-- ╚══════════════════════════════════════════════════════════════════════╝

-- A1 · Damga defteri genişliyor: artık yalnız "ne zaman" değil
--      "kim / ne oldu / hata aldı mı" da yazılıyor.
alter table public.supurge_damgasi add column if not exists kaynak       text;
alter table public.supurge_damgasi add column if not exists son_sonuc    jsonb;
alter table public.supurge_damgasi add column if not exists ardisik_hata int not null default 0;
alter table public.supurge_damgasi add column if not exists son_hata     text;
alter table public.supurge_damgasi add column if not exists son_hata_an  timestamptz;

-- A2 · Süpürge: imzaya `p_kaynak` geliyor.
--
-- ⚠️ ÖNCE DROP: `create or replace` yeni parametreli bir AŞIRI YÜK
-- yaratır, eskisini SİLMEZ. İki tanım yan yana kalırsa hangisinin
-- koştuğu çağrının şekline bağlı olur — bu, sessiz sapmanın tarifidir.
-- Varsayılan değer sayesinde `rpc('expire_stale_sessions')` (argümansız)
-- İSTEMCİDE AYNEN ÇALIŞMAYA DEVAM EDER; App.js'te değişiklik gerekmez.
drop function if exists public.expire_stale_sessions();

-- ----------------------------------------------------------------------
-- bo_supurge_sagligi   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_supurge_sagligi()
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $function$
declare
  v_d       record;
  v_bekleyen_istek int;
  v_bekleyen_otrm  int;
  v_cron_var boolean := false;
  v_cron_is  jsonb   := null;
  v_durum    text;
  v_gecen    interval;
begin
  select * into v_d from public.supurge_damgasi where ad = 'expire_stale_sessions';

  -- ŞU AN süpürülmeyi bekleyen satırlar (gövdenin iki dalıyla birebir
  -- aynı koşullar — biri değişirse buranın da değişmesi gerekir).
  select count(*) into v_bekleyen_istek
    from requests r
    join availabilities a on a.id = r.avail_id
    left join sessions s on s.request_id = r.id
   where r.status = 'accepted' and s.id is null
     and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours';

  select count(*) into v_bekleyen_otrm
    from sessions s
    join requests r on r.id = s.request_id
    join availabilities a on a.id = r.avail_id
   where s.status = 'pending'
     and (s.host_started_at is null) <> (s.guest_started_at is null)
     and public.yerel_an(a.avail_date, a.time_to, a.airport_code) < now() - interval '2 hours';

  -- pg_cron canlı ölçülüyor — saklanan bir bayrağa güvenmiyoruz.
  -- ⚠️ `to_regclass('cron.job')` DEĞİL `pg_extension`: yerel replikada
  -- `cron.job` tablosu duruyor ama uzantı kurulu değil. Tabloya bakan
  -- bir gösterge yeşil yanar ve yalan söyler.
  select exists (select 1 from pg_extension where extname = 'pg_cron') into v_cron_var;
  if v_cron_var and to_regclass('cron.job') is not null then
    begin
      execute $q$ select jsonb_agg(jsonb_build_object('ad', jobname, 'plan', schedule, 'aktif', active))
                    from cron.job where jobname = 'll-supurge' $q$ into v_cron_is;
    exception when others then v_cron_is := null;
    end;
  end if;

  v_gecen := case when v_d.son_kosum is null then null else now() - v_d.son_kosum end;

  v_durum := case
    when v_d.son_kosum is null                       then 'hic_kosmadi'
    when coalesce(v_d.ardisik_hata,0) > 0            then 'hata_aliyor'
    when v_gecen > interval '30 minutes'
         and (v_bekleyen_istek + v_bekleyen_otrm) > 0 then 'gecikmis_ve_birikmis'
    when v_gecen > interval '30 minutes'             then 'gecikmis'
    else 'saglikli'
  end;

  return jsonb_build_object(
    'durum',            v_durum,
    'son_kosum',        v_d.son_kosum,
    'gecen_saniye',     case when v_gecen is null then null else extract(epoch from v_gecen)::int end,
    'kaynak',           v_d.kaynak,
    'son_sonuc',        v_d.son_sonuc,
    'ardisik_hata',     coalesce(v_d.ardisik_hata, 0),
    'son_hata',         v_d.son_hata,
    'son_hata_an',      v_d.son_hata_an,
    'bekleyen_istek',   v_bekleyen_istek,
    'bekleyen_oturum',  v_bekleyen_otrm,
    'pg_cron_var',      v_cron_var,
    'pg_cron_isi',      v_cron_is,
    -- Süpürgeyi ŞU AN kim koşturuyor? Yanıt "hiç kimse" olamaz: pg_cron
    -- yoksa uygulama tetiği yedektedir ve panelde öyle yazar.
    'zamanlayici',      case when v_cron_is is not null then 'pg_cron'
                             else 'uygulama_tetigi' end
  );
end $function$;

revoke all    on function public.bo_supurge_sagligi() from public;
revoke execute on function public.bo_supurge_sagligi() from anon, authenticated;
grant  execute on function public.bo_supurge_sagligi() to service_role;


-- ╔══════════════════════════════════════════════════════════════════════╗
-- ║ BÖLÜM B · KREDİ YARIŞI — İKİ KATMAN                                 ║
-- ╚══════════════════════════════════════════════════════════════════════╝

-- B1 · KATMAN 2 ÖNCE KURULUYOR (defter tetikleyicisi).
--
-- Neden önce? Çünkü katman 1 (kilit) yalnız BİLDİĞİM yolları korur.
-- Tetikleyici HER yolu korur — bugün yazılmamış olanı da. Bir değişmezi
-- yalnız onu ihlal edebilecek koda emanet etmek, değişmez yazmamaktır.
--
-- ⚠️ MUAFİYETLER — ölçerek belirlendi, keyfi değil:
--   · `paid_guest_thanks_reversal:%` → K3 geri alması. Misafir teşekkür
--     kredisini ALDI ve HARCADI; oturum sonradan iptal olunca geri
--     alınır. Bu, bakiyeyi eksiye düşürebilir ve DÜŞÜRMELİDİR — aksi
--     halde harcanmış bir krediyi geri alamayız ve kayıp hosta kalır.
--   · `admin%` → yönetici düzeltmesi. Yanlışlıkla verilmiş krediyi geri
--     almak, harcanmış olsa bile mümkün olmalı.
-- Bunların dışındaki her negatif satır HARCAMADIR ve bakiyeyi
-- eksiye düşüremez.

-- ----------------------------------------------------------------------
-- trg_bakiye_negatife_dusemez   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.trg_bakiye_negatife_dusemez()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_bal int;
begin
  if new.delta >= 0 then return new; end if;
  if new.reason like 'paid_guest_thanks_reversal:%' or new.reason like 'admin%' then
    return new;
  end if;

  -- 🔴 300/B6: KİLİT TETİKLEYİCİNİN İÇİNDE. 299/B2 kilidi dört yola
  -- koymuştu; `misafir_hakki_hediye_et` beşinciydi ve kilitsizdi. İki
  -- eşzamanlı hediye aynı 3 krediyi iki kez harcayabiliyordu (ölçüldü:
  -- ikinci oturum birincinin commit'ini beklemeden geçti).
  -- Kilit burada olunca YOL SAYISI önemsizleşiyor: bakiyeyi eksilten her
  -- satır, aynı kullanıcının diğer eksiltmesini commit'e kadar bekler ve
  -- sonra GÜNCEL toplamı okur.
  perform pg_advisory_xact_lock(hashtextextended('kredi:' || new.user_id::text, 0));
  select coalesce(sum(delta), 0) into v_bal
    from credit_ledger where user_id = new.user_id;

  if v_bal + new.delta < 0 then
    raise exception 'insufficient_credits'
      using detail = format('kullanıcı %s: bakiye %s, denenen %s (%s)',
                            new.user_id, v_bal, new.delta, new.reason),
            hint   = 'Bu satır bakiyeyi negatife düşürürdü; 299/B1 reddetti.';
  end if;
  return new;
end $function$;

-- ════════════════════════════════════════════════════════════════════════
-- §Z — KENDİNİ ÖLÇ. Açık kalan kapı varsa DUR.
-- ════════════════════════════════════════════════════════════════════════
do $z300$
declare v_n int; v_liste text;
begin
  -- A1: kilitli olanlar authenticated/anon tarafından çağrılamaz
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('change_plan','kredi_akis_raporu','anonymized_users',
                       'host_kota_durumu','doluluk_reddi_sayisi','oturum_kural_hedefi',
                       'kural_guncelligi','access_options_for_user','bo_slot_asimlari')
     and (has_function_privilege('authenticated', p.oid, 'execute')
          or has_function_privilege('anon', p.oid, 'execute'));
  if v_n > 0 then raise exception '300 §Z/A1: hâlâ açık: %', v_liste; end if;

  -- A2: PUBLIC'e açık SECURITY DEFINER fonksiyon kalmadı
  select count(distinct p.oid), string_agg(distinct p.proname, ', ') into v_n, v_liste
    from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
   where p.pronamespace = 'public'::regnamespace and p.prosecdef
     and a.grantee = 0 and a.privilege_type = 'EXECUTE';
  if v_n > 0 then raise exception '300 §Z/A2: PUBLIC''e açık % fonksiyon: %', v_n, v_liste; end if;

  -- A2: küresel varsayılan gerçekten yazıldı mı?
  if not exists (select 1 from pg_default_acl d
                  where d.defaclnamespace = 0 and d.defaclobjtype = 'f'
                    and d.defaclrole = 'postgres'::regrole) then
    raise exception '300 §Z/A2: küresel varsayılan yetki kaydı yok';
  end if;

  -- Uygulamanın çağırdığı beş fonksiyon authenticated'da KALDI mı?
  select count(*), string_agg(p.proname, ', ') into v_n, v_liste
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('cancel_availability','binis_karti_kaydet','ilani_yeniden_yayinla',
                       'hikaye_davetini_ertele','kesifte_gorun','profil_karti',
                       'create_request','respond_request','confirm_session')
     and not has_function_privilege('authenticated', p.oid, 'execute');
  if v_n > 0 then raise exception '300 §Z: uygulama fonksiyonu KAPANDI: %', v_liste; end if;

  -- A3 / B6 tetikleyicileri yerinde mi?
  if not exists (select 1 from pg_trigger where tgname = 'trg_visit_0_beyan_temizle') then
    raise exception '300 §Z/A3: tetikleyici yok';
  end if;
  if position('pg_advisory_xact_lock' in
       (select prosrc from pg_proc where proname = 'trg_bakiye_negatife_dusemez')) = 0 then
    raise exception '300 §Z/B6: kredi kilidi tetikleyicide yok';
  end if;
  if position('availability_expired' in
       (select prosrc from pg_proc where proname = 'respond_request')) = 0 then
    raise exception '300 §Z/B1: kabul kapısı yok';
  end if;
  if position('already_requested' in
       (select prosrc from pg_proc where proname = 'create_request_impl')) = 0 then
    raise exception '300 §Z/B5: mükerrer başvuru kapısı yok';
  end if;

  raise notice '300 §Z: bütün kapılar ölçüldü — kapalı';
end $z300$;

select '300 OK — uçtan uca denetim bulguları kapatıldı' as sonuc;

-- ----------------------------------------------------------------------
-- trg_puan_negatife_dusemez   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_puan_negatife_dusemez()
returns trigger
language plpgsql
as $function$
declare v_pts int;
begin
  if new.delta >= 0 then return new; end if;
  if new.reason like 'admin%' then return new; end if;

  select coalesce(sum(delta), 0) into v_pts
    from points_ledger where user_id = new.user_id;

  if v_pts + new.delta < 0 then
    raise exception 'insufficient_points'
      using detail = format('kullanici %s: puan %s, denenen %s (%s)',
                            new.user_id, v_pts, new.delta, new.reason);
  end if;
  return new;
end $function$;

drop trigger if exists trg_puan_negatife_dusemez on public.points_ledger;
create trigger trg_puan_negatife_dusemez
  before insert on public.points_ledger
  for each row execute function public.trg_puan_negatife_dusemez();

-- B2 · KATMAN 1 — kullanıcı başına danışma kilidi, DÖRT YOLA.
--
-- Tablo satırı kilitlemiyoruz çünkü kilitlenecek bir "bakiye satırı"
-- yok: bakiye bir TOPLAM. `pg_advisory_xact_lock` işlem bitince kendi
-- kendine bırakılır — `unlock` unutma riski yoktur.
--
-- ⚠️ KİLİT ANAHTARLARI AYRI: kredi için 'kredi:<uid>', puan için
-- 'puan:<uid>'. Aynı anahtarı paylaşsalardı puan harcayan bir işlem
-- kredi harcayan bir işlemi gereksiz yere bekletirdi.
--
-- Tanımı ELDEN yazmıyoruz: `pg_get_functiondef` ile MEVCUT gövdeyi alıp
-- tek bir çapa metnini değiştiriyoruz. Çapa bulunamazsa migration
-- PATLAR — sessizce "hiçbir şey yapmadım" demez.
do $$
declare
  v_def text; v_yeni text; v_capa text; v_ek text;
begin
  -- ── create_request_impl_preflag ─────────────────────────────────────
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_request_impl_preflag';
  if v_def is null then raise exception '299/B2: create_request_impl_preflag bulunamadi'; end if;

  v_capa := 'select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;';
  v_ek   := '-- 299/B2: bakiye ARTIK KILITLI okunuyor (kullanici basina).' || E'\n  '
         || 'perform pg_advisory_xact_lock(hashtextextended(''kredi:'' || v_uid::text, 0));' || E'\n  '
         || v_capa;

  if position(v_capa in v_def) = 0 then
    raise exception '299/B2: create_request_impl_preflag icinde bakiye okuma capasi bulunamadi';
  end if;
  if position('pg_advisory_xact_lock' in v_def) > 0 then
    raise notice '299/B2: create_request_impl_preflag zaten kilitli — atlandi.';
  else
    v_yeni := replace(v_def, v_capa, v_ek);
    execute v_yeni;
    raise notice '299/B2: create_request_impl_preflag kilitlendi.';
  end if;

  -- ── respond_invite ──────────────────────────────────────────────────
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'respond_invite';
  if v_def is null then raise exception '299/B2: respond_invite bulunamadi'; end if;

  v_capa := 'select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;';
  v_ek   := '-- 299/B2: davet kabulu de bakiye harciyor — ayni kilit.' || E'\n        '
         || 'perform pg_advisory_xact_lock(hashtextextended(''kredi:'' || v_uid::text, 0));' || E'\n        '
         || v_capa;

  if position(v_capa in v_def) = 0 then
    raise exception '299/B2: respond_invite icinde bakiye okuma capasi bulunamadi';
  end if;
  if position('pg_advisory_xact_lock' in v_def) > 0 then
    raise notice '299/B2: respond_invite zaten kilitli — atlandi.';
  else
    execute replace(v_def, v_capa, v_ek);
    raise notice '299/B2: respond_invite kilitlendi.';
  end if;

  -- ── redeem_reward (puan) ────────────────────────────────────────────
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'redeem_reward';
  if v_def is not null and position('pg_advisory_xact_lock' in v_def) = 0 then
    v_capa := 'from points_ledger where user_id = v_uid;';
    if position(v_capa in v_def) = 0 then
      raise exception '299/B2: redeem_reward icinde puan okuma capasi bulunamadi';
    end if;
    v_ek := v_capa || E'\n  '
         || '-- 299/B2: puan da kilitli okunuyor.' || E'\n  '
         || 'perform pg_advisory_xact_lock(hashtextextended(''puan:'' || v_uid::text, 0));';
    execute replace(v_def, v_capa, v_ek);
    raise notice '299/B2: redeem_reward kilitlendi.';
  end if;

  -- ── set_featured (puan) ─────────────────────────────────────────────
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'set_featured';
  if v_def is not null and position('pg_advisory_xact_lock' in v_def) = 0 then
    v_capa := 'from points_ledger where user_id = v_uid;';
    if position(v_capa in v_def) = 0 then
      raise exception '299/B2: set_featured icinde puan okuma capasi bulunamadi';
    end if;
    v_ek := v_capa || E'\n    '
         || '-- 299/B2: puan da kilitli okunuyor.' || E'\n    '
         || 'perform pg_advisory_xact_lock(hashtextextended(''puan:'' || v_uid::text, 0));';
    execute replace(v_def, v_capa, v_ek);
    raise notice '299/B2: set_featured kilitlendi.';
  end if;
end $$;

-- ----------------------------------------------------------------------
-- bo_defter_yetimleri   [etkin kaynak: 299_kredi_kilidi_supurge_sahibi_ve_iade_tutari.sql]
-- ----------------------------------------------------------------------
create or replace function public.bo_defter_yetimleri()
returns table (
  defter     text,
  satir_id   uuid,
  user_id    uuid,
  delta      int,
  reason     text,
  ref_id     uuid,
  created_at timestamptz
)
language sql
stable
security definer
set search_path to 'public'
as $function$
  select 'credit'::text, c.id, c.user_id, c.delta, c.reason, c.ref_id, c.created_at
    from credit_ledger c
   where c.ref_id is not null
     and not exists (select 1 from requests      r where r.id = c.ref_id)
     and not exists (select 1 from sessions      s where s.id = c.ref_id)
     and not exists (select 1 from availabilities a where a.id = c.ref_id)
     and not exists (select 1 from users         u where u.id = c.ref_id)
  union all
  select 'points'::text, p.id, p.user_id, p.delta, p.reason, p.ref_id, p.created_at
    from points_ledger p
   where p.ref_id is not null
     and not exists (select 1 from requests      r where r.id = p.ref_id)
     and not exists (select 1 from sessions      s where s.id = p.ref_id)
     and not exists (select 1 from availabilities a where a.id = p.ref_id)
     and not exists (select 1 from rewards       w where w.id = p.ref_id)
  order by 7 desc
$function$;

revoke all    on function public.bo_defter_yetimleri() from public;
revoke execute on function public.bo_defter_yetimleri() from anon, authenticated;
grant  execute on function public.bo_defter_yetimleri() to service_role;


-- ╔══════════════════════════════════════════════════════════════════════╗
-- ║ SINAMA                                                              ║
-- ╚══════════════════════════════════════════════════════════════════════╝
do $$
declare
  v_uid   uuid;
  v_sag   jsonb;
  v_r     jsonb;
  v_yetim int;
  v_bal   int;
  v_hata  text;
  v_req   uuid;
  v_av    uuid;
  v_host  uuid;
  v_iade  int;
  v_satir uuid;
begin
  -- ── T1 · Süpürge hâlâ frenli ve artık kaynağını yazıyor ────────────
  delete from public.supurge_damgasi where ad = 'expire_stale_sessions';
  v_r := public.expire_stale_sessions('sinama');
  if (v_r ->> 'durum') <> 'kosuldu' then
    raise exception '299/T1: ilk cagri kosmadi (%)', v_r;
  end if;
  if (v_r ->> 'kaynak') <> 'sinama' then
    raise exception '299/T1: kaynak yazilmadi (%)', v_r;
  end if;
  v_r := public.expire_stale_sessions('sinama');
  if (v_r ->> 'durum') <> 'atlandi' then
    raise exception '299/T1: fren calismadi (%)', v_r;
  end if;
  -- Argümansız çağrı (istemcinin yaptığı) hâlâ çalışmalı:
  v_r := public.expire_stale_sessions();
  if (v_r ->> 'ok')::boolean is not true then
    raise exception '299/T1: argumansiz cagri bozuldu (%)', v_r;
  end if;

  -- ── T2 · Sağlık göstergesi konuşuyor ───────────────────────────────
  v_sag := public.bo_supurge_sagligi();
  if v_sag ->> 'durum' is null then raise exception '299/T2: saglik durumu bos'; end if;
  if (v_sag ->> 'bekleyen_istek') is null or (v_sag ->> 'bekleyen_oturum') is null then
    raise exception '299/T2: birikim sayaclari bos (%)', v_sag;
  end if;
  if (v_sag ->> 'son_sonuc') is null then
    raise exception '299/T2: son kosum sonucu damgaya yazilmamis (%)', v_sag;
  end if;
  -- Damgayı 40 dakika geriye al: durum 'gecikmis' olmalı.
  update public.supurge_damgasi set son_kosum = now() - interval '40 minutes'
   where ad = 'expire_stale_sessions';
  v_sag := public.bo_supurge_sagligi();
  if (v_sag ->> 'durum') not in ('gecikmis','gecikmis_ve_birikmis') then
    raise exception '299/T2: 40 dk once kosmus supurge SAGLIKLI gorunuyor (%) — gosterge isirmiyor', v_sag;
  end if;

  -- ── T3 · Bakiye negatife düşemiyor ─────────────────────────────────
  select id into v_uid from users limit 1;
  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  begin
    insert into credit_ledger (user_id, delta, reason, balance_after)
    values (v_uid, -(v_bal + 1), 'request_hold', -1);
    raise exception '299/T3: bakiyeyi negatife dusuren satir KABUL EDILDI — tetikleyici isirmiyor';
  exception when others then
    if SQLERRM not like '%insufficient_credits%' then raise; end if;
  end;
  -- Muafiyet çalışıyor mu: yönetici düzeltmesi eksiye düşebilmeli.
  insert into credit_ledger (user_id, delta, reason, balance_after)
  values (v_uid, -(v_bal + 5), 'admin_adjust', -5)
  returning id into v_satir;
  -- Sonraki sınamalar bu kullanıcının bakiyesini okuyabilir; izi hemen
  -- siliyoruz ki T5'in tutma satırı yanlışlıkla reddedilmesin.
  delete from credit_ledger where id = v_satir;

  -- ── T4 · Tutma adları tek kaynaktan ve invite_hold içeride ─────────
  if not ('invite_hold' = any (public.tutma_sebepleri())) then
    raise exception '299/T4: invite_hold tutma listesinde yok';
  end if;

  -- ── T5 · Davetle açılan istekte iade GERÇEKTEN yazılıyor ───────────
  -- Sahte bir davet isteği kur: tutma adı `invite_hold`, bedel 2.
  select a.id, a.host_id into v_av, v_host from availabilities a limit 1;
  select id into v_uid from users where id <> v_host limit 1;
  insert into requests (guest_id, host_id, avail_id, status, type, purpose, match_score, created_at)
  values (v_uid, v_host, v_av, 'accepted', 'direct_invite', 'lounge', 60, now())
  returning id into v_req;

  -- Bakiyeyi garantiye al: sınama, kullanıcının seed bakiyesine bağlı
  -- olmamalı (bağlı olsaydı sınamanın yeşil yanması veriye bağlı olurdu).
  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  insert into credit_ledger (user_id, delta, reason, balance_after)
  values (v_uid, 5, 'admin_adjust', v_bal + 5);

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  values (v_uid, -2, 'invite_hold', v_req, v_bal - 2);

  v_iade := public.istek_kredisi_iade(v_req, 'no_show_refund');
  if v_iade <> 2 then
    raise exception '299/T5: invite_hold ile tutulan 2 kredi icin iade % yazildi (2 olmaliydi)', v_iade;
  end if;
  -- `idx_requests_unique_active` (guest_id, avail_id) yalnız pending/accepted
  -- için geçerli — sıradaki sınama aynı ilana yazabilsin diye kapatıyoruz.
  update requests set status = 'cancelled' where id = v_req;

  -- ── T6 · Eşikten SONRA tutma kaydı yoksa 1 UYDURULMUYOR ────────────
  insert into requests (guest_id, host_id, avail_id, status, type, purpose, match_score, created_at)
  values (v_uid, v_host, v_av, 'accepted', 'standard', 'lounge', 40, now())
  returning id into v_req;
  v_iade := public.istek_kredisi_iade(v_req, 'no_show_refund');
  if v_iade <> 0 then
    raise exception '299/T6: tutma kaydi OLMAYAN yeni istege % kredi UYDURULDU (0 olmaliydi)', v_iade;
  end if;
  update requests set status = 'cancelled' where id = v_req;

  -- ── T7 · Eşikten ÖNCEKİ istekte eski davranış KORUNUYOR ────────────
  insert into requests (guest_id, host_id, avail_id, status, type, purpose, match_score, created_at)
  values (v_uid, v_host, v_av, 'accepted', 'standard', 'lounge', 40,
          public.tutma_varsayim_esigi() - interval '10 days')
  returning id into v_req;
  v_iade := public.istek_kredisi_iade(v_req, 'no_show_refund');
  if v_iade <> 1 then
    raise exception '299/T7: eski istekte varsayim BOZULDU — iade % (1 olmaliydi)', v_iade;
  end if;
  update requests set status = 'cancelled' where id = v_req;

  -- ── T8 · 298'de DÜŞEN (c) BLOĞU GERÇEKTEN GERİ GELDİ Mİ ───────────
  -- Kurulum: kabul edilmiş bir istek + no_show ile 'expired' kapanmış
  -- oturum. 298'in gövdesinde bu istek SONSUZA 'accepted' kalıyordu:
  -- misafirin kredisi kilitli, host'un slotu dolu.
  insert into requests (guest_id, host_id, avail_id, status, type, purpose, match_score, created_at)
  values (v_uid, v_host, v_av, 'accepted', 'standard', 'lounge', 40, now())
  returning id into v_req;

  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  values (v_uid, 5, 'admin_adjust', v_req, v_bal + 5);
  select coalesce(sum(delta),0) into v_bal from credit_ledger where user_id = v_uid;
  insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
  values (v_uid, -2, 'request_hold', v_req, v_bal - 2);

  insert into sessions (request_id, status, cancel_reason, completed_at, no_show_user_id)
  values (v_req, 'expired', 'no_show', now(), v_host);

  -- Freni aç ve koştur.
  update public.supurge_damgasi set son_kosum = now() - interval '1 hour'
   where ad = 'expire_stale_sessions';
  v_r := public.expire_stale_sessions('sinama');
  if (v_r ->> 'ok')::boolean is not true then
    raise exception '299/T8: supurge hata dondu (%)', v_r;
  end if;

  if (select status from requests where id = v_req) <> 'cancelled' then
    raise exception '299/T8: no_show oturumun arkasindaki istek ACCEPTED kaldi — 187-noshow hatasi geri gelmis';
  end if;
  select coalesce(sum(delta),0) into v_iade
    from credit_ledger where ref_id = v_req and reason = 'no_show_refund';
  if v_iade <> 2 then
    raise exception '299/T8: no_show iadesi % yazildi (tutulan 2 idi)', v_iade;
  end if;

  -- ── T9 · Yetim tarayıcı çalışıyor ──────────────────────────────────
  select count(*) into v_yetim from public.bo_defter_yetimleri();
  raise notice '299 sinama OK · defter yetimi: % satir', v_yetim;

  raise exception 'GERI_AL_SINAMA';
exception
  when others then
    if SQLERRM <> 'GERI_AL_SINAMA' then raise; end if;
end $$;

-- ----------------------------------------------------------------------
-- trg_visit_0_beyan_temizle   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_visit_0_beyan_temizle()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- Sunucu yolları (tohum, cron, motor) auth.uid() olmadan yazar → dokunma.
  if auth.uid() is null or coalesce(current_setting('loungelink.motor', true), '') = 'evet' then
    return new;
  end if;
  new.flight_verified     := false;
  new.flight_source       := null;
  new.flight_checked_at   := null;
  new.scheduled_departure := null;
  new.scheduled_arrival   := null;
  new.terminal            := null;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- kesifte_gorun   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ----------------------------------------------------------------------
create or replace function public.kesifte_gorun(p_acik boolean)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);
  update profiles set show_on_discovery = coalesce(p_acik, true), updated_at = now()
   where user_id = v_uid;
  return jsonb_build_object('ok', true, 'show_on_discovery', coalesce(p_acik, true));
end $$;

-- ----------------------------------------------------------------------
-- profil_karti   [etkin kaynak: 300_uctan_uca_denetim.sql]
-- ----------------------------------------------------------------------
create or replace function public.profil_karti(p_user uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_user is null then return null; end if;
  if p_user <> v_uid then
    if public.is_blocked_pair(v_uid, p_user) then return null; end if;
    if exists (select 1 from users u where u.id = p_user
                and (u.deleted_at is not null or u.banned_at is not null)) then
      return null;
    end if;
  end if;
  select jsonb_build_object(
           'role', u.role,
           'kadin', (u.gender = 'female'),
           'phone_verified', coalesce(vf.phone_verified, false),
           'email_verified', coalesce(vf.email_verified, false),
           'id_verified',    coalesce(vf.id_verified, false),
           'linkedin_verified', coalesce(vf.linkedin_verified, false),
           'oturum', (select count(*) from sessions s join requests r on r.id = s.request_id
                       where s.status = 'completed' and (r.guest_id = p_user or r.host_id = p_user)))
    into v
    from users u left join verifications vf on vf.user_id = u.id
   where u.id = p_user;
  return v;
end $$;

-- ----------------------------------------------------------------------
-- seed_test_hesabi   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ----------------------------------------------------------------------
create or replace function public.seed_test_hesabi(p_email text)
returns boolean language sql immutable as $$
  select coalesce(p_email, '') like '%@seed.loungelink.test'
      or coalesce(p_email, '') like '%@sahne.loungelink.test'
      or coalesce(p_email, '') like '%@vitrin.loungelink.test'
      or coalesce(p_email, '') like '%@e2e.test';
$$;

-- ----------------------------------------------------------------------
-- test_hesabi_gizli_mi   [etkin kaynak: 302_test_hesaplarini_gorenler.sql]
-- ⚠ Bu fonksiyon 2 dosyada tanimli. Degistirirken drift_check.py calistir.
-- ----------------------------------------------------------------------
create or replace function public.test_hesabi_gizli_mi(p_hedef uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select f.enabled from feature_flags f where f.key = 'test_hesaplarini_gizle'), true)
     and exists (select 1 from users u where u.id = p_hedef and public.seed_test_hesabi(u.email))
     and not coalesce((select public.seed_test_hesabi(x.email) or coalesce(x.is_staff, false)
                         from users x where x.id = auth.uid()), false)
     and not exists (select 1 from test_gorunurlugu g where g.user_id = auth.uid());
$$;

-- ----------------------------------------------------------------------
-- engelle   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ----------------------------------------------------------------------
create or replace function public.engelle(p_user uuid, p_sebep text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  r record;
  v_istek int := 0; v_davet int := 0; v_bag int := 0;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);
  if p_user is null or p_user = v_uid then raise exception 'cannot_block_self'; end if;
  if not exists (select 1 from users where id = p_user) then raise exception 'target_not_found'; end if;

  insert into blocks (blocker, blocked, created_at, sebep)
  values (v_uid, p_user, now(), left(nullif(btrim(coalesce(p_sebep,'')),''), 200))
  on conflict (blocker, blocked) do update set sebep = coalesce(excluded.sebep, blocks.sebep);

  -- İki kişi arasındaki AÇIK buluşmalar kapanır. Başlamış (aktif) oturuma
  -- dokunulmaz: o an salondalar — orada doğru yol Bildir/SOS.
  for r in
    select q.id, q.status, q.guest_id
      from requests q
     where ((q.guest_id = v_uid and q.host_id = p_user) or (q.guest_id = p_user and q.host_id = v_uid))
       and q.status in ('pending', 'accepted')
       and not exists (select 1 from sessions s where s.request_id = q.id
                         and (s.status = 'active'
                              or (s.status = 'pending' and (s.host_started_at is not null
                                                            or s.guest_started_at is not null))))
     for update of q
  loop
    update requests set status = 'cancelled', responded_at = coalesce(responded_at, now()),
           decision_note = coalesce(decision_note, 'Engelleme nedeniyle kapandı (301).')
     where id = r.id;
    update sessions set status = 'cancelled', completed_at = now(), cancelled_by = v_uid,
           cancel_reason = 'engellendi'
     where request_id = r.id and status = 'pending';
    perform public.istek_kredisi_iade(r.id, 'request_refund');
    v_istek := v_istek + 1;
  end loop;

  update invites set status = 'declined', responded_at = now()
   where status = 'pending'
     and ((host_id = v_uid and guest_id = p_user) or (host_id = p_user and guest_id = v_uid));
  get diagnostics v_davet = row_count;

  update connection_requests set status = 'blocked', responded_at = now()
   where status in ('pending', 'accepted')
     and ((from_id = v_uid and to_id = p_user) or (from_id = p_user and to_id = v_uid));
  get diagnostics v_bag = row_count;
  update chat_channels c set active = false
   where c.connection_id in (select id from connection_requests
                              where (from_id = v_uid and to_id = p_user) or (from_id = p_user and to_id = v_uid));

  -- Engellenen kişiye BİLDİRİM GİTMEZ (bilerek: engel sessizdir).
  return jsonb_build_object('ok', true, 'kapanan_istek', v_istek,
                            'reddedilen_davet', v_davet, 'kapanan_baglanti', v_bag);
end $$;

-- ----------------------------------------------------------------------
-- engeli_kaldir   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ----------------------------------------------------------------------
create or replace function public.engeli_kaldir(p_user uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_n int;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  delete from blocks where blocker = v_uid and blocked = p_user;
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'kaldirildi', v_n > 0);
end $$;

-- ----------------------------------------------------------------------
-- engellediklerim   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ----------------------------------------------------------------------
create or replace function public.engellediklerim()
returns table (user_id uuid, name text, photo_url text, created_at timestamptz, sebep text)
language sql stable security definer set search_path = public as $$
  select b.blocked, coalesce(p.name, '—'), p.photo_url, b.created_at, b.sebep
    from blocks b left join profiles p on p.user_id = b.blocked
   where b.blocker = auth.uid()
   order by b.created_at desc;
$$;

-- ----------------------------------------------------------------------
-- trg_mesaj_engel   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ----------------------------------------------------------------------
create or replace function public.trg_mesaj_engel()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_diger uuid;
begin
  select case when q.guest_id = new.from_id then q.host_id else q.guest_id end into v_diger
    from chat_channels c join requests q on q.id = c.request_id
   where c.id = new.channel_id;
  if v_diger is null then
    select case when k.from_id = new.from_id then k.to_id else k.from_id end into v_diger
      from chat_channels c join connection_requests k on k.id = c.connection_id
     where c.id = new.channel_id;
  end if;
  if v_diger is not null and public.is_blocked_pair(new.from_id, v_diger) then
    raise exception 'blocked_pair';
  end if;
  return new;
end $$;

-- ----------------------------------------------------------------------
-- gelmedi_bildir   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ----------------------------------------------------------------------
create or replace function public.gelmedi_bildir(p_request_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_req requests%rowtype;
  v_s sessions%rowtype;
  v_ben_host boolean; v_bas timestamptz; v_diger uuid;
  v_dk int := coalesce((select (value #>> '{}')::int from beta_settings where key = 'gelmedi_bekleme_dk'), 15);
  v_iade int := 0;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform public.hesap_kapisi(v_uid);
  select * into v_req from requests where id = p_request_id for update;
  if not found then raise exception 'request_not_found'; end if;
  if v_uid not in (v_req.host_id, v_req.guest_id) then raise exception 'not_party'; end if;
  if v_req.status <> 'accepted' then raise exception 'not_open'; end if;

  select * into v_s from sessions where request_id = p_request_id for update;
  if not found or v_s.status <> 'pending' then raise exception 'gelmedi_once_baslat'; end if;
  v_ben_host := (v_uid = v_req.host_id);
  v_bas := case when v_ben_host then v_s.host_started_at else v_s.guest_started_at end;
  if v_bas is null then raise exception 'gelmedi_once_baslat'; end if;
  if (case when v_ben_host then v_s.guest_started_at else v_s.host_started_at end) is not null then
    raise exception 'karsi_taraf_geldi';
  end if;
  if now() < v_bas + make_interval(mins => v_dk) then
    raise exception 'gelmedi_erken'
      using hint = format('%s dakika dolmadı', v_dk);
  end if;
  v_diger := case when v_ben_host then v_req.guest_id else v_req.host_id end;

  -- Süpürgenin (b) adımı — birebir
  update sessions set status = 'expired', completed_at = now(), cancel_reason = 'no_show',
         no_show_user_id = v_diger, cancelled_by = v_uid, cancel_note = 'gelmedi_bildirildi'
   where id = v_s.id;
  -- Süpürgenin (c) adımı — birebir: istek kapanır, misafire tutulan kredi döner
  update requests set status = 'cancelled' where id = v_req.id;
  if not exists (select 1 from credit_ledger c where c.ref_id = v_req.id and c.reason = 'no_show_refund') then
    v_iade := coalesce(public.tutulan_kredi(v_req.id), 0);
    if v_iade > 0 then
      insert into credit_ledger (user_id, delta, reason, ref_id, balance_after)
      select v_req.guest_id, v_iade, 'no_show_refund', v_req.id,
             coalesce((select sum(delta) from credit_ledger where user_id = v_req.guest_id), 0) + v_iade;
    end if;
  end if;
  perform public.recompute_trust(v_diger);

  insert into notifications (user_id, category, title, body, ref_type, ref_id)
  values (v_diger, 'sessions', 'Buluşma kapandı',
          'Seni bekleyen taraf gelmediğini bildirdi. Bir yanlışlık varsa bu buluşmanın sohbetindeki "Bu buluşmayla ilgili sorun bildir" ile itiraz edebilirsin.',
          'request', v_req.id),
         (v_uid, 'sessions', 'Bildirimin alındı',
          case when v_ben_host then 'Buluşma kapandı. Misafirin gelmediği kaydedildi.'
               when v_iade > 0 then 'Buluşma kapandı ve tutulan kredin iade edildi.'
               else 'Buluşma kapandı. Host''un gelmediği kaydedildi.' end,
          'request', v_req.id);

  return jsonb_build_object('ok', true, 'iade', v_iade, 'gelmeyen', v_diger);
end $$;

-- ----------------------------------------------------------------------
-- gelmedi_esigi   [etkin kaynak: 301_guven_ve_akis_tamamlama.sql]
-- ----------------------------------------------------------------------
create or replace function public.gelmedi_esigi()
returns int language sql stable security definer set search_path = public as $$
  select coalesce((select (value #>> '{}')::int from beta_settings where key = 'gelmedi_bekleme_dk'), 15)
$$;
